function mobileCorsOriginAllowed(origin: string) {
  if (!origin) return false;
  const publicOrigin = (() => {
    try {
      return MOBILE_PUBLIC_URL ? new URL(MOBILE_PUBLIC_URL).origin : "";
    } catch {
      return "";
    }
  })();
  return (
    origin === publicOrigin ||
    /^https:\/\/[^/]+\.service\.tcloudbase\.com$/i.test(origin) ||
    /^http:\/\/(?:127\.0\.0\.1|localhost)(?::\d+)?$/i.test(origin) ||
    /^http:\/\/(?:10|172\.(?:1[6-9]|2\d|3[01])|192\.168)\.\d{1,3}\.\d{1,3}(?::\d+)?$/i.test(origin)
  );
}

app.addHook("onRequest", async (req, reply) => {
  if (!req.url.startsWith("/api/mobile/") && !req.url.startsWith("/api/auth/") && req.url !== "/api/health") return;
  const origin = String(req.headers.origin || "");
  if (mobileCorsOriginAllowed(origin)) {
    reply.header("Access-Control-Allow-Origin", origin);
    reply.header("Vary", "Origin");
    reply.header("Access-Control-Allow-Credentials", "true");
    reply.header("Access-Control-Allow-Methods", "GET,POST,PUT,PATCH,DELETE,OPTIONS");
    reply.header("Access-Control-Allow-Headers", "Content-Type,Authorization,Cookie");
  }
  if (req.method === "OPTIONS") {
    return reply.code(204).send();
  }
});

