if (setupRequiredSnapshot && process.env.OPENCLAW_WORKBENCH_PASSWORD) {
  const password = process.env.OPENCLAW_WORKBENCH_PASSWORD;
  if (password.length >= 6) {
    const { hash, salt } = hashPassword(password);
    db.prepare("INSERT INTO users (id, password_hash, salt, created_at) VALUES (1, ?, ?, ?)").run(hash, salt, nowIso());
    audit(db, "auth.bootstrap_env", "user", "1", "high", {});
    setupRequiredSnapshot = false;
  }
}

if (
  !setupRequiredSnapshot
  && process.env.OPENCLAW_WORKBENCH_ENV !== "prod"
  && process.env.OPENCLAW_WORKBENCH_RESET_PASSWORD === "1"
  && process.env.OPENCLAW_WORKBENCH_PASSWORD
) {
  const password = process.env.OPENCLAW_WORKBENCH_PASSWORD;
  if (password.length >= 6) {
    const { hash, salt } = hashPassword(password);
    db.prepare("UPDATE users SET password_hash = ?, salt = ? WHERE id = 1").run(hash, salt);
    audit(db, "auth.reset_env", "user", "1", "high", { env: process.env.OPENCLAW_WORKBENCH_ENV || "dev" });
  }
}

