app.post("/api/auth/setup", async (req, reply) => {
  if (hasUser(db)) return reply.code(409).send({ ok: false, error: "already_setup" });
  const password = String((req.body as { password?: string })?.password || process.env.OPENCLAW_WORKBENCH_PASSWORD || "");
  if (password.length < 6) return reply.code(400).send({ ok: false, error: "password_min_6" });
  const { hash, salt } = hashPassword(password);
  db.prepare("INSERT INTO users (id, password_hash, salt, created_at) VALUES (1, ?, ?, ?)").run(hash, salt, nowIso());
  setupRequiredSnapshot = false;
  createSession(db, reply);
  audit(db, "auth.setup", "user", "1", "high", {});
  return { ok: true };
});

app.post("/api/auth/login", async (req, reply) => {
  const password = String((req.body as { password?: string })?.password || "");
  const row = db.prepare("SELECT password_hash, salt FROM users WHERE id = 1").get() as { password_hash: string; salt: string } | undefined;
  if (!row || !verifyPassword(password, row.salt, row.password_hash)) return reply.code(401).send({ ok: false, error: "invalid_login" });
  createSession(db, reply);
  audit(db, "auth.login", "user", "1", "low", {});
  return { ok: true };
});

