app.post("/api/mobile/pairing/start", async (req) => {
  const body = (req.body || {}) as { deviceHint?: string };
  let code = String(randomInt(100_000, 1_000_000));
  const broker = cloudbaseForwarderSingleton.instance?.getMacId()
    ? await publishPairCodeToBroker({
        macId: cloudbaseForwarderSingleton.instance.getMacId() as string,
        macHint: os.hostname(),
        deviceHint: String(body.deviceHint || "").slice(0, 120),
      })
    : { ok: false as const, error: CLOUDBASE_ENABLED ? "cloudbase_forwarder_not_registered" : "cloudbase_disabled", brokerUrl: CLOUDBASE_BROKER_URL };
  if (broker.ok) code = broker.brokerCode;
  const id = randomUUID();
  const now = nowIso();
  const expiresAt = new Date(Date.now() + MOBILE_PAIRING_TTL_MS).toISOString();
  db.prepare("INSERT INTO mobile_pairing_challenges (id, code_hash, status, device_hint, created_by, created_at, expires_at) VALUES (?, ?, ?, ?, ?, ?, ?)")
    .run(id, tokenHash(code), "created", String(body.deviceHint || "").slice(0, 120), "owner", now, expiresAt);
  audit(db, "mobile.pairing.start", "mobile_pairing", id, "high", { expiresAt, deviceHint: body.deviceHint || "", broker });
  return {
    ok: true,
    pairing: {
      id,
      code,
      expiresAt,
      ttlSeconds: Math.round(MOBILE_PAIRING_TTL_MS / 1000),
      status: "created",
      broker,
      publicUrl: broker.brokerUrl,
    },
  };
});

