app.post("/api/mobile/pairing/claim", async (req, reply) => {
  const body = (req.body || {}) as { code?: string; deviceName?: string; platform?: string; appVersion?: string; buildNumber?: string };
  const code = String(body.code || "").replace(/\D/g, "");
  if (!/^\d{6}$/.test(code)) return reply.code(400).send({ ok: false, error: "invalid_pairing_code" });
  const challenge = db.prepare("SELECT * FROM mobile_pairing_challenges WHERE code_hash = ? LIMIT 1").get(tokenHash(code)) as Record<string, unknown> | undefined;
  if (!challenge || challenge.status !== "created") return reply.code(404).send({ ok: false, error: "pairing_not_found" });
  const challengeId = String(challenge.id || "");
  if (Date.parse(String(challenge.expires_at || "")) < Date.now()) {
    db.prepare("UPDATE mobile_pairing_challenges SET status = 'expired' WHERE id = ?").run(challengeId);
    return reply.code(410).send({ ok: false, error: "pairing_expired" });
  }
  const now = nowIso();
  const deviceId = randomUUID();
  const deviceName = String(body.deviceName || "OpenClaw Mobile").slice(0, 80);
  const platform = normalizeMobilePlatform(body.platform);
  const buildNumber = String(body.buildNumber || "").slice(0, 24);
  const appVersion = `${String(body.appVersion || "").slice(0, 40)}${buildNumber ? ` (${buildNumber})` : ""}`.slice(0, 80);
  db.prepare("INSERT INTO mobile_devices (id, name, platform, app_version, status, pairing_id, user_agent, created_at, last_seen_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)")
    .run(deviceId, deviceName, platform, appVersion, "active", challengeId, String(req.headers["user-agent"] || "").slice(0, 240), now, now);
  db.prepare("UPDATE mobile_pairing_challenges SET status = 'claimed', claimed_at = ? WHERE id = ?").run(now, challengeId);
  const access = createMobileDeviceToken(deviceId, "access", MOBILE_ACCESS_TOKEN_TTL_MS);
  const refresh = createMobileDeviceToken(deviceId, "refresh", MOBILE_REFRESH_TOKEN_TTL_MS);
  audit(db, "mobile.pairing.claim", "mobile_device", deviceId, "high", { platform, appVersion, buildNumber, pairingId: challengeId });
  return {
    ok: true,
    device: sanitizeMobileDevice(db.prepare("SELECT * FROM mobile_devices WHERE id = ?").get(deviceId)),
    accessToken: access.token,
    accessExpiresAt: access.expiresAt,
    refreshToken: refresh.token,
    refreshExpiresAt: refresh.expiresAt,
  };
});

app.post("/api/mobile/auth/refresh", async (req, reply) => {
  const body = (req.body || {}) as { refreshToken?: string };
  const refreshToken = String(body.refreshToken || "");
  const row = db.prepare(`
    SELECT t.id, t.device_id, t.expires_at, d.status AS device_status
    FROM mobile_device_tokens t
    JOIN mobile_devices d ON d.id = t.device_id
    WHERE t.token_hash = ?
      AND t.kind = 'refresh'
      AND t.revoked_at IS NULL
      AND d.status = 'active'
    LIMIT 1
  `).get(tokenHash(refreshToken)) as { id: string; device_id: string; expires_at: string; device_status: string } | undefined;
  if (!row || Date.parse(row.expires_at) < Date.now()) return reply.code(401).send({ ok: false, error: "refresh_required" });
  const access = createMobileDeviceToken(row.device_id, "access", MOBILE_ACCESS_TOKEN_TTL_MS);
  db.prepare("UPDATE mobile_device_tokens SET last_used_at = ? WHERE id = ?").run(nowIso(), row.id);
  db.prepare("UPDATE mobile_devices SET last_seen_at = ? WHERE id = ?").run(nowIso(), row.device_id);
  audit(db, "mobile.auth.refresh", "mobile_device", row.device_id, "normal", {});
  return { ok: true, accessToken: access.token, accessExpiresAt: access.expiresAt };
});

