app.patch("/api/mobile/recorder/sessions/:id", async (req, reply) => {
  const id = String((req.params as { id?: string }).id || "");
  const device = mobileDeviceFromRequest(req);
  const deviceId = device?.id ? String(device.id) : "";
  if (!deviceId) return reply.code(401).send({ ok: false, error: "mobile_auth_required" });
  const session = getMobileRecordingSession(db, id) as { deviceId?: string; status?: string } | null;
  if (!session) return reply.code(404).send({ ok: false, error: "recorder_session_not_found" });
  if (!canAccessMobileRecordingSession(session, deviceId)) return reply.code(403).send({ ok: false, error: "recorder_session_device_mismatch" });
  const body = (req.body || {}) as MobileRecorderSessionBody;
  const status = normalizeMobileRecorderStatus(body.status);
  const stopped = status === "stopped" || status === "failed";
  const now = nowIso();
  const updated = updateMobileRecordingSession(db, {
    id,
    title: typeof body.title === "string" ? mobileText(body.title, 120) : undefined,
    status: status || undefined,
    scene: typeof body.scene === "string" ? mobileText(body.scene, 80) : undefined,
    language: typeof body.language === "string" ? mobileText(body.language, 20) || "zh-CN" : undefined,
    network: typeof body.network === "string" ? mobileText(body.network, 40) : undefined,
    batteryLevel: body.batteryLevel === undefined ? undefined : normalizeNullableInteger(body.batteryLevel),
    retentionHours: body.retentionHours === undefined ? undefined : normalizeMobileRecorderRetentionHours(body.retentionHours),
    sampleRate: body.sampleRate === undefined ? undefined : normalizeNullableInteger(body.sampleRate) || 0,
    channelCount: body.channelCount === undefined ? undefined : normalizeNullableInteger(body.channelCount) || 1,
    durationMs: body.durationMs === undefined ? undefined : normalizeNullableInteger(body.durationMs) || 0,
    endedAt: stopped ? now : undefined,
    completedAt: stopped ? now : undefined,
    metadata: body.metadata,
  });
  audit(db, "mobile.recorder.session.update", "mobile_recording_session", id, status === "failed" ? "warn" : "normal", {
    deviceId,
    status: status || session.status || "",
  });
  return { ok: true, session: updated };
});

app.post("/api/mobile/recorder/sessions/:id/chunks", async (req, reply) => {
  const id = String((req.params as { id?: string }).id || "");
  const body = (req.body || {}) as MobileRecorderChunkBody;
  const device = mobileDeviceFromRequest(req);
  const deviceId = device?.id ? String(device.id) : "";
  if (!deviceId) return reply.code(401).send({ ok: false, error: "mobile_auth_required" });
  const session = getMobileRecordingSession(db, id) as { id?: string; deviceId?: string; totalChunks?: number; totalBytes?: number; language?: string } | null;
  if (!session) return reply.code(404).send({ ok: false, error: "recorder_session_not_found" });
  if (!canAccessMobileRecordingSession(session, deviceId)) return reply.code(403).send({ ok: false, error: "recorder_session_device_mismatch" });

  let chunkIndex = 0;
  let totalChunks = 0;
  let audio: Buffer;
  try {
    chunkIndex = normalizeMobileAudioChunkNumber(body.chunkIndex, "chunk_index", MOBILE_AUDIO_CHUNK_MAX_COUNT - 1);
    totalChunks = normalizeMobileAudioChunkNumber(body.totalChunks, "total_chunks", MOBILE_AUDIO_CHUNK_MAX_COUNT);
    if (totalChunks <= 0 || chunkIndex >= totalChunks) throw new Error("audio_chunk_index_invalid");
    audio = decodeMobileVoiceAudioBase64(body.audioBase64);
  } catch (err) {
    const message = err instanceof Error ? err.message : "invalid_audio_chunk";
    return reply.code(400).send({ ok: false, error: message });
  }
  if (audio.byteLength > MOBILE_AUDIO_CHUNK_BYTES) {
    return reply.code(413).send({ ok: false, error: "audio_chunk_too_large", maxBytes: MOBILE_AUDIO_CHUNK_BYTES, chunkBytes: audio.byteLength });
  }
  const totalBytes = normalizeNullableInteger(body.totalBytes);
  if (totalBytes != null && totalBytes > MOBILE_TRANSCRIPTION_MAX_BYTES) {
    return reply.code(413).send({ ok: false, error: "audio_too_large", maxBytes: MOBILE_TRANSCRIPTION_MAX_BYTES, totalBytes });
  }

  const chunkDir = mobileRecorderChunkDir(id);
  if (chunkIndex === 0 || isTruthyMobileFlag(body.reset)) {
    fs.rmSync(chunkDir, { recursive: true, force: true });
  }
  fs.mkdirSync(chunkDir, { recursive: true });
  const chunkPath = mobileRecorderChunkPath(id, chunkIndex);
  fs.writeFileSync(chunkPath, audio);
  const chunkHash = createHash("sha256").update(audio).digest("hex");
  const audioMime = normalizeMobileAudioMime(body.audioMime);
  const uploaded = mobileRecorderChunkStats(id);
  const now = nowIso();
  const segment = insertMobileTranscriptSegment(db, {
    sessionId: id,
    deviceId,
    segmentIndex: normalizeNullableInteger(body.chunkIndex) || 0,
    chunkIndex,
    chunkHash,
    text: normalizeMobileTranscript(body.transcriptText || body.text || ""),
    status: mobileText(body.status || "partial", 32) || "partial",
    startMs: normalizeNullableInteger(body.startMs) || 0,
    endMs: normalizeNullableInteger(body.endMs) || 0,
    language: mobileText(body.language || session.language || "zh-CN", 20) || "zh-CN",
    provider: mobileText(body.provider || "", 80),
    audioPath: chunkPath,
    audioMime,
    audioBytes: audio.byteLength,
    metadata: { uploadedAt: now },
  });
  const updated = updateMobileRecordingSession(db, {
    id,
    status: uploaded.uploadedChunks >= totalChunks ? "uploading" : "recording",
    totalChunks: Math.max(Number(session.totalChunks || 0), totalChunks, uploaded.uploadedChunks),
    totalBytes: uploaded.receivedBytes,
    durationMs: normalizeNullableInteger(body.durationMs) || undefined,
    lastSegmentAt: now,
  });
  audit(db, "mobile.recorder.chunk", "mobile_recording_session", id, "normal", {
    deviceId,
    chunkIndex,
    totalChunks,
    uploadedChunks: uploaded.uploadedChunks,
    receivedBytes: uploaded.receivedBytes,
  });
  // 2026-07-04 — R10: the stop-time flush of the final partial segment lands
  // here (uploadRecorderAudio → /chunks). When the upload completes and the
  // client did NOT provide its own transcript, transcribe the assembled audio
  // with the configured provider so the final segment is filled in too — the
  // same transcribeMobileVoiceAudio() path the rolling live-segments endpoint
  // uses. Background so the chunk response stays fast; the mobile segment-poll
  // picks up the text.
  const providedFinalText = normalizeMobileTranscript(body.transcriptText || body.text || "");
  if (uploaded.uploadedChunks >= totalChunks && !providedFinalText && mobileTranscriptionConfigured()) {
    const finalSegmentRowId = String((segment as { id?: string })?.id || "");
    const finalLanguage = mobileText(body.language || session.language || "zh-CN", 20) || "zh-CN";
    db.prepare("UPDATE mobile_transcript_segments SET status = 'transcribing', updated_at = ? WHERE id = ?")
      .run(nowIso(), finalSegmentRowId);
    void (async () => {
      try {
        const assembled = assembleMobileRecorderChunks(id, totalChunks);
        const result = await transcribeMobileVoiceAudio({
          audioBuffer: assembled,
          audioMime,
          filename: `recorder-final${mobileAudioExtension(audioMime)}`,
          language: finalLanguage,
          audioPath: chunkPath,
        });
        const transcriptText = normalizeMobileTranscript(result.text);
        db.prepare(`
          UPDATE mobile_transcript_segments
          SET text = ?, status = ?, provider = ?, updated_at = ?, error = ''
          WHERE id = ?
        `).run(
          transcriptText,
          transcriptText ? "transcript_ready" : "empty",
          `${result.provider}:${result.model}`,
          nowIso(),
          finalSegmentRowId,
        );
        audit(db, "mobile.recorder.chunk.transcribed", "mobile_recording_session", id, "normal", {
          deviceId,
          provider: result.provider,
          model: result.model,
          transcriptChars: transcriptText.length,
        });
      } catch (err) {
        const message = err instanceof Error ? err.message : "transcription_failed";
        db.prepare("UPDATE mobile_transcript_segments SET status = 'transcription_failed', error = ?, updated_at = ? WHERE id = ?")
          .run(message.slice(0, 500), nowIso(), finalSegmentRowId);
        audit(db, "mobile.recorder.chunk.transcribe_failed", "mobile_recording_session", id, "warn", { deviceId, error: message });
      }
    })();
  }
  return {
    ok: true,
    status: uploaded.uploadedChunks >= totalChunks ? "audio_uploaded" : "audio_uploading",
    chunkIndex,
    totalChunks,
    uploadedChunks: uploaded.uploadedChunks,
    receivedBytes: uploaded.receivedBytes,
    maxChunkBytes: MOBILE_AUDIO_CHUNK_BYTES,
    chunkHash,
    segment,
    session: updated,
  };
});

// 2026-07-04 — R10: live transcription segments.
//
// While the user is still recording, the mobile app finalizes a rolling audio
// segment every ~12s (LIVE_SEGMENT_MS) and uploads it here in small chunks.
// Unlike /chunks (a single stop-time upload that resets its shared dir), this
// endpoint keeps each segment's audio in its OWN directory so prior segments
// are never clobbered. When a segment's chunks are all in, the server
// assembles the segment audio and calls transcribeMobileVoiceAudio() on it —
// the SAME transcription provider the /voice-notes path uses. The resulting
// text is written into mobile_transcript_segments so the mobile segment-poll
// fills the transcript textarea incrementally, before the user stops.
//
// This is the real live voice-to-text data path R10 requires. If no provider
// is configured, the segment row is stored with status "provider_unavailable"
// and the response reports transcriptionConfigured:false so the UI can tell
// the truth instead of pretending realtime is running.
app.post("/api/mobile/recorder/sessions/:id/live-segments", async (req, reply) => {
  const id = String((req.params as { id?: string }).id || "");
  const body = (req.body || {}) as MobileRecorderLiveSegmentBody;
  const device = mobileDeviceFromRequest(req);
  const deviceId = device?.id ? String(device.id) : "";
  if (!deviceId) return reply.code(401).send({ ok: false, error: "mobile_auth_required" });
  const session = getMobileRecordingSession(db, id) as { id?: string; deviceId?: string; language?: string } | null;
  if (!session) return reply.code(404).send({ ok: false, error: "recorder_session_not_found" });
  if (!canAccessMobileRecordingSession(session, deviceId)) return reply.code(403).send({ ok: false, error: "recorder_session_device_mismatch" });

  let segmentIndex = 0;
  let chunkIndex = 0;
  let totalChunks = 0;
  let audio: Buffer;
  try {
    segmentIndex = normalizeMobileAudioChunkNumber(body.segmentIndex, "segment_index", MOBILE_AUDIO_CHUNK_MAX_COUNT * 64);
    chunkIndex = normalizeMobileAudioChunkNumber(body.chunkIndex, "chunk_index", MOBILE_AUDIO_CHUNK_MAX_COUNT - 1);
    totalChunks = normalizeMobileAudioChunkNumber(body.totalChunks, "total_chunks", MOBILE_AUDIO_CHUNK_MAX_COUNT);
    if (totalChunks <= 0 || chunkIndex >= totalChunks) throw new Error("audio_chunk_index_invalid");
    audio = decodeMobileVoiceAudioBase64(body.audioBase64);
  } catch (err) {
    const message = err instanceof Error ? err.message : "invalid_audio_chunk";
    return reply.code(400).send({ ok: false, error: message });
  }
  if (audio.byteLength > MOBILE_AUDIO_CHUNK_BYTES) {
    return reply.code(413).send({ ok: false, error: "audio_chunk_too_large", maxBytes: MOBILE_AUDIO_CHUNK_BYTES, chunkBytes: audio.byteLength });
  }

  // Per-segment chunk dir — reset only THIS segment's dir on chunkIndex 0, so
  // prior segments' audio survives (contract: "without clearing prior segment
  // audio").
  const segmentDir = mobileRecorderLiveSegmentDir(id, segmentIndex);
  if (chunkIndex === 0 || isTruthyMobileFlag(body.reset)) {
    fs.rmSync(segmentDir, { recursive: true, force: true });
  }
  fs.mkdirSync(segmentDir, { recursive: true });
  fs.writeFileSync(path.join(segmentDir, `${String(chunkIndex).padStart(5, "0")}.part`), audio);

  let uploadedChunks = 0;
  for (const name of fs.readdirSync(segmentDir)) {
    if (/^\d{5}\.part$/.test(name)) uploadedChunks += 1;
  }
  const now = nowIso();
  updateMobileRecordingSession(db, { id, status: "recording", lastSegmentAt: now });

  if (uploadedChunks < totalChunks) {
    return {
      ok: true,
      status: "segment_uploading",
      segmentIndex,
      chunkIndex,
      totalChunks,
      uploadedChunks,
    };
  }

  let segmentAudio: Buffer;
  try {
    const parts: Buffer[] = [];
    for (let i = 0; i < totalChunks; i += 1) {
      const partPath = path.join(segmentDir, `${String(i).padStart(5, "0")}.part`);
      if (!fs.existsSync(partPath)) throw new Error("segment_incomplete");
      parts.push(fs.readFileSync(partPath));
    }
    segmentAudio = Buffer.concat(parts);
  } catch {
    return reply.code(409).send({ ok: false, error: "segment_incomplete", segmentIndex, uploadedChunks, totalChunks });
  }

  const audioMime = normalizeMobileAudioMime(body.audioMime);
  const language = mobileText(body.language || session.language || "zh-CN", 20) || "zh-CN";
  const filename = `recorder-live-${segmentIndex}${mobileAudioExtension(audioMime)}`;
  const segmentPath = path.join(mobileRecorderLiveRoot(id), `segment-${String(segmentIndex).padStart(5, "0")}${mobileAudioExtension(audioMime)}`);
  fs.mkdirSync(path.dirname(segmentPath), { recursive: true });
  fs.writeFileSync(segmentPath, segmentAudio);
  const chunkHash = createHash("sha256").update(segmentAudio).digest("hex");

  const providerConfigured = mobileTranscriptionConfigured();

  // Insert (idempotent by chunk_hash) the segment row immediately, in a
  // "transcribing" (or "provider_unavailable") state, so the mobile poll can
  // distinguish "uploaded, waiting for transcription" from "text received".
  const segment = insertMobileTranscriptSegment(db, {
    sessionId: id,
    deviceId,
    segmentIndex,
    chunkIndex: segmentIndex,
    chunkHash,
    text: "",
    status: providerConfigured ? "transcribing" : "provider_unavailable",
    startMs: normalizeNullableInteger(body.startMs) || 0,
    endMs: normalizeNullableInteger(body.endMs) || 0,
    language,
    provider: "",
    audioPath: segmentPath,
    audioMime,
    audioBytes: segmentAudio.byteLength,
    metadata: { live: true, uploadedAt: now },
  });
  const segmentRowId = String((segment as { id?: string })?.id || "");

  audit(db, "mobile.recorder.live_segment", "mobile_recording_session", id, "normal", {
    deviceId,
    segmentIndex,
    totalChunks,
    audioBytes: segmentAudio.byteLength,
    providerConfigured,
  });

  if (!providerConfigured) {
    return reply.code(202).send({
      ok: true,
      status: "provider_unavailable",
      transcriptionConfigured: false,
      segmentIndex,
      segment,
    });
  }

  // Transcribe this completed live segment in the background; the mobile
  // segment-poll picks up the text on its next tick. Store non-empty text into
  // mobile_transcript_segments on success.
  const runSegmentTranscription = async () => {
    const result = await transcribeMobileVoiceAudio({
      audioBuffer: segmentAudio,
      audioMime,
      filename,
      language,
      audioPath: segmentPath,
    });
    const transcriptText = normalizeMobileTranscript(result.text);
    db.prepare(`
      UPDATE mobile_transcript_segments
      SET text = ?, status = ?, provider = ?, updated_at = ?, error = ''
      WHERE id = ?
    `).run(
      transcriptText,
      transcriptText ? "transcript_ready" : "empty",
      `${result.provider}:${result.model}`,
      nowIso(),
      segmentRowId,
    );
    updateMobileRecordingSession(db, { id, lastSegmentAt: nowIso() });
    audit(db, "mobile.recorder.live_segment.transcribed", "mobile_recording_session", id, "normal", {
      deviceId,
      segmentIndex,
      provider: result.provider,
      model: result.model,
      transcriptChars: transcriptText.length,
    });
  };
  void runSegmentTranscription().catch((err) => {
    const message = err instanceof Error ? err.message : "transcription_failed";
    db.prepare("UPDATE mobile_transcript_segments SET status = 'transcription_failed', error = ?, updated_at = ? WHERE id = ?")
      .run(message.slice(0, 500), nowIso(), segmentRowId);
    audit(db, "mobile.recorder.live_segment.failed", "mobile_recording_session", id, "warn", { deviceId, segmentIndex, error: message });
  });

  return reply.code(202).send({
    ok: true,
    status: "transcribing",
    transcriptionConfigured: true,
    segmentIndex,
    segment,
  });
});

app.get("/api/mobile/recorder/sessions/:id/segments", async (req, reply) => {
  const id = String((req.params as { id?: string }).id || "");
  const device = mobileDeviceFromRequest(req);
  const deviceId = device?.id ? String(device.id) : "";
  if (!deviceId) return reply.code(401).send({ ok: false, error: "mobile_auth_required" });
  const session = getMobileRecordingSession(db, id) as { deviceId?: string } | null;
  if (!session) return reply.code(404).send({ ok: false, error: "recorder_session_not_found" });
  if (!canAccessMobileRecordingSession(session, deviceId)) return reply.code(403).send({ ok: false, error: "recorder_session_device_mismatch" });
  return { ok: true, session, segments: listMobileTranscriptSegments(db, id) };
});

app.post("/api/mobile/recorder/sessions/:id/ingest", async (req, reply) => {
  const id = String((req.params as { id?: string }).id || "");
  const body = (req.body || {}) as MobileRecorderIngestBody;
  const device = mobileDeviceFromRequest(req);
  const deviceId = device?.id ? String(device.id) : "";
  if (!deviceId) return reply.code(401).send({ ok: false, error: "mobile_auth_required" });
  const session = getMobileRecordingSession(db, id) as { deviceId?: string } | null;
  if (!session) return reply.code(404).send({ ok: false, error: "recorder_session_not_found" });
  if (!canAccessMobileRecordingSession(session, deviceId)) return reply.code(403).send({ ok: false, error: "recorder_session_device_mismatch" });
  const target = normalizeMobileRecorderIngestTarget(body.target);
  const existing = getMobileIngestionJobBySessionTarget(db, id, target);
  if (existing && String((existing as { status?: string }).status || "") === "completed") {
    return { ok: true, status: "reused", job: existing };
  }
  const job = existing || createMobileIngestionJob(db, {
    sessionId: id,
    deviceId,
    target,
    payload: body.payload || {},
  });
  const jobId = String((job as { id?: string }).id || "");
  const payload = (body.payload || {}) as Record<string, unknown>;
  const transcriptText = normalizeMobileTranscript(payload.transcriptText || payload.content || payload.text || "");
  if (!transcriptText) {
    db.prepare("UPDATE mobile_ingestion_jobs SET status = 'failed', attempts = attempts + 1, last_error = ?, completed_at = ?, updated_at = ? WHERE id = ?")
      .run("transcript_required", nowIso(), nowIso(), jobId);
    return reply.code(400).send({ ok: false, error: "transcript_required", job });
  }
  const startedAt = nowIso();
  db.prepare("UPDATE mobile_ingestion_jobs SET status = 'running', attempts = attempts + 1, started_at = COALESCE(started_at, ?), last_error = '', payload = ?, updated_at = ? WHERE id = ?")
    .run(startedAt, JSON.stringify(payload), startedAt, jobId);
  try {
    const dateKey = normalizeMobileDateKey(payload.date || localDateKey()) || localDateKey();
    const title = normalizeMobileVoiceTitle(payload.title, transcriptText, dateKey);
    const source = normalizeMobileVoiceSource(payload.source || "speech_recognition");
    const language = String(payload.language || "zh-CN").slice(0, 20);
    const durationSeconds = normalizeNullableInteger(payload.durationSeconds);
    const sourceHash = createHash("sha256")
      .update(`${deviceId}::recorder::${id}::${target}::${transcriptText}`)
      .digest("hex");
    let voiceNote = db.prepare(`
      SELECT * FROM mobile_voice_notes
      WHERE device_id IS NOT NULL AND device_id = ? AND source_hash = ?
      ORDER BY updated_at DESC
      LIMIT 1
    `).get(deviceId, sourceHash) as Record<string, unknown> | undefined;
    if (!voiceNote) {
      const voiceNoteId = randomUUID();
      const now = nowIso();
      db.prepare(`
        INSERT INTO mobile_voice_notes (id, device_id, date_key, title, transcript_text, status, source, language, duration_seconds, source_hash, created_at, updated_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      `).run(
        voiceNoteId,
        deviceId,
        dateKey,
        title,
        transcriptText,
        "transcript_ready",
        source,
        language,
        durationSeconds,
        sourceHash,
        now,
        now,
      );
      voiceNote = db.prepare("SELECT * FROM mobile_voice_notes WHERE id = ?").get(voiceNoteId) as Record<string, unknown>;
    }
    const result = saveMobileVoiceNoteToCalendar(voiceNote);
    const knowledgeEntryId = String(result.knowledgeEntry.id || "");
    const calendarNoteId = String((result.calendarNote as { id?: string }).id || "");
    let wikiResult: Record<string, unknown> | null = null;
    try {
      const compiled = compileKnowledgeWiki(db, { mode: "incremental" });
      wikiResult = {
        runId: String(compiled.run?.id || ""),
        status: String(compiled.run?.status || ""),
        generatedCount: compiled.generatedCount,
        mocGeneratedCount: compiled.mocGeneratedCount,
        conflictCount: compiled.conflictCount,
      };
      audit(db, "mobile.recorder.ingest.wiki_compile", "knowledge_wiki_run", String(compiled.run?.id || ""), "normal", { sessionId: id, knowledgeEntryId });
    } catch (err) {
      const message = err instanceof Error ? err.message : "wiki_compile_failed";
      wikiResult = { status: "failed", error: message.slice(0, 500) };
      audit(db, "mobile.recorder.ingest.wiki_compile.failed", "mobile_ingestion_job", jobId, "warn", { sessionId: id, error: message });
    }
    const completedAt = nowIso();
    db.prepare(`
      UPDATE mobile_ingestion_jobs
      SET status = 'completed',
          knowledge_entry_id = ?,
          calendar_note_id = ?,
          markdown_path = ?,
          html_path = ?,
          result = ?,
          completed_at = ?,
          updated_at = ?
      WHERE id = ?
    `).run(
      knowledgeEntryId || null,
      calendarNoteId || null,
      result.markdownPath || "",
      result.htmlPath || "",
      JSON.stringify({ voiceNoteId: String(voiceNote.id || ""), target, sourceHash, wiki: wikiResult }),
      completedAt,
      completedAt,
      jobId,
    );
    updateMobileRecordingSession(db, { id, status: "ready", knowledgeEntryId: knowledgeEntryId || null, completedAt });
    const updatedJob = db.prepare("SELECT * FROM mobile_ingestion_jobs WHERE id = ?").get(jobId);
    audit(db, "mobile.recorder.ingest.completed", "mobile_ingestion_job", jobId, "high", { deviceId, sessionId: id, target, knowledgeEntryId, calendarNoteId });
    return reply.code(existing ? 200 : 201).send({
      ok: true,
      status: existing ? "reused" : "created",
      job: updatedJob,
      voiceNote: sanitizeMobileVoiceNote(voiceNote),
      markdownPath: result.markdownPath,
      htmlPath: result.htmlPath,
      knowledgeEntryId,
      calendarNoteId,
    });
  } catch (err) {
    const message = err instanceof Error ? err.message : "recorder_ingest_failed";
    const failedAt = nowIso();
    db.prepare("UPDATE mobile_ingestion_jobs SET status = 'failed', last_error = ?, completed_at = ?, updated_at = ? WHERE id = ?")
      .run(message.slice(0, 500), failedAt, failedAt, jobId);
    audit(db, "mobile.recorder.ingest.failed", "mobile_ingestion_job", jobId, "warn", { deviceId, sessionId: id, target, error: message });
    return reply.code(500).send({ ok: false, error: "recorder_ingest_failed", reason: message, job: db.prepare("SELECT * FROM mobile_ingestion_jobs WHERE id = ?").get(jobId) });
  }
});

app.post("/api/mobile/voice-notes/:id/audio-chunk", async (req, reply) => {
  const id = String((req.params as { id?: string }).id || "");
  const body = (req.body || {}) as MobileVoiceAudioChunkBody;
  const voiceNote = db.prepare("SELECT * FROM mobile_voice_notes WHERE id = ?").get(id) as Record<string, unknown> | undefined;
  if (!voiceNote) return reply.code(404).send({ ok: false, error: "voice_note_not_found" });
  const device = mobileDeviceFromRequest(req);
  const deviceId = device?.id ? String(device.id) : "";
  if (!canAccessMobileVoiceNote(voiceNote, deviceId)) return reply.code(403).send({ ok: false, error: "voice_note_device_mismatch" });

  let chunkIndex = 0;
  let totalChunks = 0;
  let audio: Buffer;
  try {
    chunkIndex = normalizeMobileAudioChunkNumber(body.chunkIndex, "chunk_index", MOBILE_AUDIO_CHUNK_MAX_COUNT - 1);
    totalChunks = normalizeMobileAudioChunkNumber(body.totalChunks, "total_chunks", MOBILE_AUDIO_CHUNK_MAX_COUNT);
    if (totalChunks <= 0 || chunkIndex >= totalChunks) throw new Error("audio_chunk_index_invalid");
    audio = decodeMobileVoiceAudioBase64(body.audioBase64);
  } catch (err) {
    const message = err instanceof Error ? err.message : "invalid_audio_chunk";
    return reply.code(400).send({ ok: false, error: message });
  }
  if (audio.byteLength > MOBILE_AUDIO_CHUNK_BYTES) {
    return reply.code(413).send({
      ok: false,
      error: "audio_chunk_too_large",
      maxBytes: MOBILE_AUDIO_CHUNK_BYTES,
      chunkBytes: audio.byteLength,
    });
  }
  const totalBytes = normalizeNullableInteger(body.totalBytes);
  if (totalBytes != null && totalBytes > MOBILE_TRANSCRIPTION_MAX_BYTES) {
    return reply.code(413).send({ ok: false, error: "audio_too_large", maxBytes: MOBILE_TRANSCRIPTION_MAX_BYTES, totalBytes });
  }

  const dir = mobileVoiceChunkDir(id);
  if (chunkIndex === 0 || isTruthyMobileFlag(body.reset)) cleanupMobileVoiceChunks(id);
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(mobileVoiceChunkPath(id, chunkIndex), audio);
  const mime = normalizeMobileAudioMime(body.audioMime);
  const fallbackName = `mobile-voice${mobileAudioExtension(mime)}`;
  const filename = safeName(String(body.filename || fallbackName)).slice(0, 80) || fallbackName;
  fs.writeFileSync(mobileVoiceChunkMetaPath(id), JSON.stringify({
    totalChunks,
    totalBytes,
    audioMime: mime,
    filename,
    updatedAt: nowIso(),
  }, null, 2));

  let uploadedChunks = 0;
  let receivedBytes = 0;
  for (let index = 0; index < totalChunks; index += 1) {
    const file = mobileVoiceChunkPath(id, index);
    if (!fs.existsSync(file)) continue;
    uploadedChunks += 1;
    receivedBytes += fs.statSync(file).size;
  }
  const status = uploadedChunks >= totalChunks ? "audio_uploaded" : "audio_uploading";
  db.prepare(`
    UPDATE mobile_voice_notes
    SET status = ?,
        source = 'audio_upload',
        audio_mime = ?,
        audio_bytes = ?,
        duration_seconds = COALESCE(?, duration_seconds),
        updated_at = ?,
        error = ''
    WHERE id = ?
  `).run(
    status,
    mime,
    receivedBytes,
    normalizeNullableInteger(body.durationSeconds),
    nowIso(),
    id,
  );
  audit(db, "mobile.voice_note.audio_chunk", "mobile_voice_note", id, "normal", {
    deviceId: deviceId || null,
    chunkIndex,
    totalChunks,
    uploadedChunks,
    receivedBytes,
  });
  return {
    ok: true,
    status,
    chunkIndex,
    totalChunks,
    uploadedChunks,
    receivedBytes,
    maxChunkBytes: MOBILE_AUDIO_CHUNK_BYTES,
    voiceNote: sanitizeMobileVoiceNote(db.prepare("SELECT * FROM mobile_voice_notes WHERE id = ?").get(id)),
  };
});

app.post("/api/mobile/voice-notes/:id/transcribe", async (req, reply) => {
  const id = String((req.params as { id?: string }).id || "");
  const body = req.body as MobileVoiceTranscribeBody;
  const voiceNote = db.prepare("SELECT * FROM mobile_voice_notes WHERE id = ?").get(id) as Record<string, unknown> | undefined;
  if (!voiceNote) return reply.code(404).send({ ok: false, error: "voice_note_not_found" });
  const device = mobileDeviceFromRequest(req);
  const deviceId = device?.id ? String(device.id) : "";
  if (!canAccessMobileVoiceNote(voiceNote, deviceId)) return reply.code(403).send({ ok: false, error: "voice_note_device_mismatch" });

  if (!mobileTranscriptionConfigured()) {
    db.prepare("UPDATE mobile_voice_notes SET status = 'transcription_failed', error = ?, updated_at = ? WHERE id = ?")
      .run("transcription_provider_unavailable", nowIso(), id);
    audit(db, "mobile.voice_note.transcribe.unavailable", "mobile_voice_note", id, "warn", { deviceId: deviceId || null, provider: mobileTranscriptionProvider() || "none" });
    return reply.code(503).send({ ok: false, error: "transcription_provider_unavailable" });
  }

  let audio: MobileVoiceAudioPayload;
  try {
    audio = decodeMobileVoiceAudio(body, id);
  } catch (err) {
    const message = err instanceof Error ? err.message : "invalid_audio";
    return reply.code(400).send({ ok: false, error: message });
  }

  const now = nowIso();
  const title = normalizeMobileVoiceTitle(voiceNote.title, String(voiceNote.transcript_text || ""), String(voiceNote.date_key || localDateKey()));
  const savedAudio = saveMobileVoiceAudio({
    id,
    dateKey: String(voiceNote.date_key || localDateKey()),
    title,
    audio,
  });
  if (isTruthyMobileFlag(body.uploadedAudio)) cleanupMobileVoiceChunks(id);
  const probedAudioSeconds = probeMobileAudioSeconds(savedAudio.path);
  if (probedAudioSeconds != null && probedAudioSeconds < mobileVoiceMinAudioSeconds()) {
    db.prepare(`
      UPDATE mobile_voice_notes
      SET status = 'transcription_failed',
          source = 'audio_upload',
          audio_path = ?,
          audio_mime = ?,
          audio_bytes = ?,
          audio_hash = ?,
          duration_seconds = COALESCE(?, duration_seconds),
          language = ?,
          updated_at = ?,
          error = 'audio_too_short'
      WHERE id = ?
    `).run(
      savedAudio.path,
      audio.mime,
      audio.buffer.byteLength,
      savedAudio.hash,
      normalizeNullableInteger(Math.max(0, Math.round(probedAudioSeconds))),
      String(body.language || voiceNote.language || "zh-CN").slice(0, 20),
      now,
      id,
    );
    audit(db, "mobile.voice_note.transcribe.audio_too_short", "mobile_voice_note", id, "warn", {
      deviceId: deviceId || null,
      mediaDurationSeconds: probedAudioSeconds,
      requestedDurationSeconds: normalizeNullableInteger(body.durationSeconds),
      audioBytes: audio.buffer.byteLength,
    });
    return reply.code(422).send({
      ok: false,
      error: "audio_too_short",
      mediaDurationSeconds: probedAudioSeconds,
      voiceNote: sanitizeMobileVoiceNote(db.prepare("SELECT * FROM mobile_voice_notes WHERE id = ?").get(id)),
    });
  }
  db.prepare(`
    UPDATE mobile_voice_notes
    SET status = 'transcribing',
        source = 'audio_upload',
        audio_path = ?,
        audio_mime = ?,
        audio_bytes = ?,
        audio_hash = ?,
        duration_seconds = COALESCE(?, duration_seconds),
        language = ?,
        updated_at = ?,
        error = ''
    WHERE id = ?
  `).run(
    savedAudio.path,
    audio.mime,
    audio.buffer.byteLength,
    savedAudio.hash,
    normalizeNullableInteger(body.durationSeconds),
    String(body.language || voiceNote.language || "zh-CN").slice(0, 20),
    now,
    id,
  );

  const runTranscription = async () => {
    const result = await transcribeMobileVoiceAudio({
      audioBuffer: audio.buffer,
      audioMime: audio.mime,
      filename: audio.filename,
      language: String(body.language || voiceNote.language || "zh-CN").slice(0, 20),
      audioPath: savedAudio.path,
    });
    const transcriptText = normalizeMobileTranscript(result.text);
    if (!transcriptText) throw new Error("transcript_empty");
    db.prepare(`
      UPDATE mobile_voice_notes
      SET transcript_text = ?,
          status = 'transcript_ready',
          source = 'speech_recognition',
          transcription_provider = ?,
          updated_at = ?,
          error = ''
      WHERE id = ?
    `).run(transcriptText, `${result.provider}:${result.model}`, nowIso(), id);
    audit(db, "mobile.voice_note.transcribe", "mobile_voice_note", id, "normal", { deviceId: deviceId || null, provider: result.provider, model: result.model, transcriptChars: transcriptText.length });
    return {
      ok: true,
      transcriptText,
      provider: result.provider,
      model: result.model,
      voiceNote: sanitizeMobileVoiceNote(db.prepare("SELECT * FROM mobile_voice_notes WHERE id = ?").get(id)),
    };
  };

  const handleTranscriptionFailure = (err: unknown) => {
    const message = err instanceof Error ? err.message : "transcription_failed";
    db.prepare("UPDATE mobile_voice_notes SET status = 'transcription_failed', error = ?, updated_at = ? WHERE id = ?")
      .run(message.slice(0, 500), nowIso(), id);
    audit(db, "mobile.voice_note.transcribe.failed", "mobile_voice_note", id, "warn", { deviceId: deviceId || null, error: message });
    return message;
  };

  if (wantsAsyncMobileTranscription(body)) {
    void runTranscription().catch((err) => {
      handleTranscriptionFailure(err);
    });
    return reply.code(202).send({
      ok: true,
      status: "transcribing",
      voiceNote: sanitizeMobileVoiceNote(db.prepare("SELECT * FROM mobile_voice_notes WHERE id = ?").get(id)),
    });
  }

  try {
    return await runTranscription();
  } catch (err) {
    const message = handleTranscriptionFailure(err);
    return reply.code(502).send({ ok: false, error: "transcription_failed", reason: message });
  }
});

app.post("/api/mobile/voice-notes/:id/transcript", async (req, reply) => {
  const id = String((req.params as { id?: string }).id || "");
  const body = req.body as Pick<MobileVoiceNoteBody, "transcriptText" | "source" | "language" | "durationSeconds">;
  const voiceNote = db.prepare("SELECT * FROM mobile_voice_notes WHERE id = ?").get(id) as Record<string, unknown> | undefined;
  if (!voiceNote) return reply.code(404).send({ ok: false, error: "voice_note_not_found" });
  const device = mobileDeviceFromRequest(req);
  const deviceId = device?.id ? String(device.id) : "";
  if (!canAccessMobileVoiceNote(voiceNote, deviceId)) return reply.code(403).send({ ok: false, error: "voice_note_device_mismatch" });
  const transcriptText = normalizeMobileTranscript(body.transcriptText);
  if (!transcriptText) return reply.code(400).send({ ok: false, error: "transcript_required" });
  const source = normalizeMobileVoiceSource(body.source);
  db.prepare(`
    UPDATE mobile_voice_notes
    SET transcript_text = ?, status = 'transcript_ready', source = ?, language = ?, duration_seconds = COALESCE(?, duration_seconds), updated_at = ?, error = ''
    WHERE id = ?
  `).run(
    transcriptText,
    source,
    String(body.language || voiceNote.language || "zh-CN").slice(0, 20),
    normalizeNullableInteger(body.durationSeconds),
    nowIso(),
    id,
  );
  audit(db, "mobile.voice_note.transcript", "mobile_voice_note", id, "normal", { deviceId: deviceId || null, source, transcriptChars: transcriptText.length });
  return { ok: true, voiceNote: sanitizeMobileVoiceNote(db.prepare("SELECT * FROM mobile_voice_notes WHERE id = ?").get(id)) };
});

