// 2026-06-24 — P0-B: single-shot add-note that returns both Markdown + HTML paths
// in one response, and rejects duplicate submissions of the same body hash.
// This complements the older create+organize flow (which is kept for backward
// compatibility) by giving mobile a single primary action that cannot create
// duplicate notes for the same body+device+source triple.
app.post("/api/mobile/knowledge/notes/add", async (req, reply) => {
  const body = (req.body || {}) as {
    title?: string;
    body?: string;
    source?: string;
    language?: string;
    transcriptText?: string;
    durationSeconds?: number | null;
  };
  const device = mobileDeviceFromRequest(req);
  const deviceId = device?.id ? String(device.id) : "";
  const content = String(body.body || "").trim();
  const transcript = String(body.transcriptText || content || "").trim();
  if (!content && !transcript) return reply.code(400).send({ ok: false, error: "content_required" });
  // Source hash dedupes the user's local content for 60 s. The server
  // additionally dedupes on (device_id, source_hash) so a re-sent identical
  // body from the same device returns the previously saved note rather than
  // creating a second one.
  const crypto = await import("node:crypto");
  const sourceHash = crypto.createHash("sha256")
    .update(`${deviceId}::${content}::${transcript}::${body.source || "manual_transcript"}`)
    .digest("hex");
  const existing = db.prepare(`
    SELECT * FROM mobile_voice_notes
    WHERE device_id IS NOT NULL AND device_id = ? AND source_hash = ?
    ORDER BY updated_at DESC
    LIMIT 1
  `).get(deviceId, sourceHash) as Record<string, unknown> | undefined;
  if (existing) {
    return reply.code(200).send({
      ok: true,
      status: "duplicate",
      voiceNote: sanitizeMobileVoiceNote(existing),
      sourceHash,
    });
  }
  const dateKey = normalizeMobileDateKey("");
  const title = String(body.title || "").trim().slice(0, 200) || "手机速记";
  const id = randomUUID();
  const now = nowIso();
  db.prepare(`
    INSERT INTO mobile_voice_notes (id, device_id, date_key, title, transcript_text, status, source, language, duration_seconds, source_hash, created_at, updated_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `).run(
    id,
    deviceId || null,
    dateKey,
    title,
    transcript,
    "transcript_ready",
    String(body.source || "manual_transcript").slice(0, 40),
    String(body.language || "zh-CN").slice(0, 20),
    normalizeNullableInteger(body.durationSeconds),
    sourceHash,
    now,
    now,
  );
  const voiceNote = db.prepare("SELECT * FROM mobile_voice_notes WHERE id = ?").get(id) as Record<string, unknown>;
  try {
    const result = saveMobileVoiceNoteToCalendar(voiceNote);
    audit(db, "mobile.knowledge.note.add", "mobile_voice_note", id, "high", { deviceId: deviceId || null, knowledgeEntryId: String(result.knowledgeEntry.id || ""), calendarNoteId: String(result.calendarNote.id || ""), sourceHash });
    return reply.code(201).send({
      ok: true,
      status: "saved",
      voiceNote: sanitizeMobileVoiceNote(voiceNote),
      markdownPath: result.markdownPath,
      htmlPath: result.htmlPath,
      sourceHash,
      knowledgeEntryId: String(result.knowledgeEntry.id || ""),
      calendarNoteId: String(result.calendarNote.id || ""),
    });
  } catch (err) {
    const message = err instanceof Error ? err.message : "voice_note_organize_failed";
    db.prepare("UPDATE mobile_voice_notes SET status = 'organize_failed', error = ?, updated_at = ? WHERE id = ?")
      .run(message.slice(0, 500), nowIso(), id);
    audit(db, "mobile.knowledge.note.add.failed", "mobile_voice_note", id, "warn", { deviceId: deviceId || null, error: message });
    return reply.code(500).send({ ok: false, error: "voice_note_organize_failed", reason: message, sourceHash });
  }
});


app.get("/api/mobile/knowledge/notes/content", async (req, reply) => {
    const query = (req.query || {}) as { path?: string };
    const inputPath = String(query.path || "");
    if (!inputPath) return reply.code(400).send({ ok: false, error: "path_required" });
    // 限定读取范围:WORKSPACE_DIR 或 VAULT 根下的文件,防止越权
    const { WORKSPACE_DIR, KB_VAULT_DIR } = await import("./config.js");
    const allowedRoots = [WORKSPACE_DIR, KB_VAULT_DIR].map(p => path.resolve(p));
    const abs = path.resolve(inputPath);
    if (!allowedRoots.some(root => abs.startsWith(root + path.sep) || abs === root)) {
        return reply.code(403).send({ ok: false, error: "path_outside_allowed_roots" });
    }
    if (!fs.existsSync(abs)) {
        return reply.code(404).send({ ok: false, error: "file_not_found", path: inputPath });
    }
    const stat = fs.statSync(abs);
    if (!stat.isFile()) {
        return reply.code(400).send({ ok: false, error: "not_a_file" });
    }
    if (stat.size > 2 * 1024 * 1024) {
        return reply.code(413).send({ ok: false, error: "file_too_large" });
    }
    const content = fs.readFileSync(abs, "utf8");
    return { ok: true, path: abs, content, size: stat.size, kind: abs.endsWith(".html") ? "html" : "markdown" };
});

app.get("/api/overview", async () => {
  const [gateway, sources] = await Promise.all([gatewaySummary(), Promise.resolve(sourceStatus())]);
  const tasks = filterSyntheticRows(db.prepare("SELECT * FROM tasks ORDER BY updated_at DESC LIMIT 120").all() as Array<Record<string, unknown>>);
  const approvals = filterSyntheticRows(db.prepare("SELECT * FROM approvals ORDER BY requested_at DESC LIMIT 80").all() as Array<Record<string, unknown>>);
  const taskCounts = db.prepare("SELECT status, COUNT(*) count FROM tasks GROUP BY status").all();
  const researchCounts = db.prepare("SELECT status, COUNT(*) count FROM research_jobs GROUP BY status").all();
  const todos = db.prepare("SELECT * FROM todos ORDER BY created_at DESC LIMIT 30").all() as Array<Record<string, unknown>>;
  const events = db.prepare("SELECT * FROM events ORDER BY start_at ASC LIMIT 30").all() as Array<Record<string, unknown>>;
  const gatewayCron = gatewayCronJobs(gateway);
  const localCron = localCronJobs(db).slice(0, 40);
  const cron = gatewayCron.length ? gatewayCron : localCron.filter((row) => !row.synthetic);
  const notifications = db.prepare("SELECT * FROM notifications ORDER BY created_at DESC LIMIT 12").all() as Array<Record<string, unknown>>;
  const projects = db.prepare("SELECT * FROM projects ORDER BY updated_at DESC LIMIT 12").all() as Array<Record<string, unknown>>;
  const milestones = db.prepare("SELECT * FROM project_milestones ORDER BY due_date ASC, updated_at DESC LIMIT 20").all() as Array<Record<string, unknown>>;
  const deliverables = db.prepare("SELECT * FROM project_deliverables ORDER BY updated_at DESC LIMIT 20").all() as Array<Record<string, unknown>>;
  const reports = db.prepare("SELECT * FROM reports ORDER BY updated_at DESC LIMIT 12").all() as Array<Record<string, unknown>>;
  const recentKnowledge = db.prepare("SELECT * FROM knowledge_entries ORDER BY updated_at DESC LIMIT 12").all() as Array<Record<string, unknown>>;
  const recentFiles = db.prepare("SELECT * FROM knowledge_file_index ORDER BY created_at DESC LIMIT 12").all() as Array<Record<string, unknown>>;
  const outputJobs = filterSyntheticRows(db.prepare("SELECT * FROM knowledge_output_jobs ORDER BY updated_at DESC LIMIT 12").all() as Array<Record<string, unknown>>);
  const modelConfigs = db.prepare("SELECT id, label, provider, model, is_default, api_key_configured FROM model_configs WHERE status = 'active' ORDER BY is_default DESC, label ASC").all() as Array<Record<string, unknown>>;
  const audit24h = db.prepare("SELECT COUNT(*) count FROM audit_logs WHERE ts >= ?").get(new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString()) as { count?: number } | undefined;
  const resources = {
    loadavg: safeSystemMetric(() => os.loadavg(), [0, 0, 0]),
    memory: safeSystemMetric(() => {
      const total = os.totalmem();
      const free = os.freemem();
      return { total, free, used: total - free };
    }, { total: 0, free: 0, used: 0 }),
    uptimeSec: safeSystemMetric(() => os.uptime(), 0),
  };
  const today = localDateKey();
  const todayTodos = todos.filter((todo) => isOpenStatus(todo.status) && (startsWithDate(todo.due_at, today) || startsWithDate(todo.created_at, today) || startsWithDate(todo.updated_at, today)));
  const todayEvents = events.filter((event) => startsWithDate(event.start_at, today));
  const todayTasks = tasks.filter((task) => isOpenStatus(task.status) && (startsWithDate(task.created_at, today) || startsWithDate(task.updated_at, today)));
  const pendingApprovals = approvals.filter((approval) => approval.status === "pending");
  const taskSummary = {
    counts: countBy(tasks, "status"),
    running: tasks.filter((task) => ["queued", "running", "gateway_unavailable"].includes(String(task.status))),
    pendingApprovals,
    failed: tasks.filter((task) => ["failed", "blocked", "gateway_unavailable"].includes(String(task.status))),
    dagRisks: tasks.filter((task) => task.parent_task_id || String(task.input || "").includes("depends_on")).slice(0, 10),
    projectProgress: projects.map((project) => ({
      id: project.id,
      name: project.name,
      status: project.status,
      progress: Number(project.progress || 0),
      taskCount: tasks.filter((task) => task.project_id && task.project_id === project.id).length,
    })),
  };
  const knowledge = {
    sources,
    recentEntries: recentKnowledge,
    recentFiles,
    outputJobs,
    indexErrors: notifications.filter((item) => String(item.source || "").includes("knowledge") && ["error", "warn"].includes(String(item.level))),
    syncStatus: {
      memory: sources.memory?.status || "unknown",
      nas: sources.nas?.status || "unknown",
      ima: sources.ima?.status || "unknown",
    },
  };
  const costResource = {
    token: {
      status: "not_integrated",
      risk: "not_integrated",
      source: "none",
      note: "Token/额度官方用量 API 未接入；这里不展示估算成本或额度风险。",
    },
    modelCalls24h: Number(audit24h?.count || 0),
    models: modelConfigs,
    resources,
  };
  const agents = agentRuntimeCards(gateway, tasks);
  return {
    ok: true,
    gateway,
    sources,
    taskCounts,
    researchCounts,
    todos,
    notifications,
    resources,
    alerts: buildOverviewAlerts({ gateway, sources, tasks, approvals, cron, notifications, knowledge, costResource }),
    agents,
    cron: { gateway: gatewayCron, local: localCron },
    today: { todos: todayTodos, events: todayEvents, tasks: todayTasks, approvals: pendingApprovals },
    taskSummary,
    knowledge,
    projects: { projects, milestones, deliverables, reports, researchCounts },
    costResource,
    dashboard: { presets: ["owner", "ops", "personal"], defaultPreset: "owner", updatedAt: nowIso() },
  };
});

