app.get("/api/skills", async () => {
  const skills = discoverSkills();
  for (const skill of skills) {
    db.prepare("INSERT OR IGNORE INTO skill_catalog (id, name, source, path, description, status, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)")
      .run(skill.id, skill.name, skill.source, skill.path, skill.description, skill.status, nowIso());
  }
  const discoveredIds = new Set(skills.map((skill) => skill.id));
  const catalogOnly = (db.prepare("SELECT id, name, source, path, description, status FROM skill_catalog ORDER BY created_at DESC").all() as Array<Record<string, unknown>>)
    .filter((skill) => !discoveredIds.has(String(skill.id || "")));
  return { ok: true, skills: enrichSkills([...catalogOnly, ...skills]), tools: configuredTools() };
});

app.post("/api/skills", async (req, reply) => {
  const body = req.body as { name?: string; description?: string; prompt?: string; agentId?: string };
  const name = String(body.name || "").trim().slice(0, 80);
  const description = String(body.description || "").trim().slice(0, 300);
  const prompt = String(body.prompt || "").trim().slice(0, 4000);
  const agentId = String(body.agentId || "main").trim().slice(0, 40) || "main";
  if (!name) return reply.code(400).send({ ok: false, error: "skill_name_required" });
  const id = `dev-${safeName(name).slice(0, 48) || randomUUID().slice(0, 8)}`.toLowerCase();
  const skillDir = path.join(os.homedir(), "openclaw_data", "copilot", "skills", id);
  const skillPath = path.join(skillDir, "SKILL.md");
  const createdAt = nowIso();
  fs.mkdirSync(skillDir, { recursive: true });
  const markdown = [
    `---`,
    `name: ${id}`,
    `description: ${description || `${name} skill created from OpenClaw Dev Console`}`,
    `---`,
    ``,
    `# ${name}`,
    ``,
    description || "开发台创建的技能草稿。请补齐触发条件、输入、输出和验收标准。",
    ``,
    `## Usage`,
    prompt || "- TODO: 描述该 skill 何时使用、如何执行、失败如何兜底。",
    ``,
    `## Acceptance`,
    `- 创建来源: OpenClaw Dev Console`,
    `- Owner agent: ${agentId}`,
    `- Created at: ${createdAt}`,
    ``,
  ].join("\n");
  fs.writeFileSync(skillPath, markdown, "utf8");
  db.prepare("INSERT OR REPLACE INTO skill_catalog (id, name, source, path, description, status, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)")
    .run(id, name, "openclaw-dev-console", skillPath, description || "开发台创建的技能草稿", "draft", createdAt);
  audit(db, "skill.create", "skill", id, "normal", { source: "dev_console", agentId, path: skillPath });
  return {
    ok: true,
    skill: { id, name, source: "openclaw-dev-console", path: skillPath, description: description || "开发台创建的技能草稿", status: "draft", createdAt },
  };
});

