app.post("/api/model-configs", async (req) => {
  const body = req.body as { label?: string; provider?: string; model?: string; baseUrl?: string; apiKey?: string; apiKeyRef?: string; contextWindow?: number; metadata?: Record<string, unknown>; preferred?: boolean };
  const label = String(body.label || "").trim().slice(0, 80);
  const provider = String(body.provider || "").trim().slice(0, 40);
  const model = String(body.model || "").trim().slice(0, 120);
  const baseUrl = String(body.baseUrl || "").trim().slice(0, 300) || null;
  const apiKey = String(body.apiKey || "").trim();
  const apiKeyRef = String(body.apiKeyRef || "").trim().slice(0, 120) || (apiKey ? defaultApiKeyRef(provider, model) : null);
  const contextWindow = Number(body.contextWindow || 0);
  if (!label || !provider || !model) return { ok: false, error: "label_provider_model_required" };
  const id = `${safeName(provider)}-${safeName(model)}-${randomUUID().slice(0, 8)}`.toLowerCase();
  const now = nowIso();
  const metadata = {
    ...(body.metadata && typeof body.metadata === "object" ? body.metadata : {}),
    apiKeyConfigured: Boolean(apiKey || apiKeyRef),
    apiKeyPreview: apiKey ? apiKey.slice(-4) : undefined,
    credentialStorage: apiKey ? "api_key_ref_only" : "none",
  };
  if (body.preferred) db.prepare("UPDATE model_configs SET is_default = 0").run();
  db.prepare("INSERT INTO model_configs (id, label, provider, model, context_window, status, metadata, created_at, updated_at, base_url, api_key_ref, api_key_configured, is_default) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
    .run(id, label, provider, model, Number.isFinite(contextWindow) && contextWindow > 0 ? contextWindow : null, "active", JSON.stringify(metadata), now, now, baseUrl, apiKeyRef, apiKey || apiKeyRef ? 1 : 0, body.preferred ? 1 : 0);
  audit(db, "model.create", "model_config", id, "normal", { label, provider, model, baseUrl, apiKeyRef, apiKeyConfigured: Boolean(apiKey || apiKeyRef), preferred: Boolean(body.preferred) });
  return { ok: true, model: sanitizeModelConfig(db.prepare("SELECT * FROM model_configs WHERE id = ?").get(id)) };
});

app.delete("/api/model-configs/:id", async (req, reply) => {
  const id = String((req.params as { id?: string }).id || "");
  const row = db.prepare("SELECT * FROM model_configs WHERE id = ?").get(id) as { id: string; label: string; is_default?: number; status: string } | undefined;
  if (!row) return reply.code(404).send({ ok: false, error: "model_not_found" });
  const now = nowIso();
  db.prepare("UPDATE model_configs SET status = 'archived', is_default = 0, updated_at = ? WHERE id = ?").run(now, id);
  const activeDefault = db.prepare("SELECT id FROM model_configs WHERE status = 'active' AND is_default = 1 LIMIT 1").get() as { id: string } | undefined;
  if (!activeDefault) db.prepare("UPDATE model_configs SET is_default = 1, updated_at = ? WHERE id = 'minimax-m3' AND status = 'active'").run(now);
  audit(db, "model.archive", "model_config", id, "normal", { label: row.label, previousStatus: row.status });
  return { ok: true };
});

