app.patch("/api/cron/:id", async (req) => {
  const id = (req.params as { id: string }).id;
  const body = req.body as { name?: string; expression?: string; prompt?: string; status?: string };
  const current = db.prepare("SELECT * FROM cron_jobs WHERE id = ?").get(id) as { name: string; expression: string; prompt: string; status: string } | undefined;
  if (!current) {
    const gatewayJob = updateGatewayCronFile(id, body);
    if (!gatewayJob) return { ok: false, error: "not_found" };
    audit(db, "gateway_cron.update", "cron", id, "high", { ...body, source: "filesystem:~/.openclaw/cron/jobs.json" });
    return { ok: true, job: gatewayJob };
  }
  db.prepare("UPDATE cron_jobs SET name = ?, expression = ?, prompt = ?, status = ?, updated_at = ? WHERE id = ?")
    .run(body.name || current.name, body.expression || current.expression, body.prompt || current.prompt, body.status || current.status, nowIso(), id);
  audit(db, "cron.update", "cron", id, "normal", body);
  return { ok: true, job: db.prepare("SELECT * FROM cron_jobs WHERE id = ?").get(id) };
});

function updateGatewayCronFile(id: string, body: { name?: string; expression?: string; prompt?: string; status?: string }) {
  const file = path.join(os.homedir(), ".openclaw", "cron", "jobs.json");
  if (!fs.existsSync(file)) return null;
  const parsed = JSON.parse(fs.readFileSync(file, "utf8")) as { jobs?: Array<Record<string, any>> };
  const jobs = Array.isArray(parsed.jobs) ? parsed.jobs : [];
  const job = jobs.find((item) => String(item.id || item.name || "") === id);
  if (!job) return null;
  fs.copyFileSync(file, `${file}.bak.workbench_${new Date().toISOString().replace(/[:.]/g, "-")}`);
  if (typeof body.name === "string" && body.name.trim()) job.name = body.name.trim();
  if (typeof body.expression === "string" && body.expression.trim()) {
    const schedule = typeof job.schedule === "object" && job.schedule ? job.schedule : {};
    job.schedule = { ...schedule, kind: schedule.kind || "cron", tz: schedule.tz || "Asia/Shanghai", expr: body.expression.trim() };
  }
  if (typeof body.prompt === "string") {
    const payload = typeof job.payload === "object" && job.payload ? job.payload : {};
    job.payload = { ...payload, kind: payload.kind || "agentTurn", message: body.prompt };
  }
  if (typeof body.status === "string") {
    const status = body.status.toLowerCase();
    if (["active", "enabled", "true"].includes(status)) job.enabled = true;
    if (["paused", "disabled", "inactive", "false"].includes(status)) job.enabled = false;
  }
  job.updatedAtMs = Date.now();
  fs.writeFileSync(file, `${JSON.stringify(parsed, null, 2)}\n`);
  return job;
}

