app.post("/api/chat/messages/:id/regenerate", async (req) => {
  const id = (req.params as { id: string }).id;
  const row = db.prepare("SELECT * FROM chat_messages WHERE id = ? AND deleted_at IS NULL").get(id) as { id: string; session_id: string; role: string; agent_id?: string; content: string; created_at: string } | undefined;
  if (!row) return { ok: false, error: "not_found" };
  const session = db.prepare("SELECT * FROM chat_sessions WHERE id = ?").get(row.session_id) as ChatSessionRow | undefined;
  if (!session) return { ok: false, error: "session_not_found" };
  const source = row.role === "user"
    ? row
    : db.prepare("SELECT * FROM chat_messages WHERE session_id = ? AND role = 'user' AND deleted_at IS NULL AND created_at <= ? ORDER BY created_at DESC LIMIT 1").get(row.session_id, row.created_at) as { id: string; content: string } | undefined;
  if (!source?.content) return { ok: false, error: "source_message_not_found" };
  const agentId = row.agent_id || session.agent_id;
  try {
    const answer = await dispatchChat(row.session_id, agentId, source.content, `${source.id}:regenerate:${id}`, {
      modelId: session.model_id || "minimax-m3",
      mode: "regenerate",
      timeoutMs: CHAT_REGENERATE_GATEWAY_TIMEOUT_MS,
      metadata: { regenerateOf: id, sourceMessageId: source.id },
    });
    audit(db, "chat.message.regenerate", "chat_message", id, "normal", { sourceMessageId: source.id, timeoutMs: CHAT_REGENERATE_GATEWAY_TIMEOUT_MS });
    return { ok: true, assistant: answer, degraded: !["completed", "dispatched"].includes(String((answer as { status?: string } | undefined)?.status || "")) };
  } catch (err) {
    const error = sanitizePublicError(err instanceof Error ? err.message : String(err));
    const timedOut = isGatewayFinalTimeout(error);
    const assistantId = randomUUID();
    const content = timedOut
      ? backgroundGatewayContent(error)
      : `Gateway 暂不可用，重新生成请求已保存在工作台。错误：${error}`;
    ensureChatSessionForWrite({ sessionId: row.session_id, agentId, content: source.content, modelId: session.model_id || "minimax-m3" });
    db.prepare("INSERT INTO chat_messages (id, session_id, role, agent_id, content, message_type, status, metadata, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)")
      .run(assistantId, row.session_id, "assistant", agentId, content, "text", timedOut ? "running" : "gateway_unavailable", JSON.stringify({
        error,
        gatewayTimedOut: timedOut,
        context: { mode: "regenerate", regenerateOf: id, sourceMessageId: source.id, timeoutMs: CHAT_REGENERATE_GATEWAY_TIMEOUT_MS },
      }), nowIso());
    db.prepare("UPDATE chat_sessions SET updated_at = ? WHERE id = ?").run(nowIso(), row.session_id);
    audit(db, "chat.message.regenerate.degraded", "chat_message", id, "warn", { sourceMessageId: source.id, error });
    return { ok: true, degraded: true, error, assistant: db.prepare("SELECT * FROM chat_messages WHERE id = ?").get(assistantId) };
  }
});

app.post("/api/chat/attachments", async (req) => {
  const body = req.body as { sessionId?: string; type?: string; name?: string; content?: string; url?: string };
  const sessionId = body.sessionId || String((db.prepare("SELECT id FROM chat_sessions ORDER BY updated_at DESC LIMIT 1").get() as { id?: string } | undefined)?.id || "");
  if (!sessionId) return { ok: false, error: "session_required" };
  const id = randomUUID();
  const type = body.type || (body.url ? "url" : "file");
  const name = String(body.name || body.url || "attachment").slice(0, 160);
  let content = body.content || "";
  let status = "attached";
  if (type === "url" && body.url) {
    try {
      const res = await fetch(body.url, { signal: AbortSignal.timeout(8000) });
      content = await res.text();
      status = res.ok ? "fetched" : "url_saved";
    } catch {
      content = `URL saved without fetch: ${body.url}`;
      status = "url_saved";
    }
  }
  const file = path.join(SIDECAR_DIR, "attachments", `${nowIso().slice(0, 10)}_${id.slice(0, 8)}_${safeName(name)}.txt`);
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, content.slice(0, 200_000), "utf8");
  db.prepare("INSERT INTO chat_attachments (id, session_id, message_id, type, name, source_url, content_path, text_excerpt, status, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
    .run(id, sessionId, null, type, name, body.url || null, file, content.slice(0, 800), status, nowIso());
  return { ok: true, attachment: db.prepare("SELECT * FROM chat_attachments WHERE id = ?").get(id) };
});

app.post("/api/chat/send-stream", async (req, reply) => {
  const body = req.body as ChatSendBody;
  reply.hijack();
  reply.raw.writeHead(200, {
    "Content-Type": "text/event-stream; charset=utf-8",
    "Cache-Control": "no-cache, no-transform",
    Connection: "keep-alive",
  });
  const write = (event: string, data: unknown) => writeSse(reply.raw, event, data);
  let heartbeat: ReturnType<typeof setInterval> | undefined;
  let assistantId = "";
  let sessionId = "";
  try {
    const session = await ensureChatSession(body);
    sessionId = session.id;
    const selectedSources = normalizeSources(body.knowledgeSources ?? parseJsonArray(session.knowledge_sources));
    const selectedSkills = normalizeSkillIds(body.skillIds ?? parseJsonArray(session.skill_ids));
    const selectedModelId = body.modelId || session.model_id || "minimax-m3";
    const userMessageId = randomUUID();
    const content = String(body.message || "").trim();
    if (!content) {
      write("error", { ok: false, error: "empty_message" });
      return;
    }
    const agentId = body.agentId || session.agent_id;
    db.prepare("UPDATE chat_sessions SET agent_id = ?, knowledge_sources = ?, skill_ids = ?, plan_enabled = ?, model_id = ?, updated_at = ? WHERE id = ?")
      .run(agentId, JSON.stringify(selectedSources), JSON.stringify(selectedSkills), typeof body.planEnabled === "boolean" ? (body.planEnabled ? 1 : 0) : session.plan_enabled, selectedModelId, nowIso(), session.id);
    db.prepare("INSERT INTO chat_messages (id, session_id, role, agent_id, content, message_type, status, metadata, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)")
      .run(userMessageId, session.id, "user", null, content, "text", "sent", JSON.stringify({ attachmentIds: body.attachmentIds || [], knowledgeSources: selectedSources, skillIds: selectedSkills, modelId: selectedModelId }), nowIso());
    if (body.attachmentIds?.length) {
      for (const attachmentId of body.attachmentIds) db.prepare("UPDATE chat_attachments SET message_id = ? WHERE id = ? AND session_id = ?").run(userMessageId, attachmentId, session.id);
    }

    const wechatIntent = detectWechatSendIntent(content);
    if (wechatIntent) {
      assistantId = randomUUID();
      const initialMetadata = {
        userMessageId,
        knowledgeSources: selectedSources,
        skillIds: selectedSkills,
        modelId: selectedModelId,
        streaming: true,
        openclawAction: "wechat.prepare",
        recipient: wechatIntent.recipient,
        recipientLabel: wechatIntent.recipientLabel,
      };
      db.prepare("INSERT INTO chat_messages (id, session_id, role, agent_id, content, message_type, status, metadata, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)")
        .run(assistantId, session.id, "assistant", agentId, buildWechatPendingContent(wechatIntent, {}), "text", "streaming", JSON.stringify(initialMetadata), nowIso());
      db.prepare("UPDATE chat_sessions SET updated_at = ?, title = CASE WHEN title = '新对话' THEN ? ELSE title END WHERE id = ?").run(nowIso(), autoTitle(content), session.id);
      write("ready", {
        ok: true,
        sessionId: session.id,
        userMessageId,
        assistantMessageId: assistantId,
        userMessage: db.prepare("SELECT * FROM chat_messages WHERE id = ?").get(userMessageId),
        message: db.prepare("SELECT * FROM chat_messages WHERE id = ?").get(assistantId),
      });
      const actionResult = await runWechatSendAction(wechatIntent, userMessageId);
      await streamFinalContent(assistantId, actionResult.content, write);
      db.prepare("UPDATE chat_messages SET content = ?, status = ?, metadata = ? WHERE id = ?")
        .run(actionResult.content, actionResult.status, JSON.stringify({ ...initialMetadata, ...actionResult.metadata, streaming: false }), assistantId);
      db.prepare("UPDATE chat_sessions SET updated_at = ? WHERE id = ?").run(nowIso(), session.id);
      write("final", { ok: true, sessionId: session.id, userMessageId, assistantMessageId: assistantId, assistant: db.prepare("SELECT * FROM chat_messages WHERE id = ?").get(assistantId), message: db.prepare("SELECT * FROM chat_messages WHERE id = ?").get(assistantId) });
      write("done", { ok: true, sessionId: session.id });
      return;
    }

    const imessageIntent = detectIMessageSendIntent(content);
    if (imessageIntent) {
      assistantId = randomUUID();
      const initialMetadata = { userMessageId, knowledgeSources: selectedSources, skillIds: selectedSkills, modelId: selectedModelId, streaming: true, openclawAction: "imessage.send", targetSource: imessageIntent.source };
      db.prepare("INSERT INTO chat_messages (id, session_id, role, agent_id, content, message_type, status, metadata, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)")
        .run(assistantId, session.id, "assistant", agentId, imessagePendingContent(imessageIntent), "text", "streaming", JSON.stringify(initialMetadata), nowIso());
      db.prepare("UPDATE chat_sessions SET updated_at = ?, title = CASE WHEN title = '新对话' THEN ? ELSE title END WHERE id = ?").run(nowIso(), autoTitle(content), session.id);
      write("ready", {
        ok: true,
        sessionId: session.id,
        userMessageId,
        assistantMessageId: assistantId,
        userMessage: db.prepare("SELECT * FROM chat_messages WHERE id = ?").get(userMessageId),
        message: db.prepare("SELECT * FROM chat_messages WHERE id = ?").get(assistantId),
      });
      const actionResult = await runIMessageSendAction(imessageIntent, userMessageId);
      await streamFinalContent(assistantId, actionResult.content, write);
      db.prepare("UPDATE chat_messages SET content = ?, status = ?, metadata = ? WHERE id = ?")
        .run(actionResult.content, actionResult.status, JSON.stringify({ ...initialMetadata, ...actionResult.metadata, streaming: false }), assistantId);
      db.prepare("UPDATE chat_sessions SET updated_at = ? WHERE id = ?").run(nowIso(), session.id);
      write("final", { ok: true, sessionId: session.id, userMessageId, assistantMessageId: assistantId, assistant: db.prepare("SELECT * FROM chat_messages WHERE id = ?").get(assistantId), message: db.prepare("SELECT * FROM chat_messages WHERE id = ?").get(assistantId) });
      write("done", { ok: true, sessionId: session.id });
      return;
    }

    const planMode = typeof body.planEnabled === "boolean" ? body.planEnabled : Boolean(session.plan_enabled);
    assistantId = randomUUID();
    const planSkills = planMode ? ensureTaskExecutor(selectedSkills) : selectedSkills;
    const messageType = planMode ? "plan" : "text";
    const existingTaskMeta = planMode ? findActiveTaskExecutorMeta(session.id) : null;
    const taskMeta = planMode ? (existingTaskMeta || createTaskExecutorMeta(agentId)) : null;
    const taskStepKind = existingTaskMeta ? "continue" : "start";
    const initialContent = taskMeta ? taskExecutorStreamingStatusContent(taskMeta, agentId, 0) : streamingStatusContent(agentId, false, 0);
    const initialMetadata = { userMessageId, knowledgeSources: selectedSources, skillIds: planSkills, modelId: selectedModelId, streaming: true, ...(taskMeta || {}) };
    db.prepare("INSERT INTO chat_messages (id, session_id, role, agent_id, content, message_type, status, metadata, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)")
      .run(assistantId, session.id, "assistant", agentId, initialContent, messageType, "streaming", JSON.stringify(initialMetadata), nowIso());
    db.prepare("UPDATE chat_sessions SET updated_at = ?, title = CASE WHEN title = '新对话' THEN ? ELSE title END WHERE id = ?").run(nowIso(), autoTitle(content), session.id);
    write("ready", {
      ok: true,
      sessionId: session.id,
      userMessageId,
      assistantMessageId: assistantId,
      userMessage: db.prepare("SELECT * FROM chat_messages WHERE id = ?").get(userMessageId),
      message: db.prepare("SELECT * FROM chat_messages WHERE id = ?").get(assistantId),
    });

    const startedAt = Date.now();
    const gatewaySessionKey = taskMeta?.gatewaySessionKey || `agent:${agentId}:workbench:${session.id}`;
    heartbeat = setInterval(() => {
      const elapsedSeconds = Math.max(1, Math.floor((Date.now() - startedAt) / 1000));
      const fallbackContent = taskMeta ? taskExecutorStreamingStatusContent(taskMeta, agentId, elapsedSeconds) : streamingStatusContent(agentId, false, elapsedSeconds);
      const liveContent = liveGatewayStreamContent(agentId, gatewaySessionKey, startedAt - 1000);
      const statusContent = liveContent || fallbackContent;
      db.prepare("UPDATE chat_messages SET content = ?, status = ? WHERE id = ?").run(statusContent, "streaming", assistantId);
      write("delta", { message: db.prepare("SELECT * FROM chat_messages WHERE id = ?").get(assistantId) });
    }, 2500);

    if (planMode) {
      const generatedPlan = await runTaskExecutorPlanStep(taskMeta as Required<TaskExecutorMeta>, agentId, content, selectedSources, planSkills, selectedModelId, userMessageId, taskStepKind);
      if (heartbeat) {
        clearInterval(heartbeat);
        heartbeat = undefined;
      }
      await streamFinalContent(assistantId, generatedPlan.content, write);
      db.prepare("UPDATE chat_messages SET content = ?, status = ?, metadata = ? WHERE id = ?")
        .run(generatedPlan.content, generatedPlan.status, JSON.stringify({ ...initialMetadata, ...generatedPlan.metadata, planGateway: generatedPlan.gateway, streaming: false }), assistantId);
      db.prepare("UPDATE chat_sessions SET updated_at = ? WHERE id = ?").run(nowIso(), session.id);
      write("final", { ok: true, sessionId: session.id, userMessageId, planMessageId: assistantId, plan: generatedPlan.content, message: db.prepare("SELECT * FROM chat_messages WHERE id = ?").get(assistantId) });
    } else {
      const result = await runGatewayChat(session.id, agentId, content, userMessageId, { sources: selectedSources, skills: selectedSkills, mode: "chat", modelId: selectedModelId });
      if (heartbeat) {
        clearInterval(heartbeat);
        heartbeat = undefined;
      }
      await streamFinalContent(assistantId, result.response, write);
      db.prepare("UPDATE chat_messages SET content = ?, status = ?, metadata = ? WHERE id = ?")
        .run(result.response, result.status, JSON.stringify({ gateway: result.gateway, context: result.context, streaming: false }), assistantId);
      db.prepare("UPDATE chat_sessions SET updated_at = ? WHERE id = ?").run(nowIso(), session.id);
      write("final", { ok: true, sessionId: session.id, userMessageId, assistantMessageId: assistantId, assistant: db.prepare("SELECT * FROM chat_messages WHERE id = ?").get(assistantId), message: db.prepare("SELECT * FROM chat_messages WHERE id = ?").get(assistantId) });
    }
    write("done", { ok: true, sessionId: session.id });
  } catch (err) {
    const error = sanitizePublicError(err instanceof Error ? err.message : String(err));
    if (assistantId) {
      const timedOut = isGatewayFinalTimeout(error);
      const content = timedOut
        ? backgroundGatewayContent(error)
        : `Gateway 暂不可用，消息已保存在工作台。错误：${error}`;
      db.prepare("UPDATE chat_messages SET content = ?, status = ?, metadata = ? WHERE id = ?")
        .run(content, timedOut ? "running" : "gateway_unavailable", JSON.stringify({ error, gatewayTimedOut: timedOut, streaming: false }), assistantId);
      write("final", { ok: !timedOut, sessionId, error: timedOut ? undefined : error, message: db.prepare("SELECT * FROM chat_messages WHERE id = ?").get(assistantId) });
    } else {
      write("error", { ok: false, error });
    }
  } finally {
    if (heartbeat) clearInterval(heartbeat);
    reply.raw.end();
  }
});

app.post("/api/chat/send", async (req) => {
  const body = req.body as ChatSendBody;
  const session = await ensureChatSession(body);
  const selectedSources = normalizeSources(body.knowledgeSources ?? parseJsonArray(session.knowledge_sources));
  const selectedSkills = normalizeSkillIds(body.skillIds ?? parseJsonArray(session.skill_ids));
  const selectedModelId = body.modelId || session.model_id || "minimax-m3";
  const userMessageId = randomUUID();
  const content = String(body.message || "").trim();
  if (!content) return { ok: false, error: "empty_message" };
  db.prepare("UPDATE chat_sessions SET agent_id = ?, knowledge_sources = ?, skill_ids = ?, plan_enabled = ?, model_id = ?, updated_at = ? WHERE id = ?")
    .run(body.agentId || session.agent_id, JSON.stringify(selectedSources), JSON.stringify(selectedSkills), typeof body.planEnabled === "boolean" ? (body.planEnabled ? 1 : 0) : session.plan_enabled, selectedModelId, nowIso(), session.id);
  db.prepare("INSERT INTO chat_messages (id, session_id, role, agent_id, content, message_type, status, metadata, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)")
    .run(userMessageId, session.id, "user", null, content, "text", "sent", JSON.stringify({ attachmentIds: body.attachmentIds || [], knowledgeSources: selectedSources, skillIds: selectedSkills, modelId: selectedModelId }), nowIso());
  if (body.attachmentIds?.length) {
    for (const attachmentId of body.attachmentIds) db.prepare("UPDATE chat_attachments SET message_id = ? WHERE id = ? AND session_id = ?").run(userMessageId, attachmentId, session.id);
  }
  const wechatIntent = detectWechatSendIntent(content);
  if (wechatIntent) {
    const assistantId = randomUUID();
    const actionResult = await runWechatSendAction(wechatIntent, userMessageId);
    restoreChatSessionIfMissing(session, content);
    db.prepare("INSERT INTO chat_messages (id, session_id, role, agent_id, content, message_type, status, metadata, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)")
      .run(assistantId, session.id, "assistant", body.agentId || session.agent_id, actionResult.content, "text", actionResult.status, JSON.stringify({
        userMessageId,
        knowledgeSources: selectedSources,
        skillIds: selectedSkills,
        modelId: selectedModelId,
        ...actionResult.metadata,
      }), nowIso());
    db.prepare("UPDATE chat_sessions SET updated_at = ?, title = CASE WHEN title = '新对话' THEN ? ELSE title END WHERE id = ?").run(nowIso(), autoTitle(content), session.id);
    return { ok: true, sessionId: session.id, userMessageId, assistant: db.prepare("SELECT * FROM chat_messages WHERE id = ?").get(assistantId) };
  }

  const imessageIntent = detectIMessageSendIntent(content);
  if (imessageIntent) {
    const assistantId = randomUUID();
    const actionResult = await runIMessageSendAction(imessageIntent, userMessageId);
    restoreChatSessionIfMissing(session, content);
    db.prepare("INSERT INTO chat_messages (id, session_id, role, agent_id, content, message_type, status, metadata, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)")
      .run(assistantId, session.id, "assistant", body.agentId || session.agent_id, actionResult.content, "text", actionResult.status, JSON.stringify({ userMessageId, knowledgeSources: selectedSources, skillIds: selectedSkills, modelId: selectedModelId, ...actionResult.metadata }), nowIso());
    db.prepare("UPDATE chat_sessions SET updated_at = ?, title = CASE WHEN title = '新对话' THEN ? ELSE title END WHERE id = ?").run(nowIso(), autoTitle(content), session.id);
    return { ok: true, sessionId: session.id, userMessageId, assistant: db.prepare("SELECT * FROM chat_messages WHERE id = ?").get(assistantId) };
  }
  const planMode = typeof body.planEnabled === "boolean" ? body.planEnabled : Boolean(session.plan_enabled);
  if (planMode) {
    const planId = randomUUID();
    const planSkills = ensureTaskExecutor(selectedSkills);
    const planAgentId = body.agentId || session.agent_id;
    const existingTaskMeta = findActiveTaskExecutorMeta(session.id);
    const taskMeta = existingTaskMeta || createTaskExecutorMeta(planAgentId);
    const generatedPlan = await runTaskExecutorPlanStep(taskMeta as Required<TaskExecutorMeta>, planAgentId, content, selectedSources, planSkills, selectedModelId, userMessageId, existingTaskMeta ? "continue" : "start");
    restoreChatSessionIfMissing(session, content);
    db.prepare("INSERT INTO chat_messages (id, session_id, role, agent_id, content, message_type, status, metadata, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)")
      .run(planId, session.id, "assistant", planAgentId, generatedPlan.content, "plan", generatedPlan.status, JSON.stringify({ userMessageId, knowledgeSources: selectedSources, skillIds: planSkills, modelId: selectedModelId, ...taskMeta, ...generatedPlan.metadata, planGateway: generatedPlan.gateway }), nowIso());
    db.prepare("UPDATE chat_sessions SET updated_at = ?, title = CASE WHEN title = '新对话' THEN ? ELSE title END WHERE id = ?").run(nowIso(), autoTitle(content), session.id);
    return { ok: true, sessionId: session.id, userMessageId, planMessageId: planId, plan: generatedPlan.content };
  }
  const answer = await dispatchChat(session.id, body.agentId || session.agent_id, content, userMessageId, {
    sources: selectedSources,
    skills: selectedSkills,
    mode: "chat",
    modelId: selectedModelId,
    timeoutMs: CHAT_SEND_GATEWAY_TIMEOUT_MS,
  });
  return { ok: true, sessionId: session.id, userMessageId, assistant: answer };
});

app.post("/api/chat/plan/:id/confirm", async (req) => {
  const id = (req.params as { id: string }).id;
  const plan = db.prepare("SELECT * FROM chat_messages WHERE id = ?").get(id) as { session_id: string; agent_id?: string; metadata: string; content: string; status: string } | undefined;
  if (!plan) return { ok: false, error: "not_found" };
  if (plan.status === "confirmed") return { ok: false, error: "already_confirmed" };
  const meta = JSON.parse(plan.metadata || "{}");
  const userMessage = db.prepare("SELECT * FROM chat_messages WHERE id = ?").get(meta.userMessageId) as { content: string } | undefined;
  const session = db.prepare("SELECT * FROM chat_sessions WHERE id = ?").get(plan.session_id) as ChatSessionRow | undefined;
  const sources = normalizeSources(meta.knowledgeSources ?? parseJsonArray(session?.knowledge_sources));
  const skills = ensureTaskExecutor(normalizeSkillIds(meta.skillIds ?? parseJsonArray(session?.skill_ids)));
  const modelId = meta.modelId || session?.model_id || "minimax-m3";
  const taskMeta = normalizeTaskExecutorMeta(meta);
  if (taskMeta.taskExecutor && (!taskMeta.planPath || !fs.existsSync(taskMeta.planPath))) {
    return { ok: false, error: "PLAN.md 尚未生成，需先完成 task-executor 提问和计划阶段。" };
  }
  const executionPrompt = taskMeta.taskExecutor
    ? buildTaskExecutorExecutionPrompt(taskMeta as Required<TaskExecutorMeta>, plan.agent_id || session?.agent_id || "worker", sources, skills, modelId, userMessage?.content || plan.content)
    : [
      "请使用 task-executor skill 执行以下已确认计划。",
      `执行代理：${plan.agent_id || session?.agent_id || "worker"}`,
      `知识源：${sources.join(", ")}`,
      `Skills：${skills.join(", ")}`,
      `模型配置：${modelId}`,
      "",
      "用户原始任务：",
      userMessage?.content || plan.content,
    ].join("\n");
  db.prepare("UPDATE chat_messages SET status = ? WHERE id = ?").run("confirmed", id);
  const answer = await dispatchChat(plan.session_id, plan.agent_id || session?.agent_id || "worker", executionPrompt, id, {
    sources,
    skills,
    mode: "confirmed_plan",
    modelId,
    timeoutMs: PLAN_EXECUTION_GATEWAY_TIMEOUT_MS,
    sessionKey: taskMeta.gatewaySessionKey,
    metadata: taskMeta.taskExecutor ? { ...taskMeta, taskExecutorPhase: "executing" } : undefined,
  });
  audit(db, "chat.plan.confirm", "chat_message", id, "normal", { sources, skills, modelId });
  return { ok: true, assistant: answer, execution: { sources, skills } };
});

