app.post("/api/development/projects/:id/messages", async (req, reply) => {
  ensureDevelopmentSeedData();
  const id = (req.params as { id: string }).id;
  if (!developmentProjectExists(id)) return reply.code(404).send({ ok: false, error: "development_project_not_found" });
  const body = req.body as { message?: string; subtaskId?: string; workPacketId?: string; actor?: string };
  const message = String(body.message || "").trim();
  if (!message) return reply.code(400).send({ ok: false, error: "empty_message" });
  const subtaskId = String(body.subtaskId || "");
  const subtask = subtaskId ? developmentSubtaskById(subtaskId) : null;
  if (subtaskId && (!subtask || subtask.projectId !== id)) return reply.code(409).send({ ok: false, error: "subtask_not_in_project" });
  developmentEvent({
    projectId: id,
    subtaskId: subtask?.id || null,
    eventType: "message",
    actor: String(body.actor || "owner"),
    severity: "info",
    message,
    payload: { workPacketId: body.workPacketId || "", source: "development_composer" },
  });
  if (subtask && isDevelopmentRunInstruction(message)) {
    const result = await runDevelopmentSubtask(subtask.id);
    const feedback = {
      intent: "run_current_subtask",
      eventType: "tool_result",
      actor: "main",
      severity: result.ok ? "info" : "warn",
      message: result.ok
        ? `已按用户指令调用 OpenClaw ${result.run?.activeAgentId || subtask.ownerAgentId || "main"} 代理推进当前子任务。`
        : `用户指令识别为执行意图，但当前子任务未能派发：${result.error || "unknown_error"}`,
      suggestedActions: result.ok ? ["查看最新代理事件", "等待后台结果", "按证据验收"] : ["检查当前子任务", "保持阻塞"],
    };
    developmentEvent({
      projectId: id,
      subtaskId: subtask.id,
      eventType: feedback.eventType,
      actor: feedback.actor,
      severity: feedback.severity,
      message: feedback.message,
      payload: { source: "development_composer_dispatch", intent: feedback.intent, suggestedActions: feedback.suggestedActions },
    });
    audit(db, "development.message.dispatch_current_subtask", "project", id, "normal", { subtaskId: subtask.id, source: "development_composer" });
    return { ok: true, feedback, run: result.ok ? result.run : null, detail: developmentProjectDetail(id) };
  }
  const feedback = developmentComposerFeedback({ message, projectId: id, subtask });
  if (feedback) {
    developmentEvent({
      projectId: id,
      subtaskId: subtask?.id || null,
      eventType: feedback.eventType,
      actor: feedback.actor,
      severity: feedback.severity,
      message: feedback.message,
      payload: {
        source: "development_composer_feedback",
        intent: feedback.intent,
        suggestedActions: feedback.suggestedActions,
      },
    });
  }
  audit(db, "development.message.create", "project", id, "normal", { subtaskId: subtask?.id || "", source: "development_composer" });
  return { ok: true, feedback, detail: developmentProjectDetail(id) };
});

