/**
 * Sprint1 Task1 — 自然语言目标入口。
 *
 * 用户输入一句话（"在 Chrome 里打开 Workbench演示笔记生成，截图存证"），
 * server调 v3 gateway LLM拆解为标准 ParsedGoal，自动入库。
 *
 * 设计要点：
 *1.走 v3 notes同一 gateway链路（agent gatewayCall + expectFinal），
 * 但 prompt version独立（goal-nlu-prompt-20260610a），不污染 knowledge-note harvest。
 *2. LLM失败 → fallback:true + minimal parsed，server仍能用 fallback goal 入库，
 * UI提示用户后续手填 successCriteria / subtasks。
 *3. 默认 agent 用 OPENCLAW_WORKBENCH_NOTE_GATEWAY_AGENT env（main），
 * sessionKey走 agent:<agent>:goal-nlu 与 knowledge-note隔离。
 *4. timeout4 min，与 v3 notes HTML阶段相当（LLM 真慢）。
 */
app.post("/api/development/goals/from-natural-language", async (req, reply) => {
 ensureDevelopmentSeedData();
 const query = req.query as { dryRun?: string };
 const body = req.body as { naturalLanguage?: string; projectId?: string; agentId?: string; sessionKey?: string; timeoutMs?: number };
 const text = String(body?.naturalLanguage || "").trim();
 const isDryRun = query.dryRun === "1" || query.dryRun === "true";

 if (!text) return reply.code(400).send({ ok: false, error: "naturalLanguage_required" });

 // dryRun模式：只调 LLM拆解，不入库、不写 events（避免 FK约束）。
 if (isDryRun) {
 const parseResult = await parseNaturalLanguageGoal(text, {
 agentId: body?.agentId,
 sessionKey: body?.sessionKey,
 timeoutMs: body?.timeoutMs,
 });
 return { ok: true, parse: parseResult, dryRun: true };
 }

 const projectId = String(body?.projectId || "").trim();
 if (!projectId) return reply.code(400).send({ ok: false, error: "projectId_required" });
 if (!developmentProjectExists(projectId)) return reply.code(404).send({ ok: false, error: "development_project_not_found" });

 const startedAt = Date.now();
 const parseResult: GoalNluParseResult = await parseNaturalLanguageGoal(text, {
 agentId: body?.agentId,
 sessionKey: body?.sessionKey,
 timeoutMs: body?.timeoutMs,
 });

 //审计：每次 NLU 调用都写入事件账本，方便后续 learning review
 developmentEvent({
 projectId,
 eventType: parseResult.ok ? "goal_nlu_parsed" : "goal_nlu_fallback",
 actor: "owner",
 severity: parseResult.ok ? "info" : "warn",
 message: parseResult.ok
 ? `自然语言目标已拆解：${parseResult.parsed?.title || text.slice(0,40)}`
 : `自然语言目标 fallback：${parseResult.error || "unknown"}`,
 payload: {
 sourceHash: parseResult.sourceHash,
 promptVersion: GOAL_NLU_PROMPT_VERSION,
 fallback: parseResult.fallback === true,
 durationMs: parseResult.durationMs,
 subtaskCount: parseResult.parsed?.subtasks?.length ||0,
 },
 });

 if (!parseResult.parsed) {
 return reply.code(502).send({
 ok: false,
 error: "goal_nlu_parse_failed_no_fallback",
 parse: parseResult,
 });
 }

 // 用 LLM拆解结果自动入库
 const goalBody = parsedGoalToGoalCreateBody(parseResult.parsed);
 const goal = createDevelopmentGoal(projectId, goalBody);
 if (!goal) return reply.code(500).send({ ok: false, error: "createDevelopmentGoal_failed_after_nlu" });

 // 把 LLM拆解出来的 subtasks / verification写入 goal evidence + next_action，
 //供后续 dispatcher 在 baseline派发时读取（不直接插 development_subtasks，
 // 因为 subtasks 表需要 baseline_id + sequence NOT NULL——baseline 由后续 planning阶段创建）。
 if (parseResult.parsed.subtasks.length >0) {
 try {
 const evidenceEntry = `[goal-nlu] subtasks: ${parseResult.parsed.subtasks.map((s) => `${s.key}=${s.title} (${s.kind})`).join(" | ")}`;
 const verificationEntry = `[goal-nlu] verification: kind=${parseResult.parsed.verification.kind}${parseResult.parsed.verification.targetApp ? ` target=${parseResult.parsed.verification.targetApp}` : ""}${parseResult.parsed.verification.expectedScreenshots ? ` shots=${parseResult.parsed.verification.expectedScreenshots}` : ""}`;
 const nextAction = `继续推进 subtask[${parseResult.parsed.subtasks[0].key}]：${parseResult.parsed.subtasks[0].title}。`;
 db.prepare(`
 UPDATE development_goals
 SET evidence = ?, next_action = ?, updated_at = ?
 WHERE id = ?
 `).run(
 JSON.stringify([evidenceEntry, verificationEntry]),
 nextAction,
 nowIso(),
 goal.id,
 );
 developmentEvent({
 projectId,
 eventType: "goal_subtasks_seeded",
 actor: "owner",
 severity: "info",
 message: `子任务列表已写入 goal evidence：${parseResult.parsed.subtasks.length} 个`,
 payload: {
 goalId: goal.id,
 subtaskCount: parseResult.parsed.subtasks.length,
 subtasks: parseResult.parsed.subtasks,
 verification: parseResult.parsed.verification,
 },
 });
 } catch (err) {
 app.log.warn({ err, goalId: goal.id }, "goal_nlu: failed to write subtasks to evidence");
 }
 }

 return {
 ok: true,
 parse: parseResult,
 goal,
 detail: developmentProjectDetail(projectId),
 durationMs: Date.now() - startedAt,
 };
});

app.patch("/api/development/goals/:goalId", async (req, reply) => {
  ensureDevelopmentSeedData();
  const goalId = (req.params as { goalId: string }).goalId;
  const goal = developmentGoalById(goalId);
  if (!goal) return reply.code(404).send({ ok: false, error: "development_goal_not_found" });
  const body = req.body as { title?: string; objective?: string; status?: string; autonomyLevel?: string; nextAction?: string; blockers?: unknown; successCriteria?: unknown; tokenBudget?: number | string | null; activeWorkPacketId?: string; activeSubtaskId?: string; autoRunEnabled?: boolean | number; heartbeatIntervalMinutes?: number | string | null; maxAutoTurns?: number | string | null; riskPolicy?: string; stopConditions?: unknown; metadata?: Record<string, unknown> | null };
  const now = nowIso();
  const status = body.status === undefined ? goal.status : String(body.status || goal.status);
  const heartbeatIntervalMinutes = body.heartbeatIntervalMinutes === undefined ? goal.heartbeatIntervalMinutes : Math.max(5, Math.min(240, Number(body.heartbeatIntervalMinutes || goal.heartbeatIntervalMinutes || 30)));
  const maxAutoTurns = body.maxAutoTurns === undefined ? goal.maxAutoTurns : Math.max(1, Math.min(12, Number(body.maxAutoTurns || goal.maxAutoTurns || 3)));
  // 合并 metadata: body.metadata 覆盖原 metadata 对应 key, 其它 key 保留
  const mergedMetadata: Record<string, unknown> = (() => {
    const base = (goal as { metadata?: string }).metadata ? JSON.parse((goal as { metadata?: string }).metadata || "{}") : {};
    if (body.metadata === null) return {};
    if (body.metadata === undefined) return base;
    return { ...base, ...body.metadata };
  })();
  db.prepare(`
    UPDATE development_goals
    SET title = ?, objective = ?, status = ?, autonomy_level = ?, active_work_packet_id = ?, active_subtask_id = ?, token_budget = ?, auto_run_enabled = ?, heartbeat_interval_minutes = ?, max_auto_turns = ?, risk_policy = ?, stop_conditions = ?, next_action = ?, blockers = ?, success_criteria = ?, metadata = ?, updated_at = ?, completed_at = CASE WHEN ? = 'completed' THEN COALESCE(completed_at, ?) ELSE completed_at END
    WHERE id = ?
  `).run(
    String(body.title ?? goal.title),
    String(body.objective ?? goal.objective),
    status,
    String(body.autonomyLevel ?? goal.autonomyLevel),
    String((body.activeWorkPacketId ?? goal.activeWorkPacketId) || "") || null,
    String((body.activeSubtaskId ?? goal.activeSubtaskId) || "") || null,
    body.tokenBudget === undefined ? goal.tokenBudget : body.tokenBudget === null || body.tokenBudget === "" ? null : Math.max(0, Number(body.tokenBudget || 0)),
    body.autoRunEnabled === undefined ? (goal.autoRunEnabled ? 1 : 0) : body.autoRunEnabled ? 1 : 0,
    heartbeatIntervalMinutes,
    maxAutoTurns,
    String(body.riskPolicy ?? goal.riskPolicy ?? "low_risk_only"),
    JSON.stringify(body.stopConditions === undefined ? goal.stopConditions : developmentStringList(body.stopConditions)),
    String(body.nextAction ?? goal.nextAction),
    JSON.stringify(body.blockers === undefined ? goal.blockers : developmentStringList(body.blockers)),
    JSON.stringify(body.successCriteria === undefined ? goal.successCriteria : developmentStringList(body.successCriteria)),
    JSON.stringify(mergedMetadata),
    now,
    status,
    now,
    goalId,
  );
  developmentEvent({ projectId: goal.projectId, eventType: "goal_updated", actor: "owner", severity: status === "blocked" ? "warn" : "info", message: `长期目标已更新：${String(body.title ?? goal.title)}`, payload: { goalId, status } });
  audit(db, "development.goal.update", "development_goal", goalId, status === "blocked" ? "high" : "normal", { projectId: goal.projectId, status });
  return { ok: true, goal: developmentGoalById(goalId), detail: developmentProjectDetail(goal.projectId) };
});

// Sprint1 Task4 (verify-tab) — owner ACCEPT/REJECT/REQUEST_REDO 决策端点
// 端点契约:POST /api/development/goals/<id>/verify/{accept|reject|redo}
//   * accept — goal.status → completed,completed_at 写入,事件 goal_verify_accepted
//   * reject — goal.status → blocked,blockers ← [reason],事件 goal_verify_rejected
//   * redo   — goal.status → running(若 paused/active),blockers 清空,事件 goal_verify_redo
// 设计:FE GoalVerifyTab 调这些端点,不在 GoalVerifyTab 组件里 PATCH ——
//       保持 verify 决策在 endpoint 集中,便于后续 audit_logs trace 与 owner 复盘。
app.post("/api/development/goals/:goalId/verify/accept", async (req, reply) => {
  ensureDevelopmentSeedData();
  const goalId = (req.params as { goalId: string }).goalId;
  const goal = developmentGoalById(goalId);
  if (!goal) return reply.code(404).send({ ok: false, error: "development_goal_not_found" });
  const body = (req.body || {}) as { note?: string; overrideReason?: string };
  const note = String(body.note || "").trim();
  const overrideReason = String(body.overrideReason || "").trim();
  const auditResult = developmentGoalCompletionAudit(goalId);
  if (!auditResult?.passed && !overrideReason) {
    const failed = auditResult?.checks.filter((check) => !check.passed).map((check) => `${check.label}: ${check.evidence}`).slice(0, 8) || ["目标完成审计未通过"];
    developmentEvent({
      projectId: goal.projectId,
      eventType: "goal_verify_rejected",
      actor: "goal_os",
      severity: "warn",
      message: `Verify ACCEPT 被 Goal OS 拦截：${failed[0] || "缺少验收证据"}`,
      payload: { goalId, completionAudit: auditResult, failed },
    });
    audit(db, "development.goal.verify_accept_blocked", "development_goal", goalId, "high", { projectId: goal.projectId, completionAudit: auditResult, failed });
    return reply.code(409).send({ ok: false, error: "completion_audit_required", message: "Verify ACCEPT 必须先通过 completion audit；如需人工 override，必须填写 overrideReason。", completionAudit: auditResult, failed });
  }
  const now = nowIso();
  db.prepare("UPDATE development_goals SET status = ?, completed_at = COALESCE(completed_at, ?), next_action = ?, blockers = ?, updated_at = ? WHERE id = ?")
    .run("completed", now, overrideReason ? `owner override 验收：${overrideReason.slice(0, 180)}` : note || "owner 已通过 Verify Tab 接受验收。", "[]", now, goalId);
  updateLatestGoalRunEvidence(goalId, {
    kind: overrideReason ? "verify_accept_override" : "verify_accept",
    generatedAt: now,
    completionAudit: auditResult,
    note,
    overrideReason,
    acceptedBy: "owner",
  }, "completed");
  developmentEvent({
    projectId: goal.projectId,
    eventType: "goal_verify_accepted",
    actor: "owner",
    severity: overrideReason ? "warn" : "info",
    message: overrideReason ? `Verify 人工 override 通过：${goal.title}` : `Verify 验收通过：${goal.title}`,
    payload: { goalId, note, overrideReason, completionAudit: auditResult },
  });
  audit(db, overrideReason ? "development.goal.verify_accept_override" : "development.goal.verify_accept", "development_goal", goalId, overrideReason ? "high" : "normal", { projectId: goal.projectId, note, overrideReason, completionAudit: auditResult });
  return { ok: true, goal: developmentGoalById(goalId), detail: developmentProjectDetail(goal.projectId), completionAudit: auditResult, overrideReason };
});

app.post("/api/development/goals/:goalId/verify/reject", async (req, reply) => {
  ensureDevelopmentSeedData();
  const goalId = (req.params as { goalId: string }).goalId;
  const goal = developmentGoalById(goalId);
  if (!goal) return reply.code(404).send({ ok: false, error: "development_goal_not_found" });
  const body = (req.body || {}) as { reason?: string };
  const reason = String(body.reason || "").trim();
  if (!reason) return reply.code(400).send({ ok: false, error: "reason_required", message: "REJECT 必须提供原因。" });
  const now = nowIso();
  const blockers = [...new Set([...goal.blockers, `verify_reject: ${reason}`])].slice(0, 12);
  db.prepare("UPDATE development_goals SET status = ?, blockers = ?, next_action = ?, updated_at = ? WHERE id = ?")
    .run("blocked", JSON.stringify(blockers), `owner 已拒绝验收：${reason.slice(0, 80)}`, now, goalId);
  developmentEvent({ projectId: goal.projectId, eventType: "goal_verify_rejected", actor: "owner", severity: "warn", message: `Verify 验收被拒：${goal.title} · ${reason.slice(0, 80)}`, payload: { goalId, reason } });
  audit(db, "development.goal.verify_reject", "development_goal", goalId, "high", { projectId: goal.projectId, reason });
  return { ok: true, goal: developmentGoalById(goalId), detail: developmentProjectDetail(goal.projectId) };
});

app.post("/api/development/goals/:goalId/verify/redo", async (req, reply) => {
  ensureDevelopmentSeedData();
  const goalId = (req.params as { goalId: string }).goalId;
  const goal = developmentGoalById(goalId);
  if (!goal) return reply.code(404).send({ ok: false, error: "development_goal_not_found" });
  const body = (req.body || {}) as { reason?: string };
  const reason = String(body.reason || "").trim();
  const now = nowIso();
  const nextStatus = goal.status === "completed" ? "blocked" : goal.status;
  const nextBlockers = reason ? [...new Set([...goal.blockers, `verify_redo: ${reason}`])].slice(0, 12) : goal.blockers;
  db.prepare("UPDATE development_goals SET status = ?, blockers = ?, next_action = ?, updated_at = ? WHERE id = ?")
    .run(nextStatus, JSON.stringify(nextBlockers), `owner 请求重做桌面验收：${reason.slice(0, 80) || "等待重新跑 evidence pack"}`, now, goalId);
  developmentEvent({ projectId: goal.projectId, eventType: "goal_verify_redo", actor: "owner", severity: "warn", message: `Verify 重做请求：${goal.title} · ${reason.slice(0, 80) || "未填原因"}`, payload: { goalId, reason, previousStatus: goal.status } });
  audit(db, "development.goal.verify_redo", "development_goal", goalId, "normal", { projectId: goal.projectId, reason, previousStatus: goal.status });
  return { ok: true, goal: developmentGoalById(goalId), detail: developmentProjectDetail(goal.projectId) };
});

