app.get("/api/development/scheduler/state", async (_req, reply) => {
  // 内存对象是 fast path；DB 是 ground truth（重启后唯一可信来源）。
  // 合并两者：DB 永远比内存新（哪怕在内存被 reset 后）。
  ensureDevelopmentSeedData();
  let dbRow: Record<string, unknown> | undefined;
  let persistedSnapshot: DevelopmentGoalAutoLoopState | null = null;
  try {
    dbRow = db.prepare("SELECT * FROM development_scheduler_state WHERE id = ?").get(DEVELOPMENT_SCHEDULER_STATE_ROW_ID) as Record<string, unknown> | undefined;
    if (dbRow) persistedSnapshot = developmentSchedulerRowToState(dbRow);
  } catch (err) {
    app.log.warn({ err }, "failed to read development_scheduler_state for /state route");
  }
  const inMemory = developmentGoalAutoLoopState;
  // 取每个字段的最新值：DB 行存在 -> 用 DB 的（更可信）；否则退化到内存
  const effective: DevelopmentGoalAutoLoopState = persistedSnapshot
 ? {
 running: inMemory.running, // running永远是当前进程的实时状态
 lastStartedAt: pickLatest(inMemory.lastStartedAt, persistedSnapshot.lastStartedAt),
 lastFinishedAt: pickLatest(inMemory.lastFinishedAt, persistedSnapshot.lastFinishedAt),
 lastError: inMemory.lastError || persistedSnapshot.lastError,
 targetGoalId: inMemory.targetGoalId || persistedSnapshot.targetGoalId,
 scannedGoals: Math.max(inMemory.scannedGoals, persistedSnapshot.scannedGoals),
 executedGoals: Math.max(inMemory.executedGoals, persistedSnapshot.executedGoals),
 skippedGoals: Math.max(inMemory.skippedGoals, persistedSnapshot.skippedGoals),
 recoveredRuns: Math.max(inMemory.recoveredRuns, persistedSnapshot.recoveredRuns),
 nextDueGoalId: persistedSnapshot.nextDueGoalId || inMemory.nextDueGoalId,
 nextDueAt: persistedSnapshot.nextDueAt || inMemory.nextDueAt,
 lastDecision: inMemory.lastDecision || persistedSnapshot.lastDecision,
 lastAutoTickAt: pickLatest(inMemory.lastAutoTickAt, persistedSnapshot.lastAutoTickAt),
 }
 : inMemory;
  const lastFinishedMs = Date.parse(effective.lastFinishedAt || "");
  const lastStartedMs = Date.parse(effective.lastStartedAt || "");
  const lastSeenMs = Number.isFinite(lastFinishedMs) ? lastFinishedMs : lastStartedMs;
  const staleSeconds = Number.isFinite(lastSeenMs) ? Math.max(0, Math.floor((Date.now() - lastSeenMs) / 1000)) : -1;
  const processBootId = String(dbRow?.process_id || developmentSchedulerProcessBootId);
  const processBootAt = String(dbRow?.process_started_at || "");
  const processBootAgeSeconds = processBootAt ? Math.max(0, Math.floor((Date.now() - Date.parse(processBootAt)) / 1000)) : -1;
  // 当前进程（route 调用者）的 boot 信息 —— 用于判断 server 是否刚被重启过
  // 若 processBootId !== currentProcessBootId，说明 DB 行的状态来自上一次进程（我们刚 boot）
  const currentProcessBootId = developmentSchedulerProcessBootId;
  const currentProcessStartedAt = nowIso(); // 近似：route 调用时刻；用户可结合 serverStartedAt 判断
  // 重启信号 = 本进程启动时检测到的（DB 来自不同进程）
  // 这是"快照"，不会被后续 load → claim 更新覆盖。
  const wasRestartedAtBoot = developmentSchedulerRestartedAtBoot;
  const previousProcessIdAtBoot = developmentSchedulerPreviousProcessIdAtBoot;
  // 重新计算 status（保持与 developmentGoalSchedulerSnapshot 同步语义）
  const status = effective.running
    ? "running"
    : effective.lastError
      ? "error"
      : staleSeconds >= 0 && staleSeconds <= 150
        ? "online"
        : "idle";
  // 同时算"DB 行是否表明上次进程在跑时被打断"
  const previouslyRunning = Number(dbRow?.running || 0) === 1 && processBootId !== developmentSchedulerProcessBootId;
  return {
    ok: true,
    scheduler: {
      ...effective,
      status,
      staleSeconds,
      source: persistedSnapshot ? "db+memory" : "memory_only",
      persisted: {
        rowExists: Boolean(dbRow),
        lastUpdatedAt: String(dbRow?.updated_at || ""),
        processBootId,
        processBootAt,
        processBootAgeSeconds,
        previouslyRunning,
        wasRestartedAtBoot,
        previousProcessIdAtBoot,
        currentProcessBootId,
        currentProcessStartedAt,
        dirty: developmentSchedulerDirty,
        lastPersistAt: developmentSchedulerLastPersistAt ? new Date(developmentSchedulerLastPersistAt).toISOString() : "",
      },
      counters: {
        scanned: effective.scannedGoals,
 executed: effective.executedGoals,
 skipped: effective.skippedGoals,
 recovered: effective.recoveredRuns,
 },
 },
 };
});

// ─── Observability: heartbeat / token budget / event flow ───────────────────
//12 小时运行需要可观测的运行指标 —— 这一组端点返回稳定的 JSON shape，
//供主控 / dashboard /报警脚本实时读取。
//
// shape约束（不允许裸500；任何异常都返回结构化错误）：
// {
// ok: true,
// service: { uptimeMs, startedAt },
// goals: { activeCount, lastHeartbeatAt, nextHeartbeatAt, heartbeatCountTotal, turnCountTotal },
// tokenBudget:{ totalBudget, used, remaining, usageRatio },
// events: { writtenLastHour, writtenLastMinute },
// scheduler: { running, lastTickAt, lastFinishedAt, lastDecision, lastError, status, scannedGoals, executedGoals, skippedGoals, recoveredRuns },
// staleRuns: { count, thresholdMs, thresholdSeconds },
// process: { pid, bootId, startedAt },
// generatedAt: string
// }
type ObservabilityHeartbeatResponse = {
 ok: boolean;
 error?: string;
 service?: { uptimeMs: number; startedAt: string };
 goals?: {
 activeCount: number;
 lastHeartbeatAt: string;
 nextHeartbeatAt: string;
 heartbeatCountTotal: number;
 turnCountTotal: number;
 };
 tokenBudget?: {
 totalBudget: number;
 used: number;
 remaining: number | null;
 usageRatio: number;
 overBudgetGoalCount: number;
 };
 events?: {
 writtenLastHour: number;
 writtenLastMinute: number;
 };
 scheduler?: {
 running: boolean;
 lastTickAt: string;
 lastStartedAt: string;
 lastFinishedAt: string;
 lastDecision: string;
 lastError: string;
 status: "running" | "online" | "idle" | "error" | "scheduler_not_started";
 scannedGoals: number;
 executedGoals: number;
 skippedGoals: number;
 recoveredRuns: number;
 };
 staleRuns?: { count: number; thresholdMs: number; thresholdSeconds: number };
 process?: { pid: number; bootId: string; startedAt: string };
 generatedAt?: string;
};

app.get("/api/development/observability/heartbeat", async (req, reply) => {
 // 需要 workbench session cookie —— 未授权返回结构化401
 if (!requireAuth(db, req, reply)) return;
 const nowMs = Date.now();
 const generatedAt = nowIso();
 try {
 ensureDevelopmentSeedData();

 // ---- goals:聚合指标 ----
 const goalsRow = db.prepare(`
 SELECT
 COUNT(*) AS activeCount,
 COALESCE(MAX(last_heartbeat_at), '') AS lastHeartbeatAt,
 COALESCE(MIN(NULLIF(next_heartbeat_at, '')), '') AS nextHeartbeatAt,
 COALESCE(SUM(heartbeat_count),0) AS heartbeatCountTotal,
 COALESCE(SUM(turn_count),0) AS turnCountTotal
 FROM development_goals
 WHERE status IN ('active', 'running', 'blocked')
 `).get() as { activeCount?: number; lastHeartbeatAt?: string; nextHeartbeatAt?: string; heartbeatCountTotal?: number; turnCountTotal?: number } | undefined;

 // ---- token budget:聚合总预算 / 已使用 / 超 budget 的目标数 ----
 const tokenRow = db.prepare(`
 SELECT
 COALESCE(SUM(CASE WHEN token_budget IS NULL OR token_budget =0 THEN 0 ELSE token_budget END),0) AS totalBudget,
 COALESCE(SUM(COALESCE(tokens_used,0)),0) AS used,
 COALESCE(SUM(CASE WHEN token_budget IS NOT NULL AND token_budget >0 AND COALESCE(tokens_used,0) >= token_budget THEN 1 ELSE 0 END),0) AS overBudgetGoalCount
 FROM development_goals
 WHERE status IN ('active', 'running', 'blocked')
 `).get() as { totalBudget?: number; used?: number; overBudgetGoalCount?: number } | undefined;
 const totalBudget = Number(tokenRow?.totalBudget ||0);
 const tokensUsed = Number(tokenRow?.used ||0);
 const usageRatio = totalBudget >0 ? Math.round((tokensUsed / totalBudget) *10000) /10000 :0;
 const remaining = totalBudget >0 ? Math.max(0, totalBudget - tokensUsed) : null;

 // ---- events:1 小时 /1 分钟窗口 ----
 const hourAgoIso = new Date(nowMs -60 *60 *1000).toISOString();
 const minuteAgoIso = new Date(nowMs -60 *1000).toISOString();
 const eventsLastHour = (db.prepare(`
 SELECT COUNT(*) AS count FROM development_run_events WHERE created_at >= ?
 `).get(hourAgoIso) as { count?: number })?.count ||0;
 const eventsLastMinute = (db.prepare(`
 SELECT COUNT(*) AS count FROM development_run_events WHERE created_at >= ?
 `).get(minuteAgoIso) as { count?: number })?.count ||0;

 // ---- scheduler:从 DB 行 +内存合并 ----
 let dbRow: Record<string, unknown> | undefined;
 let persistedSnapshot: DevelopmentGoalAutoLoopState | null = null;
 try {
 dbRow = db.prepare("SELECT * FROM development_scheduler_state WHERE id = ?").get(DEVELOPMENT_SCHEDULER_STATE_ROW_ID) as Record<string, unknown> | undefined;
 if (dbRow) persistedSnapshot = developmentSchedulerRowToState(dbRow);
 } catch (schedErr) {
 app.log.warn({ err: schedErr }, "observability/heartbeat: failed to read development_scheduler_state");
 }
 const inMemory = developmentGoalAutoLoopState;
 const merged: DevelopmentGoalAutoLoopState = persistedSnapshot
 ? {
 running: inMemory.running,
 lastStartedAt: pickLatest(inMemory.lastStartedAt, persistedSnapshot.lastStartedAt),
 lastFinishedAt: pickLatest(inMemory.lastFinishedAt, persistedSnapshot.lastFinishedAt),
 lastError: inMemory.lastError || persistedSnapshot.lastError,
 targetGoalId: inMemory.targetGoalId || persistedSnapshot.targetGoalId,
 scannedGoals: Math.max(inMemory.scannedGoals, persistedSnapshot.scannedGoals),
 executedGoals: Math.max(inMemory.executedGoals, persistedSnapshot.executedGoals),
 skippedGoals: Math.max(inMemory.skippedGoals, persistedSnapshot.skippedGoals),
 recoveredRuns: Math.max(inMemory.recoveredRuns, persistedSnapshot.recoveredRuns),
 nextDueGoalId: persistedSnapshot.nextDueGoalId || inMemory.nextDueGoalId,
 nextDueAt: persistedSnapshot.nextDueAt || inMemory.nextDueAt,
 lastDecision: inMemory.lastDecision || persistedSnapshot.lastDecision,
 lastAutoTickAt: pickLatest(inMemory.lastAutoTickAt, persistedSnapshot.lastAutoTickAt),
 }
 : inMemory;
 const lastTickMs = Date.parse(merged.lastAutoTickAt || merged.lastStartedAt || "");
 const tickStaleSeconds = Number.isFinite(lastTickMs) ? Math.max(0, Math.floor((nowMs - lastTickMs) /1000)) : -1;
 const schedulerStatus: ObservabilityHeartbeatResponse["scheduler"] extends infer T
 ? T extends { status?: infer S } ? S : never
 : never = merged.running
 ? "running"
 : merged.lastError
 ? "error"
 : tickStaleSeconds >=0 && tickStaleSeconds <=150
 ? "online"
 : tickStaleSeconds <0
 ? "scheduler_not_started"
 : "idle";

 // ---- stale runs:超过30 分钟无新事件 ----
 const staleRow = (db.prepare(`
 SELECT COUNT(*) AS count FROM development_runs
 WHERE status IN ('running', 'dispatched')
 AND started_at <= ?
 `).get(new Date(nowMs - DEVELOPMENT_RUN_STALE_MS).toISOString()) as { count?: number })?.count ||0;

 const response: ObservabilityHeartbeatResponse = {
 ok: true,
 service: { uptimeMs: nowMs - SERVICE_START_TIME_MS, startedAt: SERVICE_START_TIME_ISO },
 goals: {
 activeCount: Number(goalsRow?.activeCount ||0),
 lastHeartbeatAt: String(goalsRow?.lastHeartbeatAt || ""),
 nextHeartbeatAt: String(goalsRow?.nextHeartbeatAt || ""),
 heartbeatCountTotal: Number(goalsRow?.heartbeatCountTotal ||0),
 turnCountTotal: Number(goalsRow?.turnCountTotal ||0),
 },
 tokenBudget: {
 totalBudget,
 used: tokensUsed,
 remaining,
 usageRatio,
 overBudgetGoalCount: Number(tokenRow?.overBudgetGoalCount ||0),
 },
 events: {
 writtenLastHour: Number(eventsLastHour),
 writtenLastMinute: Number(eventsLastMinute),
 },
 scheduler: {
 running: merged.running,
 lastTickAt: merged.lastAutoTickAt || merged.lastStartedAt || "",
 lastStartedAt: merged.lastStartedAt,
 lastFinishedAt: merged.lastFinishedAt,
 lastDecision: merged.lastDecision,
 lastError: merged.lastError,
 status: schedulerStatus as "running" | "online" | "idle" | "error" | "scheduler_not_started",
 scannedGoals: merged.scannedGoals,
 executedGoals: merged.executedGoals,
 skippedGoals: merged.skippedGoals,
 recoveredRuns: merged.recoveredRuns,
 },
 staleRuns: {
 count: Number(staleRow),
 thresholdMs: DEVELOPMENT_RUN_STALE_MS,
 thresholdSeconds: Math.floor(DEVELOPMENT_RUN_STALE_MS /1000),
 },
 process: {
 pid: process.pid,
 bootId: developmentSchedulerProcessBootId,
 startedAt: SERVICE_START_TIME_ISO,
 },
 generatedAt,
 };
 return response;
 } catch (err) {
 app.log.warn({ err }, "observability/heartbeat route failed");
 const message = err instanceof Error ? err.message : String(err);
 reply.code(500);
 return { ok: false, error: "observability_heartbeat_failed", detail: sanitizePublicError(message), generatedAt };
 }
});

