app.post("/api/development/goals/:goalId/dispatch-recovery", async (req, reply) => {
  ensureDevelopmentSeedData();
  const goalId = (req.params as { goalId: string }).goalId;
  const body = req.body as { reason?: string; dryRun?: boolean; action?: string };
  if (String(body.action || "") === "resolve") {
    const goal = developmentGoalById(goalId);
    if (!goal) return reply.code(404).send({ ok: false, error: "development_goal_not_found" });
    const health = await refreshLiveGatewayHealth({
      force: true,
      timeoutMs: 15_000,
      source: "development_goal_dispatch_recovery",
    });
    if (!health.ok) {
      developmentEvent({
        projectId: goal.projectId,
        eventType: "goal_dispatch_recovery",
        actor: "main",
        severity: "warn",
        message: `派发恢复验证未通过：${health.status} · ${health.error || "Gateway health check failed"}`,
        payload: { goalId, action: "resolve", health },
      });
      audit(db, "development.goal.dispatch_recovery_verify_failed", "development_goal", goalId, "high", {
        projectId: goal.projectId,
        gatewayStatus: health.status,
        gatewayError: health.error,
      });
      return {
        ok: true,
        resolved: false,
        health,
        goal: developmentGoalById(goalId),
        detail: developmentProjectDetail(goal.projectId),
        timeline: developmentGoalTimeline(goalId),
        snapshot: developmentGoalOperatingSnapshot(goalId),
      };
    }
    const resolution = resolveDevelopmentGoalDispatchFailure(goalId, health);
    if (!resolution) return reply.code(404).send({ ok: false, error: "development_goal_not_found" });
    return {
      ok: true,
      resolved: true,
      dispatchResolution: resolution,
      health,
      goal: developmentGoalById(goalId),
      detail: developmentProjectDetail(goal.projectId),
      timeline: developmentGoalTimeline(goalId),
      snapshot: developmentGoalOperatingSnapshot(goalId),
    };
  }
  const recovery = buildDevelopmentGoalDispatchRecovery(goalId, String(body.reason || ""));
  if (!recovery) return reply.code(404).send({ ok: false, error: "development_goal_not_found" });
  if (body.dryRun) {
    return {
      ok: true,
      dryRun: true,
      dispatchRecovery: recovery,
      goal: developmentGoalById(goalId),
      detail: developmentProjectDetail(recovery.projectId),
      timeline: developmentGoalTimeline(goalId),
    };
  }
  const artifact = persistDevelopmentGoalArtifact({
    projectId: recovery.projectId,
    goalId,
    artifactType: "goal_dispatch_recovery",
    title: "Goal Dispatch Recovery Prompt",
    markdown: recovery.prompt,
    evidenceLevel: "goal_recovery",
    metadata: { generatedAt: recovery.generatedAt, reason: recovery.reason },
  });
  const goal = developmentGoalById(goalId);
  const currentEvidence = goal?.evidence || [];
  // restore 路径拆解：默认只做诊断（生成 prompt + artifact + 写 warn event + 追加 evidence），
  // 不再强改 goal.status / goal.blockers —— 那些副作用由 action="resolve" 路径负责。
  // 旧客户端若仍依赖"restore 后 goal 被强写回 blocked"，可显式传 action: "force_block"。
  const forceBlock = String(body.action || "") === "force_block";
  if (forceBlock) {
    const nextBlockers = [...new Set([...(goal?.blockers || []), "OpenClaw 代理派发失败"])].slice(0, 12);
    db.prepare("UPDATE development_goals SET status = ?, blockers = ?, next_action = ?, evidence = ?, updated_at = ? WHERE id = ?")
      .run(
        "blocked",
        JSON.stringify(nextBlockers),
        recovery.nextAction,
        developmentGoalEvidence(currentEvidence, `${recovery.generatedAt} · 派发恢复(force_block) · ${recovery.reason}`),
        nowIso(),
        goalId,
      );
  } else {
    // 诊断模式：保留 goal 当前状态，只追加 evidence 一行（可追溯）
    db.prepare("UPDATE development_goals SET evidence = ?, updated_at = ? WHERE id = ?")
      .run(
        developmentGoalEvidence(currentEvidence, `${recovery.generatedAt} · 派发恢复(诊断) · ${recovery.reason}`),
        nowIso(),
        goalId,
      );
  }
  developmentEvent({
    projectId: recovery.projectId,
    subtaskId: recovery.pointer.subtaskId || null,
    eventType: "goal_dispatch_recovery",
    actor: "main",
    severity: "warn",
    message: `${recovery.summary}${forceBlock ? " [force_block]" : " [诊断]"}`,
    payload: {
      goalId,
      artifactId: artifact.id,
      artifactPath: artifact.path,
      reason: recovery.reason,
      nextAction: recovery.nextAction,
      pointer: recovery.pointer,
      prompt: recovery.prompt,
      mode: forceBlock ? "force_block" : "diagnose",
    },
  });
  audit(db, "development.goal.dispatch_recovery", "development_goal", goalId, forceBlock ? "high" : "normal", {
    projectId: recovery.projectId,
    reason: recovery.reason,
    subtaskId: recovery.pointer.subtaskId,
  });
  return {
    ok: true,
    dispatchRecovery: { ...recovery, artifact },
    mode: forceBlock ? "force_block" : "diagnose",
    goal: developmentGoalById(goalId),
    detail: developmentProjectDetail(recovery.projectId),
    timeline: developmentGoalTimeline(goalId),
  };
});

