app.post("/api/development/goals/:goalId/continuation-contract", async (req, reply) => {
  ensureDevelopmentSeedData();
  const goalId = (req.params as { goalId: string }).goalId;
  const body = req.body as { action?: string; activeAgentId?: string; agentId?: string };
  const action = String(body.action || "stage");
  const contract = developmentGoalContinuationContract(goalId);
  if (!contract) return reply.code(404).send({ ok: false, error: "development_goal_not_found" });
  const artifact = persistDevelopmentGoalArtifact({
    projectId: contract.projectId,
    goalId,
    artifactType: "goal_continuation_contract",
    title: "Goal Continuation Contract",
    markdown: contract.markdown,
    evidenceLevel: "goal_handoff",
    metadata: { generatedAt: contract.generatedAt, readinessScore: contract.readinessScore, readinessLabel: contract.readinessLabel, action },
  });
  const severity = contract.blockers.length || contract.requiredEvidence.length ? "warn" : "info";
  developmentEvent({
    projectId: contract.projectId,
    eventType: "goal_continuation_contract",
    actor: "main",
    severity,
    message: `目标续跑契约：${contract.readinessLabel} · ${contract.readinessScore}/100 · ${contract.nextCommand}`,
    payload: {
      goalId,
      action,
      artifactId: artifact.id,
      artifactPath: artifact.path,
      readinessScore: contract.readinessScore,
      readinessLabel: contract.readinessLabel,
      nextCommand: contract.nextCommand,
      pointer: contract.pointer,
      requiredEvidence: contract.requiredEvidence,
      blockers: contract.blockers,
    },
  });
  audit(db, "development.goal.continuation_contract", "development_goal", goalId, severity === "warn" ? "high" : "normal", {
    projectId: contract.projectId,
    action,
    readinessScore: contract.readinessScore,
    readinessLabel: contract.readinessLabel,
  });
  if (action === "continue") {
    const result = await runDevelopmentGoalAction(goalId, { action: "continue", message: contract.nextCommand, activeAgentId: body.activeAgentId || body.agentId });
    return {
      ok: result.ok,
      continuationContract: { ...contract, artifact },
      goal: developmentGoalById(goalId),
      detail: developmentProjectDetail(contract.projectId),
      run: result.ok ? result.run : null,
      feedback: result.ok ? null : result.error,
    };
  }
  return { ok: true, continuationContract: { ...contract, artifact }, detail: developmentProjectDetail(contract.projectId), goal: developmentGoalById(goalId) };
});

