app.patch("/api/agent-workbench/value-metrics", async (req, reply) => {
  const body = req.body as { metrics?: unknown };
  if (!Array.isArray(body.metrics)) return reply.code(400).send({ ok: false, error: "metrics_required" });
  const metrics = normalizeValueMetricConfig(body.metrics);
  fs.mkdirSync(path.dirname(VALUE_METRICS_CONFIG_PATH), { recursive: true });
  fs.writeFileSync(VALUE_METRICS_CONFIG_PATH, JSON.stringify({ metrics }, null, 2) + "\n", "utf8");
  audit(db, "agent_workbench.value_metrics.update", "config", VALUE_METRICS_CONFIG_PATH, "normal", { metricIds: metrics.map((metric) => metric.id) });
  return { ok: true, path: VALUE_METRICS_CONFIG_PATH, metrics };
});

app.post("/api/agent-workbench/actions", async (req) => {
  const body = req.body as { action?: string; workItemId?: string; agentId?: string; message?: string };
  const action = String(body.action || "").trim();
  const workItemId = String(body.workItemId || "").trim();
  const agentId = String(body.agentId || "").trim() || undefined;
  const item = buildWorkbenchTaskItems().find((row) => row.id === workItemId) || null;
  if (!action) return { ok: false, error: "action_required" };
  const lowRiskActions = new Set(["diagnose", "summarize", "draft", "sync", "preview", "continue_waiting", "recover_prompt"]);
  if (!lowRiskActions.has(action)) {
    const approvalId = randomUUID();
    db.prepare("INSERT INTO approvals (id, task_id, action, status, requested_at, details) VALUES (?, ?, ?, ?, ?, ?)")
      .run(approvalId, item?.dbTaskId || null, action, "pending", nowIso(), JSON.stringify({ workItemId, agentId, message: body.message || "", reason: "high_autonomy_boundary" }));
    workbenchEvent({
      workItemId,
      sourceType: "agent-workbench",
      sourceId: approvalId,
      agentId: agentId || item?.agentId,
      eventType: "approval_requested",
      severity: "warn",
      message: `高风险动作 ${action} 已进入审批队列`,
      payload: { action, workItemId },
    });
    audit(db, "agent_workbench.approval_requested", "work_item", workItemId || null, "high", { action, approvalId });
    return { ok: true, requiresApproval: true, approvalId };
  }
  const summary = buildLowRiskAutonomyResult(action, item, body.message || "");
  workbenchEvent({
    workItemId,
    sourceType: "agent-workbench",
    sourceId: action,
    agentId: agentId || item?.agentId,
    eventType: `autonomy_${action}`,
    severity: action === "recover_prompt" ? "warn" : "info",
    message: summary.message,
    payload: summary,
  });
  audit(db, `agent_workbench.${action}`, "work_item", workItemId || null, "low", summary);
  return { ok: true, action, result: summary };
});

app.get("/api/tasks/workbench/detail", async (req) => {
  const query = req.query as { itemId?: string; taskPath?: string };
  const itemId = String(query.itemId || "");
  const taskPath = String(query.taskPath || "");
  if (!itemId && !taskPath) return { ok: true, item: null, planContent: "", resultContent: "", timeline: [] };
  const item = buildWorkbenchTaskItems().find((row) => row.id === itemId || Boolean(taskPath && row.taskPath === taskPath)) || null;
  return {
    ok: true,
    item,
    planContent: item?.planPath ? readTextFile(item.planPath, 80_000) : "",
    resultContent: item?.resultPath ? readTextFile(item.resultPath, 80_000) : "",
    timeline: item ? workbenchTaskTimeline(item) : [],
    events: item ? workbenchEventsForItem(item.id, 80) : [],
    artifacts: item ? dedupeArtifacts(item.artifacts || []) : [],
    links: item ? workbenchLinksForItem(item.id) : [],
  };
});

app.post("/api/tasks", async (req) => {
  const body = req.body as {
    title?: string;
    description?: string;
    agentId?: string;
    riskLevel?: string;
    sessionKey?: string;
    priority?: string;
    parentTaskId?: string;
    projectId?: string;
    tags?: string[];
    dependencies?: string[];
    input?: unknown;
  };
  const id = randomUUID();
  const agentId = body.agentId || "worker";
  const risk = body.riskLevel || "normal";
  const priority = body.priority || "P2";
  const title = String(body.title || "Untitled task").slice(0, 160);
  const description = String(body.description || "").slice(0, 8000);
  const taskMeta = createTaskExecutorMeta(agentId);
  const sessionKey = body.sessionKey || taskMeta.gatewaySessionKey || `agent:${agentId}:main`;
  const requiresApproval = risk === "high";
  const input = {
    ...(body.input && typeof body.input === "object" && !Array.isArray(body.input) ? body.input as Record<string, unknown> : {}),
    taskExecutor: true,
    taskId: taskMeta.taskId,
    taskPath: taskMeta.taskPath,
    planPath: taskMeta.planPath,
    resultPath: taskMeta.resultPath,
    gatewaySessionKey: sessionKey,
    workspace: taskMeta.workspace,
  };
  db.prepare("INSERT INTO tasks (id, title, description, agent_id, status, risk_level, session_key, approval_status, created_at, updated_at, priority, parent_task_id, project_id, tags, input) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
    .run(id, title, description, agentId, requiresApproval ? "pending_approval" : "queued", risk, sessionKey, requiresApproval ? "pending" : "not_required", nowIso(), nowIso(), priority, body.parentTaskId || null, body.projectId || null, JSON.stringify(body.tags || []), JSON.stringify(input));
  for (const dependency of body.dependencies || []) {
    if (dependency && dependency !== id) db.prepare("INSERT OR IGNORE INTO task_dependencies (task_id, depends_on_task_id, created_at) VALUES (?, ?, ?)").run(id, dependency, nowIso());
  }
  taskEvent(id, "created", "owner", `Task created for ${agentId}`, { priority, risk, dependencies: body.dependencies || [], taskPath: taskMeta.taskPath });
  upsertWorkbenchLink(workbenchTaskKey(agentId, taskMeta.taskId), "sqlite_task", id, { agentId, priority, risk });
  upsertWorkbenchLink(workbenchTaskKey(agentId, taskMeta.taskId), "task_path", taskMeta.taskPath, { planPath: taskMeta.planPath, resultPath: taskMeta.resultPath });
  upsertWorkbenchLink(workbenchTaskKey(agentId, taskMeta.taskId), "gateway_session", sessionKey, { agentId });
  audit(db, "task.create", "task", id, risk, { agentId, title });
  if (!requiresApproval) void dispatchWorkbenchTask(id, taskMeta, agentId, sessionKey, title, description, priority, risk);
  const task = db.prepare("SELECT * FROM tasks WHERE id = ?").get(id);
  const workbenchItem = buildWorkbenchTaskItems().find((item) => item.dbTaskId === id || item.id === workbenchTaskKey(agentId, taskMeta.taskId)) || null;
  return { ok: true, task, workbenchItem };
});

