app.post("/api/tasks/:id/:action", async (req) => {
  const params = req.params as { id: string; action: string };
  if (!["pause", "retry", "terminate", "inject"].includes(params.action)) return { ok: false, error: "unsupported_action" };
  const task = db.prepare("SELECT * FROM tasks WHERE id = ?").get(params.id) as { session_key?: string } | undefined;
  const approvalId = randomUUID();
  db.prepare("INSERT INTO approvals (id, task_id, action, status, requested_at, details) VALUES (?, ?, ?, ?, ?, ?)")
    .run(approvalId, params.id, params.action, "pending", nowIso(), JSON.stringify({ sessionKey: task?.session_key }));
  if (params.action === "pause") db.prepare("UPDATE tasks SET status = ?, updated_at = ? WHERE id = ?").run("paused", nowIso(), params.id);
  taskEvent(params.id, "intervention_requested", "owner", `${params.action} requested`, {});
  audit(db, "intervention.request", "approval", approvalId, "high", { taskId: params.id, action: params.action });
  notify("warn", "Intervention pending", `${params.action} 需要人工审批`, "approvals");
  return { ok: true, approval: db.prepare("SELECT * FROM approvals WHERE id = ?").get(approvalId) };
});

app.post("/api/interventions", async (req) => {
  const body = req.body as { taskId?: string; action?: string; sessionKey?: string; message?: string };
  const id = randomUUID();
  db.prepare("INSERT INTO approvals (id, task_id, action, status, requested_at, details) VALUES (?, ?, ?, ?, ?, ?)")
    .run(id, body.taskId || null, body.action || "inject", "pending", nowIso(), JSON.stringify({ sessionKey: body.sessionKey, message: body.message }));
  if (body.taskId) {
    db.prepare("UPDATE tasks SET status = CASE WHEN ? = 'pause' THEN 'paused' ELSE status END, updated_at = ? WHERE id = ?").run(body.action || "inject", nowIso(), body.taskId);
    taskEvent(body.taskId, "intervention_requested", "owner", `${body.action || "inject"} requested`, body);
  }
  audit(db, "intervention.request", "approval", id, "high", body);
  notify("warn", "Intervention pending", `${body.action || "inject"} 需要人工审批`, "approvals");
  return { ok: true, approval: db.prepare("SELECT * FROM approvals WHERE id = ?").get(id) };
});

app.post("/api/approvals/:id/resolve", async (req) => {
  const id = (req.params as { id: string }).id;
  const body = req.body as { decision?: "approved" | "rejected" };
  const approval = db.prepare("SELECT * FROM approvals WHERE id = ?").get(id) as { details: string; action: string; task_id?: string } | undefined;
  if (!approval) return { ok: false, error: "not_found" };
  const details = JSON.parse(approval.details || "{}");
  let execution: unknown = null;
  if (body.decision === "approved") {
    if (["abort", "terminate", "pause"].includes(approval.action)) execution = await gatewayCall("chat.abort", { sessionKey: details.sessionKey || "agent:worker:main" });
    if (approval.action === "inject") execution = await gatewayCall("chat.send", { sessionKey: details.sessionKey || "agent:worker:main", message: details.message || "Human intervention approved." });
    if (approval.action === "wechat_send_message" && details.source === "computer_use_wechat_prepare") {
      if (!details.recipientName || !details.message) {
        execution = { ok: false, error: "wechat_approval_payload_incomplete", safeBehavior: "message_not_sent" };
      } else {
        execution = computerUseWechatSendApproved(String(details.recipientName), String(details.message), id);
      }
    }
    if (approval.action === "retry" && approval.task_id) {
      const task = db.prepare("SELECT * FROM tasks WHERE id = ?").get(approval.task_id) as { agent_id: string; session_key?: string; description: string; title: string } | undefined;
      if (task) execution = await gatewayCall("agent", { agentId: task.agent_id, sessionKey: task.session_key || `agent:${task.agent_id}:main`, message: task.description || task.title, idempotencyKey: `${approval.task_id}:retry:${id}` });
    }
  }
  db.prepare("UPDATE approvals SET status = ?, resolved_at = ? WHERE id = ?").run(body.decision || "rejected", nowIso(), id);
  if (approval.task_id) {
    const nextStatus = body.decision === "approved" && approval.action === "retry" ? "running" : body.decision === "approved" && ["abort", "terminate"].includes(approval.action) ? "failed" : undefined;
    if (nextStatus) db.prepare("UPDATE tasks SET status = ?, updated_at = ? WHERE id = ?").run(nextStatus, nowIso(), approval.task_id);
    taskEvent(approval.task_id, "approval_resolved", "owner", `${approval.action} ${body.decision || "rejected"}`, { execution });
  }
  audit(db, "approval.resolve", "approval", id, "high", { decision: body.decision, execution });
  return { ok: true, execution };
});

