app.get("/api/knowledge/search", async (req) => {
  const q = String((req.query as { q?: string }).q || "");
  // T6 Phase 2 / R5 search-source-normalize rework: route through normalizeSources so the
  // chat / research / global-search contract holds here too. No `sources` query -> DEFAULT
  // ["njx-knowledge"]. `sources=all` -> expands to the full 5 source set before reaching
  // searchKnowledge. `sources=memory,wiki` / invalid tokens pass through normalizeSources'
  // allowed-set filter; an all-invalid input falls back to ["njx-knowledge"].
  const sourceParam = String((req.query as { sources?: string }).sources || "");
  const sources = normalizeSources(sourceParam ? sourceParam.split(",") : []);
  return { ok: true, query: q, results: await searchKnowledge(q, sources) };
});

