app.get("/api/knowledge/file", async (req, reply) => {
  const query = req.query as { path?: string; download?: string };
  const file = String(query.path || "");
  const preview = previewKnowledgeFile(file) as { ok?: boolean; type?: string; path?: string; error?: string };
  if (!preview.ok || !preview.path || !fs.existsSync(preview.path)) return reply.code(404).send({ ok: false, error: preview.error || "file_not_found" });
  const type = knowledgeFileMime(preview.path, query.download === "1");
  if (query.download === "1") reply.header("Content-Disposition", `attachment; filename="${encodeURIComponent(path.basename(preview.path))}"`);
  return reply.type(type).send(fs.readFileSync(preview.path));
});

app.get("/api/workbench/file", async (req, reply) => {
  const query = req.query as { path?: string; download?: string };
  const file = resolveWorkbenchFilePath(String(query.path || ""));
  if (!file) return reply.code(404).send({ ok: false, error: "file_not_found" });
  if (query.download === "1") reply.header("Content-Disposition", `attachment; filename="${encodeURIComponent(path.basename(file))}"`);
  if (path.extname(file).toLowerCase() === ".html") {
    reply.header("Content-Security-Policy", "default-src 'none'; style-src 'unsafe-inline'; img-src 'self' data:; font-src 'self'; base-uri 'none'; form-action 'none'");
  }
  return reply.type(knowledgeFileMime(file, query.download === "1")).send(fs.readFileSync(file));
});

app.post("/api/documents/render", async (req, reply) => {
  const body = req.body as { sourcePath?: string; markdown?: string; title?: string; documentType?: string };
  let sourcePath = String(body.sourcePath || "").trim();
  let markdown = String(body.markdown || "");
  if (sourcePath) {
    const preview = previewKnowledgeFile(sourcePath) as { ok?: boolean; path?: string; error?: string; content?: string };
    if (!preview.ok || !preview.path || !fs.existsSync(preview.path)) return reply.code(404).send({ ok: false, error: preview.error || "file_not_found" });
    sourcePath = preview.path;
    markdown = fs.readFileSync(preview.path, "utf8");
  }
  if (!markdown.trim()) return reply.code(400).send({ ok: false, error: "markdown_or_source_required" });
  const folder = path.join(SIDECAR_DIR, "html_docs", nowIso().slice(0, 10));
  fs.mkdirSync(folder, { recursive: true });
  const htmlPath = sourcePath ? defaultHtmlPath(sourcePath) : path.join(folder, `${safeName(body.title || "document")}_${randomUUID().slice(0, 8)}.html`);
  const result = sourcePath
    ? writeHtmlSidecar(sourcePath, htmlPath, { title: body.title, documentType: body.documentType || "manual_render" })
    : writeHtmlDocument(markdown, htmlPath, { title: body.title, documentType: body.documentType || "manual_render" });
  db.prepare("INSERT INTO document_renders (id, source_path, html_path, source_hash, render_status, document_type, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)")
    .run(randomUUID(), sourcePath || "inline_markdown", result.htmlPath, result.sourceHash, "fresh", body.documentType || "manual_render", nowIso(), nowIso());
  audit(db, "document.render", "document", result.htmlPath, "normal", { sourcePath: sourcePath || "inline_markdown", documentType: body.documentType || "manual_render" });
  return { ok: true, render: result, fileUrl: `/api/documents/file?path=${encodeURIComponent(result.htmlPath)}` };
});

