app.post("/api/knowledge/notes/organize", async (req, reply) => {
  const body = req.body as KnowledgeNoteOrganizeBody;
  const abortController = new AbortController();
  const abortRequest = () => abortController.abort();
  req.raw.setTimeout(0);
  reply.raw.setTimeout(0);
  req.raw.once("aborted", abortRequest);
  // v3.2 修复：默认 9 分钟 hard timeout。LLM 实际跑 3-8 分钟飘。
  // 5 分钟太短会误杀慢请求；9 分钟给足 LLM 时间。Abort signal 强制 settle，避免 promise 永远不 resolve。
  const hardTimeoutMs = Math.max(540_000, Number(body.gatewayTimeoutMs) || 0);
  const hardTimeout = setTimeout(() => {
    if (!abortController.signal.aborted) {
      abortController.abort();
      audit(db, "knowledge.note.organize.hard_timeout", "knowledge_note", null, "warn", { hardTimeoutMs });
    }
  }, hardTimeoutMs);
  try {
    const result = await organizeKnowledgeNoteDraftHighQualityWithOpsRecovery(body, { signal: abortController.signal });
    audit(db, "knowledge.note.organize", "knowledge_note", null, "normal", {
      title: result.draft.title,
      type: result.draft.type,
      folder: result.draft.folder,
      qualityMode: result.qualityMode,
      agentDecision: result.agentDecision,
      generationPipeline: result.generationPipeline,
    });
    return { ok: true, ...result, knowledgeNotePipelineVersion: KNOWLEDGE_NOTE_PIPELINE_VERSION };
  } catch (err) {
    if (abortController.signal.aborted) {
      const abortLabel = knowledgeNoteJobIsDirect({ qualityMode: body.qualityMode, requestedQualityMode: body.requestedQualityMode, effectiveQualityMode: body.effectiveQualityMode } as Record<string, unknown>) ? "MiniMax-M3 直连" : "Gateway/MiniMax";
      return reply.code(499).send({
        ok: false,
        error: "knowledge_note_organize_aborted",
        message: `Knowledge 添加笔记整理请求已停止，后端已中止等待 ${abortLabel}。`,
        retryable: true,
        knowledgeNotePipelineVersion: KNOWLEDGE_NOTE_PIPELINE_VERSION,
      });
    }
    const { failure, details, payload, statusCode } = buildKnowledgeNoteFailurePayload(err);
    audit(db, "knowledge.note.organize.failed", "knowledge_note", null, "warn", {
      stage: failure.stage,
      reason: failure.reason,
      reasonLabel: details.reasonLabel,
      retryable: details.retryable,
      debugReportPath: failure.debugReportPath,
      diagnosis: failure.diagnosis,
      retryBudget: failure.retryBudget,
      attempts: failure.attempts,
      generationPipeline: failure.generationPipeline,
    });
    return reply.code(statusCode).send(payload);
  } finally {
    clearTimeout(hardTimeout);
  }
});

