function recentKnowledgeNoteOrganizeJobs(limit: number) {
  const nowMs = Date.now();
  const byId = new Map<string, Record<string, any>>();
  for (const job of knowledgeNoteOrganizeJobs.values()) {
    byId.set(job.id, publicKnowledgeNoteOrganizeJob(job));
  }
  for (const item of listRecentJsonReports(KNOWLEDGE_NOTE_ORGANIZE_JOB_ROOT, Math.max(limit * 4, 80))) {
    const data = readJsonPath(item.file);
    if (!data || !String(data.id || "")) continue;
    byId.set(String(data.id), normalizeKnowledgeNoteOrganizeReportForRuntime(data, item.file, nowMs));
  }
  return [...byId.values()]
    .sort((a, b) => knowledgeNoteOrganizeReportTimeMs(b) - knowledgeNoteOrganizeReportTimeMs(a))
    .slice(0, limit);
}

app.get("/api/knowledge/notes/organize-jobs", async (req) => {
  const query = req.query as { limit?: string; date?: string; status?: string; sourceHash?: string; folder?: string };
  const limit = Math.max(1, Math.min(80, Number(query.limit || 20) || 20));
  const date = String(query.date || "").trim();
  const status = String(query.status || "").trim();
  const sourceHash = String(query.sourceHash || "").trim();
  const folder = String(query.folder || "").trim();
  const jobs = recentKnowledgeNoteOrganizeJobs(Math.max(limit * 4, 80))
    .filter((job) => !date || String(job.date || "").slice(0, 10) === date)
    .filter((job) => !status || String(job.status || "") === status)
    .filter((job) => !sourceHash || String(job.sourceHash || "") === sourceHash)
    .filter((job) => !folder || String(job.folder || "").startsWith(folder))
    .slice(0, limit);
  return { ok: true, jobs, knowledgeNotePipelineVersion: KNOWLEDGE_NOTE_PIPELINE_VERSION };
});

