type KnowledgeNoteOrganizeBody = KnowledgeNoteDraftInput & {
  content?: string;
  source?: string;
  text?: string;
  qualityMode?: string;
  requestedQualityMode?: string;
  effectiveQualityMode?: string;
  qualityModeAliasReason?: string;
  htmlMode?: string;
  agentId?: string;
  forceFresh?: boolean;
  gatewayTimeoutMs?: number;
  retryPolicy?: {
    autoRepair?: boolean;
    maxAttempts?: number;
    exposeDiagnostics?: boolean;
  };
  manualRepairNote?: string;
};

function knowledgeNoteRawContent(body: Partial<KnowledgeNoteOrganizeBody>) {
  return String(body.rawContent ?? body.content ?? body.source ?? body.text ?? "");
}

function normalizeKnowledgeNoteOrganizeBody(body: KnowledgeNoteOrganizeBody) {
  const rawContent = knowledgeNoteRawContent(body);
  const next = rawContent === String(body.rawContent || "") ? { ...body } : { ...body, rawContent };
  const quality = normalizeKnowledgeNoteQualityMode(next.requestedQualityMode || next.qualityMode);
  // T1 (v3): keep body.qualityMode as the original requested value so the run-time
  // branching code (requestedMode === "minimax-direct") can actually fire.
  // The resolved effective mode is stored separately in effectiveQualityMode.
  next.qualityMode = quality.requested;
  next.requestedQualityMode = quality.requested;
  next.effectiveQualityMode = quality.effective;
  if (quality.aliasReason) next.qualityModeAliasReason = quality.aliasReason;
  else delete next.qualityModeAliasReason;
  return next;
}

function normalizeKnowledgeNoteQualityMode(input: unknown) {
  const requested = String(input || "minimax-direct").trim().toLowerCase() || "minimax-direct";
  if (requested === "local") return { requested, effective: "local", aliasReason: "" };
  if (requested === "m27" || requested === "m27-html") return { requested, effective: "m27-html", aliasReason: requested === "m27" ? "m27_alias_to_m27_html" : "" };
  if (requested === "m3-html") return { requested, effective: "m3-html", aliasReason: "" };
  // njx-knowledge v2 / Phase 4 — minimax-direct 直连 MiniMax-M3 是默认路径, 必须保持 effective = minimax-direct.
  // 不再 alias 到 m3-html Gateway 链路; 失败由调用方显式 fail-fast (BLOCKED_MINIMAX_DIRECT_CONFIG), 不做隐式 fallback.
  if (requested === "minimax-direct") {
    return { requested, effective: "minimax-direct", aliasReason: "" };
  }
  if (["high", "m3", "minimax-m3", "minimax_m3"].includes(requested)) {
    return { requested, effective: "m3-html", aliasReason: `${requested}_alias_to_m3_html` };
  }
  return { requested, effective: requested, aliasReason: "" };
}

type KnowledgeNotePromptProfile = "compact-low-information" | "calendar-meeting" | "full";

type KnowledgeNoteGatewayDraft = {
  sourceHash?: string;
  draft?: Partial<KnowledgeNoteDraftInput>;
  layoutStrategy?: KnowledgeNoteLayoutStrategyInput;
  agentDecision?: { chosenAgent?: string; reason?: string; escalationNeeded?: boolean };
  quality?: { confidence?: number; sourceCoverage?: string; unresolvedItems?: unknown };
  coverageMap?: unknown;
  missingRisk?: unknown;
  sourceAnchors?: unknown;
};

type KnowledgeNoteGatewayHtmlDraft = {
  sourceHash?: string;
  title?: string;
  html?: string;
  htmlQuality?: { score?: number; passed?: boolean; issues?: unknown };
};

type KnowledgeNoteGatewayExecution = {
  roleAgent: AgentId;
  executionAgent: AgentId;
  reason: string;
  rerouteReason?: string;
  sessionKey?: string;
};

type KnowledgeNoteLateSessionHarvest = {
  agentId: AgentId;
  sessionKey: string;
  sessionId: string;
  transcriptPath: string;
  tsMs: number;
  text: string;
};

type KnowledgeNoteMarkdownGatewayResult = {
  gatewayAttempt: { gateway: GatewayResult; execution: KnowledgeNoteGatewayExecution };
  parsed: KnowledgeNoteGatewayDraft;
  normalized: ReturnType<typeof normalizeGatewayKnowledgeDraft>;
  sourceCheck: { ok: boolean; reason: string };
  repaired: boolean;
  debugReportPath?: string;
};

type KnowledgeNoteAttemptStatus = "passed" | "failed";

type KnowledgeNoteAttempt = {
  attempt: number;
  stage: string;
  strategy: string;
  status: KnowledgeNoteAttemptStatus;
  reason?: string;
  repairDirectives?: string[];
  debugReportPath?: string;
  confidence?: number;
  htmlScore?: number;
};

type KnowledgeNoteOpsRecoveryReport = {
  ok: boolean;
  status: "RECOVERED" | "DEGRADED" | "FAILED" | "SKIPPED";
  ts: string;
  attempt: number;
  stage: string;
  reason: string;
  sourceHash: string;
  reportPath?: string;
  retryRecommended: boolean;
  durationMs: number;
  watchdog?: ReturnType<typeof runSystemOpsWatchdog> | Record<string, unknown> | null;
  latestSystemOps?: { path?: string | null; status?: string | null; summary?: string | null; network_status?: string | null; nas_status?: string | null; blockers?: unknown } | null;
  gatewayHealthChecks: LiveGatewayHealthSnapshot[];
  actions: string[];
  blockers: string[];
  nextActions: string[];
};

type KnowledgeNoteOpsRecoverySummary = {
  status: "RECOVERED" | "DEGRADED" | "FAILED" | "SKIPPED";
  attempts: number;
  retryRecommended: boolean;
  reports: string[];
  latestReportPath?: string;
  latestSystemOpsStatus?: string | null;
  latestGatewayStatus?: string | null;
  blockers: string[];
  nextActions: string[];
};

type GatewayLifecycleActionResult = {
  action: GatewayControlAction;
  ok: boolean;
  status: "connected" | "unavailable";
  error?: string;
  output?: string;
  durationMs: number;
};

type GatewayLifecycleRecoveryResult = {
  attempted: boolean;
  ok: boolean;
  steps: GatewayLifecycleActionResult[];
  finalStatus?: string | null;
  finalError?: string | null;
};

function isGatewayControlStatusConnected(text: string, status: GatewayControlResult["status"]) {
  if (status === "connected") return true;
  const lower = String(text || "").toLowerCase();
  return /(connected|running|service is running|all good|ok)/.test(lower);
}

function shouldAttemptGatewayLifecycleInstall(text: string) {
  return /(not installed|service not loaded|not loaded|could not find service|launchagent .*not loaded|launch agent .*not running|service is not running)/i.test(text);
}

function gatewayLifecycleActionOutputText(result: GatewayControlResult<unknown>) {
  return `${result.stdout || ""}\n${result.stderr || ""}\n${result.error || ""}`.trim();
}

function knowledgeNoteGatewayRestartApproved() {
  return process.env.OPENCLAW_WORKBENCH_NOTE_GATEWAY_RESTART_APPROVAL === "OPENCLAW_WORKBENCH_NOTE_GATEWAY_RESTART_APPROVED";
}

async function runGatewayLifecycleAction(
  action: GatewayControlAction,
  signal: AbortSignal | undefined,
  reasonHint: string,
  steps: GatewayLifecycleActionResult[],
): Promise<GatewayControlResult<unknown>> {
  const result = await gatewayControl(action, {
    timeoutMs: 40_000,
    serializeCli: true,
    signal,
  });
  const output = gatewayLifecycleActionOutputText(result);
  const actionResult: GatewayLifecycleActionResult = {
    action,
    ok: result.ok,
    status: result.status,
    output: (output || reasonHint).slice(0, 1_200),
    error: result.error ? result.error.slice(0, 800) : undefined,
    durationMs: result.durationMs,
  };
  steps.push(actionResult);
  return result;
}

async function runGatewayLifecycleRecovery(input: {
  attempt: number;
  reason: string;
  signal?: AbortSignal;
}): Promise<GatewayLifecycleRecoveryResult> {
  const steps: GatewayLifecycleActionResult[] = [];
  let finalError: string | null = null;
  const reason = sanitizePublicError(input.reason).toLowerCase();
  try {
    const statusResult = await runGatewayLifecycleAction("status", input.signal, reason, steps);
    const statusText = gatewayLifecycleActionOutputText(statusResult);
    let finalStatus = isGatewayControlStatusConnected(statusText, statusResult.status) ? "connected" : (statusResult.status || null);
    if (!isGatewayControlStatusConnected(statusText, statusResult.status)) {
      if (shouldAttemptGatewayLifecycleInstall(statusText)) {
        const installResult = await runGatewayLifecycleAction("install", input.signal, reason, steps);
        const startResult = await runGatewayLifecycleAction("start", input.signal, reason, steps);
        finalStatus = isGatewayControlStatusConnected(gatewayLifecycleActionOutputText(startResult), startResult.status) ? "connected" : finalStatus;
        if (!installResult.ok && !startResult.ok) finalError = `${installResult.error || ""} ${startResult.error || ""}`.trim() || "install_and_start_failed";
      } else {
        const startResult = await runGatewayLifecycleAction("start", input.signal, reason, steps);
        finalStatus = isGatewayControlStatusConnected(gatewayLifecycleActionOutputText(startResult), startResult.status) ? "connected" : finalStatus;
        if (!startResult.ok) {
          if (knowledgeNoteGatewayRestartApproved()) {
            const restartResult = await runGatewayLifecycleAction("restart", input.signal, reason, steps);
            finalStatus = isGatewayControlStatusConnected(gatewayLifecycleActionOutputText(restartResult), restartResult.status) ? "connected" : finalStatus;
            if (!restartResult.ok) finalError = `${startResult.error || ""} ${restartResult.error || ""}`.trim() || "gateway_lifecycle_start_restart_failed";
          } else {
            steps.push({
              action: "restart",
              ok: false,
              status: "unavailable",
              error: "gateway_restart_main_approval_required",
              output: "Knowledge-note Worker ops recovery will not restart OpenClaw Gateway without explicit Main/user approval and the standard backup -> restart -> validate -> rollback flow.",
              durationMs: 0,
            });
            finalError = `${startResult.error || ""} gateway_restart_main_approval_required`.trim();
          }
        }
      }
      const recheck = await runGatewayLifecycleAction("status", input.signal, reason, steps);
      finalStatus = isGatewayControlStatusConnected(gatewayLifecycleActionOutputText(recheck), recheck.status) ? "connected" : finalStatus;
    }

    const health = await refreshLiveGatewayHealth({
      force: true,
      timeoutMs: LIVE_GATEWAY_HEALTH_TIMEOUT_MS,
      minIntervalMs: 0,
      source: "gateway:server_ops_lifecycle",
      signal: input.signal,
    });
    const finalHealthy = health.ok;
    const finalStatusWithHealth: string | null = finalHealthy ? "connected" : finalStatus;
    const finalErrorWithHealth = finalHealthy
      ? finalError
      : `${finalError || ""}${(finalError ? ";" : "")}${health.error || "gateway_health_check_failed"}`.trim() || "gateway_health_check_failed";
    return {
      attempted: steps.length > 1,
      ok: finalHealthy || finalStatusWithHealth === "connected",
      steps,
      finalStatus: finalStatusWithHealth,
      finalError: finalErrorWithHealth || null,
    };
  } catch (err) {
    return {
      attempted: steps.length > 0,
      ok: false,
      steps,
      finalStatus: "unavailable",
      finalError: sanitizePublicError(err instanceof Error ? err.message : String(err)),
    };
  }
}

type KnowledgeNoteDiagnosis = {
  category: string;
  rootCause: string;
  retryable: boolean;
  userAction: string;
  repairDirectives: string[];
  nextActions: string[];
  reasonLabel?: string;
  advice?: string;
};

type KnowledgeNoteRetryBudget = {
  used: number;
  max: number;
  exhausted: boolean;
  allowed?: number;
  remaining?: number;
  maxMarkdownAttempts?: number;
  maxHtmlAttempts?: number;
  maxMarkdownRepairAttempts?: number;
};

type KnowledgeNoteFailureExtras = {
  attempts?: KnowledgeNoteAttempt[];
  diagnosis?: KnowledgeNoteDiagnosis;
  retryBudget?: KnowledgeNoteRetryBudget;
  debugReports?: string[];
  nextActions?: string[];
  opsRecovery?: KnowledgeNoteOpsRecoverySummary | null;
  directMinimaxNote?: { fallback: boolean; reason?: string; provider: string; baseUrl: string; baseUrlSource: string; apiKeyRefSource: string; durationMs?: number; model?: string } | null;
};

type KnowledgeNoteOrganizeJobStatus = "queued" | "running" | "succeeded" | "failed" | "aborted";

type KnowledgeNoteOrganizeJob = {
  id: string;
  key: string;
  status: KnowledgeNoteOrganizeJobStatus;
  phase: string;
  message: string;
  createdAt: string;
  updatedAt: string;
  completedAt?: string;
  sourceHash: string;
  title: string;
  date: string;
  folder: string;
  qualityMode: string;
  requestedQualityMode?: string;
  effectiveQualityMode?: string;
  qualityModeAliasReason?: string;
  forceFresh?: boolean;
  attempts: KnowledgeNoteAttempt[];
  debugReports: string[];
  diagnosis?: KnowledgeNoteDiagnosis | null;
  retryBudget?: KnowledgeNoteRetryBudget | null;
  opsRecovery?: KnowledgeNoteOpsRecoverySummary | null;
  result?: Record<string, unknown>;
  failure?: Record<string, unknown>;
  reportPath?: string;
};

const knowledgeNoteOrganizeJobs = new Map<string, KnowledgeNoteOrganizeJob>();
const knowledgeNoteOrganizeJobKeys = new Map<string, string>();
const knowledgeNoteOrganizeQueue: string[] = [];
const knowledgeNoteOrganizeLateRecoveryInFlight = new Set<string>();
let knowledgeNoteOrganizeActiveJobId = "";

class KnowledgeNoteGatewayRequiredError extends Error {
  statusCode: number;
  stage: string;
  reason: string;
  generationPipeline: string[];
  debugReportPath?: string;
  attempts: KnowledgeNoteAttempt[];
  diagnosis?: KnowledgeNoteDiagnosis;
  retryBudget?: KnowledgeNoteRetryBudget;
  debugReports: string[];
  nextActions: string[];
  opsRecovery?: KnowledgeNoteOpsRecoverySummary | null;
  directMinimaxNote: { fallback: boolean; reason?: string; provider: string; baseUrl: string; baseUrlSource: string; apiKeyRefSource: string; durationMs?: number; model?: string } | null;

  constructor(stage: string, reason: string, generationPipeline: string[] = [], statusCode = 503, debugReportPath?: string, extras: KnowledgeNoteFailureExtras = {}) {
    super(reason || "gateway_model_required");
    this.name = "KnowledgeNoteGatewayRequiredError";
    this.statusCode = statusCode;
    this.stage = stage;
    this.reason = reason || "gateway_model_required";
    this.generationPipeline = generationPipeline;
    this.debugReportPath = debugReportPath;
    this.attempts = extras.attempts || [];
    this.diagnosis = extras.diagnosis;
    this.retryBudget = extras.retryBudget;
    this.debugReports = uniqueStrings([
      ...(extras.debugReports || []),
      debugReportPath || "",
      ...this.attempts.map((attempt) => attempt.debugReportPath || ""),
    ].filter(Boolean));
    this.nextActions = extras.nextActions || extras.diagnosis?.nextActions || [];
    this.opsRecovery = extras.opsRecovery || null;
    this.directMinimaxNote = extras.directMinimaxNote || null;
  }
}

function failKnowledgeNoteGateway(stage: string, reason: string, generationPipeline: string[] = [], statusCode = 503, debugReportPath?: string, extras: KnowledgeNoteFailureExtras = {}): never {
  throw new KnowledgeNoteGatewayRequiredError(stage, reason, generationPipeline, statusCode, debugReportPath, extras);
}

function isKnowledgeNoteGatewayRequiredError(err: unknown): err is KnowledgeNoteGatewayRequiredError {
  return err instanceof KnowledgeNoteGatewayRequiredError
    || (Boolean(err) && typeof err === "object" && (err as { name?: string }).name === "KnowledgeNoteGatewayRequiredError");
}

function buildKnowledgeNoteFailurePayload(err: unknown) {
  const failure = isKnowledgeNoteGatewayRequiredError(err)
    ? err
    : new KnowledgeNoteGatewayRequiredError("knowledge_note_organize", err instanceof Error ? err.message : "m3_organize_failed", ["gateway_required_failed"], 503);
  const details = knowledgeNoteFailureDetails(failure.reason);
  // 2026-07-06 (rework2): we need THREE distinct buckets for minimax-direct failures:
  //   (a) blocked_minimax_direct_config   — missing API key / config  (BLOCKED_MINIMAX_DIRECT_CONFIG)
  //   (b) blocked_minimax_direct_quality  — output quality gate failed  (minimax_direct_markdown_quality_*)
  //   (c) blocked_minimax_direct_config   — all other direct failures (http / aborted / throw / fetch)
  //         (kept as "config" semantics so the existing UI copy is still correct:
  //          these are still "you should retry / check API key", not "model output quality")
  // Quality vs config MUST NOT be conflated. A successful direct call whose output
  // fails quality MUST NOT emit "请配置 MiniMax API key" — that is misleading.
  const reasonText = String(failure.reason || "");
  const stageText = String(failure.stage || "");
  const directFailureCodeMatch = reasonText.match(/^(BLOCKED_MINIMAX_DIRECT_CONFIG|minimax_direct\w*)/);
  const directFailureCode = directFailureCodeMatch ? directFailureCodeMatch[1] : "";
  const isDirectConfigMissing = directFailureCode === "BLOCKED_MINIMAX_DIRECT_CONFIG";
  const isDirectQualityFailure = stageText === "minimax_direct_markdown_quality"
    || /^minimax_direct_markdown_quality/.test(directFailureCode)
    || /^minimax_direct_markdown_quality/.test(reasonText);
  const isDirectMinimaxFailure = stageText.startsWith("minimax_direct")
    || /^minimax_direct/.test(reasonText)
    || isDirectConfigMissing;
  // 2026-07-06 (rework3): if the reason starts with `minimax_direct_markdown_repair_failed`,
  // we have already issued one repair direct call and it also failed. Top-level copy must
  // reflect that both attempts failed, so the user knows we did try the repair.
  const isDirectRepairFailed = /^minimax_direct_markdown_repair_failed/.test(directFailureCode)
    || /^minimax_direct_markdown_repair_failed/.test(reasonText);
  // Pick the error code:
  //   * quality   -> blocked_minimax_direct_quality
  //   * config    -> blocked_minimax_direct_config (and transport / aborted / throw also use this)
  //   * otherwise -> gateway_model_required
  const errorCode = isDirectQualityFailure
    ? "blocked_minimax_direct_quality"
    : (isDirectMinimaxFailure ? "blocked_minimax_direct_config" : "gateway_model_required");
  // Top-level message MUST be category-correct. Do NOT say "请配置 MiniMax API key"
  // when the failure is pure quality — that misdirects the user.
  const message = isDirectQualityFailure
    ? (isDirectRepairFailed
      ? "MiniMax M3 直连与一次性 repair 两次均未通过质量门禁；不降级到 Gateway。请重试；若多次失败，可在 UI 切换 qualityMode=m3-html (legacy Gateway)。MiniMax API key 已配置正确，失败原因仅是模型输出质量。"
      : "MiniMax M3 直连成功调用，但输出未通过质量门禁；不降级到 Gateway。请重试；若多次失败，可在 UI 切换 qualityMode=m3-html (legacy Gateway)。MiniMax API key 已配置正确，失败原因仅是模型输出质量。")
    : isDirectMinimaxFailure
      ? "MiniMax M3 直连失败，不降级到 Gateway。请配置 MiniMax API key 或在 UI 显式切换 qualityMode=m3-html 走 Gateway。"
      : "Knowledge 添加笔记已禁用本地 fallback；必须通过 Gateway/MiniMax 完成整理。";
  // Direct-mode failures must NEVER surface Gateway repair copy at top-level
  // `reasonLabel` / `advice`. knowledgeNoteFailureDetails() falls through to
  // "Gateway/MiniMax 未返回可保存结果" + "请重试；若持续失败，检查 Gateway 状态…"
  // which misleads users into restarting OpenClaw Gateway when the actual root
  // cause is a missing MiniMax API key or a clean direct-call quality gate.
  // m3-html is mentioned only as the explicit user-selected legacy path.
  const directReasonLabel = isDirectConfigMissing
    ? "MiniMax API key 未配置（不降级到 Gateway）"
    : "MiniMax M3 直连失败（不降级到 Gateway）";
  const directAdvice = "minimax-direct 模式下不做 Gateway 隐式 fallback. 若需 Gateway 路径, 请在 UI 显式将 qualityMode 切换为 m3-html (legacy).";
  const qualityReasonLabel = "MiniMax M3 直连输出质量未通过（不降级到 Gateway）";
  const qualityAdvice = "minimax-direct 直连质量门禁已生效；本次输出未达可保存门槛。MiniMax API key 已成功调用，失败原因仅是模型输出质量，可重试或切换 qualityMode=m3-html (legacy Gateway) 路径。";
  const topReasonLabel = isDirectQualityFailure
    ? qualityReasonLabel
    : (isDirectMinimaxFailure ? directReasonLabel : details.reasonLabel);
  const topAdvice = isDirectQualityFailure
    ? qualityAdvice
    : (isDirectMinimaxFailure ? directAdvice : details.advice);
  // Use the mode-aware diagnose when the default diagnose is needed (i.e. no
  // explicit failure.diagnosis was provided). For direct failures
  // buildKnowledgeNoteFailurePayload callers should already inject
  // failure.diagnosis via the runtime direct branch, but we apply the same
  // mode-aware override defensively so the top-level advice / reasonLabel
  // never falls back to "检查 Gateway 状态" for a default minimax-direct job.
  const fallbackDiagnosis = diagnoseKnowledgeNoteFailureForMode(failure.stage, failure.reason, isDirectMinimaxFailure ? "minimax-direct" : undefined);
  const fallbackNextActions = (fallbackDiagnosis.nextActions || []);
  return {
    statusCode: failure.statusCode,
    payload: {
      ok: false,
      error: errorCode,
      message,
      stage: failure.stage,
      reason: failure.reason,
      reasonLabel: topReasonLabel,
      retryable: details.retryable,
      advice: topAdvice,
      debugReportPath: failure.debugReportPath,
      debugReports: failure.debugReports,
      opsRecovery: failure.opsRecovery,
      attempts: failure.attempts,
      diagnosis: failure.diagnosis || fallbackDiagnosis,
      retryBudget: failure.retryBudget,
      nextActions: failure.nextActions.length ? failure.nextActions : (failure.diagnosis || fallbackDiagnosis).nextActions || fallbackNextActions,
      generationPipeline: failure.generationPipeline,
      knowledgeNotePipelineVersion: KNOWLEDGE_NOTE_PIPELINE_VERSION,
      directMinimaxNote: failure.directMinimaxNote,
    },
    failure,
    details,
  };
}

function publicKnowledgeNoteOrganizeJob(job: KnowledgeNoteOrganizeJob) {
  const failureObj = (job.failure || {}) as Record<string, unknown>;
  return {
    id: job.id,
    key: job.key,
    status: job.status,
    phase: job.phase,
    message: job.message,
    error: typeof failureObj.reasonLabel === "string" ? failureObj.reasonLabel : (typeof failureObj.reason === "string" ? failureObj.reason : null),
    errorCode: typeof failureObj.reason === "string" ? failureObj.reason : null,
    errorStage: typeof failureObj.stage === "string" ? failureObj.stage : null,
    errorAdvice: (() => { const advice = (failureObj as { advice?: unknown }).advice; return Array.isArray(advice) ? advice : null; })(),
    createdAt: job.createdAt,
    updatedAt: job.updatedAt,
    completedAt: job.completedAt || null,
    sourceHash: job.sourceHash,
    title: job.title,
    date: job.date,
    folder: job.folder,
    qualityMode: job.qualityMode,
    requestedQualityMode: job.requestedQualityMode || job.qualityMode,
    effectiveQualityMode: job.effectiveQualityMode || job.qualityMode,
    qualityModeAliasReason: job.qualityModeAliasReason || "",
    forceFresh: Boolean(job.forceFresh),
    attempts: job.attempts,
    debugReports: job.debugReports,
    diagnosis: job.diagnosis || null,
    retryBudget: job.retryBudget || null,
    opsRecovery: job.opsRecovery || null,
    result: job.result || null,
    failure: job.failure || null,
    reportPath: job.reportPath || null,
  };
}

function knowledgeNoteOrganizeJobKey(body: KnowledgeNoteOrganizeBody, sourceHash: string) {
  return createHash("sha256").update(JSON.stringify({
    pipeline: KNOWLEDGE_NOTE_PIPELINE_VERSION,
    prompt: KNOWLEDGE_NOTE_GATEWAY_PROMPT_VERSION,
    sourceHash,
    title: String(body.title || "").trim(),
    date: String(body.date || "").trim(),
    type: String(body.type || "").trim(),
    status: String(body.status || "").trim(),
    folder: String(body.folder || "").trim(),
    tags: Array.isArray(body.tags) ? body.tags.map(String).sort() : body.tags,
    related: Array.isArray(body.related) ? body.related.map(String).sort() : body.related,
    manualRepairNote: String(body.manualRepairNote || "").trim(),
    qualityMode: String(body.qualityMode || "minimax-direct"),
  })).digest("hex");
}

function uniqueKnowledgeNoteAttempts(attempts: KnowledgeNoteAttempt[]) {
  return attempts.filter((attempt, index, all) => {
    const key = [
      attempt.stage || "",
      attempt.strategy || "",
      attempt.status || "",
      attempt.reason || "",
      attempt.debugReportPath || "",
    ].join("::");
    return all.findIndex((item) => [
      item.stage || "",
      item.strategy || "",
      item.status || "",
      item.reason || "",
      item.debugReportPath || "",
    ].join("::") === key) === index;
  });
}

function isPathInside(baseDir: string, file: string) {
  const base = path.resolve(baseDir);
  const resolved = path.resolve(file);
  return resolved === base || resolved.startsWith(`${base}${path.sep}`);
}

function knowledgeNoteOrganizeReportCreatedMs(data: Record<string, any>) {
  const parsed = Date.parse(String(data.createdAt || data.completedAt || data.updatedAt || ""));
  return Number.isFinite(parsed) ? parsed : 0;
}

function knowledgeNoteOrganizeResultHasDraftAndHtml(result: Record<string, any> | null | undefined) {
  return Boolean(result?.draft?.markdown && result?.htmlDraft?.html);
}

function knowledgeNoteOrganizeRecoveryFile(job: KnowledgeNoteOrganizeJob) {
  const ts = String(job.completedAt || job.updatedAt || job.createdAt).replace(/[-:]/g, "").replace(/\.\d+Z$/, "Z");
  return path.join(KNOWLEDGE_NOTE_ORGANIZE_JOB_RECOVERY_ROOT, `knowledge_note_organize_recovery_${ts}_${job.sourceHash.slice(0, 10)}_${job.id.slice(0, 8)}.json`);
}

function persistKnowledgeNoteOrganizeJobRecovery(job: KnowledgeNoteOrganizeJob): string | null {
  if (job.status !== "succeeded" || !job.result) return null;
  const result = job.result as Record<string, any>;
  if (!knowledgeNoteOrganizeResultHasDraftAndHtml(result)) return typeof result.resultRecoveryPath === "string" ? result.resultRecoveryPath : null;
  const existingPath = typeof result.resultRecoveryPath === "string" ? result.resultRecoveryPath : "";
  const recoveryPath = existingPath && isPathInside(KNOWLEDGE_NOTE_ORGANIZE_JOB_RECOVERY_ROOT, existingPath)
    ? existingPath
    : knowledgeNoteOrganizeRecoveryFile(job);
  const recoveryResult = {
    ok: true,
    draft: result.draft,
    layoutStrategy: result.layoutStrategy || null,
    htmlDraft: result.htmlDraft,
    htmlQuality: result.htmlQuality || null,
    generationPipeline: Array.isArray(result.generationPipeline) ? result.generationPipeline : [],
    htmlMode: result.htmlMode || "m3",
    quality: result.quality || null,
    agentDecision: result.agentDecision || null,
    fallbackReason: result.fallbackReason || "",
    qualityMode: result.qualityMode || job.qualityMode || "m3-html",
    staleRuntimeError: Boolean(result.staleRuntimeError),
    attempts: Array.isArray(result.attempts) ? result.attempts : job.attempts,
    debugReports: Array.isArray(result.debugReports) ? result.debugReports : job.debugReports,
    diagnosis: result.diagnosis || job.diagnosis || null,
    retryBudget: result.retryBudget || job.retryBudget || null,
    opsRecovery: result.opsRecovery || job.opsRecovery || null,
    knowledgeNotePipelineVersion: result.knowledgeNotePipelineVersion || KNOWLEDGE_NOTE_PIPELINE_VERSION,
    sourceHash: job.sourceHash,
    resultRecoveryPath: recoveryPath,
  };
  const recovery = {
    ok: true,
    jobId: job.id,
    key: job.key,
    sourceHash: job.sourceHash,
    title: job.title,
    date: job.date,
    folder: job.folder,
    qualityMode: job.qualityMode,
    requestedQualityMode: job.requestedQualityMode || job.qualityMode,
    effectiveQualityMode: job.effectiveQualityMode || job.qualityMode,
    qualityModeAliasReason: job.qualityModeAliasReason || "",
    createdAt: job.createdAt,
    updatedAt: job.updatedAt,
    completedAt: job.completedAt || job.updatedAt,
    result: recoveryResult,
  };
  fs.mkdirSync(path.dirname(recoveryPath), { recursive: true });
  fs.writeFileSync(recoveryPath, `${JSON.stringify(recovery, null, 2)}\n`, "utf8");
  result.resultRecoveryPath = recoveryPath;
  return recoveryPath;
}

function loadKnowledgeNoteOrganizeJobRecovery(recoveryPath: unknown, expectedSourceHash = "") {
  const file = String(recoveryPath || "");
  if (!file || !isPathInside(KNOWLEDGE_NOTE_ORGANIZE_JOB_RECOVERY_ROOT, file)) return null;
  const recovery = readJsonPath(file);
  if (!recovery || typeof recovery !== "object") return null;
  const result = recovery.result as Record<string, any> | undefined;
  if (!knowledgeNoteOrganizeResultHasDraftAndHtml(result)) return null;
  const sourceHash = String(recovery.sourceHash || result?.sourceHash || "");
  if (expectedSourceHash && sourceHash !== expectedSourceHash) return null;
  const recoveredResult: Record<string, any> = {
    ok: true,
    ...result,
    sourceHash,
    resultRecoveryPath: file,
    knowledgeNotePipelineVersion: result?.knowledgeNotePipelineVersion || KNOWLEDGE_NOTE_PIPELINE_VERSION,
  };
  return {
    recoveryPath: file,
    recovery,
    result: recoveredResult,
  };
}

function inMemoryKnowledgeNoteSuccessResult(job: KnowledgeNoteOrganizeJob) {
  if (job.status !== "succeeded" || !job.result) return null;
  const result = job.result as Record<string, any>;
  if (knowledgeNoteOrganizeResultHasDraftAndHtml(result)) {
    const recoveryPath = persistKnowledgeNoteOrganizeJobRecovery(job);
    return { ok: true, ...result, resultRecoveryPath: recoveryPath || result.resultRecoveryPath || "" };
  }
  return loadKnowledgeNoteOrganizeJobRecovery(result.resultRecoveryPath, job.sourceHash)?.result || null;
}

function findLatestRecoverableKnowledgeNoteSuccess(input: {
  sourceHash: string;
  key?: string;
  afterMs?: number;
  excludeJobId?: string;
}) {
  const sourceHash = String(input.sourceHash || "");
  if (!sourceHash) return null;
  const candidates: Array<{
    job: Record<string, any>;
    result: Record<string, any>;
    reportPath: string;
    resultRecoveryPath: string;
    timeMs: number;
  }> = [];

  for (const job of knowledgeNoteOrganizeJobs.values()) {
    if (job.status !== "succeeded" || job.sourceHash !== sourceHash) continue;
    if (input.key && job.key !== input.key) continue;
    if (input.excludeJobId && job.id === input.excludeJobId) continue;
    const createdMs = knowledgeNoteOrganizeReportCreatedMs(job as unknown as Record<string, any>);
    if (input.afterMs && createdMs <= input.afterMs) continue;
    const result = inMemoryKnowledgeNoteSuccessResult(job);
    if (!result) continue;
    candidates.push({
      job: publicKnowledgeNoteOrganizeJob(job),
      result,
      reportPath: job.reportPath || "",
      resultRecoveryPath: String(result.resultRecoveryPath || ""),
      timeMs: knowledgeNoteOrganizeReportTimeMs(job as unknown as Record<string, any>) || createdMs,
    });
  }

  for (const item of listRecentJsonReports(KNOWLEDGE_NOTE_ORGANIZE_JOB_ROOT, 400)) {
    const data = readJsonPath(item.file);
    if (!data || String(data.status || "") !== "succeeded") continue;
    if (String(data.sourceHash || "") !== sourceHash) continue;
    if (input.key && String(data.key || "") !== input.key) continue;
    if (input.excludeJobId && String(data.id || "") === input.excludeJobId) continue;
    const createdMs = knowledgeNoteOrganizeReportCreatedMs(data);
    if (input.afterMs && createdMs <= input.afterMs) continue;
    const recovery = loadKnowledgeNoteOrganizeJobRecovery(data.result?.resultRecoveryPath || data.resultRecoveryPath, sourceHash);
    if (!recovery) continue;
    candidates.push({
      job: data,
      result: recovery.result,
      reportPath: item.file,
      resultRecoveryPath: recovery.recoveryPath,
      timeMs: knowledgeNoteOrganizeReportTimeMs(data) || createdMs,
    });
  }

  return candidates.sort((a, b) => b.timeMs - a.timeMs)[0] || null;
}

function inflateKnowledgeNoteOrganizeReportResult(report: Record<string, any>) {
  const status = String(report.status || "");
  const hasCompletedRecoverableResult = Boolean(
    report.completedAt
    && report.result?.ok
    && (report.result?.resultRecoveryPath || report.resultRecoveryPath),
  );
  if (status !== "succeeded" && !hasCompletedRecoverableResult) return report;
  if (knowledgeNoteOrganizeResultHasDraftAndHtml(report.result)) {
    return status === "succeeded" ? report : {
      ...report,
      status: "succeeded",
      phase: "preview_ready",
      message: "后台整理任务已完成并有可恢复结果；已归一为成功状态。",
      failure: null,
      diagnosis: null,
    };
  }
  const recovery = loadKnowledgeNoteOrganizeJobRecovery(report.result?.resultRecoveryPath || report.resultRecoveryPath, String(report.sourceHash || ""));
  if (!recovery) return report;
  return {
    ...report,
    status: "succeeded",
    phase: "preview_ready",
    message: status === "succeeded" ? report.message : "后台整理任务已完成并回收可保存 Markdown 与 HTML 预览。",
    completedAt: report.completedAt || recovery.result?.completedAt || report.updatedAt || nowIso(),
    failure: null,
    diagnosis: null,
    result: {
      ...recovery.result,
      attempts: Array.isArray(recovery.result.attempts) ? recovery.result.attempts : report.attempts || [],
      debugReports: Array.isArray(recovery.result.debugReports) ? recovery.result.debugReports : report.debugReports || [],
      opsRecovery: recovery.result.opsRecovery || report.opsRecovery || null,
      retryBudget: recovery.result.retryBudget || report.retryBudget || null,
    },
    resultRecoveryPath: recovery.recoveryPath,
  };
}

function supersededKnowledgeNoteOrganizeReport(
  report: Record<string, any>,
  reportPath: string,
  takeover: NonNullable<ReturnType<typeof findLatestRecoverableKnowledgeNoteSuccess>>,
  nowMs: number,
) {
  const takeoverResult = takeover.result;
  const supersededAttempt: KnowledgeNoteAttempt = {
    attempt: 0,
    stage: "knowledge_note_background_job",
    strategy: "superseded_by_later_success",
    status: "passed",
    reason: "superseded_by_later_success",
    repairDirectives: [
      "同一 sourceHash 的后续 job 已通过 Gateway/MiniMax 生成可信 Markdown 与 HTML。",
      "只复用可恢复结果引用，不启用本地 fallback。",
      "保留旧 job 的 stale 诊断和接管来源，供 Worker 运维审计。",
    ],
  };
  const attempts = uniqueKnowledgeNoteAttempts([
    ...(Array.isArray(report.attempts) ? report.attempts : []),
    ...(Array.isArray(takeoverResult.attempts) ? takeoverResult.attempts as KnowledgeNoteAttempt[] : []),
    supersededAttempt,
  ]);
  const debugReports = uniqueStrings([
    ...(Array.isArray(report.debugReports) ? report.debugReports : []),
    ...(Array.isArray(takeoverResult.debugReports) ? takeoverResult.debugReports : []),
    takeover.reportPath,
    takeover.resultRecoveryPath,
  ].filter(Boolean));
  return {
    ...report,
    status: "succeeded",
    phase: "preview_ready",
    message: "同一 sourceHash 的后续成功 job 已接管当前旧后台任务；已返回可保存 Markdown 与 HTML 预览。",
    completedAt: takeover.job.completedAt || takeover.job.updatedAt || nowIso(),
    failure: null,
    diagnosis: null,
    retryBudget: takeoverResult.retryBudget || report.retryBudget || null,
    opsRecovery: takeoverResult.opsRecovery || report.opsRecovery || null,
    attempts,
    debugReports,
    result: {
      ok: true,
      ...takeoverResult,
      attempts,
      debugReports,
      opsRecovery: takeoverResult.opsRecovery || report.opsRecovery || null,
      retryBudget: takeoverResult.retryBudget || report.retryBudget || null,
      knowledgeNotePipelineVersion: takeoverResult.knowledgeNotePipelineVersion || KNOWLEDGE_NOTE_PIPELINE_VERSION,
      supersededReason: "superseded_by_later_success",
      supersededByJobId: takeover.job.id || null,
      supersededByReportPath: takeover.reportPath,
      resultRecoveryPath: takeover.resultRecoveryPath,
    },
    reportPath: report.reportPath || reportPath,
    staleReport: true,
    staleReportAgeMs: Math.max(0, nowMs - knowledgeNoteOrganizeReportTimeMs(report)),
    supersededReason: "superseded_by_later_success",
    supersededByJobId: takeover.job.id || null,
    supersededByReportPath: takeover.reportPath,
    resultRecoveryPath: takeover.resultRecoveryPath,
  };
}

function persistKnowledgeNoteOrganizeJob(job: KnowledgeNoteOrganizeJob) {
  try {
    fs.mkdirSync(KNOWLEDGE_NOTE_ORGANIZE_JOB_ROOT, { recursive: true });
    const reportPath = path.join(KNOWLEDGE_NOTE_ORGANIZE_JOB_ROOT, `knowledge_note_organize_job_${job.createdAt.replace(/[-:]/g, "").replace(/\.\d+Z$/, "Z")}_${job.sourceHash.slice(0, 10)}_${job.id.slice(0, 8)}.json`);
    job.reportPath = reportPath;
    const result = job.result || {};
    const resultRecoveryPath = persistKnowledgeNoteOrganizeJobRecovery(job);
    const redacted = {
      ...publicKnowledgeNoteOrganizeJob(job),
      result: job.result ? {
        ok: true,
        title: (result as { draft?: { title?: string } }).draft?.title || job.title,
        date: (result as { draft?: { date?: string } }).draft?.date || job.date,
        qualityMode: (result as { qualityMode?: string }).qualityMode || job.qualityMode,
        generationPipeline: (result as { generationPipeline?: unknown }).generationPipeline || [],
        htmlScore: (result as { htmlQuality?: { score?: number } }).htmlQuality?.score ?? null,
        hasMarkdown: Boolean((result as { draft?: { markdown?: string } }).draft?.markdown),
        hasHtml: Boolean((result as { htmlDraft?: { html?: string } }).htmlDraft?.html),
        resultRecoveryPath,
      } : null,
    };
    fs.writeFileSync(reportPath, `${JSON.stringify(redacted, null, 2)}\n`, "utf8");
  } catch {
    // Report writing must not turn a model result into a false failure.
  }
}

function knowledgeNoteOrganizeReportTimeMs(data: Record<string, any>) {
  const parsed = Date.parse(String(data.updatedAt || data.createdAt || data.completedAt || ""));
  return Number.isFinite(parsed) ? parsed : 0;
}

function isStaleKnowledgeNoteOrganizeReport(data: Record<string, any>, nowMs = Date.now()) {
  const status = String(data.status || "");
  if (!["running", "queued"].includes(status)) return false;
  const reportMs = knowledgeNoteOrganizeReportTimeMs(data);
  return reportMs > 0 && nowMs - reportMs > KNOWLEDGE_NOTE_ORGANIZE_JOB_STALE_MS;
}

function normalizeKnowledgeNoteOrganizeReportForRuntime(data: Record<string, any>, reportPath: string, nowMs = Date.now()): Record<string, any> {
  const report: Record<string, any> = { ...data, reportPath: data.reportPath || reportPath };
  if (!isStaleKnowledgeNoteOrganizeReport(report, nowMs)) return inflateKnowledgeNoteOrganizeReportResult(report);
  const takeover = report.forceFresh ? null : findLatestRecoverableKnowledgeNoteSuccess({
    sourceHash: String(report.sourceHash || ""),
    afterMs: knowledgeNoteOrganizeReportCreatedMs(report),
    excludeJobId: String(report.id || ""),
  });
  if (takeover) return supersededKnowledgeNoteOrganizeReport(report, reportPath, takeover, nowMs);
  const reason = `stale_job_report_after_${KNOWLEDGE_NOTE_ORGANIZE_JOB_STALE_MS}ms`;
  const staleJobLabel = knowledgeNoteJobIsDirect({ qualityMode: report.qualityMode, requestedQualityMode: report.requestedQualityMode, effectiveQualityMode: report.effectiveQualityMode } as Record<string, unknown>) ? "MiniMax-M3 直连" : "Gateway/MiniMax";
  return {
    ...report,
    status: "aborted",
    phase: "stale_job_report_aborted",
    message: `后台整理任务报告已超过心跳窗口；Workbench 可能已重启或 ${staleJobLabel} 请求失去收敛，已按可重试失败处理。`,
    completedAt: report.completedAt || report.updatedAt || report.createdAt || "",
    failure: report.failure || {
      ok: false,
      error: "knowledge_note_organize_job_stale",
      stage: "knowledge_note_background_job",
      reason,
      reasonLabel: "后台整理任务失去心跳",
      retryable: true,
    },
    diagnosis: report.diagnosis || diagnoseKnowledgeNoteFailureForMode("knowledge_note_background_job", "background_job_timeout_after_stale_window", report.qualityMode),
    retryBudget: report.retryBudget || knowledgeNoteRetryBudget(0, KNOWLEDGE_NOTE_ORGANIZE_JOB_END_TO_END_ATTEMPTS),
    staleReport: true,
    staleReportAgeMs: Math.max(0, nowMs - knowledgeNoteOrganizeReportTimeMs(report)),
  };
}

function loadKnowledgeNoteOrganizeJobReportById(jobId: string): Record<string, any> | null {
  if (!jobId) return null;
  const reports = listRecentJsonReports(KNOWLEDGE_NOTE_ORGANIZE_JOB_ROOT, 200);
  for (const item of reports) {
    const data = readJsonPath(item.file);
    if (!data || String(data.id || "") !== jobId) continue;
    return normalizeKnowledgeNoteOrganizeReportForRuntime(data, item.file);
  }
  return null;
}

function cleanupKnowledgeNoteOrganizeJobs() {
  const now = Date.now();
  for (const [id, job] of knowledgeNoteOrganizeJobs.entries()) {
    if (!job.completedAt) {
      const updatedAtMs = Date.parse(job.updatedAt || job.createdAt);
      if (Number.isFinite(updatedAtMs) && now - updatedAtMs > KNOWLEDGE_NOTE_ORGANIZE_JOB_STALE_MS) {
        const takeover = job.forceFresh ? null : findLatestRecoverableKnowledgeNoteSuccess({
          sourceHash: job.sourceHash,
          afterMs: knowledgeNoteOrganizeReportCreatedMs(job as unknown as Record<string, any>),
          excludeJobId: job.id,
        });
        if (takeover) {
          const superseded = supersededKnowledgeNoteOrganizeReport(publicKnowledgeNoteOrganizeJob(job), job.reportPath || "", takeover, now);
          updateKnowledgeNoteOrganizeJob(job, {
            status: "succeeded",
            phase: "preview_ready",
            message: String(superseded.message || "同一 sourceHash 的后续成功 job 已接管当前旧后台任务。"),
            completedAt: String(superseded.completedAt || nowIso()),
            result: superseded.result,
            failure: undefined,
            diagnosis: null,
            retryBudget: superseded.retryBudget,
            opsRecovery: superseded.opsRecovery,
            attempts: superseded.attempts,
            debugReports: superseded.debugReports,
          });
          if (knowledgeNoteOrganizeActiveJobId === id) knowledgeNoteOrganizeActiveJobId = "";
          const queuedIndex = knowledgeNoteOrganizeQueue.indexOf(id);
          if (queuedIndex >= 0) knowledgeNoteOrganizeQueue.splice(queuedIndex, 1);
          continue;
        }
        updateKnowledgeNoteOrganizeJob(job, {
          status: "aborted",
          phase: "stale_job_aborted",
          message: "后台整理任务长时间没有进展，已自动作废；相同内容会创建新 job 重新整理。",
          completedAt: nowIso(),
          failure: {
            ok: false,
            error: "knowledge_note_organize_job_stale",
            stage: "knowledge_note_background_job",
            reason: `stale_job_after_${KNOWLEDGE_NOTE_ORGANIZE_JOB_STALE_MS}ms`,
            retryable: true,
          },
          diagnosis: diagnoseKnowledgeNoteFailure("knowledge_note_background_job", "background_job_timeout_after_stale_window"),
          retryBudget: knowledgeNoteRetryBudget(0, KNOWLEDGE_NOTE_ORGANIZE_JOB_END_TO_END_ATTEMPTS),
        });
        if (knowledgeNoteOrganizeActiveJobId === id) knowledgeNoteOrganizeActiveJobId = "";
        const queuedIndex = knowledgeNoteOrganizeQueue.indexOf(id);
        if (queuedIndex >= 0) knowledgeNoteOrganizeQueue.splice(queuedIndex, 1);
      }
      continue;
    }
    if (!job.completedAt) continue;
    const completedAtMs = Date.parse(job.completedAt);
    if (Number.isFinite(completedAtMs) && now - completedAtMs > KNOWLEDGE_NOTE_ORGANIZE_JOB_RETENTION_MS) {
      knowledgeNoteOrganizeJobs.delete(id);
      knowledgeNoteOrganizeJobBodies.delete(id);
      knowledgeNoteOrganizeLateRecoveryInFlight.delete(id);
      if (knowledgeNoteOrganizeJobKeys.get(job.key) === id) knowledgeNoteOrganizeJobKeys.delete(job.key);
    }
  }
}

function updateKnowledgeNoteOrganizeJob(job: KnowledgeNoteOrganizeJob, patch: Partial<KnowledgeNoteOrganizeJob>) {
  Object.assign(job, patch, { updatedAt: nowIso() });
  persistKnowledgeNoteOrganizeJob(job);
  return job;
}

function createRecoveredKnowledgeNoteOrganizeJob(input: KnowledgeNoteOrganizeBody, key: string, sourceHash: string, takeover: NonNullable<ReturnType<typeof findLatestRecoverableKnowledgeNoteSuccess>>) {
  const createdAt = nowIso();
  const result = takeover.result;
  const recoveryAttempt: KnowledgeNoteAttempt = {
    attempt: 0,
    stage: "knowledge_note_background_job",
    strategy: "superseded_by_later_success",
    status: "passed",
    reason: "superseded_by_later_success",
    repairDirectives: [
      "检测到同一 key/sourceHash 已有 Gateway/MiniMax M3 成功结果。",
      "直接复用可恢复 Markdown/HTML 引用，避免重复排队和模型调用。",
      "不启用本地 fallback，不创建未验证草稿。",
    ],
  };
  const attempts = uniqueKnowledgeNoteAttempts([
    ...(Array.isArray(result.attempts) ? result.attempts as KnowledgeNoteAttempt[] : []),
    recoveryAttempt,
  ]);
  const debugReports = uniqueStrings([
    ...(Array.isArray(result.debugReports) ? result.debugReports : []),
    takeover.reportPath,
    takeover.resultRecoveryPath,
  ].filter(Boolean));
  const job: KnowledgeNoteOrganizeJob = {
    id: randomUUID(),
    key,
    status: "succeeded",
    phase: "preview_ready",
    message: "已接回同一内容的可信 MiniMax-M3 成功结果，可直接进入预览；本次没有重复调用 Gateway。",
    createdAt,
    updatedAt: createdAt,
    completedAt: createdAt,
    sourceHash,
    title: String(input.title || result.draft?.title || "").slice(0, 160),
    date: String(input.date || result.draft?.date || "").slice(0, 32),
    folder: String(input.folder || result.draft?.folder || "").slice(0, 240),
    qualityMode: String(input.qualityMode || result.qualityMode || "minimax-direct"),
    requestedQualityMode: input.requestedQualityMode || String(input.qualityMode || result.qualityMode || "minimax-direct"),
    effectiveQualityMode: input.effectiveQualityMode || String(input.qualityMode || result.qualityMode || "minimax-direct"),
    qualityModeAliasReason: input.qualityModeAliasReason || "",
    attempts,
    debugReports,
    diagnosis: null,
    retryBudget: result.retryBudget || null,
    opsRecovery: result.opsRecovery || null,
    result: {
      ok: true,
      ...result,
      attempts,
      debugReports,
      retryBudget: result.retryBudget || null,
      opsRecovery: result.opsRecovery || null,
      knowledgeNotePipelineVersion: result.knowledgeNotePipelineVersion || KNOWLEDGE_NOTE_PIPELINE_VERSION,
      requestedQualityMode: input.requestedQualityMode || String(input.qualityMode || result.qualityMode || "minimax-direct"),
      effectiveQualityMode: input.effectiveQualityMode || String(input.qualityMode || result.qualityMode || "minimax-direct"),
      qualityModeAliasReason: input.qualityModeAliasReason || "",
      supersededReason: "superseded_by_later_success",
      supersededByJobId: takeover.job.id || null,
      supersededByReportPath: takeover.reportPath,
      resultRecoveryPath: takeover.resultRecoveryPath,
    },
  };
  knowledgeNoteOrganizeJobs.set(job.id, job);
  knowledgeNoteOrganizeJobKeys.set(key, job.id);
  persistKnowledgeNoteOrganizeJob(job);
  return job;
}

function createKnowledgeNoteOrganizeJob(input: KnowledgeNoteOrganizeBody): { job: KnowledgeNoteOrganizeJob; reused: boolean } {
  cleanupKnowledgeNoteOrganizeJobs();
  const body = normalizeKnowledgeNoteOrganizeBody(input);
  const rawContent = knowledgeNoteRawContent(body);
  const sourceHash = createHash("sha256").update(rawContent).digest("hex");
  const key = knowledgeNoteOrganizeJobKey(body, sourceHash);
  const existingId = knowledgeNoteOrganizeJobKeys.get(key);
  const existing = existingId ? knowledgeNoteOrganizeJobs.get(existingId) : null;
  const forceFresh = body.forceFresh === true || String(body.forceFresh || "").toLowerCase() === "true";
  if (!forceFresh && existing) {
    if (existing.status !== "failed" && existing.status !== "aborted") {
      return { job: existing, reused: true };
    }
  }
  const persistedSuccess = forceFresh ? null : findLatestRecoverableKnowledgeNoteSuccess({ sourceHash, key });
  if (!forceFresh && persistedSuccess) {
    return { job: createRecoveredKnowledgeNoteOrganizeJob(body, key, sourceHash, persistedSuccess), reused: true };
  }
  const createdAt = nowIso();
  // 2026-07-05 — Knowledge v2 Add Note background-job direct-mode rework #2.
  //
  // The default `minimax-direct` queued-state copy must not surface the literal
  // substring `Gateway` (NJX product expectation: the default Add Note /
  // 同步日程 path is MiniMax-M3 direct, no Gateway wording). Legacy
  // `m3-html` / `m27-html` (explicit user-selected Gateway path) keeps the
  // legacy wording. This mirrors `knowledgeNoteJobDirectLabel` semantics
  // used elsewhere in this file so a freshly-queued job reads
  // "已加入 MiniMax-M3 直连后台队列；..." for direct mode and
  // "已加入添加笔记后台队列；...避免 Gateway 并发拥塞。" for legacy mode.
  const initialDirect = knowledgeNoteJobIsDirect({
    qualityMode: String(body.qualityMode || "minimax-direct"),
    requestedQualityMode: body.requestedQualityMode || String(input.qualityMode || body.qualityMode || "minimax-direct"),
    effectiveQualityMode: body.effectiveQualityMode || String(body.qualityMode || "minimax-direct"),
  });
  const queuedMessage = initialDirect
    ? "已加入 MiniMax-M3 直连后台队列；相同内容重复提交会复用同一个 job，避免 MiniMax 通道并发拥塞。"
    : "已加入添加笔记后台队列；相同内容重复提交会复用同一个 job，避免 Gateway 并发拥塞。";
  const job: KnowledgeNoteOrganizeJob = {
    id: randomUUID(),
    key,
    status: "queued",
    phase: "queued",
    message: queuedMessage,
    createdAt,
    updatedAt: createdAt,
    sourceHash,
    title: String(body.title || "").slice(0, 160),
    date: String(body.date || "").slice(0, 32),
    folder: String(body.folder || "").slice(0, 240),
    qualityMode: String(body.qualityMode || "minimax-direct"),
    requestedQualityMode: body.requestedQualityMode || String(input.qualityMode || body.qualityMode || "minimax-direct"),
    effectiveQualityMode: body.effectiveQualityMode || String(body.qualityMode || "minimax-direct"),
    qualityModeAliasReason: body.qualityModeAliasReason || "",
    forceFresh,
    attempts: [],
    debugReports: [],
    diagnosis: null,
    retryBudget: null,
    opsRecovery: null,
  };
  knowledgeNoteOrganizeJobs.set(job.id, job);
  knowledgeNoteOrganizeJobKeys.set(key, job.id);
  persistKnowledgeNoteOrganizeJob(job);
  enqueueKnowledgeNoteOrganizeJob(job, body);
  return { job, reused: false };
}

function enqueueKnowledgeNoteOrganizeJob(job: KnowledgeNoteOrganizeJob, body: KnowledgeNoteOrganizeBody) {
  if (!knowledgeNoteOrganizeQueue.includes(job.id)) knowledgeNoteOrganizeQueue.push(job.id);
  processKnowledgeNoteOrganizeQueue(bodyByJob(job.id, body));
}

function bodyByJob(jobId: string, body: KnowledgeNoteOrganizeBody) {
  return { jobId, body };
}

const knowledgeNoteOrganizeJobBodies = new Map<string, KnowledgeNoteOrganizeBody>();

function knowledgeNoteOrganizeAttemptTimeoutMs(body: KnowledgeNoteOrganizeBody) {
  const requestedTimeoutMs = Number(body.gatewayTimeoutMs);
  const effectiveRequestedTimeoutMs = Number.isFinite(requestedTimeoutMs) && requestedTimeoutMs >= KNOWLEDGE_NOTE_M3_GATEWAY_TIMEOUT_MS
    ? requestedTimeoutMs
    : KNOWLEDGE_NOTE_M3_GATEWAY_TIMEOUT_MS;
  const gatewayTimeoutMs = clampNumber(
    effectiveRequestedTimeoutMs,
    KNOWLEDGE_NOTE_MIN_REAL_GATEWAY_TIMEOUT_MS,
    Number.MAX_SAFE_INTEGER,
    effectiveRequestedTimeoutMs,
  );
  // v3.2 修复：限制 max 8 分钟（之前 9.5 分钟太长）。LLM 实际 3-8 分钟飘，9.5 分钟让前端 modal 长时间卡死。
  // 8 分钟 timeout + abort signal + 短 retry = 整体约 10-12 分钟内必返回，UI 用户能接受。
  return Math.min(
    8 * 60_000,
    Math.max(KNOWLEDGE_NOTE_ORGANIZE_JOB_MAX_MS, gatewayTimeoutMs + 30_000),
  );
}

// 2026-07-05 — Knowledge v2 real Add Note job direct-mode helpers.
//
// The previous rework only fixed the synchronous /api/knowledge/notes/organize
// path. The background job path (KnowledgeNoteOrganizeJob created via
// /api/knowledge/notes/organize-jobs and consumed by the Calendar "添加笔记 /
// 同步日程" / 知识库添加笔记 flow) still emitted hard-coded "Gateway/MiniMax"
// wording for default direct-mode jobs. NJX's screenshot failure exposed this:
//   - "正在后台执行 Gateway/MiniMax 整理..."
//   - "连接 Gateway"
//   - "必须通过 Gateway/MiniMax"
//   - "Gateway 不可用"
//   - "Workbench/Gateway transport failed during Add Note organize request."
//
// The two helpers below normalize: every job-message string and the failure
// diagnosis default branch consult the job's effective qualityMode and only
// surface Gateway/MiniMax wording when the user explicitly selected the legacy
// m3-html / m27-html path. Default "minimax-direct" and unresolved modes get
// direct wording. This keeps the legacy Gateway path intact (regression guard
// in scripts/test-knowledge-add-note-direct-runtime.mjs).
function knowledgeNoteJobRequestedMode(job: Partial<KnowledgeNoteOrganizeJob>): string {
  const candidates = [
    String(job.requestedQualityMode || ""),
    String(job.effectiveQualityMode || ""),
    String(job.qualityMode || ""),
  ].map((value) => value.trim()).filter(Boolean);
  if (!candidates.length) return "minimax-direct";
  // Prefer the explicitly requested value, fall back to effective, then
  // declared qualityMode. Empty/missing gets the direct default.
  return candidates[0] || "minimax-direct";
}

function knowledgeNoteJobIsDirect(job: Partial<KnowledgeNoteOrganizeJob>): boolean {
  return knowledgeNoteJobRequestedMode(job) === "minimax-direct";
}

function knowledgeNoteJobDirectLabel(job: Partial<KnowledgeNoteOrganizeJob>): string {
  return knowledgeNoteJobIsDirect(job) ? "MiniMax-M3 直连" : "Gateway/MiniMax";
}

function knowledgeNoteJobDirectReasonLabel(job: Partial<KnowledgeNoteOrganizeJob>): string {
  return knowledgeNoteJobIsDirect(job) ? "MiniMax-M3 直连失败" : "Gateway/MiniMax 整理失败";
}

function knowledgeNoteJobDirectRepairDirective(job: Partial<KnowledgeNoteOrganizeJob>): string {
  return knowledgeNoteJobIsDirect(job)
    ? "不要重启 OpenClaw Gateway"
    : "重新连接 Gateway";
}

function processKnowledgeNoteOrganizeQueue(initial?: { jobId: string; body: KnowledgeNoteOrganizeBody }) {
  if (initial) knowledgeNoteOrganizeJobBodies.set(initial.jobId, initial.body);
  if (knowledgeNoteOrganizeActiveJobId) return;
  const nextId = knowledgeNoteOrganizeQueue.shift();
  if (!nextId) return;
  const nextJob = knowledgeNoteOrganizeJobs.get(nextId);
  const nextBody = knowledgeNoteOrganizeJobBodies.get(nextId);
  if (!nextJob || !nextBody || nextJob.status !== "queued") {
    knowledgeNoteOrganizeJobBodies.delete(nextId);
    processKnowledgeNoteOrganizeQueue();
    return;
  }
  knowledgeNoteOrganizeActiveJobId = nextId;
  const directLabel = knowledgeNoteJobDirectLabel(nextJob);
  updateKnowledgeNoteOrganizeJob(nextJob, {
    status: "running",
    phase: "m3_pipeline",
    message: `正在后台执行 ${directLabel} 整理；其他添加笔记会排队等待，避免模型通道拥塞。`,
  });
  void runKnowledgeNoteOrganizeJob(nextJob, nextBody).finally(() => {
    knowledgeNoteOrganizeActiveJobId = "";
    if (nextJob.status === "succeeded") knowledgeNoteOrganizeJobBodies.delete(nextId);
    processKnowledgeNoteOrganizeQueue();
  });
}

async function runKnowledgeNoteOrganizeJob(job: KnowledgeNoteOrganizeJob, body: KnowledgeNoteOrganizeBody) {
  // 2026-07-05 — Knowledge v2 Add Note real-UI fix: direct-mode jobs must NOT
  // emit "Gateway/MiniMax" status copy. Compute label/reasonLabel/repairDirective
  // from the job's effective qualityMode once and thread them through every
  // status message produced by this run. Legacy m3-html/m27-html still gets
  // "Gateway/MiniMax" wording.
  const directLabel = knowledgeNoteJobDirectLabel(job);
  const directReasonLabel = knowledgeNoteJobDirectReasonLabel(job);
  const directRepairDirective = knowledgeNoteJobDirectRepairDirective(job);
  if (job.status !== "running") {
    updateKnowledgeNoteOrganizeJob(job, {
      status: "running",
      phase: "m3_pipeline",
      message: `正在后台执行 ${directLabel} 整理；如失败会自动进入 Worker 运维恢复后重试。`,
    });
  }
  let lastFailure: ReturnType<typeof buildKnowledgeNoteFailurePayload> | null = null;
  const attemptTimeoutMs = knowledgeNoteOrganizeAttemptTimeoutMs(body);
  for (let jobAttempt = 1; jobAttempt <= KNOWLEDGE_NOTE_ORGANIZE_JOB_END_TO_END_ATTEMPTS; jobAttempt += 1) {
    const attemptController = new AbortController();
    let jobTimedOut = false;
    let retryAfterProactiveOps = false;
    let proactiveRetryReject: ((err: KnowledgeNoteGatewayRequiredError) => void) | null = null;
    let timeoutTimer: ReturnType<typeof setTimeout> | null = null;
    const proactiveRetryPromise = new Promise<never>((_, reject) => {
      proactiveRetryReject = reject;
    });
    const timeoutPromise = new Promise<never>((_, reject) => {
      timeoutTimer = setTimeout(() => {
        jobTimedOut = true;
        attemptController.abort();
        if (job.status === "running") {
          updateKnowledgeNoteOrganizeJob(job, {
            phase: "worker_ops_timeout_recovery",
            message: `本轮${directLabel}整理超过 ${Math.round(attemptTimeoutMs / 1000)}s，已主动中止等待并进入 Worker 运维恢复。`,
          });
        }
        reject(new KnowledgeNoteGatewayRequiredError(
          "knowledge_note_background_wait",
          `background_job_timeout_after_${attemptTimeoutMs}ms`,
          ["local_seed", "m3_background_job_timeout"],
          503,
        ));
      }, attemptTimeoutMs);
    });
    const proactiveOpsTimer = setTimeout(() => {
      if (job.status !== "running") return;
      updateKnowledgeNoteOrganizeJob(job, {
        phase: "worker_ops_shadow_check",
        message: `${directLabel} 整理等待较久，Worker 正在主动执行 shadow 运维巡检；恢复后会中止悬挂请求并自动重试。`,
      });
      void runKnowledgeNoteServerOpsRecovery({
        attempt: jobAttempt,
        stage: "knowledge_note_background_wait",
        reason: `background_job_wait_exceeded_${KNOWLEDGE_NOTE_ORGANIZE_JOB_PROACTIVE_OPS_MS}ms`,
        sourceHash: job.sourceHash,
      }).then((report) => {
        if (job.status !== "running" || jobTimedOut) return;
        const recoveryAttempt = knowledgeNoteOpsRecoveryAttempt(report);
        const lateMarkdownHarvestReady = !body.forceFresh && hasRecoverableKnowledgeNoteMarkdownForJob(job, body, {
          // proactive_ops_recovery 路径在 attemptTimeoutMs（默认 120s）之后才触发，天然是长等待场景：
          // 优先复用 5min 内的同 sourceHash 缓存，避免 6+ 分钟的 LLM 整理白跑。kill switch 由
          // OPENCLAW_WORKBENCH_NOTE_LATE_SAME_HASH_FALLBACK 控制。
          allowRecentSameHashFallback: !body.forceFresh && KNOWLEDGE_NOTE_LATE_SAME_HASH_FALLBACK_ENABLED,
          trigger: "proactive_ops_recovery",
        });
        const shouldAbortForRecoveredRetry = report.retryRecommended
          && jobAttempt < KNOWLEDGE_NOTE_ORGANIZE_JOB_END_TO_END_ATTEMPTS
          && !lateMarkdownHarvestReady;
        updateKnowledgeNoteOrganizeJob(job, {
          phase: lateMarkdownHarvestReady ? "late_m3_markdown_harvest_html_recovery" : shouldAbortForRecoveredRetry ? "worker_ops_recovered_retrying" : "m3_pipeline",
          message: shouldAbortForRecoveredRetry
            ? `Worker shadow 运维巡检确认可恢复，正在中止当前悬挂请求并自动进行第 ${jobAttempt + 1}/${KNOWLEDGE_NOTE_ORGANIZE_JOB_END_TO_END_ATTEMPTS} 轮整理。`
            : lateMarkdownHarvestReady
            ? `Worker shadow 运维巡检发现同一 sourceHash 的 ${directLabel} Markdown 已可回收，保留当前请求并启动 HTML 阶段回收，不再重复重跑 Markdown。`
            : report.retryRecommended
            ? `Worker shadow 运维巡检已完成，但自动重试预算已用尽，继续等待当前 ${directLabel} 结果。`
            : "Worker shadow 运维巡检发现阻塞，继续等待当前模型结果并保留诊断报告。",
          attempts: uniqueKnowledgeNoteAttempts([...job.attempts, recoveryAttempt]),
          debugReports: uniqueStrings([...job.debugReports, report.reportPath || ""].filter(Boolean)),
          opsRecovery: summarizeKnowledgeNoteOpsRecovery([report]),
        });
        if (lateMarkdownHarvestReady) {
          maybeRecoverKnowledgeNoteOrganizeJobFromPoll(job);
        }
        if (shouldAbortForRecoveredRetry) {
          retryAfterProactiveOps = true;
          attemptController.abort();
          proactiveRetryReject?.(new KnowledgeNoteGatewayRequiredError(
            "worker_ops_recovered_retry",
            "ops_recovery_recovered_abort_current_attempt_for_retry",
            ["local_seed", "worker_ops_recovered", "m3_retry_after_ops_recovery"],
            503,
            report.reportPath,
            {
              attempts: uniqueKnowledgeNoteAttempts([...job.attempts, recoveryAttempt]),
              debugReports: uniqueStrings([...job.debugReports, report.reportPath || ""].filter(Boolean)),
              diagnosis: diagnoseKnowledgeNoteFailureForMode("worker_ops_recovered_retry", "ops_recovery_recovered_abort_current_attempt_for_retry", job.qualityMode),
              retryBudget: knowledgeNoteRetryBudget(jobAttempt, KNOWLEDGE_NOTE_ORGANIZE_JOB_END_TO_END_ATTEMPTS),
              opsRecovery: summarizeKnowledgeNoteOpsRecovery([report]),
              nextActions: [
                "Worker 运维恢复已确认，系统已中止当前悬挂请求。",
                `自动进入下一轮 ${directLabel} 整理。`,
              ],
            },
          ));
        }
      }).catch((err) => {
        if (job.status !== "running" || jobTimedOut) return;
        const reason = sanitizePublicError(err instanceof Error ? err.message : String(err));
        updateKnowledgeNoteOrganizeJob(job, {
          phase: "m3_pipeline",
          message: `Worker shadow 运维巡检未完成：${reason}；继续等待 ${directLabel} 整理结果。`,
          attempts: uniqueKnowledgeNoteAttempts([...job.attempts, {
            attempt: jobAttempt,
            stage: "worker_system_ops_recovery",
            strategy: "proactive_shadow_watchdog",
            status: "failed",
            reason,
            repairDirectives: ["保留后台整理任务", `等待 ${directLabel} 当前结果`, "将巡检失败写入 job 状态"],
          }]),
        });
      });
    }, KNOWLEDGE_NOTE_ORGANIZE_JOB_PROACTIVE_OPS_MS);
    try {
      if (jobAttempt > 1) {
        updateKnowledgeNoteOrganizeJob(job, {
          status: "running",
          phase: "m3_pipeline_retry",
          message: `Worker 运维恢复后正在执行第 ${jobAttempt}/${KNOWLEDGE_NOTE_ORGANIZE_JOB_END_TO_END_ATTEMPTS} 轮 ${directLabel} 整理。`,
        });
      }
      const organizePromise = organizeKnowledgeNoteDraftHighQualityWithOpsRecovery(body, { signal: attemptController.signal });
      organizePromise.catch(() => undefined);
      const result = await Promise.race([organizePromise, timeoutPromise, proactiveRetryPromise]);
      if (job.status === "succeeded") return;
      if (timeoutTimer) clearTimeout(timeoutTimer);
      clearTimeout(proactiveOpsTimer);
      const combinedAttempts = uniqueKnowledgeNoteAttempts([
        ...job.attempts,
        ...(Array.isArray((result as { attempts?: unknown }).attempts) ? (result as { attempts: KnowledgeNoteAttempt[] }).attempts : []),
      ]);
      const combinedDebugReports = uniqueStrings([
        ...job.debugReports,
        ...(Array.isArray((result as { debugReports?: unknown }).debugReports) ? (result as { debugReports: string[] }).debugReports : []),
      ]);
      const combinedOpsRecovery = (result as { opsRecovery?: KnowledgeNoteOpsRecoverySummary | null }).opsRecovery || job.opsRecovery || null;
      updateKnowledgeNoteOrganizeJob(job, {
        status: "succeeded",
        phase: "preview_ready",
        message: `${directLabel} 已返回可保存 Markdown 与 HTML，草稿可进入预览。`,
        completedAt: nowIso(),
        result: { ok: true, ...result, attempts: combinedAttempts, debugReports: combinedDebugReports, opsRecovery: combinedOpsRecovery, knowledgeNotePipelineVersion: KNOWLEDGE_NOTE_PIPELINE_VERSION } as Record<string, unknown>,
        attempts: combinedAttempts,
        debugReports: combinedDebugReports,
        diagnosis: (result as { diagnosis?: KnowledgeNoteDiagnosis | null }).diagnosis || null,
        retryBudget: (result as { retryBudget?: KnowledgeNoteRetryBudget | null }).retryBudget || null,
        opsRecovery: combinedOpsRecovery,
      });
      audit(db, "knowledge.note.organize.job.succeeded", "knowledge_note", null, "normal", {
        jobId: job.id,
        title: job.title,
        folder: job.folder,
        sourceHash: job.sourceHash,
        reportPath: job.reportPath,
        jobAttempt,
      });
      return;
    } catch (err) {
      if (timeoutTimer) clearTimeout(timeoutTimer);
      clearTimeout(proactiveOpsTimer);
      if (job.status === "succeeded") return;
      if (retryAfterProactiveOps && jobAttempt < KNOWLEDGE_NOTE_ORGANIZE_JOB_END_TO_END_ATTEMPTS) {
        const proactiveFailure = buildKnowledgeNoteFailurePayload(err);
        updateKnowledgeNoteOrganizeJob(job, {
          status: "queued",
          phase: "queued_after_proactive_ops_recovery",
          message: `Worker 运维恢复已确认，已中止悬挂请求，将自动进行第 ${jobAttempt + 1}/${KNOWLEDGE_NOTE_ORGANIZE_JOB_END_TO_END_ATTEMPTS} 轮 ${directLabel} 整理。`,
          attempts: uniqueKnowledgeNoteAttempts([
            ...job.attempts,
            ...(Array.isArray(proactiveFailure.payload.attempts) ? proactiveFailure.payload.attempts as KnowledgeNoteAttempt[] : []),
          ]),
          debugReports: uniqueStrings([
            ...job.debugReports,
            ...(Array.isArray(proactiveFailure.payload.debugReports) ? proactiveFailure.payload.debugReports as string[] : []),
          ]),
          diagnosis: proactiveFailure.payload.diagnosis as KnowledgeNoteDiagnosis,
          retryBudget: knowledgeNoteRetryBudget(jobAttempt, KNOWLEDGE_NOTE_ORGANIZE_JOB_END_TO_END_ATTEMPTS),
          opsRecovery: (proactiveFailure.payload.opsRecovery as KnowledgeNoteOpsRecoverySummary | null) || job.opsRecovery || null,
          failure: undefined,
        });
        continue;
      }
      const effectiveErr = jobTimedOut
        ? new KnowledgeNoteGatewayRequiredError(
            "knowledge_note_background_wait",
            `background_job_timeout_after_${attemptTimeoutMs}ms`,
            ["local_seed", "m3_background_job_timeout"],
            503,
            undefined,
            {
              attempts: uniqueKnowledgeNoteAttempts([...job.attempts, {
                attempt: jobAttempt,
                stage: "knowledge_note_background_wait",
                strategy: "end_to_end_timeout_abort",
                status: "failed",
                reason: `background_job_timeout_after_${attemptTimeoutMs}ms`,
                repairDirectives: [`中止当前 ${directLabel} 等待`, "执行 Worker 运维 shadow 巡检", "恢复后端到端重试添加笔记"],
              }]),
              diagnosis: diagnoseKnowledgeNoteFailureForMode("knowledge_note_background_wait", "timed out", job.qualityMode),
              retryBudget: knowledgeNoteRetryBudget(jobAttempt, KNOWLEDGE_NOTE_ORGANIZE_JOB_END_TO_END_ATTEMPTS),
              opsRecovery: job.opsRecovery || null,
            },
          )
        : err;
      lastFailure = buildKnowledgeNoteFailurePayload(effectiveErr);
      const failureAttempts = Array.isArray(lastFailure.payload.attempts)
        ? lastFailure.payload.attempts as KnowledgeNoteAttempt[]
        : [];
      const failureDebugReports = Array.isArray(lastFailure.payload.debugReports)
        ? lastFailure.payload.debugReports as string[]
        : [];
      const combinedFailureAttempts = uniqueKnowledgeNoteAttempts([...job.attempts, ...failureAttempts]);
      const combinedFailureDebugReports = uniqueStrings([...job.debugReports, ...failureDebugReports]);
      const shouldRetryAfterOps = jobAttempt < KNOWLEDGE_NOTE_ORGANIZE_JOB_END_TO_END_ATTEMPTS
        && isKnowledgeNoteGatewayRequiredError(lastFailure.failure)
        && shouldRunKnowledgeNoteOpsRecovery(lastFailure.failure);
      updateKnowledgeNoteOrganizeJob(job, {
        phase: jobTimedOut ? "worker_ops_timeout_recovery" : shouldRetryAfterOps ? "worker_ops_failure_recovery" : String(lastFailure.payload.stage || "m3_pipeline_failed"),
        message: shouldRetryAfterOps
          ? `${lastFailure.payload.reasonLabel || (knowledgeNoteJobIsDirect(job) ? `${directReasonLabel}（可恢复）` : `${directReasonLabel}（可恢复）`)}，Worker 将先执行运维恢复，再自动进行第 ${jobAttempt + 1}/${KNOWLEDGE_NOTE_ORGANIZE_JOB_END_TO_END_ATTEMPTS} 轮整理。`
          : `${lastFailure.payload.reasonLabel || (knowledgeNoteJobIsDirect(job) ? `${directLabel} 直连未返回可保存结果` : `${directLabel} 未返回可保存结果`)}：${String(lastFailure.payload.reason || lastFailure.payload.message || "").slice(0, 800)}`,
        attempts: combinedFailureAttempts,
        debugReports: combinedFailureDebugReports,
        diagnosis: lastFailure.payload.diagnosis as KnowledgeNoteDiagnosis,
        retryBudget: knowledgeNoteRetryBudget(jobAttempt, KNOWLEDGE_NOTE_ORGANIZE_JOB_END_TO_END_ATTEMPTS),
        opsRecovery: (lastFailure.payload.opsRecovery as KnowledgeNoteOpsRecoverySummary | null) || job.opsRecovery || null,
        failure: shouldRetryAfterOps ? undefined : lastFailure.payload as Record<string, unknown>,
      });
      if (shouldRetryAfterOps) {
        try {
          const recovery = await runKnowledgeNoteServerOpsRecovery({
            attempt: jobAttempt,
            stage: jobTimedOut ? "knowledge_note_background_timeout" : String(lastFailure.payload.stage || "knowledge_note_gateway_failure"),
            reason: jobTimedOut
              ? `background_job_timeout_after_${attemptTimeoutMs}ms`
              : String(lastFailure.payload.reason || lastFailure.payload.message || "gateway_failure"),
            sourceHash: job.sourceHash,
          });
          const recoveryAttempt = knowledgeNoteOpsRecoveryAttempt(recovery);
          updateKnowledgeNoteOrganizeJob(job, {
            status: "queued",
            phase: "queued_after_ops_recovery",
            message: recovery.retryRecommended
              ? `Worker 运维恢复已执行，添加笔记将自动进行第 ${jobAttempt + 1}/${KNOWLEDGE_NOTE_ORGANIZE_JOB_END_TO_END_ATTEMPTS} 轮整理。`
              : `Worker 运维恢复未确认完全恢复；仍将进行第 ${jobAttempt + 1}/${KNOWLEDGE_NOTE_ORGANIZE_JOB_END_TO_END_ATTEMPTS} 轮整理并保留诊断。`,
            attempts: uniqueKnowledgeNoteAttempts([...job.attempts, recoveryAttempt]),
            debugReports: uniqueStrings([...job.debugReports, recovery.reportPath || ""].filter(Boolean)),
            opsRecovery: summarizeKnowledgeNoteOpsRecovery([recovery]),
          });
        } catch (recoveryErr) {
          const reason = sanitizePublicError(recoveryErr instanceof Error ? recoveryErr.message : String(recoveryErr));
          updateKnowledgeNoteOrganizeJob(job, {
            status: "queued",
            phase: "queued_after_ops_recovery_failed",
            message: `Worker 运维恢复未完成：${reason}；仍将执行最后一次整理重试。`,
            attempts: uniqueKnowledgeNoteAttempts([...job.attempts, {
              attempt: jobAttempt,
              stage: "worker_system_ops_recovery",
              strategy: "timeout_recovery_before_retry",
              status: "failed",
              reason,
              repairDirectives: ["保留后台整理任务", `继续最后一次 ${directLabel} 重试`, "将运维恢复失败写入 job 诊断"],
            }]),
          });
        }
        continue;
      }
      break;
    }
  }

  const failure = (lastFailure || buildKnowledgeNoteFailurePayload(new KnowledgeNoteGatewayRequiredError("knowledge_note_organize", "organize_job_failed_without_failure_payload", ["gateway_required_failed"], 503))).payload;
  const lateRecoveryTimeoutMs = knowledgeNoteOrganizeAttemptTimeoutMs(body);
  let lateRecoveryTimedOut = false;
  let lateRecoveryTimer: ReturnType<typeof setTimeout> | null = null;
  const lateSessionResult = body.forceFresh ? null : await Promise.race([
    recoverKnowledgeNoteOrganizeJobFromLateSessionResult(job, body, failure),
    new Promise<null>((resolve) => {
      lateRecoveryTimer = setTimeout(() => {
        lateRecoveryTimedOut = true;
        resolve(null);
      }, lateRecoveryTimeoutMs);
    }),
  ]).finally(() => {
    if (lateRecoveryTimer) clearTimeout(lateRecoveryTimer);
  }).catch((err) => {
    audit(db, "knowledge.note.organize.job.late_session_recovery.failed", "knowledge_note", null, "warn", {
      jobId: job.id,
      sourceHash: job.sourceHash,
      reason: sanitizePublicError(err instanceof Error ? err.message : String(err)),
    });
    return null;
  });
  if (lateRecoveryTimedOut) {
    audit(db, "knowledge.note.organize.job.late_session_recovery.timeout", "knowledge_note", null, "warn", {
      jobId: job.id,
      sourceHash: job.sourceHash,
      timeoutMs: lateRecoveryTimeoutMs,
      previousStage: failure.stage,
      previousReason: failure.reason,
    });
  }
  if (lateSessionResult) {
    const combinedAttempts = uniqueKnowledgeNoteAttempts([
      ...job.attempts,
      ...(Array.isArray((lateSessionResult as { attempts?: unknown }).attempts) ? (lateSessionResult as { attempts: KnowledgeNoteAttempt[] }).attempts : []),
    ]);
    const combinedDebugReports = uniqueStrings([
      ...job.debugReports,
      ...(Array.isArray((lateSessionResult as { debugReports?: unknown }).debugReports) ? (lateSessionResult as { debugReports: string[] }).debugReports : []),
    ]);
    const combinedOpsRecovery = (lateSessionResult as { opsRecovery?: KnowledgeNoteOpsRecoverySummary | null }).opsRecovery || job.opsRecovery || null;
    updateKnowledgeNoteOrganizeJob(job, {
      status: "succeeded",
      phase: "preview_ready",
      message: `已回收同一 sourceHash 的 ${directLabel} 迟到会话输出，并生成可保存 Markdown 与 HTML 预览。`,
      completedAt: nowIso(),
      result: { ok: true, ...lateSessionResult, attempts: combinedAttempts, debugReports: combinedDebugReports, opsRecovery: combinedOpsRecovery, knowledgeNotePipelineVersion: KNOWLEDGE_NOTE_PIPELINE_VERSION } as Record<string, unknown>,
      attempts: combinedAttempts,
      debugReports: combinedDebugReports,
      diagnosis: (lateSessionResult as { diagnosis?: KnowledgeNoteDiagnosis | null }).diagnosis || null,
      retryBudget: (lateSessionResult as { retryBudget?: KnowledgeNoteRetryBudget | null }).retryBudget || null,
      opsRecovery: combinedOpsRecovery,
      failure: undefined,
    });
    audit(db, "knowledge.note.organize.job.succeeded.late_session_harvest", "knowledge_note", null, "normal", {
      jobId: job.id,
      title: job.title,
      folder: job.folder,
      sourceHash: job.sourceHash,
      reportPath: job.reportPath,
    });
    return;
  }
  const finalReasonLabel = failure.reasonLabel || (knowledgeNoteJobIsDirect(job) ? `${directLabel} 直连未返回可保存结果` : `${directLabel} 未返回可保存结果`);
  updateKnowledgeNoteOrganizeJob(job, {
    status: "failed",
    phase: String(failure.stage || "m3_pipeline_failed"),
    message: `${finalReasonLabel}：${String(failure.reason || failure.message || "").slice(0, 800)}`,
    completedAt: nowIso(),
    failure: failure as Record<string, unknown>,
    attempts: uniqueKnowledgeNoteAttempts([
      ...job.attempts,
      ...(Array.isArray(failure.attempts) ? failure.attempts as KnowledgeNoteAttempt[] : []),
    ]),
    debugReports: uniqueStrings([
      ...job.debugReports,
      ...(Array.isArray(failure.debugReports) ? failure.debugReports as string[] : []),
    ]),
    diagnosis: failure.diagnosis as KnowledgeNoteDiagnosis,
    retryBudget: failure.retryBudget as KnowledgeNoteRetryBudget,
    opsRecovery: (failure.opsRecovery as KnowledgeNoteOpsRecoverySummary | null) || job.opsRecovery || null,
  });
  audit(db, "knowledge.note.organize.job.failed", "knowledge_note", null, "warn", {
    jobId: job.id,
    sourceHash: job.sourceHash,
    stage: failure.stage,
    reason: failure.reason,
    reasonLabel: failure.reasonLabel,
    retryable: failure.retryable,
    reportPath: job.reportPath,
    debugReports: failure.debugReports,
  });
}

function shouldProbeKnowledgeNoteOrganizeJobLateRecovery(job: KnowledgeNoteOrganizeJob) {
  if (job.status === "succeeded" || job.status === "aborted") return false;
  if (knowledgeNoteOrganizeLateRecoveryInFlight.has(job.id)) return false;
  if (!knowledgeNoteOrganizeJobBodies.has(job.id)) return false;
  if (job.status === "failed") return true;
  const ageMs = Date.now() - (Date.parse(job.createdAt || "") || Date.now());
  if (ageMs >= KNOWLEDGE_NOTE_ORGANIZE_JOB_POLL_RECOVERY_MIN_AGE_MS) return true;
  if (job.attempts.length > 0) return true;
  return /worker_ops|timeout|retry|recovery/i.test(job.phase || "");
}

function maybeRecoverKnowledgeNoteOrganizeJobFromPoll(job: KnowledgeNoteOrganizeJob) {
  if (!shouldProbeKnowledgeNoteOrganizeJobLateRecovery(job)) return;
  const body = knowledgeNoteOrganizeJobBodies.get(job.id);
  if (!body) return;
  if (body.forceFresh) return;
  knowledgeNoteOrganizeLateRecoveryInFlight.add(job.id);
  void (async () => {
    const failure = job.failure || {
      stage: job.phase || "knowledge_note_background_wait",
      reason: job.message || "poll_triggered_late_session_recovery",
      message: job.message || "",
    };
    // job_status_poll 路径：fresh job（< 5s、0 attempts、running）保守用 job_window；任何已发生重试 / 处于
    // timeout-recovery 阶段 / 显式 failed 的 job，放开 recent-same-hash 回收。kill switch 走
    // OPENCLAW_WORKBENCH_NOTE_LATE_SAME_HASH_FALLBACK。
    const isLongWaitPollContext = job.attempts.length > 0
      || job.status === "failed"
      || /worker_ops|timeout|retry|recovery/i.test(job.phase || "");
    const result = await recoverKnowledgeNoteOrganizeJobFromLateSessionResult(job, body, failure, {
      allowRecentSameHashFallback: isLongWaitPollContext && !body.forceFresh && KNOWLEDGE_NOTE_LATE_SAME_HASH_FALLBACK_ENABLED,
      trigger: "job_status_poll",
    });
    if (!result || job.status === "succeeded") return;
    completeKnowledgeNoteOrganizeJobWithLateSessionResult(
      job,
      result,
      "轮询状态时已回收同一 sourceHash 的 MiniMax-M3 输出，并生成可保存 Markdown 与 HTML 预览。",
      "knowledge.note.organize.job.succeeded.poll_late_session_harvest",
    );
  })().catch((err) => {
    audit(db, "knowledge.note.organize.job.poll_late_session_recovery.failed", "knowledge_note", null, "warn", {
      jobId: job.id,
      sourceHash: job.sourceHash,
      reason: sanitizePublicError(err instanceof Error ? err.message : String(err)),
    });
  }).finally(() => {
    knowledgeNoteOrganizeLateRecoveryInFlight.delete(job.id);
  });
}

function completeKnowledgeNoteOrganizeJobWithLateSessionResult(
  job: KnowledgeNoteOrganizeJob,
  lateSessionResult: Record<string, unknown>,
  message: string,
  auditAction: string,
) {
  const combinedAttempts = uniqueKnowledgeNoteAttempts([
    ...job.attempts,
    ...(Array.isArray(lateSessionResult.attempts) ? lateSessionResult.attempts as KnowledgeNoteAttempt[] : []),
  ]);
  const combinedDebugReports = uniqueStrings([
    ...job.debugReports,
    ...(Array.isArray(lateSessionResult.debugReports) ? lateSessionResult.debugReports as string[] : []),
  ]);
  const combinedOpsRecovery = (lateSessionResult.opsRecovery as KnowledgeNoteOpsRecoverySummary | null) || job.opsRecovery || null;
  updateKnowledgeNoteOrganizeJob(job, {
    status: "succeeded",
    phase: "preview_ready",
    message,
    completedAt: nowIso(),
    result: { ok: true, ...lateSessionResult, attempts: combinedAttempts, debugReports: combinedDebugReports, opsRecovery: combinedOpsRecovery, knowledgeNotePipelineVersion: KNOWLEDGE_NOTE_PIPELINE_VERSION } as Record<string, unknown>,
    attempts: combinedAttempts,
    debugReports: combinedDebugReports,
    diagnosis: (lateSessionResult.diagnosis as KnowledgeNoteDiagnosis | null) || null,
    retryBudget: (lateSessionResult.retryBudget as KnowledgeNoteRetryBudget | null) || null,
    opsRecovery: combinedOpsRecovery,
    failure: undefined,
  });
  knowledgeNoteOrganizeJobBodies.delete(job.id);
  audit(db, auditAction, "knowledge_note", null, "normal", {
    jobId: job.id,
    title: job.title,
    folder: job.folder,
    sourceHash: job.sourceHash,
    reportPath: job.reportPath,
  });
}

function hasRecoverableKnowledgeNoteMarkdownForJob(
  job: KnowledgeNoteOrganizeJob,
  inputBody: KnowledgeNoteOrganizeBody,
  options: { allowRecentSameHashFallback?: boolean; trigger?: string } = {},
) {
  const body = normalizeKnowledgeNoteOrganizeBody(inputBody);
  const rawContent = knowledgeNoteRawContent(body);
  const sourceHash = createHash("sha256").update(rawContent).digest("hex");
  if (!sourceHash || sourceHash !== job.sourceHash) return false;
  const seed = organizeKnowledgeNoteDraft(body);
  const sourceProfile = knowledgeNoteSourceProfile(rawContent, body);
  const agentDecision = decideKnowledgeNoteAgent({ ...body, type: body.type || seed.type, title: body.title || seed.title, rawContent: body.rawContent });
  const sinceMs = Math.max(0, Date.parse(job.createdAt || "") - 5000 || Date.now() - 30 * 60_000);
  let harvest = recoverKnowledgeNoteGatewayFinalBySourceHash({
    purpose: "markdown",
    sourceHash,
    sinceMs,
    preferredAgent: agentDecision.chosenAgent,
    requirePromptMarker: KNOWLEDGE_NOTE_GATEWAY_PROMPT_VERSION,
  });
  if (!harvest && options.allowRecentSameHashFallback) {
    harvest = recoverKnowledgeNoteGatewayFinalBySourceHash({
      purpose: "markdown",
      sourceHash,
      sinceMs: Math.max(0, Date.now() - KNOWLEDGE_NOTE_RECENT_SOURCE_HASH_HARVEST_MS),
      preferredAgent: agentDecision.chosenAgent,
      requirePromptMarker: KNOWLEDGE_NOTE_GATEWAY_PROMPT_VERSION,
    });
  }
  if (!harvest) return false;
  const parsed = parseKnowledgeNoteGatewayJson(harvest.text) || extractKnowledgeNoteGatewayDraftObject({ final: harvest.text });
  if (!parsed) return false;
  const normalized = normalizeGatewayKnowledgeDraft(parsed, seed, agentDecision);
  const sourceCheck = validateGatewayKnowledgeDraftSource(parsed, normalized.draft, seed, rawContent, sourceHash);
  if (sourceCheck.ok) return true;
  return false;
}

async function recoverKnowledgeNoteOrganizeJobFromLateSessionResult(
  job: KnowledgeNoteOrganizeJob,
  inputBody: KnowledgeNoteOrganizeBody,
  failure: Record<string, unknown>,
  options: { allowRecentSameHashFallback?: boolean; trigger?: string } = {},
) {
  const body = normalizeKnowledgeNoteOrganizeBody(inputBody);
  const rawContent = knowledgeNoteRawContent(body);
  const sourceHash = createHash("sha256").update(rawContent).digest("hex");
  if (!sourceHash || sourceHash !== job.sourceHash) return null;
  const seed = organizeKnowledgeNoteDraft(body);
  const sourceProfile = knowledgeNoteSourceProfile(rawContent, body);
  const agentDecision = decideKnowledgeNoteAgent({ ...body, type: body.type || seed.type, title: body.title || seed.title, rawContent: body.rawContent });
  const promptProfile = resolveKnowledgeNotePromptProfile(body, rawContent, sourceProfile);
  const sinceMs = Math.max(0, Date.parse(job.createdAt || "") - 5000 || Date.now() - 30 * 60_000);
  let harvestMode = "job_window";
  let harvestSinceMs = sinceMs;
  let harvest = recoverKnowledgeNoteGatewayFinalBySourceHash({
    purpose: "markdown",
    sourceHash,
    sinceMs,
    preferredAgent: agentDecision.chosenAgent,
    requirePromptMarker: KNOWLEDGE_NOTE_GATEWAY_PROMPT_VERSION,
  });
  if (!harvest && options.allowRecentSameHashFallback) {
    harvestMode = "recent_same_source_hash";
    harvestSinceMs = Math.max(0, Date.now() - KNOWLEDGE_NOTE_RECENT_SOURCE_HASH_HARVEST_MS);
    harvest = recoverKnowledgeNoteGatewayFinalBySourceHash({
      purpose: "markdown",
      sourceHash,
      sinceMs: harvestSinceMs,
      preferredAgent: agentDecision.chosenAgent,
      requirePromptMarker: KNOWLEDGE_NOTE_GATEWAY_PROMPT_VERSION,
    });
  }
  if (!harvest) return null;
  const parsed = parseKnowledgeNoteGatewayJson(harvest.text) || extractKnowledgeNoteGatewayDraftObject({ final: harvest.text });
  if (!parsed) return null;
  const gatewayRunId = safeName(job.id || randomUUID()).slice(0, 12) || randomUUID().slice(0, 12);
  const debugReportPath = writeKnowledgeNoteGatewayDebugReport({
    stage: "m3_obsidian_markdown",
    reason: "late_m3_session_source_hash_harvest",
    sourceHash,
    runId: gatewayRunId,
    promptProfile,
    repairAttempt: 0,
    gatewayText: harvest.text,
    gatewayData: {
      recoveredAgentId: harvest.agentId,
      recoveredSessionKey: harvest.sessionKey,
      recoveredSessionId: harvest.sessionId,
      transcriptPath: harvest.transcriptPath,
      harvestMode,
      harvestTrigger: options.trigger || "job_final_failure",
      harvestSince: new Date(harvestSinceMs).toISOString(),
      previousFailure: {
        stage: failure.stage,
        reason: failure.reason,
      },
    },
  });
  let markdownResult: KnowledgeNoteMarkdownGatewayResult = {
    gatewayAttempt: {
      gateway: knowledgeNoteGatewayResultFromLateHarvest(harvest),
      execution: {
        roleAgent: agentDecision.chosenAgent,
        executionAgent: harvest.agentId,
        reason: "late_m3_session_source_hash_harvest",
        rerouteReason: `${harvestMode}:${String(failure.reason || failure.message || "background_failure_before_final_delivery").slice(0, 260)}`,
        sessionKey: harvest.sessionKey,
      },
    },
    parsed,
    normalized: normalizeGatewayKnowledgeDraft(parsed, seed, agentDecision),
    sourceCheck: { ok: false, reason: "" },
    repaired: false,
    debugReportPath,
  };
  markdownResult.sourceCheck = validateGatewayKnowledgeDraftSource(parsed, markdownResult.normalized.draft, seed, rawContent, sourceHash);
  const attempts: KnowledgeNoteAttempt[] = [{
    attempt: KNOWLEDGE_NOTE_ORGANIZE_JOB_END_TO_END_ATTEMPTS,
    stage: "m3_obsidian_markdown",
    strategy: "late_m3_session_source_hash_harvest",
    status: markdownResult.sourceCheck.ok ? "passed" : "failed",
    reason: markdownResult.sourceCheck.ok ? undefined : markdownResult.sourceCheck.reason,
    repairDirectives: [
      "回收 OpenClaw session 中同一 sourceHash 的 MiniMax-M3 最终输出。",
      "继续执行既有 source-hash 与内容质量门槛。",
      "不启用本地 fallback，不把非 MiniMax 内容伪装为成功。",
    ],
    debugReportPath,
    confidence: Number(markdownResult.normalized.quality?.confidence || 0) || undefined,
  }];
  if (!markdownResult.sourceCheck.ok) return null;
  const retryBudget = knowledgeNoteRetryBudget(KNOWLEDGE_NOTE_ORGANIZE_JOB_END_TO_END_ATTEMPTS, KNOWLEDGE_NOTE_ORGANIZE_JOB_END_TO_END_ATTEMPTS);
  const timeoutMs = knowledgeNoteOrganizeAttemptTimeoutMs(body);
  const htmlResult = await generateKnowledgeNoteM3Html({
    input: body,
    sourceHash,
    gatewayRunId,
    agentDecision: markdownResult.normalized.agentDecision,
    draft: markdownResult.normalized.draft,
    layoutStrategy: markdownResult.normalized.layoutStrategy,
    quality: markdownResult.normalized.quality,
    timeoutMs,
    priorAttempts: attempts,
    retryBudget,
    harvestSinceMs,
  });
  const pipeline = [
    "local_seed",
    "m3_obsidian_markdown",
    harvestMode === "recent_same_source_hash" ? "m3_recent_source_hash_reuse" : "m3_late_session_source_hash_harvest",
  ];
  return {
    knowledgeNotePipelineVersion: KNOWLEDGE_NOTE_PIPELINE_VERSION,
    qualityMode: "m3-html",
    draft: markdownResult.normalized.draft,
    layoutStrategy: markdownResult.normalized.layoutStrategy,
    agentDecision: markdownResult.normalized.agentDecision,
    quality: markdownResult.normalized.quality,
    htmlDraft: htmlResult.htmlDraft,
    htmlQuality: htmlResult.htmlQuality,
    generationPipeline: [...pipeline, ...htmlResult.generationPipeline],
    attempts: [...attempts, ...(htmlResult.attempts || [])],
    diagnosis: null,
    retryBudget,
    debugReports: knowledgeNoteDebugReports([...attempts, ...(htmlResult.attempts || [])]),
    nextActions: [
      "已回收迟到 MiniMax-M3 会话输出并进入预览。",
      "后续继续监控 Gateway final delivery，避免只依赖 session harvest。",
    ],
    fallbackReason: "",
    gatewayExecution: markdownResult.gatewayAttempt.execution,
    htmlGatewayExecution: (htmlResult as { gatewayExecution?: KnowledgeNoteGatewayExecution }).gatewayExecution,
    opsRecovery: job.opsRecovery || null,
    staleRuntimeError: false,
  };
}

function knowledgeNoteFailureDetails(reason: string) {
  const text = String(reason || "");
  if (/gateway_preflight/.test(text)) {
    return {
      reasonLabel: "Gateway 当前不可用",
      retryable: true,
      advice: "Workbench 已在整理前短路，避免继续等待 MiniMax。请等待底部 Gateway 状态恢复 connected 后重试；不会启用本地 fallback。",
    };
  }
  if (/Service not installed|Could not find service|not loaded|LaunchAgent not loaded|com\.clawdbot\.gateway/i.test(text)) {
    return {
      reasonLabel: "Gateway 服务未安装/未加载",
      retryable: true,
      advice: "请先调用系统恢复接口 `/api/system/gateway/recover`（可返回恢复步骤），确认网关恢复 connected 后再重试。若仍失败再手动执行 `openclaw-cn gateway install` 与 `openclaw-cn gateway start`。",
    };
  }
  if (/Failed to inspect sandbox image|docker API|docker\.sock|orbstack|Cannot connect to Docker|daemon is running/i.test(text)) {
    return {
      reasonLabel: "Gateway agent 执行环境未就绪",
      retryable: true,
      advice: "请先启动 OrbStack/Docker，确认 /Users/njx/.orbstack/run/docker.sock 可用后重试；系统不会启用本地 fallback。",
    };
  }
  if (/low_value_or_noisy_summary/.test(text)) {
    return {
      reasonLabel: "模型整理结果仍像口语转写或缺少价值结构",
      retryable: true,
      advice: "已要求 MiniMax 去口语、提炼判断、补齐证据和行动项；如果仍失败，请补充上下文或减少无关闲聊。",
    };
  }
  if (/insufficient_topic_coverage/.test(text)) {
    return {
      reasonLabel: "模型未覆盖原文主要主题",
      retryable: true,
      advice: "建议保留完整原文，避免只粘贴片段；系统会要求 MiniMax 重新补齐主题覆盖。",
    };
  }
  if (/gateway_returned_non_json/.test(text)) {
    return {
      reasonLabel: "MiniMax 输出不是可解析 JSON",
      retryable: true,
      advice: "系统已尝试格式修复；请直接重试。若持续失败，查看 debug report 中的模型原始返回，通常是模型输出了说明文字、空回复或旧会话内容。",
    };
  }
  if (/html_gateway_returned_markdown_stage_output/.test(text)) {
    return {
      reasonLabel: "HTML 阶段误收 Markdown 输出",
      retryable: true,
      advice: "Workbench 会阻止保存，并要求 Worker 诊断 Gateway/会话回收后只重派 HTML 阅读层；不会把 Markdown 伪装成 HTML 成功。",
    };
  }
  if (isRecoverableGatewayFinalError(text)) {
    return {
      reasonLabel: "Gateway 连接提前关闭",
      retryable: true,
      advice: "系统会先尝试从同一代理会话恢复已生成文本，再要求用户重试；当前不会启用本地 fallback。",
    };
  }
  if (/gateway.*timeout|timed out|unavailable|ETIMEDOUT/i.test(text)) {
    return {
      reasonLabel: "Gateway 或 MiniMax 等待超时",
      retryable: true,
      advice: "请稍后重试；当前流程不会用本地 fallback 伪生成笔记。",
    };
  }
  if (/source_mismatch|not_supported/.test(text)) {
    return {
      reasonLabel: "模型输出与原文证据不一致",
      retryable: false,
      advice: "系统已阻止保存，避免把可靠性会、安委会、MBA 等主题串写。",
    };
  }
  if (/html_quality_gate/.test(text)) {
    return {
      reasonLabel: "HTML 阅读层未过质量门槛",
      retryable: true,
      advice: "Markdown 可信源已经通过，系统会要求 MiniMax 重做阅读层；低信息密度记录不会再强套大报告模板。",
    };
  }
  return {
    reasonLabel: "Gateway/MiniMax 未返回可保存结果",
    retryable: true,
    advice: "请重试；若持续失败，检查 Gateway 状态或粘贴更完整的上下文。",
  };
}

// 2026-07-05 — diagnoseKnowledgeNoteFailure(): when called for a job whose
// effective qualityMode is the default direct path, the gateway-only category
// ("Gateway 不可用") and repair directive ("重新连接 Gateway") must be replaced
// with direct-mode copy. The fallback advice ("检查 Gateway 状态") must not
// mislead the user into restarting OpenClaw Gateway when the real cause is
// missing MiniMax API key / network failure of the direct call. Legacy
// m3-html/m27-html continues to use the original copy.
function diagnoseKnowledgeNoteFailureForMode(
  stage: string,
  reason: string,
  effectiveQualityMode?: string,
): KnowledgeNoteDiagnosis {
  const base = diagnoseKnowledgeNoteFailure(stage, reason);
  const text = String(reason || "");
  // Direct-mode failures are detected via stage prefix or reason prefix; this
  // mirrors buildKnowledgeNoteFailurePayload's isDirectMinimaxFailure check.
  const isDirectJob = String(effectiveQualityMode || "").trim() === "minimax-direct";
  const isDirectFailureByMarker = String(stage || "").startsWith("minimax_direct")
    || /^BLOCKED_MINIMAX_DIRECT_CONFIG|^minimax_direct/.test(text);
  if (!(isDirectJob || isDirectFailureByMarker)) return base;
  // Override the gateway copy only on the specific gateway-availability paths
  // and the default fallback; the content-quality paths (returned_non_json,
  // html_quality_gate, etc.) are mode-agnostic and stay as-is.
  const gatewayOnly = [
    /gateway_preflight|gateway_unavailable|timed out|timeout|timeout_after|background_job_timeout|m3_background_job_timeout|ECONNRESET|ETIMEDOUT|gateway_closed|OpenClaw Gateway CLI/i,
    /gateway.*timeout|gateway\/MiniMax 未返回可保存结果|重新连接 Gateway|Gateway 不可用/i,
  ].some((rx) => rx.test(text))
    || base.category === "Gateway 不可用"
    || base.reasonLabel === "Gateway/MiniMax 未返回可保存结果"
    || /^Gateway|MiniMax\s+未返回可保存结果|Gateway\s+或\s+MiniMax\s+等待超时/.test(base.reasonLabel || "");
  if (!gatewayOnly) return base;
  const isConfigMissing = /BLOCKED_MINIMAX_DIRECT_CONFIG|minimax API key not found|API key reference set but key value not exposed/i.test(text);
  return {
    ...base,
    category: isConfigMissing ? "MiniMax API key 未配置" : "MiniMax-M3 直连失败",
    reasonLabel: isConfigMissing
      ? "MiniMax API key 未配置（不降级到 Gateway）"
      : (base.reasonLabel && base.reasonLabel !== "Gateway/MiniMax 未返回可保存结果")
        ? base.reasonLabel.replace(/^Gateway\/MiniMax\s+/, "MiniMax-M3 直连 ")
        : "MiniMax-M3 直连失败（不降级到 Gateway）",
    rootCause: isConfigMissing
      ? "minimax-direct 模式下, MINIMAX_API_KEY / OPENCLAW_MINIMAX_API_KEY / model_configs 中未发现 MiniMax API key."
      : (base.rootCause && /已到达\s+Gateway\/MiniMax\s+通道/.test(base.rootCause))
        ? "minimax-direct 直连调用失败, 不是 OpenClaw Gateway 通道问题, 不要重启 Gateway."
        : base.rootCause,
    userAction: isConfigMissing
      ? "请在 Workbench 模型配置或环境变量中设置 MiniMax API key 后再整理."
      : (base.userAction && /Gateway\s+状态恢复\s+connected/.test(base.userAction))
        ? "请检查 MiniMax API key / baseUrl / 网络后重试; 若需 Gateway 链路, 显式切换 qualityMode 为 m3-html (legacy)."
        : base.userAction,
    repairDirectives: [
      "不要重启 OpenClaw Gateway",
      "检查 MiniMax API key / model_configs / baseUrl",
      "切换 m3-html Gateway 路径需用户显式选择",
    ],
    advice: isConfigMissing
      ? "minimax-direct 模式下不做 Gateway 隐式 fallback. 请配置 MiniMax API key, 或在 UI 显式切换 qualityMode=m3-html (legacy)."
      : "minimax-direct 模式下不做 Gateway 隐式 fallback. 若需 Gateway 路径, 请在 UI 显式将 qualityMode 切换为 m3-html (legacy).",
    nextActions: isConfigMissing
      ? ["配置 MiniMax API key", "或在 UI 切换 qualityMode 为 m3-html (Gateway)"]
      : ["检查 MiniMax API key / model_configs", "或在 UI 切换 qualityMode 为 m3-html (Gateway, legacy)"],
  };
}

function diagnoseKnowledgeNoteFailure(stage: string, reason: string): KnowledgeNoteDiagnosis {
  const text = String(reason || "");
  if (/gateway_preflight|gateway_unavailable|timed out|timeout|timeout_after|background_job_timeout|m3_background_job_timeout|ECONNRESET|ETIMEDOUT|gateway_closed|OpenClaw Gateway CLI/i.test(text)) {
    return {
      category: "Gateway 不可用",
      rootCause: "Workbench 已到达 Gateway/MiniMax 通道，但连接、队列或最终输出等待失败；这不是内容质量问题。",
      retryable: true,
      userAction: "等待底部 Gateway 状态恢复 connected 后重试；不要启用本地 fallback。",
      repairDirectives: ["重新连接 Gateway", "保持原始笔记和元数据不变", "重试时继续要求 MiniMax 返回结构化 Markdown 与 HTML"],
      nextActions: ["检查 Gateway 状态", "稍后重试添加笔记", "若连续超时，查看 debug report 和 Gateway 队列"],
    };
  }
  if (/returned_non_json|不是可解析 JSON|non_json/i.test(text)) {
    return {
      category: "模型输出格式错误",
      rootCause: "MiniMax 返回了说明文字、代码块外文本、截断内容或不合法 JSON，Workbench 无法安全解析为可信 Markdown。",
      retryable: true,
      userAction: "自动修复会要求模型只返回严格 JSON；若仍失败，请减少输入长度或拆成更短的笔记。",
      repairDirectives: ["只返回一个严格 JSON 对象", "draft.markdown 内换行必须转义", "不要输出解释文字、代码块、思考过程或工具调用结果"],
      nextActions: ["自动执行格式修复", "查看 debug report 中的模型原始返回", "必要时缩短原文后重试"],
    };
  }
  if (/html_gateway_returned_non_html|html_gateway_returned_markdown_stage_output|html_source_hash_mismatch|html_generation_failed/i.test(text)) {
    return {
      category: "HTML 质量失败",
      rootCause: /html_gateway_returned_markdown_stage_output/i.test(text)
        ? "可信 Markdown 已生成，但 HTML 阶段收到的是 Markdown 阶段 JSON；这通常是 Gateway 会话回收或错阶段复用导致的。"
        : "可信 Markdown 已生成，但 MiniMax 没有返回可保存的离线 HTML 或 HTML 与当前 sourceHash 不一致。",
      retryable: true,
      userAction: "自动修复会要求模型只重做 HTML，不改变事实；若仍失败，请保留 Markdown 并重试 HTML 阶段。",
      repairDirectives: ["只返回包含 sourceHash、title、html、htmlQuality 的严格 JSON", "html 字段必须是完整离线 HTML", "不要改变 Markdown 中的事实和行动项"],
      nextActions: ["自动重做 HTML 阅读层", "查看 HTML debug report", "若多次失败，降低原文长度或拆分主题"],
    };
  }
  if (/html_quality_gate|quality_failed|first_screen_raw_or_noisy_transcript/i.test(text)) {
    return {
      category: "HTML 质量失败",
      rootCause: "HTML 已生成但没有达到首屏可读、证据可追溯或噪声控制要求。",
      retryable: true,
      userAction: "自动修复会要求模型重做首屏结构、证据入口和噪声控制。",
      repairDirectives: ["首屏必须出现核心判断、高价值摘要、行动项和证据入口", "不要把原始口语转写放在首屏", "source-hash 必须在证据入口可见"],
      nextActions: ["自动执行 HTML 质量修复", "查看质量维度分数", "仍失败时减少原文闲聊或拆分长记录"],
    };
  }
  if (/insufficient_topic_coverage/i.test(text)) {
    return {
      category: "主题覆盖不足",
      rootCause: "MiniMax 草稿遗漏了原文中被检测到的关键主题，保存会造成知识笔记偏题或缺项。",
      retryable: true,
      userAction: "自动修复会补齐缺失主题；若仍失败，请在原文前补充核心议题列表。",
      repairDirectives: ["补齐主题覆盖清单", "每个主题必须有原文证据短句", "高价值摘要必须整合缺失主题而不是只堆标签"],
      nextActions: ["自动执行主题覆盖修复", "补充会议主题或项目背景", "删减与主题无关的长闲聊"],
    };
  }
  if (/low_value_or_noisy_summary/i.test(text)) {
    return {
      category: "内容质量门槛未过",
      rootCause: "MiniMax 输出仍像口语转写，或缺少可复用判断、证据、行动项和低信息密度说明。",
      retryable: true,
      userAction: "自动修复会要求模型去口语、提炼判断、补齐证据和行动项；若仍失败，请补充上下文或减少无关闲聊。",
      repairDirectives: ["去除口语、脏话、重复寒暄和时间戳转写", "补齐高价值摘要、关键判断、证据锚点、行动项、待核验", "信息密度低时明确写低信息密度判断，不编造高价值内容"],
      nextActions: ["自动执行价值结构修复", "补充会议背景、目标、决策对象", "删减无关闲聊后重试"],
    };
  }
  if (/sanitize|安全清洗/i.test(text)) {
    return {
      category: "安全清洗失败",
      rootCause: "生成结果包含不允许保存的 HTML、脚本、事件属性或不安全结构。",
      retryable: true,
      userAction: "自动修复会要求模型输出纯静态 HTML。",
      repairDirectives: ["禁止 script、iframe、form 和事件属性", "只保留静态阅读结构", "不要使用外部资源"],
      nextActions: ["自动执行安全清洗修复", "查看被拦截的 HTML 结构", "必要时重新生成 HTML"],
    };
  }
  return {
    category: "模型整理失败",
    rootCause: "Workbench 未能把当前 Gateway/MiniMax 返回安全转成可保存的 Markdown 与 HTML。",
    retryable: true,
    userAction: "请查看诊断详情；若连续失败，请补充上下文、缩短原文或稍后重试。",
    repairDirectives: ["保持 sourceHash 不变", "只依据原文整理", "输出可解析 Markdown JSON 与完整 HTML"],
    nextActions: ["自动重试一次", "查看 debug report", "补充上下文后重试"],
  };
}

function knowledgeNoteAttemptStrategy(attempt: number, reason = "") {
  if (attempt <= 0) return "normal";
  if (attempt === 1 && isInsufficientKnowledgeNoteTopicCoverageReason(reason)) return "topic_coverage_repair";
  if (attempt === 1) return "de_noisy_value_repair";
  if (attempt === 2 && isInsufficientKnowledgeNoteTopicCoverageReason(reason)) return "topic_coverage_repair";
  if (attempt === 2) return "strict_value_structure_repair";
  return "source_reduction_context_repair";
}

function knowledgeNoteRepairDirectivesForAttempt(reason: string, attempt: number) {
  const diagnosis = diagnoseKnowledgeNoteFailure("m3_obsidian_markdown", reason);
  if (attempt <= 1) return diagnosis.repairDirectives;
  if (attempt === 2) {
    return [
      "强制补齐高价值摘要、关键判断、证据锚点、行动项、待核验、低信息密度说明",
      "不要把说话人时间戳或原始闲聊放进首屏摘要",
      "每个判断必须能回到原文证据；证据不足时明确写待核验",
    ];
  }
  return [
    "只保留可证实核心议题，压缩无关寒暄和重复闲聊",
    "信息不足时给出低信息密度判断与需要用户补充的上下文清单",
    "不得为了通过质量门槛编造未出现的项目、会议或行动项",
  ];
}

function knowledgeNoteDebugReports(attempts: KnowledgeNoteAttempt[], extra = "") {
  return uniqueStrings([
    extra,
    ...attempts.map((attempt) => attempt.debugReportPath || ""),
  ].filter(Boolean));
}

function knowledgeNoteRetryBudget(used: number, max: number): KnowledgeNoteRetryBudget {
  return { used, max, exhausted: used >= max };
}

function knowledgeNoteFailureExtras(
  stage: string,
  reason: string,
  attempts: KnowledgeNoteAttempt[],
  retryBudget: KnowledgeNoteRetryBudget,
  debugReportPath = "",
  opsRecovery: KnowledgeNoteOpsRecoverySummary | null = null,
): KnowledgeNoteFailureExtras {
  const diagnosis = diagnoseKnowledgeNoteFailure(stage, reason);
  const debugReports = knowledgeNoteDebugReports(attempts, debugReportPath);
  return {
    attempts,
    diagnosis,
    retryBudget,
    debugReports,
    nextActions: diagnosis.nextActions,
    opsRecovery,
  };
}

async function organizeKnowledgeNoteDraftHighQualityWithOpsRecovery(input: KnowledgeNoteOrganizeBody, options: { signal?: AbortSignal } = {}) {
  const body = normalizeKnowledgeNoteOrganizeBody(input);
  const maxOpsAttempts = body.retryPolicy?.autoRepair === false ? 0 : KNOWLEDGE_NOTE_SERVER_OPS_MAX_ATTEMPTS;
  const sourceHash = createHash("sha256").update(knowledgeNoteRawContent(body)).digest("hex");
  const opsAttempts: KnowledgeNoteAttempt[] = [];
  const opsReports: KnowledgeNoteOpsRecoveryReport[] = [];

  for (let opsAttempt = 0; opsAttempt <= maxOpsAttempts; opsAttempt += 1) {
    throwIfSignalAborted(options.signal);
    try {
      const result = await organizeKnowledgeNoteDraftHighQuality(body, options);
      const opsRecovery = summarizeKnowledgeNoteOpsRecovery(opsReports);
      return {
        ...result,
        attempts: [...opsAttempts, ...(Array.isArray(result.attempts) ? result.attempts : [])],
        debugReports: uniqueStrings([
          ...(Array.isArray(result.debugReports) ? result.debugReports : []),
          ...opsReports.map((report) => report.reportPath || ""),
        ].filter(Boolean)),
        opsRecovery,
        nextActions: opsRecovery ? uniqueStrings([...(result.nextActions || []), ...opsRecovery.nextActions]) : result.nextActions,
      };
    } catch (err) {
      if (!isKnowledgeNoteGatewayRequiredError(err)) throw err;
      if (options.signal?.aborted || !shouldRunKnowledgeNoteOpsRecovery(err) || opsAttempt >= maxOpsAttempts) {
        throwKnowledgeNoteGatewayFailureWithOps(err, opsAttempts, opsReports);
      }
      const recovery = await runKnowledgeNoteServerOpsRecovery({
        attempt: opsAttempt + 1,
        stage: err.stage,
        reason: err.reason,
        sourceHash,
        signal: options.signal,
      });
      opsReports.push(recovery);
      opsAttempts.push(knowledgeNoteOpsRecoveryAttempt(recovery));
      if (!recovery.retryRecommended) throwKnowledgeNoteGatewayFailureWithOps(err, opsAttempts, opsReports);
      await sleep(Math.min(8000, 1500 * (opsAttempt + 1)), options.signal);
    }
  }

  failKnowledgeNoteGateway("knowledge_note_organize", "ops_recovery_loop_exhausted", ["local_seed", "worker_ops_recovery_failed"], 503, undefined, {
    attempts: opsAttempts,
    diagnosis: diagnoseKnowledgeNoteFailure("knowledge_note_organize", "ops_recovery_loop_exhausted"),
    retryBudget: knowledgeNoteRetryBudget(maxOpsAttempts, maxOpsAttempts),
    debugReports: opsReports.map((report) => report.reportPath || "").filter(Boolean),
    opsRecovery: summarizeKnowledgeNoteOpsRecovery(opsReports),
  });
}

function shouldRunKnowledgeNoteOpsRecovery(err: KnowledgeNoteGatewayRequiredError) {
  const text = `${err.stage || ""} ${err.reason || ""}`;
  if (/low_value_or_noisy_summary|insufficient_topic_coverage|source_mismatch|not_supported|html_quality_gate/i.test(text)) {
    return false;
  }
  return /gateway_preflight|gateway_unavailable|gateway_transport_first_failed|gateway_transport_retry_failed|html_gateway_unavailable|html_gateway_returned_non_html|html_gateway_returned_markdown_stage_output|gateway_returned_non_json|gateway_final_retry_failed|gateway closed|tick timeout|timeout_after|background_job_timeout|m3_background_job_timeout|Gateway CLI queue timeout|OpenClaw Gateway CLI timed out|timed out after \d+ms|ECONNRESET|ETIMEDOUT|Workbench request aborted/i.test(text);
}

function throwKnowledgeNoteGatewayFailureWithOps(err: KnowledgeNoteGatewayRequiredError, opsAttempts: KnowledgeNoteAttempt[], opsReports: KnowledgeNoteOpsRecoveryReport[]): never {
  const opsRecovery = summarizeKnowledgeNoteOpsRecovery(opsReports);
  if (!opsRecovery) throw err;
  const diagnosis = err.diagnosis || diagnoseKnowledgeNoteFailure(err.stage, err.reason);
  const nextActions = uniqueStrings([
    ...diagnosis.nextActions,
    ...opsRecovery.nextActions,
    "Worker 运维恢复已执行；如仍失败，保留当前草稿并稍后重试。",
  ]);
  failKnowledgeNoteGateway(err.stage, err.reason, err.generationPipeline, err.statusCode, err.debugReportPath, {
    attempts: [...opsAttempts, ...(Array.isArray(err.attempts) ? err.attempts : [])],
    diagnosis: { ...diagnosis, nextActions },
    retryBudget: err.retryBudget,
    debugReports: uniqueStrings([
      ...(Array.isArray(err.debugReports) ? err.debugReports : []),
      ...opsReports.map((report) => report.reportPath || ""),
    ].filter(Boolean)),
    nextActions,
    opsRecovery,
  });
}

function summarizeKnowledgeNoteOpsRecovery(reports: KnowledgeNoteOpsRecoveryReport[]): KnowledgeNoteOpsRecoverySummary | null {
  if (!reports.length) return null;
  const latest = reports[reports.length - 1];
  const rank: Record<KnowledgeNoteOpsRecoveryReport["status"], number> = { RECOVERED: 0, DEGRADED: 1, SKIPPED: 2, FAILED: 3 };
  const worst = reports.reduce((current, report) => rank[report.status] > rank[current.status] ? report : current, latest);
  return {
    status: latest.status === "RECOVERED" ? "RECOVERED" : worst.status,
    attempts: reports.length,
    retryRecommended: latest.retryRecommended,
    reports: reports.map((report) => report.reportPath || "").filter(Boolean),
    latestReportPath: latest.reportPath,
    latestSystemOpsStatus: latest.latestSystemOps?.status || null,
    latestGatewayStatus: latest.gatewayHealthChecks.at(-1)?.status || null,
    blockers: uniqueStrings(reports.flatMap((report) => report.blockers || [])),
    nextActions: uniqueStrings(reports.flatMap((report) => report.nextActions || [])),
  };
}

function knowledgeNoteOpsRecoveryAttempt(report: KnowledgeNoteOpsRecoveryReport): KnowledgeNoteAttempt {
  return {
    attempt: report.attempt,
    stage: "worker_system_ops_recovery",
    strategy: "server_side_shadow_watchdog_then_retry",
    status: report.retryRecommended ? "passed" : "failed",
    reason: `ops_recovery_${report.status.toLowerCase()}`,
    repairDirectives: report.actions,
    debugReportPath: report.reportPath,
  };
}

async function runKnowledgeNoteServerOpsRecovery(input: {
  attempt: number;
  stage: string;
  reason: string;
  sourceHash: string;
  signal?: AbortSignal;
}): Promise<KnowledgeNoteOpsRecoveryReport> {
  const startedAtMs = Date.now();
  const actions = [
    "Worker system_ops shadow 巡检",
    "Gateway 生命周期恢复（status/install/start；restart 需 Main/user 审批）",
    "Gateway health 重新探测",
    "保留原始笔记和元数据不变",
    "恢复后重试 Gateway/MiniMax 整理",
  ];
  const gatewayHealthChecks: LiveGatewayHealthSnapshot[] = [];
  const blockers: string[] = [];
  let watchdog: any = null;
  let latestSystemOps: KnowledgeNoteOpsRecoveryReport["latestSystemOps"] = null;
  let lifecycle: GatewayLifecycleRecoveryResult | null = null;

  try {
    watchdog = await runSystemOpsWatchdogAsync("shadow", KNOWLEDGE_NOTE_SERVER_OPS_TIMEOUT_MS, input.signal);
  } catch (err) {
    watchdog = {
      status: null,
      error: sanitizePublicError(err instanceof Error ? err.message : String(err)),
      parsed: null,
    };
    blockers.push(`watchdog_failed:${watchdog.error}`);
  }

  const latestReport = latestSystemOpsReport();
  if (latestReport?.data) {
    latestSystemOps = {
      path: latestReport.path,
      status: latestReport.data.status || null,
      summary: latestReport.data.summary || null,
      network_status: latestReport.data.network_status || null,
      nas_status: latestReport.data.nas_status || null,
      blockers: latestReport.data.blockers || [],
    };
  }

  try {
    lifecycle = await runGatewayLifecycleRecovery(input);
    if (!lifecycle.ok) {
      blockers.push(`gateway_lifecycle_failed:${lifecycle.finalError || "gateway_lifecycle_error"}`);
    }
  } catch (err) {
    blockers.push(`gateway_lifecycle_probe_failed:${sanitizePublicError(err instanceof Error ? err.message : String(err))}`);
  }

  const healthDeadline = Date.now() + KNOWLEDGE_NOTE_SERVER_OPS_HEALTH_WAIT_MS;
  while (Date.now() <= healthDeadline) {
    throwIfSignalAborted(input.signal);
    try {
      const health = await refreshLiveGatewayHealth({
        force: true,
        timeoutMs: LIVE_GATEWAY_HEALTH_TIMEOUT_MS,
        minIntervalMs: 0,
        source: "knowledge_note_ops_recovery",
        signal: input.signal,
      });
      gatewayHealthChecks.push(health);
      if (health.ok) break;
      blockers.push(`gateway_health:${health.status}:${health.error || "unknown"}`);
    } catch (err) {
      blockers.push(`gateway_health_probe_failed:${sanitizePublicError(err instanceof Error ? err.message : String(err))}`);
    }
    await sleep(3000, input.signal);
  }

  const latestHealth = gatewayHealthChecks.at(-1) || liveGatewayHealthSnapshot();
  const watchdogStatus = String(watchdog?.parsed?.status || watchdog?.status || "");
  const watchdogOk = watchdog?.status === 0 && watchdogStatus !== "ERROR";
  const lifecycleRecovered = lifecycle ? lifecycle.ok || lifecycle.finalStatus === "connected" : false;
  const lifecycleAttempted = lifecycle ? lifecycle.attempted : false;
  const status: KnowledgeNoteOpsRecoveryReport["status"] = latestHealth.ok || lifecycleRecovered
    ? "RECOVERED"
    : lifecycleAttempted || watchdogOk
      ? "DEGRADED"
      : "FAILED";
  if (status !== "RECOVERED" && latestHealth.error) blockers.push(`gateway_not_recovered:${latestHealth.error}`);
  const retryRecommended = status === "RECOVERED" || status === "DEGRADED";
  const report: KnowledgeNoteOpsRecoveryReport = {
    ok: status !== "FAILED",
    status,
    ts: nowIso(),
    attempt: input.attempt,
    stage: input.stage,
    reason: sanitizePublicError(input.reason).slice(0, 1200),
    sourceHash: input.sourceHash,
    retryRecommended,
    durationMs: Date.now() - startedAtMs,
    watchdog,
    latestSystemOps,
    gatewayHealthChecks,
    actions,
    blockers: uniqueStrings(blockers).slice(0, 8),
    nextActions: retryRecommended
      ? ["Worker 运维恢复已执行，自动重试添加笔记。", "如果再次失败，继续保留草稿和 debug report。"]
      : ["Worker 运维恢复未能确认 Gateway 可用，保留草稿并稍后重试。", "查看 system_ops_watchdog 和 knowledge_note_ops_recovery 报告。"],
  };
  report.reportPath = writeKnowledgeNoteOpsRecoveryReport(report);
  return report;
}

function writeKnowledgeNoteOpsRecoveryReport(report: KnowledgeNoteOpsRecoveryReport) {
  try {
    fs.mkdirSync(KNOWLEDGE_NOTE_OPS_RECOVERY_REPORT_ROOT, { recursive: true });
    const file = path.join(KNOWLEDGE_NOTE_OPS_RECOVERY_REPORT_ROOT, `knowledge_note_ops_recovery_${nowIso().replace(/[-:]/g, "").replace(/\.\d+Z$/, "Z")}_${report.sourceHash.slice(0, 10)}_${report.attempt}.json`);
    fs.writeFileSync(file, `${JSON.stringify(report, null, 2)}\n`, "utf8");
    return file;
  } catch {
    return "";
  }
}

function parseLooseJsonObject(text: string) {
  const raw = String(text || "").trim();
  if (!raw) return null;
  try {
    return JSON.parse(raw);
  } catch {
    const start = raw.indexOf("{");
    const end = raw.lastIndexOf("}");
    if (start >= 0 && end > start) {
      try {
        return JSON.parse(raw.slice(start, end + 1));
      } catch {
        return null;
      }
    }
  }
  return null;
}

function runSystemOpsWatchdogAsync(mode: "shadow" | "apply", timeoutMs: number, signal?: AbortSignal): Promise<ReturnType<typeof runSystemOpsWatchdog>> {
  return new Promise((resolve) => {
    const startedAtMs = Date.now();
    if (!fs.existsSync(SYSTEM_OPS_SKILL_RUNNER)) {
      resolve({
        status: 127,
        signal: null,
        error: `system_ops_runner_missing:${SYSTEM_OPS_SKILL_RUNNER}`,
        parsed: null,
        stdout: "",
        stderr: "",
      });
      return;
    }
    const child = spawn(process.execPath, [SYSTEM_OPS_SKILL_RUNNER, `--mode=${mode}`, "--owner=worker", "--json"], {
      cwd: WORKSPACE_DIR,
      env: { ...process.env, PATH: `${path.join(os.homedir(), ".npm-global/bin")}:/opt/homebrew/bin:/usr/local/bin:${process.env.PATH || ""}` },
      stdio: ["ignore", "pipe", "pipe"],
    });
    let stdout = "";
    let stderr = "";
    let settled = false;
    const timeout = setTimeout(() => finish({
      status: null,
      signal: "SIGTERM",
      error: `system_ops_watchdog_timeout_after_${timeoutMs}ms`,
    }), timeoutMs);
    const abort = () => finish({ status: null, signal: "SIGTERM", error: "system_ops_watchdog_aborted" });
    signal?.addEventListener("abort", abort, { once: true });
    child.stdout?.on("data", (chunk) => {
      stdout += String(chunk);
      if (stdout.length > 8 * 1024 * 1024) stdout = stdout.slice(-8 * 1024 * 1024);
    });
    child.stderr?.on("data", (chunk) => {
      stderr += String(chunk);
      if (stderr.length > 1024 * 1024) stderr = stderr.slice(-1024 * 1024);
    });
    child.on("error", (err) => finish({ status: null, signal: null, error: err.message }));
    child.on("close", (code, closeSignal) => finish({ status: code, signal: closeSignal, error: null }));

    function finish(outcome: { status: number | null; signal: NodeJS.Signals | string | null; error: string | null }) {
      if (settled) return;
      settled = true;
      clearTimeout(timeout);
      signal?.removeEventListener("abort", abort);
      if (outcome.error && child.pid) {
        try {
          child.kill("SIGTERM");
        } catch {
          // Best effort.
        }
      }
      const parsed = parseLooseJsonObject(stdout);
      resolve({
        status: outcome.status,
        signal: outcome.signal as NodeJS.Signals | null,
        error: outcome.error,
        parsed,
        stdout: parsed ? "" : stdout.slice(0, 4000),
        stderr: stderr.slice(0, 4000),
        durationMs: Date.now() - startedAtMs,
      } as ReturnType<typeof runSystemOpsWatchdog>);
    }
  });
}

function liveGatewayHealthSnapshot(): LiveGatewayHealthSnapshot {
  const now = Date.now();
  const checkedAt = liveGatewayHealthState.checkedAtMs ? new Date(liveGatewayHealthState.checkedAtMs).toISOString() : null;
  return {
    ok: liveGatewayHealthState.ok,
    status: liveGatewayHealthState.status,
    error: liveGatewayHealthState.error,
    source: liveGatewayHealthState.source,
    checkedAt,
    staleSeconds: checkedAt ? Math.max(0, Math.round((now - liveGatewayHealthState.checkedAtMs) / 1000)) : 0,
    failureCount: liveGatewayHealthState.failureCount,
    nextCheckAt: liveGatewayHealthState.nextProbeAtMs ? new Date(liveGatewayHealthState.nextProbeAtMs).toISOString() : null,
    durationMs: liveGatewayHealthState.durationMs,
  };
}

function updateLiveGatewayHealthFromResult(gateway: GatewayResult, source: string) {
  const now = Date.now();
  const gatewayDurationMs = Number((gateway.data as { durationMs?: unknown } | undefined)?.durationMs);
  liveGatewayHealthState.durationMs = Number.isFinite(gatewayDurationMs) ? gatewayDurationMs : null;
  if (gateway.ok) {
    liveGatewayHealthState.ok = true;
    liveGatewayHealthState.status = "connected";
    liveGatewayHealthState.error = null;
    liveGatewayHealthState.failureCount = 0;
    liveGatewayHealthState.nextProbeAtMs = now + LIVE_GATEWAY_HEALTH_SUCCESS_MS;
  } else {
    liveGatewayHealthState.ok = false;
    liveGatewayHealthState.failureCount += 1;
    liveGatewayHealthState.status = liveGatewayHealthState.failureCount >= 2 ? "unavailable" : "degraded";
    liveGatewayHealthState.error = sanitizePublicError(gateway.error || "Gateway health check failed");
    const backoffMs = Math.min(LIVE_GATEWAY_HEALTH_FAILURE_MAX_MS, LIVE_GATEWAY_HEALTH_FAILURE_MIN_MS * liveGatewayHealthState.failureCount);
    liveGatewayHealthState.nextProbeAtMs = now + backoffMs;
  }
  liveGatewayHealthState.source = source;
  liveGatewayHealthState.checkedAtMs = now;
  return liveGatewayHealthSnapshot();
}

async function refreshLiveGatewayHealth(options: {
  force?: boolean;
  timeoutMs?: number;
  minIntervalMs?: number;
  source?: string;
  signal?: AbortSignal;
} = {}) {
  const now = Date.now();
  const minIntervalMs = Math.max(0, options.minIntervalMs ?? 0);
  const recentlyChecked = liveGatewayHealthState.checkedAtMs > 0 && now - liveGatewayHealthState.checkedAtMs < minIntervalMs;
  if (liveGatewayHealthInflight) return liveGatewayHealthInflight;
  if (!options.force && now < liveGatewayHealthState.nextProbeAtMs) return liveGatewayHealthSnapshot();
  if (options.force && recentlyChecked && liveGatewayHealthState.status !== "checking") return liveGatewayHealthSnapshot();

  liveGatewayHealthState.status = liveGatewayHealthState.checkedAtMs ? liveGatewayHealthState.status : "checking";
  liveGatewayHealthState.source = options.source || "gateway:health";
  liveGatewayHealthInflight = (async () => {
    const gateway = await gatewayCall("health", {}, options.timeoutMs || LIVE_GATEWAY_HEALTH_TIMEOUT_MS, { signal: options.signal, serializeCli: false });
    return updateLiveGatewayHealthFromResult(gateway, options.source || "gateway:health");
  })().finally(() => {
    liveGatewayHealthInflight = null;
  });
  return liveGatewayHealthInflight;
}

async function requireGatewayReadyForKnowledgeNote(signal?: AbortSignal) {
  throwIfSignalAborted(signal);
  const current = liveGatewayHealthSnapshot();
  if (current.ok && current.staleSeconds <= Math.round(KNOWLEDGE_NOTE_GATEWAY_PREFLIGHT_CACHE_OK_MS / 1000)) {
    return current;
  }

  // Knowledge-note generation is the actual Gateway/MiniMax probe. Short
  // preflight CLI calls can queue behind long model runs and fail before the
  // real organize request starts, producing a false gateway_preflight error.
  if (isHardGatewayUnavailableForKnowledgeNote(current)) {
    failKnowledgeNoteGateway(
      "gateway_preflight",
      `gateway_preflight_${current.status}:${current.error || "Gateway health check failed"}`,
      ["gateway_preflight_failed"],
      503,
    );
  }
  return current;
}

function isHardGatewayUnavailableForKnowledgeNote(current: LiveGatewayHealthSnapshot) {
  if (current.status !== "unavailable" || current.failureCount < 2) return false;
  if (current.staleSeconds > 30) return false;
  return !isGatewayCliQueueOrRpcTimeout(current.error);
}

function isGatewayCliQueueOrRpcTimeout(error: unknown) {
  return /Gateway CLI queue timeout|OpenClaw Gateway CLI timed out|timed out after \d+ms/i.test(String(error || ""));
}

async function callKnowledgeNoteGatewayAgent<T = unknown>(input: {
  preferredAgent: AgentId;
  purpose: "markdown" | "html";
  sourceHash: string;
  runId: string;
  message: string;
  idempotencyKey: string;
  timeoutMs: number;
  signal?: AbortSignal;
}): Promise<{ gateway: GatewayResult<T>; execution: KnowledgeNoteGatewayExecution }> {
  const initialExecution = resolveKnowledgeNoteGatewayExecution(input.preferredAgent);
  const runKey = safeName(input.runId || randomUUID()).slice(0, 16);
  const firstSessionKey = `agent:${initialExecution.executionAgent}:knowledge-note-${input.purpose}:${input.sourceHash.slice(0, 16)}:${runKey}`;
  const first = await runKnowledgeNoteGatewayAgentAttempt<T>({
    agentId: initialExecution.executionAgent,
    sessionKey: firstSessionKey,
    params: {
    agentId: initialExecution.executionAgent,
    sessionKey: firstSessionKey,
    message: initialExecution.executionAgent === input.preferredAgent
      ? input.message
      : buildKnowledgeNoteProxyPrompt(input.preferredAgent, initialExecution.executionAgent, initialExecution.reason, input.message),
    idempotencyKey: initialExecution.executionAgent === input.preferredAgent
      ? input.idempotencyKey
      : `${input.idempotencyKey}:${initialExecution.executionAgent}-transport`,
    },
    timeoutMs: input.timeoutMs,
    signal: input.signal,
  });
  if (first.ok || initialExecution.executionAgent === "main" || !isKnowledgeNoteSandboxRuntimeError(first.error)) {
    return { gateway: first, execution: first.ok ? { ...initialExecution, sessionKey: firstSessionKey, rerouteReason: "dispatch_session_final" } : { ...initialExecution, sessionKey: firstSessionKey, rerouteReason: first.error } };
  }

  const retrySessionKey = `agent:main:knowledge-note-${input.purpose}:${input.sourceHash.slice(0, 16)}:${runKey}`;
  const retryExecution: KnowledgeNoteGatewayExecution = {
    roleAgent: input.preferredAgent,
    executionAgent: "main",
    sessionKey: retrySessionKey,
    reason: "preferred_agent_sandbox_runtime_failed_main_transport_retry",
    rerouteReason: first.error,
  };
  const retry = await runKnowledgeNoteGatewayAgentAttempt<T>({
    agentId: "main",
    sessionKey: retrySessionKey,
    params: {
      agentId: "main",
      sessionKey: retrySessionKey,
      message: buildKnowledgeNoteProxyPrompt(input.preferredAgent, "main", retryExecution.reason, input.message),
      idempotencyKey: `${input.idempotencyKey}:main-transport-retry`,
    },
    timeoutMs: input.timeoutMs,
    signal: input.signal,
  });
  return {
    gateway: retry.ok
      ? retry
      : {
          ...retry,
          error: `preferred_agent_sandbox_unavailable:${first.error || "unknown"}; main_transport_failed:${retry.error || "unknown"}`,
        },
    execution: retryExecution,
  };
}

async function callKnowledgeNoteGatewayAgentWithLateHarvest<T = unknown>(input: {
  preferredAgent: AgentId;
  purpose: "markdown" | "html";
  sourceHash: string;
  runId: string;
  message: string;
  idempotencyKey: string;
  timeoutMs: number;
  signal?: AbortSignal;
  harvestSinceMs: number;
}): Promise<{ gateway: GatewayResult<T>; execution: KnowledgeNoteGatewayExecution }> {
  const controller = new AbortController();
  const abortFromParent = () => controller.abort();
  if (input.signal?.aborted) controller.abort();
  else input.signal?.addEventListener("abort", abortFromParent, { once: true });

  const gatewayPromise = callKnowledgeNoteGatewayAgent<T>({
    preferredAgent: input.preferredAgent,
    purpose: input.purpose,
    sourceHash: input.sourceHash,
    runId: input.runId,
    message: input.message,
    idempotencyKey: input.idempotencyKey,
    timeoutMs: input.timeoutMs,
    signal: controller.signal,
  });
  gatewayPromise.catch(() => undefined);

  const harvestTimeoutMs = Math.max(10_000, Math.min(input.timeoutMs - 1000, 180_000));
  const harvestPromise = waitForKnowledgeNoteLateHarvest({
    purpose: input.purpose,
    sourceHash: input.sourceHash,
    sinceMs: input.harvestSinceMs,
    preferredAgent: input.preferredAgent,
    timeoutMs: harvestTimeoutMs,
    signal: controller.signal,
  }).then((harvest) => harvest ? { type: "harvest" as const, harvest } : null);

  try {
    const first = await Promise.race([
      gatewayPromise.then((result) => ({ type: "gateway" as const, result })),
      harvestPromise,
    ]);
    if (first?.type === "harvest") {
      controller.abort();
      return {
        gateway: knowledgeNoteGatewayResultFromLateHarvest<T>(first.harvest),
        execution: {
          roleAgent: input.preferredAgent,
          executionAgent: first.harvest.agentId,
          reason: "late_m3_session_source_hash_harvest",
          rerouteReason: "gateway_final_not_delivered_to_workbench_harvest_race",
          sessionKey: first.harvest.sessionKey,
        },
      };
    }
    if (first?.type === "gateway") return first.result;
    return await gatewayPromise;
  } finally {
    controller.abort();
    input.signal?.removeEventListener("abort", abortFromParent);
  }
}

async function waitForKnowledgeNoteLateHarvest(input: {
  purpose: "markdown" | "html";
  sourceHash: string;
  sinceMs: number;
  preferredAgent?: AgentId;
  timeoutMs: number;
  signal?: AbortSignal;
}) {
  const deadline = Date.now() + Math.max(0, input.timeoutMs);
  while (Date.now() <= deadline) {
    const harvest = recoverKnowledgeNoteGatewayFinalBySourceHash({
      purpose: input.purpose,
      sourceHash: input.sourceHash,
      sinceMs: input.sinceMs,
      preferredAgent: input.preferredAgent,
      requirePromptMarker: KNOWLEDGE_NOTE_GATEWAY_PROMPT_VERSION,
    });
    if (harvest) return harvest;
    const remainingMs = deadline - Date.now();
    if (remainingMs <= 0) break;
    await sleep(Math.min(1500, remainingMs), input.signal);
  }
  return null;
}

async function runKnowledgeNoteGatewayAgentAttempt<T>(input: {
  agentId: AgentId;
  sessionKey: string;
  params: Record<string, unknown>;
  timeoutMs: number;
  signal?: AbortSignal;
}): Promise<GatewayResult<T>> {
  const skipToken = process.env.OPENCLAW_WORKBENCH_NOTE_GATEWAY_SKIP_TOKEN === "1";
  const startedMs = Date.now();
  const final = await callKnowledgeNoteGatewayFinalWithSessionRecovery<T>({
    agentId: input.agentId,
    sessionKey: input.sessionKey,
    params: input.params,
    timeoutMs: input.timeoutMs,
    skipToken,
    signal: input.signal,
    startedMs,
  });
  if (!final.ok) {
    const recovered = isRecoverableGatewayFinalError(final.error)
      ? await recoverKnowledgeNoteGatewayFinalAfterClose(input.agentId, input.sessionKey, startedMs - 1000, final.error, input.timeoutMs, input.signal)
      : "";
    if (recovered) {
      return {
        ok: true,
        status: "connected",
        data: { final: recovered, recoveredFromSession: true, recoveredAfterGatewayClose: true, dispatch: final } as T,
      };
    }
    return final;
  }
  const text = extractGatewayText(final.data).trim();
  if (text) return final;
  const recovered = await recoverKnowledgeNoteGatewayFinalAfterClose(input.agentId, input.sessionKey, startedMs - 1000, "empty_final_text", input.timeoutMs, input.signal);
  if (recovered) {
    return {
      ok: true,
      status: "connected",
      data: { final: recovered, recoveredFromSession: true, dispatch: final.data } as T,
    };
  }
  return {
    ok: false,
    status: "unavailable",
    error: "OpenClaw Gateway final response did not contain model text.",
  };
}

async function callKnowledgeNoteGatewayFinalWithSessionRecovery<T>(input: {
  agentId: AgentId;
  sessionKey: string;
  params: Record<string, unknown>;
  timeoutMs: number;
  skipToken: boolean;
  signal?: AbortSignal;
  startedMs: number;
}): Promise<GatewayResult<T>> {
  const shouldRetry = input.timeoutMs > 10_000;
  const recoverSinceMs = input.startedMs - 1000;
  const call = () => gatewayCall<T>("agent", input.params, input.timeoutMs, {
    expectFinal: true,
    skipToken: input.skipToken,
    serializeCli: false,
    signal: input.signal,
  });
  const recover = async (error: unknown) => {
    if (!isRecoverableGatewayFinalError(error)) return "";
    return recoverKnowledgeNoteGatewayFinalAfterClose(input.agentId, input.sessionKey, recoverSinceMs, error, input.timeoutMs, input.signal);
  };

  const first = await call();
  if (first.ok) return first;
  const firstRecovered = await recover(first.error);
  if (firstRecovered) return recoveredKnowledgeNoteGatewayResult<T>(firstRecovered, first);
  const firstElapsedMs = Date.now() - input.startedMs;
  if (!shouldRetry || !shouldRetryKnowledgeNoteGatewayFinal(first.error, firstElapsedMs)) return first;

  await sleep(2000, input.signal);
  const retry = await call();
  if (retry.ok) return retry;
  const retryRecovered = await recover(retry.error);
  if (retryRecovered) return recoveredKnowledgeNoteGatewayResult<T>(retryRecovered, retry);
  return {
    ...retry,
    error: `gateway_final_retry_failed:${first.error || "unknown"}; ${retry.error || "unknown"}`,
  };
}

function recoveredKnowledgeNoteGatewayResult<T>(finalText: string, dispatch: GatewayResult<T>): GatewayResult<T> {
  return {
    ok: true,
    status: "connected",
    data: { final: finalText, recoveredFromSession: true, recoveredAfterGatewayClose: true, dispatch } as T,
  };
}

async function recoverKnowledgeNoteGatewayFinalAfterClose(
  agentId: AgentId,
  sessionKey: string,
  sinceMs: number,
  error: unknown,
  timeoutMs: number,
  signal?: AbortSignal,
) {
  const deadline = Date.now() + gatewayFinalRecoveryWindowMs(error, timeoutMs);
  while (Date.now() <= deadline) {
    throwIfSignalAborted(signal);
    const recovered = (recoverGatewayFinalFromSession(agentId, sessionKey, sinceMs)
      || recoverGatewayFinalFromRecentSessionFiles(agentId, sessionKey, sinceMs)).trim();
    if (recovered) return recovered;
    await sleep(Math.min(KNOWLEDGE_NOTE_GATEWAY_RECOVERY_POLL_MS, Math.max(250, deadline - Date.now())), signal);
  }
  return "";
}

function throwIfSignalAborted(signal?: AbortSignal) {
  if (signal?.aborted) throw new Error("Workbench request aborted while waiting for Gateway.");
}

async function callKnowledgeNoteGatewayFinal<T>(
  params: Record<string, unknown>,
  timeoutMs: number,
  skipToken: boolean,
  signal?: AbortSignal,
): Promise<GatewayResult<T>> {
  const shouldRetry = timeoutMs > 10_000;
  const first = await gatewayCall<T>("agent", params, timeoutMs, { expectFinal: true, skipToken, signal });
  if (first.ok || !shouldRetry || !isTransientGatewayDispatchError(first.error)) return first;
  await sleep(2000, signal);
  const retry = await gatewayCall<T>("agent", params, timeoutMs, { expectFinal: true, skipToken, signal });
  if (retry.ok || !isFastGatewayClose(first.error) || !isTransientGatewayDispatchError(retry.error)) {
    if (retry.ok) return retry;
    return {
      ...retry,
      error: `gateway_final_retry_failed:${first.error || "unknown"}; ${retry.error || "unknown"}`,
    };
  }
  await sleep(5000, signal);
  const secondRetry = await gatewayCall<T>("agent", params, timeoutMs, { expectFinal: true, skipToken, signal });
  if (secondRetry.ok) return secondRetry;
  return {
    ...secondRetry,
    error: `gateway_final_retry_failed:${first.error || "unknown"}; ${retry.error || "unknown"}; ${secondRetry.error || "unknown"}`,
  };
}

function isTransientGatewayDispatchError(error: unknown) {
  return isRecoverableGatewayFinalError(error);
}

function isFastGatewayClose(error: unknown) {
  return /gateway closed \((1000|1006|1012|4000)|normal closure|no close reason|tick timeout|ECONNRESET|ETIMEDOUT/i.test(String(error || ""));
}

function isRecoverableGatewayFinalError(error: unknown) {
  return /gateway closed \((1000|1006|1012|4000)|normal closure|no close reason|gateway timeout|timed out after \d+ms|OpenClaw Gateway CLI timed out|Gateway CLI queue timeout|ECONNRESET|ETIMEDOUT|tick timeout/i.test(String(error || ""));
}

function shouldRetryKnowledgeNoteGatewayFinal(error: unknown, elapsedMs: number) {
  const text = String(error || "");
  if (!isTransientGatewayDispatchError(text)) return false;
  if (/Gateway CLI queue timeout|OpenClaw Gateway CLI timed out|timed out after \d+ms/i.test(text)) return false;
  // A late tick timeout usually means the model/session is still busy. Polling
  // the same session is safer than starting another long MiniMax run.
  if (/tick timeout/i.test(text) && elapsedMs > 20_000) return false;
  return isFastGatewayClose(text) || /ECONNRESET|ETIMEDOUT/i.test(text);
}

function gatewayFinalRecoveryWindowMs(error: unknown, timeoutMs: number) {
  const text = String(error || "");
  if (/empty_final_text/i.test(text)) return Math.min(10_000, Math.max(3000, Math.floor(timeoutMs * 0.05)));
  if (/Gateway CLI queue timeout/i.test(text)) return 3000;
  if (/OpenClaw Gateway CLI timed out.*final agent output|timed out after \d+ms while waiting for final agent output/i.test(text)) {
    return Math.min(KNOWLEDGE_NOTE_GATEWAY_RECOVERY_MAX_MS, Math.max(45_000, Math.floor(timeoutMs * 0.25)));
  }
  if (/OpenClaw Gateway CLI timed out|timed out after \d+ms|tick timeout|no close reason|normal closure|gateway closed/i.test(text)) {
    return Math.min(KNOWLEDGE_NOTE_GATEWAY_RECOVERY_MAX_MS, Math.max(8000, Math.floor(timeoutMs * 0.08)));
  }
  return 5000;
}

function resolveKnowledgeNoteGatewayExecution(preferredAgent: AgentId): KnowledgeNoteGatewayExecution {
  const forced = normalizeKnowledgeNoteExecutionAgent(process.env.OPENCLAW_WORKBENCH_NOTE_GATEWAY_AGENT);
  if (forced) {
    return { roleAgent: preferredAgent, executionAgent: forced, reason: "env_forced_execution_agent" };
  }
  if (preferredAgent !== "main" && !hasLocalDockerSocket()) {
    return { roleAgent: preferredAgent, executionAgent: "main", reason: "sandbox_docker_socket_missing_main_transport" };
  }
  return { roleAgent: preferredAgent, executionAgent: preferredAgent, reason: "preferred_agent" };
}

function normalizeKnowledgeNoteExecutionAgent(value: unknown): AgentId | null {
  const clean = String(value || "").trim();
  return clean === "main" || clean === "boss" || clean === "worker" ? clean : null;
}

function hasLocalDockerSocket() {
  return [
    path.join(os.homedir(), ".orbstack", "run", "docker.sock"),
    "/var/run/docker.sock",
  ].some((socketPath) => {
    try {
      return fs.existsSync(socketPath);
    } catch {
      return false;
    }
  });
}

function isKnowledgeNoteSandboxRuntimeError(error: unknown) {
  return /Failed to inspect sandbox image|docker API|docker\.sock|orbstack|sandbox image|Cannot connect to Docker|daemon is running/i.test(String(error || ""));
}

function buildKnowledgeNoteProxyPrompt(roleAgent: AgentId, executionAgent: AgentId, reason: string, originalPrompt: string) {
  return [
    `Gateway execution note: ${executionAgent} is the transport agent for this text-only Knowledge note task.`,
    `Role decision remains ${roleAgent}. Preserve the ${roleAgent} responsibilities, quality bar, and output contract exactly.`,
    `Transport reason: ${reason}. Do not mention this routing detail in the user-facing note.`,
    "",
    originalPrompt,
  ].join("\n");
}

// njx-knowledge v2 / Phase 3 — MiniMax M3 直连路径 (minimax-direct qualityMode)
// 不依赖 OpenClaw Gateway ready preflight, 失败结构化 fallback 到 m3-html Gateway 链路.
// apiKey 只读 env + model_configs apiKeyRef, 绝不硬编码; 不外泄 key.
type DirectMinimaxCallSource =
  | "env:MINIMAX_API_KEY"
  | "env:OPENCLAW_MINIMAX_API_KEY"
  | "codex:minimax.config.toml"
  | "openclaw:auth-profiles"
  | "model_configs:apiKey"
  | "missing";

function resolveMinimaxM3BaseUrl(): { url: string; source: string } {
  const envBase = String(process.env.MINIMAX_BASE_URL || process.env.OPENCLAW_MINIMAX_BASE_URL || "").trim();
  if (envBase) return { url: envBase.replace(/\/+$/, ""), source: "env:MINIMAX_BASE_URL" };
  // 优先取 active 默认 model_config (provider=minimax, model=m3) 的 baseUrl, 否则使用 MiniMax 公网默认
  try {
    const row = (db.prepare(
      "SELECT base_url FROM model_configs WHERE status = 'active' AND provider = 'minimax' AND (model = 'm3' OR model LIKE 'm3-%' OR id = 'minimax-m3') ORDER BY is_default DESC LIMIT 1"
    ).get() || {}) as { base_url?: string };
    if (row?.base_url) return { url: String(row.base_url).replace(/\/+$/, ""), source: "model_configs:baseUrl" };
  } catch {}
  return { url: "https://api.minimaxi.com/v1", source: "default:api.minimaxi.com" };
}

function readMinimaxM3ApiKeyFromCodexConfig(): string | null {
  try {
    const configPath = path.join(os.homedir(), ".codex", "minimax.config.toml");
    const text = fs.readFileSync(configPath, "utf8");
    const match = text.match(/^\s*experimental_bearer_token\s*=\s*"([^"]+)"\s*$/m)
      || text.match(/^\s*api_key\s*=\s*"([^"]+)"\s*$/m);
    const key = String(match?.[1] || "").trim();
    return key || null;
  } catch {
    return null;
  }
}

function readMinimaxM3ApiKeyFromOpenClawProfiles(): string | null {
  try {
    const profilesPath = path.join(os.homedir(), ".openclaw", "agents", "main", "agent", "auth-profiles.json");
    const parsed = JSON.parse(fs.readFileSync(profilesPath, "utf8")) as { profiles?: Record<string, { key?: string }> };
    const key = String(parsed.profiles?.["minimax:default"]?.key || "").trim();
    return key || null;
  } catch {
    return null;
  }
}

function resolveMinimaxM3ApiKey(): { key: string | null; refSource: DirectMinimaxCallSource } {
  const fromEnv = String(process.env.MINIMAX_API_KEY || process.env.OPENCLAW_MINIMAX_API_KEY || "").trim();
  if (fromEnv) return { key: fromEnv, refSource: process.env.MINIMAX_API_KEY ? "env:MINIMAX_API_KEY" : "env:OPENCLAW_MINIMAX_API_KEY" };
  const fromCodexConfig = readMinimaxM3ApiKeyFromCodexConfig();
  if (fromCodexConfig) return { key: fromCodexConfig, refSource: "codex:minimax.config.toml" };
  const fromOpenClawProfiles = readMinimaxM3ApiKeyFromOpenClawProfiles();
  if (fromOpenClawProfiles) return { key: fromOpenClawProfiles, refSource: "openclaw:auth-profiles" };
  try {
    const row = (db.prepare(
      "SELECT api_key_configured FROM model_configs WHERE status = 'active' AND provider = 'minimax' AND (model = 'm3' OR model LIKE 'm3-%' OR id = 'minimax-m3') ORDER BY is_default DESC LIMIT 1"
    ).get() || {}) as { api_key_configured?: number };
    if (Number(row?.api_key_configured) === 1) return { key: null, refSource: "model_configs:apiKey" };
  } catch {}
  return { key: null, refSource: "missing" };
}

type DirectMinimaxM3CallResult = {
  ok: boolean;
  content?: string;
  provider: "minimax-direct";
  model: string;
  baseUrl: string;
  baseUrlSource: string;
  apiKeyRefSource: DirectMinimaxCallSource;
  finishReason?: string;
  promptTokens?: number;
  completionTokens?: number;
  durationMs?: number;
  error?: { code: string; message: string; stage: string };
};

function requestKnowledgeNoteDirectAuditId() {
  try {
    return randomUUID();
  } catch {
    return `nkx-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
  }
}

function escapeHtmlForDirectRender(input: string): string {
  return String(input || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

// 2026-07-06 — minimax-direct 直连质量门禁.
// MiniMax-M3 在没有 JSON contract / 没有工具调用约束的直连模式下, 经常把链式思考
// (`<think>…</think>`) 和英文分析 preamble 写进最终 assistant content. 直接把
// raw `directResult.content` 当作 Markdown 会把 reasoning / preamble 暴露到
// `draft.markdown` 和 `draft.html`, UI 就会看到 NJX 截图里那种
// `<think>Let me analyze this raw note carefully…` 的污染 preview.
//
// 这一组 helper 在 server 侧做清理 + 评估, 不依赖 Gateway:
//   * cleanKnowledgeNoteDirectMarkdown(raw) — 移除 `<think>…</think>`, JSON envelope,
//     英文 / 中文分析 preamble. 任何残留都会进入 issues[].
//   * assessKnowledgeNoteDirectMarkdownQuality(markdown) — 在清理后的 markdown 上
//     算真实 score / passed / issues, 不再 hard-code `{ passed: true, score: 0.6 }`.
//
// 调用方必须在保存前调用这两个 helper, 任何 issues 命中或长度过低都必须按
// `minimax_direct_markdown_quality_failed` fail-fast, 不允许 fake-pass.
const KNOWLEDGE_NOTE_DIRECT_THINK_BLOCK_RE = /<think>[\s\S]*?<\/think>/gi;
const KNOWLEDGE_NOTE_DIRECT_UNCLOSED_THINK_RE = /^\s*<think>\b[\s\S]*?(?=\n\s*---\s*\n|\n\s*#\s+|\Z)/i;
const KNOWLEDGE_NOTE_DIRECT_PREAMBLE_RE = /^\s*(?:(?:Let me (?:analyze|look at|review|examine|read|organize|process|start))|First,?\s+let me|The user is asking|The raw notes are|The user (?:provided|pasted|gave|wants)|I need to|I'll (?:start|now|begin|analyze)|Here's my (?:analysis|plan)|Below is (?:my|the) (?:analysis|plan)|下面我|让我(?:先|来)?|我来(?:分析|整理|看看))/i;
// 整篇只剩下 JSON envelope (`{"draft":{"markdown":"…"},…}`) 也算污染.
const KNOWLEDGE_NOTE_DIRECT_JSON_ENVELOPE_ONLY_RE = /^\s*\{[\s\S]*?"draft"[\s\S]*?"markdown"[\s\S]*?\}\s*$/;
// 中段里残留的 `<think>` (清理后没清干净的, 用于 quality 检测).
const KNOWLEDGE_NOTE_DIRECT_RESIDUAL_THINK_RE = /<\/?think\b/i;

function cleanKnowledgeNoteDirectMarkdown(raw: string): {
  markdown: string;
  removedBlocks: number;
  removedPreamble: boolean;
  unwrappedJson: boolean;
  issues: string[];
} {
  const issues: string[] = [];
  let text = String(raw || "");
  const before = text;

  // (1) 完整 `<think>…</think>` blocks (multiline, 多组, 大小写不敏感).
  let removedBlocks = 0;
  text = text.replace(KNOWLEDGE_NOTE_DIRECT_THINK_BLOCK_RE, () => {
    removedBlocks += 1;
    return "";
  });
  if (removedBlocks > 0) issues.push("stripped_think_block");

  // (2) 起始位置的未闭合 `<think>` (模型偶发忘记 `</think>` 关闭 tag).
  const unclosed = KNOWLEDGE_NOTE_DIRECT_UNCLOSED_THINK_RE.exec(text);
  if (unclosed) {
    text = text.slice(unclosed[0].length);
    issues.push("stripped_unclosed_think_block");
  }

  // (3) 整篇只是 JSON envelope — 提取 `draft.markdown` 字段.
  let unwrappedJson = false;
  text = text.trim();
  if (KNOWLEDGE_NOTE_DIRECT_JSON_ENVELOPE_ONLY_RE.test(text)) {
    const unwrapped = extractKnowledgeNoteDirectMarkdownFromJsonEnvelope(text);
    if (unwrapped) {
      text = unwrapped;
      unwrappedJson = true;
      issues.push("unwrapped_json_envelope");
    }
  }

  // (4) 移除开头的中英文 chain-of-thought preamble.
  let removedPreamble = false;
  let safety = 0;
  while (KNOWLEDGE_NOTE_DIRECT_PREAMBLE_RE.test(text) && safety < 5) {
    text = text.replace(KNOWLEDGE_NOTE_DIRECT_PREAMBLE_RE, "").trimStart();
    removedPreamble = true;
    safety += 1;
  }
  // (4.5) 同一段开头 line / sentence 中可能串了多个 preamble phrase. 即使
  // 第一个 phrase 在句子中间, 我们也想把同一行/同一段中残留的
  // `Let me analyze` / `The user is asking` / `The raw notes are` 砍掉.
  if (/Let me (?:analyze|look at|review|examine|read|organize|process|start)/i.test(text)
    || /The user is asking/i.test(text)
    || /The raw notes are/i.test(text)
    || /I need to/i.test(text)
    || /下面我|让我(?:先|来)?|我来(?:分析|整理|看看)/.test(text)) {
    // 把首个含 preamble 的行整行砍掉.
    const lines = text.split(/\r?\n/);
    let consumedLines = 0;
    for (let idx = 0; idx < Math.min(lines.length, 12); idx += 1) {
      const line = String(lines[idx] || "").trim();
      if (!line) { consumedLines += 1; continue; }
      if (/^(?:---|-{3,}|#{1,6}\s|[-*+]\s|>\s|\|)/.test(line)) break;
      if (/^source-hash\s*[:：]/i.test(line)) break;
      if (/Let me (?:analyze|look at|review|examine|read|organize|process|start)/i.test(line)
        || /The user is asking/i.test(line)
        || /The raw notes are/i.test(line)
        || /I need to/i.test(line)
        || /下面我|让我(?:先|来)?|我来(?:分析|整理|看看)/.test(line)) {
        consumedLines += 1;
        removedPreamble = true;
        continue;
      }
      break;
    }
    if (consumedLines > 0) text = lines.slice(consumedLines).join("\n");
  }
  if (removedPreamble) issues.push("stripped_preamble");

  // (5) 移除前置说明行 (例如 "Note:", "Output:", "Here's the structured note:", "整理结果:")
  // 直到遇到 `---` / `#` / 空行已结束.
  text = stripKnowledgeNoteDirectPreHeaderNarration(text);

  // (6) 末尾的 "Let me know if you need anything else" / "希望对您有帮助" 等客套
  // 也需要砍掉, 但只砍最后一段.
  text = stripKnowledgeNoteDirectPostFooterNarration(text);

  // (7) 收尾 trim
  text = text.replace(/^\s+|\s+$/g, "");

  if (text === before.trim()) {
    // 没有任何变化, 也记录一下, 便于 quality 阶段判断.
    if (issues.length === 0 && KNOWLEDGE_NOTE_DIRECT_RESIDUAL_THINK_RE.test(text)) {
      issues.push("residual_think_uncleaned");
    }
  }

  return { markdown: text, removedBlocks, removedPreamble, unwrappedJson, issues };
}

function stripKnowledgeNoteDirectPreHeaderNarration(text: string): string {
  // 把 `Note: ...` / `Output: ...` / `整理结果: ...` / `下面是整理后的笔记: ...`
  // 之类的引导行砍掉, 直到遇到 `---` / `#` / `##` / list / 引用 等真正 Markdown
  // 起始符号. 限制最多砍 6 行, 避免误删。
  const lines = text.split(/\r?\n/);
  let consumed = 0;
  let i = 0;
  for (; i < Math.min(lines.length, 12); i += 1) {
    const raw = lines[i];
    const line = String(raw || "").trim();
    if (!line) { consumed += 1; continue; }
    // 真 Markdown 起始, 停.
    if (/^(?:---|-{3,}|#{1,6}\s|[-*+]\s|>\s|\|)/.test(line)) break;
    // 允许 source-hash 行作为说明被吃掉
    if (/^source-hash\s*[:：]/i.test(line)) break;
    // 引导行 pattern
    if (/^(?:Note|Output|Result|Answer|Response|整理结果|整理后的笔记|以下是|下面是|Here's|Here is|Below is|Output is|下面是整理)\s*[:：]/i.test(line)) {
      consumed += 1;
      continue;
    }
    // 不像引导行, 也不是 Markdown 起始 — 保守起见停.
    break;
  }
  if (consumed === 0) return text;
  return lines.slice(consumed).join("\n");
}

function stripKnowledgeNoteDirectPostFooterNarration(text: string): string {
  const lines = text.split(/\r?\n/);
  // 从尾部向前扫描, 跳过空行后, 最多跳过 3 个"客套/分析" 行.
  let tail = lines.length;
  let safety = 0;
  while (tail > 0 && safety < 4) {
    const prev = tail - 1;
    const line = String(lines[prev] || "").trim();
    if (!line) { tail = prev; continue; }
    if (/^(?:Let me know if|Hope this helps|如有(?:需要|疑问)|如果(?:您|你)需要|希望(?:对您|对你)有帮助|如有其他问题)/i.test(line)) {
      tail = prev;
      safety += 1;
      continue;
    }
    break;
  }
  if (tail === lines.length) return text;
  return lines.slice(0, tail).join("\n").replace(/\s+$/, "");
}

function extractKnowledgeNoteDirectMarkdownFromJsonEnvelope(text: string): string | null {
  // 极简 JSON 解析; 直接用 JSON.parse 在 envelope 完整时取 `draft.markdown`.
  try {
    const parsed = JSON.parse(text);
    const candidate = parsed?.draft?.markdown;
    if (typeof candidate === "string" && candidate.trim()) return candidate;
    // 兼容 `{ markdown: "...", ... }` 顶层结构.
    if (typeof parsed?.markdown === "string" && parsed.markdown.trim()) return parsed.markdown;
  } catch {
    return null;
  }
  return null;
}

function assessKnowledgeNoteDirectMarkdownQuality(markdown: string, cleanIssues: string[] = []): {
  passed: boolean;
  score: number;
  issues: string[];
  warnings: string[];
  sanitized: boolean;
  dimensions: Record<string, number>;
  reasonLabel: string;
  advice: string;
} {
  const text = String(markdown || "").trim();
  // 2026-07-06 (rework2): sanitization events from cleanKnowledgeNoteDirectMarkdown
  // (stripped_think_block / stripped_unclosed_think_block / stripped_preamble /
  // unwrapped_json_envelope) are *warnings* when the cleaner successfully
  // removed the offending content. They MUST NOT poison `passed` if the final
  // cleaned markdown is structurally safe (no residual leak, has heading,
  // has source-hash, length ok). Hard-fail only for residual leaks or invalid
  // final content.
  const SANITIZATION_WARNING_TAGS = new Set<string>([
    "stripped_think_block",
    "stripped_unclosed_think_block",
    "stripped_preamble",
    "unwrapped_json_envelope",
  ]);
  const warnings: string[] = [];
  for (const tag of cleanIssues) {
    if (SANITIZATION_WARNING_TAGS.has(tag)) warnings.push(tag);
  }
  const issues: string[] = [];
  for (const tag of cleanIssues) {
    if (!SANITIZATION_WARNING_TAGS.has(tag)) issues.push(tag);
  }

  // (A) residual <think> tag — true defect, hard-fail.
  if (KNOWLEDGE_NOTE_DIRECT_RESIDUAL_THINK_RE.test(text)) {
    issues.push("residual_think_uncleaned");
  }
  // (B) 起始残留 preamble — true defect, hard-fail.
  if (KNOWLEDGE_NOTE_DIRECT_PREAMBLE_RE.test(text)) {
    issues.push("residual_preamble");
  }
  // (C) 仅剩 JSON envelope — true defect, hard-fail.
  if (KNOWLEDGE_NOTE_DIRECT_JSON_ENVELOPE_ONLY_RE.test(text)) {
    issues.push("only_json_envelope");
  }
  // (D) 必须包含至少一个 # 标题或 frontmatter `---`.
  const hasHeading = /^#{1,6}\s+\S/m.test(text);
  const hasFrontmatter = /^---\s*$/m.test(text);
  if (!hasHeading && !hasFrontmatter) {
    issues.push("missing_heading_or_frontmatter");
  }
  // (E) 至少一段 `source-hash` (Obsidian 习惯) 或证据锚点 section.
  const hasSourceHashLine = /^source-hash\s*[:：]/im.test(text);
  if (!hasSourceHashLine) {
    issues.push("missing_source_hash_line");
  }

  // length-based scoring
  const length = text.length;
  let lengthScore = 0;
  if (length >= 1200) lengthScore = 95;
  else if (length >= 800) lengthScore = 88;
  else if (length >= 500) lengthScore = 78;
  else if (length >= 300) lengthScore = 65;
  else if (length >= 150) lengthScore = 48;
  else if (length >= 60) lengthScore = 28;
  else lengthScore = 12;

  // contamination penalty (residual leaks only; sanitization warnings don't count).
  const contaminationIssues = issues.filter((i) => i !== "missing_source_hash_line" && i !== "missing_heading_or_frontmatter");
  const contaminationPenalty = Math.min(60, contaminationIssues.length * 25);

  let score = Math.max(0, Math.min(100, lengthScore - contaminationPenalty));

  // structural bonus
  const hasActionItems = /(^|\n)##\s+行动项[\s\S]*?\n/i.test(text) || /(^|\n)##\s+Action Items?[\s\S]*?\n/i.test(text);
  const hasKeyFacts = /(^|\n)##\s+(?:关键事实|Key Facts)[\s\S]*?\n/i.test(text);
  if (hasActionItems) score = Math.min(100, score + 4);
  if (hasKeyFacts) score = Math.min(100, score + 4);

  // 2026-07-06 (rework2): warnings alone do NOT fail the gate. Only hard defects
  // (issues[]) plus length / score threshold can fail.
  const sanitized = warnings.length > 0;
  const passed = issues.length === 0 && score >= 50 && length >= 200;
  const reasonLabel = passed
    ? (sanitized
      ? "MiniMax 直连输出已通过质量门禁（含清理痕迹）"
      : "MiniMax 直连输出已通过质量门禁")
    : (contaminationIssues.length > 0
      ? "MiniMax 直连输出含污染片段（已清理失败 / 仍残留）"
      : (length < 200
        ? "MiniMax 直连输出内容过短，未达最低质量门槛"
        : "MiniMax 直连输出未达质量门槛"));
  const advice = passed
    ? "可进入保存预览。"
    : "已阻止保存。请重试；若多次失败，可在 UI 切换 qualityMode=m3-html (legacy Gateway) 路径。";

  return {
    passed,
    score,
    issues,
    warnings,
    sanitized,
    dimensions: {
      length: lengthScore,
      contamination: contaminationIssues.length === 0 ? 100 : Math.max(0, 100 - contaminationPenalty),
      structure: (hasActionItems ? 60 : 0) + (hasKeyFacts ? 40 : 0),
    },
    reasonLabel,
    advice,
  };
}

// 2026-07-06 (rework5) — Apply inline Markdown markers to an already
// HTML-escaped line. Run AFTER `escapeHtmlForDirectRender` (so the markers
// are still literal `*` / `~` / `` ` ``) and AFTER the link transform
// (so link text can contain inline markers). Order matters: code first
// (the only marker that consumes backticks, which can contain `*`),
// then bold `**...**` (must run before italic to avoid partial matches),
// then strikethrough `~~...~~`, then italic `*...*` (last because it
// matches single `*` and must not over-consume the middle of `**`).
function applyKnowledgeNoteDirectInlineMarkers(escaped: string): string {
  return escaped
    .replace(/`([^`\n]+?)`/g, (_m, code) => `<code>${code}</code>`)
    .replace(/\*\*([^*\n]+?)\*\*/g, (_m, b) => `<strong>${b}</strong>`)
    .replace(/~~([^~\n]+?)~~/g, (_m, s) => `<del>${s}</del>`)
    .replace(/\*([^*\n]+?)\*/g, (_m, i) => `<em>${i}</em>`);
}

// 2026-07-06 (rework5) — Whether a line is the trailing `source-hash: <hex>`
// metadata line. These are Obsidian-style footer markers that the renderer
// must keep OUT of the visible HTML body — they live in the document
// `<meta name="source-hash">` already, and the cleaned markdown keeps
// them for downstream consumers.
const SOURCE_HASH_LINE_RE = /^\s*source-hash\s*[:：]/i;

// njx-knowledge v2 / Phase 3 — minimax-direct 直连拿到 markdown 后做最小 server-side HTML 包装.
// 不依赖 Gateway HTML pipeline. 失败仍可由 Phase 4 字典校验 + Phase 7 dashboard 单独再 compile.
//
// 2026-07-06 (rework5) — renderer now produces a clean document preview:
//   * YAML frontmatter (`---` block at the top) is stripped from the body.
//   * The trailing `source-hash:` line is stripped from the body (it lives
//     in the document `<meta name="source-hash">` already).
//   * Inline Markdown markers — `**bold**`, `*italic*`, `` `code` ``,
//     `~~strike~~` — are converted to semantic HTML (`<strong>`, `<em>`,
//     `<code>`, `<del>`) so the preview does not show raw `**`, `*`,
//     `` ` ``, or `~~` markers. The contract from the rework5 scope
//     correction: the preview must look like a clean article, not raw
//     Markdown text.
function renderKnowledgeNoteDirectMarkdownAsHtmlSafe(markdown: string, opts: {
  title: string;
  sourceHash: string;
  seed: { title?: string; type?: string; status?: string; tags?: string[]; related?: string[]; folder?: string };
  layoutStrategy?: KnowledgeNoteLayoutStrategyInput;
  agentDecision: { chosenAgent: AgentId; reason: string; escalationNeeded: boolean };
  sourceHashFull: string;
  confidence: number;
}): string {
  // 2026-07-08 (regression-fix): minimax-direct path 默认产 plain markdown HTML.
  //   老 commit `d96aa494` (KB v3, 2026-07-07 16:20) 把 trust fallback (`renderKnowledgeNoteHtmlFromTrustedM3Draft`)
  //   从 minimax-direct 路径剥离,只保留简单 `<h1>/<p>/<ul>` 渲染 (`renderKnowledgeNoteDirectMarkdownAsHtml`).
  //   NJX 7-08 早上抱怨 "添加笔记又没有 html 渲染了" — 对比 7-06 之前走 trust fallback 的 fancy HTML (hero + cards) 现在是 plain.
  // 修复策略: minimax-direct path 默认也调 trust fallback 函数 (产出 hero/cards/TOC/evidence-list 完整 layout),
  //   内部 markdown section 解析对任意 markdown 都有 fallback 文本, 安全.
  //   如果函数内任何意外抛错 (e.g. layout 不全) → fallback 回 plain render, 保证存活的 fallback.
  try {
    const rendered = renderKnowledgeNoteHtmlFromTrustedM3Draft({
      sourceHash: opts.sourceHashFull,
      gatewayRunId: `minimax-direct-${opts.sourceHashFull.slice(0, 12)}`,
      agentDecision: opts.agentDecision,
      draft: {
        markdown,
        title: opts.title,
        type: opts.seed.type,
        status: opts.seed.status,
        tags: opts.seed.tags,
        related: opts.seed.related,
        folder: opts.seed.folder,
      },
      layoutStrategy: opts.layoutStrategy,
      quality: {
        confidence: Math.max(0.5, Math.min(0.95, opts.confidence)),
        sourceCoverage: "minimax_direct",
        unresolvedItems: [],
      },
    });
    return rendered.sanitized.html;
  } catch (err) {
    app.log.warn({ err, sourceHash: opts.sourceHash }, "minimax-direct trusted render fallback to plain");
    return renderKnowledgeNoteDirectMarkdownAsHtml(markdown, { title: opts.title, sourceHash: opts.sourceHash });
  }
}

function renderKnowledgeNoteDirectMarkdownAsHtml(markdown: string, opts: { title: string; sourceHash: string }): string {
  const safeTitle = escapeHtmlForDirectRender(opts.title || "未命名笔记");
  const safeHash = escapeHtmlForDirectRender(opts.sourceHash || "");
  const lines = String(markdown || "").split(/\r?\n/);
  const html: string[] = [];
  let inCode = false;
  let inList = false;
  // frontmatterPhase: "before" (looking for opening `---`) | "in" (consuming
  // frontmatter lines until closing `---`) | "after" (normal body).
  let frontmatterPhase: "before" | "in" | "after" = "before";
  for (const lineRaw of lines) {
    const line = String(lineRaw || "");
    // (1) YAML frontmatter at the top of the document.
    if (frontmatterPhase === "before") {
      if (/^---\s*$/.test(line)) {
        frontmatterPhase = "in";
        continue;
      }
      if (line.trim() === "") continue; // tolerate blank lines before the opening `---`
      frontmatterPhase = "after";
    }
    if (frontmatterPhase === "in") {
      if (/^---\s*$/.test(line)) frontmatterPhase = "after";
      continue;
    }
    // (2) Trailing `source-hash:` metadata line — keep it OUT of the body.
    if (SOURCE_HASH_LINE_RE.test(line)) continue;
    if (line.startsWith("```")) {
      if (inCode) { html.push("</code></pre>"); inCode = false; }
      else { html.push("<pre><code>"); inCode = true; }
      continue;
    }
    if (inCode) {
      html.push(escapeHtmlForDirectRender(line));
      continue;
    }
    let processed = escapeHtmlForDirectRender(line);
    // markdown link: [text](url)
    processed = processed.replace(/\[([^\]]+)\]\(([^\s)]+)\)/g, (_m, text, url) => `<a href="${url}">${text}</a>`);
    // (3) Inline Markdown markers — must run on the HTML-escaped text, AFTER
    // the link transform, BEFORE the block-element wrapping.
    processed = applyKnowledgeNoteDirectInlineMarkers(processed);
    if (/^#\s+/.test(line)) {
      html.push(`<h1>${processed.replace(/^#\s+/, "")}</h1>`);
      continue;
    }
    if (/^##\s+/.test(line)) {
      html.push(`<h2>${processed.replace(/^##\s+/, "")}</h2>`);
      continue;
    }
    if (/^###\s+/.test(line)) {
      html.push(`<h3>${processed.replace(/^###\s+/, "")}</h3>`);
      continue;
    }
    if (/^[-*+]\s+/.test(line)) {
      if (!inList) { html.push("<ul>"); inList = true; }
      html.push(`<li>${processed.replace(/^[-*+]\s+/, "")}</li>`);
      continue;
    }
    if (inList && line.trim() === "") {
      html.push("</ul>");
      inList = false;
      continue;
    }
    if (line.trim() === "") {
      if (inList) { html.push("</ul>"); inList = false; }
      html.push("<br/>");
      continue;
    }
    if (inList) { html.push("</ul>"); inList = false; }
    html.push(`<p>${processed}</p>`);
  }
  if (inCode) html.push("</code></pre>");
  if (inList) html.push("</ul>");
  return `<!doctype html><html lang="zh"><head><meta charset="utf-8"/><meta name="source-hash" content="${safeHash}"/><title>${safeTitle}</title></head><body><article>${html.join("\n")}</article></body></html>`;
}

async function directMinimaxM3Call(prompt: string, opts: { signal?: AbortSignal; timeoutMs?: number; modelHint?: string } = {}): Promise<DirectMinimaxM3CallResult> {
  const base = resolveMinimaxM3BaseUrl();
  const key = resolveMinimaxM3ApiKey();
  const model = String(opts.modelHint || "MiniMax-M3");
  if (key.refSource === "missing") {
    return {
      ok: false, provider: "minimax-direct", model, baseUrl: base.url, baseUrlSource: base.source, apiKeyRefSource: "missing",
      error: { code: "BLOCKED_MINIMAX_DIRECT_CONFIG", message: "minimax API key not found in env (MINIMAX_API_KEY / OPENCLAW_MINIMAX_API_KEY) or model_configs", stage: "resolve_key" },
    };
  }
  if (!key.key) {
    return {
      ok: false, provider: "minimax-direct", model, baseUrl: base.url, baseUrlSource: base.source, apiKeyRefSource: key.refSource,
      error: { code: "BLOCKED_MINIMAX_DIRECT_CONFIG", message: "minimax API key reference set but key value not exposed to in-memory path; configure MINIMAX_API_KEY or OPENCLAW_MINIMAX_API_KEY", stage: "resolve_key" },
    };
  }
  const start = Date.now();
  const timeoutMs = clampNumber(opts.timeoutMs ?? 120_000, 5_000, 570_000, 120_000);
  const controller = new AbortController();
  const t = setTimeout(() => controller.abort(), timeoutMs);
  const signal = opts.signal ? mergeAbortSignals(opts.signal, controller.signal) : controller.signal;
  try {
    const res = await fetch(`${base.url}/chat/completions`, {
      method: "POST",
      headers: { "Content-Type": "application/json", "Authorization": `Bearer ${key.key}` },
      body: JSON.stringify({
        model,
        messages: [{ role: "user", content: prompt }],
        temperature: 0.2,
        max_tokens: 4096,
      }),
      signal,
    });
    const durationMs = Date.now() - start;
    if (!res.ok) {
      const text = await res.text().catch(() => "");
      return {
        ok: false, provider: "minimax-direct", model, baseUrl: base.url, baseUrlSource: base.source, apiKeyRefSource: key.refSource, durationMs,
        error: { code: `minimax_direct_http_${res.status}`, message: text.slice(0, 500), stage: "http_status" },
      };
    }
    const json = await res.json() as { choices?: Array<{ message?: { content?: string }; finish_reason?: string }>; usage?: { prompt_tokens?: number; completion_tokens?: number } };
    const content = json.choices?.[0]?.message?.content || "";
    return {
      ok: true, content, provider: "minimax-direct", model, baseUrl: base.url, baseUrlSource: base.source, apiKeyRefSource: key.refSource,
      finishReason: json.choices?.[0]?.finish_reason, promptTokens: json.usage?.prompt_tokens, completionTokens: json.usage?.completion_tokens, durationMs,
    };
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    return {
      ok: false, provider: "minimax-direct", model, baseUrl: base.url, baseUrlSource: base.source, apiKeyRefSource: key.refSource, durationMs: Date.now() - start,
      error: { code: message.includes("abort") ? "minimax_direct_aborted" : "minimax_direct_failed", message: message.slice(0, 500), stage: "fetch" },
    };
  } finally {
    clearTimeout(t);
  }
}

function mergeAbortSignals(a: AbortSignal, b: AbortSignal): AbortSignal {
  const ctrl = new AbortController();
  const onAbort = () => ctrl.abort();
  a.addEventListener("abort", onAbort, { once: true });
  b.addEventListener("abort", onAbort, { once: true });
  if (a.aborted || b.aborted) ctrl.abort();
  return ctrl.signal;
}

async function organizeKnowledgeNoteDraftHighQuality(input: KnowledgeNoteOrganizeBody, options: { signal?: AbortSignal } = {}) {
  const body = normalizeKnowledgeNoteOrganizeBody(input);
  const seed = organizeKnowledgeNoteDraft(body);
  const rawContent = knowledgeNoteRawContent(body);
  const sourceProfile = knowledgeNoteSourceProfile(rawContent, body);
  // Phase 4: default = minimax-direct 直连 MiniMax-M3. 历史别名 (high / m3 / m3-html / m27 等) 仍允许作为显式 Gateway 路径.
  const __phase1_qmNorm = normalizeKnowledgeNoteQualityMode(body.qualityMode || "minimax-direct");
  const qualityModeAliasReason = __phase1_qmNorm.aliasReason;
  const effectiveMode = __phase1_qmNorm.effective;
  const requestedMode = __phase1_qmNorm.requested;
  const htmlMode = String(body.htmlMode || "m3").toLowerCase();
  const agentDecision = decideKnowledgeNoteAgent({ ...body, type: body.type || seed.type, title: body.title || seed.title, rawContent: body.rawContent });
  const sourceHash = createHash("sha256").update(rawContent).digest("hex");
  if (requestedMode === "local") {
    failKnowledgeNoteGateway("request", "local_mode_disabled_gateway_required", ["local_mode_rejected"], 400);
  }
  // Phase 1 v1: alias 模式下, 把 body.qualityMode 改写为 effective, 让下游 (build prompt / organizeKnowledgeNoteDraft 等) 直接走 m3-html 管线, 不再撞其它 alias-not-supported 错误
  if (effectiveMode !== requestedMode) {
    body.qualityMode = effectiveMode;
    body.requestedQualityMode = requestedMode;
    body.effectiveQualityMode = effectiveMode;
    body.qualityModeAliasReason = qualityModeAliasReason;
  } else {
    body.requestedQualityMode = body.requestedQualityMode || requestedMode;
    body.effectiveQualityMode = body.effectiveQualityMode || effectiveMode;
    body.qualityModeAliasReason = body.qualityModeAliasReason || qualityModeAliasReason;
  }
  // Phase 1 v1: alias 通过 (requested 是原始字符串; effectiveMode 归一化到 m3-html / m27-html)
  if (!["m3-html", "m27-html", "minimax-direct", "high", "m3", "minimax-m3", "minimax_m3"].includes(requestedMode)) {
    failKnowledgeNoteGateway("request", "m3_html_mode_required", ["m3_html_mode_required"], 400);
  }
  if (htmlMode === "local") {
    failKnowledgeNoteGateway("request", "local_html_mode_disabled_gateway_required", ["local_html_mode_rejected"], 400);
  }
  // njx-knowledge v2 / Phase 4 — minimax-direct 直连分支. 不依赖 OpenClaw Gateway ready preflight, 不做隐式 Gateway fallback.
  // 任何 minimax-direct 失败 (key missing / http 非 2xx / timeout / aborted / throw) 都直接 fail-fast,
  // 由调用方 UI 显示 BLOCKED_MINIMAX_DIRECT_CONFIG, 不再路由到 m3-html Gateway 链路 (audit 标记 minimax_direct_failed_no_fallback).
  if (requestedMode === "minimax-direct") {
    const directTimeoutMs = clampNumber(Number(body.gatewayTimeoutMs) || 120_000, 5_000, 570_000, 120_000);
    const directPrompt = buildKnowledgeNoteM3Prompt({ input: body, seed, agentDecision, sourceHash, sourceProfile, promptMode: "direct" });
    const directStage: KnowledgeNoteAttempt["stage"] = "minimax_direct_markdown";
    const minimaxDirectRound: KnowledgeNoteAttempt[] = [];
    let directFailureCode = "minimax_direct_failed";
    let directFailureMessage = "minimax_direct_failed";
    let directFailureBaseUrl = "";
    let directFailureBaseUrlSource: string = "missing";
    let directFailureApiKeyRef: DirectMinimaxCallSource = "missing";
    let directFailureModel = "MiniMax-M3";
    let directFailureDurationMs: number | undefined;
    let directResult: DirectMinimaxM3CallResult;
    try {
      directResult = await directMinimaxM3Call(directPrompt, { signal: options.signal, timeoutMs: directTimeoutMs, modelHint: "MiniMax-M3" });
    } catch (directErr) {
      // directMinimaxM3Call 不预期抛出; 但保留防御性兜底.
      directFailureCode = "minimax_direct_throw";
      directFailureMessage = directErr instanceof Error ? directErr.message : "minimax_direct_throw";
      const minimaxDirectRoundErr: KnowledgeNoteAttempt[] = [{
        attempt: 0, stage: directStage, strategy: "minimax_direct",
        status: "failed", reason: directFailureMessage.slice(0, 200),
      }];
      audit(db, "knowledge.note.direct_minimax", "knowledge_note_direct", requestKnowledgeNoteDirectAuditId(), "warn", {
        provider: "minimax-direct", baseUrl: directFailureBaseUrl, baseUrlSource: directFailureBaseUrlSource, apiKeyRefSource: directFailureApiKeyRef,
        model: directFailureModel, ok: false, error: directFailureCode, message: directFailureMessage.slice(0, 200),
        fallback: "none", requestedQualityMode: body.requestedQualityMode || requestedMode, effectiveQualityMode: "minimax-direct",
        note: "minimax_direct_failed_no_fallback",
      });
      failKnowledgeNoteGateway(
        directStage,
        `${directFailureCode}:${directFailureMessage}`,
        ["local_seed", "minimax_direct_markdown_failed", "minimax_direct_failed_no_fallback"],
        502,
        undefined,
        {
          diagnosis: {
            category: "MiniMax 直连失败",
            reasonLabel: "MiniMax M3 直连抛出异常（不降级到 Gateway）",
            retryable: false,
            rootCause: `minimax-direct 调用抛出异常: ${directFailureMessage}`,
            userAction: "请检查 MiniMax 网络/凭据; 如需 Gateway 路径, 显式切换 qualityMode=m3-html.",
            advice: "minimax-direct 模式下不做 Gateway 隐式 fallback.",
            repairDirectives: ["不要重启 OpenClaw Gateway", "切换 m3-html Gateway 路径需用户显式选择"],
            nextActions: ["配置 MiniMax API key", "或在 UI 切换 qualityMode 为 m3-html (Gateway)"],
          },
          attempts: minimaxDirectRoundErr,
          retryBudget: { allowed: 1, used: 1, remaining: 0, max: 1, exhausted: true, maxMarkdownAttempts: 1, maxHtmlAttempts: 0, maxMarkdownRepairAttempts: 0 },
          debugReports: knowledgeNoteDebugReports(minimaxDirectRoundErr),
          directMinimaxNote: {
            fallback: false,
            reason: directFailureCode,
            provider: "minimax-direct",
            baseUrl: directFailureBaseUrl,
            baseUrlSource: directFailureBaseUrlSource,
            apiKeyRefSource: directFailureApiKeyRef,
            model: directFailureModel,
          },
        },
      );
    }
    directFailureBaseUrl = directResult.baseUrl;
    directFailureBaseUrlSource = directResult.baseUrlSource;
    directFailureApiKeyRef = directResult.apiKeyRefSource;
    directFailureModel = directResult.model;
    directFailureDurationMs = directResult.durationMs;
    if (!directResult.ok || !directResult.content) {
      directFailureCode = directResult.error?.code || "minimax_direct_failed";
      directFailureMessage = directResult.error?.message || "minimax_direct_failed";
      minimaxDirectRound.push({
        attempt: 0, stage: directStage, strategy: "minimax_direct",
        status: "failed", reason: directFailureMessage.slice(0, 200),
      });
      audit(db, "knowledge.note.direct_minimax", "knowledge_note_direct", requestKnowledgeNoteDirectAuditId(), "warn", {
        provider: "minimax-direct", baseUrl: directResult.baseUrl, baseUrlSource: directResult.baseUrlSource, apiKeyRefSource: directResult.apiKeyRefSource,
        model: directResult.model, durationMs: directResult.durationMs, ok: false, error: directFailureCode, message: directFailureMessage.slice(0, 200),
        fallback: "none", requestedQualityMode: body.requestedQualityMode || requestedMode, effectiveQualityMode: "minimax-direct",
        note: "minimax_direct_failed_no_fallback",
      });
      // Phase 4: fail-fast, 不路由到 m3-html Gateway 链路. UI 直接展示 BLOCKED_MINIMAX_DIRECT_CONFIG.
      failKnowledgeNoteGateway(
        directStage,
        `${directFailureCode}:${directFailureMessage}`,
        ["local_seed", "minimax_direct_markdown_failed", "minimax_direct_failed_no_fallback"],
        directFailureCode === "BLOCKED_MINIMAX_DIRECT_CONFIG" ? 503 : 502,
        undefined,
        {
          diagnosis: {
            category: "MiniMax 直连失败",
            reasonLabel: directFailureCode === "BLOCKED_MINIMAX_DIRECT_CONFIG"
              ? "MiniMax API key 未配置（不降级到 Gateway）"
              : "MiniMax M3 直连失败（不降级到 Gateway）",
            retryable: false,
            rootCause: directFailureCode === "BLOCKED_MINIMAX_DIRECT_CONFIG"
              ? "未配置 MINIMAX_API_KEY / OPENCLAW_MINIMAX_API_KEY 或 model_configs 中无 MiniMax API key."
              : `MiniMax API 返回失败 (${directFailureCode}); 这是直连错误, 不是 Gateway 错误, 不要重启 OpenClaw Gateway.`,
            userAction: directFailureCode === "BLOCKED_MINIMAX_DIRECT_CONFIG"
              ? "请在 Workbench 模型配置或环境变量中设置 MiniMax API key 后再整理."
              : "请检查 MiniMax API key / baseUrl / 网络后重试; 若需 Gateway 链路, 显式切换质量模式为 m3-html.",
            advice: "minimax-direct 模式下不做 Gateway 隐式 fallback. 若要 Gateway 路径, 请明确将 qualityMode 切换为 m3-html.",
            repairDirectives: ["不要重启 OpenClaw Gateway", "检查 MiniMax API key / model_configs", "切换 m3-html Gateway 路径需用户显式选择"],
            nextActions: ["配置 MiniMax API key", "或在 UI 切换 qualityMode 为 m3-html (Gateway)"],
          },
          attempts: minimaxDirectRound,
          retryBudget: { allowed: 1, used: 1, remaining: 0, max: 1, exhausted: true, maxMarkdownAttempts: 1, maxHtmlAttempts: 0, maxMarkdownRepairAttempts: 0 },
          debugReports: knowledgeNoteDebugReports(minimaxDirectRound),
          directMinimaxNote: {
            fallback: false,
            reason: directFailureCode,
            provider: "minimax-direct",
            baseUrl: directFailureBaseUrl,
            baseUrlSource: directFailureBaseUrlSource,
            apiKeyRefSource: directFailureApiKeyRef,
            durationMs: directFailureDurationMs,
            model: directFailureModel,
          },
        },
      );
    }
    // 2026-07-06 — minimax-direct 直连拿到 raw content 后必须先清理 + 评估.
    // 不能直接把 `directResult.content` 塞进 `draft.markdown` / `draft.html` / fake-pass
    // `htmlQuality`, 那正是 NJX 截图里的污染源.
    const rawDirectContent = String(directResult.content || "");
    let cleaned = cleanKnowledgeNoteDirectMarkdown(rawDirectContent);
    let cleanedMarkdown = cleaned.markdown;
    let qualityAssessment = assessKnowledgeNoteDirectMarkdownQuality(cleanedMarkdown, cleaned.issues);
    let renderedHtml = renderKnowledgeNoteDirectMarkdownAsHtmlSafe(cleanedMarkdown, {
      title: body.title || seed.title || "未命名笔记",
      sourceHash,
      seed,
      layoutStrategy: normalizeKnowledgeNoteLayoutStrategy(body.layoutStrategy),
      agentDecision,
      sourceHashFull: sourceHash,
      confidence: Math.max(0.5, Math.min(0.95, qualityAssessment.score / 100)),
    });
    // 标记这是不是经过 repair 之后的最终状态. repair 路径会重置这些变量;
    // 非 repair 路径它们保持上面这次初始 direct 调用的结果.
    let didRepair = false;
    let repairRound: KnowledgeNoteAttempt["stage"] = "minimax_direct_markdown_repair";
    let firstRoundPipelineMarker: string | null = null;

    // 2026-07-06 (rework3): 一键 direct repair retry.
    //
    // 默认 `minimax-direct` 路径下, 第一次直接调用拿回的 content 经常是
    // `<think>…</think>` 占满 (低信息密度 transcript 上尤其常见); cleanup 后
    // length=0, 第一次 quality 评估必然失败. 之前 rework1+rework2 把这种 fail
    // 准确地分类成 `blocked_minimax_direct_quality`, 但没尝试自救.
    //
    // 现在: 当 cleanedMarkdown 为空, 或者 cleanIssues/qualityIssues 命中了
    // 这些"清理后还能再抢救一次"的标签时, 我们再做一次额外 direct 调用,
    // prompt 换成 `buildKnowledgeNoteM3RepairPrompt`, 明确告诉模型上一版被拒
    // 的原因, 再走一次同样的 clean+assess 流程. 这一次成功就把它当成最终
    // 结果返回, pipeline 多两个 marker:
    //   `minimax_direct_markdown_empty_after_clean` + `minimax_direct_markdown_repair`.
    //
    // 约束:
    //   * 仅当 `requestedMode === "minimax-direct"` 时触发.
    //   * 只额外调用 MiniMax 一次, 不绕去 Gateway, 不在 server 端做本地模板 fallback.
    //   * 第二次调用同样走 `directMinimaxM3Call`, timeoutMs 与第一次相同.
    //   * 第二次也失败时, 我们把 `attempts` 累计两条, pipeline 改写为
    //     `local_seed -> minimax_direct_markdown -> minimax_direct_markdown_empty_after_clean
    //      -> minimax_direct_markdown_repair_failed -> minimax_direct_failed_no_fallback`,
    //     audit 标记 `minimax_direct_failed_no_fallback` 不变 (不引入 Gateway).
    //   * top-level reason 标记 `minimax_direct_markdown_repair_failed`, 但 stage
    //     仍是 `minimax_direct_markdown_quality`, 因此
    //     `buildKnowledgeNoteFailurePayload` 仍 emit `blocked_minimax_direct_quality`,
    //     copy 仍说"两次直连均未通过质量门禁", 绝不提 API key 配置 / Gateway 重启.
    const REPAIR_TRIGGER_TAGS = new Set<string>([
      "stripped_think_block",
      "stripped_unclosed_think_block",
      "stripped_preamble",
      "unwrapped_json_envelope",
      "only_json_envelope",
      "residual_think_uncleaned",
      "residual_preamble",
      "missing_heading_or_frontmatter",
      "missing_source_hash_line",
    ]);
    const initialQualityFailed = !qualityAssessment.passed || !cleanedMarkdown.trim();
    const initialEmptyAfterClean = !cleanedMarkdown.trim();
    const shouldRepairDirectly = initialQualityFailed
      && (initialEmptyAfterClean
        || cleaned.issues.some((t) => REPAIR_TRIGGER_TAGS.has(t))
        || qualityAssessment.issues.some((t) => REPAIR_TRIGGER_TAGS.has(t)));
    if (shouldRepairDirectly) {
      firstRoundPipelineMarker = initialEmptyAfterClean
        ? "minimax_direct_markdown_empty_after_clean"
        : "minimax_direct_markdown_quality_failed";
      minimaxDirectRound.push({
        attempt: 0, stage: "minimax_direct_markdown_quality",
        strategy: "minimax_direct_quality_gate",
        status: "failed",
        reason: `initial:${firstRoundPipelineMarker}:cleanIssues=${cleaned.issues.join(",") || "none"}; qualityIssues=${qualityAssessment.issues.join(",") || "none"}; length=${cleanedMarkdown.length}`.slice(0, 200),
      });
      const repairPrompt = buildKnowledgeNoteM3RepairPrompt({
        input: body,
        seed,
        agentDecision,
        sourceHash,
        rawContent,
        previousIssues: qualityAssessment.issues,
        previousWarnings: qualityAssessment.warnings,
        previousCleanedLength: cleanedMarkdown.length,
        emptyAfterClean: initialEmptyAfterClean,
      });
      let repairResult: DirectMinimaxM3CallResult | undefined;
      let repairThrew = false;
      try {
        repairResult = await directMinimaxM3Call(repairPrompt, { signal: options.signal, timeoutMs: directTimeoutMs, modelHint: "MiniMax-M3" });
      } catch (repairErr) {
        // repair 自身 throw, 与 first round 的质量失败合并 → 报"两次直连均未通过".
        const throwMsg = repairErr instanceof Error ? repairErr.message : "minimax_direct_throw";
        minimaxDirectRound.push({
          attempt: 1, stage: repairRound, strategy: "minimax_direct_repair",
          status: "failed", reason: `repair_throw:${throwMsg}`.slice(0, 200),
        });
        audit(db, "knowledge.note.direct_minimax", "knowledge_note_direct", requestKnowledgeNoteDirectAuditId(), "warn", {
          provider: "minimax-direct", baseUrl: directResult.baseUrl, baseUrlSource: directResult.baseUrlSource, apiKeyRefSource: directResult.apiKeyRefSource,
          model: directResult.model, ok: false, error: "minimax_direct_markdown_repair_failed",
          initialCleanIssues: cleaned.issues, initialQualityIssues: qualityAssessment.issues, repairError: throwMsg,
          fallback: "none", requestedQualityMode: body.requestedQualityMode || requestedMode, effectiveQualityMode: "minimax-direct",
          note: "minimax_direct_failed_no_fallback",
        });
        // Fall-through to the unified failure block below by setting local state.
        qualityAssessment = {
          passed: false,
          score: 0,
          issues: [...qualityAssessment.issues, "repair_throw"],
          warnings: qualityAssessment.warnings,
          sanitized: false,
          dimensions: qualityAssessment.dimensions,
          reasonLabel: "MiniMax 直连 repair 调用抛出异常（不降级到 Gateway）",
          advice: "minimax-direct repair 调用异常, 不降级到 Gateway.",
        };
        repairThrew = true;
      }
      // 走到这里说明 repair 调用本身没 throw, 可能是 ok 也可能是 transport 失败.
      let repairQualityFailed = true;
      let repairReasonCode = "minimax_direct_markdown_repair_failed";
      let repairCleanIssues: string[] = [];
      let repairCleanedMarkdown = "";
      let repairQualityIssues: string[] = [];
      let repairQualityWarnings: string[] = [];
      if (!repairThrew && repairResult && repairResult.ok && repairResult.content) {
        const repairCleaned = cleanKnowledgeNoteDirectMarkdown(String(repairResult.content || ""));
        const repairAssessment = assessKnowledgeNoteDirectMarkdownQuality(repairCleaned.markdown, repairCleaned.issues);
        repairCleanIssues = repairCleaned.issues;
        repairCleanedMarkdown = repairCleaned.markdown;
        repairQualityIssues = repairAssessment.issues;
        repairQualityWarnings = repairAssessment.warnings;
        const repairOk = repairAssessment.passed && repairCleanedMarkdown.trim();
        minimaxDirectRound.push({
          attempt: 1, stage: repairRound, strategy: "minimax_direct_repair",
          status: repairOk ? "passed" : "failed",
          reason: repairOk
            ? undefined
            : `repair:${repairCleaned.issues.join(",") || "none"};quality=${repairAssessment.issues.join(",") || "none"};length=${repairCleanedMarkdown.length}`.slice(0, 200),
        });
        if (repairOk) {
          // repair 成功 → 用 repair 的结果作为最终 markdown/html, 标记 didRepair.
          cleaned = repairCleaned;
          cleanedMarkdown = repairCleanedMarkdown;
          qualityAssessment = repairAssessment;
          renderedHtml = renderKnowledgeNoteDirectMarkdownAsHtmlSafe(cleanedMarkdown, {
            title: body.title || seed.title || "未命名笔记",
            sourceHash,
            seed,
            layoutStrategy: normalizeKnowledgeNoteLayoutStrategy(body.layoutStrategy),
            agentDecision,
            sourceHashFull: sourceHash,
            confidence: Math.max(0.5, Math.min(0.95, qualityAssessment.score / 100)),
          });
          didRepair = true;
          repairQualityFailed = false;
        } else {
          repairReasonCode = !repairCleanedMarkdown.trim()
            ? "minimax_direct_markdown_empty_after_clean"
            : "minimax_direct_markdown_quality_failed";
        }
      } else if (!repairThrew && repairResult) {
        // transport / http / aborted / throw 已经在 catch 上面处理过. 这里只处理 ok=false.
        minimaxDirectRound.push({
          attempt: 1, stage: repairRound, strategy: "minimax_direct_repair",
          status: "failed",
          reason: `repair_transport:${repairResult.error?.code || "minimax_direct_failed"}`.slice(0, 200),
        });
        repairReasonCode = repairResult.error?.code || "minimax_direct_markdown_repair_failed";
        // repair 走 transport 失败: 不算 quality 失败, 但仍记入 attempts; 走最终
        // 失败分支, stage 仍 `minimax_direct_markdown_quality` (Phase 4 contract).
        qualityAssessment = {
          passed: false,
          score: 0,
          issues: [...qualityAssessment.issues, "repair_transport_failed"],
          warnings: qualityAssessment.warnings,
          sanitized: false,
          dimensions: qualityAssessment.dimensions,
          reasonLabel: "MiniMax 直连 repair 调用失败（不降级到 Gateway）",
          advice: "minimax-direct repair 调用失败, 不降级到 Gateway.",
        };
      }
      if (repairQualityFailed) {
        // 两次直连都没过质量门禁 → 走统一 fail-fast 块, 但 reason 标 "repair_failed".
        audit(db, "knowledge.note.direct_minimax", "knowledge_note_direct", requestKnowledgeNoteDirectAuditId(), "warn", {
          provider: "minimax-direct", baseUrl: directResult.baseUrl, baseUrlSource: directResult.baseUrlSource, apiKeyRefSource: directResult.apiKeyRefSource,
          model: directResult.model, ok: false, error: repairReasonCode,
          initialCleanIssues: cleaned.issues, initialCleanWarnings: qualityAssessment.warnings, initialQualityIssues: qualityAssessment.issues, initialCleanedLength: cleanedMarkdown.length,
          repairCleanIssues, repairCleanedLength: repairCleanedMarkdown.length, repairQualityIssues, repairQualityWarnings,
          fallback: "none", requestedQualityMode: body.requestedQualityMode || requestedMode, effectiveQualityMode: "minimax-direct",
          note: "minimax_direct_failed_no_fallback",
        });
        const failureStage = "minimax_direct_markdown_quality";
        const reasonDetail = `initial=${firstRoundPipelineMarker}:cleanIssues=${cleaned.issues.join(",") || "none"}:qualityIssues=${qualityAssessment.issues.join(",") || "none"}:length=${cleanedMarkdown.length}; repair=${repairReasonCode}:repairCleanIssues=${repairCleanIssues.join(",") || "none"}:repairQualityIssues=${repairQualityIssues.join(",") || "none"}:repairLength=${repairCleanedMarkdown.length}`;
        const reason = `${repairReasonCode}:${reasonDetail}`;
        failKnowledgeNoteGateway(
          failureStage,
          reason,
          [
            "local_seed",
            "minimax_direct_markdown",
            firstRoundPipelineMarker,
            "minimax_direct_markdown_repair_failed",
            "minimax_direct_failed_no_fallback",
          ],
          422,
          undefined,
          {
            diagnosis: {
              category: "MiniMax 直连输出质量未通过",
              reasonLabel: qualityAssessment.reasonLabel || "MiniMax 直连两次质量门禁均未通过（不降级到 Gateway）",
              retryable: true,
              rootCause: `MiniMax 直连第一次质量门禁失败（${firstRoundPipelineMarker}: ${qualityAssessment.issues.join(",") || "low_score"}），已自动再发一次直连 repair 请求；repair 后仍未通过（${repairReasonCode}: ${repairQualityIssues.join(",") || repairCleanIssues.join(",") || "low_score"}）。这是模型输出质量问题，与 MiniMax API key 无关，也与 OpenClaw Gateway 无关，不要重启 Gateway。`,
              userAction: "请重试以触发新的直连请求；若多次失败，可在 UI 切换 qualityMode=m3-html (legacy Gateway) 路径。这是模型输出质量问题，不是 API key 配置问题。",
              advice: "minimax-direct 直连质量门禁已生效；首次直连与一次性 repair 均未达可保存门槛，已阻止进入预览与保存。MiniMax API key 已成功调用，失败原因仅是模型输出质量。",
              repairDirectives: [
                "不要重启 OpenClaw Gateway",
                "不要重新配置 MiniMax API key (本次已成功调用)",
                "重试以触发新的直连请求",
                "若多次失败，在 UI 显式切换 qualityMode=m3-html (legacy Gateway)",
              ],
              nextActions: ["重试当前整理", "或在 UI 切换 qualityMode 为 m3-html (legacy Gateway)"],
            },
            attempts: minimaxDirectRound,
            retryBudget: { allowed: 1, used: 1, remaining: 0, max: 1, exhausted: true, maxMarkdownAttempts: 1, maxHtmlAttempts: 0, maxMarkdownRepairAttempts: 1 },
            debugReports: knowledgeNoteDebugReports(minimaxDirectRound),
            directMinimaxNote: {
              fallback: false,
              reason: repairReasonCode,
              provider: "minimax-direct",
              baseUrl: directResult.baseUrl,
              baseUrlSource: directResult.baseUrlSource,
              apiKeyRefSource: directResult.apiKeyRefSource,
              durationMs: directFailureDurationMs,
              model: directResult.model,
            },
          },
        );
      }
    }

    // Quality 失败必须 fail-fast, 不允许 fake-pass. 错误类别是内容质量, 不是 Gateway.
    // 这里的关键约束:
    //   * 错误 reason 必须是 `minimax_direct_markdown_quality_failed:…` / `…_empty_after_clean`,
    //     这样 buildKnowledgeNoteFailurePayload 能区分 quality vs config 失败, 把它 emit 为
    //     `blocked_minimax_direct_quality`(不是 `blocked_minimax_direct_config`), top-level
    //     copy 永远不出现 "请配置 MiniMax API key" / Gateway 维修 / "请配置 API key" 这种误导文案.
    //   * 诊断 category 明确是 `MiniMax 直连输出质量未通过`, advice 告诉用户重试
    //     或切换 m3-html (legacy), 绝不推荐重启 OpenClaw Gateway.
    //   * cleanedMarkdown 中如果只有 sanitization warnings (stripped_think_block 等) 但没有
    //     残留 leak, assessKnowledgeNoteDirectMarkdownQuality 已经把它视为 warnings (不是
    //     issues), 所以质量门禁会自动放过 (passed: true), 不会走到这里.
    if (!qualityAssessment.passed || !cleanedMarkdown.trim()) {
      const failureStage = "minimax_direct_markdown_quality";
      const reasonCode = cleanedMarkdown.trim()
        ? "minimax_direct_markdown_quality_failed"
        : "minimax_direct_markdown_empty_after_clean";
      const reasonDetail = `cleanIssues=${cleaned.issues.join(",") || "none"}; qualityIssues=${qualityAssessment.issues.join(",") || "none"}; cleanWarnings=${qualityAssessment.warnings.join(",") || "none"}; length=${cleanedMarkdown.length}`;
      const reason = `${reasonCode}:${reasonDetail}`;
      minimaxDirectRound.push({
        attempt: 0, stage: failureStage, strategy: "minimax_direct_quality_gate", status: "failed",
        reason: reasonDetail.slice(0, 200),
      });
      audit(db, "knowledge.note.direct_minimax", "knowledge_note_direct", requestKnowledgeNoteDirectAuditId(), "warn", {
        provider: "minimax-direct", baseUrl: directResult.baseUrl, baseUrlSource: directResult.baseUrlSource, apiKeyRefSource: directResult.apiKeyRefSource,
        model: directResult.model, durationMs: directResult.durationMs, ok: false, error: reasonCode,
        cleanIssues: cleaned.issues, cleanWarnings: qualityAssessment.warnings, qualityIssues: qualityAssessment.issues, cleanedLength: cleanedMarkdown.length,
        fallback: "none", requestedQualityMode: body.requestedQualityMode || requestedMode, effectiveQualityMode: "minimax-direct",
        note: "minimax_direct_failed_no_fallback",
      });
      failKnowledgeNoteGateway(
        failureStage,
        reason,
        ["local_seed", "minimax_direct_markdown_quality_failed", "minimax_direct_failed_no_fallback"],
        422,
        undefined,
        {
          diagnosis: {
            category: "MiniMax 直连输出质量未通过",
            reasonLabel: qualityAssessment.reasonLabel,
            retryable: true,
            // 2026-07-06 rework2: 不要再说 "请配置 MiniMax API key" — API key 已经成功,
            // 失败原因纯粹是模型输出质量. rootCause/userAction/repairDirectives 全部围绕质量门禁.
            rootCause: cleaned.issues.length > 0
              ? `MiniMax 直连返回内容含污染片段（${cleaned.issues.join(",")}），清理后仍残留质量缺陷（${qualityAssessment.issues.join(",") || "low_score"}）。这是模型输出质量问题，与 MiniMax API key 无关，也与 OpenClaw Gateway 无关，不要重启 Gateway。`
              : `MiniMax 直连返回内容质量分=${qualityAssessment.score}，issues=${qualityAssessment.issues.join(",") || "length_or_structure"}。这是模型输出质量问题，与 MiniMax API key 无关，也与 OpenClaw Gateway 无关。`,
            userAction: "请重试以触发新的直连请求；若多次失败，可在 UI 切换 qualityMode=m3-html (legacy Gateway) 路径。这是模型输出质量问题，不是 API key 配置问题。",
            advice: "minimax-direct 直连质量门禁已生效；本次输出未达可保存门槛，已阻止进入预览与保存。MiniMax API key 已成功调用，失败原因仅是输出质量。",
            repairDirectives: ["不要重启 OpenClaw Gateway", "不要重新配置 MiniMax API key (本次已成功调用)", "重试以触发新的直连请求", "若多次失败，在 UI 显式切换 qualityMode=m3-html (legacy Gateway)"],
            nextActions: ["重试当前整理", "或在 UI 切换 qualityMode 为 m3-html (legacy Gateway)"],
          },
          attempts: minimaxDirectRound,
          retryBudget: { allowed: 1, used: 1, remaining: 0, max: 1, exhausted: true, maxMarkdownAttempts: 1, maxHtmlAttempts: 0, maxMarkdownRepairAttempts: 0 },
          debugReports: knowledgeNoteDebugReports(minimaxDirectRound),
          directMinimaxNote: {
            fallback: false,
            reason: reasonCode,
            provider: "minimax-direct",
            baseUrl: directResult.baseUrl,
            baseUrlSource: directResult.baseUrlSource,
            apiKeyRefSource: directResult.apiKeyRefSource,
            durationMs: directFailureDurationMs,
            model: directResult.model,
          },
        },
      );
    }

    minimaxDirectRound.push({
      attempt: 0, stage: directStage, strategy: "minimax_direct", status: "passed",
      reason: directResult.finishReason || undefined,
    });
    audit(db, "knowledge.note.direct_minimax", "knowledge_note_direct", requestKnowledgeNoteDirectAuditId(), didRepair ? "normal" : "normal", {
      provider: "minimax-direct", baseUrl: directResult.baseUrl, baseUrlSource: directResult.baseUrlSource, apiKeyRefSource: directResult.apiKeyRefSource,
      model: directResult.model, durationMs: directResult.durationMs, ok: true, promptTokens: directResult.promptTokens, completionTokens: directResult.completionTokens,
      cleanIssues: cleaned.issues, cleanWarnings: qualityAssessment.warnings, qualityScore: qualityAssessment.score, cleanedLength: cleanedMarkdown.length, sanitized: qualityAssessment.sanitized,
      repaired: didRepair,
      fallback: false, requestedQualityMode: body.requestedQualityMode || requestedMode, effectiveQualityMode: "minimax-direct",
    });
    // 2026-07-06 (rework3): pipeline 必须显式标出 repair 路径, 让 UI / audit / dashboard
    // 区分"一次直连成功" vs "第一次空 / 被拒, repair 救回"。
    const basePipeline = didRepair
      ? [
        "local_seed",
        "minimax_direct_markdown",
        firstRoundPipelineMarker || "minimax_direct_markdown_empty_after_clean",
        "minimax_direct_markdown_repair",
      ]
      : ["local_seed", "minimax_direct_markdown"];
    const finalPipeline = qualityAssessment.sanitized
      ? [...basePipeline, "minimax_direct_markdown_sanitized", "server_render_html"]
      : [...basePipeline, "server_render_html"];
    return {
      knowledgeNotePipelineVersion: KNOWLEDGE_NOTE_PIPELINE_VERSION,
      qualityMode: "minimax-direct",
      draft: { markdown: cleanedMarkdown, title: body.title || seed.title, type: seed.type, status: seed.status, tags: seed.tags, related: seed.related, folder: seed.folder, html: renderedHtml },
      layoutStrategy: normalizeKnowledgeNoteLayoutStrategy(body.layoutStrategy),
      agentDecision,
      quality: { confidence: Math.max(0.5, Math.min(0.95, qualityAssessment.score / 100)), sourceCoverage: "minimax_direct", unresolvedItems: [] },
      htmlDraft: { html: renderedHtml, title: body.title || seed.title || "未命名笔记", sourceHash },
      htmlQuality: {
        passed: qualityAssessment.passed,
        score: qualityAssessment.score,
        issues: qualityAssessment.issues,
        warnings: qualityAssessment.warnings,
        sanitized: qualityAssessment.sanitized,
        dimensions: qualityAssessment.dimensions,
        repaired: didRepair,
      },
      generationPipeline: finalPipeline,
      attempts: minimaxDirectRound,
      diagnosis: null,
      retryBudget: { allowed: 1, used: 1, remaining: 0, max: 1, exhausted: true, maxMarkdownAttempts: 1, maxHtmlAttempts: 0, maxMarkdownRepairAttempts: didRepair ? 1 : 0 },
      debugReports: knowledgeNoteDebugReports(minimaxDirectRound),
      nextActions: [],
      fallbackReason: "",
      requestedQualityMode: body.requestedQualityMode || requestedMode,
      effectiveQualityMode: "minimax-direct",
      qualityModeAliasReason: body.qualityModeAliasReason || "",
      gatewayExecution: null,
      htmlGatewayExecution: null,
      staleRuntimeError: false,
    };
  }
  try {
    await requireGatewayReadyForKnowledgeNote(options.signal);
    const requestedTimeoutMs = Number(body.gatewayTimeoutMs);
    if (Number.isFinite(requestedTimeoutMs) && requestedTimeoutMs > 0 && requestedTimeoutMs < KNOWLEDGE_NOTE_MIN_REAL_GATEWAY_TIMEOUT_MS) {
      failKnowledgeNoteGateway(
        "request",
        `gateway_timeout_budget_too_small:${Math.max(0, Math.floor(requestedTimeoutMs))}ms`,
        ["local_seed", "m3_gateway_fast_fail"],
        503,
      );
    }
    const requestedGatewayTimeoutMs = Number(body.gatewayTimeoutMs);
    const effectiveGatewayTimeoutMs = Number.isFinite(requestedGatewayTimeoutMs) && requestedGatewayTimeoutMs >= KNOWLEDGE_NOTE_M3_GATEWAY_TIMEOUT_MS
      ? requestedGatewayTimeoutMs
      : KNOWLEDGE_NOTE_M3_GATEWAY_TIMEOUT_MS;
    const timeoutMs = clampNumber(effectiveGatewayTimeoutMs, KNOWLEDGE_NOTE_MIN_REAL_GATEWAY_TIMEOUT_MS, 570_000, KNOWLEDGE_NOTE_M3_GATEWAY_TIMEOUT_MS);
    const promptProfile = resolveKnowledgeNotePromptProfile(body, rawContent, sourceProfile);
    const gatewayRunId = randomUUID().slice(0, 12);
    const basePrompt = promptProfile === "calendar-meeting"
      ? buildKnowledgeNoteM3CalendarPrompt({ input: body, seed, agentDecision, sourceHash, sourceProfile })
      : promptProfile === "compact-low-information"
        ? buildKnowledgeNoteM3CompactPrompt({ input: body, seed, agentDecision, sourceHash, sourceProfile })
        : buildKnowledgeNoteM3Prompt({ input: body, seed, agentDecision, sourceHash, sourceProfile });
    const prompt = String(body.manualRepairNote || "").trim()
      ? [
          basePrompt,
          "",
          "=== 用户补充修正指令 ===",
          String(body.manualRepairNote || "").trim().slice(0, 2000),
        ].join("\n")
      : basePrompt;
    const maxMarkdownGatewayAttempts = body.retryPolicy?.autoRepair === false
      ? 1
      : clampNumber(body.retryPolicy?.maxAttempts, 1, 4, 3);
    const maxMarkdownRepairAttempts = Math.max(0, maxMarkdownGatewayAttempts - 1);
    const attempts: KnowledgeNoteAttempt[] = [];
    let markdownResult: KnowledgeNoteMarkdownGatewayResult | null = null;
    let markdownRepairAttempts = 0;
    let lastRepairReason = "";
    while (true) {
      const attemptNumber = markdownRepairAttempts;
      const repairReason = attemptNumber > 0 ? lastRepairReason || markdownResult?.sourceCheck.reason || "quality_repair" : "";
      const repairDirectives = attemptNumber > 0 ? knowledgeNoteRepairDirectivesForAttempt(repairReason, attemptNumber) : [];
      try {
        markdownResult = await requestKnowledgeNoteMarkdownDraft({
          body,
          seed,
          agentDecision,
          sourceHash,
          rawContent,
          prompt,
          promptProfile,
          gatewayRunId,
          timeoutMs,
          signal: options.signal,
          repairReason,
          repairInput: attemptNumber > 0 ? markdownResult?.normalized.draft || null : null,
          repairAttempt: attemptNumber,
        });
      } catch (err) {
        if (isKnowledgeNoteGatewayRequiredError(err)) {
          const failedAttempts = [
            ...attempts,
            {
              attempt: attemptNumber,
              stage: err.stage || "m3_obsidian_markdown",
              strategy: knowledgeNoteAttemptStrategy(attemptNumber, err.reason),
              status: "failed" as const,
              reason: err.reason,
              repairDirectives,
              debugReportPath: err.debugReportPath,
            },
          ];
          const budget = knowledgeNoteRetryBudget(Math.min(failedAttempts.length, maxMarkdownGatewayAttempts), maxMarkdownGatewayAttempts);
          failKnowledgeNoteGateway(
            err.stage,
            err.reason,
            err.generationPipeline,
            err.statusCode,
            err.debugReportPath,
            knowledgeNoteFailureExtras(err.stage, err.reason, failedAttempts, budget, err.debugReportPath),
          );
        }
        throw err;
      }
      attempts.push({
        attempt: attemptNumber,
        stage: "m3_obsidian_markdown",
        strategy: knowledgeNoteAttemptStrategy(attemptNumber, markdownResult.sourceCheck.reason),
        status: markdownResult.sourceCheck.ok ? "passed" : "failed",
        reason: markdownResult.sourceCheck.reason || undefined,
        repairDirectives,
        debugReportPath: markdownResult.debugReportPath,
        confidence: Number(markdownResult.normalized.quality?.confidence || 0) || undefined,
      });
      if (markdownResult.sourceCheck.ok) break;
      if (!isRetryableKnowledgeNoteDraftQualityReason(markdownResult.sourceCheck.reason) || attempts.length >= maxMarkdownGatewayAttempts) {
        const budget = knowledgeNoteRetryBudget(Math.min(attempts.length, maxMarkdownGatewayAttempts), maxMarkdownGatewayAttempts);
        failKnowledgeNoteGateway(
          "m3_obsidian_markdown",
          markdownResult.sourceCheck.reason,
          ["local_seed", "m3_obsidian_markdown_failed"],
          503,
          markdownResult.debugReportPath,
          knowledgeNoteFailureExtras("m3_obsidian_markdown", markdownResult.sourceCheck.reason, attempts, budget, markdownResult.debugReportPath),
        );
      }
      lastRepairReason = markdownResult.sourceCheck.reason;
      markdownRepairAttempts += 1;
    }
    if (!markdownResult) failKnowledgeNoteGateway("m3_obsidian_markdown", "gateway_returned_empty_result", ["local_seed", "m3_obsidian_markdown_failed"]);
    const pipeline = [
      "local_seed",
      "m3_obsidian_markdown",
      ...(attempts.some((attempt) => attempt.strategy === "de_noisy_value_repair") ? ["m3_markdown_quality_repair"] : []),
      ...(attempts.some((attempt) => attempt.strategy === "topic_coverage_repair") ? ["m3_markdown_topic_coverage_repair"] : []),
      ...(attempts.some((attempt) => attempt.strategy === "strict_value_structure_repair") ? ["m3_markdown_value_structure_repair"] : []),
      ...(attempts.some((attempt) => attempt.strategy === "source_reduction_context_repair") ? ["m3_markdown_context_repair"] : []),
    ];
    const normalized = markdownResult.normalized;
    const retryBudget = knowledgeNoteRetryBudget(Math.min(attempts.length, maxMarkdownGatewayAttempts), maxMarkdownGatewayAttempts);
    const htmlResult = await generateKnowledgeNoteM3Html({
      input: body,
      sourceHash,
      gatewayRunId,
      agentDecision: normalized.agentDecision,
      draft: normalized.draft,
      layoutStrategy: normalized.layoutStrategy,
      quality: normalized.quality,
      timeoutMs,
      signal: options.signal,
      priorAttempts: attempts,
      retryBudget,
    });
    return {
      knowledgeNotePipelineVersion: KNOWLEDGE_NOTE_PIPELINE_VERSION,
      qualityMode: "m3-html",
      draft: normalized.draft,
      layoutStrategy: normalized.layoutStrategy,
      agentDecision: normalized.agentDecision,
      quality: normalized.quality,
      htmlDraft: htmlResult.htmlDraft,
      htmlQuality: htmlResult.htmlQuality,
      generationPipeline: [...pipeline, ...htmlResult.generationPipeline],
      attempts: [...attempts, ...(htmlResult.attempts || [])],
      diagnosis: null,
      retryBudget,
      debugReports: knowledgeNoteDebugReports([...attempts, ...(htmlResult.attempts || [])]),
      nextActions: [],
      fallbackReason: "",
      requestedQualityMode: body.requestedQualityMode || requestedMode,
      effectiveQualityMode: body.effectiveQualityMode || "m3-html",
      qualityModeAliasReason: body.qualityModeAliasReason || "",
      gatewayExecution: markdownResult.gatewayAttempt.execution,
      htmlGatewayExecution: (htmlResult as { gatewayExecution?: KnowledgeNoteGatewayExecution }).gatewayExecution,
      staleRuntimeError: false,
    };
  } catch (err) {
    if (isKnowledgeNoteGatewayRequiredError(err)) throw err;
    failKnowledgeNoteGateway("knowledge_note_organize", err instanceof Error ? err.message : "m3_organize_failed", ["gateway_required_failed"]);
  }
}

async function requestKnowledgeNoteMarkdownDraft(input: {
  body: KnowledgeNoteOrganizeBody;
  seed: ReturnType<typeof organizeKnowledgeNoteDraft>;
  agentDecision: { chosenAgent: AgentId; reason: string; escalationNeeded: boolean };
  sourceHash: string;
  rawContent: string;
  prompt: string;
  promptProfile: string;
  gatewayRunId: string;
  timeoutMs: number;
  signal?: AbortSignal;
  repairReason: string;
  repairInput: KnowledgeNoteDraftInput | null;
  repairAttempt?: number;
}): Promise<KnowledgeNoteMarkdownGatewayResult> {
  const message = input.repairReason
    ? buildKnowledgeNoteMarkdownRepairPrompt(input.prompt, input.repairReason, input.repairInput, input.rawContent, input.sourceHash, input.repairAttempt || 1)
    : input.prompt;
  const baseIdempotencyKey = `knowledge-note:${KNOWLEDGE_NOTE_PIPELINE_VERSION}:${KNOWLEDGE_NOTE_GATEWAY_PROMPT_VERSION}:${input.promptProfile}:${input.sourceHash}:${input.gatewayRunId}${input.repairReason ? `:repair${input.repairAttempt || 1}:${safeName(input.repairReason).slice(0, 64)}` : ""}`;
  const requestStartedMs = Date.now();
  const harvestMarkdownGatewayAttempt = (dispatch: GatewayResult | null) => {
    const harvest = recoverKnowledgeNoteGatewayFinalBySourceHash({
      purpose: "markdown",
      sourceHash: input.sourceHash,
      sinceMs: requestStartedMs - 5000,
      preferredAgent: input.agentDecision.chosenAgent,
      requirePromptMarker: KNOWLEDGE_NOTE_GATEWAY_PROMPT_VERSION,
    });
    if (!harvest) return null;
    return {
      gateway: knowledgeNoteGatewayResultFromLateHarvest(harvest, dispatch || undefined),
      execution: {
        roleAgent: input.agentDecision.chosenAgent,
        executionAgent: harvest.agentId,
        reason: "late_m3_session_source_hash_harvest",
        rerouteReason: dispatch?.error || "gateway_final_not_delivered_to_workbench",
        sessionKey: harvest.sessionKey,
      } as KnowledgeNoteGatewayExecution,
    };
  };
  const callMarkdownGateway = (transportRetry = 0) => callKnowledgeNoteGatewayAgentWithLateHarvest({
    preferredAgent: input.agentDecision.chosenAgent,
    purpose: "markdown",
    sourceHash: input.sourceHash,
    runId: transportRetry ? `${input.gatewayRunId}-transport-${transportRetry}` : input.gatewayRunId,
    message: transportRetry
      ? [
          message,
          "",
          "=== Gateway transport retry ===",
          "上一轮 Gateway 连接提前关闭或 tick timeout。请重新生成同一 sourceHash 的最终 JSON，不要续写旧会话，不要输出解释文字。",
          "保持事实、标题、行动项和来源依据不变；如果信息不足，写低信息密度判断和待核验。",
        ].join("\n")
      : message,
    idempotencyKey: transportRetry ? `${baseIdempotencyKey}:transport-retry-${transportRetry}` : baseIdempotencyKey,
    timeoutMs: transportRetry ? Math.min(input.timeoutMs, 120_000) : input.timeoutMs,
    signal: input.signal,
    harvestSinceMs: requestStartedMs - 5000,
  });
  let gatewayAttempt = await callMarkdownGateway();
  let gateway = gatewayAttempt.gateway;
  if (!gateway.ok && isRecoverableKnowledgeNoteMarkdownTransportError(gateway.error)) {
    const firstReason = gateway.error || "gateway_unavailable";
    const firstDebugReportPath = writeKnowledgeNoteGatewayDebugReport({
      stage: "m3_obsidian_markdown",
      reason: `gateway_transport_first_failed:${firstReason}`,
      sourceHash: input.sourceHash,
      runId: input.gatewayRunId,
      promptProfile: input.promptProfile,
      repairAttempt: input.repairReason ? input.repairAttempt || 1 : 0,
      gatewayText: "",
      gatewayData: { status: gateway.status, error: gateway.error, data: gateway.data, execution: gatewayAttempt.execution },
    });
    if (!shouldImmediateKnowledgeNoteGatewayTransportRetry(firstReason)) {
      failKnowledgeNoteGateway(
        "m3_obsidian_markdown",
        `gateway_transport_first_failed:${firstReason}`,
        ["local_seed", "m3_obsidian_markdown_failed", "m3_markdown_transport_deferred_to_worker_ops"],
        503,
        firstDebugReportPath,
      );
    }
    await sleep(2000, input.signal);
    const retryAttempt = await callMarkdownGateway(1);
    if (retryAttempt.gateway.ok) {
      gatewayAttempt = retryAttempt;
      gateway = retryAttempt.gateway;
    } else {
      const retryReason = retryAttempt.gateway.error || "gateway_unavailable";
      const debugReportPath = writeKnowledgeNoteGatewayDebugReport({
        stage: "m3_obsidian_markdown",
        reason: `gateway_transport_retry_failed:${firstReason}; ${retryReason}`,
        sourceHash: input.sourceHash,
        runId: input.gatewayRunId,
        promptProfile: input.promptProfile,
        repairAttempt: input.repairReason ? input.repairAttempt || 1 : 0,
        gatewayText: "",
        gatewayData: {
          first: { status: gateway.status, error: gateway.error, data: gateway.data, execution: gatewayAttempt.execution },
          retry: { status: retryAttempt.gateway.status, error: retryAttempt.gateway.error, data: retryAttempt.gateway.data, execution: retryAttempt.execution },
        },
      });
      failKnowledgeNoteGateway(
        "m3_obsidian_markdown",
        `gateway_transport_retry_failed:${firstReason}; ${retryReason}`,
        ["local_seed", "m3_obsidian_markdown_failed", "m3_markdown_transport_retry_failed"],
        503,
        debugReportPath,
      );
    }
  }
  if (!gateway.ok) {
    const harvestedAttempt = harvestMarkdownGatewayAttempt(gateway);
    if (harvestedAttempt) {
      gatewayAttempt = harvestedAttempt;
      gateway = harvestedAttempt.gateway;
    }
  }
  if (!gateway.ok) failKnowledgeNoteGateway("m3_obsidian_markdown", gateway.error || "gateway_unavailable", ["local_seed", "m3_obsidian_markdown_failed"]);
  let gatewayText = extractGatewayText(gateway.data);
  let parsed = parseKnowledgeNoteGatewayJson(gatewayText) || extractKnowledgeNoteGatewayDraftObject(gateway.data);
  if (!parsed) {
    const harvestedAttempt = harvestMarkdownGatewayAttempt(gateway);
    if (harvestedAttempt) {
      const harvestedText = extractGatewayText(harvestedAttempt.gateway.data);
      const harvestedParsed = parseKnowledgeNoteGatewayJson(harvestedText) || extractKnowledgeNoteGatewayDraftObject(harvestedAttempt.gateway.data);
      if (harvestedParsed) {
        gatewayAttempt = harvestedAttempt;
        gateway = harvestedAttempt.gateway;
        gatewayText = harvestedText;
        parsed = harvestedParsed;
      }
    }
  }
  if (!parsed && !input.repairReason) {
    gatewayAttempt = await callKnowledgeNoteGatewayAgentWithLateHarvest({
      preferredAgent: input.agentDecision.chosenAgent,
      purpose: "markdown",
      sourceHash: input.sourceHash,
      runId: input.gatewayRunId,
      message: buildKnowledgeNoteMarkdownFormatRepairPrompt(input.prompt, gatewayText, input.sourceHash),
      idempotencyKey: `knowledge-note:${KNOWLEDGE_NOTE_PIPELINE_VERSION}:${KNOWLEDGE_NOTE_GATEWAY_PROMPT_VERSION}:${input.promptProfile}:${input.sourceHash}:${input.gatewayRunId}:format-repair`,
      timeoutMs: input.timeoutMs,
      signal: input.signal,
      harvestSinceMs: requestStartedMs - 5000,
    });
    gateway = gatewayAttempt.gateway;
    if (!gateway.ok) failKnowledgeNoteGateway("m3_obsidian_markdown", gateway.error || "gateway_unavailable", ["local_seed", "m3_obsidian_markdown_failed", "m3_markdown_format_repair_failed"]);
    gatewayText = extractGatewayText(gateway.data);
    parsed = parseKnowledgeNoteGatewayJson(gatewayText) || extractKnowledgeNoteGatewayDraftObject(gateway.data);
  }
  if (!parsed) {
    const debugReportPath = writeKnowledgeNoteGatewayDebugReport({
      stage: "m3_obsidian_markdown",
      reason: "gateway_returned_non_json",
      sourceHash: input.sourceHash,
      runId: input.gatewayRunId,
      promptProfile: input.promptProfile,
      repairAttempt: input.repairReason ? input.repairAttempt || 1 : 0,
      gatewayText,
      gatewayData: gateway.data,
    });
    failKnowledgeNoteGateway("m3_obsidian_markdown", "gateway_returned_non_json", ["local_seed", "m3_obsidian_markdown_failed"], 503, debugReportPath);
  }
  const normalized = normalizeGatewayKnowledgeDraft(parsed, input.seed, input.agentDecision);
  const sourceCheck = validateGatewayKnowledgeDraftSource(parsed, normalized.draft, input.seed, input.rawContent, input.sourceHash);
  const debugReportPath = sourceCheck.ok ? "" : writeKnowledgeNoteGatewayDebugReport({
    stage: "m3_obsidian_markdown",
    reason: sourceCheck.reason,
    sourceHash: input.sourceHash,
    runId: input.gatewayRunId,
    promptProfile: input.promptProfile,
    repairAttempt: input.repairReason ? input.repairAttempt || 1 : 0,
    gatewayText,
    gatewayData: gateway.data,
  });
  return { gatewayAttempt, parsed, normalized, sourceCheck, repaired: Boolean(input.repairReason), debugReportPath };
}

function writeKnowledgeNoteGatewayDebugReport(input: {
  stage: string;
  reason: string;
  sourceHash: string;
  runId: string;
  promptProfile: string;
  repairAttempt: number;
  gatewayText: string;
  gatewayData: unknown;
}) {
  try {
    const day = nowIso().slice(0, 10);
    const dir = path.join(SIDECAR_DIR, "debug", "knowledge-notes", day);
    fs.mkdirSync(dir, { recursive: true });
    const file = path.join(dir, `${safeName(`${input.stage}-${input.reason}-${input.sourceHash.slice(0, 10)}-${input.runId}`).slice(0, 120)}.json`);
    const report = {
      ok: false,
      ts: nowIso(),
      stage: input.stage,
      reason: input.reason,
      sourceHash: input.sourceHash,
      runId: input.runId,
      promptProfile: input.promptProfile,
      repairAttempt: input.repairAttempt,
      parser: "parseKnowledgeNoteGatewayJson",
      gatewayTextPreview: redactKnowledgeNoteGatewayDebugText(input.gatewayText).slice(0, 16_000),
      gatewayDataPreview: redactKnowledgeNoteGatewayDebugText(JSON.stringify(input.gatewayData, null, 2)).slice(0, 20_000),
    };
    fs.writeFileSync(file, `${JSON.stringify(report, null, 2)}\n`, "utf8");
    return file;
  } catch {
    return "";
  }
}

function redactKnowledgeNoteGatewayDebugText(value: string) {
  return String(value || "")
    .replace(/(api[_-]?key|authorization|bearer|token|password|secret)(["'\s:=]+)([^"'\s,}]+)/gi, "$1$2[redacted]")
    .replace(/sk-[A-Za-z0-9_-]{12,}/g, "sk-[redacted]")
    .replace(/Bearer\s+[A-Za-z0-9._~+/-]+=*/gi, "Bearer [redacted]");
}

function isRetryableKnowledgeNoteDraftQualityReason(reason: string) {
  return /gateway_source_hash_mismatch|low_value_or_noisy_summary|insufficient_topic_coverage|source_mismatch:reliability_template_not_supported/.test(String(reason || ""));
}

function isRecoverableKnowledgeNoteMarkdownTransportError(error: unknown) {
  const text = String(error || "");
  return isRecoverableGatewayFinalError(text)
    || /gateway_transport_retry_failed|gateway_final_retry_failed|gateway_unavailable|tick timeout|gateway closed \((1000|1006|1012|4000)\)|normal closure|no close reason|ECONNRESET|ETIMEDOUT/i.test(text);
}

function shouldImmediateKnowledgeNoteGatewayTransportRetry(error: unknown) {
  const text = String(error || "");
  if (/Gateway CLI queue timeout|OpenClaw Gateway CLI timed out|timed out after \d+ms|tick timeout/i.test(text)) return false;
  return /gateway closed \((1000|1006|1012)\)|normal closure|no close reason|ECONNRESET|ETIMEDOUT/i.test(text);
}

function isInsufficientKnowledgeNoteTopicCoverageReason(reason: string) {
  return /insufficient_topic_coverage/.test(String(reason || ""));
}

function isSoftAcceptableKnowledgeNoteQualityReason(reason: string) {
  return /low_value_or_noisy_summary|insufficient_topic_coverage/.test(String(reason || ""));
}

function buildKnowledgeNoteMarkdownRepairPrompt(
  basePrompt: string,
  reason: string,
  previousDraft: KnowledgeNoteDraftInput | null,
  rawContent: string,
  sourceHash: string,
  repairAttempt: number,
) {
  const coverageRepair = buildKnowledgeNoteTopicCoverageRepairSection(reason, rawContent);
  return [
    basePrompt,
    "",
    "=== 服务端质量门槛未通过，必须修订后重新输出严格 JSON ===",
    `修订轮次：${repairAttempt}`,
    `失败原因：${reason}`,
    `当前 sourceHash：${sourceHash}`,
    `硬约束：顶层 JSON.sourceHash 必须严格等于 ${sourceHash}；draft.markdown 的原始记录入口也必须使用这个 hash。不要沿用上一版草稿或历史会话中的任何旧 hash。`,
    coverageRepair,
    "修订要求：",
    "1. 不要复述口语转写，不要保留脏话、语气词和无意义闲聊。",
    "2. 如果原文信息密度低，不要编造高价值内容；用 `## 高价值摘要` 说明低信息密度，并给出 `## 待核验` 与 `## 原始记录入口`。",
    "3. Markdown 必须至少包含这些二级标题：`## 高价值摘要`、`## 价值提炼` 或 `## 低信息密度判断`、`## 金句 / 判断句`、`## 行动项`、`## 待核验`、`## 来源依据`、`## 原始记录入口`。",
    "4. 金句必须是整理后的判断句，不能直接引用粗口或低价值口语。",
    "5. 不得引入原文没有的 MBA、安委会、可靠性会、外交、课程、系统开发等主题。",
    repairAttempt >= 2 ? [
      "",
      "=== 价值结构强修复 ===",
      "上一轮仍未达到内容质量门槛。必须把草稿从口语记录改成可复用工作笔记：",
      "1. `## 高价值摘要` 用 3-5 句写清楚发生了什么、核心矛盾是什么、为什么值得记录。",
      "2. `## 关键判断` 至少列 2 条可复用判断；证据不足时写 `待核验`，不要编造。",
      "3. `## 证据锚点` 至少列 3 条原文净化短句；不得直接粘贴说话人时间戳转写。",
      "4. `## 行动项` 区分已明确行动、建议行动、待确认行动。",
      "5. 如果原文只有闲聊或低信息内容，必须明确写 `## 低信息密度判断`，说明无法沉淀的原因。",
    ].join("\n") : "",
    repairAttempt >= 3 ? [
      "",
      "=== 源文本压缩与上下文缺口修复 ===",
      "如果信息密度仍然不足，只保留可证实核心议题，删除寒暄、重复句、情绪化表达和无关闲聊。",
      "输出必须包含 `## 需要用户补充的上下文`，列出继续整理需要的会议背景、项目目标、决策对象、责任人或截止时间。",
      "不要为了通过质量门槛扩写不存在的事实；宁可返回低信息密度判断，也不要生成漂亮但无证据的总结。",
    ].join("\n") : "",
    previousDraft ? "上一版草稿：" : "",
    previousDraft ? JSON.stringify({ title: previousDraft.title, type: previousDraft.type, tags: previousDraft.tags, related: previousDraft.related, markdown: String(previousDraft.markdown || "").slice(0, 12_000) }, null, 2) : "",
  ].filter(Boolean).join("\n");
}

function buildKnowledgeNoteTopicCoverageRepairSection(reason: string, rawContent: string) {
  if (!isInsufficientKnowledgeNoteTopicCoverageReason(reason)) return "";
  const missingLabels = missingKnowledgeNoteCoverageLabels(reason);
  if (!missingLabels.length) return "";
  const specs = allExpectedKnowledgeNoteTopics();
  const source = String(rawContent || "");
  const rows = missingLabels.map((label, index) => {
    const spec = specs.find((item) => item.label === label);
    const outputTerms = spec?.outputTerms?.length ? spec.outputTerms.join(" / ") : label;
    const evidence = spec ? knowledgeNoteTopicEvidenceSnippets(source, spec).join("；") : "";
    return [
      `${index + 1}. ${label}`,
      `   - Markdown 必须出现的主题词：${outputTerms}`,
      `   - coverageMap.topic 必须使用这个主题名：${label}`,
      evidence ? `   - 原文证据片段：${evidence}` : "   - 原文证据片段：从原始笔记中选择最相关的短句，不得编造。",
    ].join("\n");
  });
  return [
    "=== 主题覆盖补齐硬约束 ===",
    "上一版没有覆盖原文中被检测到的主要主题。你必须补齐，而不是改写成更窄的系统开发/API/个人感想主题。",
    "缺失主题清单：",
    ...rows,
    "输出要求：",
    "1. JSON.coverageMap 必须逐项包含上方缺失主题，每项写 topic/evidence/coveredIn。",
    "2. JSON.sourceAnchors 必须逐项给出可回溯的原文证据短句；证据薄弱时写 missingRisk，但不得完全遗漏。",
    "3. draft.markdown 必须新增或更新 `## 主题覆盖清单`，逐项写出上方主题、来源依据和可复用判断。",
    "4. draft.markdown 的 `## 高价值摘要` 与 `## 价值提炼` 必须整合这些主题，而不是只列标签。",
    "5. 不得为了通过检测机械堆词；每个主题必须有一句明确的人类可读判断。",
  ].join("\n");
}

function missingKnowledgeNoteCoverageLabels(reason: string) {
  const marker = "insufficient_topic_coverage:";
  const text = String(reason || "");
  const start = text.indexOf(marker);
  if (start < 0) return [];
  return uniqueStrings(text
    .slice(start + marker.length)
    .split(/[,，;；\n]/)
    .map((item) => item.trim())
    .filter(Boolean));
}

function knowledgeNoteTopicEvidenceSnippets(rawContent: string, spec: ExpectedKnowledgeTopic) {
  const lines = String(rawContent || "")
    .split(/\r?\n+/)
    .map((line) => line.trim())
    .filter(Boolean);
  const snippets = lines.filter((line) => spec.patterns.some((pattern) => pattern.test(line)));
  return uniqueStrings(snippets.map((line) => line.replace(/\s+/g, " ").slice(0, 160))).slice(0, 3);
}

function buildKnowledgeNoteMarkdownFormatRepairPrompt(basePrompt: string, previousGatewayText: string, sourceHash: string) {
  return [
    basePrompt,
    "",
    "=== 上一版不是可解析 JSON，必须只修复输出格式 ===",
    "失败原因：Workbench 未能 JSON.parse 上一版输出。常见原因是 markdown 字段内出现真实换行、未转义引号、输出过长被 Gateway 截断，或 payload 前有 output new_sensitive 标记。",
    `必须保留 sourceHash=${sourceHash}。`,
    "只返回一个严格 JSON 对象，不要 Markdown 代码块外的说明，不要思考过程。",
    "输出长度硬约束：整个 JSON 控制在 9000 字符以内；draft.markdown 控制在 900-1500 中文字；coverageMap/sourceAnchors 最多各 3 条。",
    "draft.markdown 必须是合法 JSON 字符串：所有换行必须写成 \\n，所有双引号必须写成 \\\"。",
    "如果上一版已过长，请只保留 draft、layoutStrategy、agentDecision、quality、missingRisk；不要展开长 coverageMap。",
    "不要改变事实、标题、类型、标签、质量判断或来源依据；只重新输出合法 JSON。",
    "上一版输出片段（仅供格式修复，不得新增事实）：",
    String(previousGatewayText || "").slice(0, 8_000),
  ].join("\n");
}

function shouldUseCompactKnowledgeNotePrompt(
  rawContent: string,
  sourceProfile: ReturnType<typeof knowledgeNoteSourceProfile>,
) {
  const source = String(rawContent || "");
  const compactLength = source.replace(/\s+/g, "").length;
  if (compactLength === 0) return false;
  if (sourceProfile.isCourseTranscript || sourceProfile.isDegreeCourse || sourceProfile.hasCourseEvidence) return false;
  if (/安委会|安全委员会|安全会议|可靠性会|可靠性会议|MEL|O项|串件|鸟击|航前|机械取消|维修差错|MBA|EMBA|工程硕士/i.test(source)) {
    return false;
  }
  const meaningfulLines = source
    .split(/\r?\n/)
    .map((line) => line
      .replace(/^\s*[\u4e00-\u9fa5A-Za-z0-9_ -]{1,18}\s+\d{1,2}:\d{2}(?::\d{2})?\s*/, "")
      .replace(/^\s*\d{1,2}:\d{2}(?::\d{2})?\s*/, "")
      .replace(/^\s*(朋友|用户|发言人|主持人|嘉宾)\d*[:：]?\s*/, "")
      .trim())
    .filter((line) => line.length >= 8 && !/^(嗯+|啊+|好的|可以|对|对啊|好|行|OK|谢谢)$/i.test(line));
  const hasLowSignalCue = sourceProfile.evidence.casualSignals || /闲聊|聊天|随口|不等了|扩容|准备得踢|小组赛|朋友\d+/i.test(source);
  return compactLength < 900 && meaningfulLines.length <= 10 && hasLowSignalCue;
}

function resolveKnowledgeNotePromptProfile(
  body: KnowledgeNoteOrganizeBody,
  rawContent: string,
  sourceProfile: ReturnType<typeof knowledgeNoteSourceProfile>,
): KnowledgeNotePromptProfile {
  if (shouldUseCompactKnowledgeNotePrompt(rawContent, sourceProfile)) return "compact-low-information";
  if (isCalendarKnowledgeNoteInput(body, rawContent)) return "calendar-meeting";
  return "full";
}

function isCalendarKnowledgeNoteInput(body: Partial<KnowledgeNoteOrganizeBody>, rawContent = "") {
  const folder = String(body.folder || "");
  const text = `${body.title || ""}\n${body.type || ""}\n${Array.isArray(body.tags) ? body.tags.join(" ") : ""}\n${rawContent}`.slice(0, 20_000);
  return /^calendar(?:\/|$)/i.test(folder)
    || /日程笔记|同步日程|当日日程|早会|例会|会议主持人|会议纪要|会议记录/i.test(text);
}

function decideKnowledgeNoteAgent(input: KnowledgeNoteDraftInput & { agentId?: string }): { chosenAgent: AgentId; reason: string; escalationNeeded: boolean } {
  if (input.agentId === "main" || input.agentId === "boss" || input.agentId === "worker") {
    return { chosenAgent: input.agentId, reason: "用户指定执行代理。", escalationNeeded: false };
  }
  const text = `${input.title || ""}\n${input.type || ""}\n${input.rawContent || ""}`.slice(0, 20_000);
  const isCapturedConversation = isKnowledgeNoteCapturedConversation(text);
  const looksLikeLearningRecord = /学习笔记|课程|课堂|MBA|EMBA|工程硕士|培训|复训/i.test(text);
  const hasStrategicDecisionSignal = /决策|战略|规划|路线图|投资|商业模式|价值审计|产品评审|PRD|竞争|取舍|预算/i.test(text) || input.type === "决策记录";
  if (hasStrategicDecisionSignal && !looksLikeLearningRecord && !/午间咖啡|咖啡闲聊|闲聊|聊天|转写|录音/i.test(text)) {
    return { chosenAgent: "boss", reason: "内容涉及战略、决策或价值判断，交给 boss 做高阶整理。", escalationNeeded: false };
  }
  if (isCapturedConversation) {
    return { chosenAgent: "worker", reason: "内容是录音转写/会议/闲聊记录，属于知识治理整理任务，交给 worker。", escalationNeeded: false };
  }
  if (hasDirectSystemOperationsIntent(text)) {
    return { chosenAgent: "main", reason: "内容是直接系统运维、配置或故障处理任务，交给 main。", escalationNeeded: false };
  }
  return { chosenAgent: "worker", reason: "内容属于知识治理执行工作，默认交给 worker 进行语义重写。", escalationNeeded: false };
}

function isKnowledgeNoteCapturedConversation(text: string) {
  const source = String(text || "");
  const speakerTimeCount = (source.match(/(?:^|\n)\s*[\u4e00-\u9fa5A-Za-z0-9_ -]{1,18}\s+\d{1,2}:\d{2}(?::\d{2})?\s*(?:\n|$)/g) || []).length;
  const timestampCount = (source.match(/(?:^|\n)\s*\d{1,2}:\d{2}(?::\d{2})?\s*(?:\n|$)/g) || []).length;
  return speakerTimeCount >= 2
    || timestampCount >= 3
    || /午间咖啡|咖啡闲聊|闲聊|聊天|录音|转写|谈话记录|会议纪要|早会|例会/i.test(source);
}

function hasDirectSystemOperationsIntent(text: string) {
  const source = String(text || "");
  const operationVerb = "(请|需要|必须|继续|执行|修复|排查|配置|重启|发布|部署|上线|监控|验证|恢复|升级)";
  const systemNoun = "(Gateway|Workbench|API|数据库|权限|密钥|token|服务|代码|openclaw_workbench|构建|测试|端口|进程)";
  return new RegExp(`${operationVerb}.{0,48}${systemNoun}|${systemNoun}.{0,48}(报错|失败|异常|不可用|超时|重启|发布|部署|修复|排查|配置)`, "i").test(source);
}

function buildKnowledgeNoteM3SimplePrompt(input: {
  input: KnowledgeNoteDraftInput;
  seed: ReturnType<typeof organizeKnowledgeNoteDraft>;
  agentDecision: { chosenAgent: AgentId; reason: string; escalationNeeded: boolean };
  sourceHash: string;
  rawContent: string;
  calendarHint?: boolean;
  // 2026-07-06 — minimax-direct 直连不再要求 JSON output. Direct 路径下模型返回
  // 内容会被 server-side 清理 + 评估, JSON envelope 反而会污染. Legacy Gateway
  // 路径继续要 JSON (legacy parser 依赖 JSON contract).
  promptMode?: "direct" | "gateway";
}) {
  const promptMode = input.promptMode || "gateway";
  const isDirect = promptMode === "direct";
  const seedSummary = {
    title: input.seed.title,
    date: input.seed.date,
    type: input.seed.type,
    status: input.seed.status,
    tags: input.seed.tags,
    related: input.seed.related,
    folder: input.seed.folder,
  };
  if (isDirect) {
    return [
      `Workbench mode: knowledge-note-organize-direct; Prompt version: ${KNOWLEDGE_NOTE_GATEWAY_PROMPT_VERSION}; Preferred model config: minimax-m3`,
      `Source hash: ${input.sourceHash}`,
      "你是知识整理助手。把用户粘贴的原始笔记整理为 Obsidian 长期可用的 Markdown 笔记。",
      "",
      "【硬约束 — 任何违反都会让整次整理失败】",
      "1. 只输出最终可保存的 Obsidian Markdown 笔记本体。**不要输出 JSON, 不要输出任何包装层, 不要任何解释/前言/后记**。",
      "2. **绝对不要**输出 <think>…</think> 或任何形式的 chain-of-thought / 内部推理。也不要写 `Let me analyze`、`The user is asking`、`The raw notes are`、`I need to`、`First, let me`、`Below is my analysis`、`I'll start by`、中文「下面我」「让我先」「我来分析一下」之类的分析 preamble。",
      "3. **直接以笔记本体开始**: 如果用 frontmatter, 先输出 `---` 起头的 YAML; 否则以 `# <标题>` 起头。不要在笔记前写 `Note:`、`Output:`、`整理结果:`、`Here's the structured note:` 之类的引导行。",
      "4. 只整理原文, 不编造内容。如果原文模糊、缺上下文或与外部知识冲突, 照实写「原文未说明」或「待核验」, 不要补全。",
      "5. Obsidian 习惯: frontmatter（tags/date/type/status/related）+ `# 标题` + `## 小节`。Markdown 末尾必须写一行 `source-hash: <hash>` 标记本次来源。",
      "6. Markdown 必须包含以下小节（按需命名, 顺序可调）: ## 高价值摘要、## 关键事实、## 行动项、## 风险与待核验、## 证据锚点、## 原始记录入口。没有行动项时写「未从原文确认」。",
      "7. 不得复用历史会话、固定模板（可靠性会议 / 安委会 / MBA / 系统开发 等）或其他录音的主题；每个结论必须能在本次原文找到证据锚点。证据锚点必须是净化后的原文短句或时间线线索, 不要直接粘贴大段逐字稿。",
      "",
      "【输出形态 — 仅以下面之一开始, 后面立即是 Markdown 本体】",
      "(A) frontmatter 形态:",
      "---",
      "title: <标题>",
      "date: YYYY-MM-DD",
      "type: <类型>",
      "status: <状态>",
      "tags: [<tag>...]",
      "related: [<[[实体]]>...]",
      "folder: openclaw",
      "---",
      "",
      "(B) 直标题形态:",
      "# <标题>",
      "",
      "【元数据（弱提示, 可据此推断 frontmatter 字段）】",
      JSON.stringify({
        title: input.input.title || "",
        date: input.input.date || "",
        type: input.input.type || "",
        status: input.input.status || "",
        tags: input.input.tags || [],
        related: input.input.related || [],
        folder: input.input.folder || "",
      }),
      "本地 seed 摘要（弱提示）:",
      JSON.stringify(seedSummary),
      "",
      "【原始笔记】",
      input.rawContent,
    ].join("\n");
  }
  return [
    `Workbench mode: knowledge-note-organize; Prompt version: ${KNOWLEDGE_NOTE_GATEWAY_PROMPT_VERSION}; Preferred model config: minimax-m3`,
    `Source hash: ${input.sourceHash}`,
    "你是知识整理助手。把用户粘贴的原始笔记整理为 Obsidian 长期可用的 Markdown 笔记。",
    "",
    "约束（只这 3 条）：",
    "1. 只整理原文，不编造内容。如果原文模糊、缺上下文或与外部知识冲突，照实写「原文未说明」或「待核验」，不要补全。",
    "2. 用 Obsidian 习惯：可加 frontmatter（tags/date/type/status/related），用 # 标题和 ## 小节，section 数量和命名你按内容决定。Markdown 末尾写 `source-hash: <hash>`。",
    "3. 用 JSON 输出，便于程序解析。",
    "",
    "高质量 Add Note 硬要求：",
    "- 不得复用历史会话、固定模板或其他录音的主题；每个结论必须能在本次原文找到证据锚点。",
    "- 不得套用「可靠性会议 / 安委会 / MBA / 系统开发」等模板，除非本次原文明确出现对应会议或主题。",
    "- 如果原文只是碎片对话、低信息密度或主题不清，输出低信息密度判断、可保留事实、待核验和需要补充的上下文；不要强行生成漂亮但无证据的会议纪要。",
    "- Markdown 必须包含：## 高价值摘要、## 关键事实、## 行动项、## 风险与待核验、## 证据锚点、## 原始记录入口。没有行动项时写「未从原文确认」。",
    "- 证据锚点必须是净化后的原文短句或时间线线索，不要直接粘贴大段逐字稿。",
    "",
    "JSON contract:",
    JSON.stringify({
      sourceHash: input.sourceHash,
      draft: {
        title: "string",
        date: "YYYY-MM-DD",
        type: "会议纪要|工作记录|学习笔记|决策记录|项目文档|备忘",
        status: "待跟进|已完成|仅供参考|进行中",
        tags: ["tag"],
        related: ["[[实体]]"],
        folder: "openclaw",
        markdown: "Obsidian 整理后的 markdown 全文（含 frontmatter + # 标题 + ## sections）",
      },
      quality: {
        confidence: 0.8,
        sourceCoverage: "覆盖原文主要事实",
        unresolvedItems: ["待核验项"],
      },
    }, null, 2),
    "",
    "用户元数据（弱提示）:",
    JSON.stringify({
      title: input.input.title || "",
      date: input.input.date || "",
      type: input.input.type || "",
      status: input.input.status || "",
      tags: input.input.tags || [],
      related: input.input.related || [],
      folder: input.input.folder || "",
    }),
    "本地 seed 摘要（弱提示）:",
    JSON.stringify(seedSummary),
    "",
    "原始笔记:",
    input.rawContent,
  ].filter(Boolean).join("\n");
}

// 2026-07-06 (rework3): 一键 direct repair prompt.
//
// 默认 `minimax-direct` 路径下, 第一次 direct 调用可能因为模型对低信息密度/低
// 信噪比 transcript 反复只输出 `<think>…</think>` 而不写真笔记本体, 清理器把
// 整个 think block 砍掉后留下 length=0 的 markdown, 触发
// `minimax_direct_markdown_empty_after_clean`. rework1 + rework2 把这种 fail
// 准确地分类成 `blocked_minimax_direct_quality`, 但没有尝试自救.
//
// 这条 repair prompt 用于第二次也是唯一一次的直接重试:
//   * 不再用 `direct` 第一次的 prompt, 因为它对 MiniMax-M3 在 transcript 极
//     短/低信噪比场景下的 "先想再说" 倾向不够强.
//   * 直接告诉模型: 上一版因 `<think>` / preamble / JSON envelope / 缺标题
//     / 缺 source-hash 被拒, 必须这一版只输出最终可保存的 Markdown.
//   * 仍然禁止 `<think>`, 仍然禁止 JSON, 仍然禁止 preamble / postface / `Note:`
//     / `Output:` / `整理结果:` 等引导行.
//   * 给了"低信息密度 transcript" 的处理规则:
//       - 标题可以是 `午间咖啡杂谈` 或根据 rawContent 推断;
//       - 没有的决策 / 行动项就照实写 "原文未说明" / "未从原文确认";
//       - 保留原文里能识别的事实 / 主题 / 时间线线索;
//       - 末尾必须带 `source-hash: <hash>` 锚点.
//
// 这条 prompt 只给 minimax-direct repair 用; Gateway / m3-html 仍然走 legacy
// `gateway` JSON contract prompt, 不会受影响.
function buildKnowledgeNoteM3RepairPrompt(input: {
  input: KnowledgeNoteDraftInput;
  seed: ReturnType<typeof organizeKnowledgeNoteDraft>;
  agentDecision: { chosenAgent: AgentId; reason: string; escalationNeeded: boolean };
  sourceHash: string;
  rawContent: string;
  previousIssues: string[];
  previousWarnings: string[];
  previousCleanedLength: number;
  emptyAfterClean: boolean;
}) {
  const rawContent = String(input.rawContent || "").slice(0, 70_000);
  const previousIssues = Array.isArray(input.previousIssues) ? input.previousIssues.filter(Boolean) : [];
  const previousWarnings = Array.isArray(input.previousWarnings) ? input.previousWarnings.filter(Boolean) : [];
  const meta = {
    title: String(input.input.title || "").trim(),
    date: String(input.input.date || "").trim(),
    type: String(input.input.type || "").trim(),
    status: String(input.input.status || "").trim(),
    tags: Array.isArray(input.input.tags) ? input.input.tags.map((t) => String(t)) : [],
    related: Array.isArray(input.input.related) ? input.input.related.map((t) => String(t)) : [],
    folder: String(input.input.folder || "").trim(),
  };
  const seedSummary = {
    title: input.seed.title,
    date: input.seed.date,
    type: input.seed.type,
    status: input.seed.status,
    tags: input.seed.tags,
    related: input.seed.related,
    folder: input.seed.folder,
  };
  const rejectionSummary = input.emptyAfterClean
    ? "上一版只输出了 chain-of-thought (`<think>…</think>`) 或被清理后为空, 因此被质量门禁拒绝。"
    : "上一版 Markdown 未通过质量门禁。";
  const issueList = previousIssues.length ? previousIssues.join(", ") : "无";
  const warnList = previousWarnings.length ? previousWarnings.join(", ") : "无";
  return [
    `Workbench mode: knowledge-note-organize-direct-repair; Prompt version: ${KNOWLEDGE_NOTE_GATEWAY_PROMPT_VERSION}; Preferred model config: minimax-m3`,
    `Source hash: ${input.sourceHash}`,
    `上一轮整理结果已被服务器质量门禁拒绝（${rejectionSummary}）`,
    `上一轮 cleanIssues=${issueList}; cleanWarnings=${warnList}; cleanedLength=${input.previousCleanedLength}`,
    "",
    "你是知识整理助手, 正在做 minimax-direct 直连模式下的 **一次性 repair**。",
    "这一次你必须把同一份原始笔记整理成 Obsidian Markdown 笔记本体, 直接可保存。",
    "",
    "【硬约束 — 任何违反都会被拒】",
    "1. **只输出最终可保存的 Obsidian Markdown 笔记本体**。不要输出 JSON, 不要输出任何包装层, 不要任何解释 / 前言 / 后记 / 收尾寒暄。",
    "2. **绝对不要**输出 `<think>…</think>` 或任何形式的 chain-of-thought / 内部推理。不要写 `Let me analyze`、`The user is asking`、`The raw notes are`、`I need to`、`First, let me`、`Below is my analysis`、`I'll start by`、中文「下面我」「让我先」「我来分析一下」之类的分析 preamble。",
    "3. **直接以笔记本体开始**: 如果用 frontmatter, 先输出 `---` 起头的 YAML; 否则以 `# <标题>` 起头。不要在笔记前写 `Note:`、`Output:`、`整理结果:`、`Here's the structured note:` 之类的引导行。",
    "4. **末尾必须**写一行 `source-hash: <hash>` 标记本次来源（hash 值见本提示顶端）。如果省略, 仍会被拒。",
    "5. 只整理原文, 不编造内容。如果原文模糊 / 缺上下文 / 是低信息密度闲聊, 照实写「原文未说明」或「未从原文确认」, 不要补全。",
    "6. Obsidian 习惯: frontmatter（tags/date/type/status/related）+ `# 标题` + `## 小节`。Markdown 必须包含以下小节（按需命名, 顺序可调）: ## 高价值摘要、## 关键事实、## 行动项、## 风险与待核验、## 证据锚点、## 原始记录入口。没有行动项时写「未从原文确认」。",
    "7. **不得复用历史会话、固定模板**（可靠性会议 / 安委会 / MBA / 系统开发 等）。每个结论必须能在本次原文找到证据锚点。证据锚点必须是净化后的原文短句或时间线线索, 不要直接粘贴大段逐字稿。",
    "",
    "【低信息密度 transcript 的处理】",
    "- 如果原文只是碎片对话 / 闲聊 / 主题不清, 不要为了「漂亮」硬塞结论; 走「仅供参考」 / 低信息密度判断。",
    "- 标题可以是用户给定的标题（例如 `午间咖啡杂谈`）或根据 rawContent 第一句/最显眼主题推断; 不要写 `Note:` / `Output:` 之类引导。",
    "- 行动项 / 决策类小节如果没有就明确写「未从原文确认」, 不要凭空加待办。",
    "- 保留原文里能识别的事实（人名、地名、年份、时间线、数字、关键判断）。",
    "- 风险与待核验可以照实写「原始信息密度低, 关键判断待用户补充」。",
    "",
    "【输出形态 — 仅以下面之一开始, 后面立即是 Markdown 本体】",
    "(A) frontmatter 形态:",
    "---",
    "title: <标题>",
    "date: YYYY-MM-DD",
    "type: <类型>",
    "status: <状态>",
    "tags: [<tag>...]",
    "related: [<[[实体]]>...]",
    "folder: openclaw",
    "---",
    "",
    "(B) 直标题形态:",
    "# <标题>",
    "",
    "【元数据（弱提示, 可据此推断 frontmatter 字段）】",
    JSON.stringify(meta),
    "本地 seed 摘要（弱提示）:",
    JSON.stringify(seedSummary),
    "",
    "【原始笔记】",
    rawContent,
  ].join("\n");
}

function buildKnowledgeNoteM3CompactPrompt(input: {
  input: KnowledgeNoteDraftInput;
  seed: ReturnType<typeof organizeKnowledgeNoteDraft>;
  agentDecision: { chosenAgent: AgentId; reason: string; escalationNeeded: boolean };
  sourceHash: string;
  sourceProfile: ReturnType<typeof knowledgeNoteSourceProfile>;
  promptMode?: "direct" | "gateway";
}) {
  const rawContent = String(input.input.rawContent || "").slice(0, 12_000);
  return buildKnowledgeNoteM3SimplePrompt({
    input: input.input,
    seed: input.seed,
    agentDecision: input.agentDecision,
    sourceHash: input.sourceHash,
    rawContent,
    promptMode: input.promptMode,
  });
}

function buildKnowledgeNoteM3CalendarPrompt(input: {
  input: KnowledgeNoteDraftInput;
  seed: ReturnType<typeof organizeKnowledgeNoteDraft>;
  agentDecision: { chosenAgent: AgentId; reason: string; escalationNeeded: boolean };
  sourceHash: string;
  sourceProfile: ReturnType<typeof knowledgeNoteSourceProfile>;
  promptMode?: "direct" | "gateway";
}) {
  const rawContent = String(input.input.rawContent || "").slice(0, 18_000);
  return buildKnowledgeNoteM3SimplePrompt({
    input: input.input,
    seed: input.seed,
    agentDecision: input.agentDecision,
    sourceHash: input.sourceHash,
    rawContent,
    calendarHint: true,
    promptMode: input.promptMode,
  });
}

function buildKnowledgeNoteM3Prompt(input: {
  input: KnowledgeNoteDraftInput;
  seed: ReturnType<typeof organizeKnowledgeNoteDraft>;
  agentDecision: { chosenAgent: AgentId; reason: string; escalationNeeded: boolean };
  sourceHash: string;
  sourceProfile: ReturnType<typeof knowledgeNoteSourceProfile>;
  promptMode?: "direct" | "gateway";
}) {
  const rawContent = String(input.input.rawContent || "").slice(0, 70_000);
  return buildKnowledgeNoteM3SimplePrompt({
    input: input.input,
    seed: input.seed,
    agentDecision: input.agentDecision,
    sourceHash: input.sourceHash,
    rawContent,
    promptMode: input.promptMode,
  });
}

async function generateKnowledgeNoteM3Html(input: {
  input: KnowledgeNoteOrganizeBody;
  sourceHash: string;
  gatewayRunId: string;
  agentDecision: { chosenAgent: AgentId; reason: string; escalationNeeded: boolean };
  draft: KnowledgeNoteDraftInput;
  layoutStrategy?: KnowledgeNoteLayoutStrategyInput;
  quality: { confidence: number; sourceCoverage: string; unresolvedItems: string[] };
  timeoutMs: number;
  signal?: AbortSignal;
  priorAttempts?: KnowledgeNoteAttempt[];
  retryBudget?: KnowledgeNoteRetryBudget;
  harvestSinceMs?: number;
}) {
  const attempts: KnowledgeNoteAttempt[] = [];
  const allowDeterministicHtmlFallback = (() => {
    const htmlMode = String(input.input.htmlMode || "m3").toLowerCase();
    const qualityMode = String(input.input.qualityMode || "minimax-direct").toLowerCase();
    return ["trusted-markdown", "deterministic", "server-render"].includes(htmlMode) || qualityMode === "trusted-markdown-html";
  })();
  const shouldRenderHtmlFromTrustedMarkdown = (() => {
    if (!allowDeterministicHtmlFallback) return false;
    const rawContent = String(input.input.rawContent || "");
    const title = String(input.draft.title || input.input.title || "");
    const tags = Array.isArray(input.input.tags) ? input.input.tags.map(String).join(" ") : String(input.input.tags || "");
    return isCalendarKnowledgeNoteInput(input.input, rawContent)
      && (rawContent.length > 12_000 || /元宝录音|语音转写|会议纪要|日程笔记/i.test(`${title}\n${tags}\n${rawContent.slice(0, 2000)}`));
  })();
  if (shouldRenderHtmlFromTrustedMarkdown) {
    const deterministic = renderKnowledgeNoteHtmlFromTrustedM3Draft({
      sourceHash: input.sourceHash,
      gatewayRunId: input.gatewayRunId,
      agentDecision: input.agentDecision,
      draft: input.draft,
      layoutStrategy: input.layoutStrategy,
      quality: input.quality,
    });
    attempts.push({
      ...deterministic.attempt,
      attempt: attempts.length,
      strategy: "long_calendar_trusted_markdown_html_render",
    });
    if (deterministic.sanitized.quality.passed) {
      return {
        htmlDraft: { html: deterministic.sanitized.html, title: input.draft.title || "Knowledge Note", sourceHash: input.sourceHash },
        htmlQuality: deterministic.sanitized.quality,
        generationPipeline: ["m3_trusted_markdown", "long_calendar_deterministic_html_render", "server_sanitize"],
        gatewayExecution: undefined,
        attempts,
      };
    }
  }
  // v3：完全交给模型负责。每次必走 LLM 出 HTML，server 只做 XSS 防护 + HTML 完整性。
  //     prompt 已简化（不限制模型），quality gate 已放宽（不阻断 LLM 自由发挥）。
  //     hang 兜底在 connectors/gateway.ts execGatewayCli 修：detached execFile 子进程死掉时强制 resolve 错误。
  const requestHtml = async (critique = "", attemptKey = "") => {
    const startedMs = Date.now();
    const harvestSinceMs = Math.min(startedMs - 5000, input.harvestSinceMs ?? startedMs - 5000);
    const prompt = buildKnowledgeNoteHtmlM3Prompt(input, critique);
    const runId = attemptKey ? `${input.gatewayRunId}-${attemptKey}` : input.gatewayRunId;
    const gatewayAttempt = await callKnowledgeNoteGatewayAgentWithLateHarvest({
      preferredAgent: input.agentDecision.chosenAgent,
      purpose: "html",
      sourceHash: input.sourceHash,
      runId,
      message: prompt,
      idempotencyKey: critique
        ? `knowledge-note-html:${KNOWLEDGE_NOTE_PIPELINE_VERSION}:${KNOWLEDGE_NOTE_GATEWAY_PROMPT_VERSION}:${input.sourceHash}:${runId}:retry`
        : `knowledge-note-html:${KNOWLEDGE_NOTE_PIPELINE_VERSION}:${KNOWLEDGE_NOTE_GATEWAY_PROMPT_VERSION}:${input.sourceHash}:${runId}`,
      timeoutMs: input.timeoutMs,
      signal: input.signal,
      harvestSinceMs,
    });
    const gateway = gatewayAttempt.gateway;
    if (!gateway.ok) return { ok: false as const, reason: `html_gateway_unavailable:${gateway.error || "unknown"}` };
    let execution = gatewayAttempt.execution;
    let text = extractGatewayText(gateway.data);
    let parsed = parseKnowledgeNoteHtmlGatewayResponse(text) || extractHtmlFromKnowledgeNoteGatewayObject(gateway.data);
    if (!parsed?.html) {
      const sessionKey = gatewayAttempt.execution.sessionKey
        || `agent:${gatewayAttempt.execution.executionAgent}:knowledge-note-html:${input.sourceHash.slice(0, 16)}:${safeName(input.gatewayRunId || "").slice(0, 16)}`;
      const recoveredText = (recoverGatewayFinalFromSession(gatewayAttempt.execution.executionAgent, sessionKey, startedMs - 1000)
        || recoverGatewayFinalFromRecentSessionFiles(gatewayAttempt.execution.executionAgent, sessionKey, startedMs - 1000)).trim();
      if (recoveredText && recoveredText !== text.trim()) {
        text = recoveredText;
        parsed = parseKnowledgeNoteHtmlGatewayResponse(recoveredText) || extractHtmlFromKnowledgeNoteGatewayObject({ final: recoveredText });
      }
    }
    if (!parsed?.html) {
      const harvest = recoverKnowledgeNoteGatewayFinalBySourceHash({
        purpose: "html",
        sourceHash: input.sourceHash,
        sinceMs: harvestSinceMs,
        preferredAgent: input.agentDecision.chosenAgent,
        requirePromptMarker: KNOWLEDGE_NOTE_GATEWAY_PROMPT_VERSION,
      });
      if (harvest) {
        text = harvest.text;
        parsed = parseKnowledgeNoteHtmlGatewayResponse(harvest.text) || extractHtmlFromKnowledgeNoteGatewayObject({ final: harvest.text });
        if (parsed?.html) {
          execution = {
            roleAgent: input.agentDecision.chosenAgent,
            executionAgent: harvest.agentId,
            reason: "late_m3_session_source_hash_harvest",
            rerouteReason: gateway.error || "html_final_not_delivered_to_workbench",
            sessionKey: harvest.sessionKey,
          };
        }
      }
    }
    if (!parsed?.html) {
      const wrongStageMarkdown = Boolean(parseKnowledgeNoteGatewayJson(text) || extractKnowledgeNoteGatewayDraftObject({ final: text }));
      const reason = wrongStageMarkdown ? "html_gateway_returned_markdown_stage_output" : "html_gateway_returned_non_html";
      const debugReportPath = writeKnowledgeNoteGatewayDebugReport({
        stage: "m3_html_document",
        reason,
        sourceHash: input.sourceHash,
        runId: input.gatewayRunId,
        promptProfile: "html",
        repairAttempt: critique ? 1 : 0,
        gatewayText: text,
        gatewayData: gateway.data,
      });
      return { ok: false as const, reason, debugReportPath };
    }
    const echoedHash = String(parsed.sourceHash || "").trim();
    if (echoedHash && echoedHash !== input.sourceHash) return { ok: false as const, reason: "html_source_hash_mismatch" };
    const sanitized = sanitizeKnowledgeNoteModelHtml(parsed.html, {
      title: parsed.title || String(input.draft.title || "Knowledge Note"),
      sourceHash: input.sourceHash,
      qualityProfile: isLowInformationKnowledgeNoteDraft(input.draft) ? "low-information" : "standard",
    });
    return { ok: true as const, parsed, sanitized, execution };
  };
  try {
    let result = await requestHtml();
    attempts.push({
      attempt: 0,
      stage: "m3_html_document",
      strategy: "html_document",
      status: result.ok && result.sanitized.quality.passed ? "passed" : "failed",
      reason: result.ok && !result.sanitized.quality.passed ? "html_quality_gate" : result.ok ? undefined : result.reason,
      debugReportPath: result.ok ? undefined : result.debugReportPath,
      htmlScore: result.ok ? result.sanitized.quality.score : undefined,
    });
    if (!result.ok && /html_gateway_returned_non_html|html_gateway_returned_markdown_stage_output/.test(result.reason)) {
      const retry = await requestHtml([
        /html_gateway_returned_markdown_stage_output/.test(result.reason)
          ? "上一版返回了 Markdown 阶段 JSON，而不是 HTML 阶段 JSON。请只重做 HTML 阅读层，不要重复输出 draft/markdown。"
          : "上一版没有按契约返回可解析的 html 字段。请修复输出格式，不要改事实。",
        "只返回一个严格 JSON 对象，字段必须包含 sourceHash、title、html、htmlQuality。",
        "html 字段必须是完整离线 HTML 字符串，以 <!doctype html> 或 <html 开头并以 </html> 结束。",
        "不要返回 Markdown 代码块、说明文字、思考过程或工具调用结果。",
      ].join("\n"));
      attempts.push({
        attempt: 1,
        stage: "m3_html_document",
        strategy: "html_format_repair",
        status: retry.ok ? "passed" : "failed",
        reason: retry.ok ? undefined : retry.reason,
        repairDirectives: diagnoseKnowledgeNoteFailure("m3_html_document", result.reason).repairDirectives,
        debugReportPath: retry.ok ? undefined : retry.debugReportPath,
        htmlScore: retry.ok ? retry.sanitized.quality.score : undefined,
      });
      if (retry.ok || retry.debugReportPath) result = retry;
    }
    if (!result.ok
      && /html_gateway_unavailable|gateway_final_retry_failed|gateway closed|tick timeout|normal closure|no close reason/i.test(result.reason)
      && shouldImmediateKnowledgeNoteGatewayTransportRetry(result.reason)) {
      const retry = await requestHtml([
        "上一轮 HTML 阶段 Gateway 连接提前关闭。不要续用旧会话；请基于可信 Markdown 重新生成一份更短、更稳的离线 HTML。",
        "只返回一个严格 JSON 对象，字段必须包含 sourceHash、title、html、htmlQuality。",
        "html 字段必须完整闭合；不要输出解释、Markdown 代码块、思考过程或工具调用结果。",
        "压缩输出：<style> 不超过 520 字符，HTML 控制在 3200-6200 字符；首屏必须出现核心判断、主题地图、高价值摘要、行动项、证据入口。",
        "不得改变 Markdown 中的事实、标题、行动项和来源依据。",
      ].join("\n"), "transport-retry");
      attempts.push({
        attempt: attempts.length,
        stage: "m3_html_document",
        strategy: "html_transport_recovery",
        status: retry.ok && retry.sanitized.quality.passed ? "passed" : "failed",
        reason: retry.ok && !retry.sanitized.quality.passed ? "html_quality_gate" : retry.ok ? undefined : retry.reason,
        repairDirectives: diagnoseKnowledgeNoteFailure("m3_html_document", result.reason).repairDirectives,
        debugReportPath: retry.ok ? undefined : retry.debugReportPath,
        htmlScore: retry.ok ? retry.sanitized.quality.score : undefined,
      });
      if (retry.ok || retry.debugReportPath) result = retry;
    }
    if (!result.ok) {
      if (allowDeterministicHtmlFallback) {
        const deterministic = renderKnowledgeNoteHtmlFromTrustedM3Draft({
          sourceHash: input.sourceHash,
          gatewayRunId: input.gatewayRunId,
          agentDecision: input.agentDecision,
          draft: input.draft,
          layoutStrategy: input.layoutStrategy,
          quality: input.quality,
        });
        attempts.push({
          ...deterministic.attempt,
          attempt: attempts.length,
          strategy: "html_transport_deterministic_render",
          reason: deterministic.sanitized.quality.passed ? undefined : result.reason,
        });
        if (deterministic.sanitized.quality.passed) {
          return {
            htmlDraft: { html: deterministic.sanitized.html, title: input.draft.title || "Knowledge Note", sourceHash: input.sourceHash },
            htmlQuality: deterministic.sanitized.quality,
            generationPipeline: ["m3_html_document_failed", "m3_html_deterministic_render", "server_sanitize"],
            gatewayExecution: undefined,
            attempts,
          };
        }
      }
      const combinedAttempts = [...(input.priorAttempts || []), ...attempts];
      failKnowledgeNoteGateway(
        "m3_html_document",
        result.reason,
        ["m3_html_document_failed"],
        503,
        result.debugReportPath,
        knowledgeNoteFailureExtras("m3_html_document", result.reason, combinedAttempts, input.retryBudget || knowledgeNoteRetryBudget(0, 0), result.debugReportPath),
      );
    }
    if (!result.sanitized.quality.passed) {
      const qualityDebug = [
        ...(result.sanitized.quality.issues.length ? result.sanitized.quality.issues : ["quality_failed"]),
        `score=${result.sanitized.quality.score}`,
        `semantic=${result.sanitized.quality.dimensions.semanticCoverage}`,
        `visual=${result.sanitized.quality.dimensions.visualHierarchy}`,
        `evidence=${result.sanitized.quality.dimensions.evidenceTrace}`,
        `noise=${result.sanitized.quality.dimensions.noiseControl}`,
      ].join(",");
      const critique = [
        "上一版 HTML 未通过服务端质量门槛，请只重做 HTML，不要改变事实。",
        `失败原因：${qualityDebug}`,
        isLowInformationKnowledgeNoteDraft(input.draft)
          ? "这是低信息密度记录。必须补齐首屏，并在 body 开头 2600 个可见字符内出现这些精确中文标签：核心判断、低信息密度判断、高价值摘要、价值提炼、金句 / 判断句、行动项、证据入口。"
          : "必须补齐首屏，并在 body 开头 2600 个可见字符内出现这些精确中文标签：核心判断、主题地图、高价值摘要、金句 / 判断句、行动项、证据入口。",
        `证据追溯硬约束：证据入口模块必须可见写出这些精确文本：Markdown 可信源、原始记录入口、source-hash，并展示 source-hash: ${input.sourceHash.slice(0, 16)}...；不要只把 hash 放在 meta 标签里。`,
        "结构要求：使用 <main> 包裹正文；首屏每个模块用 <section>；至少包含一个 <h1> 和多个 <h2>；卡片或网格 class 名必须包含 card/grid/summary/panel/hero 中的至少两个词。",
        "完整性硬约束：不要把输出预算耗在长 CSS。<style> 不超过 650 字符；html 字符串前 1600 个字符内必须已经出现 <body><main>，并且必须有完整 </main></body></html>。",
        /first_screen_raw_or_noisy_transcript/.test(qualityDebug)
          ? "首屏噪声专项修复：不要在 body 前 2600 个可见字符内出现任何说话人+时间戳原始转写，例如 `发言人1 00:01`、`技术专家 00:01`、`值班经理 15:22`、`会议主持人 15:28`。如果需要证据，只写净化短句，并放在证据入口模块。"
          : "",
        "禁止使用 input、select、textarea、form、iframe、script、onclick/onload/onmouseover 等任何事件属性；静态视觉按钮请用 span 或无事件 button。",
        "不得使用通用 Knowledge Note 壳，不得让元数据、目录、来源校验抢占首屏。",
      ].join("\n");
      const retry = await requestHtml(critique);
      attempts.push({
        attempt: attempts.length,
        stage: "m3_html_document",
        strategy: "html_quality_repair",
        status: retry.ok && retry.sanitized.quality.passed ? "passed" : "failed",
        reason: retry.ok && !retry.sanitized.quality.passed ? "html_quality_gate" : retry.ok ? undefined : retry.reason,
        repairDirectives: diagnoseKnowledgeNoteFailure("m3_html_document", `html_quality_gate:${qualityDebug}`).repairDirectives,
        debugReportPath: retry.ok ? undefined : retry.debugReportPath,
        htmlScore: retry.ok ? retry.sanitized.quality.score : undefined,
      });
      if (retry.ok && retry.sanitized.quality.passed) {
        result = retry;
      } else {
        if (allowDeterministicHtmlFallback) {
          const deterministic = renderKnowledgeNoteHtmlFromTrustedM3Draft({
            sourceHash: input.sourceHash,
            gatewayRunId: input.gatewayRunId,
            agentDecision: input.agentDecision,
            draft: input.draft,
            layoutStrategy: input.layoutStrategy,
            quality: input.quality,
          });
          attempts.push({
            ...deterministic.attempt,
            attempt: attempts.length,
          });
          if (deterministic.sanitized.quality.passed) {
            return {
              htmlDraft: { html: deterministic.sanitized.html, title: input.draft.title || "Knowledge Note", sourceHash: input.sourceHash },
              htmlQuality: deterministic.sanitized.quality,
              generationPipeline: ["m3_html_document", "m3_html_deterministic_render", "server_sanitize"],
              gatewayExecution: result.execution,
              attempts,
            };
          }
        }
        const reason = retry.ok
          ? `html_quality_gate:${[
              ...(retry.sanitized.quality.issues.length ? retry.sanitized.quality.issues : ["failed"]),
              `score=${retry.sanitized.quality.score}`,
              `semantic=${retry.sanitized.quality.dimensions.semanticCoverage}`,
              `visual=${retry.sanitized.quality.dimensions.visualHierarchy}`,
              `evidence=${retry.sanitized.quality.dimensions.evidenceTrace}`,
              `noise=${retry.sanitized.quality.dimensions.noiseControl}`,
            ].join(",")}`
          : retry.reason;
        const combinedAttempts = [...(input.priorAttempts || []), ...attempts];
        failKnowledgeNoteGateway(
          "m3_html_document",
          reason,
          ["m3_html_document_failed"],
          503,
          retry.ok ? undefined : retry.debugReportPath,
          knowledgeNoteFailureExtras("m3_html_document", reason, combinedAttempts, input.retryBudget || knowledgeNoteRetryBudget(0, 0), retry.ok ? "" : retry.debugReportPath),
        );
      }
    }
    const lastAttempt = attempts[attempts.length - 1];
    if (lastAttempt) {
      lastAttempt.status = "passed";
      lastAttempt.reason = undefined;
      lastAttempt.htmlScore = result.sanitized.quality.score;
    }
    return {
      htmlDraft: { html: result.sanitized.html, title: result.parsed.title || input.draft.title || "Knowledge Note", sourceHash: input.sourceHash },
      htmlQuality: result.sanitized.quality,
      generationPipeline: ["m3_html_document", "server_sanitize"],
      gatewayExecution: result.execution,
      attempts,
    };
  } catch (err) {
    if (isKnowledgeNoteGatewayRequiredError(err)) throw err;
    const reason = err instanceof Error ? `html_generation_failed:${err.message}` : "html_generation_failed";
    const combinedAttempts = [...(input.priorAttempts || []), ...attempts];
    failKnowledgeNoteGateway(
      "m3_html_document",
      reason,
      ["m3_html_document_failed"],
      503,
      undefined,
      knowledgeNoteFailureExtras("m3_html_document", reason, combinedAttempts, input.retryBudget || knowledgeNoteRetryBudget(0, 0)),
    );
  }
}

function buildKnowledgeNoteHtmlM3Prompt(input: {
  input: KnowledgeNoteOrganizeBody;
  sourceHash: string;
  agentDecision: { chosenAgent: AgentId; reason: string; escalationNeeded: boolean };
  draft: KnowledgeNoteDraftInput;
  quality: { confidence: number; sourceCoverage: string; unresolvedItems: string[] };
}, retryCritique = "") {
  const calendarNote = isCalendarKnowledgeNoteInput(input.input, String(input.input.rawContent || ""));
  const rawContent = String(input.input.rawContent || "").slice(0, calendarNote ? 2_000 : 5_000);
  const markdown = String(input.draft.markdown || "").slice(0, calendarNote ? 7_000 : 12_000);
  return [
    `Workbench mode: ${calendarNote ? "assistant-calendar-html" : "knowledge-note-html"}; Preferred model config: minimax-m3`,
    `Source hash: ${input.sourceHash}`,
    "你是 AI 文档设计师。任务：基于可信 Markdown 生成完整离线 HTML 阅读文件。",
    "",
    "自由发挥（你决定一切视觉）：",
    "- 章节、卡片、配色、字体、间距、图标、表格、时间线、callout、tag pill 等都由你设计。",
    "- 适合信息密度的视觉层次，让用户一眼能找到关键信息。",
    "",
    "唯一非协商要求：",
    "1. 离线 HTML + inline CSS：禁止 script / iframe / form / input / textarea / select / 外链 / CDN / 远程图片 / 事件属性 / @import / 未知协议 / 凭据（XSS 防护）。",
    "2. HTML 必须含 <meta name=\"source-hash\" content=\"上方 hash\">（server 也会自动注入）。",
    "3. 严格基于 Markdown 提供的事实，不编造；没有的字段就省略或标注「待核验」。",
    "4. 输出完整闭合的 <!doctype html>...</html>。",
    "5. JSON contract：返回 { sourceHash, title, html, htmlQuality }。",
    "6. 渲染正文必须从 <h1> 主题 / 摘要类标题直接开始，禁止在 <body> 文本节点出现「让我分析」「让我先」「我来整理」「下面我」「以下是整理后的笔记」「整理结果」「Let me analyze」「The user is asking」「Below is my analysis」等 chain-of-thought 前言；任何此类前言必须从 HTML body 中移除后再输出。",
    retryCritique ? `\n=== 上一轮整改要求 ===\n${retryCritique}` : "",
    "",
    "JSON contract:",
    JSON.stringify({
      sourceHash: input.sourceHash,
      title: "string",
      html: "<!doctype html><html lang=\"zh-CN\"><head><meta name=\"source-hash\" content=\"" + input.sourceHash + "\">...</head><body><main>...</main></body></html>",
      htmlQuality: { score: 90, dimensions: { semanticCoverage: 90, visualHierarchy: 90, evidenceTrace: 90, noiseControl: 90, safety: 100 }, issues: [] },
    }, null, 2),
    "",
    "可信 Markdown:",
    markdown,
    "原始笔记（仅供核验事实用，不要逐行复读）:",
    rawContent,
  ].filter(Boolean).join("\n");
}

function isLowInformationKnowledgeNoteDraft(draft: KnowledgeNoteDraftInput) {
  const metadata = [
    draft.title || "",
    draft.type || "",
    ...(draft.tags || []),
    ...(draft.related || []),
    JSON.stringify(draft.layoutStrategy || {}),
  ].join("\n");
  if (/低信息密度|低信号|闲聊记录|碎片记录|low-information-note/.test(metadata)) return true;
  const text = [
    draft.title || "",
    draft.type || "",
    ...(draft.tags || []),
    ...(draft.related || []),
    draft.markdown || "",
  ].join("\n");
  const signals = [
    /低信息密度/,
    /信息密度判断|信息不足判断/,
    /闲聊记录|碎片记录/,
    /暂无可执行行动项/,
    /不宜推断|不建议.*长期/,
    /有限价值|可保留事实/,
    /缺少上下文|需要补充上下文/,
  ].filter((pattern) => pattern.test(text)).length;
  return signals >= 2;
}

function renderKnowledgeNoteHtmlFromTrustedM3Draft(input: {
  sourceHash: string;
  gatewayRunId: string;
  agentDecision: { chosenAgent: AgentId; reason: string; escalationNeeded: boolean };
  draft: KnowledgeNoteDraftInput;
  layoutStrategy?: KnowledgeNoteLayoutStrategyInput;
  quality: { confidence: number; sourceCoverage: string; unresolvedItems: string[] };
}) {
  const title = compactKnowledgeNoteHtmlText(input.draft.title || "Knowledge Note", 90);
  const markdown = String(input.draft.markdown || "");
  const layout = normalizeKnowledgeNoteLayoutStrategy(input.layoutStrategy) || {
    template: "calendar-work-note",
    hero: "",
    summaryCards: [],
    sidebarBlocks: [],
    primarySections: [],
    visualEmphasis: "",
  };
  const lowInformation = isLowInformationKnowledgeNoteDraft(input.draft);
  const summary = firstKnowledgeNoteHtmlText([
    markdownSectionText(markdown, ["会议摘要", "高价值摘要", "价值摘要", "摘要"]),
    layout.hero,
  ], 360);
  const judgment = firstKnowledgeNoteHtmlText([
    markdownSectionText(markdown, ["核心判断", "关键结论", "判断", "结论"]),
    layout.hero,
  ], 300);
  const topicMap = firstKnowledgeNoteHtmlText([
    markdownSectionText(markdown, ["主题地图", "主题脉络", "主题结构"]),
    layout.primarySections.join(" / "),
    [input.draft.type || "工作记录", ...(input.draft.tags || [])].join(" / "),
  ], 220);
  const quote = firstKnowledgeNoteHtmlText([
    markdownSectionText(markdown, ["金句 / 判断句", "金句", "判断句", "关键判断"]),
  ], 180);
  const actions = markdownSectionList(markdown, ["行动项", "后续行动", "下一步"], ["暂无可执行行动项；当前记录以验证与待核验为主。"], 5);
  const risks = markdownSectionList(markdown, ["风险与待核验", "待核验", "风险"], input.quality.unresolvedItems || [], 6);
  const evidence = markdownSectionList(markdown, ["来源依据", "证据入口", "关键依据"], [
    `Markdown 可信源：MiniMax M3 已返回结构化 Markdown 与 layoutStrategy。`,
    `原始记录入口：source-hash: ${input.sourceHash.slice(0, 16)}...`,
    input.quality.sourceCoverage || "来源覆盖说明未返回，按 source-hash 与 Markdown 结构进行校验。",
  ], 5);
  const cards = layout.summaryCards.length ? layout.summaryCards.slice(0, 4) : [
    { label: "结论", value: lowInformation ? "有限价值" : "可信整理", note: "由 M3 Markdown 生成" },
    { label: "行动项", value: String(actions.length), note: "保留待核验状态" },
    { label: "待核验", value: String(risks.length), note: "不伪造缺失信息" },
  ];
  const sidebarItems = layout.sidebarBlocks.flatMap((block) => block.items.slice(0, 4)).slice(0, 8);
  const html = `<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="source-hash" content="${escapeInlineHtml(input.sourceHash)}">
  <title>${escapeInlineHtml(title)}</title>
  <style>
  :root{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#18202f;background:#f6f8fb}
  *{box-sizing:border-box}body{margin:0;background:#f6f8fb;color:#18202f;line-height:1.65}
  main{max-width:1120px;margin:0 auto;padding:32px 20px 48px}
  h1{margin:0 0 12px;font-size:30px;line-height:1.2;letter-spacing:0}h2{margin:0 0 12px;font-size:18px;letter-spacing:0}
  .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px;margin:18px 0}.card,.panel{background:white;border:1px solid #d9e2ef;border-radius:8px;padding:18px;box-shadow:0 8px 22px rgba(27,39,61,.06)}
  .summary .value{font-size:22px;font-weight:800;color:#0f766e}.summary .label{font-size:12px;text-transform:uppercase;color:#5b677a}.map{border-left:5px solid #0f766e}
  .judgment{border-left:5px solid #2563eb}.golden{background:#fff7ed;border-color:#fed7aa}.action{background:#f0fdf4;border-color:#bbf7d0}.evidence{background:#f8fafc;border-style:dashed}
  .hero{background:#0f766e;color:white;border-radius:8px;padding:28px;box-shadow:0 18px 45px rgba(15,118,110,.18)}.hero p{margin:0;max-width:860px}
  ul{padding-left:20px;margin:8px 0 0}li{margin:6px 0}.meta{font-size:13px;color:#536173;word-break:break-word}.badge{display:inline-block;margin:4px 6px 0 0;padding:3px 8px;border-radius:999px;background:#e0f2fe;color:#075985;font-size:12px}
  .content{display:grid;grid-template-columns:minmax(0,2fr) minmax(240px,.8fr);gap:16px}.markdown-source{white-space:pre-wrap;overflow-wrap:anywhere;max-height:520px;overflow:auto}
  @media(max-width:760px){main{padding:18px 12px}.content{grid-template-columns:1fr}h1{font-size:24px}.hero{padding:20px}.card,.panel{padding:14px}}
  @media print{body{background:white}.card,.panel,.hero{box-shadow:none}.hero{color:#18202f;background:white;border:1px solid #d9e2ef}}
  </style>
</head>
<body>
<main>
  <section class="hero panel judgment">
    <h1>${escapeInlineHtml(title)}</h1>
    <h2>核心判断</h2>
    <p>${escapeInlineHtml(judgment)}</p>
  </section>
  <section class="summary grid">
    ${cards.map((card) => `<article class="card summary-card"><div class="label">${escapeInlineHtml(card.label)}</div><div class="value">${escapeInlineHtml(card.value)}</div><p>${escapeInlineHtml(card.note)}</p></article>`).join("\n    ")}
  </section>
  <section class="panel map topic-map">
    <h2>${lowInformation ? "低信息密度判断" : "主题地图"}</h2>
    <p>${escapeInlineHtml(topicMap)}</p>
  </section>
  <section class="panel summary-block">
    <h2>高价值摘要</h2>
    <p>${escapeInlineHtml(summary)}</p>
  </section>
  <section class="panel golden golden-quote-block">
    <h2>金句 / 判断句</h2>
    <p>${escapeInlineHtml(quote)}</p>
  </section>
  <section class="panel action action-block">
    <h2>行动项</h2>
    ${htmlList(actions)}
  </section>
  <section class="panel evidence evidence-block">
    <h2>证据入口</h2>
    <p class="meta">Markdown 可信源 · 原始记录入口 · source-hash: ${escapeInlineHtml(input.sourceHash.slice(0, 16))}...</p>
    ${htmlList(evidence)}
  </section>
  <section class="content">
    <article class="panel">
      <h2>Markdown 可信源</h2>
      <div class="markdown-source">${escapeInlineHtml(stripKnowledgeRawArchive(markdown).slice(0, 6000))}</div>
    </article>
    <aside class="panel">
      <h2>待核验</h2>
      ${htmlList(risks)}
      <p class="meta">rendered-at: ${escapeInlineHtml(nowIso())}</p>
      <p class="meta">agent: ${escapeInlineHtml(input.agentDecision.chosenAgent)}</p>
      ${(input.draft.tags || []).slice(0, 10).map((tag) => `<span class="badge">${escapeInlineHtml(tag)}</span>`).join("")}
      ${sidebarItems.length ? `<h2>侧栏要点</h2>${htmlList(sidebarItems)}` : ""}
    </aside>
  </section>
</main>
</body>
</html>`;
  const sanitized = sanitizeKnowledgeNoteModelHtml(html, {
    title,
    sourceHash: input.sourceHash,
    qualityProfile: lowInformation ? "low-information" : "standard",
  });
  return {
    sanitized,
    attempt: {
      attempt: 0,
      stage: "m3_html_document",
      strategy: "trusted_m3_draft_deterministic_render",
      status: sanitized.quality.passed ? "passed" : "failed",
      reason: sanitized.quality.passed ? undefined : `deterministic_html_quality_gate:${sanitized.quality.issues.join(",")}`,
      repairDirectives: [
        "使用 MiniMax-M3 已返回的可信 Markdown 与 layoutStrategy 确定性渲染 HTML。",
        "不启用本地内容 fallback；sourceHash、Markdown 和证据入口必须保留。",
        "若确定性 HTML 未过质量门槛，再进入 Gateway/MiniMax HTML 修复。",
      ],
      htmlScore: sanitized.quality.score,
    } satisfies KnowledgeNoteAttempt,
  };
}

function firstKnowledgeNoteHtmlText(values: unknown[], maxLength: number) {
  for (const value of values) {
    const compacted = compactKnowledgeNoteHtmlText(String(value || ""), maxLength);
    if (compacted) return compacted;
  }
  return "信息不足，保留为仅供参考记录；后续需补充背景、目标、责任人和验收标准。";
}

function compactKnowledgeNoteHtmlText(value: string, maxLength: number) {
  const text = stripMarkdownSyntax(String(value || ""))
    .replace(/\s+/g, " ")
    .trim();
  if (!text) return "";
  return text.length > maxLength ? `${text.slice(0, Math.max(0, maxLength - 1)).trim()}…` : text;
}

function markdownSectionText(markdown: string, headings: string[]) {
  return markdownSectionList(markdown, headings, [], 8).join(" ");
}

function markdownSectionList(markdown: string, headings: string[], fallback: unknown[] | string[], maxItems: number) {
  const text = String(markdown || "");
  const wanted = new Set(headings.map((heading) => heading.toLowerCase()));
  const lines = text.split(/\r?\n/);
  const collected: string[] = [];
  let active = false;
  for (const line of lines) {
    const heading = line.match(/^#{2,4}\s+(.+?)\s*$/)?.[1]?.trim();
    if (heading) {
      active = [...wanted].some((wantedHeading) => heading.toLowerCase().includes(wantedHeading));
      continue;
    }
    if (!active) continue;
    const cleaned = stripMarkdownSyntax(line).replace(/^\s*[-*•]\s*/, "").replace(/^\s*\d+[.)]\s*/, "").trim();
    if (cleaned) collected.push(cleaned);
    if (collected.length >= maxItems) break;
  }
  const source = collected.length ? collected : (fallback || []).map(String);
  return source
    .map((item) => compactKnowledgeNoteHtmlText(item, 180))
    .filter(Boolean)
    .slice(0, maxItems);
}

function stripMarkdownSyntax(value: string) {
  return String(value || "")
    .replace(/^---[\s\S]*?---\s*/, "")
    .replace(/```[\s\S]*?```/g, " ")
    .replace(/!\[[^\]]*]\([^)]+\)/g, " ")
    .replace(/\[([^\]]+)]\([^)]+\)/g, "$1")
    .replace(/\[\[([^\]]+)]]/g, "$1")
    .replace(/^[#>\s-]+/gm, "")
    .replace(/[*_`~]/g, "");
}

function htmlList(items: string[]) {
  const safeItems = items.map((item) => compactKnowledgeNoteHtmlText(item, 220)).filter(Boolean).slice(0, 10);
  if (!safeItems.length) return "<ul><li>暂无明确条目；需补充上下文后再判断。</li></ul>";
  return `<ul>${safeItems.map((item) => `<li>${escapeInlineHtml(item)}</li>`).join("")}</ul>`;
}

function parseKnowledgeNoteHtmlGatewayResponse(text: string): KnowledgeNoteGatewayHtmlDraft | null {
  const raw = String(text || "").trim();
  if (!raw) return null;
  const htmlFromJson = parseKnowledgeNoteHtmlGatewayJson(raw);
  if (htmlFromJson) return htmlFromJson;
  const html = extractDirectKnowledgeNoteHtml(raw);
  if (!html) return null;
  return { html };
}

function parseKnowledgeNoteHtmlGatewayJson(text: string): KnowledgeNoteGatewayHtmlDraft | null {
  const raw = String(text || "").trim();
  if (!raw) return null;
  const fencedBlocks = [...raw.matchAll(/```(?:json|JSON)?\s*([\s\S]*?)```/g)].map((match) => match[1]?.trim()).filter(Boolean);
  const firstBrace = raw.indexOf("{");
  const lastBrace = raw.lastIndexOf("}");
  const sliced = firstBrace >= 0 && lastBrace > firstBrace ? raw.slice(firstBrace, lastBrace + 1) : "";
  const jsonAssignmentBlocks = [...raw.matchAll(/(?:final|output|response|content|json)\s*[:=]\s*(```json)?\s*(\{[\s\S]*?\})\s*(```)?/gi)].map((match) => match[2]?.trim()).filter(Boolean);
  const payloadCandidates = raw
    .split(/\n{2,}/)
    .map((part) => part.trim())
    .filter((part) => part.startsWith("{") || part.startsWith("[") || part.includes("\"html\"") || part.includes("htmlQuality") || part.includes("<!doctype") || part.includes("<html"));
  const baseCandidates = [...fencedBlocks, ...jsonAssignmentBlocks, ...payloadCandidates, raw, sliced].filter(Boolean) as string[];
  const candidates = uniqueStrings(baseCandidates.flatMap((candidate) => [
    candidate,
    repairJsonControlCharactersInsideStrings(candidate),
  ]));
  for (const candidate of candidates) {
    try {
      const parsed = JSON.parse(candidate);
      const html = extractHtmlFromKnowledgeNoteGatewayObject(parsed);
      if (html?.html) return html;
    } catch {
      // Try the next candidate.
    }
  }
  return null;
}

function extractDirectKnowledgeNoteHtml(text: string) {
  const raw = String(text || "").trim();
  const fencedHtml = raw.match(/```html\s*([\s\S]*?)```/i)?.[1]?.trim();
  const directHtml = new RegExp('<!doctype\\\\s+html[\\\\s\\\\S]*<\\\\/html>', 'i').exec(raw)?.[0]?.trim() || new RegExp('<html\\\\b[\\\\s\\\\S]*<\\\\/html>', 'i').exec(raw)?.[0]?.trim();
  const html = fencedHtml || directHtml || "";
  return isKnowledgeNoteHtmlString(html) ? html : "";
}

function isKnowledgeNoteHtmlString(value: string) {
  const text = String(value || "").trim();
  return new RegExp('(?:<!doctype\\\\s+html|<html\\\\b)', 'i').test(text) && new RegExp('<\\\\/html>\\\\s*$', 'i').test(text);
}

function parseKnowledgeNoteGatewayJson(text: string): KnowledgeNoteGatewayDraft | null {
  const raw = String(text || "").trim();
  if (!raw) return null;
  const fencedBlocks = [...raw.matchAll(/```(?:json|JSON)?\s*([\s\S]*?)```/g)].map((match) => match[1]?.trim()).filter(Boolean);
  const firstBrace = raw.indexOf("{");
  const lastBrace = raw.lastIndexOf("}");
  const sliced = firstBrace >= 0 && lastBrace > firstBrace ? raw.slice(firstBrace, lastBrace + 1) : "";
  const jsonAssignmentBlocks = [...raw.matchAll(/(?:final|output|response|content|json)\s*[:=]\s*(```json)?\s*(\{[\s\S]*?\})\s*(```)?/gi)].map((match) => match[2]?.trim()).filter(Boolean);
  const payloadCandidates = raw
    .split(/\n{2,}/)
    .map((part) => part.trim())
    .filter((part) => part.startsWith("{") || part.startsWith("[") || part.includes("\"draft\""));
  const baseCandidates = [...fencedBlocks, ...jsonAssignmentBlocks, ...payloadCandidates, raw, sliced].filter(Boolean) as string[];
  const candidates = uniqueStrings(baseCandidates.flatMap((candidate) => [
    candidate,
    repairJsonControlCharactersInsideStrings(candidate),
  ]));
  for (const candidate of candidates) {
    try {
      const parsed = JSON.parse(candidate);
      const draft = extractKnowledgeNoteGatewayDraftObject(parsed);
      if (draft) return draft;
    } catch {
      // Try the next candidate.
    }
  }
  return extractPartialKnowledgeNoteGatewayDraft(raw);
}

function extractKnowledgeNoteGatewayDraftObject(value: unknown, depth = 0): KnowledgeNoteGatewayDraft | null {
  if (depth > 6 || value == null) return null;
  if (typeof value === "string") return parseKnowledgeNoteGatewayJson(value);
  if (Array.isArray(value)) {
    for (const item of value) {
      const nested = extractKnowledgeNoteGatewayDraftObject(item, depth + 1);
      if (nested) return nested;
    }
    return null;
  }
  if (typeof value !== "object") return null;
  const record = value as Record<string, unknown>;
  const draft = record.draft && typeof record.draft === "object" ? record.draft as Record<string, unknown> : null;
  if (draft && (typeof draft.markdown === "string" || typeof draft.title === "string")) return record as KnowledgeNoteGatewayDraft;
  if (typeof record.markdown === "string" || typeof record.title === "string") {
    return {
      sourceHash: firstString(record.sourceHash),
      draft: record as Partial<KnowledgeNoteDraftInput>,
      layoutStrategy: record.layoutStrategy as KnowledgeNoteLayoutStrategyInput,
      agentDecision: record.agentDecision as KnowledgeNoteGatewayDraft["agentDecision"],
      quality: record.quality as KnowledgeNoteGatewayDraft["quality"],
      coverageMap: record.coverageMap,
      missingRisk: record.missingRisk,
      sourceAnchors: record.sourceAnchors,
    };
  }
  for (const key of ["final", "data", "result", "payload", "response", "output", "assistant", "completion", "lastMessage", "message", "content", "text", "value"]) {
    const nested = extractKnowledgeNoteGatewayDraftObject(record[key], depth + 1);
    if (nested) return nested;
  }
  return null;
}

function extractPartialKnowledgeNoteGatewayDraft(raw: string): KnowledgeNoteGatewayDraft | null {
  const draft = parseBalancedJsonPropertyObject(raw, "draft") as Partial<KnowledgeNoteDraftInput> | null;
  if (!draft || (typeof draft.markdown !== "string" && typeof draft.title !== "string")) return null;
  const sourceHash = firstRegexGroup(raw, /"sourceHash"\s*:\s*"([^"]+)"/);
  return {
    sourceHash,
    draft,
    layoutStrategy: parseBalancedJsonPropertyObject(raw, "layoutStrategy") as KnowledgeNoteLayoutStrategyInput | undefined,
    agentDecision: parseBalancedJsonPropertyObject(raw, "agentDecision") as KnowledgeNoteGatewayDraft["agentDecision"] | undefined,
    quality: parseBalancedJsonPropertyObject(raw, "quality") as KnowledgeNoteGatewayDraft["quality"] | undefined,
    missingRisk: parseBalancedJsonPropertyArray(raw, "missingRisk"),
    coverageMap: parseBalancedJsonPropertyArray(raw, "coverageMap"),
    sourceAnchors: parseBalancedJsonPropertyArray(raw, "sourceAnchors"),
  };
}

function parseBalancedJsonPropertyObject(raw: string, key: string): Record<string, unknown> | null {
  const fragment = balancedJsonPropertyFragment(raw, key, "{", "}");
  if (!fragment) return null;
  return parseJsonFragmentObject(fragment);
}

function parseBalancedJsonPropertyArray(raw: string, key: string): unknown[] | undefined {
  const fragment = balancedJsonPropertyFragment(raw, key, "[", "]");
  if (!fragment) return undefined;
  try {
    const parsed = JSON.parse(repairJsonControlCharactersInsideStrings(fragment));
    return Array.isArray(parsed) ? parsed : undefined;
  } catch {
    return undefined;
  }
}

function balancedJsonPropertyFragment(raw: string, key: string, openChar: "{" | "[", closeChar: "}" | "]") {
  const source = String(raw || "");
  const prop = `"${key}"`;
  let propIndex = source.indexOf(prop);
  while (propIndex >= 0) {
    const colonIndex = source.indexOf(":", propIndex + prop.length);
    if (colonIndex < 0) return "";
    let start = colonIndex + 1;
    while (/\s/.test(source[start] || "")) start += 1;
    if (source[start] === openChar) {
      return sliceBalancedJsonFragment(source, start, openChar, closeChar);
    }
    propIndex = source.indexOf(prop, propIndex + prop.length);
  }
  return "";
}

function sliceBalancedJsonFragment(source: string, start: number, openChar: "{" | "[", closeChar: "}" | "]") {
  let depth = 0;
  let inString = false;
  let escaped = false;
  for (let index = start; index < source.length; index += 1) {
    const char = source[index];
    if (inString) {
      if (escaped) {
        escaped = false;
      } else if (char === "\\") {
        escaped = true;
      } else if (char === "\"") {
        inString = false;
      }
      continue;
    }
    if (char === "\"") {
      inString = true;
      continue;
    }
    if (char === openChar) depth += 1;
    if (char === closeChar) {
      depth -= 1;
      if (depth === 0) return source.slice(start, index + 1);
    }
  }
  return "";
}

function parseJsonFragmentObject(fragment: string): Record<string, unknown> | null {
  const candidates = uniqueStrings([
    fragment,
    repairJsonControlCharactersInsideStrings(fragment),
  ]);
  for (const candidate of candidates) {
    try {
      const parsed = JSON.parse(candidate);
      return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed as Record<string, unknown> : null;
    } catch {
      // Try the repaired candidate.
    }
  }
  return null;
}

function firstRegexGroup(raw: string, pattern: RegExp) {
  return String(raw || "").match(pattern)?.[1] || "";
}

function repairJsonControlCharactersInsideStrings(input: string) {
  let output = "";
  let inString = false;
  let escaped = false;
  for (const char of String(input || "")) {
    if (!inString) {
      if (char === "\"") inString = true;
      output += char;
      continue;
    }
    if (escaped) {
      output += char;
      escaped = false;
      continue;
    }
    if (char === "\\") {
      output += char;
      escaped = true;
      continue;
    }
    if (char === "\"") {
      output += char;
      inString = false;
      continue;
    }
    if (char === "\n") {
      output += "\\n";
      continue;
    }
    if (char === "\r") {
      output += "\\r";
      continue;
    }
    if (char === "\t") {
      output += "\\t";
      continue;
    }
    output += char;
  }
  return output;
}

function extractHtmlFromKnowledgeNoteGatewayObject(value: unknown, depth = 0): KnowledgeNoteGatewayHtmlDraft | null {
  if (depth > 8 || value == null) return null;
  if (typeof value === "string") {
    const directHtml = extractDirectKnowledgeNoteHtml(value);
    if (directHtml) return { html: directHtml };
    if (/[\{\[]/.test(value) && /"html"|htmlQuality|payloads|<!doctype|<html/i.test(value)) {
      return parseKnowledgeNoteHtmlGatewayJson(value);
    }
    return null;
  }
  if (Array.isArray(value)) {
    for (const item of value) {
      const nested = extractHtmlFromKnowledgeNoteGatewayObject(item, depth + 1);
      if (nested?.html) return nested;
    }
    return null;
  }
  if (!value || typeof value !== "object") return null;
  const record = value as Record<string, unknown>;
  const directHtml = firstString(record.html, record.documentHtml, record.htmlDocument, record.content);
  if (directHtml && isKnowledgeNoteHtmlString(directHtml)) return { ...(record as KnowledgeNoteGatewayHtmlDraft), html: directHtml };
  for (const key of ["htmlDraft", "document", "result", "output", "data", "payload", "response", "final", "message", "text", "value", "draft", "payloads", "choices"]) {
    const nested = extractHtmlFromKnowledgeNoteGatewayObject(record[key], depth + 1);
    if (nested?.html) {
      return {
        sourceHash: firstString(record.sourceHash, nested.sourceHash),
        title: firstString(record.title, nested.title),
        htmlQuality: (record.htmlQuality || nested.htmlQuality) as KnowledgeNoteGatewayHtmlDraft["htmlQuality"],
        html: nested.html,
      };
    }
  }
  return null;
}

function firstString(...values: unknown[]) {
  for (const value of values) {
    if (typeof value === "string" && value.trim()) return value.trim();
  }
  return "";
}

function validateGatewayKnowledgeDraftSource(
  parsed: KnowledgeNoteGatewayDraft,
  draft: ReturnType<typeof normalizeGatewayKnowledgeDraft>["draft"],
  seed: ReturnType<typeof organizeKnowledgeNoteDraft>,
  rawContent: string,
  sourceHash: string,
) {
  const echoedHash = String(parsed.sourceHash || "").trim();
  if (echoedHash && echoedHash !== sourceHash) return { ok: false, reason: "gateway_source_hash_mismatch" };
  if (knowledgeNoteHasUnsupportedCourseDrift(rawContent, {
    title: draft.title,
    type: draft.type,
    tags: draft.tags,
    related: draft.related,
    markdown: draft.markdown,
  })) {
    return { ok: false, reason: "gateway_source_mismatch:course_context_not_supported" };
  }
  if (knowledgeNoteHasUnsupportedMbaDrift(rawContent, {
    title: draft.title,
    type: draft.type,
    tags: draft.tags,
    related: draft.related,
    markdown: draft.markdown,
  })) {
    return { ok: false, reason: "gateway_source_mismatch:degree_course_not_supported" };
  }
  if (knowledgeNoteHasUnsupportedSafetyMeetingDrift(rawContent, {
    title: draft.title,
    type: draft.type,
    tags: draft.tags,
    related: draft.related,
    markdown: draft.markdown,
  })) {
    return { ok: false, reason: "gateway_source_mismatch:safety_meeting_not_supported" };
  }
  if (knowledgeNoteHasUnsupportedReliabilityMeetingDrift(rawContent, {
    title: draft.title,
    type: draft.type,
    tags: draft.tags,
    related: draft.related,
    markdown: draft.markdown,
  })) {
    return { ok: false, reason: "gateway_source_mismatch:reliability_template_not_supported" };
  }
  const coverageCheck = validateKnowledgeNoteTopicCoverage(rawContent, draft, parsed);
  if (!coverageCheck.ok) return coverageCheck;
  const raw = normalizeValidationText(rawContent);
  const titleTerms = extractValidationTerms(draft.title).filter((term) => !isCommonValidationTerm(term));
  const supportedTitleTerms = titleTerms.filter((term) => validationTermSupported(term, raw));
  const seedTerms = extractValidationTerms(seed.title).filter((term) => !isCommonValidationTerm(term));
  const titleSharesSeed = titleTerms.some((term) => seedTerms.includes(term)) || seedTerms.some((term) => titleTerms.includes(term));
  if (titleTerms.length >= 2 && supportedTitleTerms.length === 0 && !titleSharesSeed && titleHasHighRiskUnsupportedDomain(draft.title)) {
    return { ok: false, reason: "gateway_source_mismatch:title_not_supported" };
  }
  const analysisText = stripKnowledgeRawArchive(`${draft.title}\n${draft.tags.join(" ")}\n${draft.related.join(" ")}\n${draft.markdown}`).slice(0, 8000);
  const prominentTerms = uniqueStrings(extractValidationTerms(analysisText))
    .filter((term) => !isCommonValidationTerm(term))
    .slice(0, 80);
  const supported = prominentTerms.filter((term) => validationTermSupported(term, raw));
  const unsupported = prominentTerms.filter((term) => !validationTermSupported(term, raw));
  // v3 哲学：让模型自由发挥，不做 source overlap 硬门槛（LLM 有时会用同义词/重写，不一定字面 overlap）。
  // low_source_overlap 仍是诊断信息，但不再阻断。XSS / 错配等硬校验继续。
  if (false && prominentTerms.length >= 12 && supported.length < 3 && unsupported.length >= 8) {
    return { ok: false, reason: "gateway_source_mismatch:low_source_overlap" };
  }
  return { ok: true, reason: "" };
}

function titleHasHighRiskUnsupportedDomain(title: string) {
  return /MBA|EMBA|工程硕士|生产运作管理|供应链金融|波特五力|安委会|安全委员会|可靠性会|可靠性会议|习近平|特朗普|中美关系|总统|高峰会/i.test(title);
}

function knowledgeNoteHasUnsupportedSafetyMeetingDrift(
  rawContent: string,
  candidate: Pick<KnowledgeNoteDraftInput, "title" | "type" | "tags" | "related" | "markdown">,
) {
  const source = String(rawContent || "");
  const sourceHasSafetyMeeting = /安委会|安全委员会|安全会议|安全生产委员会|安全工作会|安全运行会/.test(source);
  if (sourceHasSafetyMeeting) return false;
  const candidateText = [
    candidate.title || "",
    candidate.type || "",
    ...(candidate.tags || []),
    ...(candidate.related || []),
    stripKnowledgeRawArchive(candidate.markdown || "").slice(0, 12_000),
  ].join("\n");
  return /安委会|安全委员会|安全会议|安全生产委员会|安全工作会|安全运行会/.test(candidateText);
}

function knowledgeNoteHasUnsupportedReliabilityMeetingDrift(
  rawContent: string,
  candidate: Pick<KnowledgeNoteDraftInput, "title" | "type" | "tags" | "related" | "markdown">,
) {
  const source = String(rawContent || "");
  const sourceExplicitReliability = /可靠性会|可靠性会议|可靠性月度|可靠性管理/.test(source);
  const candidateText = [
    candidate.title || "",
    candidate.type || "",
    ...(candidate.tags || []),
    ...(candidate.related || []),
    stripKnowledgeRawArchive(candidate.markdown || "").slice(0, 12_000),
  ].join("\n");
  const copiedReliabilityTemplate = /这是一份可靠性会议记录|可靠性会议的价值|可靠性管理不是把故障逐条列完|没有航材保障的工程指令/.test(candidateText);
  if (copiedReliabilityTemplate && !sourceExplicitReliability) return true;
  const unsupportedAviationTerms = ["HSTA", "PMA", "CFM56", "V2500", "SFCC", "客舱玻璃", "外层玻璃", "刹车导线", "Boeing"];
  const unsupportedCount = unsupportedAviationTerms.filter((term) => candidateText.includes(term) && !source.includes(term)).length;
  return unsupportedCount >= 3 && /可靠性|工程指令|EO|C检|航材保障/.test(candidateText);
}

type ExpectedKnowledgeTopic = {
  label: string;
  patterns: RegExp[];
  outputTerms: string[];
};

function validateKnowledgeNoteTopicCoverage(rawContent: string, draft: KnowledgeNoteDraftInput, parsed: KnowledgeNoteGatewayDraft) {
  // v3.3 修复：删 topic coverage 硬门槛。LLM 用同义词/重写时会触发"insufficient_topic_coverage"误杀。
  // v3 哲学"不限制模型输出"——只留 XSS / HTML 完整性 + sourceHash 校验，其他全删。
  return { ok: true, reason: "" };
}

function expectedKnowledgeNoteTopics(rawContent: string): ExpectedKnowledgeTopic[] {
  const source = String(rawContent || "");
  return allExpectedKnowledgeNoteTopics().filter((spec) => spec.patterns.some((pattern) => pattern.test(source)));
}

function allExpectedKnowledgeNoteTopics(): ExpectedKnowledgeTopic[] {
  return [
    { label: "《浪潮将至》共读", patterns: [/浪潮将至|共读|读书会|这本书/], outputTerms: ["浪潮将至", "共读", "读书会"] },
    { label: "AI 工具使用", patterns: [/扣子|Coze|艾玛|(?:^|[^a-z])ima(?:$|[^a-z])|AI\s*工具|每日觉察|自动化任务/i], outputTerms: ["AI工具", "扣子", "Coze", "艾玛", "每日觉察"] },
    { label: "Obsidian 与知识管理", patterns: [/Obsidian|obsessing|双向链接|知识图谱|LLM Wiki|知识管理|知识库|Markdown.*(?:知识|笔记|双链|Obsidian)/i], outputTerms: ["Obsidian", "Markdown", "双向链接", "知识图谱", "知识管理", "LLM Wiki"] },
    { label: "AI 项目推进", patterns: [/AI\s*精准营销|AI\s*洞察|立项|信息部|AOG|项目二期|场景/i], outputTerms: ["AI项目", "AI精准营销", "AI洞察", "立项", "信息部", "AOG"] },
    { label: "产品开发模式变革", patterns: [/PRD|产品经理|需求|直接交付|重新开发|体验者模式|HTML\s*交互文档|Markdown\s*可信源/i], outputTerms: ["PRD", "产品开发", "直接交付", "Markdown", "HTML", "体验者"] },
    { label: "编程成本趋近于零", patterns: [/代码成本|编程成本|程序员|复刻|甲骨文|信息部未来|算力.*门槛/i], outputTerms: ["代码成本", "编程成本", "复刻", "程序员", "信息部"] },
    { label: "马斯克与星际文明", patterns: [/马斯克|火星|星辰|文明|机器人|永生|脑机接口|芯片工厂/i], outputTerms: ["马斯克", "火星", "星际", "文明", "机器人", "永生", "脑机接口"] },
    { label: "芯片算力与能源竞争", patterns: [/芯片|算力|英伟达|华为|电力|绿色能源|H25|中国优势/i], outputTerms: ["芯片", "算力", "英伟达", "华为", "电力", "中国优势"] },
    { label: "共读活动调整", patterns: [/下期|分享|主理人|AI应用专场|主题分享|轮流/i], outputTerms: ["共读活动", "下期", "分享", "主理人", "AI应用"] },
    { label: "成本与模型配置", patterns: [/token|VPN|API|key|provider|模型配置|MiniMax.*配置|deepseek.*配置|deep sync/i], outputTerms: ["token", "VPN", "API", "模型配置", "MiniMax", "DeepSeek"] },
  ];
}

function normalizeGatewayKnowledgeDraft(parsed: KnowledgeNoteGatewayDraft, seed: ReturnType<typeof organizeKnowledgeNoteDraft>, requestedDecision: { chosenAgent: AgentId; reason: string; escalationNeeded: boolean }) {
  const draft = parsed.draft && typeof parsed.draft === "object" ? parsed.draft : {};
  const title = compactGatewayField(draft.title, seed.title, 80);
  const date = /^\d{4}-\d{2}-\d{2}$/.test(String(draft.date || "")) ? String(draft.date) : seed.date;
  const type = ["会议纪要", "工作记录", "学习笔记", "决策记录", "项目文档", "备忘"].includes(String(draft.type || "")) ? String(draft.type) : seed.type;
  const status = ["待跟进", "已完成", "仅供参考", "进行中"].includes(String(draft.status || "")) ? String(draft.status) : seed.status;
  const tags = normalizeGatewayStringList(draft.tags, seed.tags, 12);
  const related = normalizeGatewayStringList(draft.related, seed.related, 14).map((item) => item.startsWith("[[") ? item : `[[${item.replace(/^\[+|\]+$/g, "")}]]`);
  const folder = safeGatewayFolder(draft.folder, seed.folder);
  const sanitizedDraftMarkdown = maskGatewayKnowledgeDraftProfanity(String(draft.markdown || ""));
  const markdown = ensureGatewayMarkdown(normalizeKnowledgeNoteMarkdownEscapes(sanitizedDraftMarkdown), { title, date, type, status, tags, related }, seed.markdown);
  const layoutStrategy = normalizeKnowledgeNoteLayoutStrategy(parsed.layoutStrategy);
  const agentDecision = normalizeGatewayAgentDecision(parsed.agentDecision, requestedDecision);
  const quality = {
    ...normalizeGatewayQuality(parsed.quality),
    coverageMap: normalizeGatewayObjectList(parsed.coverageMap, 12),
    missingRisk: normalizeGatewayStringList(parsed.missingRisk, [], 8),
    sourceAnchors: normalizeGatewayObjectList(parsed.sourceAnchors, 12),
  };
  return { draft: { title, date, type, status, tags, related, folder, markdown }, layoutStrategy, agentDecision, quality };
}

function maskGatewayKnowledgeDraftProfanity(value: string): string {
  let text = String(value || "");
  text = text
    .replace(/我操/g, "**")
    .replace(/卧槽/g, "**")
    .replace(/他妈的/g, "**")
    .replace(/他妈/g, "**")
    .replace(/妈的/g, "**")
    .replace(/尼玛/g, "**")
    .replace(/傻逼/g, "**")
    .replace(/傻比/g, "**")
    .replace(/牛逼/g, "**")
    .replace(/滚蛋/g, "**");
  return text;
}

function stripKnowledgeRawArchive(markdown: string) {
  return String(markdown || "")
    .replace(/^---[\s\S]*?---\s*/, "")
    .replace(/##\s*原始记录[\s\S]*$/i, "")
    .replace(/```[\s\S]*?```/g, " ");
}

function normalizeValidationText(value: string) {
  return String(value || "").toLowerCase().normalize("NFKC").replace(/\s+/g, " ");
}

function extractValidationTerms(value: string) {
  const text = normalizeValidationText(value);
  const terms: string[] = [];
  for (const match of text.matchAll(/[a-z][a-z0-9_-]{1,}/g)) terms.push(match[0]);
  for (const match of text.matchAll(/[\u4e00-\u9fa5]{2,12}/g)) {
    const phrase = match[0];
    if (phrase.length <= 6) terms.push(phrase);
    else {
      for (let index = 0; index <= phrase.length - 4; index += 2) terms.push(phrase.slice(index, index + 4));
    }
  }
  return uniqueStrings(terms.map((term) => term.trim()).filter((term) => term.length >= 2 && term.length <= 24));
}

function uniqueStrings(rows: string[]) {
  return Array.from(new Set(rows.map((row) => String(row || "").trim()).filter(Boolean)));
}

function validationTermSupported(term: string, normalizedRaw: string) {
  const clean = normalizeValidationText(term);
  if (!clean) return false;
  if (normalizedRaw.includes(clean)) return true;
  if (/^[\u4e00-\u9fa5]{5,}$/.test(clean)) {
    const grams: string[] = [];
    for (let index = 0; index <= clean.length - 3; index += 1) grams.push(clean.slice(index, index + 3));
    return grams.length > 0 && grams.filter((gram) => normalizedRaw.includes(gram)).length >= Math.ceil(grams.length * 0.6);
  }
  return false;
}

function isCommonValidationTerm(term: string) {
  return new Set([
    "会议", "会议纪要", "工作", "工作记录", "学习", "学习笔记", "笔记", "项目", "项目文档", "备忘", "内容", "内容理解",
    "核心", "关键", "关键结论", "结论", "问题", "行动", "后续行动", "待核验", "原始", "原始记录", "记录",
    "管理", "系统", "流程", "任务", "计划", "状态", "来源", "主题", "结构", "概念", "相关", "依据",
    "markdown", "knowledge", "note", "openclaw", "task", "project",
  ]).has(term);
}

function compactGatewayField(value: unknown, fallback: string, maxLength: number) {
  const clean = String(value || "").replace(/\s+/g, " ").trim();
  return (clean || fallback).slice(0, maxLength);
}

function normalizeGatewayStringList(value: unknown, fallback: string[], maxItems: number) {
  const list = Array.isArray(value) ? value.map(String) : [];
  const cleaned = list.map((item) => item.replace(/[<>{}`$]/g, "").trim()).filter(Boolean);
  return Array.from(new Set(cleaned.length ? cleaned : fallback)).slice(0, maxItems);
}

function normalizeGatewayObjectList(value: unknown, maxItems: number) {
  if (!Array.isArray(value)) return [];
  return value
    .map((item) => {
      if (!item || typeof item !== "object") return null;
      const record = item as Record<string, unknown>;
      const cleaned: Record<string, string> = {};
      for (const [key, raw] of Object.entries(record)) {
        const cleanKey = key.replace(/[^a-zA-Z0-9_-]/g, "").slice(0, 32);
        const cleanValue = String(raw || "").replace(/[<>{}`$]/g, "").replace(/\s+/g, " ").trim().slice(0, 240);
        if (cleanKey && cleanValue) cleaned[cleanKey] = cleanValue;
      }
      return Object.keys(cleaned).length ? cleaned : null;
    })
    .filter(Boolean)
    .slice(0, maxItems);
}

function safeGatewayFolder(value: unknown, fallback: string) {
  const raw = String(value || fallback || "openclaw").trim();
  if (!raw || path.isAbsolute(raw) || raw.includes("..")) return fallback || "openclaw";
  return raw.split(/[\\/]+/).map((part) => safeName(part)).filter(Boolean).join("/") || fallback || "openclaw";
}

function ensureGatewayMarkdown(markdown: string, meta: { title: string; date: string; type: string; status: string; tags: string[]; related: string[] }, fallback: string) {
  const clean = markdown.trim();
  if (!clean) return fallback;
  if (/^---[\s\S]*?---\s*#\s+/m.test(clean)) return clean;
  const body = clean.replace(/^---[\s\S]*?---\s*/, "").replace(/^#\s+.*(?:\r?\n)+/, "").trim();
  if (!body) return fallback;
  return [
    "---",
    `tags: ${JSON.stringify(meta.tags)}`,
    `date: ${meta.date}`,
    `type: ${meta.type}`,
    `status: ${meta.status}`,
    `related: ${JSON.stringify(meta.related)}`,
    "---",
    "",
    `# ${meta.date} ${meta.title}`,
    "",
    body,
  ].join("\n");
}

function normalizeGatewayAgentDecision(value: KnowledgeNoteGatewayDraft["agentDecision"], fallback: { chosenAgent: AgentId; reason: string; escalationNeeded: boolean }) {
  const chosen = value?.chosenAgent === "main" || value?.chosenAgent === "boss" || value?.chosenAgent === "worker" ? value.chosenAgent : fallback.chosenAgent;
  return {
    chosenAgent: chosen,
    reason: compactGatewayField(value?.reason, fallback.reason, 160),
    escalationNeeded: Boolean(value?.escalationNeeded),
  };
}

function normalizeGatewayQuality(value: KnowledgeNoteGatewayDraft["quality"]) {
  const unresolved = Array.isArray(value?.unresolvedItems) ? value.unresolvedItems.map(String).filter(Boolean).slice(0, 8) : [];
  const confidence = Math.max(0, Math.min(1, Number(value?.confidence || 0.82)));
  return {
    confidence,
    sourceCoverage: compactGatewayField(value?.sourceCoverage, "M2.7 已基于原始内容和本地 seed draft 完成语义整理。", 180),
    unresolvedItems: unresolved,
  };
}

function clampNumber(value: unknown, min: number, max: number, fallback: number) {
  const number = Number(value);
  if (!Number.isFinite(number)) return fallback;
  return Math.max(min, Math.min(max, number));
}

app.post("/api/knowledge/preview-chat", async (req) => {
  const body = req.body as { sourcePath?: string; agentId?: string; question?: string };
  const preview = previewKnowledgeFile(body.sourcePath || "");
  const id = randomUUID();
  const answer = `已基于当前预览文件生成讨论上下文。\\n\\n问题：${body.question || ""}\\n\\n文件：${body.sourcePath || ""}\\n\\n摘要：${"content" in preview ? String(preview.content).slice(0, 1000) : ""}`;
  db.prepare("INSERT INTO knowledge_preview_chats (id, source_path, agent_id, question, answer, created_at) VALUES (?, ?, ?, ?, ?, ?)")
    .run(id, body.sourcePath || "", body.agentId || "main", body.question || "", answer, nowIso());
  return { ok: true, chat: db.prepare("SELECT * FROM knowledge_preview_chats WHERE id = ?").get(id) };
});

app.get("/api/knowledge/output-jobs", async () => ({
  ok: true,
  jobs: db.prepare("SELECT * FROM knowledge_output_jobs ORDER BY created_at DESC LIMIT 100").all(),
}));

app.get("/api/knowledge/wiki/pages", async (req) => {
  const query = req.query as { type?: string; q?: string; reviewStatus?: string; legacy?: string };
  const clauses: string[] = [];
  const values: string[] = [];
  if (query.type && query.type !== "all") {
    clauses.push("page_type = ?");
    values.push(query.type);
  }
  if (query.reviewStatus && query.reviewStatus !== "all") {
    clauses.push("review_status = ?");
    values.push(query.reviewStatus);
  }
  if (query.q) {
    clauses.push("(title LIKE ? OR summary LIKE ? OR path LIKE ?)");
    const like = `%${query.q}%`;
    values.push(like, like, like);
  }
  // 2026-07-07 (rework11 v2 Q3) — MOC 类型默认过滤老路径 (NJX 拍板: 老 MOC 隐藏, 单一真源在 njx-knowledge)
  // 知识库页面 MOC 列表只显示新路径 17 个
  // 兼容读: 加 ?legacy=1 显示老 MOC (debug / admin)
  if (!query.legacy && query.type === "MOC") {
    clauses.push("path LIKE ?");
    values.push("/Users/njx/njx-knowledge/wiki/MOC/%");
  }
  const sql = `SELECT * FROM knowledge_wiki_pages${clauses.length ? ` WHERE ${clauses.join(" AND ")}` : ""} ORDER BY updated_at DESC LIMIT 200`;
  return { ok: true, pages: db.prepare(sql).all(...values) };
});

