// iter-9: 笔记预渲染缓存 + 笔记-文件路径映射
// 复用 buildKnowledgeGraph 用的 NOTES_DIR + leaf scan
const NOTES_DIR = "/Users/njx/openclaw_data/memory/knowledge/notes";
const NOTES_PREVIEW_CACHE: { ts: number; data: Map<string, { title: string; summary: string; tags: string[]; rawHtml: string; file: string }> } = { ts: 0, data: new Map() };
const NOTES_PREVIEW_TTL_MS = 5 * 60 * 1000; // 5 min

async function buildNotePreviews(limit = 100): Promise<Map<string, { title: string; summary: string; tags: string[]; rawHtml: string; file: string }>> {
  const fs = await import("node:fs/promises");
  const pathMod = await import("node:path");
  const out = new Map<string, { title: string; summary: string; tags: string[]; rawHtml: string; file: string }>();
  async function walk(dir: string, prefix: string) {
    if (out.size >= limit) return;
    let entries: Array<{ name: string; isFile: () => boolean; isDirectory: () => boolean }> = [];
    try {
      entries = await fs.readdir(dir, { withFileTypes: true }) as any;
    } catch { return; }
    for (const entry of entries) {
      if (out.size >= limit) return;
      if (entry.name.startsWith(".")) continue;
      const fullPath = pathMod.join(dir, entry.name);
      if (entry.isDirectory()) {
        if (entry.name === "node_modules" || entry.name === "worker_runs") continue;
        await walk(fullPath, prefix ? `${prefix}/${entry.name}` : entry.name);
      } else if (entry.isFile() && entry.name.endsWith(".html")) {
        const rel = prefix ? `${prefix}/${entry.name}` : entry.name;
        try {
          const raw = await fs.readFile(fullPath, "utf8");
          // 提取 title (优先从 h1 找，否则从 <title>)
          const h1Match = raw.match(/<h1[^>]*>([^<]+)<\/h1>/gi);
          const titleMatch = raw.match(/<title[^>]*>([^<]+)<\/title>/gi);
          const title = (h1Match?.[1] || titleMatch?.[1] || entry.name.replace(/\.html$/i, "")).trim();
          // 提取 .subtitle (作为 summary)
          const subMatch = raw.match(/class=["']subtitle["'][^>]*>([^<]+)/i);
          const summary = subMatch?.[1]?.trim() || "";
          // 提取 tag (.tag 元素)
          const tagRegex = /class=["']tag["'][^>]*>([^<]+)</g;
          const tags: string[] = [];
          const tagMatches = raw.matchAll(tagRegex);
          for (const tm of tagMatches) {
            const t = tm[1].trim();
            if (t && !tags.includes(t)) tags.push(t);
          }
          out.set(entry.name, { title, summary, tags, rawHtml: raw, file: rel });
        } catch (e) {
          // 读不到就 skip
        }
      }
    }
  }
  await walk(NOTES_DIR, "");
  return out;
}

function getNotePreviews(limit: number): Map<string, { title: string; summary: string; tags: string[]; rawHtml: string; file: string }> {
  const now = Date.now();
  if (now - NOTES_PREVIEW_CACHE.ts > NOTES_PREVIEW_TTL_MS || NOTES_PREVIEW_CACHE.data.size === 0) {
    // 同步扫描（避免 async 在 sync 上下文里）— 用顶层 import 的 fs/path（line 1-2）（iter-10: ESM require 已废）
    NOTES_PREVIEW_CACHE.data.clear();
    NOTES_PREVIEW_CACHE.ts = now;
    function walkSync(dir: string, prefix: string) {
      if (NOTES_PREVIEW_CACHE.data.size >= limit) return;
      let entries: string[] = [];
      try {
        entries = fs.readdirSync(dir);
      } catch { return; }
      for (const name of entries) {
        if (NOTES_PREVIEW_CACHE.data.size >= limit) return;
        if (name.startsWith(".")) continue;
        const fullPath = path.join(dir, name);
        let stat;
        try { stat = fs.statSync(fullPath); } catch { continue; }
        if (stat.isDirectory()) {
          if (name === "node_modules" || name === "worker_runs") continue;
          walkSync(fullPath, prefix ? `${prefix}/${name}` : name);
        } else if (name.endsWith(".html")) {
          const rel = prefix ? `${prefix}/${name}` : name;
          try {
            const raw = fs.readFileSync(fullPath, "utf8");
            const h1Match = raw.match(/<h1[^>]*>([^<]+)<\/h1>/gi);
            const titleMatch = raw.match(/<title[^>]*>([^<]+)<\/title>/gi);
            const title = (h1Match?.[1] || titleMatch?.[1] || name.replace(/\.html$/i, "")).trim();
            const subMatch = raw.match(/class=["']subtitle["'][^>]*>([^<]+)/i);
            const summary = subMatch?.[1]?.trim() || "";
            const tagRegex = new RegExp('<span[^>]*class="tag"[^>]*>([^<]+)</span>', "g");
            const tags: string[] = [];
            for (const tm of raw.matchAll(tagRegex)) {
              const t = tm[1].trim();
              if (t && !tags.includes(t)) tags.push(t);
            }
            NOTES_PREVIEW_CACHE.data.set(name, { title, summary, tags, rawHtml: raw, file: rel });
          } catch (e) {}
        }
      }
    }
    try { walkSync(NOTES_DIR, ""); } catch (e) { console.warn("[note-previews] scan failed:", e); }
  }
  return NOTES_PREVIEW_CACHE.data;
}

const NOTES_FILE_MAP_CACHE: { ts: number; map: Record<string, string> } = { ts: 0, map: {} };

// iter-10: 预计算 leaf entries（修 iter-9 写错成 fire-and-forget IIFE 放 return 后永不执行的 bug）
const NOTES_DIR_LEAF_PATH = "/Users/njx/openclaw_data/memory/knowledge/notes";
type LeafEntry = { rel: string; name: string; category: string };
function buildLeafEntries(): LeafEntry[] {
  const out: LeafEntry[] = [];
  function walk(dir: string, prefix: string): void {
    let entries: string[] = [];
    try { entries = fs.readdirSync(dir); } catch { return; }
    for (const n of entries) {
      if (n.startsWith(".")) continue;
      const full = path.join(dir, n);
      let st: ReturnType<typeof fs.statSync> | null = null;
      try { st = fs.statSync(full); } catch { continue; }
      if (!st) continue;
      if (st.isDirectory()) {
        if (n === "node_modules" || n === "worker_runs") continue;
        walk(full, prefix ? `${prefix}/${n}` : n);
      } else if (st.isFile() && n.endsWith(".html")) {
        out.push({
          rel: prefix ? `${prefix}/${n}` : n,
          name: n.replace(/\.html$/i, ""),
          category: prefix ? prefix.split("/")[0] : "",
        });
      }
    }
  }
  try { walk(NOTES_DIR_LEAF_PATH, ""); } catch (e) { console.warn("[iter-10 leaf scan] failed:", e); }
  return out;
}
const LEAF_ENTRIES: ReadonlyArray<LeafEntry> = buildLeafEntries();

function getHtmlFileMap(): Record<string, string> {
  const now = Date.now();
  if (now - NOTES_FILE_MAP_CACHE.ts > NOTES_PREVIEW_TTL_MS) {
    // iter-10: 用顶层 import 的 fs/path（line 1-2）；旧 require 在 ESM dist 抛 ReferenceError
    const map: Record<string, string> = {};
    function walkSync(dir: string, prefix: string) {
      let entries: string[] = [];
      try { entries = fs.readdirSync(dir); } catch { return; }
      for (const name of entries) {
        if (name.startsWith(".")) continue;
        const fullPath = path.join(dir, name);
        let stat;
        try { stat = fs.statSync(fullPath); } catch { continue; }
        if (stat.isDirectory()) {
          if (name === "node_modules" || name === "worker_runs") continue;
          walkSync(fullPath, prefix ? `${prefix}/${name}` : name);
        } else if (name.endsWith(".html")) {
          const rel = prefix ? `${prefix}/${name}` : name;
          map[name] = rel;
        }
      }
    }
    try { walkSync(NOTES_DIR, ""); } catch (e) { console.warn("[html-file-map] scan failed:", e); }
    NOTES_FILE_MAP_CACHE.ts = now;
    NOTES_FILE_MAP_CACHE.map = map;
  }
  return NOTES_FILE_MAP_CACHE.map;
}

app.get("/api/knowledge/note-previews", async (req) => {
  const query = req.query as { limit?: string };
  const limit = Math.max(1, Math.min(500, parseInt(String(query.limit || "100"), 10) || 100));
  const map = getNotePreviews(limit);
  const out: Record<string, { title: string; summary: string; tags: string[]; rawHtml: string; file: string }> = {};
  let i = 0;
  for (const [k, v] of map) {
    if (i >= limit) break;
    out[k] = v;
    i++;
  }
  return { ok: true, count: Object.keys(out).length, previews: out };
});

