app.post("/api/research", async (req) => {
  const body = req.body as { title?: string; question?: string; sources?: KnowledgeSource[]; formats?: string[] };
  const title = String(body.title || "Deep Research");
  const question = String(body.question || "");
  const sources = normalizeSources(body.sources);
  const requestedFormats = body.formats?.length ? body.formats : ["md", "mindmap"];
  const formats = requestedFormats.filter((format) => ["md", "mindmap"].includes(format));
  const unsupportedFormats = requestedFormats.filter((format) => !formats.includes(format));
  const created = nowIso();
  const placeholder = randomUUID();
  db.prepare("INSERT INTO research_jobs (id, title, question, sources, formats, status, notes, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)")
    .run(placeholder, title, question, JSON.stringify(sources), JSON.stringify(formats), "running", "", created, created);
  const result = await runResearch({ title, question, sources, formats });
  db.prepare("UPDATE research_jobs SET id = ?, status = ?, output_dir = ?, report_path = ?, mindmap_path = ?, ppt_path = ?, notes = ?, updated_at = ?, report_html_path = ?, mindmap_html_path = ?, sidecar_html_path = ? WHERE id = ?")
    .run(result.id, "completed", result.outputDir, result.reportPath, result.mindmapPath, result.pptPath, [result.notes, unsupportedFormats.length ? `unsupported_formats: ${unsupportedFormats.join(", ")}` : ""].filter(Boolean).join("; "), nowIso(), result.reportHtmlPath, result.mindmapHtmlPath, result.sidecarHtmlPath, placeholder);
  audit(db, "research.create", "research", result.id, "normal", { title, sources, formats });
  return { ok: true, job: db.prepare("SELECT * FROM research_jobs WHERE id = ?").get(result.id) };
});

