function opcNumber(value: unknown, fallback = 0) {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

function opcText(value: unknown, fallback = "") {
  return value === undefined || value === null ? fallback : String(value);
}

function opcJsonText(value: unknown, fallback: unknown) {
  if (typeof value === "string") return value;
  return JSON.stringify(value ?? fallback);
}

function opcReadJson<T>(value: unknown, fallback: T): T {
  if (typeof value !== "string" || !value.trim()) return fallback;
  try {
    return JSON.parse(value) as T;
  } catch {
    return fallback;
  }
}

function opcApprovalDetails(row: Record<string, unknown>) {
  const details = opcReadJson<Record<string, unknown>>(row.details, {});
  return {
    ...details,
    scope: String(details.scope || ""),
    projectId: String(details.projectId || ""),
    approvalKey: String(details.approvalKey || ""),
    title: String(details.title || row.action || "OPC 审批"),
    summary: String(details.summary || ""),
    riskLevel: String(details.riskLevel || "normal"),
    runId: String(details.runId || ""),
    objectType: String(details.objectType || ""),
    objectId: String(details.objectId || ""),
    targetTab: String(details.targetTab || "自动化"),
  };
}

function opcApprovalRows(projectId: string, limit = 160) {
  const rows = db.prepare("SELECT * FROM approvals ORDER BY requested_at DESC LIMIT ?").all(limit) as Array<Record<string, unknown>>;
  const withDetails = rows.map((row) => ({ ...row, opcDetails: opcApprovalDetails(row) })) as Array<Record<string, any>>;
  return withDetails.filter((row) => row.opcDetails.scope === "opc" && row.opcDetails.projectId === projectId);
}

function opcPendingApprovalByKey(projectId: string, approvalKey: string) {
  return opcApprovalRows(projectId, 240).find((row) => row.status === "pending" && row.opcDetails.approvalKey === approvalKey) || null;
}

function opcEnsureApproval(projectId: string, input: {
  approvalKey: string;
  action: string;
  title: string;
  summary: string;
  riskLevel?: string;
  runId?: string;
  objectType?: string;
  objectId?: string;
  targetTab?: string;
  payload?: unknown;
}) {
  const existing = opcPendingApprovalByKey(projectId, input.approvalKey);
  if (existing) return existing;
  const id = randomUUID();
  const details = {
    scope: "opc",
    projectId,
    approvalKey: input.approvalKey,
    title: input.title,
    summary: input.summary,
    riskLevel: input.riskLevel || "normal",
    runId: input.runId || "",
    objectType: input.objectType || "automation",
    objectId: input.objectId || input.runId || "",
    targetTab: input.targetTab || "自动化",
    payload: input.payload || {},
  };
  db.prepare("INSERT INTO approvals (id, task_id, action, status, requested_at, details) VALUES (?, ?, ?, ?, ?, ?)")
    .run(id, null, `opc:${input.action}`, "pending", nowIso(), JSON.stringify(details));
  audit(db, "opc.approval.request", "approval", id, input.riskLevel || "normal", details);
  notify("warn", "OPC 需要人工确认", input.title, "opc");
  return { ...(db.prepare("SELECT * FROM approvals WHERE id = ?").get(id) as Record<string, unknown>), opcDetails: details };
}

function opcRiskWeight(value: unknown) {
  const text = String(value || "").toLowerCase();
  if (/p0|critical|high|blocked|paused|risk/.test(text)) return 0;
  if (/p1|pending_approval|pending|not_configured/.test(text)) return 1;
  if (/p2|planned|draft/.test(text)) return 2;
  return 3;
}

function opcLatestRunByAction(rows: Array<Record<string, unknown>>, action: string) {
  return rows.find((row) => String(row.action) === action) || null;
}

function opcMoneyPair(body: Record<string, unknown>, usdKey: string, cnyKey: string) {
  const usd = opcNumber(body[usdKey], 0);
  const cny = body[cnyKey] === undefined || body[cnyKey] === null || body[cnyKey] === "" ? usd * OPC_FX_RATE : opcNumber(body[cnyKey], 0);
  return { usd, cny };
}

function markdownSource(paths: string[]) {
  for (const filePath of paths) {
    try {
      if (fs.existsSync(filePath)) return { path: filePath, content: fs.readFileSync(filePath, "utf8") };
    } catch {
      continue;
    }
  }
  return null;
}

function cleanMarkdownCell(value: string) {
  return String(value || "")
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/\*\*/g, "")
    .replace(/​/g, "")
    .replace(/&nbsp;/g, " ")
    .replace(/\s+\n/g, "\n")
    .replace(/\n\s+/g, "\n")
    .trim();
}

function tableCells(line: string) {
  return line.split("|").slice(1, -1).map((cell) => cleanMarkdownCell(cell));
}

function matrixParts(text: string) {
  const knowledge = text.match(/\[知\]\s*([\s\S]*?)(?=\[行\]|-\s*\[|$)/)?.[1]?.trim() || "";
  const action = text.match(/\[行\]\s*([\s\S]*?)(?=-\s*\[|$)/)?.[1]?.trim() || "";
  const items = [...text.matchAll(/-\s*\[([ xX])\]\s*([^\n]+)/g)].map((match) => ({
    title: match[2].trim(),
    done: match[1].toLowerCase() === "x",
  }));
  return { knowledge, action, items };
}

function parseLifeMatrix(matrixMarkdown = "", planMarkdown = "") {
  const cells = new Map<string, {
    dimension: string;
    vision: string;
    knowledge: string;
    action: string;
    actionItems: Array<{ title: string; done: boolean }>;
    completion: number;
    recentAction: string;
  }>();
  for (const vision of LIFE_VISIONS) {
    for (const dimension of LIFE_DIMENSIONS) {
      cells.set(`${vision}:${dimension}`, { dimension, vision, knowledge: "", action: "", actionItems: [], completion: 0, recentAction: "" });
    }
  }
  for (const markdown of [matrixMarkdown, planMarkdown]) {
    for (const line of markdown.split(/\r?\n/)) {
      if (!line.trim().startsWith("|")) continue;
      const cellsInLine = tableCells(line);
      if (cellsInLine.length < 5) continue;
      const vision = LIFE_VISIONS.find((item) => cellsInLine[0].includes(item));
      if (!vision) continue;
      LIFE_DIMENSIONS.forEach((dimension, index) => {
        const key = `${vision}:${dimension}`;
        const current = cells.get(key);
        if (!current) return;
        const parts = matrixParts(cellsInLine[index + 1] || "");
        if (parts.knowledge && !current.knowledge) current.knowledge = parts.knowledge;
        if (parts.action && !current.action) current.action = parts.action;
        if (parts.items.length) current.actionItems = parts.items;
      });
    }
  }
  return LIFE_VISIONS.map((vision) => ({
    vision,
    cells: LIFE_DIMENSIONS.map((dimension) => {
      const cell = cells.get(`${vision}:${dimension}`)!;
      const total = cell.actionItems.length;
      const done = cell.actionItems.filter((item) => item.done).length;
      return {
        ...cell,
        actionCount: total,
        completion: total ? Math.round((done / total) * 100) : 0,
        recentAction: cell.actionItems[0]?.title || "待补充行动记录",
      };
    }),
  }));
}

function inferLifeDimension(project: Record<string, unknown>) {
  const text = [
    project.name,
    project.status,
    project.description,
    project.objective,
    project.key_results,
  ].map((value) => String(value || "")).join(" ");
  if (/家庭|成家|伴侣|家人|生育|基金|厨艺|旅游/.test(text)) return "家庭";
  if (/事业|公司|航材|AOG|库房|供应链|经理|工作|项目|团队|管理体系/.test(text)) return "事业";
  if (/社会|文化|阳明|健康生活|自媒体|行业标准|奉献|传统文化/.test(text)) return "社会";
  if (/个人|MBA|论文|知识库|AI|机器人|OpenClaw|健康|运动|情绪|人生规划/.test(text)) return "个人";
  return "未分类";
}

function buildLifePlan() {
  const matrixSource = markdownSource(LIFE_MATRIX_PATHS);
  const planSource = markdownSource(LIFE_PLAN_PATHS);
  const projectRows = db.prepare("SELECT * FROM projects WHERE name <> ? ORDER BY created_at DESC").all(OPC_PROJECT_NAME) as Array<Record<string, unknown>>;
  const planProject = projectRows.find((project) => String(project.name).includes(LIFE_PLAN_PROJECT_NAME)) || null;
  const projectIds = projectRows.map((project) => String(project.id));
  const milestones = projectIds.length
    ? db.prepare(`SELECT * FROM project_milestones WHERE project_id IN (${projectIds.map(() => "?").join(",")}) ORDER BY due_date ASC, created_at DESC`).all(...projectIds)
    : [];
  const deliverables = projectIds.length
    ? db.prepare(`SELECT * FROM project_deliverables WHERE project_id IN (${projectIds.map(() => "?").join(",")}) ORDER BY created_at DESC`).all(...projectIds)
    : [];
  return {
    ok: true,
    matrix: parseLifeMatrix(matrixSource?.content || "", planSource?.content || ""),
    dimensions: LIFE_DIMENSIONS,
    visions: LIFE_VISIONS,
    planProject,
    projects: projectRows.map((project) => ({ ...project, life_dimension: inferLifeDimension(project) })),
    milestones,
    deliverables,
    sources: {
      matrix: matrixSource?.path || null,
      plan: planSource?.path || null,
      missing: [
        matrixSource ? null : "人生修行矩阵.md",
        planSource ? null : "五年人生规划（2026-2030）.md",
      ].filter(Boolean),
    },
  };
}

function opcFindProject() {
  return db.prepare("SELECT * FROM projects WHERE name = ? ORDER BY created_at ASC LIMIT 1").get(OPC_PROJECT_NAME) as Record<string, unknown> | undefined;
}

function opcProjectOrReply(projectId: string) {
  return db.prepare("SELECT * FROM projects WHERE id = ?").get(projectId) as Record<string, unknown> | undefined;
}

function opcInsertIfMissing(table: string, projectId: string, uniqueColumn: string, uniqueValue: string, row: Record<string, unknown>) {
  const existing = db.prepare(`SELECT id FROM ${table} WHERE project_id = ? AND ${uniqueColumn} = ? LIMIT 1`).get(projectId, uniqueValue);
  if (existing) return;
  const created = nowIso();
  const data: Record<string, unknown> = { id: randomUUID(), project_id: projectId, ...row, created_at: created, updated_at: created };
  const columns = Object.keys(data);
  const placeholders = columns.map(() => "?").join(", ");
  db.prepare(`INSERT INTO ${table} (${columns.join(", ")}) VALUES (${placeholders})`).run(...columns.map((column) => data[column] as any));
}

function opcEnsureProjectTodo(projectId: string, title: string, dueOffsetDays: number, notes: string) {
  const existing = db.prepare("SELECT id FROM todos WHERE project_id = ? AND title = ? LIMIT 1").get(projectId, title);
  if (existing) return;
  const due = new Date();
  due.setDate(due.getDate() + dueOffsetDays);
  db.prepare("INSERT INTO todos (id, title, status, priority, due_at, project_id, created_at, updated_at, tags, list_name, agent_id, notes) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
    .run(randomUUID(), title, "open", "P1", due.toISOString().slice(0, 16), projectId, nowIso(), nowIso(), JSON.stringify(["OPC", "Autopilot"]), "OPC自动化", "worker", notes);
}

function opcEnsureMilestone(projectId: string, name: string, dueOffsetDays: number, deliverables: string[]) {
  const existing = db.prepare("SELECT id FROM project_milestones WHERE project_id = ? AND name = ? LIMIT 1").get(projectId, name);
  if (existing) return;
  const due = new Date();
  due.setDate(due.getDate() + dueOffsetDays);
  db.prepare("INSERT INTO project_milestones (id, project_id, name, due_date, status, deliverables, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)")
    .run(randomUUID(), projectId, name, due.toISOString().slice(0, 10), "pending", JSON.stringify(deliverables), nowIso(), nowIso());
}

function opcEnsureDeliverable(projectId: string, title: string, uri: string) {
  const existing = db.prepare("SELECT id FROM project_deliverables WHERE project_id = ? AND title = ? LIMIT 1").get(projectId, title);
  if (existing) return;
  db.prepare("INSERT INTO project_deliverables (id, project_id, title, uri, status, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?)")
    .run(randomUUID(), projectId, title, uri, "open", nowIso(), nowIso());
}

function opcDefaultIntegrationRow(definition: OpcConnectorDefinition) {
  return {
    provider: definition.provider,
    status: "not_configured",
    mode: "dry_run",
    key_ref: definition.requiredKeyRef,
    credential_configured: 0,
    credential_hint: "只保存凭证引用，不保存密钥值",
    scopes: JSON.stringify(definition.scopes),
    last_error: "",
    capabilities: JSON.stringify({ officialApi: definition.officialApi, capabilities: definition.capabilities, liveWrites: definition.liveWrites }),
    notes: definition.note,
  };
}

function opcSyncConnectorDefinitions(projectId: string) {
  for (const definition of Object.values(opcConnectorDefinitions)) {
    const existing = db.prepare("SELECT * FROM opc_integration_accounts WHERE project_id = ? AND provider = ? LIMIT 1").get(projectId, definition.provider) as Record<string, unknown> | undefined;
    if (!existing) {
      opcInsertIfMissing("opc_integration_accounts", projectId, "provider", definition.provider, opcDefaultIntegrationRow(definition));
      continue;
    }
    const keyRef = String(existing.key_ref || "") || definition.requiredKeyRef;
    const scopes = String(existing.scopes || "") || JSON.stringify(definition.scopes);
    const capabilities = String(existing.capabilities || "") || JSON.stringify({ officialApi: definition.officialApi, capabilities: definition.capabilities, liveWrites: definition.liveWrites });
    const notes = String(existing.notes || "") || definition.note;
    db.prepare("UPDATE opc_integration_accounts SET key_ref = ?, scopes = ?, capabilities = ?, notes = ?, updated_at = ? WHERE project_id = ? AND provider = ?")
      .run(keyRef, scopes, capabilities, notes, nowIso(), projectId, definition.provider);
  }
}

