app.post("/api/macos-sync/run", async (req, reply) => {
  try {
    const startedAtMs = Date.now();
    const result = runWorkbenchMacosSync({ ...((req.body || {}) as Record<string, unknown>), trigger: "workbench_manual" });
    const body = (req.body || {}) as { apply?: boolean; scope?: string; mode?: string };
    const durationMs = Date.now() - startedAtMs;
    const resultStatus = (result as { status?: { stats?: { pending?: number; retryable?: number; blocked?: number; synced?: number; kindSummary?: { auth?: number; timeout?: number; upstream?: number } } } }).status || macosSyncStatus(db);
    const resultDetails = result as {
      pendingBefore?: number;
      pendingAfter?: number;
      kindSummary?: { auth?: number; timeout?: number; upstream?: number };
      todos?: { kindSummary?: { auth?: number; timeout?: number; upstream?: number } };
      events?: { kindSummary?: { auth?: number; timeout?: number; upstream?: number } };
      status?: { stats?: { kindSummary?: { auth?: number; timeout?: number; upstream?: number } } };
    };
    const stats = resultStatus.stats || {};
    const runOk = Boolean(result.ok);
    const runProcessed = Number((result as { processed?: unknown }).processed || 0);
    const runPendingBefore = Number((resultDetails.pendingBefore || 0));
    const runPendingAfter = Number((resultDetails.pendingAfter || 0));
    const runHasProgress = runProcessed > 0 || runPendingAfter < runPendingBefore;
    audit(db, "macos.sync.run", "macos_sync", null, result.ok ? "normal" : "high", {
      ok: result.ok,
      apply: Boolean(body.apply),
      scope: body.scope || "all",
      mode: body.mode || "push_pending",
      durationMs,
      processed: Number((result as { processed?: unknown }).processed || 0),
      failed: Number((result as { failed?: unknown }).failed || 0),
      pendingBefore: Number(resultDetails.pendingBefore || 0),
      pendingAfter: Number(resultDetails.pendingAfter || 0),
      remainingPending: Number((result as { remainingPending?: unknown }).remainingPending || 0),
      pending: Number((stats as { pending?: number }).pending || 0),
      retryable: Number((stats as { retryable?: number }).retryable || 0),
      blocked: Number((stats as { blocked?: number }).blocked || 0),
      synced: Number((stats as { synced?: number }).synced || 0),
      kindSummary: {
        auth: Number((resultDetails.kindSummary || {}).auth || stats.kindSummary?.auth || 0),
        timeout: Number((resultDetails.kindSummary || {}).timeout || stats.kindSummary?.timeout || 0),
        upstream: Number((resultDetails.kindSummary || {}).upstream || stats.kindSummary?.upstream || 0),
      },
      error: String((result as { error?: unknown; message?: unknown }).error || (result as { message?: unknown }).message || ""),
    });
    if (!runOk && !runHasProgress) return reply.code(400).send(result);
    return result;
  } catch (err) {
    return reply.code(400).send({ ok: false, error: sanitizePublicError(err instanceof Error ? err.message : String(err)) });
  }
});

