app.patch("/api/plan-items/:id", async (req, reply) => {
  const id = (req.params as { id: string }).id;
  const current = db.prepare("SELECT * FROM plan_items WHERE id = ?").get(id) as Record<string, unknown> | undefined;
  if (!current) return reply.code(404).send({ ok: false, error: "not_found" });
  const body = req.body as { title?: string; status?: string; priority?: string; dueAt?: string | null; agentId?: string | null; listName?: string; tags?: string[]; rawFields?: Record<string, string>; followed?: boolean };
  const title = body.title ?? String(current.title || "");
  const status = body.status ?? String(current.status || "open");
  const priority = body.priority ?? String(current.priority || "P2");
  const dueAt = body.dueAt !== undefined ? body.dueAt || null : (current.due_at as string | null) ?? null;
  const agentId = body.agentId !== undefined ? cleanAgentId(body.agentId) || null : (current.agent_id as string | null) ?? null;
  const listName = body.listName ?? String(current.list_name || "未分类");
  const tags = body.tags ? JSON.stringify(body.tags) : String(current.tags || "[]");
  const rawFields = body.rawFields ? JSON.stringify(body.rawFields) : String(current.raw_fields || "{}");
  const followed = body.followed !== undefined ? (body.followed ? 1 : 0) : Number(current.followed || 0);
  db.prepare("UPDATE plan_items SET title = ?, status = ?, priority = ?, due_at = ?, agent_id = ?, list_name = ?, tags = ?, raw_fields = ?, followed = ?, updated_at = ? WHERE id = ?")
    .run(title, status, priority, dueAt, agentId, listName, tags, rawFields, followed, nowIso(), id);
  const todoId = String(current.todo_id || "");
  if (todoId) {
    db.prepare("UPDATE todos SET title = ?, status = ?, priority = ?, due_at = ?, tags = ?, list_name = ?, agent_id = ?, updated_at = ? WHERE id = ?")
      .run(title, status, priority, dueAt, tags, listName, agentId, nowIso(), todoId);
    markTodoReminderSyncPending(db, todoId, listName);
    scheduleWorkbenchMacosSyncSoon();
  }
  return { ok: true, item: db.prepare("SELECT * FROM plan_items WHERE id = ?").get(id) };
});

app.get("/api/calendar", async (req, reply) => {
  const query = req.query as { start?: string; end?: string };
  const start = parseDateKey(query.start);
  const end = parseDateKey(query.end);
  if (!start || !end) return reply.code(400).send({ ok: false, error: "invalid_date_range" });
  const dayCount = daysBetweenInclusive(start, end);
  if (dayCount < 1 || dayCount > 370) return reply.code(400).send({ ok: false, error: "date_range_must_be_1_to_370_days" });
  const startKey = dateKeyFromUtc(start);
  const endKey = dateKeyFromUtc(end);
  const events = db.prepare(`
    SELECT e.*,
      l.status AS sync_status,
      l.external_calendar AS sync_external_calendar,
      l.external_id AS sync_external_id,
      l.last_synced_at AS sync_last_synced_at,
      l.error AS sync_error
    FROM events e
    LEFT JOIN event_sync_links l ON l.event_id = e.id AND l.provider = 'macos_calendar'
    WHERE substr(e.start_at, 1, 10) BETWEEN ? AND ?
    ORDER BY e.start_at ASC
  `).all(startKey, endKey);
  const todos = db.prepare("SELECT * FROM todos WHERE due_at IS NOT NULL AND substr(due_at, 1, 10) BETWEEN ? AND ? ORDER BY due_at ASC, priority ASC, updated_at DESC").all(startKey, endKey);
  const planItems = db.prepare("SELECT * FROM plan_items WHERE due_at IS NOT NULL AND substr(due_at, 1, 10) BETWEEN ? AND ? ORDER BY due_at ASC, priority ASC, updated_at DESC").all(startKey, endKey);
  syncCalendarKnowledgeFolderNotes(startKey, endKey);
  const notes = db.prepare("SELECT * FROM calendar_notes WHERE date_key BETWEEN ? AND ? ORDER BY date_key ASC, updated_at DESC").all(startKey, endKey)
    .map(enrichCalendarNoteRow);
  const reports = db.prepare("SELECT * FROM reports WHERE range_start IS NOT NULL AND substr(range_start, 1, 10) BETWEEN ? AND ? ORDER BY range_start ASC, updated_at DESC").all(startKey, endKey);
  const holidays = await chinaCalendarRange(startKey, endKey);
  return { ok: true, events, todos, planItems, notes, reports, holidays, range: { start: startKey, end: endKey, days: dayCount } };
});

type CalendarNoteBody = { date?: string; title?: string; content?: string; tags?: string[]; relatedType?: string; relatedId?: string };
type CalendarNoteLinkBody = CalendarNoteBody & {
  summary?: string;
  knowledgeEntryId?: string;
  knowledgePath?: string;
  knowledgeHtmlPath?: string;
};

function calendarNoteTags(tags: unknown, dateKey: string) {
  let input = Array.isArray(tags) ? tags.map(String) : [];
  if (!input.length && typeof tags === "string" && tags.trim()) {
    try {
      const parsed = JSON.parse(tags);
      input = Array.isArray(parsed) ? parsed.map(String) : tags.split(/[,，;；]/).map(String);
    } catch {
      input = tags.split(/[,，;；]/).map(String);
    }
  }
  return [...new Set(["日程笔记", dateKey, ...input.map((item) => item.trim()).filter(Boolean)])];
}

function calendarNoteRawContent(input: { dateKey: string; title: string; content: string; tags: string[]; relatedType?: string | null; relatedId?: string | null }) {
  return [
    `日期：${input.dateKey}`,
    `标题：${input.title}`,
    `标签：${input.tags.join("，")}`,
    input.relatedType || input.relatedId ? `关联对象：${input.relatedType || "object"} ${input.relatedId || ""}`.trim() : "",
    "",
    "## 原始记录",
    input.content || input.title,
  ].filter(Boolean).join("\n");
}

function calendarKnowledgeInput(body: CalendarNoteBody, existing?: Record<string, unknown>): KnowledgeNoteDraftInput & { relatedType?: string | null; relatedId?: string | null } {
  const dateKey = String(body.date || existing?.date_key || nowIso().slice(0, 10)).slice(0, 10);
  const title = String(body.title || existing?.title || "日程笔记").trim() || "日程笔记";
  const content = String(body.content ?? existing?.content ?? "").trim();
  const tags = calendarNoteTags(body.tags ?? existing?.tags, dateKey);
  const relatedType = body.relatedType ?? (existing?.related_type ? String(existing.related_type) : null);
  const relatedId = body.relatedId ?? (existing?.related_id ? String(existing.related_id) : null);
  return {
    rawContent: calendarNoteRawContent({ dateKey, title, content, tags, relatedType, relatedId }),
    title,
    date: dateKey,
    type: "工作记录",
    status: "进行中",
    tags,
    related: relatedType || relatedId ? [`${relatedType || "object"}:${relatedId || ""}`] : [],
    folder: `calendar/${dateKey.slice(0, 7)}`,
    htmlMode: "m3",
    relatedType,
    relatedId,
  };
}

function calendarNoteFailurePayload(err: unknown) {
  if (isKnowledgeNoteGatewayRequiredError(err)) {
    const details = knowledgeNoteFailureDetails(err.reason);
    return {
      statusCode: err.statusCode,
      payload: {
        ok: false,
        error: "gateway_model_required",
        stage: err.stage,
        reason: err.reason,
        reasonLabel: details.reasonLabel,
        retryable: details.retryable,
        advice: details.advice,
        generationPipeline: err.generationPipeline,
        knowledgeNotePipelineVersion: KNOWLEDGE_NOTE_PIPELINE_VERSION,
      },
    };
  }
  return {
    statusCode: 503,
    payload: {
      ok: false,
      error: "calendar_note_high_quality_failed",
      stage: "calendar_note_save",
      reason: err instanceof Error ? err.message : "note_create_failed",
      retryable: true,
      knowledgeNotePipelineVersion: KNOWLEDGE_NOTE_PIPELINE_VERSION,
    },
  };
}

function enrichCalendarNoteRow(row: unknown) {
  const note = row as Record<string, unknown>;
  const knowledgePath = String(note.knowledge_path || "");
  const knowledgeHtmlPath = String(note.knowledge_html_path || "");
  const isLegacySidecar = /knowledge_sidecars\/calendar_notes/.test(knowledgePath);
  const knowledgeStatus = knowledgeHtmlPath ? "linked" : knowledgePath && !isLegacySidecar ? "markdown_only" : "upgrade_required";
  return {
    ...note,
    knowledgePath,
    knowledgeHtmlPath,
    knowledgeStatus,
    summary: String(note.summary || note.content || "").slice(0, 500),
  };
}

function syncCalendarKnowledgeFolderNotes(startKey: string, endKey: string) {
  // 2026-07-08 (rework11) — root 改为 "notes/calendar" (NJX-knowledge v2 实际落点)
  // 2026-07-07 (rework10 v2) — 原本扫 "calendar" (老 path, NJX-knowledge v2 wiki MOC 路径)
  //     但 cron `笔记整理` v4 (2026-07-07) 实际写到 "notes/calendar/",两边错位导致整个 7 月
  //     每日笔记整合稿 sync 漏进 calendar_notes,智能助理页面看不到。
  // 修复:NJX-knowledge v2 路径 = "knowledge/notes/calendar/<YYYY-MM>/*.md"
  //      (跟 cron v4 实际写的路径对齐, 跟 save/mobile/manual add-note 落点一致)
  // 老路径 (knowledge/calendar) 仍是 wiki MOC 接入点, 由其他 sync 维护 (互不冲突)
  // 老 DB row (5/6 月, knowledge_path 老路径) 不动, 保留只读兼容
  const root = path.join(NJX_KNOWLEDGE_NOTES_ROOT, "notes", "calendar");
  if (!fs.existsSync(root)) return;
  const monthKeys = calendarMonthKeysInRange(startKey, endKey);
  const candidates = monthKeys.flatMap((monthKey) => listCalendarKnowledgeMarkdownFiles(path.join(root, monthKey)));
  for (const file of candidates) {
    try {
      const markdown = fs.readFileSync(file, "utf8");
      // dedupe by date_key + basename (兼容 path 迁移: 老路径 + 新路径同名 file 不重复 INSERT)
      const dateKeyFromFile = calendarDateFromKnowledgeFile(file);
      const basename = path.basename(file);
      const existing = dateKeyFromFile
        ? db.prepare("SELECT * FROM calendar_notes WHERE date_key = ? AND knowledge_path LIKE ? LIMIT 1").get(dateKeyFromFile, `%/${basename}`) as Record<string, unknown> | undefined
        : db.prepare("SELECT * FROM calendar_notes WHERE knowledge_path = ? LIMIT 1").get(file) as Record<string, unknown> | undefined;
      const title = calendarNoteTitleFromMarkdown(markdown, path.basename(file, ".md"));
      const summary = calendarNoteSummaryFromMarkdown(markdown, title);
      const htmlPath = calendarKnowledgeHtmlPath(file);
      const entry = db.prepare("SELECT * FROM knowledge_entries WHERE source_path = ? OR content_path = ? LIMIT 1").get(file, file) as Record<string, unknown> | undefined;
      const entryId = entry?.id ? String(entry.id) : "";
      const dateKey = calendarDateFromKnowledgeMarkdown(markdown, file) || calendarDateFromKnowledgeCreatedAt(file, entry);
      if (!dateKey || dateKey < startKey || dateKey > endKey) continue;
      const tags = calendarNoteTags(["知识库导入"], dateKey);
      const now = nowIso();
      if (existing) {
        const needsUpdate = String(existing.date_key || "") !== dateKey
          || String(existing.title || "") !== title
          || !String(existing.summary || "")
          || String(existing.knowledge_html_path || "") !== htmlPath
          || String(existing.knowledge_entry_id || "") !== String(entryId || existing.knowledge_entry_id || "");
        if (needsUpdate) {
          db.prepare("UPDATE calendar_notes SET date_key = ?, title = ?, summary = ?, content = ?, tags = ?, knowledge_entry_id = ?, knowledge_html_path = ?, related_type = ?, related_id = ?, updated_at = ? WHERE id = ?")
            .run(dateKey, title, summary, markdown.slice(0, 6000), JSON.stringify(tags), entryId || String(existing.knowledge_entry_id || "") || null, htmlPath || String(existing.knowledge_html_path || "") || null, "knowledge_calendar_file", entryId || file, now, String(existing.id || ""));
        }
        continue;
      }
      const id = randomUUID();
      db.prepare("INSERT INTO calendar_notes (id, date_key, title, summary, content, tags, knowledge_entry_id, knowledge_path, knowledge_html_path, related_type, related_id, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
        .run(id, dateKey, title, summary, markdown.slice(0, 6000), JSON.stringify(tags), entryId || null, file, htmlPath || null, "knowledge_calendar_file", entryId || file, now, now);
    } catch (err) {
      app.log.warn({ err, file }, "calendar knowledge note sync failed");
    }
  }
}

function calendarMonthKeysInRange(startKey: string, endKey: string) {
  const keys: string[] = [];
  const cursor = new Date(`${startKey.slice(0, 7)}-01T00:00:00Z`);
  const end = new Date(`${endKey.slice(0, 7)}-01T00:00:00Z`);
  while (cursor <= end && keys.length < 14) {
    keys.push(cursor.toISOString().slice(0, 7));
    cursor.setUTCMonth(cursor.getUTCMonth() + 1);
  }
  return keys;
}

function listCalendarKnowledgeMarkdownFiles(dir: string) {
  if (!fs.existsSync(dir)) return [] as string[];
  const files: string[] = [];
  const stack = [dir];
  while (stack.length) {
    const current = stack.pop();
    if (!current) continue;
    for (const entry of fs.readdirSync(current, { withFileTypes: true })) {
      if (entry.name.startsWith(".")) continue;
      const full = path.join(current, entry.name);
      if (entry.isDirectory()) stack.push(full);
      else if (entry.isFile() && entry.name.toLowerCase().endsWith(".md")) files.push(full);
    }
  }
  return files;
}

function calendarDateFromKnowledgeFile(file: string) {
  const normalized = file.replace(/\\/g, "/");
  const exact = normalized.match(/(\d{4})-(\d{2})-(\d{2})/);
  if (exact) return `${exact[1]}-${exact[2]}-${exact[3]}`;
  const compact = normalized.match(/(?:^|\/)(\d{4})(\d{2})(\d{2})[^/]*\.md$/);
  if (compact) return `${compact[1]}-${compact[2]}-${compact[3]}`;
  return "";
}

function calendarDateFromKnowledgeMarkdown(markdown: string, file: string) {
  const frontmatter = markdown.match(/^---\s*([\s\S]*?)\n---/m)?.[1] || "";
  const fromMetadata = frontmatter.match(/^date:\s*["']?(\d{4}-\d{2}-\d{2})/m)?.[1]
    || frontmatter.match(/^created:\s*["']?(\d{4}-\d{2}-\d{2})/m)?.[1];
  return fromMetadata || calendarDateFromKnowledgeFile(file);
}

function calendarDateFromKnowledgeCreatedAt(file: string, entry?: Record<string, unknown>) {
  const entryCreatedRaw = String(entry?.created_at || entry?.createdAt || "");
  if (/^\d{4}-\d{2}-\d{2}$/.test(entryCreatedRaw)) return entryCreatedRaw;
  const entryCreated = entryCreatedRaw ? new Date(entryCreatedRaw) : null;
  if (entryCreated && Number.isFinite(entryCreated.getTime())) return formatLocalCalendarDate(entryCreated);
  try {
    const stat = fs.statSync(file);
    const created = Number.isFinite(stat.birthtimeMs) && stat.birthtimeMs > 946684800000 ? stat.birthtime : stat.mtime;
    return formatLocalCalendarDate(created);
  } catch {
    return "";
  }
}

function formatLocalCalendarDate(date: Date) {
  const pad = (value: number) => String(value).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

function stripMarkdownFrontmatter(markdown: string) {
  return markdown.replace(/^---\s*[\s\S]*?\n---\s*/m, "").trim();
}

function calendarNoteTitleFromMarkdown(markdown: string, fallback: string) {
  const titleMeta = markdown.match(/^title:\s*["']?(.+?)["']?\s*$/m);
  const title = titleMeta?.[1] || stripMarkdownFrontmatter(markdown).split(/\r?\n/).find((line) => /^#\s+/.test(line)) || fallback;
  return cleanCalendarNoteText(title, fallback, 70);
}

function calendarNoteSummaryFromMarkdown(markdown: string, title: string) {
  const body = stripMarkdownFrontmatter(markdown)
    .split(/\r?\n/)
    .filter((line) => !/^#\s+/.test(line.trim()))
    .join(" ");
  return cleanCalendarNoteText(body, title, 420);
}

function cleanCalendarNoteText(value: string, fallback: string, limit: number) {
  const text = String(value || "")
    .replace(/^#+\s*/gm, "")
    .replace(/!\[[^\]]*]\([^)]+\)/g, "")
    .replace(/\[[^\]]+]\([^)]+\)/g, (match) => match.replace(/^\[|\]\([^)]+\)$/g, ""))
    .replace(/[`*_>|-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  const compact = text || fallback || "日程笔记";
  return compact.length > limit ? `${compact.slice(0, limit - 1)}…` : compact;
}

function calendarKnowledgeHtmlPath(markdownPath: string) {
  const sibling = markdownPath.replace(/\.md$/i, ".html");
  if (fs.existsSync(sibling)) return sibling;
  const render = db.prepare("SELECT html_path FROM document_renders WHERE source_path = ? AND render_status = 'completed' ORDER BY updated_at DESC LIMIT 1").get(markdownPath) as { html_path?: string } | undefined;
  return render?.html_path || "";
}

function safeCalendarActivityRows(sql: string, ...params: string[]) {
  try {
    return db.prepare(sql).all(...params) as Record<string, unknown>[];
  } catch {
    return [];
  }
}

function activityLine(row: Record<string, unknown>, fields: Array<[string, string]>) {
  return fields
    .map(([label, key]) => {
      const value = row[key];
      if (value === null || value === undefined || value === "") return "";
      const text = typeof value === "string" ? value : JSON.stringify(value);
      return `${label}:${text.replace(/\s+/g, " ").slice(0, 180)}`;
    })
    .filter(Boolean)
    .join("；");
}

function activitySection(title: string, rows: Record<string, unknown>[], fields: Array<[string, string]>, empty = "无") {
  if (!rows.length) return [`## ${title}`, empty].join("\n");
  return [`## ${title}`, ...rows.slice(0, 40).map((row, index) => `- ${index + 1}. ${activityLine(row, fields) || JSON.stringify(row).slice(0, 240)}`)].join("\n");
}

function dailyWorkspaceActivityInput(dateKey: string, notes = "") {
  const todos = safeCalendarActivityRows(`
    SELECT id, title, status, priority, due_at, agent_id, list_name, tags, notes, updated_at
    FROM todos
    WHERE substr(COALESCE(due_at, updated_at, created_at), 1, 10) = ?
      OR substr(updated_at, 1, 10) = ?
    ORDER BY COALESCE(due_at, updated_at) ASC
  `, dateKey, dateKey);
  const events = safeCalendarActivityRows(`
    SELECT id, title, start_at, end_at, event_type, notes, updated_at
    FROM events
    WHERE substr(start_at, 1, 10) = ? OR substr(updated_at, 1, 10) = ?
    ORDER BY start_at ASC
  `, dateKey, dateKey);
  const planItems = safeCalendarActivityRows(`
    SELECT id, plan_type, title, status, priority, due_at, agent_id, list_name, tags, raw_fields, updated_at
    FROM plan_items
    WHERE substr(COALESCE(due_at, updated_at, created_at), 1, 10) = ?
      OR substr(updated_at, 1, 10) = ?
    ORDER BY plan_type ASC, COALESCE(due_at, updated_at) ASC
  `, dateKey, dateKey);
  const calendarNotes = safeCalendarActivityRows(`
    SELECT id, title, summary, tags, knowledge_path, knowledge_html_path, updated_at
    FROM calendar_notes
    WHERE date_key = ?
    ORDER BY updated_at DESC
  `, dateKey);
  const reports = safeCalendarActivityRows(`
    SELECT id, report_type, title, status, range_start, range_end, content, html_path, updated_at
    FROM reports
    WHERE substr(COALESCE(range_start, updated_at, created_at), 1, 10) = ?
      OR substr(updated_at, 1, 10) = ?
    ORDER BY updated_at DESC
  `, dateKey, dateKey);
  const projects = safeCalendarActivityRows(`
    SELECT id, name, status, objective, description, progress, updated_at
    FROM projects
    WHERE substr(updated_at, 1, 10) = ? OR substr(created_at, 1, 10) = ?
    ORDER BY updated_at DESC
  `, dateKey, dateKey);
  const tasks = safeCalendarActivityRows(`
    SELECT id, title, status, priority, agent_id, risk_level, description, output, updated_at
    FROM tasks
    WHERE substr(updated_at, 1, 10) = ? OR substr(created_at, 1, 10) = ?
    ORDER BY updated_at DESC
  `, dateKey, dateKey);
  const taskEvents = safeCalendarActivityRows(`
    SELECT task_id, event_type, actor, message, created_at
    FROM task_events
    WHERE substr(created_at, 1, 10) = ?
    ORDER BY created_at DESC
  `, dateKey);
  const workbenchEvents = safeCalendarActivityRows(`
    SELECT source_type, source_id, agent_id, event_type, severity, message, created_at
    FROM workbench_events
    WHERE substr(created_at, 1, 10) = ?
    ORDER BY created_at DESC
  `, dateKey);
  const automationRuns = safeCalendarActivityRows(`
    SELECT action, status, mode, risk_level, summary, updated_at, created_at
    FROM opc_automation_runs
    WHERE substr(updated_at, 1, 10) = ? OR substr(created_at, 1, 10) = ?
    ORDER BY updated_at DESC
  `, dateKey, dateKey);
  const syncRuns = safeCalendarActivityRows(`
    SELECT provider, status, mode, records_read, records_written, message, created_at
    FROM opc_sync_runs
    WHERE substr(created_at, 1, 10) = ?
    ORDER BY created_at DESC
  `, dateKey);
  const approvals = safeCalendarActivityRows(`
    SELECT action, status, requested_at, resolved_at, details
    FROM approvals
    WHERE substr(requested_at, 1, 10) = ? OR substr(COALESCE(resolved_at, requested_at), 1, 10) = ?
    ORDER BY requested_at DESC
  `, dateKey, dateKey);
  const openTodos = todos.filter((row) => String(row.status || "") !== "done").length;
  const doneTodos = todos.filter((row) => String(row.status || "") === "done").length;
  return [
    `# 日报 ${dateKey}`,
    "",
    "这是一份由 OpenClaw Workbench 自动汇总的日程知识笔记，覆盖当日待办、计划、项目、系统开发、自动化、报告和既有笔记。",
    "",
    "## 当日概览",
    `- 日期：${dateKey}`,
    `- 待办：${todos.length} 项（未完成 ${openTodos}，已完成 ${doneTodos}）`,
    `- 日程：${events.length} 项`,
    `- 计划项：${planItems.length} 项`,
    `- 项目更新：${projects.length} 项`,
    `- 系统开发任务：${tasks.length} 项，事件 ${taskEvents.length + workbenchEvents.length} 条`,
    `- 自动化：运行 ${automationRuns.length} 条，同步 ${syncRuns.length} 条，审批 ${approvals.length} 条`,
    `- 日程笔记：${calendarNotes.length} 条，已有报告 ${reports.length} 条`,
    notes.trim() ? `- 人工补充：${notes.trim()}` : "",
    "",
    activitySection("当日待办", todos, [["标题", "title"], ["状态", "status"], ["优先级", "priority"], ["截止", "due_at"], ["负责人", "agent_id"], ["分类", "list_name"], ["备注/反馈", "notes"]]),
    "",
    activitySection("日程与会议", events, [["标题", "title"], ["开始", "start_at"], ["结束", "end_at"], ["类型", "event_type"], ["备注", "notes"]]),
    "",
    activitySection("五年人生规划与年度工作计划", planItems, [["类型", "plan_type"], ["标题", "title"], ["状态", "status"], ["优先级", "priority"], ["截止", "due_at"], ["负责人", "agent_id"], ["分类", "list_name"], ["原表字段", "raw_fields"]]),
    "",
    activitySection("项目动态", projects, [["项目", "name"], ["状态", "status"], ["目标", "objective"], ["进度", "progress"], ["描述", "description"], ["更新", "updated_at"]]),
    "",
    activitySection("系统开发任务", tasks, [["标题", "title"], ["状态", "status"], ["优先级", "priority"], ["代理", "agent_id"], ["风险", "risk_level"], ["描述", "description"], ["输出", "output"]]),
    "",
    activitySection("系统事件", [...taskEvents, ...workbenchEvents], [["时间", "created_at"], ["类型", "event_type"], ["代理", "actor"], ["来源", "source_type"], ["级别", "severity"], ["消息", "message"]]),
    "",
    activitySection("自动化与同步", [...automationRuns, ...syncRuns, ...approvals], [["动作", "action"], ["供应商", "provider"], ["状态", "status"], ["模式", "mode"], ["风险", "risk_level"], ["摘要", "summary"], ["消息", "message"], ["审批", "details"]]),
    "",
    activitySection("已有日程笔记与报告", [...calendarNotes, ...reports], [["标题", "title"], ["类型", "report_type"], ["状态", "status"], ["摘要", "summary"], ["路径", "knowledge_path"], ["HTML", "knowledge_html_path"], ["报告HTML", "html_path"]]),
    "",
    "## 复盘要求",
    "- 提炼今天真正推进的结果，不只罗列事项。",
    "- 识别风险、阻塞和需要人工确认的动作。",
    "- 给出明天最小可执行清单，并标注负责人和优先级。",
  ].filter(Boolean).join("\n");
}

async function createHighQualityCalendarNote(body: CalendarNoteBody, existing?: Record<string, unknown>) {
  const input = calendarKnowledgeInput(body, existing);
  const organized = await organizeKnowledgeNoteDraftHighQuality({ ...input, qualityMode: "minimax-direct", gatewayTimeoutMs: 300_000 });
  const saved = await saveKnowledgeNote(db, {
    ...input,
    ...organized.draft,
    rawContent: input.rawContent,
    folder: input.folder,
    markdown: organized.draft.markdown,
    layoutStrategy: organized.layoutStrategy,
    htmlDraft: organized.htmlDraft,
    htmlQuality: organized.htmlQuality,
    generationPipeline: organized.generationPipeline,
    htmlMode: "m3",
  });
  const entry = db.prepare("SELECT * FROM knowledge_entries WHERE id = ?").get(saved.entryId) as Record<string, unknown> | undefined;
  return { input, organized, saved, entry };
}

app.post("/api/calendar/notes", async (req, reply) => {
  const body = req.body as CalendarNoteBody;
  try {
    const { input, saved, entry } = await createHighQualityCalendarNote(body);
    const id = randomUUID();
    const dateKey = String(input.date || nowIso().slice(0, 10)).slice(0, 10);
    const title = String((entry?.title || saved.title || input.title || "日程笔记")).replace(new RegExp(`^${dateKey}\\s+`), "");
    const summary = String(entry?.summary || input.rawContent || "").slice(0, 500);
    const createdAt = nowIso();
    db.prepare("INSERT INTO calendar_notes (id, date_key, title, summary, content, tags, knowledge_entry_id, knowledge_path, knowledge_html_path, related_type, related_id, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
      .run(id, dateKey, title, summary, String(body.content || ""), JSON.stringify(input.tags || []), saved.entryId, saved.path, saved.htmlPath, input.relatedType || null, input.relatedId || null, createdAt, createdAt);
    audit(db, "calendar.note.create", "calendar_note", id, "normal", { entryId: saved.entryId, dateKey, htmlPath: saved.htmlPath, pipeline: saved.htmlQuality ? "m3-html" : "unknown" });
    return { ok: true, note: enrichCalendarNoteRow(db.prepare("SELECT * FROM calendar_notes WHERE id = ?").get(id)), knowledgeEntry: entry, htmlPath: saved.htmlPath };
  } catch (err) {
    const failure = calendarNoteFailurePayload(err);
    audit(db, "calendar.note.create.failed", "calendar_note", null, "warn", failure.payload);
    return reply.code(failure.statusCode).send(failure.payload);
  }
});

app.post("/api/calendar/notes/link", async (req, reply) => {
  const body = req.body as CalendarNoteLinkBody;
  const dateKey = String(body.date || nowIso().slice(0, 10)).slice(0, 10);
  const knowledgePath = String(body.knowledgePath || "").trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dateKey)) return reply.code(400).send({ ok: false, error: "invalid_date" });
  if (!knowledgePath) return reply.code(400).send({ ok: false, error: "knowledge_path_required" });
  const entry = body.knowledgeEntryId
    ? db.prepare("SELECT * FROM knowledge_entries WHERE id = ?").get(body.knowledgeEntryId) as Record<string, unknown> | undefined
    : db.prepare("SELECT * FROM knowledge_entries WHERE source_path = ? OR content_path = ? LIMIT 1").get(knowledgePath, knowledgePath) as Record<string, unknown> | undefined;
  const htmlPath = String(body.knowledgeHtmlPath || "");
  const tags = calendarNoteTags(body.tags, dateKey);
  const title = String(entry?.title || body.title || path.basename(knowledgePath, path.extname(knowledgePath)) || "日程笔记")
    .replace(new RegExp(`^${dateKey}\\s+`), "")
    .trim() || "日程笔记";
  const summary = String(body.summary || entry?.summary || body.content || title).slice(0, 500);
  const entryId = body.knowledgeEntryId || (entry?.id ? String(entry.id) : null);
  const id = randomUUID();
  const createdAt = nowIso();
  db.prepare("INSERT INTO calendar_notes (id, date_key, title, summary, content, tags, knowledge_entry_id, knowledge_path, knowledge_html_path, related_type, related_id, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
    .run(id, dateKey, title, summary, String(body.content || summary || ""), JSON.stringify(tags), entryId, knowledgePath, htmlPath || null, body.relatedType || "knowledge_note", body.relatedId || entryId, createdAt, createdAt);
  audit(db, "calendar.note.link", "calendar_note", id, "normal", { entryId, dateKey, knowledgePath, htmlPath });
  return { ok: true, note: enrichCalendarNoteRow(db.prepare("SELECT * FROM calendar_notes WHERE id = ?").get(id)), knowledgeEntry: entry || null, htmlPath };
});

app.post("/api/calendar/notes/daily-report", async (req, reply) => {
  const body = req.body as { date?: string; notes?: string };
  const dateKey = String(body.date || nowIso().slice(0, 10)).slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dateKey)) return reply.code(400).send({ ok: false, error: "invalid_date" });
  try {
    const content = dailyWorkspaceActivityInput(dateKey, String(body.notes || ""));
    const { input, saved, entry } = await createHighQualityCalendarNote({
      date: dateKey,
      title: `日报 ${dateKey}`,
      content,
      tags: ["日报", "日程笔记", "工作区活动", dateKey],
      relatedType: "daily_report",
      relatedId: dateKey,
    });
    const id = randomUUID();
    const createdAt = nowIso();
    const title = String(entry?.title || saved.title || `日报 ${dateKey}`).replace(new RegExp(`^${dateKey}\\s+`), "").trim() || `日报 ${dateKey}`;
    const summary = String(entry?.summary || input.rawContent || content).slice(0, 500);
    db.prepare("INSERT INTO calendar_notes (id, date_key, title, summary, content, tags, knowledge_entry_id, knowledge_path, knowledge_html_path, related_type, related_id, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
      .run(id, dateKey, title, summary, content, JSON.stringify(input.tags || []), saved.entryId, saved.path, saved.htmlPath, "daily_report", dateKey, createdAt, createdAt);
    audit(db, "calendar.note.daily_report", "calendar_note", id, "normal", { entryId: saved.entryId, dateKey, htmlPath: saved.htmlPath, pipeline: "m3-html" });
    return { ok: true, note: enrichCalendarNoteRow(db.prepare("SELECT * FROM calendar_notes WHERE id = ?").get(id)), knowledgeEntry: entry, htmlPath: saved.htmlPath };
  } catch (err) {
    const failure = calendarNoteFailurePayload(err);
    audit(db, "calendar.note.daily_report.failed", "calendar_note", null, "warn", { dateKey, ...failure.payload });
    return reply.code(failure.statusCode).send(failure.payload);
  }
});

app.post("/api/calendar/notes/:id/upgrade", async (req, reply) => {
  const id = (req.params as { id: string }).id;
  const current = db.prepare("SELECT * FROM calendar_notes WHERE id = ?").get(id) as Record<string, unknown> | undefined;
  if (!current) return reply.code(404).send({ ok: false, error: "not_found" });
  try {
    const { input, saved, entry } = await createHighQualityCalendarNote(req.body as CalendarNoteBody, current);
    const title = String((entry?.title || saved.title || input.title || current.title || "日程笔记")).replace(new RegExp(`^${String(input.date).slice(0, 10)}\\s+`), "");
    const summary = String(entry?.summary || input.rawContent || "").slice(0, 500);
    db.prepare("UPDATE calendar_notes SET title = ?, summary = ?, content = ?, tags = ?, knowledge_entry_id = ?, knowledge_path = ?, knowledge_html_path = ?, related_type = ?, related_id = ?, updated_at = ? WHERE id = ?")
      .run(title, summary, String(input.rawContent || current.content || ""), JSON.stringify(input.tags || []), saved.entryId, saved.path, saved.htmlPath, input.relatedType || null, input.relatedId || null, nowIso(), id);
    audit(db, "calendar.note.upgrade", "calendar_note", id, "normal", { entryId: saved.entryId, htmlPath: saved.htmlPath });
    return { ok: true, note: enrichCalendarNoteRow(db.prepare("SELECT * FROM calendar_notes WHERE id = ?").get(id)), knowledgeEntry: entry, htmlPath: saved.htmlPath };
  } catch (err) {
    const failure = calendarNoteFailurePayload(err);
    audit(db, "calendar.note.upgrade.failed", "calendar_note", id, "warn", failure.payload);
    return reply.code(failure.statusCode).send(failure.payload);
  }
});

