app.post("/api/opc/projects/:id/autopilot/policies", async (req, reply) => {
  const projectId = (req.params as { id: string }).id;
  if (!opcProjectOrReply(projectId)) return reply.code(404).send({ ok: false, error: "not_found" });
  const body = req.body as Record<string, unknown>;
  const current = db.prepare("SELECT * FROM opc_automation_policies WHERE project_id = ?").get(projectId) as Record<string, unknown> | undefined;
  const mode = ["dry_run", "live"].includes(String(body.mode || current?.mode)) ? String(body.mode || current?.mode) : "dry_run";
  const budgetUsd = body.budget_usd === undefined ? opcNumber(current?.budget_usd, 3289) : opcNumber(body.budget_usd, 3289);
  const fxRate = body.fx_rate === undefined ? opcNumber(current?.fx_rate, OPC_FX_RATE) : opcNumber(body.fx_rate, OPC_FX_RATE);
  const budgetCny = body.budget_cny === undefined ? budgetUsd * fxRate : opcNumber(body.budget_cny, budgetUsd * fxRate);
  const actions = body.actions_json ?? body.actions ?? current?.actions_json ?? { sync: true, sku: true, purchase: true, fulfillment: true, ads: true, support: "draft_only", reports: true, risk_review: true };
  const pauseRules = body.pause_rules_json ?? body.pauseRules ?? current?.pause_rules_json ?? { maxBudgetUsd: budgetUsd, minRoas: 1.5, pauseOnComplianceRisk: true, pauseOnMissingConnector: true, maxRetry: 2 };
  if (current) {
    db.prepare("UPDATE opc_automation_policies SET mode = ?, budget_usd = ?, budget_cny = ?, fx_rate = ?, actions_json = ?, pause_rules_json = ?, status = ?, updated_at = ? WHERE project_id = ?")
      .run(mode, budgetUsd, budgetCny, fxRate, opcJsonText(actions, {}), opcJsonText(pauseRules, {}), opcText(body.status, String(current.status || "active")), nowIso(), projectId);
  } else {
    db.prepare("INSERT INTO opc_automation_policies (id, project_id, mode, budget_usd, budget_cny, fx_rate, actions_json, pause_rules_json, status, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
      .run(randomUUID(), projectId, mode, budgetUsd, budgetCny, fxRate, opcJsonText(actions, {}), opcJsonText(pauseRules, {}), opcText(body.status, "active"), nowIso(), nowIso());
  }
  db.prepare("UPDATE opc_profiles SET mode = ?, updated_at = ? WHERE project_id = ?").run(mode, nowIso(), projectId);
  audit(db, "opc.policy.update", "project", projectId, mode === "live" ? "high" : "normal", { mode, budgetUsd });
  return { ok: true, dashboard: opcDashboard(projectId) };
});

