app.post("/api/opc/projects/:id/approvals/:approvalId/resolve", async (req, reply) => {
  const { id: projectId, approvalId } = req.params as { id: string; approvalId: string };
  if (!opcProjectOrReply(projectId)) return reply.code(404).send({ ok: false, error: "not_found" });
  const body = (req.body || {}) as { decision?: "approved" | "rejected"; note?: string };
  if (!["approved", "rejected"].includes(String(body.decision))) return reply.code(400).send({ ok: false, error: "invalid_decision" });
  const result = opcResolveApproval(projectId, approvalId, body.decision as "approved" | "rejected", body.note || "");
  if (!result.ok) return reply.code(result.error === "not_found" ? 404 : 400).send(result);
  return result;
});

