app.patch("/api/todos/:id", async (req) => {
  const id = (req.params as { id: string }).id;
  const current = db.prepare("SELECT * FROM todos WHERE id = ?").get(id) as { title: string; status: string; priority: string; due_at?: string | null; tags?: string; list_name?: string; agent_id?: string | null; notes?: string; reminder_sent_at?: string | null; reminder_inbox_id?: string | null; reminder_push_status?: string | null; reminder_push_error?: string | null } | undefined;
  if (!current) return { ok: false, error: "not_found" };
  const body = req.body as { title?: string; status?: string; priority?: string; dueAt?: string | null; tags?: string[]; listName?: string; agentId?: string | null; notes?: string; recordType?: "note" | "feedback"; recordText?: string };
  const nextDueAt = body.dueAt !== undefined ? body.dueAt || null : current.due_at ?? null;
  const nextStatus = body.status || current.status;
  const nextAgentId = body.agentId !== undefined ? cleanAgentId(body.agentId) || null : current.agent_id ?? null;
  let nextNotes = body.notes ?? current.notes ?? "";
  if (body.recordText?.trim()) nextNotes = appendTodoRecord(nextNotes, body.recordType === "feedback" ? "反馈" : "备注", body.recordText);
  const reminderShouldReset =
    (body.dueAt !== undefined && String(nextDueAt || "") !== String(current.due_at || "")) ||
    (body.agentId !== undefined && String(nextAgentId || "") !== String(current.agent_id || "")) ||
    (body.status !== undefined && isOpenStatus(nextStatus) && !isOpenStatus(current.status));
  const reminderSentAt = reminderShouldReset ? null : current.reminder_sent_at ?? null;
  const reminderInboxId = reminderShouldReset ? null : current.reminder_inbox_id ?? null;
  const reminderPushStatus = reminderShouldReset ? null : current.reminder_push_status ?? null;
  const reminderPushError = reminderShouldReset ? null : current.reminder_push_error ?? null;
  db.prepare("UPDATE todos SET title = ?, status = ?, priority = ?, due_at = ?, tags = ?, list_name = ?, agent_id = ?, notes = ?, reminder_sent_at = ?, reminder_inbox_id = ?, reminder_push_status = ?, reminder_push_error = ?, updated_at = ? WHERE id = ?")
    .run(body.title || current.title, nextStatus, body.priority || current.priority, nextDueAt, body.tags ? JSON.stringify(body.tags) : current.tags || "[]", body.listName || current.list_name || "work", nextAgentId, nextNotes, reminderSentAt, reminderInboxId, reminderPushStatus, reminderPushError, nowIso(), id);
  markTodoReminderSyncPending(db, id, body.listName || current.list_name || "work");
  scheduleWorkbenchMacosSyncSoon();
  return { ok: true, todo: db.prepare("SELECT * FROM todos WHERE id = ?").get(id) };
});

