app.patch("/api/reports/schedules/:type", async (req, reply) => {
  const type = (req.params as { type: string }).type;
  if (!["daily", "weekly", "monthly", "yearly"].includes(type)) return reply.code(400).send({ ok: false, error: "invalid_report_type" });
  ensureDefaultReportSchedules();
  const current = db.prepare("SELECT * FROM report_schedules WHERE report_type = ?").get(type) as Record<string, unknown> | undefined;
  const body = req.body as { enabled?: boolean; timeOfDay?: string; templateId?: string | null; sources?: string[] };
  const enabled = body.enabled !== undefined ? (body.enabled ? 1 : 0) : Number(current?.enabled || 0);
  const timeOfDay = /^\d{2}:\d{2}$/.test(String(body.timeOfDay || "")) ? String(body.timeOfDay) : String(current?.time_of_day || "18:00");
  const templateId: string | null = body.templateId !== undefined ? body.templateId || null : current?.template_id ? String(current.template_id) : null;
  const sources = body.sources ? JSON.stringify(body.sources) : String(current?.sources || JSON.stringify(defaultReportSources()));
  db.prepare("UPDATE report_schedules SET enabled = ?, time_of_day = ?, template_id = ?, sources = ?, updated_at = ? WHERE report_type = ?")
    .run(enabled, timeOfDay, templateId, sources, nowIso(), type);
  return { ok: true, schedule: db.prepare("SELECT * FROM report_schedules WHERE report_type = ?").get(type) };
});

