app.post("/api/computer-use/wechat/prepare", async (req, reply) => {
  const body = req.body as { recipientName?: string; recipient?: string; message?: string; text?: string };
  const recipientName = String(body.recipientName || body.recipient || "").trim();
  const message = String(body.message || body.text || "").trim();
  if (!recipientName) return reply.code(400).send({ ok: false, error: "recipient_required" });
  if (!message) return reply.code(400).send({ ok: false, error: "message_required" });
  const prepare = computerUseWechatPrepare(recipientName, message) as Record<string, unknown>;
  if (prepare.ok !== true) {
    audit(db, "computer_use.wechat_prepare_failed", "computer_use", recipientName, "high", {
      recipientName,
      messageHash: createHash("sha256").update(message).digest("hex").slice(0, 16),
      prepare,
    });
    return reply.code(409).send({ ok: false, error: "recipient_verification_failed", prepare });
  }
  const approvalId = randomUUID();
  const details = {
    source: "computer_use_wechat_prepare",
    recipientName,
    message,
    messageLength: message.length,
    messageHash: String(prepare.messageHash || createHash("sha256").update(message).digest("hex").slice(0, 16)),
    messagePreview: message.slice(0, 80),
    verifiedRecipientTitle: prepare.verifiedRecipientTitle || prepare.currentChatTitle || "",
    selectedScreenshotPath: prepare.selectedScreenshotPath || "",
    safeBehavior: prepare.safeBehavior || "message_not_typed_or_sent",
    execution: "not_sent_prepare_only",
  };
  db.prepare("INSERT INTO approvals (id, task_id, action, status, requested_at, details) VALUES (?, ?, ?, ?, ?, ?)")
    .run(approvalId, null, "wechat_send_message", "pending", nowIso(), JSON.stringify(details));
  audit(db, "computer_use.wechat_prepare", "approval", approvalId, "high", details);
  notify("warn", "微信外发待审批", `${recipientName} 的微信消息已完成收件人验证，等待人工审批`, "system");
  return { ok: true, approval: db.prepare("SELECT * FROM approvals WHERE id = ?").get(approvalId), prepare };
});

app.get("/api/config-review/html", async (req, reply) => {
  const review = await buildConfigReview();
  const title = `OpenClaw 系统配置评审 ${nowIso().slice(0, 10)}`;
  const markdown = `# ${title}\n\n## 摘要\n\n本 HTML 是系统配置评审的人机交互层；真实数据来自 Workbench API、OpenClaw Gateway/CLI 与本地文件系统探测。\n\n## 配置评审 JSON\n\n\`\`\`json\n${JSON.stringify(review, null, 2)}\n\`\`\`\n`;
  const folder = path.join(SIDECAR_DIR, "system_reviews", nowIso().slice(0, 10));
  fs.mkdirSync(folder, { recursive: true });
  const markdownPath = path.join(folder, `${safeName(title)}.md`);
  const htmlPath = path.join(folder, `${safeName(title)}.html`);
  fs.writeFileSync(markdownPath, markdown, "utf8");
  const render = writeHtmlDocument(markdown, htmlPath, { title, sourcePath: markdownPath, documentType: "system_config_review" });
  db.prepare("INSERT INTO document_renders (id, source_path, html_path, source_hash, render_status, document_type, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)")
    .run(randomUUID(), markdownPath, render.htmlPath, render.sourceHash, "fresh", "system_config_review", nowIso(), nowIso());
  audit(db, "config_review.render_html", "system", "config-review", "normal", { markdownPath, htmlPath });
  reply.header("Content-Security-Policy", "default-src 'none'; style-src 'unsafe-inline'; img-src 'self' data:; font-src 'self'; base-uri 'none'; form-action 'none'");
  return reply.type("text/html; charset=utf-8").send(fs.readFileSync(htmlPath, "utf8"));
});

app.get("/api/events", async (req, reply) => {
  reply.hijack();
  reply.raw.writeHead(200, {
    "Content-Type": "text/event-stream; charset=utf-8",
    "Cache-Control": "no-cache, no-transform",
    Connection: "keep-alive",
  });
  let closed = false;
  const send = () => {
    const payload = {
      ts: nowIso(),
      overview: {
        tasks: db.prepare("SELECT status, COUNT(*) count FROM tasks WHERE title NOT LIKE 'PRD11_TEST_%' GROUP BY status").all(),
        notifications: db.prepare("SELECT * FROM notifications ORDER BY created_at DESC LIMIT 5").all(),
      },
      knowledge: knowledgeLiveSnapshot(),
      gateway: liveGatewayHealthSnapshot(),
    };
    reply.raw.write(`event: snapshot\ndata: ${JSON.stringify(payload)}\n\n`);
  };
  const refreshGateway = async () => {
    await refreshLiveGatewayHealth({ source: "gateway:sse_health", timeoutMs: LIVE_GATEWAY_HEALTH_TIMEOUT_MS });
    if (!closed) send();
  };
  send();
  void refreshGateway();
  const timer = setInterval(() => {
    send();
    void refreshGateway();
  }, 5000);
  req.raw.on("close", () => {
    closed = true;
    clearInterval(timer);
  });
});

