function readJsonPath(file: string): Record<string, any> | null {
  try {
    if (!fs.existsSync(file)) return null;
    return JSON.parse(fs.readFileSync(file, "utf8")) as Record<string, any>;
  } catch {
    return null;
  }
}

function readTextPreview(file: string, max = 4000) {
  try {
    if (!fs.existsSync(file)) return "";
    return fs.readFileSync(file, "utf8").slice(0, max);
  } catch {
    return "";
  }
}

function writeJsonPath(file: string, value: unknown) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, `${JSON.stringify(value, null, 2)}\n`);
}

function normalizeMainReviewDecision(value: string) {
  const decision = String(value || "").trim().toLowerCase();
  if (["approve", "approved", "approve_shadow", "approved_shadow", "approved_shadow_only"].includes(decision)) return "approve_shadow";
  if (["defer", "deferred", "hold", "later"].includes(decision)) return "defer";
  if (["reject", "rejected", "deny", "denied"].includes(decision)) return "reject";
  return "";
}

function normalizeFinalApprovalDecision(value: string) {
  const decision = String(value || "").trim().toLowerCase();
  if (["approve", "approved", "approve_plan", "approved_plan", "approve_migration_plan", "approve_delivery_migration_plan_only", "approved_delivery_migration_plan_only"].includes(decision)) {
    return "approve_delivery_migration_plan_only";
  }
  if (["defer", "deferred", "hold", "later"].includes(decision)) return "deferred";
  if (["reject", "rejected", "deny", "denied"].includes(decision)) return "rejected";
  return "";
}

function readStrategyQueueStore() {
  return readJsonPath(OPENCLAW_STRATEGY_QUEUE_PATH) || { generated_at: null, queue: [] };
}

function readMainReviewPacketsReport() {
  return readJsonPath(path.join(WORKER_AUTONOMY_TASK_DIR, "worker_cron_main_review_packets.json"))
    || readJsonPath(path.join(WORKER_AUTONOMY_REPORT_ROOT, "LATEST_WORKER_CRON_MAIN_REVIEW_PACKETS.json"))
    || { packets: [], summary: null, reportPaths: {} };
}

function readMainReviewConsumerReport() {
  return readJsonPath(path.join(WORKER_AUTONOMY_TASK_DIR, "worker_cron_main_review_consumer.json"))
    || readJsonPath(path.join(WORKER_AUTONOMY_REPORT_ROOT, "LATEST_WORKER_CRON_MAIN_REVIEW_CONSUMER.json"))
    || { decisions: [], summary: null, reportPaths: {} };
}

function readFinalApprovalPackReport() {
  return readJsonPath(path.join(WORKER_AUTONOMY_TASK_DIR, "worker_cron_final_approval_pack.json"))
    || readJsonPath(path.join(WORKER_AUTONOMY_REPORT_ROOT, "LATEST_WORKER_CRON_FINAL_APPROVAL_PACK.json"))
    || { packets: [], summary: null, reportPaths: {} };
}

function readFinalApprovalConsumerReport() {
  return readJsonPath(path.join(WORKER_AUTONOMY_TASK_DIR, "worker_cron_final_approval_consumer.json"))
    || readJsonPath(path.join(WORKER_AUTONOMY_REPORT_ROOT, "LATEST_WORKER_CRON_FINAL_APPROVAL_CONSUMER.json"))
    || { decisions: [], summary: null, reportPaths: {} };
}

function buildSystemOpsMainReviewSnapshot() {
  const packetReport = readMainReviewPacketsReport();
  const consumerReport = readMainReviewConsumerReport();
  const queueStore = readStrategyQueueStore();
  const queueItems = Array.isArray(queueStore.queue) ? queueStore.queue : [];
  const queueById = new Map(queueItems.map((item: any) => [item.queue_id, item]));
  const consumerByReviewId = new Map((Array.isArray(consumerReport.decisions) ? consumerReport.decisions : []).map((item: any) => [item.review_id, item]));
  const packets = (Array.isArray(packetReport.packets) ? packetReport.packets : []).map((packet: any) => {
    const item = queueById.get(packet.queue_id) as Record<string, any> | undefined;
    const consumer = consumerByReviewId.get(packet.review_id) as Record<string, any> | undefined;
    return {
      reviewId: packet.review_id,
      queueId: packet.queue_id,
      riskLevel: packet.riskLevel || item?.main_review_risk || "unknown",
      status: item?.main_review_status || packet.status || "packet_ready",
      decision: item?.main_review_decision || null,
      decisionStatus: item?.main_review_decision_status || null,
      decidedAt: item?.main_review_decided_at || null,
      decidedBy: item?.main_review_decided_by || null,
      note: item?.main_review_note || "",
      consumptionStatus: item?.main_review_consumption_status || consumer?.status || null,
      workerShadowStatus: item?.worker_shadow_status || null,
      workerShadowReportPath: item?.worker_shadow_report_path || consumer?.shadowPath || null,
      recommendedDecision: packet.decision?.recommendedDecision || item?.main_review_recommended_decision || null,
      job: packet.job,
      diagnosis: packet.diagnosis,
      allowedAfterApproval: packet.decision?.allowedAfterApproval || [],
      forbidden: packet.decision?.forbidden || [],
      packetPath: packet.packetPath || null,
      markdownPath: packet.markdownPath || null,
    };
  });
  const summary = {
    total: packets.length,
    highRisk: packets.filter((packet: any) => packet.riskLevel === "high").length,
    waiting: packets.filter((packet: any) => !packet.decision).length,
    approvedShadow: packets.filter((packet: any) => packet.decision === "approve_shadow").length,
    deferred: packets.filter((packet: any) => packet.decision === "defer").length,
    rejected: packets.filter((packet: any) => packet.decision === "reject").length,
    shadowReady: packets.filter((packet: any) => packet.consumptionStatus === "shadow_design_ready").length,
  };
  return {
    ok: true,
    generatedAt: nowIso(),
    summary,
    packets,
    consumer: {
      status: consumerReport.status || null,
      summary: consumerReport.summary || null,
      reportPaths: consumerReport.reportPaths || {},
    },
    reportPaths: {
      packetReport: packetReport.reportPaths?.taskMd || packetReport.reportPaths?.taskJson || path.join(WORKER_AUTONOMY_TASK_DIR, "worker_cron_main_review_packets.md"),
      consumerReport: consumerReport.reportPaths?.taskMd || consumerReport.reportPaths?.taskJson || path.join(WORKER_AUTONOMY_TASK_DIR, "worker_cron_main_review_consumer.md"),
      strategyQueue: OPENCLAW_STRATEGY_QUEUE_PATH,
    },
    safety: {
      decisionWritesMetadataOnly: true,
      cronMutationAllowed: false,
      externalSendAllowed: false,
      gatewayRestartAllowed: false,
      protectedPathDeleteMoveRenameAllowed: false,
    },
  };
}

function writeSystemOpsMainReviewDecision(reviewId: string, rawDecision: string, rawNote: string) {
  const decision = normalizeMainReviewDecision(rawDecision);
  if (!decision) return { ok: false, statusCode: 400, error: "invalid_decision", allowed: ["approve_shadow", "defer", "reject"] };
  const snapshot = buildSystemOpsMainReviewSnapshot();
  const packet = snapshot.packets.find((row: any) => row.reviewId === reviewId);
  if (!packet) return { ok: false, statusCode: 404, error: "review_packet_not_found", reviewId };
  const queueStore = readStrategyQueueStore();
  queueStore.queue = Array.isArray(queueStore.queue) ? queueStore.queue : [];
  const idx = queueStore.queue.findIndex((item: any) => item.queue_id === packet.queueId);
  if (idx < 0) return { ok: false, statusCode: 404, error: "strategy_queue_item_not_found", reviewId, queueId: packet.queueId };
  const now = nowIso();
  const item = queueStore.queue[idx] as Record<string, any>;
  const run = {
    ts: now,
    actor: "main",
    source: "workbench_system_ops",
    decision,
    note: String(rawNote || "").slice(0, 1000),
    safety: "metadata_only_no_cron_mutation_no_external_send",
  };
  const runs = Array.isArray(item.main_review_decision_runs) ? item.main_review_decision_runs : [];
  queueStore.queue[idx] = {
    ...item,
    main_review_decision: decision,
    main_review_decision_status: decision === "approve_shadow" ? "approved_shadow_only" : decision,
    main_review_decided_at: now,
    main_review_decided_by: "main",
    main_review_note: run.note,
    main_review_decision_runs: [...runs, run].slice(-8),
  };
  queueStore.generated_at = now;
  writeJsonPath(OPENCLAW_STRATEGY_QUEUE_PATH, queueStore);
  const decisionRecord = {
    reviewId,
    queueId: packet.queueId,
    job: packet.job,
    riskLevel: packet.riskLevel,
    decision,
    note: run.note,
    generatedAt: now,
    safety: snapshot.safety,
  };
  writeJsonPath(path.join(WORKER_AUTONOMY_TASK_DIR, "main_review_decisions", `${reviewId}.json`), decisionRecord);
  return {
    ok: true,
    decision,
    reviewId,
    queueId: packet.queueId,
    decisionRecordPath: path.join(WORKER_AUTONOMY_TASK_DIR, "main_review_decisions", `${reviewId}.json`),
    snapshot: buildSystemOpsMainReviewSnapshot(),
  };
}

