function latestWorkerSystemOpsCronSession() {
  const sessionKey = `agent:worker:cron:${SYSTEM_OPS_CRON_ID}`;
  try {
    if (!fs.existsSync(WORKER_SESSION_STORE_PATH)) return null;
    const store = JSON.parse(fs.readFileSync(WORKER_SESSION_STORE_PATH, "utf8")) as Record<string, Record<string, unknown>>;
    const entry = store[sessionKey];
    const sessionId = String(entry?.sessionId || "");
    if (!sessionId) return { sessionKey, error: "session_not_found" };
    const transcriptPath = path.join(WORKER_SESSION_DIR, `${sessionId}.jsonl`);
    const mtimeMs = fs.existsSync(transcriptPath) ? fs.statSync(transcriptPath).mtimeMs : 0;
    if (!fs.existsSync(transcriptPath)) return { sessionKey, sessionId, updatedAt: entry.updatedAt || null, transcriptPath, error: "transcript_not_found" };
    const lines = fs.readFileSync(transcriptPath, "utf8").trim().split(/\r?\n/).filter(Boolean).slice(-160);
    let cronStatus = "";
    let lastText = "";
    let toolError = "";
    for (const line of lines) {
      try {
        const item = JSON.parse(line) as Record<string, any>;
        const message = item.message || {};
        const content = Array.isArray(message.content) ? message.content : [];
        if (message.role === "assistant") {
          const text = content
            .filter((part: any) => part?.type === "text")
            .map((part: any) => String(part.text || ""))
            .join("\n")
            .trim();
          if (text) {
            lastText = text.slice(0, 1200);
            const match = text.match(/CRON_STATUS=(OK|DEGRADED|ERROR)/);
            if (match) cronStatus = match[1];
          }
        }
        if (message.role === "toolResult") {
          const detailText = String(message.details?.error || content.map((part: any) => part?.text || "").join("\n") || "");
          if (/error|failed|not found|timed out|exit/i.test(detailText)) toolError = detailText.slice(0, 1200);
        }
      } catch {
        // Ignore malformed historical transcript lines; the session itself should remain observable.
      }
    }
    return {
      sessionKey,
      sessionId,
      updatedAt: entry.updatedAt || null,
      transcriptPath,
      mtimeMs,
      ageMs: mtimeMs ? Date.now() - mtimeMs : null,
      cronStatus: cronStatus || null,
      lastText,
      toolError,
    };
  } catch (err) {
    return { sessionKey, error: err instanceof Error ? err.message : String(err) };
  }
}

function latestSystemOpsReport() {
  try {
    if (!fs.existsSync(SYSTEM_OPS_REPORT_ROOT)) return null;
    const files = fs.readdirSync(SYSTEM_OPS_REPORT_ROOT)
      .filter((name) => /^system_ops_watchdog_.*\.json$/.test(name))
      .map((name) => path.join(SYSTEM_OPS_REPORT_ROOT, name))
      .sort((a, b) => fs.statSync(b).mtimeMs - fs.statSync(a).mtimeMs);
    const file = files[0];
    if (!file) return null;
    const data = JSON.parse(fs.readFileSync(file, "utf8"));
    return { path: file, mtimeMs: fs.statSync(file).mtimeMs, data };
  } catch (err) {
    return { path: SYSTEM_OPS_REPORT_ROOT, error: err instanceof Error ? err.message : String(err), data: null };
  }
}

function readWorkerSystemOpsConfig() {
  try {
    const raw = fs.readFileSync(OPENCLAW_CONFIG_PATH, "utf8");
    const config = JSON.parse(raw) as { agents?: { list?: Array<Record<string, any>> } };
    const worker = config.agents?.list?.find((agent) => agent.id === "worker") || {};
    const exec = worker.tools?.exec || {};
    return {
      agentId: "worker",
      exec: {
        security: exec.security || "unknown",
        ask: exec.ask || "unknown",
        node: exec.node || null,
      },
      allowedLowRisk: ["状态检查", "NAS 恢复", "允许地区 Clash 切换", "报告生成", "任务续跑提示", "Workbench 派单"],
      requiresMainApproval: ["gateway 重启", "OpenClaw 配置写入", "外部通知", "受保护路径删除/移动", "付费资源", "账号/密码/2FA"],
      source: OPENCLAW_CONFIG_PATH,
    };
  } catch (err) {
    return { agentId: "worker", error: err instanceof Error ? err.message : String(err), source: OPENCLAW_CONFIG_PATH };
  }
}

function runSystemOpsWatchdog(mode: "shadow" | "apply") {
  const out = spawnSync(process.execPath, [SYSTEM_OPS_SKILL_RUNNER, `--mode=${mode}`, "--owner=worker", "--json"], {
    encoding: "utf8",
    cwd: WORKSPACE_DIR,
    timeout: mode === "apply" ? 8 * 60_000 : 3 * 60_000,
    maxBuffer: 8 * 1024 * 1024,
    env: { ...process.env, PATH: `${path.join(os.homedir(), ".npm-global/bin")}:/opt/homebrew/bin:/usr/local/bin:${process.env.PATH || ""}` },
  });
  let parsed: any = null;
  try {
    parsed = out.stdout ? JSON.parse(out.stdout) : null;
  } catch {
    parsed = null;
  }
  return {
    status: out.status,
    signal: out.signal,
    error: out.error ? String(out.error.message || out.error) : null,
    parsed,
    stdout: parsed ? "" : String(out.stdout || "").slice(0, 4000),
    stderr: String(out.stderr || "").slice(0, 4000),
  };
}

app.get("/*", async (req, reply) => {
  const urlPath = decodeURIComponent(req.url.split("?")[0]);
  if (urlPath.startsWith("/api/")) return reply.code(404).send({ ok: false, error: "not_found" });
  const rel = urlPath === "/" ? "index.html" : urlPath.replace(/^\/+/, "");
  const filePath = path.normalize(path.join(WEB_DIST_DIR, rel));
  const safe = filePath.startsWith(WEB_DIST_DIR) && fs.existsSync(filePath) && fs.statSync(filePath).isFile()
    ? filePath
    : path.join(WEB_DIST_DIR, "index.html");
  if (!fs.existsSync(safe)) return reply.type("text/html").send("<h1>OpenClaw Workbench</h1><p>Run npm run build first.</p>");
  reply.header("Cache-Control", "no-store, must-revalidate");
  reply.type(contentType(safe)).send(fs.readFileSync(safe));
});

function contentType(file: string) {
  if (file.endsWith(".js")) return "application/javascript; charset=utf-8";
  if (file.endsWith(".css")) return "text/css; charset=utf-8";
  if (file.endsWith(".svg")) return "image/svg+xml";
  if (file.endsWith(".png")) return "image/png";
  return "text/html; charset=utf-8";
}

function normalizeMobilePlatform(value: unknown) {
  const platform = String(value || "").toLowerCase();
  if (["ios", "android", "web"].includes(platform)) return platform;
  return "unknown";
}

function createMobileDeviceToken(deviceId: string, kind: "access" | "refresh", ttlMs: number) {
  const token = `ocm_${kind}_${randomBytes(32).toString("base64url")}`;
  const id = randomUUID();
  const now = nowIso();
  const expiresAt = new Date(Date.now() + ttlMs).toISOString();
  db.prepare("INSERT INTO mobile_device_tokens (id, device_id, token_hash, kind, expires_at, created_at) VALUES (?, ?, ?, ?, ?, ?)")
    .run(id, deviceId, tokenHash(token), kind, expiresAt, now);
  return { id, token, expiresAt };
}

function sanitizeMobileDevice(row: unknown) {
  const device = (row || {}) as Record<string, unknown>;
  return {
    id: String(device.id || ""),
    name: String(device.name || ""),
    platform: String(device.platform || "unknown"),
    appVersion: String(device.app_version || ""),
    status: String(device.status || "unknown"),
    createdAt: String(device.created_at || ""),
    lastSeenAt: device.last_seen_at ? String(device.last_seen_at) : null,
    revokedAt: device.revoked_at ? String(device.revoked_at) : null,
  };
}

