function upsertDevelopmentSeedProject(seed: DevelopmentSeed) {
  const now = nowIso();
  db.prepare("INSERT OR IGNORE INTO projects (id, name, status, description, created_at, updated_at, objective, key_results, deadline, progress) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
    .run(seed.id, seed.name, seed.status, seed.description, now, now, seed.objective, JSON.stringify(["development_domain"]), null, seed.id === "aog-copilot" ? 45 : 10);
  const current = db.prepare("SELECT status FROM projects WHERE id = ?").get(seed.id) as { status?: string } | undefined;
  if (current && !["archived", "completed"].includes(String(current.status))) {
    db.prepare("UPDATE projects SET name = ?, description = COALESCE(NULLIF(description, ''), ?), objective = COALESCE(NULLIF(objective, ''), ?), updated_at = ? WHERE id = ?")
      .run(seed.name, seed.description, seed.objective, now, seed.id);
  }
  db.prepare(`
    INSERT INTO development_project_profiles (project_id, objective, repo_path, task_dir, preview_url, quality_gates, default_model_id, default_agent_policy, created_at, updated_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(project_id) DO UPDATE SET
      objective = excluded.objective,
      repo_path = excluded.repo_path,
      task_dir = COALESCE(NULLIF(development_project_profiles.task_dir, ''), excluded.task_dir),
      preview_url = COALESCE(NULLIF(development_project_profiles.preview_url, ''), excluded.preview_url),
      quality_gates = excluded.quality_gates,
      default_model_id = excluded.default_model_id,
      default_agent_policy = excluded.default_agent_policy,
      updated_at = excluded.updated_at
  `).run(seed.id, seed.objective, seed.repoPath || "", seed.taskDir || "", seed.previewUrl || "", JSON.stringify(["prd_required", "test_evidence_required", "approval_required_for_release"]), seed.modelId || "minimax-m3", seed.agentPolicy || "auto", now, now);
  seedDevelopmentProjectWorkspace(seed);
  seedDevelopmentProductRole(seed);
  seedDevelopmentDocuments(seed);
  seedDevelopmentStages(seed);
  seedDevelopmentTasks(seed);
  seedDevelopmentWorkPackets(seed);
  seedDevelopmentToolRegistry(seed);
  seedDevelopmentGateDefinitions(seed);
  seedDevelopmentPluginRegistry(seed);
  seedDevelopmentRun(seed);
  seedDevelopmentEvidenceArtifacts(seed);
  seedDevelopmentContextManifest(seed);
  seedDevelopmentReviewRecords(seed);
  seedDevelopmentBaseline(seed);
  seedDevelopmentGoals(seed);
}

