function writeTextFileIfMissing(filePath: string, content: string) {
 if (fs.existsSync(filePath)) return;
 fs.mkdirSync(path.dirname(filePath), { recursive: true });
 fs.writeFileSync(filePath, content);
}

/**
 * Safely write a file and surface failure to the development event log + audit trail.
 * Returned object lets the caller decide whether to abort the operation or only emit a warning.
 *
 * WHY THIS EXISTS (goal-progression P0):
 * - Previous code did `fs.writeFileSync(subtask.resultPath, ...)` in three places
 * (runDevelopmentSubtask, writeDevelopmentSubtaskResultFromSession, acceptDevelopmentSubtask)
 * without try/catch — a missing directory or unwritable path would500 the request
 * with no audit event, leaving the UI/database state out of sync with the disk.
 * - PLAN.md / RESULT.md are user-visible evidence; silent disk write failure must
 * always be visible in development_run_events + audit_logs.
 */
function writeDevelopmentEvidenceFile(input: {
 filePath: string;
 content: string;
 projectId: string;
 runId?: string | null;
 subtaskId?: string | null;
 goalId?: string | null;
 kind?: "RESULT" | "PLAN" | "OTHER";
}) {
 const kind = input.kind || "OTHER";
 const trimmedPath = String(input.filePath || "").trim();
 if (!trimmedPath) {
 const message = `${kind} 文件路径为空，跳过写盘。`;
developmentEvent({
  projectId: input.projectId,
  runId: input.runId || undefined,
  subtaskId: input.subtaskId || null,
  eventType: "error",
  actor: "main",
  severity: "warn",
  message,
  payload: { source: "writeDevelopmentEvidenceFile", kind, goalId: input.goalId || null },
  });
 audit(db, "development.subtask.evidence_write_skipped", "development_subtask", input.subtaskId || "", "normal", {
 projectId: input.projectId,
 kind,
 reason: "empty_path",
 goalId: input.goalId || null,
 });
 return { ok: false, reason: "empty_path" as const };
 }
 try {
 fs.mkdirSync(path.dirname(trimmedPath), { recursive: true });
 fs.writeFileSync(trimmedPath, input.content);
 return { ok: true, reason: null };
 } catch (err) {
 const message = `${kind} 文件写盘失败：${trimmedPath} · ${err instanceof Error ? err.message : String(err)}`;
developmentEvent({
  projectId: input.projectId,
  runId: input.runId || undefined,
  subtaskId: input.subtaskId || null,
  eventType: "error",
  actor: "main",
  severity: "error",
 message,
 payload: {
 source: "writeDevelopmentEvidenceFile",
 kind,
 path: trimmedPath,
 error: sanitizePublicError(err instanceof Error ? err.message : String(err)),
 goalId: input.goalId || null,
 },
 });
 audit(db, "development.subtask.evidence_write_failed", "development_subtask", input.subtaskId || "", "high", {
 projectId: input.projectId,
 kind,
 path: trimmedPath,
 error: err instanceof Error ? err.message : String(err),
 goalId: input.goalId || null,
 });
 return { ok: false, reason: "write_failed" as const, error: err instanceof Error ? err.message : String(err) };
 }
}

/**
 * Scan subtask.evidence_dir + subtask.artifacts_dir + subtask.plan_path + subtask.result_path
 * and ensure every file is reflected in development_artifacts with subtask_id linkage.
 *
 * WHY THIS EXISTS (goal-progression P0):
 * - subtask.evidence_dir / subtask.artifacts_dir exist as columns on development_subtasks,
 * but nothing was scanning the directory back into development_artifacts. Evidence drift:
 * OpenClaw agents dropping files into these dirs would be invisible to UI/audit until
 * a user manually re-triggered sync.
 * - This function is idempotent (deterministic artifact id), cheap (one fs.readdirSync
 * per dir), and safe (swallows individual file errors).
 * - Returns {scanned, added, errors} so callers / smoke can verify drift =0.
 */
function reconcileDevelopmentSubtaskEvidence(subtaskId: string, opts: { forceReindex?: boolean } = {}) {
 const subtask = developmentSubtaskById(subtaskId);
 if (!subtask) return { scanned:0, added:0, errors:0, skipped: "subtask_not_found" };
 const project = developmentProjectDetail(subtask.projectId);
 if (!project) return { scanned:0, added:0, errors:0, skipped: "project_not_found" };

 const dirsToScan = [subtask.evidenceDir, subtask.artifactsDir, subtask.reviewsDir].filter(Boolean);
 const explicitFiles = [subtask.planPath, subtask.resultPath].filter(Boolean);
 const seen = new Set<string>();
 let scanned =0;
 let added =0;
 let errors =0;

 const inferKind = (filePath: string): "plan" | "result" | "evidence" | "artifact" | "review" => {
 if (filePath === subtask.planPath) return "plan";
 if (filePath === subtask.resultPath) return "result";
 if (subtask.reviewsDir && filePath.startsWith(subtask.reviewsDir)) return "review";
 if (subtask.artifactsDir && filePath.startsWith(subtask.artifactsDir)) return "artifact";
 return "evidence";
 };

 const titleForKind = (kind: string, fileName: string) => {
 switch (kind) {
 case "plan": return "Subtask PLAN";
 case "result": return "Subtask RESULT";
 case "review": return `Subtask Review · ${fileName}`;
 case "artifact": return `Subtask Artifact · ${fileName}`;
 default: return `Subtask Evidence · ${fileName}`;
 }
 };

 const upsert = (filePath: string) => {
 scanned +=1;
 const safeKey = filePath.replace(/[^a-zA-Z0-9_-]/g, "_").slice(-120);
 const artifactId = `artifact-subtask-${subtask.id}-${safeKey}`;
 if (seen.has(artifactId)) return;
 seen.add(artifactId);
 let stat: fs.Stats;
 try {
 if (!fs.existsSync(filePath)) return;
 stat = fs.statSync(filePath);
 } catch {
 errors +=1;
 return;
 }
 if (!stat.isFile()) return;
 const fileName = path.basename(filePath);
 const kind = inferKind(filePath);
 const evidenceLevel = kind === "plan" ? "source"
 : kind === "result" ? "reference"
 : kind === "review" ? "review"
 : kind === "artifact" ? "deliverable"
 : "evidence";
 try {
 const existing = db.prepare("SELECT id, created_at FROM development_artifacts WHERE id = ?").get(artifactId) as { id?: string; created_at?: string } | undefined;
 if (existing && !opts.forceReindex) {
 return;
 }
 const now = nowIso();
 db.prepare(`
 INSERT INTO development_artifacts (id, project_id, run_id, task_id, artifact_type, title, path, url, status, evidence_level, metadata, created_at, subtask_id)
 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
 ON CONFLICT(id) DO UPDATE SET
 artifact_type = excluded.artifact_type,
 title = excluded.title,
 path = excluded.path,
 url = excluded.url,
 status = excluded.status,
 evidence_level = excluded.evidence_level,
 metadata = excluded.metadata,
 subtask_id = excluded.subtask_id,
 created_at = excluded.created_at
 `).run(
 artifactId,
 subtask.projectId,
 null,
 subtask.taskId || null,
 `subtask_${kind}`,
 titleForKind(kind, fileName),
 filePath,
 `/api/development/artifacts/${encodeURIComponent(artifactId)}/raw`,
 "available",
 evidenceLevel,
 JSON.stringify({
 source: "reconcileDevelopmentSubtaskEvidence",
 subtaskId: subtask.id,
 sequence: subtask.sequence,
 sizeBytes: stat.size,
 mtimeMs: stat.mtimeMs,
 kind,
 }),
 existing?.created_at || now,
 subtask.id,
 );
 added +=1;
 } catch (err) {
 errors +=1;
 app.log.warn({ err, subtaskId, filePath }, "reconcileDevelopmentSubtaskEvidence: failed to upsert artifact");
 }
 };

 for (const dir of dirsToScan) {
 if (!dir || !fs.existsSync(dir)) continue;
 let entries: fs.Dirent[];
 try {
 entries = fs.readdirSync(dir, { withFileTypes: true });
 } catch (err) {
 app.log.warn({ err, subtaskId, dir }, "reconcileDevelopmentSubtaskEvidence: readdir failed");
 errors +=1;
 continue;
 }
 for (const entry of entries) {
 if (entry.isFile()) upsert(path.join(dir, entry.name));
 else if (entry.isDirectory()) {
 // shallow recursive — one level deep is enough for typical evidence layouts
 try {
 const subEntries = fs.readdirSync(path.join(dir, entry.name), { withFileTypes: true });
 for (const sub of subEntries) {
 if (sub.isFile()) upsert(path.join(dir, entry.name, sub.name));
 }
 } catch (err) {
 app.log.warn({ err, subtaskId, dir: path.join(dir, entry.name) }, "reconcileDevelopmentSubtaskEvidence: readdir subdir failed");
 }
 }
 }
 }
 for (const file of explicitFiles) upsert(file);

// P0 (goal-progression): 不静默吞 reconcile 错误 ——added=0/errors>0 (drift 未修复)
  // 或 errors>0 (存在 stat/readdir/upsert 失败) 时也要在 timeline + audit_logs 留痕，
  // 否则监控端只看到 server log.warn，看不到 evidence 漂移。
  if (added >0 || errors >0) {
  developmentEvent({
  projectId: subtask.projectId,
  subtaskId: subtask.id,
  eventType: errors >0 ? "error" : "artifact",
  actor: "main",
  severity: errors >0 ? "warn" : "info",
  message: errors >0
  ? `子任务证据扫描异常：scanned=${scanned}, added=${added}, errors=${errors}`
  : `子任务证据扫描：新增 ${added} 条产物记录（目录扫描 ${scanned} 个文件，错误 ${errors} 个）`,
  payload: { source: "reconcileDevelopmentSubtaskEvidence", scanned, added, errors, subtaskId: subtask.id },
  });
  }
  if (errors >0) {
  audit(db, "development.subtask.evidence_reconcile_error", "development_subtask", subtask.id, "high", {
  projectId: subtask.projectId,
  scanned,
  added,
  errors,
  });
  }
  return { scanned, added, errors, skipped: null };
}

function seedDevelopmentProjectWorkspace(seed: DevelopmentSeed) {
  const now = nowIso();
  const workspacePath = developmentProjectWorkspacePath(seed.id);
  const evidenceDir = path.join(workspacePath, "evidence");
  const artifactsDir = path.join(workspacePath, "artifacts");
  const reviewsDir = path.join(workspacePath, "reviews");
  const subtasksDir = path.join(workspacePath, "subtasks");
  for (const dir of [workspacePath, evidenceDir, artifactsDir, reviewsDir, subtasksDir]) fs.mkdirSync(dir, { recursive: true });
  const goalPath = path.join(workspacePath, "GOAL.md");
  const prdPath = path.join(workspacePath, "PRD.md");
  const baselinePath = path.join(workspacePath, "BASELINE.md");
  writeTextFileIfMissing(goalPath, [
    `# ${seed.name} 项目目标`,
    "",
    seed.objective,
    "",
    "## 成功标准",
    "- 先确认目标和 PRD，再锁定子任务基线。",
    "- 每次只执行一个子任务，验收不通过不得推进。",
    "- 全部子任务通过后才进入交付门控。",
    "",
    "## 非目标",
    "- 不绕过人工审批。",
    "- 不把降级依赖显示为 OK。",
  ].join("\n"));
  const sourcePrd = seed.taskDir ? path.join(seed.taskDir, "PRD.md") : "";
  const prdContent = sourcePrd && fs.existsSync(sourcePrd)
    ? readTextFile(sourcePrd, 80_000)
    : [
      `# ${seed.name} PRD`,
      "",
      "## 产品定位",
      seed.description || seed.objective,
      "",
      "## 用户价值",
      "- 把模糊需求拆解为可执行、可验收、可复盘的 AI 产品开发链路。",
      "",
      "## 验收标准",
      "- 子任务基线明确。",
      "- 串行执行与验收门控可追溯。",
    ].join("\n");
  writeTextFileIfMissing(prdPath, prdContent);
  writeTextFileIfMissing(baselinePath, `# ${seed.name} 项目任务基线\n\n待 Top AI Product Manager 生成。\n`);
  db.prepare(`
    INSERT INTO development_project_workspaces (project_id, workspace_path, goal_path, prd_path, baseline_path, evidence_dir, artifacts_dir, reviews_dir, status, created_at, updated_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(project_id) DO UPDATE SET
      workspace_path = excluded.workspace_path,
      goal_path = excluded.goal_path,
      prd_path = excluded.prd_path,
      baseline_path = excluded.baseline_path,
      evidence_dir = excluded.evidence_dir,
      artifacts_dir = excluded.artifacts_dir,
      reviews_dir = excluded.reviews_dir,
      status = excluded.status,
      updated_at = excluded.updated_at
  `).run(seed.id, workspacePath, goalPath, prdPath, baselinePath, evidenceDir, artifactsDir, reviewsDir, "ready", now, now);
  return developmentProjectWorkspace(seed.id);
}

function seedDevelopmentProductRole(seed: DevelopmentSeed) {
  const now = nowIso();
  db.prepare(`
    INSERT INTO development_product_roles (id, project_id, role_key, title, status, principles, value_metrics, taste_threshold, critical_threshold, non_goals, acceptance_policy, updated_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(project_id, role_key) DO UPDATE SET
      title = excluded.title,
      status = excluded.status,
      principles = excluded.principles,
      value_metrics = excluded.value_metrics,
      taste_threshold = excluded.taste_threshold,
      critical_threshold = excluded.critical_threshold,
      non_goals = excluded.non_goals,
      acceptance_policy = excluded.acceptance_policy,
      updated_at = excluded.updated_at
  `).run(
    `dev-role-${seed.id}-top-ai-pm`,
    seed.id,
    "top_ai_product_manager",
    "Top AI Product Manager",
    "active",
    JSON.stringify(["从真实困境出发", "目标和 PRD 先行", "子任务必须可验收", "降级状态必须显式展示", "产品品味由证据约束"]),
    JSON.stringify(["workflow_completion", "acceptance_pass_rate", "time_to_validated_subtask", "product_taste_score", "no_fake_ok_count"]),
    85,
    75,
    JSON.stringify(["不默认使用 Codex 执行", "不做无人值守生产发布", "不绕过审批门控"]),
    "gates_plus_human_for_high_risk",
    now,
  );
  return developmentProductRole(seed.id);
}

function seedDevelopmentDocuments(seed: DevelopmentSeed) {
  const reports = listDeliveryCoreReports({ projectId: seed.id, taskDir: seed.taskDir || "" });
  const reportPath = reports[0]?.jsonPath || "";
  const workspace = developmentProjectWorkspace(seed.id);
  const docRows: Array<{ key: string; label: string; title: string; kind: string; path: string; url: string; summary: string; sortOrder: number }> = DEVELOPMENT_DOCS.map((doc, index) => ({
    key: doc.key,
    label: doc.label,
    title: doc.key === "goal" ? "GOAL.md" : doc.title,
    kind: "document",
    path: doc.key === "goal" && workspace?.goalPath ? workspace.goalPath
      : doc.key === "prd" && workspace?.prdPath ? workspace.prdPath
        : seed.taskDir ? path.join(seed.taskDir, doc.file) : "",
    url: "",
    summary: doc.summary,
    sortOrder: index * 10,
  }));
  if (workspace?.baselinePath) {
    docRows.push({
      key: "baseline",
      label: "任务基线",
      title: "BASELINE.md",
      kind: "document",
      path: workspace.baselinePath,
      url: "",
      summary: "项目开发基线、串行子任务清单和验收状态。",
      sortOrder: 25,
    });
  }
  docRows.push({
    key: "report",
    label: "开发报告",
    title: "delivery_core_run.json",
    kind: "document",
    path: reportPath,
    url: "",
    summary: "Delivery Core 最新运行报告、门控、测试矩阵和阻塞项。",
    sortOrder: 90,
  });
  docRows.push({
    key: "browser",
    label: "浏览器",
    title: seed.name,
    kind: "browser",
    path: "",
    url: seed.previewUrl || "",
    summary: "项目本地浏览器预览入口。",
    sortOrder: 100,
  });
  for (const doc of docRows) upsertDevelopmentDocument(seed.id, doc);
}

function upsertDevelopmentDocument(projectId: string, doc: { key: string; label: string; title: string; kind: string; path: string; url: string; summary: string; sortOrder: number }) {
  const now = nowIso();
  const status = developmentDocumentStatus(doc.kind, doc.path, doc.url);
  db.prepare(`
    INSERT INTO development_documents (id, project_id, doc_key, label, title, kind, path, url, summary, status, sort_order, created_at, updated_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(project_id, doc_key) DO UPDATE SET
      label = excluded.label,
      title = excluded.title,
      kind = excluded.kind,
      path = COALESCE(NULLIF(excluded.path, ''), development_documents.path),
      url = COALESCE(NULLIF(excluded.url, ''), development_documents.url),
      summary = excluded.summary,
      status = excluded.status,
      sort_order = excluded.sort_order,
      updated_at = excluded.updated_at
  `).run(`dev-doc-${projectId}-${doc.key}`, projectId, doc.key, doc.label, doc.title, doc.kind, doc.path, doc.url, doc.summary, status, doc.sortOrder, now, now);
}

function developmentProjectWorkspace(projectId: string) {
  const row = db.prepare("SELECT * FROM development_project_workspaces WHERE project_id = ?").get(projectId) as Record<string, unknown> | undefined;
  if (!row) return null;
  return {
    projectId: String(row.project_id || ""),
    workspacePath: String(row.workspace_path || ""),
    goalPath: String(row.goal_path || ""),
    prdPath: String(row.prd_path || ""),
    baselinePath: String(row.baseline_path || ""),
    evidenceDir: String(row.evidence_dir || ""),
    artifactsDir: String(row.artifacts_dir || ""),
    reviewsDir: String(row.reviews_dir || ""),
    status: String(row.status || "ready"),
    createdAt: String(row.created_at || ""),
    updatedAt: String(row.updated_at || ""),
  };
}

function developmentProductRole(projectId: string) {
  const row = db.prepare("SELECT * FROM development_product_roles WHERE project_id = ? AND role_key = ?").get(projectId, "top_ai_product_manager") as Record<string, unknown> | undefined;
  if (!row) return null;
  return {
    id: String(row.id || ""),
    projectId: String(row.project_id || ""),
    roleKey: String(row.role_key || ""),
    title: String(row.title || ""),
    status: String(row.status || ""),
    principles: parseJsonArray(row.principles),
    valueMetrics: parseJsonArray(row.value_metrics),
    tasteThreshold: Number(row.taste_threshold || 85),
    criticalThreshold: Number(row.critical_threshold || 75),
    nonGoals: parseJsonArray(row.non_goals),
    acceptancePolicy: String(row.acceptance_policy || "gates_plus_human_for_high_risk"),
    updatedAt: String(row.updated_at || ""),
  };
}

function developmentWorkspaceBundle(projectId: string) {
  return {
    workspace: developmentProjectWorkspace(projectId),
    productRole: developmentProductRole(projectId),
    goal: developmentDocument(projectId, "goal"),
    prd: developmentDocument(projectId, "prd"),
  };
}

function seedDevelopmentBaseline(seed: DevelopmentSeed) {
  generateDevelopmentBaseline(seed.id, {
    lock: seed.id === "aog-copilot",
    actor: "top_ai_pm",
    reason: "seed",
    force: false,
  });
}

