type GoalOsPreflightStatus = "passed" | "warn" | "failed";
type GoalOsPreflightCheck = {
  key: string;
  label: string;
  status: GoalOsPreflightStatus;
  summary: string;
  detail?: string;
};
type GoalOsPreflightResult = {
  ok: boolean;
  status: "ready" | "blocked" | "degraded";
  generatedAt: string;
  action: string;
  activeAgentId: string;
  projectId: string;
  goalId: string;
  subtaskId: string;
  repoPath: string;
  env: string;
  gitDirtyCount: number;
  checks: GoalOsPreflightCheck[];
  blockers: string[];
  repairActions: string[];
  forbiddenActions: string[];
  canary?: {
    ok: boolean;
    command: string;
    nodeId: string;
    summary: string;
  };
};

function addGoalOsCheck(checks: GoalOsPreflightCheck[], key: string, label: string, status: GoalOsPreflightStatus, summary: string, detail = "") {
  checks.push({ key, label, status, summary, ...(detail ? { detail } : {}) });
}

function goalOsPublicError(value: unknown, maxLength = 320) {
  return sanitizePublicError(String(value || ""))
    .replace(/\s+/g, " ")
    .slice(0, maxLength)
    .trim();
}

function goalOsJsonObject(text: string): Record<string, unknown> {
  const raw = String(text || "").trim();
  if (!raw) return {};
  try {
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed as Record<string, unknown> : {};
  } catch {
    const start = raw.indexOf("{");
    const end = raw.lastIndexOf("}");
    if (start >= 0 && end > start) {
      try {
        const parsed = JSON.parse(raw.slice(start, end + 1));
        return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed as Record<string, unknown> : {};
      } catch {
        return {};
      }
    }
    return {};
  }
}

function goalOsNodeRows(nodesJson: Record<string, unknown>) {
  const rows = Array.isArray(nodesJson.nodes) ? nodesJson.nodes : [];
  return rows.filter((row): row is Record<string, unknown> => Boolean(row && typeof row === "object" && !Array.isArray(row)));
}

function goalOsCommandList(row: Record<string, unknown>) {
  const commands = Array.isArray(row.commands) ? row.commands.map(String) : [];
  const caps = Array.isArray(row.caps) ? row.caps.map(String) : [];
  return [...commands, ...caps].map((item) => item.toLowerCase());
}

function goalOsNodeId(row: Record<string, unknown>) {
  return String(row.nodeId || row.id || row.name || row.remoteIp || "").trim();
}

function goalOsNodeHostLoaded(nodeJson: Record<string, unknown>, nodeText: string) {
  const service = safeJsonObject(nodeJson.service);
  const runtime = safeJsonObject(service.runtime);
  if (service.loaded === true) return true;
  if (/Service:\s*LaunchAgent\s*\(loaded\)|Runtime:\s*(running|active|loaded)/i.test(nodeText)) return true;
  if (runtime.status && /running|active|loaded/i.test(String(runtime.status))) return true;
  return false;
}

function summarizeGoalOsNodeHost(nodeStatus: { ok: boolean; stdout: string; stderr: string; error: string }, nodesStatus: { stdout: string; stderr: string }, nodeJson: Record<string, unknown>, nodesJson: Record<string, unknown>, nodeText: string) {
  const rows = goalOsNodeRows(nodesJson);
  const connected = rows.filter((row) => row.connected === true || /connected/i.test(String(row.status || ""))).length;
  const paired = rows.filter((row) => row.paired !== false).length || rows.length;
  const loaded = goalOsNodeHostLoaded(nodeJson, nodeText);
  if (loaded && connected > 0) return `OpenClaw node host 已加载；${connected}/${Math.max(rows.length, connected)} 个节点 connected。`;
  if (/Could not find service\s+"com\.clawdbot\.node"|missingUnit|not found/i.test(nodeText)) {
    return "OpenClaw node host 未安装或未 bootstrap：com.clawdbot.node LaunchAgent 不存在。需要 NJX 明确批准后执行 `openclaw-cn node install` / `openclaw-cn node start`。";
  }
  if (/not loaded|LaunchAgent\s*\(not loaded\)|loadedText.*not loaded/i.test(nodeText)) {
    return "OpenClaw node host LaunchAgent 存在但未加载。需要 NJX 明确批准后执行 `openclaw-cn node start` 或 `launchctl bootstrap gui/$UID ~/Library/LaunchAgents/com.clawdbot.node.plist`。";
  }
  if (paired > 0 && connected === 0) {
    return `OpenClaw node host 未连接：已配对 ${paired} 个节点，但 0 个 connected。`;
  }
  return `OpenClaw node host 不可用：${goalOsPublicError(nodeStatus.error || nodeStatus.stderr || nodeStatus.stdout || nodesStatus.stderr || nodesStatus.stdout)}`;
}

function summarizeGoalOsSystemRun(nodesJson: Record<string, unknown>, nodeText: string) {
  const rows = goalOsNodeRows(nodesJson);
  const connectedRows = rows.filter((row) => row.connected === true || /connected/i.test(String(row.status || "")));
  const systemRunRows = connectedRows.filter((row) => goalOsCommandList(row).some((item) => item === "system.run" || item.endsWith(":system.run")));
  if (systemRunRows.length) return `${systemRunRows.length} 个 connected node 支持 system.run。`;
  if (!rows.length) return "没有已配对 node，system.run 不可用。";
  if (!connectedRows.length) return `已配对 ${rows.length} 个 node，但 0 个 connected；system.run 不可用。`;
  const commandCount = connectedRows.reduce((sum, row) => sum + goalOsCommandList(row).length, 0);
  if (commandCount === 0) return `${connectedRows.length} 个 node connected，但未暴露 commands/caps；system.run 不可用。`;
  return `connected node 未暴露 system.run；可见能力：${connectedRows.flatMap(goalOsCommandList).slice(0, 8).join(", ") || goalOsPublicError(nodeText)}`;
}

function runGoalOsCommand(command: string, args: string[], cwd: string, timeoutMs = 5_000): Promise<{ ok: boolean; stdout: string; stderr: string; code: number | null; error: string }> {
  return new Promise((resolve) => {
    const child = spawn(command, args, {
      cwd,
      env: {
        ...process.env,
        PATH: [
          path.dirname(process.execPath),
          path.join(os.homedir(), ".npm-global", "bin"),
          "/opt/homebrew/bin",
          "/usr/local/bin",
          "/usr/bin",
          "/bin",
          process.env.PATH || "",
        ].filter(Boolean).join(":"),
        NODE_NO_WARNINGS: "1",
      },
      stdio: ["ignore", "pipe", "pipe"],
    });
    let stdout = "";
    let stderr = "";
    let settled = false;
    const timer = windowlessTimeout(() => {
      if (settled) return;
      settled = true;
      child.kill("SIGTERM");
      resolve({ ok: false, stdout, stderr, code: null, error: `timeout_${timeoutMs}ms` });
    }, timeoutMs);
    child.stdout?.on("data", (chunk) => {
      stdout += String(chunk);
      if (stdout.length > 16_000) stdout = stdout.slice(-16_000);
    });
    child.stderr?.on("data", (chunk) => {
      stderr += String(chunk);
      if (stderr.length > 8_000) stderr = stderr.slice(-8_000);
    });
    child.on("error", (err) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve({ ok: false, stdout, stderr, code: null, error: err.message });
    });
    child.on("close", (code) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve({ ok: code === 0, stdout, stderr, code, error: code === 0 ? "" : stderr || stdout || `exit_${code}` });
    });
  });
}

function ensureGoalOsGitStatusHelper() {
  const helperPath = process.env.OPENCLAW_GOAL_OS_GIT_STATUS_HELPER
    || path.join(os.homedir(), ".openclaw", "bin", "goal-os-git-status-short");
  const helperSource = "#!/bin/sh\nset -eu\nexec /usr/bin/git status --short\n";
  try {
    fs.mkdirSync(path.dirname(helperPath), { recursive: true });
    const existing = fs.existsSync(helperPath) ? fs.readFileSync(helperPath, "utf8") : "";
    if (existing !== helperSource) {
      fs.writeFileSync(helperPath, helperSource, { mode: 0o755 });
    }
    fs.chmodSync(helperPath, 0o755);
    return { ok: true, path: helperPath, error: "" };
  } catch (err) {
    return { ok: false, path: helperPath, error: err instanceof Error ? err.message : String(err) };
  }
}

async function runGoalOsSystemRunCanary(nodeId: string, repoPath: string) {
  const command = "pwd + git status --short";
  if (!nodeId) {
    return { ok: false, command, nodeId: "", summary: "connected node 缺少 nodeId，无法执行 system.run canary。" };
  }
  const gitStatusHelper = ensureGoalOsGitStatusHelper();
  const pwdResult = await runGoalOsCommand(
    "openclaw-cn",
    [
      "nodes",
      "run",
      "--node",
      nodeId,
      "--cwd",
      repoPath,
      "--ask",
      "off",
      "--security",
      "allowlist",
      "--command-timeout",
      "8000",
      "--timeout",
      "12000",
      "--json",
      "pwd",
    ],
    repoPath,
    14_000,
  );
  const gitResult = pwdResult.ok && gitStatusHelper.ok ? await runGoalOsCommand(
    "openclaw-cn",
    [
      "nodes",
      "run",
      "--node",
      nodeId,
      "--cwd",
      repoPath,
      "--ask",
      "off",
      "--security",
      "allowlist",
      "--command-timeout",
      "8000",
      "--timeout",
      "12000",
      "--json",
      gitStatusHelper.path,
    ],
    repoPath,
    14_000,
  ) : {
    ok: false,
    stdout: "",
    stderr: "",
    code: null,
    error: pwdResult.ok ? `git_status_helper_failed: ${gitStatusHelper.error}` : "pwd_canary_failed",
  };
  const text = `${pwdResult.stdout}\n${pwdResult.stderr}\n${pwdResult.error}\n${gitResult.stdout}\n${gitResult.stderr}\n${gitResult.error}`.trim();
  const clean = goalOsPublicError(text, 900);
  return {
    ok: pwdResult.ok && gitResult.ok && text.includes(repoPath),
    command,
    nodeId,
    summary: pwdResult.ok && gitResult.ok ? `system.run canary 已执行：${command}` : `system.run canary 失败：${clean || "unknown_error"}`,
  };
}

function windowlessTimeout(handler: () => void, timeoutMs: number) {
  return setTimeout(handler, timeoutMs);
}

function goalOsCurrentEnv() {
  const explicit = String(process.env.OPENCLAW_WORKBENCH_ENV || process.env.NODE_ENV || "").trim();
  if (explicit) return explicit;
  if (Number(PORT) === 38888) return "prod";
  if (Number(PORT) === 38890) return "staging";
  return "dev";
}

async function runGoalOsPreflight(goalInput: string | Record<string, unknown> | null, input: { action?: string; activeAgentId?: string; subtaskId?: string; requireDispatchReady?: boolean } = {}): Promise<GoalOsPreflightResult> {
  const goal = typeof goalInput === "string" ? developmentGoalById(goalInput) : goalInput;
  const generatedAt = nowIso();
  const checks: GoalOsPreflightCheck[] = [];
  if (!goal) {
    addGoalOsCheck(checks, "goal_contract", "Goal Contract", "failed", "目标不存在，不能进入 Goal Run。");
    return {
      ok: false,
      status: "blocked",
      generatedAt,
      action: String(input.action || "preflight"),
      activeAgentId: normalizeDevelopmentAgentId(String(input.activeAgentId || "")),
      projectId: "",
      goalId: typeof goalInput === "string" ? goalInput : "",
      subtaskId: String(input.subtaskId || ""),
      repoPath: "",
      env: goalOsCurrentEnv(),
      gitDirtyCount: 0,
      checks,
      blockers: ["目标不存在，不能进入 Goal Run。"],
      repairActions: ["重新选择目标或创建 Goal Intake。"],
      forbiddenActions: ["dispatch_agent", "run_subtask", "auto_continue"],
    };
  }

  const projectId = String(goal.projectId || "");
  const goalId = String(goal.id || "");
  const action = String(input.action || "preflight");
  const activeAgentId = normalizeDevelopmentAgentId(String(input.activeAgentId || ""));
  const profile = db.prepare("SELECT repo_path, task_dir, preview_url FROM development_project_profiles WHERE project_id = ?").get(projectId) as Record<string, unknown> | undefined;
  let repoPath = String(profile?.repo_path || WORKSPACE_DIR);
  let repoFallback = false;
  if (!fs.existsSync(repoPath) && fs.existsSync(WORKSPACE_DIR)) {
    repoPath = WORKSPACE_DIR;
    repoFallback = true;
  }
  const baseline = developmentBaselineBundle(projectId);
  const pointers = developmentGoalRuntimePointers(projectId, goal as { activeWorkPacketId?: string; activeSubtaskId?: string });
  const subtask = input.subtaskId ? developmentSubtaskById(input.subtaskId) : pointers.activeSubtask || baseline?.currentSubtask || null;
  const subtaskId = String(subtask?.id || input.subtaskId || "");
  const blockers = parseJsonArray((goal as Record<string, unknown>).blockers).map(String).filter(Boolean);
  const tokenBudget = (goal as Record<string, unknown>).tokenBudget === null || (goal as Record<string, unknown>).tokenBudget === undefined ? null : Number((goal as Record<string, unknown>).tokenBudget);
  const tokensUsed = Number((goal as Record<string, unknown>).tokensUsed || 0);
  const envName = goalOsCurrentEnv();

  addGoalOsCheck(checks, "goal_contract", "Goal Contract", "passed", `目标锁定：${String((goal as Record<string, unknown>).title || goalId).slice(0, 90)}`);
  if (String((goal as Record<string, unknown>).status || "") === "completed") {
    addGoalOsCheck(checks, "goal_status", "Goal Status", "failed", "目标已完成，不允许继续派发。");
  } else if (String((goal as Record<string, unknown>).status || "") === "paused" && action !== "resume") {
    addGoalOsCheck(checks, "goal_status", "Goal Status", "failed", "目标已暂停，只允许 resume。");
  } else if (blockers.length) {
    addGoalOsCheck(checks, "goal_status", "Goal Status", "failed", `目标仍有阻塞：${blockers[0]}`);
  } else {
    addGoalOsCheck(checks, "goal_status", "Goal Status", "passed", `状态可继续：${String((goal as Record<string, unknown>).status || "active")}`);
  }

  const repoExists = fs.existsSync(repoPath);
  addGoalOsCheck(
    checks,
    "repo_cwd",
    "Repo CWD",
    repoExists ? (repoFallback ? "warn" : "passed") : "failed",
    repoExists ? `工作目录可读：${repoPath}` : `工作目录不可读：${repoPath}`,
    repoFallback ? `profile.repo_path 不存在，已回退到 ${WORKSPACE_DIR}` : "",
  );

  let gitDirtyCount = 0;
  if (repoExists) {
    const git = await runGoalOsCommand("git", ["status", "--short"], repoPath, 4_000);
    gitDirtyCount = git.ok ? git.stdout.split(/\r?\n/).filter(Boolean).length : 0;
    addGoalOsCheck(
      checks,
      "git_status",
      "Git Status",
      git.ok ? (gitDirtyCount ? "warn" : "passed") : "failed",
      git.ok ? `${gitDirtyCount} 个未提交变更；可继续但必须在证据中展示 diff。` : `git status 失败：${goalOsPublicError(git.error)}`,
    );
  }

  const baselineReady = String(baseline?.status || "") === "locked";
  const needsDispatchReady = Boolean(input.requireDispatchReady);
  addGoalOsCheck(
    checks,
    "baseline",
    "Baseline",
    baselineReady && subtask ? "passed" : needsDispatchReady ? "failed" : "warn",
    baselineReady && subtask
      ? `串行基线已锁定，当前子任务：${String(subtask.sequence).padStart(3, "0")} ${subtask.title}`
      : "尚未具备可派发的锁定基线或当前子任务；只能做 intake/planning，不能派发 agent。",
  );

  if (tokenBudget !== null && tokenBudget > 0 && tokensUsed >= tokenBudget) {
    addGoalOsCheck(checks, "token_budget", "Token Budget", "failed", `token budget 已耗尽：${tokensUsed}/${tokenBudget}`);
  } else {
    addGoalOsCheck(checks, "token_budget", "Token Budget", tokenBudget ? "passed" : "warn", tokenBudget ? `预算可用：${tokensUsed}/${tokenBudget}` : `未设置预算；当前估算 ${tokensUsed}`);
  }

  const gateway = await gatewayControl("status", { timeoutMs: 5_000, serializeCli: true });
  addGoalOsCheck(
    checks,
    "gateway",
    "Gateway",
    gateway.ok ? "passed" : "failed",
    gateway.ok ? "Gateway status 可用。" : `Gateway 不可用：${goalOsPublicError(gateway.error || gateway.stderr || gateway.stdout)}`,
  );

  const nodeStatus = await runGoalOsCommand("openclaw-cn", ["node", "status", "--json"], repoPath || WORKSPACE_DIR, 5_000);
  const nodesStatus = await runGoalOsCommand("openclaw-cn", ["nodes", "status", "--json"], repoPath || WORKSPACE_DIR, 5_000);
  const nodeText = `${nodeStatus.stdout}\n${nodeStatus.stderr}\n${nodesStatus.stdout}\n${nodesStatus.stderr}`;
  const nodeJson = goalOsJsonObject(nodeStatus.stdout);
  const nodesJson = goalOsJsonObject(nodesStatus.stdout);
  const nodeRows = goalOsNodeRows(nodesJson);
  const connectedNodeRows = nodeRows.filter((row) => row.connected === true || /connected/i.test(String(row.status || "")));
  const nodeReady = nodeStatus.ok && goalOsNodeHostLoaded(nodeJson, nodeText) && connectedNodeRows.length > 0 && !/SYSTEM_RUN_DENIED|no shell access|denied/i.test(nodeText);
  const systemRunReady = nodesStatus.ok && connectedNodeRows.some((row) => goalOsCommandList(row).some((item) => item === "system.run" || item.endsWith(":system.run"))) && !/SYSTEM_RUN_DENIED|no shell access|unavailable|denied/i.test(nodeText);
  const nodeSummary = summarizeGoalOsNodeHost(nodeStatus, nodesStatus, nodeJson, nodesJson, nodeText);
  const systemRunSummary = summarizeGoalOsSystemRun(nodesJson, nodeText);
  const systemRunNodeId = goalOsNodeId(connectedNodeRows.find((row) => goalOsCommandList(row).some((item) => item === "system.run" || item.endsWith(":system.run"))) || {});
  const systemRunCanary = systemRunReady ? await runGoalOsSystemRunCanary(systemRunNodeId, repoPath || WORKSPACE_DIR) : null;
  addGoalOsCheck(
    checks,
    "node_host",
    "Node Host",
    nodeReady ? "passed" : "failed",
    nodeReady ? nodeSummary : nodeSummary,
    goalOsPublicError(nodeText, 900),
  );
  addGoalOsCheck(
    checks,
    "system_run",
    "system.run",
    systemRunReady ? "passed" : "failed",
    systemRunReady ? systemRunSummary : `${systemRunSummary} 禁止派发编码任务。`,
    goalOsPublicError(nodesStatus.error || nodesStatus.stderr || nodesStatus.stdout || nodeText, 900),
  );
  addGoalOsCheck(
    checks,
    "system_run_canary",
    "system.run Canary",
    systemRunReady ? (systemRunCanary?.ok ? "passed" : "failed") : "failed",
    systemRunReady
      ? (systemRunCanary?.summary || "system.run canary 未返回结果。")
      : "system.run capability 未通过，跳过 canary；禁止派发编码任务。",
  );

  const envStatus: GoalOsPreflightStatus = /prod/i.test(envName) ? "warn" : "passed";
  addGoalOsCheck(checks, "environment", "Environment", envStatus, /prod/i.test(envName) ? "当前是 PROD 口，只允许只读验证或 NJX 授权写入。" : `环境：${envName}`);

  const failed = checks.filter((check) => check.status === "failed");
  const warnings = checks.filter((check) => check.status === "warn");
  const ok = failed.length === 0;
  const repairActions = failed.map((check) => {
    if (check.key === "gateway") return "恢复 Gateway，再重跑 Goal OS preflight。";
    if (check.key === "node_host") return "需要 NJX 明确批准后安装/启动 openclaw-cn node host；确认 com.clawdbot.node loaded 且 connected。";
    if (check.key === "system_run") return "修复 connected node 的 system.run 能力；canary 通过前禁止派发，也不要让 OpenClaw 写代码。";
    if (check.key === "system_run_canary") return "system.run capability 必须通过真实 pwd + git status canary；失败前禁止派发。";
    if (check.key === "repo_cwd") return "修正项目 repo_path 到 /Users/njx/openclaw/copilot。";
    if (check.key === "baseline") return "生成并锁定基线，选择当前子任务后再派发。";
    if (check.key === "goal_status") return "处理目标阻塞或 resume 目标。";
    return check.summary;
  });
  return {
    ok,
    status: ok ? (warnings.length ? "degraded" : "ready") : "blocked",
    generatedAt,
    action,
    activeAgentId,
    projectId,
    goalId,
    subtaskId,
    repoPath,
    env: envName,
    gitDirtyCount,
    checks,
    blockers: failed.map((check) => check.summary),
    repairActions: [...new Set(repairActions)].slice(0, 8),
    forbiddenActions: ok ? [] : ["dispatch_agent", "run_subtask", "auto_continue"],
    canary: systemRunCanary || undefined,
  };
}

function buildGoalResumeManifest(goalInput: string | Record<string, unknown> | null, input: { action?: string; activeAgentId?: string; preflight?: GoalOsPreflightResult; subtaskId?: string } = {}) {
  const goal = typeof goalInput === "string" ? developmentGoalById(goalInput) : goalInput;
  if (!goal) return null;
  const projectId = String(goal.projectId || "");
  const goalId = String(goal.id || "");
  const pointers = developmentGoalRuntimePointers(projectId, goal as { activeWorkPacketId?: string; activeSubtaskId?: string });
  const latestEvent = db.prepare(`
    SELECT event_type, actor, severity, message, created_at
    FROM development_run_events
    WHERE project_id = ?
    ORDER BY created_at DESC
    LIMIT 1
  `).get(projectId) as Record<string, unknown> | undefined;
  const artifacts = developmentArtifacts(projectId, "", 12).map((artifact) => ({
    id: artifact.id,
    type: artifact.type,
    title: artifact.title,
    path: artifact.path,
    createdAt: artifact.createdAt,
  }));
  const contextManifest = developmentLatestContextManifest(projectId);
  const continuation = developmentGoalContinuationContract(goalId);
  const activeSubtask = input.subtaskId ? developmentSubtaskById(input.subtaskId) : pointers.activeSubtask;
  return {
    version: "goal-os-v1",
    generatedAt: nowIso(),
    action: String(input.action || "preflight"),
    activeAgentId: normalizeDevelopmentAgentId(String(input.activeAgentId || "")),
    goal: {
      id: goalId,
      projectId,
      title: String(goal.title || ""),
      status: String(goal.status || ""),
      nextAction: String(goal.nextAction || ""),
      blockers: parseJsonArray((goal as Record<string, unknown>).blockers),
      successCriteria: parseJsonArray((goal as Record<string, unknown>).successCriteria),
    },
    activeSubtask: activeSubtask ? {
      id: activeSubtask.id,
      sequence: activeSubtask.sequence,
      title: activeSubtask.title,
      status: activeSubtask.status,
      ownerAgentId: activeSubtask.ownerAgentId,
      planPath: activeSubtask.planPath,
      resultPath: activeSubtask.resultPath,
    } : null,
    preflight: input.preflight ? {
      ok: input.preflight.ok,
      status: input.preflight.status,
      blockers: input.preflight.blockers,
      repairActions: input.preflight.repairActions,
      generatedAt: input.preflight.generatedAt,
    } : null,
    continuation: continuation ? {
      status: String((continuation as Record<string, unknown>).status || (continuation as Record<string, unknown>).readinessLabel || ""),
      resumeCommand: String((continuation as Record<string, unknown>).resumeCommand || (continuation as Record<string, unknown>).nextCommand || ""),
      nextAction: String((continuation as Record<string, unknown>).nextAction || (continuation as Record<string, unknown>).nextPrompt || (continuation as Record<string, unknown>).currentFocus || ""),
      blockers: parseJsonArray((continuation as Record<string, unknown>).blockers),
      requiredEvidence: parseJsonArray((continuation as Record<string, unknown>).requiredEvidence),
    } : null,
    lastEvent: latestEvent ? {
      eventType: String(latestEvent.event_type || ""),
      actor: String(latestEvent.actor || ""),
      severity: String(latestEvent.severity || ""),
      message: String(latestEvent.message || ""),
      createdAt: String(latestEvent.created_at || ""),
    } : null,
    context: contextManifest ? {
      id: contextManifest.id,
      status: contextManifest.status,
      summary: contextManifest.summary,
      createdAt: contextManifest.createdAt,
    } : null,
    artifacts,
  };
}

function goalResumeManifestMarkdown(manifest: ReturnType<typeof buildGoalResumeManifest>) {
  if (!manifest) return "";
  const goal = manifest.goal;
  const subtask = manifest.activeSubtask;
  return [
    "# Goal Resume Manifest",
    "",
    `Generated: ${manifest.generatedAt}`,
    `Version: ${manifest.version}`,
    `Action: ${manifest.action}`,
    "",
    "## Goal Contract",
    `- Goal: ${goal.title}`,
    `- Status: ${goal.status}`,
    `- Next action: ${goal.nextAction || "未设置"}`,
    "",
    "## Preflight",
    `- Status: ${manifest.preflight?.status || "unknown"}`,
    `- OK: ${manifest.preflight?.ok ? "true" : "false"}`,
    ...(manifest.preflight?.blockers?.length ? manifest.preflight.blockers.map((item: string) => `- Blocker: ${item}`) : ["- Blocker: none"]),
    "",
    "## Active Subtask",
    subtask ? `- ${String(subtask.sequence).padStart(3, "0")} ${subtask.title} (${subtask.status})` : "- No active subtask",
    "",
    "## Last Event",
    manifest.lastEvent ? `- ${manifest.lastEvent.eventType} · ${manifest.lastEvent.actor} · ${manifest.lastEvent.message}` : "- No event",
    "",
    "## Artifacts",
    ...(manifest.artifacts.length ? manifest.artifacts.map((artifact) => `- ${artifact.type}: ${artifact.title} · ${artifact.path}`) : ["- None"]),
  ].join("\n");
}

function developmentGoalRunView(row: Record<string, unknown>) {
  return {
    id: String(row.id || ""),
    goalId: String(row.goal_id || ""),
    projectId: String(row.project_id || ""),
    subtaskId: String(row.subtask_id || ""),
    developmentRunId: String(row.development_run_id || ""),
    action: String(row.action || ""),
    status: String(row.status || ""),
    activeAgentId: String(row.active_agent_id || ""),
    preflight: safeJsonObject(row.preflight_json),
    resumeManifest: safeJsonObject(row.resume_manifest_json),
    evidencePack: safeJsonObject(row.evidence_pack_json),
    dispatchError: String(row.dispatch_error || ""),
    tokenBudget: row.token_budget === null || row.token_budget === undefined ? null : Number(row.token_budget),
    tokensUsed: Number(row.tokens_used || 0),
    createdAt: String(row.created_at || ""),
    updatedAt: String(row.updated_at || ""),
    completedAt: String(row.completed_at || ""),
  };
}

function createGoalRunLedgerEntry(input: {
  goal: Record<string, unknown>;
  action: string;
  status: "preflight_ready" | "blocked_preflight" | "dispatched" | "background_running" | "completed" | "failed";
  activeAgentId?: string;
  subtaskId?: string;
  developmentRunId?: string;
  preflight?: GoalOsPreflightResult;
  resumeManifest?: Record<string, unknown> | null;
  evidencePack?: Record<string, unknown> | null;
  dispatchError?: string;
}) {
  const now = nowIso();
  const goalId = String(input.goal.id || "");
  const projectId = String(input.goal.projectId || "");
  const id = `goal-run-${safeName(goalId).toLowerCase()}-${Date.now()}-${randomUUID().slice(0, 8)}`;
  db.prepare(`
    INSERT INTO development_goal_runs (id, goal_id, project_id, subtask_id, development_run_id, action, status, active_agent_id, preflight_json, resume_manifest_json, evidence_pack_json, dispatch_error, token_budget, tokens_used, created_at, updated_at, completed_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `).run(
    id,
    goalId,
    projectId,
    String(input.subtaskId || ""),
    String(input.developmentRunId || ""),
    input.action,
    input.status,
    normalizeDevelopmentAgentId(String(input.activeAgentId || "")),
    JSON.stringify(input.preflight || {}),
    JSON.stringify(input.resumeManifest || {}),
    JSON.stringify(input.evidencePack || {}),
    String(input.dispatchError || ""),
    input.goal.tokenBudget === null || input.goal.tokenBudget === undefined ? null : Number(input.goal.tokenBudget || 0),
    Number(input.goal.tokensUsed || 0),
    now,
    now,
    input.status === "completed" || input.status === "failed" || input.status === "blocked_preflight" ? now : null,
  );
  const row = db.prepare("SELECT * FROM development_goal_runs WHERE id = ?").get(id) as Record<string, unknown>;
  return developmentGoalRunView(row);
}

function updateGoalRunLedgerEntry(goalRunId: string, patch: { status?: string; developmentRunId?: string; dispatchError?: string; evidencePack?: Record<string, unknown> | null; completed?: boolean }) {
  if (!goalRunId) return null;
  const row = db.prepare("SELECT * FROM development_goal_runs WHERE id = ?").get(goalRunId) as Record<string, unknown> | undefined;
  if (!row) return null;
  const now = nowIso();
  db.prepare(`
    UPDATE development_goal_runs
    SET status = ?, development_run_id = ?, dispatch_error = ?, evidence_pack_json = ?, updated_at = ?, completed_at = CASE WHEN ? THEN COALESCE(completed_at, ?) ELSE completed_at END
    WHERE id = ?
  `).run(
    String(patch.status || row.status || ""),
    String(patch.developmentRunId ?? row.development_run_id ?? ""),
    String(patch.dispatchError ?? row.dispatch_error ?? ""),
    JSON.stringify(patch.evidencePack || safeJsonObject(row.evidence_pack_json)),
    now,
    patch.completed ? 1 : 0,
    now,
    goalRunId,
  );
  const next = db.prepare("SELECT * FROM development_goal_runs WHERE id = ?").get(goalRunId) as Record<string, unknown>;
  return developmentGoalRunView(next);
}

function developmentGoalRuns(goalId: string, limit = 12) {
  return (db.prepare("SELECT * FROM development_goal_runs WHERE goal_id = ? ORDER BY created_at DESC LIMIT ?").all(goalId, limit) as Array<Record<string, unknown>>).map(developmentGoalRunView);
}

function updateLatestGoalRunEvidence(goalId: string, evidencePack: Record<string, unknown>, status?: string) {
  const row = db.prepare("SELECT id FROM development_goal_runs WHERE goal_id = ? ORDER BY created_at DESC LIMIT 1").get(goalId) as { id?: string } | undefined;
  if (!row?.id) return null;
  return updateGoalRunLedgerEntry(String(row.id), { status: status || undefined, evidencePack, completed: Boolean(status && ["completed", "failed", "blocked_preflight"].includes(status)) });
}

function buildGoalOsProjectState(projectId: string, activeGoal?: Record<string, unknown> | null) {
  const row = activeGoal
    ? db.prepare("SELECT * FROM development_goal_runs WHERE goal_id = ? ORDER BY created_at DESC LIMIT 1").get(String(activeGoal.id || "")) as Record<string, unknown> | undefined
    : db.prepare("SELECT * FROM development_goal_runs WHERE project_id = ? ORDER BY created_at DESC LIMIT 1").get(projectId) as Record<string, unknown> | undefined;
  const latestRun = row ? developmentGoalRunView(row) : null;
  const preflight = latestRun?.preflight || null;
  const status = latestRun?.status || (activeGoal ? "not_initialized" : "no_goal");
  const blocked = status === "blocked_preflight" || preflight?.ok === false;
  const preflightBlockers = Array.isArray(preflight?.blockers) ? preflight.blockers : [];
  return {
    contractVersion: "goal-os-v1",
    status,
    canDispatch: Boolean(preflight && preflight.ok === true && !blocked),
    blockingReason: blocked ? String(preflightBlockers[0] || latestRun?.dispatchError || "Goal OS preflight blocked") : "",
    latestRun,
    recentRuns: activeGoal ? developmentGoalRuns(String(activeGoal.id || ""), 5) : [],
    preflight,
    resumeManifest: latestRun?.resumeManifest || null,
    generatedAt: latestRun?.updatedAt || nowIso(),
  };
}

async function handleGoalOsPreflightRequest(req: FastifyRequest, reply: any) {
  ensureDevelopmentSeedData();
  const goalId = (req.params as { goalId: string }).goalId;
  const goal = developmentGoalById(goalId);
  if (!goal) return reply.code(404).send({ ok: false, error: "development_goal_not_found" });
  const query = ((req as { query?: unknown }).query || {}) as { dryRun?: string | boolean; persist?: string | boolean };
  const body = ((req as { body?: unknown }).body || {}) as { action?: string; activeAgentId?: string; agentId?: string; subtaskId?: string; dryRun?: boolean };
  const action = String(body.action || (req.method === "GET" ? "preflight" : "dispatch"));
  const activeAgentId = normalizeDevelopmentAgentId(String(body.activeAgentId || body.agentId || ""));
  const dryRun = req.method === "GET"
    ? String(query.persist || "").toLowerCase() !== "1" && String(query.persist || "").toLowerCase() !== "true"
    : body.dryRun === true || String(query.dryRun || "").toLowerCase() === "1" || String(query.dryRun || "").toLowerCase() === "true";
  const preflight = await runGoalOsPreflight(goal, {
    action,
    activeAgentId,
    subtaskId: String(body.subtaskId || ""),
    requireDispatchReady: action === "dispatch" || action === "run_subtask",
  });
  const resumeManifest = buildGoalResumeManifest(goal, { action, activeAgentId, preflight, subtaskId: preflight.subtaskId });
  const status = preflight.ok ? "preflight_ready" : "blocked_preflight";
  if (dryRun) {
    return {
      ok: preflight.ok,
      error: preflight.ok ? "" : "goal_os_preflight_blocked",
      dryRun: true,
      persisted: false,
      preflight,
      goalRun: null,
      resumeManifest,
      artifact: null,
      detail: developmentProjectDetail(goal.projectId),
    };
  }
  const goalRun = createGoalRunLedgerEntry({
    goal,
    action,
    status,
    activeAgentId,
    subtaskId: preflight.subtaskId,
    preflight,
    resumeManifest,
  });
  const artifact = resumeManifest ? persistDevelopmentGoalArtifact({
    projectId: goal.projectId,
    goalId: goal.id,
    artifactType: "goal_resume_manifest",
    title: "Goal OS Resume Manifest",
    markdown: goalResumeManifestMarkdown(resumeManifest),
    evidenceLevel: preflight.ok ? "goal_handoff" : "blocked_preflight",
    metadata: { goalRunId: goalRun.id, preflightStatus: preflight.status },
  }) : null;
  developmentEvent({
    projectId: goal.projectId,
    subtaskId: preflight.subtaskId || null,
    eventType: preflight.ok ? "goal_os_preflight_ready" : "goal_os_preflight_blocked",
    actor: "goal_os",
    severity: preflight.ok ? "info" : "warn",
    message: preflight.ok ? "Goal OS preflight 通过，可进入派发前确认。" : `Goal OS preflight 阻塞：${preflight.blockers[0] || "执行通道不可用"}`,
    payload: { goalId, goalRunId: goalRun.id, preflight, resumeManifestId: artifact?.id || "" },
  });
  if (preflight.ok) {
    const exactAcceptanceEvidence = [
      "gateway connected",
      "node connected",
      "system.run canary passes",
      `repo cwd matches ${preflight.repoPath}`,
      "evidence pack can be loaded",
    ].join(" · ");
    const heartbeatAt = nowIso();
    const nextEvidence = developmentGoalEvidence(
      goal.evidence,
      `${heartbeatAt} · Goal OS preflight passed · ${exactAcceptanceEvidence} · goalRun=${goalRun.id}`,
    );
    db.prepare(`
      UPDATE development_goals
      SET last_heartbeat_at = ?, next_action = ?, evidence = ?, updated_at = ?
      WHERE id = ?
    `).run(
      heartbeatAt,
      "Goal OS preflight passed；可按当前子任务继续，派发前确认 PROD 写入授权。",
      nextEvidence,
      heartbeatAt,
      goal.id,
    );
  }
  developmentEvent({
    projectId: goal.projectId,
    subtaskId: preflight.subtaskId || null,
    eventType: "goal_os_resume_manifest_created",
    actor: "goal_os",
    severity: "info",
    message: "Goal OS resume manifest 已生成，后续 resume 不依赖聊天记忆。",
    payload: { goalId, goalRunId: goalRun.id, artifactId: artifact?.id || "" },
  });
  audit(db, "development.goal_os.preflight", "development_goal", goalId, preflight.ok ? "normal" : "high", { projectId: goal.projectId, status: preflight.status, blockers: preflight.blockers, goalRunId: goalRun.id });
  return {
    ok: preflight.ok,
    error: preflight.ok ? "" : "goal_os_preflight_blocked",
    preflight,
    goalRun,
    resumeManifest,
    artifact,
    detail: developmentProjectDetail(goal.projectId),
  };
}

function developmentGoalEvidence(current: unknown, line: string) {
  const next = parseJsonArray(current).map(String).filter(Boolean);
  next.unshift(line);
  return JSON.stringify([...new Set(next)].slice(0, 12));
}

function developmentMarkdownList(items: unknown[], empty = "- 无") {
  const rows = items.map((item) => String(item || "").trim()).filter(Boolean);
  return rows.length ? rows.map((item) => `- ${item.replace(/\s+/g, " ")}`).join("\n") : empty;
}

function persistDevelopmentGoalArtifact(input: {
  projectId: string;
  goalId: string;
  artifactType: string;
  title: string;
  markdown: string;
  evidenceLevel?: string;
  metadata?: Record<string, unknown>;
}) {
  const workspace = developmentProjectWorkspace(input.projectId);
  const baseDir = workspace?.artifactsDir || path.join(developmentProjectWorkspacePath(input.projectId), "artifacts");
  const artifactKey = safeName(input.artifactType).toLowerCase() || "goal-artifact";
  const goalKey = safeName(input.goalId).toLowerCase() || "goal";
  const artifactDir = path.join(baseDir, "goals", goalKey);
  fs.mkdirSync(artifactDir, { recursive: true });
  const filePath = path.join(artifactDir, `${artifactKey}.md`);
  fs.writeFileSync(filePath, input.markdown);
  const now = nowIso();
  const artifactId = `artifact-goal-${goalKey}-${artifactKey}`;
  db.prepare(`
    INSERT INTO development_artifacts (id, project_id, run_id, task_id, artifact_type, title, path, url, status, evidence_level, metadata, created_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(id) DO UPDATE SET
      artifact_type = excluded.artifact_type,
      title = excluded.title,
      path = excluded.path,
      url = excluded.url,
      status = excluded.status,
      evidence_level = excluded.evidence_level,
      metadata = excluded.metadata,
      created_at = excluded.created_at
  `).run(
    artifactId,
    input.projectId,
    null,
    null,
    input.artifactType,
    input.title,
    filePath,
    `/api/development/artifacts/${encodeURIComponent(artifactId)}/raw`,
    "available",
    input.evidenceLevel || "goal_handoff",
    JSON.stringify({ goalId: input.goalId, source: "development_goal_mode", ...(input.metadata || {}) }),
    now,
  );
  return {
    id: artifactId,
    type: input.artifactType,
    title: input.title,
    path: filePath,
    rawUrl: `/api/development/artifacts/${encodeURIComponent(artifactId)}/raw`,
    createdAt: now,
  };
}

function developmentGoalEvidencePackMarkdown(pack: ReturnType<typeof developmentGoalEvidencePack>) {
  if (!pack) return "";
  return [
    "# Goal Evidence Pack",
    "",
    `Generated: ${pack.generatedAt}`,
    `Goal: ${pack.goalId}`,
    `Coverage: ${pack.coverageScore}/100`,
    "",
    "## Summary",
    pack.summary,
    "",
    "## Counts",
    developmentMarkdownList([
      `Criteria: ${pack.counts.coveredCriteria}/${pack.counts.criteria}`,
      `Artifacts: ${pack.counts.artifacts}`,
      `Gates: ${pack.counts.gates} (${pack.counts.failedGates} failed)`,
      `Evidence events: ${pack.counts.evidenceEvents}`,
    ]),
    "",
    "## Coverage",
    developmentMarkdownList(pack.coverage.map((item) => `${item.covered ? "PASS" : "MISSING"} · ${item.criterion} · ${item.evidence}`)),
    "",
    "## Missing Evidence",
    developmentMarkdownList(pack.missingEvidence),
    "",
    "## Blockers",
    developmentMarkdownList(pack.blockers),
    "",
    "## Artifacts",
    developmentMarkdownList(pack.artifacts.map((artifact) => `${artifact.type} · ${artifact.title} · ${artifact.path || artifact.url || artifact.status}`)),
    "",
    "## Gates",
    developmentMarkdownList(pack.gates.map((gate) => `${gate.label} · ${gate.status} · ${gate.evidence || gate.severity}`)),
    "",
    "## Events",
    developmentMarkdownList(pack.events.map((event) => `${event.createdAt} · ${event.actor} · ${event.type} · ${event.message}`)),
  ].join("\n");
}

function developmentGoalCompletionAuditMarkdown(auditResult: ReturnType<typeof developmentGoalCompletionAudit>) {
  if (!auditResult) return "";
  return [
    "# Goal Completion Audit",
    "",
    `Generated: ${auditResult.generatedAt}`,
    `Goal: ${auditResult.goalId}`,
    `Result: ${auditResult.passed ? "PASSED" : "FAILED"} · ${auditResult.score}/100`,
    "",
    "## Next Action",
    auditResult.nextAction,
    "",
    "## Checks",
    developmentMarkdownList(auditResult.checks.map((check) => `${check.passed ? "PASS" : "FAIL"} · ${check.label} · ${check.evidence}`)),
    "",
    "## Criteria Coverage",
    developmentMarkdownList(auditResult.criteriaCoverage.map((item) => `${item.covered ? "PASS" : "MISSING"} · ${item.criterion} · ${item.matched}/${item.total}`)),
  ].join("\n");
}

function developmentGoalRuntimePointers(projectId: string, goal?: { activeWorkPacketId?: string; activeSubtaskId?: string }) {
  const activeWorkPacket = goal?.activeWorkPacketId ? developmentWorkPacketById(goal.activeWorkPacketId) : developmentActiveWorkPacket(projectId);
  const baseline = developmentBaselineBundle(projectId);
  const activeSubtask = goal?.activeSubtaskId ? developmentSubtaskById(goal.activeSubtaskId) : baseline?.currentSubtask || null;
  return {
    activeWorkPacket,
    baseline,
    activeSubtask: activeSubtask && activeSubtask.projectId === projectId ? activeSubtask : baseline?.currentSubtask || null,
  };
}

function createDevelopmentGoal(projectId: string, body: { title?: string; objective?: string; autonomyLevel?: string; tokenBudget?: number | string | null; successCriteria?: unknown; nextAction?: string; activeWorkPacketId?: string; activeSubtaskId?: string; heartbeatIntervalMinutes?: number | string | null; maxAutoTurns?: number | string | null; riskPolicy?: string; stopConditions?: unknown; metadata?: string | Record<string, unknown> }) {
  const now = nowIso();
  const project = db.prepare("SELECT p.name, p.objective, dp.objective dev_objective FROM projects p JOIN development_project_profiles dp ON dp.project_id = p.id WHERE p.id = ?").get(projectId) as Record<string, unknown> | undefined;
  if (!project) return null;
  const pointers = developmentGoalRuntimePointers(projectId, {
    activeWorkPacketId: String(body.activeWorkPacketId || ""),
    activeSubtaskId: String(body.activeSubtaskId || ""),
  });
  const title = String(body.title || `${String(project.name || projectId)} 持续开发目标`).slice(0, 180);
  const objective = String(body.objective || project.dev_objective || project.objective || title);
  const criteria = developmentStringList(body.successCriteria, [
    "目标、PRD、PLAN/RESULT 和验收证据可追溯",
    "每轮继续执行都写入事件账本",
    "Gateway 慢或不可用时转后台/阻塞态，不假装完成",
    "高风险动作进入人工审批",
  ]);
  const tokenBudget = body.tokenBudget === null || body.tokenBudget === undefined || body.tokenBudget === "" ? null : Math.max(0, Number(body.tokenBudget || 0));
  const heartbeatIntervalMinutes = Math.max(5, Math.min(240, Number(body.heartbeatIntervalMinutes || 30)));
  const maxAutoTurns = Math.max(1, Math.min(12, Number(body.maxAutoTurns || 3)));
  const stopConditions = developmentStringList(body.stopConditions, ["遇到阻塞停止", "质量门失败停止", "高风险动作停止"]);
  const id = `goal-${projectId}-${Date.now()}-${randomUUID().slice(0, 8)}`;
  // Sprint2.5: 解析 body.metadata, string 直接存, object 转 string, 缺失默认 {}
  const metaRaw = body.metadata;
  const metaJson = typeof metaRaw === "string" ? metaRaw : (metaRaw && typeof metaRaw === "object" ? JSON.stringify(metaRaw) : "{}");
  db.prepare(`
    INSERT INTO development_goals (id, project_id, title, objective, status, autonomy_level, active_work_packet_id, active_subtask_id, token_budget, tokens_used, turn_count, heartbeat_count, auto_run_enabled, heartbeat_interval_minutes, max_auto_turns, auto_turns_used, risk_policy, stop_conditions, last_auto_run_at, last_heartbeat_at, next_heartbeat_at, next_action, blockers, success_criteria, evidence, created_at, updated_at, completed_at, metadata)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `).run(
    id,
    projectId,
    title,
    objective,
    "active",
    String(body.autonomyLevel || "supervised"),
    pointers.activeWorkPacket?.id || null,
    pointers.activeSubtask?.id || null,
    tokenBudget,
    0,
    0,
    0,
    0,
    heartbeatIntervalMinutes,
    maxAutoTurns,
    0,
    String(body.riskPolicy || "low_risk_only"),
    JSON.stringify(stopConditions),
    null,
    null,
    null,
    String(body.nextAction || pointers.activeSubtask?.title || pointers.activeWorkPacket?.nextAction || "继续推进当前开发基线。"),
    "[]",
    JSON.stringify(criteria),
    JSON.stringify(["目标创建时已绑定当前项目、工作包、子任务和事件账本。"]),
    now,
    now,
    null,
    metaJson,
  );
  developmentEvent({ projectId, eventType: "goal_created", actor: "owner", severity: "info", message: `长期目标已创建：${title}`, payload: { goalId: id, activeSubtaskId: pointers.activeSubtask?.id || "", activeWorkPacketId: pointers.activeWorkPacket?.id || "" } });
  audit(db, "development.goal.create", "development_goal", id, "normal", { projectId, title });
  return developmentGoalById(id);
}

function buildDevelopmentGoalRecoveryPacket(goalId: string) {
  const goal = developmentGoalById(goalId);
  if (!goal) return null;
  const detail = developmentProjectDetail(goal.projectId);
  if (!detail) return null;
  const pointers = developmentGoalRuntimePointers(goal.projectId, goal);
  const activeSubtask = pointers.activeSubtask || detail.baseline?.currentSubtask || null;
  const activeWorkPacket = pointers.activeWorkPacket || detail.activeWorkPacket || null;
  const events = developmentEvents(goal.projectId, 16);
  const artifacts = developmentArtifacts(goal.projectId, "", 12);
  const gates = developmentGates(goal.projectId, "", 12);
  const blockers = [
    ...goal.blockers,
    ...(activeSubtask?.blockers || []),
    ...(activeWorkPacket?.blockers || []),
  ].filter(Boolean);
  const generatedAt = nowIso();
  const markdown = [
    `# OpenClaw Development Goal Recovery Packet`,
    ``,
    `Generated: ${generatedAt}`,
    `Project: ${detail.project.name} (${detail.project.id})`,
    `Goal: ${goal.title}`,
    `Status: ${goal.statusLabel} / ${goal.runtimeLabel}`,
    `Progress: ${goal.progressPercent}%`,
    `Autonomy: ${goal.autonomyLevel}`,
    ``,
    `## Objective`,
    goal.objective || "-",
    ``,
    `## Current Pointer`,
    `- Work packet: ${activeWorkPacket ? `${activeWorkPacket.title} (${activeWorkPacket.id})` : "none"}`,
    `- Subtask: ${activeSubtask ? `${String(activeSubtask.sequence).padStart(3, "0")} ${activeSubtask.title} (${activeSubtask.id})` : "none"}`,
    `- Baseline: ${detail.baseline ? `v${detail.baseline.version} · ${detail.baseline.status} · ${detail.baseline.progress.passed}/${detail.baseline.progress.total}` : "none"}`,
    `- Next action: ${goal.nextAction || activeSubtask?.title || activeWorkPacket?.nextAction || "Continue from the latest evidence."}`,
    ``,
    `## Success Criteria`,
    developmentMarkdownList(goal.successCriteria),
    ``,
    `## Blockers / Human Gates`,
    developmentMarkdownList([...new Set(blockers)]),
    ``,
    `## Runtime Evidence`,
    developmentMarkdownList(goal.runtimeEvidence || []),
    ``,
    `## Latest Events`,
    developmentMarkdownList(events.slice(0, 10).map((event) => `${event.createdAt} · ${event.actor} · ${event.type} · ${event.message}`)),
    ``,
    `## Artifacts`,
    developmentMarkdownList(artifacts.slice(0, 8).map((artifact) => `${artifact.type} · ${artifact.title} · ${artifact.path || artifact.url || artifact.status}`)),
    ``,
    `## Quality Gates`,
    developmentMarkdownList(gates.slice(0, 8).map((gate) => `${gate.label} · ${gate.status} · ${gate.evidence || gate.severity}`)),
    ``,
    `## Resume Contract`,
    `- Continue only from the active goal and active subtask above.`,
    `- Do not mark work complete without PLAN/RESULT, artifact, test/build, or explicit human evidence.`,
    `- If Gateway is slow or unavailable, keep the goal in running/waiting_feedback/stale and write an event instead of pretending success.`,
    `- High-risk operations require approval and audit.`,
  ].join("\n");
  return {
    goalId,
    projectId: goal.projectId,
    generatedAt,
    summary: `${goal.title} · ${goal.runtimeLabel} · ${goal.nextAction || "继续目标"}`,
    nextAction: goal.nextAction || activeSubtask?.title || activeWorkPacket?.nextAction || "",
    blockers: [...new Set(blockers)],
    markdown,
    events: events.slice(0, 10),
    artifacts: artifacts.slice(0, 8),
    gates: gates.slice(0, 8),
  };
}

function buildDevelopmentGoalDispatchRecovery(goalId: string, requestedReason = "") {
  const goal = developmentGoalById(goalId);
  if (!goal) return null;
  const detail = developmentProjectDetail(goal.projectId);
  if (!detail) return null;
  const pointers = developmentGoalRuntimePointers(goal.projectId, goal);
  const activeSubtask = pointers.activeSubtask || detail.baseline?.currentSubtask || null;
  const activeWorkPacket = pointers.activeWorkPacket || detail.activeWorkPacket || null;
  const events = developmentEvents(goal.projectId, 40);
  const latestDispatchFailure = events.find((event) => /OpenClaw\s*代理派发失败|代理派发失败|gateway_unavailable|Gateway\s*(暂不可用|不可用|failed|unavailable)|OpenClaw Gateway/i.test(`${event.type}\n${event.message}`));
  const reason = String(requestedReason || latestDispatchFailure?.message || goal.blockers.find((item) => /代理派发失败|gateway|Gateway/i.test(item)) || activeSubtask?.blockers.find((item) => /代理派发失败|gateway|Gateway/i.test(item)) || "OpenClaw 代理派发失败，当前目标不能确认已被代理接手。").slice(0, 900);
  const generatedAt = nowIso();
  const prompt = [
    "OpenClaw 开发台长期目标派发恢复请求",
    "",
    "背景：",
    `- Generated: ${generatedAt}`,
    `- 目标: ${goal.title} (${goal.id})`,
    `- 项目: ${detail.project.name} (${detail.project.id})`,
    `- 当前状态: ${goal.statusLabel} / ${goal.runtimeLabel}`,
    `- 当前子任务: ${activeSubtask ? `${String(activeSubtask.sequence).padStart(3, "0")} ${activeSubtask.title} (${activeSubtask.id})` : "none"}`,
    `- 当前工作包: ${activeWorkPacket ? `${activeWorkPacket.title} (${activeWorkPacket.id})` : "none"}`,
    `- 代理: ${activeSubtask?.ownerAgentId || detail.latestRun?.activeAgentId || "main"}`,
    `- 失败证据: ${reason}`,
    "",
    "路径：",
    `- PLAN: ${activeSubtask?.planPath || "未绑定"}`,
    `- RESULT: ${activeSubtask?.resultPath || "未绑定"}`,
    `- Evidence: ${activeSubtask?.evidenceDir || detail.workspace?.evidenceDir || "未绑定"}`,
    `- Artifacts: ${activeSubtask?.artifactsDir || detail.workspace?.artifactsDir || "未绑定"}`,
    "",
    "最近事件：",
    developmentMarkdownList(events.slice(0, 6).map((event) => `${event.createdAt} · ${event.actor} · ${event.type} · ${event.message}`), "- 暂无事件"),
    "",
    "恢复要求：",
    "1. 先判断 Gateway / OpenClaw 代理是否真实可用；不可用时保持 BLOCKED 或 DEGRADED，不得声明已执行完成。",
    "2. 如果可以继续，基于当前 PLAN、RESULT、事件和证据推进最小下一步，并写清 status、已做判断、下一步和所需证据。",
    "3. 如果不能自动恢复，输出可执行的人工恢复清单：需要修复的服务、要查看的日志、可重试的命令和不能做的高风险动作。",
    "4. 不要重启 OpenClaw Gateway，不要删除受保护文档，不要发送外部通知。",
  ].join("\n");
  return {
    goalId,
    projectId: goal.projectId,
    generatedAt,
    reason,
    summary: `代理派发恢复：${reason}`,
    nextAction: "处理 OpenClaw 代理派发失败：确认 Gateway/代理接手状态，必要时按恢复提示人工接管。",
    prompt,
    pointer: {
      workPacketId: activeWorkPacket?.id || "",
      workPacketTitle: activeWorkPacket?.title || "",
      subtaskId: activeSubtask?.id || "",
      subtaskTitle: activeSubtask ? `${String(activeSubtask.sequence).padStart(3, "0")} ${activeSubtask.title}` : "",
      baselineStatus: detail.baseline?.status || "",
      planPath: activeSubtask?.planPath || "",
      resultPath: activeSubtask?.resultPath || "",
      evidenceDir: activeSubtask?.evidenceDir || "",
    },
    events: events.slice(0, 8),
  };
}

function resolveDevelopmentGoalDispatchFailure(goalId: string, health: LiveGatewayHealthSnapshot) {
  const goal = developmentGoalById(goalId);
  if (!goal) return null;
  const detail = developmentProjectDetail(goal.projectId);
  if (!detail) return null;
  const now = nowIso();
  // 幂等检查：最近已存在 goal_dispatch_recovery_resolved 事件，且其后无新派发失败证据 → 仍清理干净
  // 但不重复写 audit / event，只在 payload 中标记 idempotent = true
  const recentEventsForIdempotency = developmentEvents(goal.projectId, 60);
  const latestResolvedBefore = recentEventsForIdempotency.find((event) => event.type === "goal_dispatch_recovery_resolved");
  const latestFailureAfterResolved = latestResolvedBefore
    ? recentEventsForIdempotency.find((event) =>
        DEVELOPMENT_GOAL_DISPATCH_FAILURE_RE.test(`${event.type}\n${event.message}`) &&
        event.severity === "warn" &&
        event.type !== "goal_dispatch_recovery_resolved" &&
        Date.parse(String(event.createdAt || "")) > Date.parse(String(latestResolvedBefore.createdAt || "")),
      )
    : null;
  const isIdempotent = Boolean(latestResolvedBefore) && !latestFailureAfterResolved;

  // 清理 goal blockers 中派发相关项
  const remainingBlockers = (goal.blockers || [])
    .filter((item) => !DEVELOPMENT_GOAL_DISPATCH_FAILURE_RE.test(item))
    .slice(0, 12);

  // 清理 activeSubtask blockers 中派发相关项（这是 snapshot 误报的另一来源）
  let subtaskCleanup: { subtaskId: string; previousBlockers: string[]; remainingBlockers: string[] } | null = null;
  if (goal.activeSubtaskId) {
    try {
      const subtaskRow = db.prepare("SELECT id, blockers FROM development_subtasks WHERE id = ?").get(goal.activeSubtaskId) as { id: string; blockers: string } | undefined;
      if (subtaskRow) {
        let subtaskBlockers: string[] = [];
        try { subtaskBlockers = JSON.parse(subtaskRow.blockers || "[]"); } catch { subtaskBlockers = []; }
        const remainingSubtaskBlockers = subtaskBlockers
          .filter((item) => !DEVELOPMENT_GOAL_DISPATCH_FAILURE_RE.test(String(item || "")))
          .slice(0, 12);
        if (remainingSubtaskBlockers.length !== subtaskBlockers.length) {
          subtaskCleanup = {
            subtaskId: subtaskRow.id,
            previousBlockers: subtaskBlockers,
            remainingBlockers: remainingSubtaskBlockers,
          };
          db.prepare("UPDATE development_subtasks SET blockers = ?, updated_at = ? WHERE id = ?")
            .run(JSON.stringify(remainingSubtaskBlockers), now, subtaskRow.id);
        }
      }
    } catch (err) {
      app.log.warn({ err, goalId, subtaskId: goal.activeSubtaskId }, "resolveDevelopmentGoalDispatchFailure: failed to clean subtask blockers");
    }
  }

  const nextStatus = goal.status === "completed"
    ? goal.status
    : remainingBlockers.length
      ? "blocked"
      : "active";
  const nextAction = remainingBlockers.length
    ? `Gateway health 已恢复，但仍有 ${remainingBlockers.length} 个 blocker 需要处理。`
    : "Gateway health 已恢复，继续按当前 PLAN/RESULT 推进最小下一步。";
  const evidenceLine = `${now} · 派发恢复已验证 · Gateway ${health.status || "connected"} · source=${health.source || "development_goal_dispatch_recovery"}`;
  db.prepare("UPDATE development_goals SET status = ?, blockers = ?, next_action = ?, evidence = ?, updated_at = ? WHERE id = ?")
    .run(
      nextStatus,
      JSON.stringify(remainingBlockers),
      nextAction,
      developmentGoalEvidence(goal.evidence || [], evidenceLine),
      now,
      goalId,
    );
  developmentEvent({
    projectId: goal.projectId,
    eventType: "goal_dispatch_recovery_resolved",
    actor: "main",
    severity: remainingBlockers.length ? "warn" : "info",
    message: `代理派发恢复已验证：${health.status || "connected"}；${nextAction}${isIdempotent ? "（幂等：此前已恢复）" : ""}`,
    payload: {
      goalId,
      previousStatus: goal.status,
      nextStatus,
      remainingBlockers,
      subtaskCleanup,
      health,
      idempotent: isIdempotent,
      previousResolvedAt: latestResolvedBefore ? String(latestResolvedBefore.createdAt || "") : null,
    },
  });
  audit(db, "development.goal.dispatch_recovery_resolved", "development_goal", goalId, remainingBlockers.length ? "high" : "normal", {
    projectId: goal.projectId,
    previousStatus: goal.status,
    nextStatus,
    remainingBlockerCount: remainingBlockers.length,
    subtaskCleanup,
    gatewayStatus: health.status,
    idempotent: isIdempotent,
  });
  return {
    goalId,
    projectId: goal.projectId,
    resolvedAt: now,
    previousStatus: goal.status,
    nextStatus,
    remainingBlockers,
    subtaskCleanup,
    idempotent: isIdempotent,
    nextAction,
    evidence: evidenceLine,
    detail: developmentProjectDetail(goal.projectId),
  };
}

function developmentGoalTimelinePhase(eventType: string, severity: string) {
  if (["goal_created"].includes(eventType)) return { phase: "created", label: "目标创建", tone: "info" };
  if (["goal_heartbeat", "goal_auto_tick"].includes(eventType)) return { phase: "running", label: eventType === "goal_auto_tick" ? "自动心跳" : "目标心跳", tone: "info" };
  if (["goal_auto_enabled", "goal_auto_disabled", "goal_auto_skipped"].includes(eventType)) return { phase: "autopilot", label: eventType === "goal_auto_skipped" ? "自动停顿" : "Autopilot", tone: eventType === "goal_auto_skipped" ? "warn" : "info" };
  if (["goal_completion_audit"].includes(eventType)) return { phase: "audit", label: "完成审计", tone: severity === "warn" ? "warn" : "info" };
  if (["goal_learning_review"].includes(eventType)) return { phase: "learning", label: "学习复盘", tone: severity === "warn" ? "warn" : "info" };
  if (["goal_recovery_packet"].includes(eventType)) return { phase: "recovery", label: "恢复包", tone: "info" };
  if (["goal_dispatch_recovery", "goal_dispatch_recovery_resolved"].includes(eventType)) return { phase: "recovery", label: eventType === "goal_dispatch_recovery_resolved" ? "派发已恢复" : "派发恢复", tone: eventType === "goal_dispatch_recovery_resolved" ? "info" : "warn" };
  if (["goal_continuation_contract"].includes(eventType)) return { phase: "continuation", label: "续跑契约", tone: severity === "warn" ? "warn" : "info" };
  if (["goal_operating_action"].includes(eventType)) return { phase: "action", label: "目标处置", tone: severity === "warn" ? "warn" : "info" };
  if (["goal_runway_refreshed"].includes(eventType)) return { phase: "runway", label: "目标跑道", tone: severity === "warn" ? "warn" : "info" };
  if (["goal_blocked", "blocker", "error"].includes(eventType) || severity === "warn") return { phase: "blocked", label: "停机/阻塞", tone: "warn" };
  if (["subtask_acceptance", "review"].includes(eventType)) return { phase: "review", label: "验收/评审", tone: "ok" };
  if (["artifact", "test", "tool_result"].includes(eventType)) return { phase: "evidence", label: "证据产出", tone: "ok" };
  if (["tool_call", "thinking"].includes(eventType)) return { phase: "working", label: "代理执行", tone: "info" };
  return { phase: "event", label: "开发事件", tone: severity === "warn" ? "warn" : "info" };
}

function developmentGoalEvidencePack(goalId: string) {
  const goal = developmentGoalById(goalId);
  if (!goal) return null;
  const detail = developmentProjectDetail(goal.projectId);
  if (!detail) return null;
  const artifacts = developmentArtifacts(goal.projectId, "", 80);
  const gates = developmentGates(goal.projectId, "", 80);
  const events = developmentEvents(goal.projectId, 120);
  const evidenceEvents = events.filter((event) => ["goal_heartbeat", "goal_auto_tick", "subtask_acceptance", "goal_completion_audit", "goal_learning_review", "goal_recovery_packet", "goal_dispatch_recovery", "goal_dispatch_recovery_resolved", "goal_operating_action", "artifact", "test", "review", "tool_result"].includes(event.type));
  const evidenceText = [
    goal.evidence.join("\n"),
    evidenceEvents.map((event) => `${event.type} ${event.actor} ${event.message}`).join("\n"),
    artifacts.map((artifact) => `${artifact.type} ${artifact.title} ${artifact.path} ${artifact.status}`).join("\n"),
    gates.map((gate) => `${gate.label} ${gate.status} ${gate.evidence}`).join("\n"),
  ].join("\n").toLowerCase();
  const criteria = goal.successCriteria.length ? goal.successCriteria : ["目标存在成功标准"];
  const coverage = criteria.map((criterion) => {
    const tokens = criterion.toLowerCase().split(/[\s,，。；;、/]+/).filter((token) => token.length >= 2).slice(0, 7);
    const matched = tokens.filter((token) => evidenceText.includes(token));
    const bestEvent = evidenceEvents.find((event) => tokens.some((token) => `${event.message} ${event.type}`.toLowerCase().includes(token)));
    const bestArtifact = artifacts.find((artifact) => tokens.some((token) => `${artifact.type} ${artifact.title} ${artifact.path}`.toLowerCase().includes(token)));
    const directEvidenceCovered = matched.length >= Math.max(1, Math.ceil(tokens.length * 0.6));
    const covered = Boolean(bestArtifact || bestEvent || directEvidenceCovered);
    return {
      criterion,
      covered,
      matched: matched.length,
      total: Math.max(1, tokens.length),
      evidence: bestArtifact
        ? `${bestArtifact.type} · ${bestArtifact.title}`
        : bestEvent
          ? `${bestEvent.type} · ${bestEvent.message}`
          : directEvidenceCovered
            ? `goal evidence · ${matched.join(", ")}`
            : "缺少直接证据",
      artifactId: bestArtifact?.id || "",
      eventId: bestEvent?.id || "",
      evidenceTextMatch: directEvidenceCovered,
    };
  });
  const failedGates = gates.filter((gate) => ["BLOCKED", "FAIL", "ERROR"].includes(gate.status));
  const passedGates = gates.filter((gate) => ["PASS", "OK", "PASSED"].includes(String(gate.status).toUpperCase()));
  const blockers = [
    ...goal.blockers,
    ...(detail.baseline?.currentSubtask?.blockers || []),
    ...(detail.activeWorkPacket?.blockers || []),
    ...failedGates.map((gate) => `${gate.label}: ${gate.evidence || gate.status}`),
  ].filter(Boolean);
  const missingEvidence = [
    ...coverage.filter((item) => !item.covered).map((item) => `成功标准缺证据：${item.criterion}`),
    ...(artifacts.length ? [] : ["缺少 RESULT、报告、测试输出、代码或预览产物。"]),
    ...(failedGates.length ? [`质量门未通过：${failedGates[0].label}`] : []),
  ];
  const coverageScore = Math.max(0, Math.min(100,
    Math.round((coverage.filter((item) => item.covered).length / Math.max(1, coverage.length)) * 55)
    + Math.min(20, artifacts.length * 4)
    + Math.min(15, passedGates.length * 3)
    + Math.min(10, coverage.filter((item) => item.eventId || item.artifactId).length * 2)
    - Math.min(25, blockers.length * 8)
  ));
  return {
    goalId,
    projectId: goal.projectId,
    generatedAt: nowIso(),
    coverageScore,
    summary: missingEvidence.length ? `${coverageScore}/100 · ${missingEvidence[0]}` : `${coverageScore}/100 · 证据链可用于完成审计`,
    counts: {
      criteria: coverage.length,
      coveredCriteria: coverage.filter((item) => item.covered).length,
      artifacts: artifacts.length,
      gates: gates.length,
      failedGates: failedGates.length,
      evidenceEvents: evidenceEvents.length,
    },
    coverage,
    missingEvidence: [...new Set(missingEvidence)].slice(0, 10),
    blockers: [...new Set(blockers)].slice(0, 10),
    artifacts: artifacts.slice(0, 8),
    gates: gates.slice(0, 8),
    events: evidenceEvents.slice(0, 8),
  };
}

function developmentGoalContinuationContract(goalId: string) {
  const goal = developmentGoalById(goalId);
  if (!goal) return null;
  const detail = developmentProjectDetail(goal.projectId);
  if (!detail) return null;
  const pointers = developmentGoalRuntimePointers(goal.projectId, goal);
  const activeSubtask = pointers.activeSubtask || detail.baseline?.currentSubtask || null;
  const activeWorkPacket = pointers.activeWorkPacket || detail.activeWorkPacket || null;
  const evidencePack = developmentGoalEvidencePack(goalId);
  const completionAudit = developmentGoalCompletionAudit(goalId);
  const timeline = developmentGoalTimeline(goalId);
  const baselineTotal = Number(detail.baseline?.progress?.total || detail.baseline?.totalSubtasks || 0);
  const baselinePassed = Number(detail.baseline?.progress?.passed || detail.baseline?.passedSubtasks || 0);
  const baselineDone = Boolean(detail.baseline && (detail.baseline.status === "completed" || (baselineTotal > 0 && baselinePassed >= baselineTotal)));
  const baselineStable = Boolean(detail.baseline && (detail.baseline.status === "locked" || baselineDone));
  const blockers = [...new Set([
    ...goal.blockers,
    ...(activeSubtask?.blockers || []),
    ...(activeWorkPacket?.blockers || []),
    ...(evidencePack?.blockers || []),
  ].map((item) => String(item || "").trim()).filter(Boolean))];
  const requiredEvidence = [...new Set([
    ...(evidencePack?.missingEvidence || []),
    ...(activeSubtask ? [] : (completionAudit?.checks || []).filter((check) => !check.passed).map((check) => `${check.label}: ${check.evidence}`)),
  ].map((item) => String(item || "").trim()).filter(Boolean))].slice(0, 8);
  const readinessScore = Math.max(0, Math.min(100,
    Math.round(((timeline?.continuityScore || 0) * 0.35) + ((evidencePack?.coverageScore || 0) * 0.4) + ((completionAudit?.score || 0) * 0.25))
    - Math.min(28, blockers.length * 9)
  ));
  const readinessLabel = blockers.length
    ? "停机接力"
    : !baselineStable
      ? "先锁定基线"
      : activeSubtask
        ? "可继续执行"
        : completionAudit?.passed
          ? "可结束审计"
          : "待补证据";
  const nextCommand = blockers.length
    ? `处理停机点：${blockers[0]}`
    : !baselineStable
      ? "锁定开发基线，确认串行子任务和验收标准。"
      : activeSubtask
        ? `继续目标：${String(activeSubtask.sequence).padStart(3, "0")} ${activeSubtask.title}`
        : completionAudit?.passed
          ? "完成目标并归档学习复盘。"
          : "运行完成审计并补齐缺失证据。";
  const currentFocus = activeSubtask
    ? `${String(activeSubtask.sequence).padStart(3, "0")} ${activeSubtask.title}: ${activeSubtask.description}`
    : activeWorkPacket
      ? `${activeWorkPacket.title}: ${activeWorkPacket.nextAction || activeWorkPacket.objective}`
      : detail.baseline
        ? `${detail.project.name}: 基线 ${detail.baseline.status}`
        : `${detail.project.name}: 先生成或锁定开发基线`;
  const resumeRules = [
    "保持原目标完整，不把本轮局部进展重新定义为完成。",
    "先读取当前项目、Goal Ledger、active subtask、证据包和完成审计，再继续执行。",
    "每次继续必须写入目标心跳或开发事件，保留可恢复状态。",
    "没有 PLAN/RESULT、测试、产物、预览或人工验收证据时，不得标记目标完成。",
    "Gateway 慢、质量门失败、审批缺失或高风险动作必须停在人工处理点。",
  ];
  const stopConditions = [
    ...(goal.stopConditions || []),
    ...(blockers.length ? ["当前存在停机点，先处理阻塞再继续。"] : []),
    ...(requiredEvidence.length ? ["缺少验收证据，先补证据或运行完成审计。"] : []),
  ].filter(Boolean);
  const checkpoints = [
    {
      key: "goal",
      label: "目标",
      status: goal.statusLabel || goal.status,
      evidence: goal.objective,
      tone: goal.status === "blocked" ? "warn" : "ok",
    },
    {
      key: "baseline",
      label: "基线",
      status: baselineStable ? "stable" : "needs_lock",
      evidence: detail.baseline ? `${detail.baseline.status} · ${baselinePassed}/${baselineTotal}` : "没有开发基线",
      tone: baselineStable ? "ok" : "warn",
    },
    {
      key: "pointer",
      label: "当前指针",
      status: activeSubtask ? "active_subtask" : activeWorkPacket ? "work_packet" : "missing",
      evidence: currentFocus,
      tone: activeSubtask || activeWorkPacket ? "ok" : "warn",
    },
    {
      key: "evidence",
      label: "证据包",
      status: `${evidencePack?.coverageScore ?? 0}/100`,
      evidence: evidencePack?.summary || "证据包不可用",
      tone: requiredEvidence.length ? "warn" : "ok",
    },
    {
      key: "audit",
      label: "完成审计",
      status: completionAudit?.passed ? "passed" : "not_ready",
      evidence: completionAudit?.passed ? "完成审计通过" : completionAudit?.nextAction || "尚未通过完成审计",
      tone: completionAudit?.passed ? "ok" : "warn",
    },
  ];
  const generatedAt = nowIso();
  const nextPrompt = [
    `继续 OpenClaw 开发台长期目标：${goal.title}`,
    ``,
    `目标：${goal.objective}`,
    `项目：${detail.project.name} (${detail.project.id})`,
    `当前状态：${readinessLabel} · ${readinessScore}/100`,
    `当前焦点：${currentFocus}`,
    `下一步：${nextCommand}`,
    ``,
    `接力规则：`,
    developmentMarkdownList(resumeRules),
    ``,
    `停止条件：`,
    developmentMarkdownList(stopConditions.length ? stopConditions : ["无额外停止条件；仍需遵守高风险审批和完成审计。"]),
    ``,
    `缺失证据/风险：`,
    developmentMarkdownList([...blockers, ...requiredEvidence].slice(0, 10), "- 暂无显式缺口"),
    ``,
    `不要从头重做计划；必须从当前 Goal、active subtask、证据包和事件账本继续。`,
  ].join("\n");
  const markdown = [
    `# Goal Continuation Contract`,
    ``,
    `Generated: ${generatedAt}`,
    `Goal: ${goal.title} (${goal.id})`,
    `Project: ${detail.project.name} (${detail.project.id})`,
    `Readiness: ${readinessLabel} · ${readinessScore}/100`,
    ``,
    `## Current Focus`,
    currentFocus,
    ``,
    `## Next Command`,
    nextCommand,
    ``,
    `## Work Pointer`,
    `- Work packet: ${activeWorkPacket ? `${activeWorkPacket.title} (${activeWorkPacket.id})` : "none"}`,
    `- Subtask: ${activeSubtask ? `${String(activeSubtask.sequence).padStart(3, "0")} ${activeSubtask.title} (${activeSubtask.id})` : "none"}`,
    `- Baseline: ${detail.baseline ? `${detail.baseline.status} · ${baselinePassed}/${baselineTotal}` : "none"}`,
    ``,
    `## Resume Rules`,
    developmentMarkdownList(resumeRules),
    ``,
    `## Stop Conditions`,
    developmentMarkdownList(stopConditions.length ? stopConditions : ["无额外停止条件；仍需遵守高风险审批和完成审计。"]),
    ``,
    `## Evidence Needed`,
    developmentMarkdownList(requiredEvidence, "- 暂无显式缺口"),
    ``,
    `## Blockers`,
    developmentMarkdownList(blockers, "- 暂无显式阻塞"),
    ``,
    `## Copy Prompt`,
    nextPrompt,
  ].join("\n");
  return {
    goalId,
    projectId: goal.projectId,
    generatedAt,
    readinessScore,
    readinessLabel,
    currentFocus,
    nextCommand,
    nextPrompt,
    resumeRules,
    stopConditions,
    requiredEvidence,
    blockers,
    checkpoints,
    pointer: {
      workPacketId: activeWorkPacket?.id || "",
      workPacketTitle: activeWorkPacket?.title || "",
      subtaskId: activeSubtask?.id || "",
      subtaskTitle: activeSubtask ? `${String(activeSubtask.sequence).padStart(3, "0")} ${activeSubtask.title}` : "",
      baselineStatus: detail.baseline?.status || "",
    },
    continuity: {
      heartbeatDue: Boolean(goal.heartbeatDue),
      heartbeatCount: goal.heartbeatCount,
      turnCount: goal.turnCount,
      nextHeartbeatAt: goal.nextHeartbeatAt || "",
      staleSeconds: goal.staleSeconds || 0,
      autopilot: goal.autoRunEnabled ? `${goal.autoTurnsUsed || 0}/${goal.maxAutoTurns || 3} turns · ${goal.heartbeatIntervalMinutes || 30}m` : "off",
    },
    markdown,
  };
}

function developmentGoalRunway(goalId: string) {
  const goal = developmentGoalById(goalId);
  if (!goal) return null;
  const detail = developmentProjectDetail(goal.projectId);
  if (!detail) return null;
  const pointers = developmentGoalRuntimePointers(goal.projectId, goal);
  const activeSubtask = pointers.activeSubtask || detail.baseline?.currentSubtask || null;
  const activeWorkPacket = pointers.activeWorkPacket || detail.activeWorkPacket || null;
  const timeline = developmentGoalTimeline(goalId);
  const evidencePack = developmentGoalEvidencePack(goalId);
  const completionAudit = developmentGoalCompletionAudit(goalId);
  const continuationContract = developmentGoalContinuationContract(goalId);
  const baselineTotal = Number(detail.baseline?.progress?.total || detail.baseline?.totalSubtasks || 0);
  const baselinePassed = Number(detail.baseline?.progress?.passed || detail.baseline?.passedSubtasks || 0);
  const baselineDone = Boolean(detail.baseline && (detail.baseline.status === "completed" || (baselineTotal > 0 && baselinePassed >= baselineTotal)));
  const baselineStable = Boolean(detail.baseline && (detail.baseline.status === "locked" || baselineDone));
  const blockers = [...new Set([
    ...(goal.blockers || []),
    ...(activeSubtask?.blockers || []),
    ...(activeWorkPacket?.blockers || []),
    ...(continuationContract?.blockers || []),
    ...(evidencePack?.blockers || []),
  ].map((item) => String(item || "").trim()).filter(Boolean))].slice(0, 8);
  const requiredEvidence = [...new Set([
    ...(continuationContract?.requiredEvidence || []),
    ...(evidencePack?.missingEvidence || []),
    ...(completionAudit?.checks || []).filter((check) => !check.passed).map((check) => `${check.label}: ${check.evidence}`),
  ].map((item) => String(item || "").trim()).filter(Boolean))].slice(0, 8);
  const hasActiveRun = (detail.latestRun && ["running", "dispatched"].includes(String(detail.latestRun.status || ""))) || false;
  const phase = blockers.length
    ? { key: "blocked", label: "停机处置", detail: blockers[0], risk: "blocked", tone: "warn", action: { key: "recovery_packet", label: "生成恢复包", detail: "先保存当前目标上下文，再处理停机点。", tone: "warn" } }
    : !baselineStable
      ? { key: "baseline", label: "基线门控", detail: "需要先锁定串行子任务和验收标准。", risk: "human", tone: "warn", action: { key: "lock_baseline", label: "锁定基线", detail: "确认目标基线后允许持续推进。", tone: "warn" } }
      : hasActiveRun
        ? { key: "running", label: "后台运行", detail: String(detail.latestRun?.summary || "已有代理运行，等待事件回写。"), risk: "active", tone: "info", action: { key: "continuation_contract", label: "刷新续跑契约", detail: "记录当前运行状态，避免中断丢上下文。", tone: "info" } }
        : activeSubtask
          ? { key: "ready", label: "可继续执行", detail: `${String(activeSubtask.sequence).padStart(3, "0")} ${activeSubtask.title}`, risk: "active", tone: "ok", action: { key: "continue_goal", label: "继续目标", detail: "写入心跳并派发当前子任务。", tone: "ok" } }
          : completionAudit?.passed
            ? { key: "closing", label: "可完成审计", detail: "目标满足完成审计，建议复盘并归档。", risk: "ready", tone: "ok", action: { key: "completion_audit", label: "完成审计", detail: "打开完成审计确认可结束目标。", tone: "ok" } }
            : { key: "evidence", label: "待补证据", detail: completionAudit?.nextAction || "运行完成审计并补齐证据。", risk: "human", tone: "warn", action: { key: "evidence_pack", label: "查看证据包", detail: "定位缺失的验收证据。", tone: "warn" } };
  const readinessScore = continuationContract?.readinessScore ?? Math.max(0, Math.min(100,
    Math.round(((timeline?.continuityScore || 0) * 0.35) + ((evidencePack?.coverageScore || 0) * 0.4) + ((completionAudit?.score || 0) * 0.25))
  ));
  const guardrails = [
    ...(goal.stopConditions || []),
    ...(continuationContract?.stopConditions || []),
    "高风险动作、质量门失败、Gateway 不可用或人工审批缺失时停止自动推进。",
  ].filter(Boolean).slice(0, 6);
  const lanes = [
    {
      key: "context",
      label: "上下文",
      status: detail.project.name,
      tone: "ok",
      detail: activeSubtask ? `${String(activeSubtask.sequence).padStart(3, "0")} ${activeSubtask.title}` : activeWorkPacket?.title || goal.title,
    },
    {
      key: "execution",
      label: "执行",
      status: phase.label,
      tone: phase.tone,
      detail: phase.detail,
    },
    {
      key: "evidence",
      label: "证据",
      status: `${evidencePack?.coverageScore ?? 0}/100`,
      tone: requiredEvidence.length ? "warn" : "ok",
      detail: evidencePack?.summary || "等待证据包。",
    },
    {
      key: "audit",
      label: "完成",
      status: completionAudit?.passed ? "可完成" : `${completionAudit?.score ?? 0}/100`,
      tone: completionAudit?.passed ? "ok" : "warn",
      detail: completionAudit?.nextAction || "完成审计未运行。",
    },
    {
      key: "autopilot",
      label: "自治",
      status: goal.autoRunEnabled ? "已开启" : "人工接管",
      tone: goal.autoRunEnabled ? "ok" : "info",
      detail: goal.autoRunEnabled ? `${goal.autoTurnsUsed || 0}/${goal.maxAutoTurns || 3} turns · ${goal.heartbeatIntervalMinutes || 30}m` : "仅人工点击继续。",
    },
  ];
  const actionQueue = [
    phase.action,
    ...(timeline?.actions || []).slice(0, 5),
    ...(requiredEvidence.length ? [{ key: "stage_contract", label: "接入输入框", detail: "把缺口和下一步写入开发台输入框。", tone: "warn", kind: "contract" }] : []),
  ];
  const uniqueActions = actionQueue.filter((action, index, list) => action && list.findIndex((item) => item?.key === action.key) === index).slice(0, 5);
  return {
    goalId,
    projectId: goal.projectId,
    generatedAt: nowIso(),
    phaseKey: phase.key,
    phaseLabel: phase.label,
    phaseDetail: phase.detail,
    riskLevel: phase.risk,
    readinessScore,
    continuityScore: timeline?.continuityScore || 0,
    evidenceScore: evidencePack?.coverageScore || 0,
    auditScore: completionAudit?.score || 0,
    nextAction: phase.action.label,
    primaryAction: phase.action,
    lanes,
    actions: uniqueActions,
    blockers,
    requiredEvidence,
    guardrails,
    resumePrompt: continuationContract?.nextPrompt || "",
    pointer: {
      workPacketId: activeWorkPacket?.id || "",
      workPacketTitle: activeWorkPacket?.title || "",
      subtaskId: activeSubtask?.id || "",
      subtaskTitle: activeSubtask ? `${String(activeSubtask.sequence).padStart(3, "0")} ${activeSubtask.title}` : "",
      baselineStatus: detail.baseline?.status || "",
    },
    lastEvent: timeline?.items?.[0] || null,
    timelinePreview: (timeline?.items || []).slice(0, 5),
    evidencePreview: (evidencePack?.artifacts || []).slice(0, 4),
  };
}

const DEVELOPMENT_GOAL_DISPATCH_FAILURE_RE = /OpenClaw\s*代理派发失败|代理派发失败|gateway_unavailable|Gateway\s*(暂不可用|不可用|failed|unavailable)|OpenClaw Gateway/i;
type DevelopmentGoalSnapshotAction = { key: string; label: string; detail: string; tone: string; kind?: string };

function developmentGoalSchedulerSnapshot(goalId: string) {
  const lastFinishedMs = Date.parse(developmentGoalAutoLoopState.lastFinishedAt || "");
  const lastStartedMs = Date.parse(developmentGoalAutoLoopState.lastStartedAt || "");
  const lastSeenMs = Number.isFinite(lastFinishedMs) ? lastFinishedMs : lastStartedMs;
  const staleSeconds = Number.isFinite(lastSeenMs) ? Math.max(0, Math.floor((Date.now() - lastSeenMs) / 1000)) : -1;
  const currentGoal = developmentGoalById(goalId);
  const currentDue = Boolean(currentGoal?.autoRunEnabled && currentGoal?.nextHeartbeatAt && Date.parse(currentGoal.nextHeartbeatAt) <= Date.now());
  const lastScanLabel = developmentGoalAutoLoopState.lastFinishedAt
    ? `${developmentGoalAutoLoopState.lastFinishedAt} · ${developmentGoalAutoLoopState.scannedGoals} scanned · ${developmentGoalAutoLoopState.executedGoals} executed · ${developmentGoalAutoLoopState.skippedGoals} skipped`
    : "后台调度器尚未完成首轮扫描";
  const status = developmentGoalAutoLoopState.running
    ? "running"
    : developmentGoalAutoLoopState.lastError
      ? "error"
      : staleSeconds >= 0 && staleSeconds <= 150
        ? "online"
        : "idle";
  const tone = status === "error" || currentDue ? "warn" : status === "online" || status === "running" ? "ok" : "info";
  return {
    status,
    tone,
    running: developmentGoalAutoLoopState.running,
    lastStartedAt: developmentGoalAutoLoopState.lastStartedAt,
    lastFinishedAt: developmentGoalAutoLoopState.lastFinishedAt,
    staleSeconds,
    scannedGoals: developmentGoalAutoLoopState.scannedGoals,
    executedGoals: developmentGoalAutoLoopState.executedGoals,
    skippedGoals: developmentGoalAutoLoopState.skippedGoals,
    recoveredRuns: developmentGoalAutoLoopState.recoveredRuns,
    targetGoalId: developmentGoalAutoLoopState.targetGoalId,
    nextDueGoalId: developmentGoalAutoLoopState.nextDueGoalId,
    nextDueAt: developmentGoalAutoLoopState.nextDueAt,
    currentGoalDue: currentDue,
    lastDecision: developmentGoalAutoLoopState.lastDecision,
    lastError: developmentGoalAutoLoopState.lastError,
    label: status === "running" ? "调度器正在扫描" : status === "error" ? "调度器最近异常" : status === "online" ? "调度器在线" : "等待后台扫描",
    detail: developmentGoalAutoLoopState.lastError || (currentDue ? "当前目标心跳已到期，下一次扫描会按低风险规则处理。" : lastScanLabel),
  };
}

function developmentGoalAutopilotPlan(goalId: string) {
  const goal = developmentGoalById(goalId);
  if (!goal) return null;
  const pointers = developmentGoalRuntimePointers(goal.projectId, goal);
  const blockers = [...goal.blockers, ...(pointers.activeSubtask?.blockers || []), ...(pointers.activeWorkPacket?.blockers || [])].filter(Boolean);
  const nextHeartbeatMs = Date.parse(goal.nextHeartbeatAt || "");
  const hasHeartbeat = Number.isFinite(nextHeartbeatMs);
  const dueInSeconds = hasHeartbeat ? Math.floor((nextHeartbeatMs - Date.now()) / 1000) : null;
  const terminalSubtask = ["passed", "needs_review", "blocked", "failed"].includes(String(pointers.activeSubtask?.status || ""));
  const activeRun = db.prepare(`
    SELECT id, status, active_agent_id, started_at, summary
    FROM development_runs
    WHERE project_id = ? AND mode = 'subtask' AND status IN ('running', 'dispatched')
    ORDER BY started_at DESC
    LIMIT 1
  `).get(goal.projectId) as Record<string, unknown> | undefined;
  const checks = [
    {
      key: "policy",
      label: "自动策略",
      passed: Boolean(goal.autoRunEnabled),
      evidence: goal.autoRunEnabled ? `${goal.heartbeatIntervalMinutes || 30}m · low_risk_only` : "未开启低风险自动推进",
      tone: goal.autoRunEnabled ? "ok" : "warn",
    },
    {
      key: "turn_budget",
      label: "轮次预算",
      passed: Number(goal.autoTurnsUsed || 0) < Number(goal.maxAutoTurns || 3),
      evidence: `${goal.autoTurnsUsed || 0}/${goal.maxAutoTurns || 3} turns`,
      tone: Number(goal.autoTurnsUsed || 0) < Number(goal.maxAutoTurns || 3) ? "ok" : "warn",
    },
    {
      key: "schedule",
      label: "心跳排程",
      passed: Boolean(hasHeartbeat),
      evidence: hasHeartbeat ? `${goal.nextHeartbeatAt}${dueInSeconds !== null && dueInSeconds <= 0 ? " · due" : ""}` : "未设置下一次心跳",
      tone: hasHeartbeat ? "ok" : "warn",
    },
    {
      key: "baseline",
      label: "开发基线",
      passed: pointers.baseline?.status === "locked",
      evidence: pointers.baseline?.status ? `baseline ${pointers.baseline.status}` : "未找到基线",
      tone: pointers.baseline?.status === "locked" ? "ok" : "warn",
    },
    {
      key: "subtask",
      label: "当前子任务",
      passed: Boolean(pointers.activeSubtask),
      evidence: pointers.activeSubtask ? `${String(pointers.activeSubtask.sequence).padStart(3, "0")} ${pointers.activeSubtask.title}` : "未绑定当前子任务",
      tone: pointers.activeSubtask ? "ok" : "warn",
    },
    {
      key: "subtask_state",
      label: "子任务状态",
      passed: Boolean(pointers.activeSubtask) && !terminalSubtask,
      evidence: pointers.activeSubtask ? String(pointers.activeSubtask.status || "unknown") : "无子任务",
      tone: Boolean(pointers.activeSubtask) && !terminalSubtask ? "ok" : "warn",
    },
    {
      key: "blockers",
      label: "停机点",
      passed: blockers.length === 0,
      evidence: blockers[0] || "无显式阻塞",
      tone: blockers.length === 0 ? "ok" : "warn",
    },
    {
      key: "active_run",
      label: "后台运行",
      passed: !activeRun,
      evidence: activeRun ? `${String(activeRun.id || "")} · ${String(activeRun.status || "")} · ${String(activeRun.active_agent_id || "")}` : "无运行中派发",
      tone: activeRun ? "warn" : "ok",
    },
  ];
  const firstFailed = checks.find((check) => !check.passed);
  const allClear = checks.every((check) => check.passed);
  const waitingForSchedule = allClear && dueInSeconds !== null && dueInSeconds > 0;
  const canAutoContinue = allClear && (dueInSeconds === null || dueInSeconds <= 0);
  const mode = !goal.autoRunEnabled
    ? "off"
    : activeRun
      ? "busy"
      : canAutoContinue
        ? "ready"
        : firstFailed
          ? "blocked"
          : waitingForSchedule
            ? "waiting"
            : "waiting";
  const tone = mode === "ready" ? "ok" : mode === "waiting" || mode === "busy" ? "info" : "warn";
  const stopReason = firstFailed ? `${firstFailed.label}: ${firstFailed.evidence}` : activeRun ? String(activeRun.summary || "已有后台运行，等待事件回写。") : "";
  const primaryAction = mode === "off"
    ? { key: "enable_autopilot", label: "开启低风险自动推进", detail: "按心跳和安全检查自动续跑。", tone: "info" }
    : mode === "ready"
      ? { key: "auto_check", label: "立即检查并续跑", detail: "当前目标已满足自动推进条件。", tone: "ok" }
      : mode === "blocked"
        ? { key: "recovery_packet", label: "生成恢复包", detail: stopReason || "先处理停机点。", tone: "warn" }
        : mode === "busy"
          ? { key: "continuation_contract", label: "刷新续跑契约", detail: "保留当前运行上下文，等待回写。", tone: "info" }
          : { key: "auto_check", label: "立即检查", detail: dueInSeconds !== null && dueInSeconds > 0 ? `距离心跳 ${dueInSeconds}s` : "检查当前自动推进资格。", tone: "info" };
  return {
    mode,
    tone,
    canAutoContinue,
    dueInSeconds,
    dueLabel: dueInSeconds === null ? "未排程" : dueInSeconds <= 0 ? "已到期" : `${Math.ceil(dueInSeconds / 60)} 分钟后`,
    nextCheckAt: goal.nextHeartbeatAt || "",
    stopReason,
    primaryAction,
    checks,
  };
}

function developmentGoalProductivitySnapshot(goalId: string, artifactRefs?: Array<{ id: string; type: string; title: string; path: string; rawUrl: string; createdAt: string }>) {
  const goal = developmentGoalById(goalId);
  if (!goal) return null;
  const pointers = developmentGoalRuntimePointers(goal.projectId, goal);
  const activeSubtaskId = pointers.activeSubtask?.id || goal.activeSubtaskId || "";
  const refs = artifactRefs || developmentGoalArtifactRefs(goalId, goal.projectId);
  const events = developmentEvents(goal.projectId, 180)
    .filter((event) => {
      const payloadGoalId = String((event.payload as Record<string, unknown>)?.goalId || "");
      return payloadGoalId === goalId || (activeSubtaskId && event.subtaskId === activeSubtaskId) || `${event.message}\n${event.id}`.includes(goalId);
    });
  const productive = events.filter((event) => DEVELOPMENT_STAT_PRODUCTIVE_EVENTS.has(event.type) || (!DEVELOPMENT_STAT_NOISE_EVENTS.has(event.type) && event.severity === "info"));
  const noise = events.filter((event) => DEVELOPMENT_STAT_NOISE_EVENTS.has(event.type));
  const blockers = events.filter((event) => event.severity === "warn" || /block|error|failed|gateway|timeout|派发失败/i.test(`${event.type}\n${event.message}`));
  const latestProductive = productive[0] || null;
  const latestProductiveMs = Date.parse(latestProductive?.createdAt || "");
  const productiveStaleSeconds = Number.isFinite(latestProductiveMs) ? Math.max(0, Math.floor((Date.now() - latestProductiveMs) / 1000)) : -1;
  const signalBase = productive.length + noise.length;
  const signalRatio = signalBase ? Math.round((productive.length / signalBase) * 100) : 0;
  const hasRecentSignal = productiveStaleSeconds >= 0 && productiveStaleSeconds <= 30 * 60;
  const artifactCount = refs.length;
  const tone = blockers.length
    ? "warn"
    : !productive.length && !artifactCount
      ? "warn"
      : productiveStaleSeconds > 60 * 60
        ? "warn"
        : signalRatio >= 45 || hasRecentSignal || artifactCount
          ? "ok"
          : "info";
  const label = blockers.length
    ? "产出受阻"
    : !productive.length && !artifactCount
      ? "尚无可验收产出"
      : hasRecentSignal
        ? "最近有产出"
        : productiveStaleSeconds > 60 * 60
          ? "产出停滞"
          : "产出可追踪";
  return {
    label,
    tone,
    signalRatio,
    productiveEvents: productive.length,
    noiseEvents: noise.length,
    blockerEvents: blockers.length,
    artifactCount,
    latestProductiveAt: latestProductive?.createdAt || "",
    latestProductiveType: latestProductive?.type || "",
    latestProductiveMessage: latestProductive?.message || refs[0]?.title || "",
    productiveStaleSeconds,
    source: "development_run_events + development_artifacts",
  };
}

function developmentGoalArtifactRefs(goalId: string, projectId: string) {
  return developmentArtifacts(projectId, "", 120)
    .filter((artifact) => {
      const metadataGoalId = String((artifact.metadata || {}).goalId || "");
      return metadataGoalId === goalId || `${artifact.id} ${artifact.path}`.includes(goalId);
    })
    .map((artifact) => ({
      id: artifact.id,
      type: artifact.type,
      title: artifact.title,
      path: artifact.path,
      rawUrl: artifact.url || `/api/development/artifacts/${encodeURIComponent(artifact.id)}/raw`,
      createdAt: artifact.createdAt,
    }));
}

function developmentGoalOperatingSnapshot(goalId: string) {
  const goal = developmentGoalById(goalId);
  if (!goal) return null;
  const detail = developmentProjectDetail(goal.projectId);
  if (!detail) return null;
  const pointers = developmentGoalRuntimePointers(goal.projectId, goal);
  const activeSubtask = pointers.activeSubtask || detail.baseline?.currentSubtask || null;
  const activeWorkPacket = pointers.activeWorkPacket || detail.activeWorkPacket || null;
  const artifactRefs = developmentGoalArtifactRefs(goalId, goal.projectId);
  const artifactByType = (type: string) => artifactRefs.find((artifact) => artifact.type === type) || null;
  const continuationArtifact = artifactByType("goal_continuation_contract");
  const evidenceArtifact = artifactByType("goal_evidence_pack");
  const recoveryArtifact = artifactByType("goal_recovery_packet");
  const completionAuditArtifact = artifactByType("goal_completion_audit");
  const runway = developmentGoalRunway(goalId);
  const timeline = developmentGoalTimeline(goalId);
  const evidencePack = developmentGoalEvidencePack(goalId);
  const completionAudit = developmentGoalCompletionAudit(goalId);
  const contract = developmentGoalContinuationContract(goalId);
  const dispatchEvidenceCandidates = [
    ...(goal.blockers || []),
    ...(activeSubtask?.blockers || []),
    ...(activeWorkPacket?.blockers || []),
    ...(runway?.blockers || []),
    ...(contract?.blockers || []),
    detail.latestRun?.status ? `run:${detail.latestRun.status}` : "",
    detail.latestRun?.summary || "",
    goal.runtimeEvidence?.join("；") || "",
    goal.nextAction || "",
    timeline?.nextCheckpoint?.detail || "",
  ].map((item) => String(item || "").trim()).filter(Boolean);
  // 已恢复事件打断机制：最近一次 goal_dispatch_recovery_resolved 事件之后若没有新的派发失败证据，
  // 则 candidates 列表中残留的派发失败字串视为"已恢复"，避免历史 evidence 误报。
  // 这是 helper 清理之外的最后一道护栏，确保恢复后 snapshot 立即同步。
  const snapshotRecentEvents = developmentEvents(goal.projectId, 60);
  const latestResolvedEvent = snapshotRecentEvents.find((event) => event.type === "goal_dispatch_recovery_resolved");
  const latestFailureAfterResolved = latestResolvedEvent
    ? snapshotRecentEvents.find((event) =>
        DEVELOPMENT_GOAL_DISPATCH_FAILURE_RE.test(`${event.type}\n${event.message}`) &&
        event.severity === "warn" &&
        event.type !== "goal_dispatch_recovery_resolved" &&
        Date.parse(String(event.createdAt || "")) > Date.parse(String(latestResolvedEvent.createdAt || "")),
      )
    : null;
  let dispatchResolution: { resolved: boolean; resolvedAt?: string; gatewayStatus?: string; idempotent?: boolean; healthSource?: string } | null = null;
  if (latestResolvedEvent && !latestFailureAfterResolved) {
    let resolvedPayload: Record<string, unknown> = {};
    try { resolvedPayload = JSON.parse(String(latestResolvedEvent.payload || "{}")) as Record<string, unknown>; } catch { resolvedPayload = {}; }
    const healthObj = (resolvedPayload.health && typeof resolvedPayload.health === "object") ? resolvedPayload.health as Record<string, unknown> : null;
    dispatchResolution = {
      resolved: true,
      resolvedAt: String(latestResolvedEvent.createdAt || ""),
      gatewayStatus: String((healthObj?.status as string) || (resolvedPayload.gatewayStatus as string) || "connected"),
      idempotent: Boolean(resolvedPayload.idempotent),
      healthSource: String((healthObj?.source as string) || "development_goal_dispatch_recovery"),
    };
  }
  const rawDispatchFailureReason = dispatchEvidenceCandidates.find((item) => DEVELOPMENT_GOAL_DISPATCH_FAILURE_RE.test(item)) || "";
  const dispatchFailureReason = dispatchResolution?.resolved
    ? `已恢复（${dispatchResolution.resolvedAt} · Gateway ${dispatchResolution.gatewayStatus}）`
    : rawDispatchFailureReason;
  const dispatchFailed = Boolean(rawDispatchFailureReason) && !dispatchResolution?.resolved;
  const pointerLabel = contract?.pointer.subtaskTitle || contract?.pointer.workPacketTitle || runway?.pointer.subtaskTitle || runway?.pointer.workPacketTitle || (activeSubtask ? `${String(activeSubtask.sequence).padStart(3, "0")} ${activeSubtask.title}` : activeWorkPacket?.title || "");
  const checks = [
    {
      key: "objective",
      label: "目标",
      passed: Boolean(goal.objective && goal.successCriteria.length),
      evidence: goal.successCriteria.length ? `${goal.successCriteria.length} 条成功标准` : "缺少成功标准",
      priority: "P1",
    },
    {
      key: "pointer",
      label: "指针",
      passed: Boolean(pointerLabel),
      evidence: pointerLabel || "未绑定当前子任务或工作包",
      priority: "P0",
    },
    {
      key: "contract",
      label: "接力",
      passed: Boolean(contract || continuationArtifact),
      evidence: contract ? `${contract.readinessScore}/100 · ${contract.readinessLabel}` : continuationArtifact ? "已保存续跑契约产物" : "未生成续跑契约",
      priority: "P0",
    },
    {
      key: "cadence",
      label: "心跳",
      passed: Boolean(goal.lastHeartbeatAt || goal.nextHeartbeatAt || goal.autoRunEnabled),
      evidence: goal.autoRunEnabled ? `${goal.heartbeatIntervalMinutes || 30}m 自动心跳` : goal.lastHeartbeatAt ? `上次 ${goal.lastHeartbeatAt}` : "尚无心跳记录",
      priority: "P1",
    },
    {
      key: "evidence",
      label: "证据",
      passed: evidencePack ? evidencePack.coverageScore >= 60 && !evidencePack.blockers.length : Boolean(evidenceArtifact),
      evidence: evidencePack ? `${evidencePack.coverageScore}/100 · ${evidencePack.counts.artifacts} artifacts` : evidenceArtifact ? "已保存证据包产物" : "未生成证据包",
      priority: "P1",
    },
    {
      key: "recovery",
      label: "恢复",
      passed: Boolean(recoveryArtifact),
      evidence: recoveryArtifact ? "已保存恢复包产物" : "未生成恢复包",
      priority: "P0",
    },
    {
      key: "dispatch",
      label: "派发",
      passed: !dispatchFailed,
      evidence: dispatchFailed ? dispatchFailureReason : detail.latestRun?.status === "dispatched" ? "后台派发中，等待事件回写" : "无代理派发失败",
      priority: "P0",
    },
  ];
  const passed = checks.filter((check) => check.passed).length;
  const rawScore = checks.length ? Math.round((passed / checks.length) * 100) : 0;
  const criticalMissing = checks.some((check) => !check.passed && ["dispatch", "recovery", "contract", "pointer"].includes(check.key));
  const score = criticalMissing ? Math.min(rawScore, 74) : rawScore;
  const label = criticalMissing ? "存在停机点，先处置" : score >= 84 ? "Codex 级接力就绪" : score >= 50 ? "接力条件部分就绪" : "接力条件不足";
  const tone = criticalMissing ? "blocked" : score >= 84 ? "ok" : score >= 50 ? "warn" : "blocked";
  const firstMissing = checks.find((check) => !check.passed);
  const recommendedActions = [
    dispatchFailed ? { key: "dispatch_recovery", label: "生成派发恢复", detail: dispatchFailureReason, tone: "warn" } : null,
    !recoveryArtifact ? { key: "recovery_packet", label: "生成恢复包", detail: "保存当前 Goal、事件、阻塞和证据，供下一轮接手。", tone: "warn" } : null,
    !continuationArtifact && !contract ? { key: "continuation_contract", label: "生成续跑契约", detail: "固化下一轮目标、当前指针、停机条件和复制提示。", tone: "warn" } : null,
    evidencePack?.missingEvidence.length ? { key: "evidence_pack", label: "补齐证据", detail: evidencePack.missingEvidence[0], tone: "warn" } : null,
    runway?.primaryAction || null,
  ].filter((action): action is DevelopmentGoalSnapshotAction => Boolean(action))
    .filter((action, index, list) => list.findIndex((item) => item.key === action.key) === index)
    .slice(0, 5);
  const scheduler = developmentGoalSchedulerSnapshot(goalId);
  const autopilotPlan = developmentGoalAutopilotPlan(goalId);
  const productivity = developmentGoalProductivitySnapshot(goalId, artifactRefs);
  const missionPrimaryAction = recommendedActions[0]
    || (autopilotPlan?.primaryAction ? { ...autopilotPlan.primaryAction, kind: "autopilot" } : null)
    || { key: "continue_goal", label: "继续目标", detail: runway?.nextAction || contract?.nextCommand || goal.nextAction || "按当前指针继续推进目标。", tone: "info", kind: "continue" };
  const missionTone = dispatchFailed || tone === "blocked"
    ? "blocked"
    : autopilotPlan?.mode === "ready" || autopilotPlan?.mode === "busy"
      ? "active"
      : autopilotPlan?.mode === "waiting" || goal.autoRunEnabled
        ? "waiting"
        : "manual";
  const missionLabel = missionTone === "blocked"
    ? "目标停机，先处置"
    : missionTone === "active"
      ? autopilotPlan?.mode === "busy" ? "后台运行中" : "可自动续跑"
      : missionTone === "waiting"
        ? "自动心跳待命"
        : "人工监督目标";
  const missionEvidenceScore = evidencePack?.coverageScore ?? (evidenceArtifact ? 60 : 0);
  const missionControl = {
    label: missionLabel,
    tone: missionTone,
    focus: pointerLabel || goal.title || "未绑定当前工作指针",
    why: dispatchFailureReason || productivity?.latestProductiveMessage || runway?.phaseDetail || contract?.currentFocus || goal.runtimeEvidence?.[0] || "目标状态来自事件账本、工作指针、证据包和自动推进策略。",
    nextAction: runway?.nextAction || contract?.nextCommand || goal.nextAction || missionPrimaryAction.detail,
    primaryAction: missionPrimaryAction,
    generatedAt: nowIso(),
    lanes: [
      {
        key: "state",
        label: "当前状态",
        value: goal.runtimeLabel || goal.statusLabel,
        detail: pointerLabel || activeSubtask?.title || activeWorkPacket?.title || "未绑定当前子任务",
        tone: missionTone === "blocked" ? "warn" : "ok",
      },
      {
        key: "automation",
        label: "自动推进",
        value: autopilotPlan?.canAutoContinue ? "可续跑" : autopilotPlan?.mode === "off" ? "未开启" : autopilotPlan?.dueLabel || scheduler.label,
        detail: autopilotPlan?.stopReason || autopilotPlan?.primaryAction.detail || scheduler.detail,
        tone: autopilotPlan?.tone === "warn" ? "warn" : goal.autoRunEnabled ? "ok" : "info",
      },
      {
        key: "productivity",
        label: "真实产出",
        value: productivity ? `${productivity.signalRatio}% signal` : "未统计",
        detail: productivity?.latestProductiveMessage || "等待事件或 artifact 证明产出",
        tone: productivity?.tone === "warn" ? "warn" : productivity ? "ok" : "info",
      },
      {
        key: "evidence",
        label: "证据链",
        value: `${missionEvidenceScore}/100`,
        detail: evidencePack?.missingEvidence[0] || evidencePack?.summary || evidenceArtifact?.title || "未生成证据包",
        tone: missionEvidenceScore >= 60 && !(evidencePack?.blockers.length) ? "ok" : "warn",
      },
    ],
    risks: [
      dispatchFailureReason,
      ...(evidencePack?.blockers || []),
      ...(evidencePack?.missingEvidence || []),
      ...(runway?.blockers || []),
      ...(contract?.blockers || []),
    ].filter(Boolean).filter((item, index, list) => list.indexOf(item) === index).slice(0, 5),
    source: "development_goal_operating_snapshot",
  };
  const codexParityChecks = [
    {
      key: "objective",
      label: "目标契约",
      passed: Boolean(goal.objective && goal.successCriteria.length),
      evidence: goal.successCriteria.length ? `${goal.successCriteria.length} 条成功标准` : "缺少目标成功标准",
      critical: true,
    },
    {
      key: "pointer",
      label: "工作指针",
      passed: Boolean(pointerLabel),
      evidence: pointerLabel || "未绑定 active subtask / work packet",
      critical: true,
    },
    {
      key: "resume",
      label: "接力命令",
      passed: Boolean(contract?.nextPrompt || continuationArtifact),
      evidence: contract?.nextCommand || continuationArtifact?.title || "未生成可复制的 Resume Command",
      critical: true,
    },
    {
      key: "evidence",
      label: "证据包",
      passed: Boolean((evidencePack && evidencePack.coverageScore >= 60 && !evidencePack.blockers.length) || evidenceArtifact),
      evidence: evidencePack ? `${evidencePack.coverageScore}/100 · ${evidencePack.counts.artifacts} artifacts` : evidenceArtifact?.title || "未生成证据包",
      critical: true,
    },
    {
      key: "recovery",
      label: "恢复包",
      passed: Boolean(recoveryArtifact),
      evidence: recoveryArtifact?.title || "未生成恢复包",
      critical: true,
    },
    {
      key: "timeline",
      label: "事件账本",
      passed: Boolean((timeline?.items?.length || 0) > 0 || goal.heartbeatCount > 0),
      evidence: `${timeline?.items?.length || 0} timeline items · ${goal.heartbeatCount} heartbeats`,
      critical: false,
    },
    {
      key: "autopilot",
      label: "自治保护",
      passed: Boolean(autopilotPlan && scheduler.status !== "error"),
      evidence: autopilotPlan?.stopReason || autopilotPlan?.primaryAction.detail || scheduler.detail,
      critical: false,
    },
    {
      key: "completion",
      label: "完成审计",
      passed: Boolean((completionAudit && completionAudit.score >= 60) || completionAuditArtifact),
      evidence: completionAudit ? `${completionAudit.score}/100 · ${completionAudit.nextAction}` : completionAuditArtifact?.title || "未运行完成审计",
      critical: true,
    },
    {
      key: "dispatch",
      label: "派发安全",
      passed: !dispatchFailed,
      evidence: dispatchFailed ? dispatchFailureReason : "无代理派发失败",
      critical: true,
    },
  ];
  const codexParityPassed = codexParityChecks.filter((check) => check.passed).length;
  const codexParityRawScore = codexParityChecks.length ? Math.round((codexParityPassed / codexParityChecks.length) * 100) : 0;
  const codexParityCriticalMissing = codexParityChecks.some((check) => check.critical && !check.passed);
  const codexParityScore = codexParityCriticalMissing ? Math.min(codexParityRawScore, 79) : codexParityRawScore;
  const codexParityTone = codexParityScore >= 85 && !codexParityCriticalMissing ? "ok" : codexParityScore >= 60 ? "warn" : "blocked";
  const codexParityMissing = codexParityChecks.filter((check) => !check.passed).map((check) => `${check.label}: ${check.evidence}`);
  const codexParity = {
    score: codexParityScore,
    rawScore: codexParityRawScore,
    label: codexParityTone === "ok" ? "Codex Goal parity ready" : codexParityTone === "warn" ? "接近 Codex 目标能力，仍有缺口" : "未达到 Codex 目标能力",
    tone: codexParityTone,
    criticalMissing: codexParityCriticalMissing,
    checks: codexParityChecks,
    missing: codexParityMissing.slice(0, 6),
    source: "goal_contract + artifacts + timeline + scheduler",
  };
  return {
    goalId,
    projectId: goal.projectId,
    generatedAt: nowIso(),
    status: goal.status,
    runtimeState: goal.runtimeState,
    nextAction: runway?.nextAction || contract?.nextCommand || goal.nextAction || firstMissing?.evidence || "继续目标",
    gate: {
      score,
      rawScore,
      label,
      tone,
      criticalMissing,
      firstMissingKey: firstMissing?.key || "",
      firstMissingEvidence: firstMissing?.evidence || "",
      checks,
    },
    dispatch: {
      failed: dispatchFailed,
      reason: dispatchFailureReason,
      resolution: dispatchResolution,
    },
    artifacts: {
      all: artifactRefs,
      continuationContract: continuationArtifact,
      evidencePack: evidenceArtifact,
      recoveryPacket: recoveryArtifact,
      completionAudit: completionAuditArtifact,
    },
    scheduler,
    autopilotPlan,
    productivity,
    missionControl,
    codexParity,
    recommendedActions,
    runway,
    timelinePreview: timeline?.items?.slice(0, 6) || [],
    evidenceSummary: evidencePack ? {
      coverageScore: evidencePack.coverageScore,
      missingEvidence: evidencePack.missingEvidence,
      blockers: evidencePack.blockers,
      artifactCount: evidencePack.counts.artifacts,
    } : null,
    completionAudit: completionAudit ? {
      passed: completionAudit.passed,
      score: completionAudit.score,
      nextAction: completionAudit.nextAction,
    } : null,
  };
}

function developmentGoalOperatingAction(goalId: string, actionKey: string, note = "") {
  const snapshot = developmentGoalOperatingSnapshot(goalId);
  if (!snapshot) return null;
  const primaryRunwayAction = snapshot.runway?.primaryAction?.key === actionKey ? snapshot.runway.primaryAction : null;
  const selectedAction = snapshot.recommendedActions.find((action) => action.key === actionKey)
    || snapshot.runway?.actions?.find((action) => action.key === actionKey)
    || primaryRunwayAction;
  const action: DevelopmentGoalSnapshotAction = selectedAction || {
    key: actionKey || "custom",
    label: actionKey || "自定义目标动作",
    detail: note || "用户从开发台触发目标动作。",
    tone: "info",
  };
  const sideEffects: Record<string, unknown> = {};
  if (action.key === "lock_baseline") {
    sideEffects.lockBaseline = lockDevelopmentBaseline(snapshot.projectId);
  }
  const sideEffectFailed = Object.values(sideEffects).some((value) => {
    if (!value || typeof value !== "object") return false;
    return (value as { ok?: boolean }).ok === false;
  });
  const severity = sideEffectFailed || action.tone === "warn" || snapshot.gate.tone === "blocked" || snapshot.dispatch.failed ? "warn" : "info";
  const riskLevel = severity === "warn" ? "high" : "normal";
  const lockResult = sideEffects.lockBaseline as { ok?: boolean; error?: string } | undefined;
  const message = sideEffectFailed && lockResult?.error
    ? `目标操作失败：${action.label} · ${lockResult.error}`
    : `目标操作：${action.label} · ${action.detail || snapshot.nextAction}`;
  developmentEvent({
    projectId: snapshot.projectId,
    eventType: "goal_operating_action",
    actor: "owner",
    severity,
    message,
    payload: {
      goalId,
      actionKey: action.key,
      actionLabel: action.label,
      actionDetail: action.detail,
      actionTone: action.tone,
      note,
      gate: snapshot.gate,
      dispatch: snapshot.dispatch,
      sideEffects,
      recommendedActionKeys: snapshot.recommendedActions.map((item) => item.key),
    },
  });
  audit(db, "development.goal.operating_action", "development_goal", goalId, riskLevel, {
    projectId: snapshot.projectId,
    actionKey: action.key,
    actionLabel: action.label,
    gateScore: snapshot.gate.score,
    gateLabel: snapshot.gate.label,
    dispatchFailed: snapshot.dispatch.failed,
  });
  return {
    goalId,
    projectId: snapshot.projectId,
    action,
    sideEffects,
    eventMessage: message,
    snapshot: developmentGoalOperatingSnapshot(goalId),
  };
}

function developmentGoalTimeline(goalId: string) {
  const goal = developmentGoalById(goalId);
  if (!goal) return null;
  const detail = developmentProjectDetail(goal.projectId);
  if (!detail) return null;
  const pointers = developmentGoalRuntimePointers(goal.projectId, goal);
  const activeSubtask = pointers.activeSubtask || detail.baseline?.currentSubtask || null;
  const activeWorkPacket = pointers.activeWorkPacket || detail.activeWorkPacket || null;
  const events = developmentEvents(goal.projectId, 180);
  const relevantTypes = new Set([
    "goal_created",
    "goal_heartbeat",
    "goal_auto_enabled",
    "goal_auto_disabled",
    "goal_auto_tick",
    "goal_auto_skipped",
    "goal_paused",
    "goal_blocked",
    "goal_completed",
 "goal_completion_audit",
 "goal_completion_audit_failed",
 "goal_learning_review",
    "goal_recovery_packet",
"goal_dispatch_recovery",
  "goal_dispatch_recovery_resolved",
    "goal_continuation_contract",
    "goal_operating_action",
    "goal_runway_refreshed",
    "subtask_acceptance",
    "review",
    "artifact",
    "test",
    "tool_result",
    "tool_call",
    "thinking",
    "blocker",
    "error",
  ]);
  const relevant = events.filter((event) => {
    const payloadGoalId = String((event.payload || {}).goalId || "");
    if (payloadGoalId === goalId) return true;
    if (!relevantTypes.has(event.type)) return false;
    if (event.subtaskId && activeSubtask?.id && event.subtaskId === activeSubtask.id) return true;
    return event.type.startsWith("goal_") && !payloadGoalId;
  }).slice(0, 28);
  const items = relevant.map((event) => {
    const phase = developmentGoalTimelinePhase(event.type, event.severity);
    return {
      id: event.id,
      type: event.type,
      actor: event.actor,
      severity: event.severity,
      createdAt: event.createdAt,
      message: event.message,
      subtaskId: event.subtaskId,
      runId: event.runId,
      phase: phase.phase,
      label: phase.label,
      tone: phase.tone,
    };
  });
  const blockers = [
    ...goal.blockers,
    ...(activeSubtask?.blockers || []),
    ...(activeWorkPacket?.blockers || []),
  ].filter(Boolean);
  const baselineTotal = Number(detail.baseline?.progress?.total || detail.baseline?.totalSubtasks || 0);
  const baselinePassed = Number(detail.baseline?.progress?.passed || detail.baseline?.passedSubtasks || 0);
  const baselineDone = Boolean(detail.baseline && (detail.baseline.status === "completed" || (baselineTotal > 0 && baselinePassed >= baselineTotal)));
  const baselineStable = Boolean(detail.baseline && (detail.baseline.status === "locked" || baselineDone));
  const hasRecentHeartbeat = items.some((item) => ["goal_heartbeat", "goal_auto_tick"].includes(item.type));
  const evidenceCount = items.filter((item) => ["evidence", "review", "audit", "learning", "recovery"].includes(item.phase)).length;
  const continuityScore = Math.max(0, Math.min(100,
    35
    + Math.min(25, Number(goal.heartbeatCount || 0) * 5)
    + Math.min(20, evidenceCount * 4)
    + (hasRecentHeartbeat ? 10 : 0)
    + (goal.autoRunEnabled ? 10 : 0)
    - Math.min(35, blockers.length * 12)
    - (Number(goal.staleSeconds || 0) > 900 ? 12 : 0)
  ));
  const nextCheckpoint = blockers.length
    ? { tone: "warn", label: "先处理停机点", detail: blockers[0] }
    : !baselineStable
      ? { tone: "warn", label: "锁定基线", detail: "长期目标需要稳定基线和 active subtask 后才能持续推进。" }
    : activeSubtask
      ? { tone: "info", label: "继续当前子任务", detail: `${String(activeSubtask.sequence).padStart(3, "0")} ${activeSubtask.title}` }
        : { tone: "ok", label: "进入完成审计", detail: "没有待执行子任务，运行完成审计确认是否可结束目标。" };
  const actions: Array<{ key: string; label: string; detail: string; tone: string; kind: string }> = [];
  if (blockers.length) {
    actions.push(
      { key: "continuation_contract", label: "续跑契约", detail: "生成下一轮可直接接手的目标、停机点和接力提示。", tone: "warn", kind: "contract" },
      { key: "evidence_pack", label: "查看证据包", detail: "检查当前证据是否足够解除阻塞或进入审计。", tone: "warn", kind: "evidence" },
      { key: "recovery_packet", label: "生成恢复包", detail: "复制当前 Goal、事件、阻塞和证据，交给下一轮继续。", tone: "warn", kind: "evidence" },
      { key: "learning_review", label: "学习复盘", detail: "复盘停机原因和下一步建议。", tone: "warn", kind: "review" },
    );
  } else if (!baselineStable) {
    actions.push(
      { key: "lock_baseline", label: "锁定基线", detail: "确认串行子任务后允许 Goal 持续推进。", tone: "warn", kind: "gate" },
      { key: "continuation_contract", label: "续跑契约", detail: "把当前未锁基线状态整理成下一轮接力说明。", tone: "warn", kind: "contract" },
      { key: "evidence_pack", label: "查看证据包", detail: "确认基线、成功标准和产物缺口。", tone: "info", kind: "evidence" },
      { key: "recovery_packet", label: "生成恢复包", detail: "先保存当前上下文，避免长目标丢失状态。", tone: "info", kind: "evidence" },
    );
  } else if (activeSubtask) {
    actions.push(
      { key: "continue_goal", label: "继续目标", detail: `从 ${String(activeSubtask.sequence).padStart(3, "0")} ${activeSubtask.title} 继续。`, tone: "info", kind: "run" },
      { key: "continuation_contract", label: "续跑契约", detail: "确认下一轮继续执行的目标边界、证据缺口和停机条件。", tone: "info", kind: "contract" },
      { key: "evidence_pack", label: "查看证据包", detail: "确认当前目标已经产生哪些可验收证据。", tone: "info", kind: "evidence" },
      { key: "recovery_packet", label: "恢复包", detail: "生成可复制的恢复上下文。", tone: "info", kind: "evidence" },
    );
    if (!goal.autoRunEnabled) actions.push({ key: "enable_autopilot", label: "开启低风险自动推进", detail: "仅在无阻塞、无运行中任务时按心跳推进。", tone: "info", kind: "automation" });
  } else {
    actions.push(
      { key: "continuation_contract", label: "续跑契约", detail: "收尾前确认目标是否应继续、完成或补证据。", tone: "ok", kind: "contract" },
      { key: "completion_audit", label: "完成审计", detail: "检查成功标准、基线、阻塞、质量门和产物证据。", tone: "ok", kind: "audit" },
      { key: "evidence_pack", label: "查看证据包", detail: "在结束目标前确认交付证据链。", tone: "ok", kind: "evidence" },
      { key: "learning_review", label: "学习复盘", detail: "形成下一轮改进和长期目标经验。", tone: "info", kind: "review" },
      { key: "recovery_packet", label: "归档恢复包", detail: "保存最终上下文，便于后续恢复或审计。", tone: "info", kind: "evidence" },
    );
  }
  return {
    goalId,
    projectId: goal.projectId,
    generatedAt: nowIso(),
    continuityScore,
    resumeBrief: `${goal.runtimeLabel || goal.statusLabel} · ${goal.nextAction || nextCheckpoint.detail}`,
    nextCheckpoint,
    pointer: {
      workPacketId: activeWorkPacket?.id || "",
      workPacketTitle: activeWorkPacket?.title || "",
      subtaskId: activeSubtask?.id || "",
      subtaskTitle: activeSubtask ? `${String(activeSubtask.sequence).padStart(3, "0")} ${activeSubtask.title}` : "",
      baselineStatus: detail.baseline?.status || "",
    },
    actions,
    items,
  };
}

function developmentGoalCompletionAudit(goalId: string) {
  const goal = developmentGoalById(goalId);
  if (!goal) return null;
  const detail = developmentProjectDetail(goal.projectId);
  if (!detail) return null;
  const baseline = detail.baseline || null;
  const gates = developmentGates(goal.projectId, "", 80);
  const artifacts = developmentArtifacts(goal.projectId, "", 80);
  const events = developmentEvents(goal.projectId, 80);
  const blockers = [
    ...goal.blockers,
    ...(baseline?.currentSubtask?.blockers || []),
    ...(detail.activeWorkPacket?.blockers || []),
  ].filter(Boolean);
  const baselineTotal = Number(baseline?.progress?.total || baseline?.totalSubtasks || 0);
  const baselinePassed = Number(baseline?.progress?.passed || baseline?.passedSubtasks || 0);
  const baselineDone = baselineTotal > 0 && baselinePassed >= baselineTotal;
  const gateFailures = gates.filter((gate) => ["BLOCKED", "FAIL", "ERROR"].includes(gate.status));
  const hasDeliverable = artifacts.some((artifact) => /result|report|test|delivery|artifact|code|html|preview/i.test(`${artifact.type} ${artifact.title} ${artifact.path}`));
  const hasRecentEvidence = events.some((event) => ["subtask_acceptance", "review", "test", "artifact", "goal_recovery_packet"].includes(event.type));
  const criteria = goal.successCriteria.length ? goal.successCriteria : ["目标存在成功标准"];
  const evidenceText = `${goal.evidence.join("\n")}\n${events.map((event) => event.message).join("\n")}\n${artifacts.map((artifact) => `${artifact.type} ${artifact.title} ${artifact.path}`).join("\n")}`.toLowerCase();
  const criteriaCoverage = criteria.map((criterion) => {
    const tokens = criterion.toLowerCase().split(/[\s,，。；;、/]+/).filter((token) => token.length >= 2).slice(0, 6);
    const bestEvent = events.find((event) => tokens.some((token) => `${event.type} ${event.message}`.toLowerCase().includes(token)));
    const bestArtifact = artifacts.find((artifact) => tokens.some((token) => `${artifact.type} ${artifact.title} ${artifact.path}`.toLowerCase().includes(token)));
    const matched = tokens.filter((token) => evidenceText.includes(token)).length;
    const evidenceTextMatch = matched >= Math.max(1, Math.ceil(tokens.length * 0.6));
    return { criterion, matched, total: Math.max(1, tokens.length), covered: Boolean(bestEvent || bestArtifact || evidenceTextMatch), eventId: bestEvent?.id || "", artifactId: bestArtifact?.id || "", evidenceTextMatch };
  });
  const checks = [
    {
      key: "criteria",
      label: "成功标准覆盖",
      passed: criteriaCoverage.every((item) => item.covered),
      evidence: criteriaCoverage.filter((item) => item.covered).length
        ? `${criteriaCoverage.filter((item) => item.covered).length}/${criteriaCoverage.length} 条标准有证据`
        : "没有成功标准证据。",
    },
    {
      key: "baseline",
      label: "基线完成",
      passed: baselineDone,
      evidence: baseline ? `${baselinePassed}/${baselineTotal} 子任务通过 · ${baseline.status}` : "没有开发基线。",
    },
    {
      key: "blockers",
      label: "无未处理阻塞",
      passed: blockers.length === 0,
      evidence: blockers.length ? blockers.slice(0, 3).join("；") : "没有目标/子任务/工作包阻塞。",
    },
    {
      key: "gates",
      label: "质量门无失败",
      passed: gateFailures.length === 0,
      evidence: gateFailures.length ? gateFailures.map((gate) => `${gate.label}: ${gate.status}`).slice(0, 3).join("；") : `${gates.length} 个质量门未发现失败。`,
    },
    {
      key: "artifacts",
      label: "交付物存在",
      passed: hasDeliverable,
      evidence: hasDeliverable ? `${artifacts.length} 个产物/证据` : "没有 RESULT、报告、预览、测试或代码产物证据。",
    },
    {
      key: "audit",
      label: "审计事件存在",
      passed: hasRecentEvidence,
      evidence: hasRecentEvidence ? `${events.length} 条近期开发事件` : "缺少验收、审查、测试、产物或恢复包事件。",
    },
  ];
  const failed = checks.filter((check) => !check.passed);
  const score = Math.max(0, Math.round((checks.filter((check) => check.passed).length / checks.length) * 100));
  return {
    goalId,
    projectId: goal.projectId,
    generatedAt: nowIso(),
    passed: failed.length === 0,
    score,
    checks,
    criteriaCoverage,
    nextAction: failed[0]?.evidence || "目标完成审计通过，可标记完成。",
  };
}

function developmentGoalLearningReview(goalId: string) {
  const goal = developmentGoalById(goalId);
  if (!goal) return null;
  const detail = developmentProjectDetail(goal.projectId);
  if (!detail) return null;
  const events = developmentEvents(goal.projectId, 120);
  const artifacts = developmentArtifacts(goal.projectId, "", 40);
  const gates = developmentGates(goal.projectId, "", 40);
  const activeSubtask = detail.baseline?.currentSubtask || null;
  const blockers = [
    ...goal.blockers,
    ...(activeSubtask?.blockers || []),
    ...(detail.activeWorkPacket?.blockers || []),
    ...gates.filter((gate) => ["BLOCKED", "FAIL", "ERROR"].includes(gate.status)).map((gate) => `${gate.label}: ${gate.evidence || gate.status}`),
  ].filter(Boolean);
  const typeCounts = events.reduce<Record<string, number>>((acc, event) => {
    acc[event.type] = (acc[event.type] || 0) + 1;
    return acc;
  }, {});
  const blockedEvents = events.filter((event) => event.severity === "warn" || ["blocker", "error", "goal_auto_skipped", "goal_completion_audit"].includes(event.type));
  const progressEvents = events.filter((event) => ["goal_heartbeat", "goal_auto_tick", "subtask_acceptance", "artifact", "test", "review", "tool_result"].includes(event.type));
  const automationEvents = events.filter((event) => ["goal_auto_enabled", "goal_auto_tick", "goal_auto_skipped", "goal_auto_disabled"].includes(event.type));
  const baselineTotal = Number(detail.baseline?.progress?.total || detail.baseline?.totalSubtasks || 0);
  const baselinePassed = Number(detail.baseline?.progress?.passed || detail.baseline?.passedSubtasks || 0);
  const baselineStable = Boolean(detail.baseline && (detail.baseline.status === "locked" || detail.baseline.status === "completed" || (baselineTotal > 0 && baselinePassed >= baselineTotal)));
  const insights = [
    blockers.length
      ? `当前主要停机点：${blockers[0]}`
      : "当前没有显式阻塞，目标可继续按下一步推进。",
    progressEvents.length
      ? `已有 ${progressEvents.length} 条推进证据，最近一次：${progressEvents[0]?.message || "开发事件"}`
      : "推进证据不足，下一步应先生成可追溯运行事件或产物。",
    automationEvents.length
      ? `Autopilot 已产生 ${automationEvents.length} 条事件，需持续观察跳过/停止原因。`
      : "Autopilot 尚未形成运行样本，仍主要依赖人工继续。",
    artifacts.length
      ? `已有 ${artifacts.length} 个产物/证据，可用于完成审计和恢复包。`
      : "缺少可预览交付物，目标长期推进时容易失去验收锚点。",
  ];
  const recommendedActions = [];
  if (blockers.length) recommendedActions.push({ key: "resolve_blocker", label: "先处理停机点", detail: blockers[0], priority: "P0" });
  if (!baselineStable) recommendedActions.push({ key: "lock_baseline", label: "锁定开发基线", detail: "长期目标需要稳定的 active subtask 才能持续推进。", priority: "P0" });
  if (!artifacts.length) recommendedActions.push({ key: "create_artifact", label: "生成首个交付证据", detail: "至少需要 RESULT、报告、测试输出或预览。", priority: "P1" });
  if (!goal.autoRunEnabled && !blockers.length) recommendedActions.push({ key: "enable_autopilot", label: "考虑开启低风险 Autopilot", detail: "无阻塞时可让目标按心跳检查推进。", priority: "P2" });
  if (!recommendedActions.length) recommendedActions.push({ key: "continue_goal", label: "继续目标", detail: goal.nextAction || "按当前子任务继续。", priority: "P1" });
  const learningScore = Math.max(0, Math.min(100,
    40
    + Math.min(25, progressEvents.length * 5)
    + Math.min(20, artifacts.length * 4)
    + (goal.autoRunEnabled ? 10 : 0)
    - Math.min(35, blockedEvents.length * 5)
  ));
  const markdown = [
    `# Goal Learning Review`,
    ``,
    `Goal: ${goal.title}`,
    `Score: ${learningScore}/100`,
    `Generated: ${nowIso()}`,
    ``,
    `## Insights`,
    developmentMarkdownList(insights),
    ``,
    `## Recommended Actions`,
    developmentMarkdownList(recommendedActions.map((action) => `${action.priority} · ${action.label} · ${action.detail}`)),
    ``,
    `## Event Mix`,
    developmentMarkdownList(Object.entries(typeCounts).map(([type, count]) => `${type}: ${count}`)),
  ].join("\n");
  return {
    goalId,
    projectId: goal.projectId,
    generatedAt: nowIso(),
    learningScore,
    eventCounts: typeCounts,
    insights,
    blockers: [...new Set(blockers)].slice(0, 12),
    recommendedActions,
    markdown,
  };
}

function seedDevelopmentGoals(seed: DevelopmentSeed) {
  const existing = db.prepare("SELECT id FROM development_goals WHERE project_id = ? LIMIT 1").get(seed.id);
  if (existing) return;
  const pointers = developmentGoalRuntimePointers(seed.id);
  const now = nowIso();
  const id = `goal-${seed.id}-operator`;
  db.prepare(`
    INSERT OR IGNORE INTO development_goals (id, project_id, title, objective, status, autonomy_level, active_work_packet_id, active_subtask_id, token_budget, tokens_used, turn_count, heartbeat_count, auto_run_enabled, heartbeat_interval_minutes, max_auto_turns, auto_turns_used, risk_policy, stop_conditions, last_auto_run_at, last_heartbeat_at, next_heartbeat_at, next_action, blockers, success_criteria, evidence, created_at, updated_at, completed_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `).run(
    id,
    seed.id,
    `${seed.name} 持续开发目标`,
    seed.objective,
    seed.status === "waiting" ? "paused" : "active",
    "supervised",
    pointers.activeWorkPacket?.id || null,
    pointers.activeSubtask?.id || null,
    null,
    0,
    0,
    0,
    0,
    30,
    3,
    0,
    "low_risk_only",
    JSON.stringify(["遇到阻塞停止", "质量门失败停止", "高风险动作停止"]),
    null,
    null,
    null,
    pointers.activeSubtask?.title || pointers.activeWorkPacket?.nextAction || "保持项目目标、基线、证据和下一步可见。",
    JSON.stringify(pointers.activeSubtask?.blockers || pointers.activeWorkPacket?.blockers || []),
    JSON.stringify(["长期目标必须可恢复", "每次继续都有事件", "当前子任务串行执行", "阻塞和人工确认显式展示"]),
    JSON.stringify(["seed: development_project", "source: development workspace"]),
    now,
    now,
    null,
  );
}

async function runDevelopmentGoalAction(goalId: string, body: { action?: string; message?: string; activeAgentId?: string; agentId?: string }) {
  const goal = developmentGoalById(goalId);
  if (!goal) return { ok: false, error: "development_goal_not_found" };
  const action = String(body.action || "continue");
  const note = String(body.message || "").trim();
  const requestedAgentId = normalizeDevelopmentAgentId(String(body.activeAgentId || body.agentId || "").trim());
  const now = nowIso();
  if (action === "enable_auto") {
    const interval = Math.max(5, Math.min(240, Number((body as { heartbeatIntervalMinutes?: number | string }).heartbeatIntervalMinutes || goal.heartbeatIntervalMinutes || 30)));
    const maxTurns = Math.max(1, Math.min(12, Number((body as { maxAutoTurns?: number | string }).maxAutoTurns || goal.maxAutoTurns || 3)));
    const nextHeartbeat = new Date(Date.now() + interval * 60 * 1000).toISOString();
    db.prepare(`
      UPDATE development_goals
      SET auto_run_enabled = 1, heartbeat_interval_minutes = ?, max_auto_turns = ?, auto_turns_used = 0, risk_policy = ?, stop_conditions = ?, next_heartbeat_at = ?, next_action = ?, updated_at = ?
      WHERE id = ?
    `).run(
      interval,
      maxTurns,
      "low_risk_only",
      JSON.stringify(["遇到阻塞停止", "质量门失败停止", "高风险动作停止", "连续轮次达到上限停止"]),
      nextHeartbeat,
      note || "低风险自动推进已开启；到达心跳后仅在无阻塞、基线锁定、无运行中派发时推进。",
      now,
      goalId,
    );
    developmentEvent({ projectId: goal.projectId, eventType: "goal_auto_enabled", actor: "owner", severity: "warn", message: `低风险自动推进已开启：${goal.title}`, payload: { goalId, interval, maxTurns, riskPolicy: "low_risk_only" } });
    audit(db, "development.goal.auto_enable", "development_goal", goalId, "high", { projectId: goal.projectId, interval, maxTurns });
    return { ok: true, goal: developmentGoalById(goalId), detail: developmentProjectDetail(goal.projectId) };
  }
  if (action === "disable_auto") {
    db.prepare("UPDATE development_goals SET auto_run_enabled = 0, next_action = ?, updated_at = ? WHERE id = ?")
      .run(note || "自动推进已关闭，等待人工继续。", now, goalId);
    developmentEvent({ projectId: goal.projectId, eventType: "goal_auto_disabled", actor: "owner", severity: "info", message: `低风险自动推进已关闭：${goal.title}`, payload: { goalId, note } });
    audit(db, "development.goal.auto_disable", "development_goal", goalId, "normal", { projectId: goal.projectId, note });
    return { ok: true, goal: developmentGoalById(goalId), detail: developmentProjectDetail(goal.projectId) };
  }
  if (action === "auto_check") {
    if (!goal.autoRunEnabled) {
      developmentEvent({ projectId: goal.projectId, eventType: "goal_auto_skipped", actor: "main", severity: "warn", message: "自动推进未开启，不能执行 Autopilot 检查。", payload: { goalId } });
      return { ok: true, goal: developmentGoalById(goalId), run: null, feedback: "auto_not_enabled", detail: developmentProjectDetail(goal.projectId) };
    }
    db.prepare("UPDATE development_goals SET next_heartbeat_at = ?, next_action = ?, updated_at = ? WHERE id = ?")
      .run(now, "人工触发 Autopilot 检查，按低风险规则决定是否推进。", now, goalId);
    await runDevelopmentGoalAutoLoop(goalId);
    audit(db, "development.goal.auto_check", "development_goal", goalId, "normal", { projectId: goal.projectId });
    return { ok: true, goal: developmentGoalById(goalId), run: null, feedback: "auto_checked", detail: developmentProjectDetail(goal.projectId) };
  }
  if (action === "pause") {
    db.prepare("UPDATE development_goals SET status = ?, next_action = ?, updated_at = ? WHERE id = ?")
      .run("paused", note || "目标已暂停，等待人工恢复。", now, goalId);
    developmentEvent({ projectId: goal.projectId, eventType: "goal_paused", actor: "owner", severity: "warn", message: `长期目标已暂停：${goal.title}`, payload: { goalId, note } });
    audit(db, "development.goal.pause", "development_goal", goalId, "normal", { projectId: goal.projectId, note });
    return { ok: true, goal: developmentGoalById(goalId), detail: developmentProjectDetail(goal.projectId) };
  }
  if (action === "complete") {
 const auditResult = developmentGoalCompletionAudit(goalId);
 if (!auditResult?.passed) {
 const blockers = auditResult?.checks.filter((check) => !check.passed).map((check) => `${check.label}: ${check.evidence}`).slice(0,8) || ["目标完成审计未通过"];
 // P0 (goal-progression):失败时不进死循环 ——
 // (a) 把 auto_turns_used归零，允许 user重新触发 complete/auto_check；
 // (b) auto_run_enabled保留由 auto-loop 检测到 blockers 后主动 disable（不会一直心跳重跑）；
 // (c) next_action明确指向"补充证据后再次审计"，防止用户看不到下一步；
 // (d) audit事件用独立 event_type "goal_completion_audit_failed"，避免和通过的 audit混在一起。
 const retryAction = `完成审计未通过（${auditResult?.score ??0}/100），请补齐失败项证据后再次审计或联系 owner：${auditResult?.nextAction || blockers[0] || "运行 /api/development/goals/<goalId>/completion-audit 后重试"}`;
 db.prepare("UPDATE development_goals SET status = ?, blockers = ?, next_action = ?, auto_turns_used =0, updated_at = ? WHERE id = ?")
 .run("blocked", JSON.stringify([...new Set([...goal.blockers, ...blockers])].slice(0,12)), retryAction, now, goalId);
 developmentEvent({ projectId: goal.projectId, eventType: "goal_completion_audit_failed", actor: "top_ai_pm", severity: "warn", message: `目标完成审计未通过：${auditResult?.score ??0}/100 · ${blockers[0] || auditResult?.nextAction || "等待补齐证据"}`, payload: { goalId, audit: auditResult, retryPath: "POST /api/development/goals/<goalId>/actions { action: complete }" } });
 developmentEvent({ projectId: goal.projectId, eventType: "goal_completion_audit", actor: "top_ai_pm", severity: "warn", message: `目标完成审计：未通过 · ${auditResult?.score ??0}/100`, payload: { goalId, audit: auditResult, outcome: "failed" } });
 audit(db, "development.goal.completion_audit_failed", "development_goal", goalId, "high", { projectId: goal.projectId, audit: auditResult, score: auditResult?.score ??0 });
 return { ok: true, goal: developmentGoalById(goalId), detail: developmentProjectDetail(goal.projectId), feedback: "completion_audit_failed", completionAudit: auditResult, retryPath: { action: "complete", endpoint: "POST /api/development/goals/<goalId>/actions" } };
 }
  // Task3 (Sprint1 Day3): 三态 status 流转 hook — 仅当 goal 有 desktopActions 才进入 evidence_pending
  // 普通 goal(无 metadata.desktopActions)走原 Task2 fire-and-forget,status 仍直转 completed
  const desktopActions = readGoalDesktopActions((goal as { metadata?: string }).metadata);
  const hasDesktopVerify = desktopActions.length > 0;

	  if (!hasDesktopVerify) {
	    // 非 desktop_verify goal — 走原 Task2 路径,status 直接 completed
	    db.prepare("UPDATE development_goals SET status = ?, completed_at = ?, next_action = ?, updated_at = ? WHERE id = ?")
	    .run("completed", now, note || "目标已完成，等待复盘或归档。", now, goalId);
      const evidencePack = developmentGoalEvidencePack(goalId);
      updateLatestGoalRunEvidence(goalId, {
        kind: "completion_audit",
        generatedAt: now,
        completionAudit: auditResult,
        evidencePack,
        desktopOutcome: null,
        acceptedBy: "owner",
      }, "completed");
	    // Sprint2.1 Gap 2: completion chain — 如果 goal.continue_goal=1, 自动起下一轮
    if (goal.continueGoal && auditResult?.score !== undefined && auditResult.score >= 75) {
      const chainInterval = Math.max(5, Math.min(240, Number(goal.heartbeatIntervalMinutes || 30)));
      const chainNext = new Date(Date.now() + chainInterval * 60 * 1000).toISOString();
      db.prepare("UPDATE development_goals SET status = ?, auto_run_enabled = 1, next_heartbeat_at = ?, auto_turns_used = 0, last_heartbeat_at = '', updated_at = ? WHERE id = ?")
        .run("active", chainNext, now, goalId);
      developmentEvent({ projectId: goal.projectId, eventType: "goal_chain_continued", actor: "main", severity: "info", message: `目标完成后自动起下一轮 chain: ${goal.title} · next_heartbeat_at=${chainNext}`, payload: { goalId, chainInterval, auditScore: auditResult.score } });
      audit(db, "development.goal.chain_continued", "development_goal", goalId, "normal", { projectId: goal.projectId, chainInterval, auditScore: auditResult.score });
    } else if (goal.continueGoal && auditResult?.score !== undefined && auditResult.score < 75) {
      developmentEvent({ projectId: goal.projectId, eventType: "goal_chain_blocked_by_score", actor: "main", severity: "warn", message: `continue_goal=1 但审计分 < 75 (${auditResult.score}), 不开下一轮 chain`, payload: { goalId, auditScore: auditResult.score } });
    }
    developmentEvent({ projectId: goal.projectId, eventType: "goal_completed", actor: "owner", severity: "info", message: `长期目标已通过完成审计并标记完成：${goal.title}`, payload: { goalId, note, audit: auditResult } });
    developmentEvent({ projectId: goal.projectId, eventType: "goal_completion_audit", actor: "top_ai_pm", severity: "info", message: `目标完成审计：通过 · ${auditResult?.score ??0}/100`, payload: { goalId, audit: auditResult, outcome: "passed" } });
    audit(db, "development.goal.complete", "development_goal", goalId, "normal", { projectId: goal.projectId, note, audit: auditResult });
    return { ok: true, goal: developmentGoalById(goalId), detail: developmentProjectDetail(goal.projectId), completionAudit: auditResult, evidencePackRef: "", evidencePackOutcome: null as EvidencePackOutcome | null };
  }

  // desktop_verify goal — 走三态流转
  // 步骤 1: status → evidence_pending
  db.prepare("UPDATE development_goals SET status = ?, next_action = ?, updated_at = ? WHERE id = ?")
    .run("evidence_pending", "桌面验收 evidence pack 收集中...", now, goalId);
  developmentEvent({ projectId: goal.projectId, eventType: "goal_evidence_pending", actor: "owner", severity: "info", message: `桌面验收 evidence pack 收集中: ${goal.title}`, payload: { goalId, actionsCount: desktopActions.length } });
  audit(db, "development.goal.evidence_pending", "development_goal", goalId, "normal", { projectId: goal.projectId, actionsCount: desktopActions.length });

  // 步骤 2: 跑 cu MCP action 序列(从 void 改为 await,owner 决策 #4)
  let packWithOutcome: Awaited<ReturnType<typeof runAndPersistWithLifecycle>>;
  try {
    packWithOutcome = await runAndPersistWithLifecycle({
      db,
      goalId,
      sessionId: `goal-${goalId}`,
      scenario: (goal as { title?: string }).title || "desktop_verify",
      actions: desktopActions,
    });
  } catch (err) {
    // runner 抛错(不应发生,runAndPersistWithLifecycle 内部 try-catch)
    const errMsg = (err as Error).message || String(err);
    app.log.error({ err, goalId }, "desktop evidence pack lifecycle runner threw");
	    db.prepare("UPDATE development_goals SET status = ?, next_action = ?, updated_at = ? WHERE id = ?")
	      .run("failed", `桌面验收 runner 异常: ${errMsg.slice(0, 200)}`, now, goalId);
      updateLatestGoalRunEvidence(goalId, {
        kind: "desktop_evidence_pack",
        generatedAt: now,
        completionAudit: auditResult,
        desktopOutcome: "failed",
        error: errMsg,
      }, "failed");
	    developmentEvent({ projectId: goal.projectId, eventType: "goal_evidence_pack_failed", actor: "owner", severity: "high", message: `桌面验收 evidence pack runner 异常: ${errMsg.slice(0, 200)}`, payload: { goalId, error: errMsg } });
    audit(db, "development.goal.desktop_evidence_pack_failed", "development_goal", goalId, "high", { projectId: goal.projectId, error: errMsg, runnerThrew: true });
    return { ok: false, error: "evidence_runner_exception", goal: developmentGoalById(goalId), detail: developmentProjectDetail(goal.projectId), evidencePackOutcome: "failed" as EvidencePackOutcome };
  }

  // 步骤 3: 决策 goal status
  const outcome = packWithOutcome.outcome;
  const finalStatus = outcomeToGoalStatus(outcome);
  const evidencePackRef = readLatestEvidencePackRef(db, goalId);
  const completedAtIso = (outcome === "completed" || outcome === "completed_partial" || outcome === "failed") ? now : null;
  const nextActionHint = outcome === "completed"
    ? (note || "目标已完成，等待复盘或归档。")
    : outcome === "completed_partial"
      ? `桌面验收部分通过(${packWithOutcome.summary.successCount}/${packWithOutcome.summary.totalActions}),sprint2 audit 工具复核。`
      : `桌面验收失败(${packWithOutcome.summary.failCount}/${packWithOutcome.summary.totalActions}),人工介入: ${packWithOutcome.actions.find((a) => !a.ok)?.error?.slice(0, 200) || "未知错误"}`;

	  db.prepare("UPDATE development_goals SET status = ?, completed_at = ?, next_action = ?, updated_at = ? WHERE id = ?")
	    .run(finalStatus, completedAtIso, nextActionHint, now, goalId);
  updateLatestGoalRunEvidence(goalId, {
    kind: "desktop_evidence_pack",
    generatedAt: now,
    completionAudit: auditResult,
    desktopOutcome: outcome,
    evidencePackRef,
    summary: packWithOutcome.summary,
    actions: packWithOutcome.actions,
  }, outcome === "failed" ? "failed" : "completed");

  const eventSeverity = outcome === "completed" ? "info" : outcome === "completed_partial" ? "warn" : "high";
  developmentEvent({ projectId: goal.projectId, eventType: "goal_completed", actor: "owner", severity: eventSeverity, message: `长期目标验收完成: ${goal.title} · outcome=${outcome}`, payload: { goalId, note, audit: auditResult, evidencePackOutcome: outcome, evidencePackRef } });
  developmentEvent({ projectId: goal.projectId, eventType: "goal_completion_audit", actor: "top_ai_pm", severity: eventSeverity, message: `目标完成审计：通过 · ${auditResult?.score ??0}/100 · evidence_outcome=${outcome}`, payload: { goalId, audit: auditResult, outcome: "passed", evidencePackOutcome: outcome, evidencePackRef } });
  audit(db, "development.goal.complete", "development_goal", goalId, outcome === "completed" ? "normal" : outcome === "completed_partial" ? "warn" : "high", { projectId: goal.projectId, note, audit: auditResult, evidencePackOutcome: outcome, evidencePackRef });

  return {
    ok: outcome !== "failed",
    goal: developmentGoalById(goalId),
    detail: developmentProjectDetail(goal.projectId),
    completionAudit: auditResult,
    evidencePackOutcome: outcome,
    evidencePackRef,
  };
}
  if (action === "block") {
    const blockers = [...new Set([...goal.blockers, note || "人工标记阻塞"])].slice(0, 12);
    db.prepare("UPDATE development_goals SET status = ?, blockers = ?, next_action = ?, updated_at = ? WHERE id = ?")
      .run("blocked", JSON.stringify(blockers), blockers[0] || "处理阻塞后继续。", now, goalId);
    developmentEvent({ projectId: goal.projectId, eventType: "goal_blocked", actor: "owner", severity: "warn", message: `长期目标进入阻塞：${blockers[0] || goal.title}`, payload: { goalId, blockers } });
    audit(db, "development.goal.block", "development_goal", goalId, "high", { projectId: goal.projectId, blockers });
    return { ok: true, goal: developmentGoalById(goalId), detail: developmentProjectDetail(goal.projectId) };
  }

  const baseline = developmentBaselineBundle(goal.projectId) || generateDevelopmentBaseline(goal.projectId, { lock: false, actor: "top_ai_pm", reason: "goal_continue_missing_baseline" });
  const pointers = developmentGoalRuntimePointers(goal.projectId, goal);
  const activeSubtask = pointers.activeSubtask || baseline?.currentSubtask || null;
  const activeWorkPacket = pointers.activeWorkPacket || developmentActiveWorkPacket(goal.projectId);
  const heartbeatIntervalMinutes = Math.max(5, Math.min(240, Number(goal.heartbeatIntervalMinutes || 30)));
  const nextHeartbeat = new Date(Date.now() + heartbeatIntervalMinutes * 60 * 1000).toISOString();
  const nextAction = activeSubtask
    ? `继续子任务 ${String(activeSubtask.sequence).padStart(3, "0")}：${activeSubtask.title}`
    : activeWorkPacket?.nextAction || "生成并锁定开发基线后继续。";
  const currentRow = db.prepare("SELECT evidence FROM development_goals WHERE id = ?").get(goalId) as { evidence?: string } | undefined;
  const goalOsPreflight = await runGoalOsPreflight(goal, {
    action,
    activeAgentId: requestedAgentId,
    subtaskId: activeSubtask?.id || "",
    requireDispatchReady: Boolean(baseline?.status === "locked" && activeSubtask),
  });
  const goalOsResumeManifest = buildGoalResumeManifest(goal, {
    action,
    activeAgentId: requestedAgentId,
    preflight: goalOsPreflight,
    subtaskId: activeSubtask?.id || "",
  });
  const goalOsRun = createGoalRunLedgerEntry({
    goal,
    action,
    status: goalOsPreflight.ok ? "preflight_ready" : "blocked_preflight",
    activeAgentId: requestedAgentId,
    subtaskId: activeSubtask?.id || "",
    preflight: goalOsPreflight,
    resumeManifest: goalOsResumeManifest,
  });
  const goalOsArtifact = goalOsResumeManifest ? persistDevelopmentGoalArtifact({
    projectId: goal.projectId,
    goalId,
    artifactType: "goal_resume_manifest",
    title: "Goal OS Resume Manifest",
    markdown: goalResumeManifestMarkdown(goalOsResumeManifest),
    evidenceLevel: goalOsPreflight.ok ? "goal_handoff" : "blocked_preflight",
    metadata: { goalRunId: goalOsRun.id, sourceAction: action },
  }) : null;
  if (!goalOsPreflight.ok) {
    const preflightBlockers = [...new Set([...goal.blockers, ...goalOsPreflight.blockers])].slice(0, 12);
    const repair = goalOsPreflight.repairActions[0] || "修复 Goal OS preflight 后重试。";
    db.prepare("UPDATE development_goals SET status = ?, blockers = ?, next_action = ?, updated_at = ? WHERE id = ?")
      .run("blocked", JSON.stringify(preflightBlockers), repair, now, goalId);
    developmentEvent({
      projectId: goal.projectId,
      subtaskId: activeSubtask?.id || null,
      eventType: "goal_os_preflight_blocked",
      actor: "goal_os",
      severity: "warn",
      message: `Goal OS preflight 阻止派发：${goalOsPreflight.blockers[0] || "执行通道不可用"}`,
      payload: { goalId, goalRunId: goalOsRun.id, preflight: goalOsPreflight, resumeManifestId: goalOsArtifact?.id || "" },
    });
    developmentEvent({
      projectId: goal.projectId,
      subtaskId: activeSubtask?.id || null,
      eventType: "goal_os_dispatch_intercepted",
      actor: "goal_os",
      severity: "warn",
      message: "执行通道未通过 canary，已拦截 OpenClaw agent 派发以节省 token。",
      payload: { goalId, goalRunId: goalOsRun.id, forbiddenActions: goalOsPreflight.forbiddenActions },
    });
    audit(db, "development.goal_os.dispatch_intercepted", "development_goal", goalId, "high", { projectId: goal.projectId, goalRunId: goalOsRun.id, blockers: goalOsPreflight.blockers });
    return { ok: false, error: "goal_os_preflight_blocked", feedback: "blocked_preflight", preflight: goalOsPreflight, goalRun: goalOsRun, resumeManifest: goalOsResumeManifest, goal: developmentGoalById(goalId), detail: developmentProjectDetail(goal.projectId) };
  }
  developmentEvent({
    projectId: goal.projectId,
    subtaskId: activeSubtask?.id || null,
    eventType: "goal_os_preflight_ready",
    actor: "goal_os",
    severity: "info",
    message: "Goal OS preflight 已通过，进入目标心跳和派发阶段。",
    payload: { goalId, goalRunId: goalOsRun.id, preflight: goalOsPreflight, resumeManifestId: goalOsArtifact?.id || "" },
  });
  db.prepare(`
    UPDATE development_goals
    SET status = ?, active_work_packet_id = ?, active_subtask_id = ?, turn_count = turn_count + 1, heartbeat_count = heartbeat_count + 1,
      auto_turns_used = CASE WHEN auto_run_enabled = 1 AND ? = 'auto_continue' THEN auto_turns_used + 1 ELSE auto_turns_used END,
      last_auto_run_at = CASE WHEN auto_run_enabled = 1 AND ? = 'auto_continue' THEN ? ELSE last_auto_run_at END,
      last_heartbeat_at = ?, next_heartbeat_at = ?, next_action = ?, evidence = ?, updated_at = ?
    WHERE id = ?
  `).run(
    activeSubtask && baseline?.status === "locked" ? "running" : "active",
    activeWorkPacket?.id || null,
    activeSubtask?.id || null,
    action,
    action,
    now,
    now,
    nextHeartbeat,
    baseline?.status === "locked" ? nextAction : "先锁定基线，再进入长期执行循环。",
    developmentGoalEvidence(currentRow?.evidence || goal.evidence, `${now} · ${action === "resume" ? "恢复目标" : action === "auto_continue" ? "自动目标心跳" : "继续目标"} · ${activeSubtask?.title || activeWorkPacket?.title || goal.title}`),
    now,
    goalId,
  );
  developmentEvent({
    projectId: goal.projectId,
    subtaskId: activeSubtask?.id || null,
    eventType: action === "auto_continue" ? "goal_auto_tick" : "goal_heartbeat",
    actor: "main",
    severity: baseline?.status === "locked" && activeSubtask ? "info" : "warn",
    message: baseline?.status === "locked" && activeSubtask ? `${action === "auto_continue" ? "自动目标心跳" : "目标心跳继续"}：${activeSubtask.title}` : "目标心跳已记录，但基线尚未锁定，等待人工确认。",
    payload: { goalId, action, note, activeAgentId: requestedAgentId || "auto", activeWorkPacketId: activeWorkPacket?.id || "", activeSubtaskId: activeSubtask?.id || "", baselineStatus: baseline?.status || "" },
  });
  audit(db, "development.goal.heartbeat", "development_goal", goalId, "normal", { projectId: goal.projectId, action, activeAgentId: requestedAgentId || "auto", activeSubtaskId: activeSubtask?.id || "" });
  if (baseline?.status === "locked" && activeSubtask) {
 const result = await runDevelopmentSubtask(activeSubtask.id, { activeAgentId: requestedAgentId, goalId, goalRunId: goalOsRun.id, skipGoalOsPreflight: true });
 //跟踪 token budget 使用 —— 即使网关未返回精确 token 数，
 // 也需要让 tokens_used随真实执行递增，否则 budget永远停在0。
 // 这里每次心跳推动一个子任务记一笔“执行消耗”，后续可通过外部审计替换。
 try {
 db.prepare(`
 UPDATE development_goals
 SET tokens_used = COALESCE(tokens_used,0) +1,
 updated_at = ?
 WHERE id = ?
 `).run(nowIso(), goalId);
 } catch (tokenErr) {
 app.log.warn({ err: tokenErr, goalId }, "failed to bump goal tokens_used after subtask run");
 }
 return { ok: result.ok, goal: developmentGoalById(goalId), run: result.ok ? result.run : null, feedback: result.ok ? null : result.error, detail: developmentProjectDetail(goal.projectId) };
 }
  return { ok: true, goal: developmentGoalById(goalId), run: null, feedback: "baseline_not_locked", detail: developmentProjectDetail(goal.projectId) };
}

let developmentGoalAutoLoopRunning = false;
type DevelopmentGoalAutoLoopState = {
 running: boolean;
 lastStartedAt: string;
 lastFinishedAt: string;
 lastError: string;
 targetGoalId: string;
 scannedGoals: number;
 executedGoals: number;
 skippedGoals: number;
 recoveredRuns: number;
 nextDueGoalId: string;
 nextDueAt: string;
 lastDecision: string;
 lastAutoTickAt: string;
};
const developmentGoalAutoLoopState: DevelopmentGoalAutoLoopState = {
 running: false,
 lastStartedAt: "",
 lastFinishedAt: "",
 lastError: "",
 targetGoalId: "",
 scannedGoals:0,
 executedGoals:0,
 skippedGoals:0,
 recoveredRuns:0,
 nextDueGoalId: "",
 nextDueAt: "",
 lastDecision: "scheduler_not_started",
 lastAutoTickAt: "",
};
const DEVELOPMENT_SCHEDULER_STATE_ROW_ID = "default";
const DEVELOPMENT_SCHEDULER_PERSIST_THROTTLE_MS = 750;
let developmentSchedulerLastPersistAt = 0;
let developmentSchedulerDirty = false;
let developmentSchedulerProcessBootId = `${process.pid}-${Date.now()}`;
// 本次进程启动时是否检测到 DB 状态来自另一个进程 —— 用于监控端识别"重启已发生"。
let developmentSchedulerRestartedAtBoot = false;
let developmentSchedulerPreviousProcessIdAtBoot = "";

function developmentSchedulerRowToState(row: Record<string, unknown>): DevelopmentGoalAutoLoopState {
 return {
 running: false, //总是以当前进程为准 —— DB 上的 running 是历史快照，重启后必须复位
 lastStartedAt: String(row.last_started_at || ""),
 lastFinishedAt: String(row.last_finished_at || ""),
 lastError: String(row.last_error || ""),
 targetGoalId: String(row.target_goal_id || ""),
 scannedGoals: Number(row.scanned_goals ||0),
 executedGoals: Number(row.executed_goals ||0),
 skippedGoals: Number(row.skipped_goals ||0),
 recoveredRuns: Number(row.recovered_runs ||0),
 nextDueGoalId: String(row.next_due_goal_id || ""),
 nextDueAt: String(row.next_due_at || ""),
 lastDecision: String(row.last_decision || "scheduler_not_started"),
 lastAutoTickAt: String(row.last_auto_tick_at || ""),
 };
}

function loadDevelopmentGoalAutoLoopState(): { restored: boolean; previousProcessId: string; previousProcessStartedAt: string; wasRestarted: boolean } {
  try {
    const row = db.prepare("SELECT * FROM development_scheduler_state WHERE id = ?").get(DEVELOPMENT_SCHEDULER_STATE_ROW_ID) as Record<string, unknown> | undefined;
    if (!row) {
      // 首次启动 —— 初始化一行
      try {
        db.prepare(`
 INSERT INTO development_scheduler_state (id, running, last_started_at, last_finished_at, last_error, target_goal_id,
 scanned_goals, executed_goals, skipped_goals, recovered_runs, next_due_goal_id, next_due_at, last_decision, last_auto_tick_at,
 process_id, process_started_at, updated_at)
 VALUES (?,0, '', '', '', '',0,0,0,0, '', '', ?, '', ?, ?, ?)
 `).run(
 DEVELOPMENT_SCHEDULER_STATE_ROW_ID,
 "scheduler_not_started",
 developmentSchedulerProcessBootId,
 nowIso(),
 nowIso(),
 );
      } catch (insertErr) {
        app.log.warn({ err: insertErr }, "failed to seed development_scheduler_state row");
      }
      return { restored: false, previousProcessId: "", previousProcessStartedAt: "", wasRestarted: false };
    }
    const restored = developmentSchedulerRowToState(row);
    Object.assign(developmentGoalAutoLoopState, restored);
    const previousProcessId = String(row.process_id || "");
    const previousProcessStartedAt = String(row.process_started_at || "");
    const wasRestarted = previousProcessId !== "" && previousProcessId !== developmentSchedulerProcessBootId;
    developmentSchedulerRestartedAtBoot = wasRestarted;
    developmentSchedulerPreviousProcessIdAtBoot = previousProcessId;
    // 如果上次进程还在跑（被 kill -9 / OOM / 崩溃），把"上次未完成"信号记录下来
    if (Number(row.running || 0) === 1) {
      const lastFinished = String(row.last_finished_at || row.last_started_at || "");
      const finishedMs = Date.parse(lastFinished);
      const ageSeconds = Number.isFinite(finishedMs) ? Math.max(0, Math.floor((Date.now() - finishedMs) / 1000)) : -1;
      developmentGoalAutoLoopState.lastError = developmentGoalAutoLoopState.lastError
        || `上次进程在扫描中消失（process=${previousProcessId || "unknown"} · age=${ageSeconds}s），已自动复位为 idle。`;
      developmentGoalAutoLoopState.lastDecision = `restart_recovered_from_unfinished_run(pid=${previousProcessId || "unknown"})`;
    }
    // 新进程"认领"调度器：把 DB 行的 process_id / process_started_at 立刻更新成当前进程
    // —— 这样监控端能立刻看到 "重启后由新进程接管"。
    try {
      db.prepare(`
        UPDATE development_scheduler_state
        SET running = 0,
            process_id = ?, process_started_at = ?, updated_at = ?
        WHERE id = ?
      `).run(developmentSchedulerProcessBootId, nowIso(), nowIso(), DEVELOPMENT_SCHEDULER_STATE_ROW_ID);
    } catch (claimErr) {
      app.log.warn({ err: claimErr }, "failed to claim development_scheduler_state on boot");
    }
    app.log.info({
      restoredProcess: previousProcessId || "none",
      wasRestarted,
      lastFinished: developmentGoalAutoLoopState.lastFinishedAt,
      nextDueGoalId: developmentGoalAutoLoopState.nextDueGoalId,
      nextDueAt: developmentGoalAutoLoopState.nextDueAt,
    }, "development goal scheduler state restored from db");
    return { restored: true, previousProcessId, previousProcessStartedAt, wasRestarted };
  } catch (err) {
    app.log.warn({ err }, "failed to load development_scheduler_state; using defaults");
    return { restored: false, previousProcessId: "", previousProcessStartedAt: "", wasRestarted: false };
  }
}

function persistDevelopmentGoalAutoLoopState(opts: { force?: boolean } = {}) {
  const now = Date.now();
  if (!opts.force && !developmentSchedulerDirty) return;
  if (!opts.force && now - developmentSchedulerLastPersistAt < DEVELOPMENT_SCHEDULER_PERSIST_THROTTLE_MS) return;
  developmentSchedulerDirty = false;
  developmentSchedulerLastPersistAt = now;
  const s = developmentGoalAutoLoopState;
  try {
    db.prepare(`
 INSERT INTO development_scheduler_state (id, running, last_started_at, last_finished_at, last_error, target_goal_id,
 scanned_goals, executed_goals, skipped_goals, recovered_runs, next_due_goal_id, next_due_at, last_decision, last_auto_tick_at,
 process_id, process_started_at, updated_at)
 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
 ON CONFLICT(id) DO UPDATE SET
 running = excluded.running,
 last_started_at = excluded.last_started_at,
 last_finished_at = excluded.last_finished_at,
 last_error = excluded.last_error,
 target_goal_id = excluded.target_goal_id,
 scanned_goals = excluded.scanned_goals,
 executed_goals = excluded.executed_goals,
 skipped_goals = excluded.skipped_goals,
 recovered_runs = excluded.recovered_runs,
 next_due_goal_id = excluded.next_due_goal_id,
 next_due_at = excluded.next_due_at,
 last_decision = excluded.last_decision,
 last_auto_tick_at = excluded.last_auto_tick_at,
 process_id = excluded.process_id,
 process_started_at = excluded.process_started_at,
 updated_at = excluded.updated_at
 `).run(
 DEVELOPMENT_SCHEDULER_STATE_ROW_ID,
 s.running ?1 :0,
 s.lastStartedAt,
 s.lastFinishedAt,
 s.lastError,
 s.targetGoalId,
 s.scannedGoals,
 s.executedGoals,
 s.skippedGoals,
 s.recoveredRuns,
 s.nextDueGoalId,
 s.nextDueAt,
 s.lastDecision,
 s.lastAutoTickAt,
 developmentSchedulerProcessBootId,
 nowIso(),
 nowIso(),
 );
  } catch (err) {
    app.log.warn({ err }, "failed to persist development_scheduler_state");
  }
}
const DEVELOPMENT_RUN_STALE_MS = 30 * 60 * 1000;
const DEVELOPMENT_RUN_TAKEOVER_MARKER = /待接管|pending[_-]?takeover|待接管状态/i;
const DEVELOPMENT_STAT_PRODUCTIVE_EVENTS = new Set([
  "tool_result",
  "review",
  "artifact",
  "subtask_acceptance",
  "test",
  "goal_completion_audit",
  "goal_learning_review",
  "goal_recovery_packet",
  "goal_dispatch_recovery",
  "blocker",
  "goal_auto_skipped",
]);
const DEVELOPMENT_STAT_NOISE_EVENTS = new Set([
  "goal_heartbeat",
  "goal_auto_tick",
  "goal_auto_enabled",
  "goal_auto_disabled",
  "goal_continuation_contract",
  "goal_runway_refreshed",
  "goal_updated",
  "goal_created",
]);

function parseDateMs(value: string, fallback: number) {
  const parsed = Date.parse(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function pickLatest(a: string, b: string) {
  // ISO 字符串按时间序比较（ISO 8601 字典序 == 时间序）
  if (!a) return b;
  if (!b) return a;
  return a >= b ? a : b;
}

function ensureRunIsRecoverable(projectId: string, runId: string, activeAgentId: string, startedAt: string, nowMs: number) {
  const latestEvent = db.prepare(`
    SELECT created_at
      FROM development_run_events
    WHERE project_id = ? AND run_id = ?
    ORDER BY created_at DESC
    LIMIT 1
  `).get(projectId, runId) as { created_at?: string } | undefined;
  const recoveryMarker = db.prepare(`
    SELECT event_type, message
    FROM development_run_events
    WHERE project_id = ? AND run_id = ?
    ORDER BY created_at DESC
    LIMIT 1
  `).get(projectId, runId) as { event_type?: string; message?: string } | undefined;
  const latestMs = parseDateMs(String(latestEvent?.created_at || startedAt), parseDateMs(startedAt, nowMs));
  const hasPendingTakeover = Boolean(recoveryMarker?.event_type === "blocker" && DEVELOPMENT_RUN_TAKEOVER_MARKER.test(String(recoveryMarker.message || "")));
  const stale = latestMs <= nowMs - DEVELOPMENT_RUN_STALE_MS || hasPendingTakeover;
  if (!stale) return { stale: false, pendingTakeover: false };

  const summary = hasPendingTakeover
    ? `OpenClaw ${activeAgentId} 代理运行已进入待接管态，转为错误态并允许继续自动推进。`
    : `OpenClaw ${activeAgentId} 代理运行超过 30 分钟无新事件，已转入错误态并允许继续自动推进。`;
  db.prepare("UPDATE development_runs SET status = ?, duration_ms = ?, summary = ? WHERE id = ?")
    .run("error", Math.max(0, nowMs - parseDateMs(startedAt, nowMs)), summary, runId);
  const existing = db.prepare(`
    SELECT id
      FROM development_run_events
    WHERE project_id = ?
      AND run_id = ?
      AND event_type = 'blocker'
      AND message = ?
    LIMIT 1
  `).get(projectId, runId, summary);
      if (!existing) {
        developmentEvent({
          projectId,
          runId,
          eventType: "blocker",
          actor: activeAgentId,
          severity: "warn",
          message: summary,
          payload: {
            source: "development_run_stale_recovery",
            staleSeconds: Math.max(0, Math.floor((nowMs - latestMs) / 1000)),
          },
        });
      }
  return { stale: true, pendingTakeover: hasPendingTakeover };
}

/**
 * Sprint2 #4 失败恢复 - 自动重试
 *
 * 每分钟由 runDevelopmentGoalAutoLoop 触发, 逻辑:
 * 1. 扫所有 auto_run_enabled=1 + status='active'/'running' 的 goal
 * 2. 检查最近 events 是否有 gateway_unavailable / 派发失败 (DEVELOPMENT_GOAL_DISPATCH_FAILURE_RE)
 * 3. refreshLiveGatewayHealth({ force: true }) 检测 gateway 是否恢复
 * 4. 如果 goal 有 dispatch failure 但 gateway 恢复 → 自动调 resolveDevelopmentGoalDispatchFailure
 * 5. retry cap=3 (看 audit_logs 里 goal_dispatch_recovery_resolved 数量)
 * 6. 写 event goal_auto_recovery_resolved / goal_auto_recovery_skipped
 */
async function tryAutoResolveGatewayUnavailableGoals(tickStartedAt: string): Promise<void> {
  let resolvedCount = 0;
  let skippedCount = 0;
  let healthCheckCount = 0;
  try {
    const failureGoals = db.prepare(`
      SELECT DISTINCT g.id, g.project_id, g.title, g.status, g.auto_run_enabled
      FROM development_goals g
      WHERE g.auto_run_enabled = 1
        AND g.status IN ('active', 'running')
        AND (
          EXISTS (
            SELECT 1 FROM development_run_events e
            WHERE e.project_id = g.project_id
              AND e.severity IN ('warn', 'high')
              AND (
                e.event_type LIKE '%dispatch_failure%'
                OR e.event_type LIKE '%gateway_unavailable%'
                OR e.message LIKE '%gateway_unavailable%'
                OR e.message LIKE '%OpenClaw 代理派发失败%'
                OR e.message LIKE '%Gateway 暂不可用%'
                OR e.message LIKE '%Gateway failed%'
              )
              AND e.created_at > datetime('now', '-1 day')
          )
          OR EXISTS (
            SELECT 1 FROM audit_logs a
            WHERE a.target_id = g.id
              AND (
                a.action = 'development.goal.dispatch_recovery_verify_failed'
                OR a.action LIKE '%gateway_unavailable%'
              )
              AND a.ts > datetime('now', '-1 day')
          )
        )
      LIMIT 20
    `).all() as Array<{ id: string; project_id: string; title: string; status: string; auto_run_enabled: number }>;
    if (failureGoals.length === 0) return;
    for (const goal of failureGoals) {
      // 检查 retry cap=3: 看 audit_logs 里 goal.auto_recovery_count
      const goalRow = db.prepare("SELECT metadata FROM development_goals WHERE id = ?").get(goal.id) as { metadata?: string } | undefined;
      const meta = (() => {
        try { return goalRow?.metadata ? JSON.parse(goalRow.metadata) : {}; } catch { return {}; }
      })() as Record<string, unknown>;
      const autoRecoveryCount = Number(meta.autoRecoveryCount || 0);
      if (autoRecoveryCount >= 3) {
        developmentEvent({
          projectId: goal.project_id,
          eventType: "goal_auto_recovery_skipped",
          actor: "main",
          severity: "warn",
          message: `自动恢复达到 cap=3 上限, 等待人工介入: ${goal.title}`,
          payload: { goalId: goal.id, autoRecoveryCount },
        });
        audit(db, "development.goal.auto_recovery_cap", "development_goal", goal.id, "high", { projectId: goal.project_id, autoRecoveryCount });
        skippedCount += 1;
        continue;
      }
      // 检查最近是否已经在 1min 内恢复过 (避免重复 resolve)
      const recentResolvedRow = db.prepare(`
        SELECT ts FROM audit_logs
        WHERE target_id = ? AND action = 'development.goal.dispatch_recovery_resolved'
        ORDER BY ts DESC LIMIT 1
      `).get(goal.id) as { ts?: string } | undefined;
      if (recentResolvedRow?.ts) {
        const ageMs = Date.now() - Date.parse(recentResolvedRow.ts);
        if (ageMs < 60_000) {
          skippedCount += 1;
          continue;
        }
      }
      // 强制刷新 health
      healthCheckCount += 1;
      const health = await refreshLiveGatewayHealth({
        force: true,
        timeoutMs: 15_000,
        source: "development_goal_auto_recovery",
      });
      if (!health.ok) {
        // gateway 仍 down, 跳过 (不增加 count, 等下次 tick)
        skippedCount += 1;
        continue;
      }
      // gateway 恢复, 自动 resolve
      try {
        const resolution = resolveDevelopmentGoalDispatchFailure(goal.id, health);
        if (resolution) {
          // 计数 +1
          meta.autoRecoveryCount = autoRecoveryCount + 1;
          meta.lastAutoRecoveryAt = tickStartedAt;
          db.prepare("UPDATE development_goals SET metadata = ?, updated_at = ? WHERE id = ?")
            .run(JSON.stringify(meta), nowIso(), goal.id);
          developmentEvent({
            projectId: goal.project_id,
            eventType: "goal_auto_recovery_resolved",
            actor: "main",
            severity: "info",
            message: `失败自动恢复成功 (${autoRecoveryCount + 1}/3): ${goal.title} · Gateway ${health.status || "connected"}`,
            payload: { goalId: goal.id, autoRecoveryCount: autoRecoveryCount + 1, healthStatus: health.status },
          });
          audit(db, "development.goal.auto_recovery_resolved", "development_goal", goal.id, "normal", { projectId: goal.project_id, autoRecoveryCount: autoRecoveryCount + 1, healthStatus: health.status });
          resolvedCount += 1;
        }
      } catch (resolveErr) {
        app.log.warn({ err: resolveErr, goalId: goal.id }, "auto recovery resolve threw");
        skippedCount += 1;
      }
    }
  } catch (err) {
    app.log.warn({ err }, "tryAutoResolveGatewayUnavailableGoals failed");
  } finally {
    if (resolvedCount > 0 || skippedCount > 0 || healthCheckCount > 0) {
      developmentGoalAutoLoopState.recoveredRuns += resolvedCount;
      developmentGoalAutoLoopState.skippedGoals += skippedCount;
      developmentGoalAutoLoopState.lastDecision = `auto-recovery: resolved=${resolvedCount} skipped=${skippedCount} healthCheck=${healthCheckCount}`;
      developmentSchedulerDirty = true;
    }
  }
}

/**
 * Sprint2 #5 多目标并行 - 单 goal 处理函数
 * 从 runDevelopmentGoalAutoLoop 提取, 让 autoLoop 用 Promise.all 并行处理多个 goal
 * 自身同步写入 DB / event, 跨 goal 共享 db 写入 (better-sqlite3 同步) 不冲突
 */
async function processAutoLoopGoal(row: Record<string, unknown>, nowMs: number): Promise<void> {
  const goal = developmentGoalView(row);
  const interval = Math.max(5, Math.min(240, Number(goal.heartbeatIntervalMinutes || 30)));
  const nextHeartbeat = new Date(Date.now() + interval * 60 * 1000).toISOString();
  const skip = (message: string, disable = false) => {
    developmentGoalAutoLoopState.skippedGoals += 1;
    developmentGoalAutoLoopState.lastDecision = message;
    developmentSchedulerDirty = true;
    db.prepare("UPDATE development_goals SET auto_run_enabled = ?, next_heartbeat_at = ?, next_action = ?, updated_at = ? WHERE id = ?")
      .run(disable ? 0 : 1, nextHeartbeat, message, nowIso(), goal.id);
    developmentEvent({
      projectId: goal.projectId,
      eventType: "goal_auto_skipped",
      actor: "main",
      severity: disable ? "warn" : "info",
      message,
      payload: { goalId: goal.id, disable, nextHeartbeat },
    });
  };
  try {
    if (goal.autoTurnsUsed >= goal.maxAutoTurns) {
      skip(`自动推进达到本轮上限 ${goal.autoTurnsUsed}/${goal.maxAutoTurns}，等待人工复核后再开启。`, true);
      return;
    }
    const pointers = developmentGoalRuntimePointers(goal.projectId, goal);
    const blockers = [...goal.blockers, ...(pointers.activeSubtask?.blockers || []), ...(pointers.activeWorkPacket?.blockers || [])].filter(Boolean);
    if (blockers.length) {
      skip(`自动推进停止：${blockers[0]}`, true);
      return;
    }
    if (pointers.baseline?.status !== "locked" || !pointers.activeSubtask) {
      skip("自动推进跳过：基线尚未锁定或没有当前子任务。", true);
      return;
    }
    if (["passed", "needs_review", "blocked", "failed"].includes(String(pointers.activeSubtask.status || ""))) {
      const activeSubRow = pointers.activeSubtask;
      const retryAtMs = activeSubRow.retryAt ? Date.parse(activeSubRow.retryAt) : 0;
      const retryCount = Number(activeSubRow.retryCount || 0);
      const nowMs2 = Date.now();
      if (String(activeSubRow.status || "") === "blocked" && retryAtMs > nowMs2) {
        skip(`自动推进 wait: retry ${retryCount}/3, retry_at=${activeSubRow.retryAt} 未到`, false);
        return;
      }
      const isRetryable = (retryAtMs === 0 || retryAtMs <= nowMs2) && retryCount < 3;
      if (String(activeSubRow.status || "") === "blocked" && isRetryable) {
        db.prepare("UPDATE development_subtasks SET status = ?, retry_at = ?, updated_at = ? WHERE id = ?").run("queued", new Date(Date.now() + 5 * 60 * 1000).toISOString(), nowIso(), activeSubRow.id);
        developmentEvent({ projectId: goal.projectId, subtaskId: activeSubRow.id, eventType: "subtask_dispatch_retry_triggered", actor: "main", severity: "info", message: `Retry 到点, 重新激活子任务: ${activeSubRow.title} (retry ${retryCount}/3${retryAtMs === 0 ? ", 原 retry_at 为空, 设为 now+5min" : ""})`, payload: { subtaskId: activeSubRow.id, retryCount, retryAt: activeSubRow.retryAt } });
      } else {
        skip(`自动推进停止：当前子任务状态为 ${activeSubRow.status}，需要人工复核。`, true);
        return;
      }
    }
    reconcileDevelopmentAgentSessionRuns(goal.projectId);
    const activeRun = db.prepare(`
      SELECT *
      FROM development_runs
      WHERE project_id = ? AND mode = 'subtask' AND status IN ('running', 'dispatched')
      ORDER BY started_at DESC
      LIMIT 1
    `).get(goal.projectId) as Record<string, unknown> | undefined;
    if (activeRun) {
      const activeRunId = String(activeRun.id || "");
      const activeRunStarted = String(activeRun.started_at || "");
      const activeAgentId = String(activeRun.active_agent_id || "main");
      const recovery = ensureRunIsRecoverable(goal.projectId, activeRunId, activeAgentId, activeRunStarted, nowMs);
      if (recovery.stale) {
        developmentGoalAutoLoopState.recoveredRuns += 1;
        developmentGoalAutoLoopState.executedGoals += 1;
        developmentGoalAutoLoopState.lastDecision = `recovered stale run ${activeRunId}`;
        developmentSchedulerDirty = true;
        await runDevelopmentGoalAction(goal.id, { action: "auto_continue", message: "自动心跳到期，恢复后台运行后继续推进当前子任务。" });
        return;
      }
      skip(`自动推进跳过：已有后台运行 ${String(activeRun.id || "")}，等待真实回写。`, false);
      return;
    }
    developmentGoalAutoLoopState.executedGoals += 1;
    developmentGoalAutoLoopState.lastDecision = `auto_continue ${goal.id}`;
    developmentSchedulerDirty = true;
    await runDevelopmentGoalAction(goal.id, { action: "auto_continue", message: "自动心跳到期，执行低风险继续。" });
  } catch (err) {
    app.log.warn({ err, goalId: goal.id }, "processAutoLoopGoal failed");
    skip(`自动推进异常: ${err instanceof Error ? err.message : String(err)}`, true);
  }
}

 async function runDevelopmentGoalAutoLoop(targetGoalId = "") {
  if (developmentGoalAutoLoopRunning) return;
  developmentGoalAutoLoopRunning = true;
  const tickStartedAt = nowIso();
  developmentGoalAutoLoopState.running = true;
  developmentGoalAutoLoopState.lastStartedAt = tickStartedAt;
  developmentGoalAutoLoopState.lastAutoTickAt = tickStartedAt;
  developmentGoalAutoLoopState.targetGoalId = targetGoalId;
  developmentGoalAutoLoopState.lastError = "";
  developmentGoalAutoLoopState.scannedGoals =0;
  developmentGoalAutoLoopState.executedGoals =0;
  developmentGoalAutoLoopState.skippedGoals =0;
  developmentGoalAutoLoopState.recoveredRuns =0;
  developmentGoalAutoLoopState.lastDecision = "scan_started";
  developmentSchedulerDirty = true;
  persistDevelopmentGoalAutoLoopState({ force: true });
   try {
     // Sprint2 #4 失败恢复: 自动检测 gateway_unavailable / 派发失败 goal, gateway 恢复后自动 dispatch-recovery resolve
     // 逻辑: 每分钟 health 刷新 + 扫所有 goal, dispatch failure 模式 → health ok → 自动 resolve + 写 recovery_resolved event
     await tryAutoResolveGatewayUnavailableGoals(tickStartedAt);
     ensureDevelopmentSeedData();
    const now = nowIso();
    const nowMs = Date.now();
    const rows = db.prepare(`
      SELECT *
      FROM development_goals
      WHERE auto_run_enabled = 1
        AND status IN ('active', 'running')
        AND COALESCE(next_heartbeat_at, '') != ''
        AND next_heartbeat_at <= ?
        AND (? = '' OR id = ?)
      ORDER BY next_heartbeat_at ASC
      LIMIT 5
    `).all(now, targetGoalId, targetGoalId) as Array<Record<string, unknown>>;
    developmentGoalAutoLoopState.scannedGoals = rows.length;
    developmentGoalAutoLoopState.lastDecision = rows.length ? `scanned ${rows.length} due goals` : "no_due_goals";
     developmentSchedulerDirty = true;
    persistDevelopmentGoalAutoLoopState();
    // Sprint2 #5 多目标并行: 把每个 goal 提到独立函数, Promise.all 并行处理 (NJX 拍板: 3+ goal 真正并行)
    await Promise.all(rows.map((row) => processAutoLoopGoal(row, nowMs)));
  } catch (err) {
    developmentGoalAutoLoopState.lastError = err instanceof Error ? err.message : String(err);
    developmentGoalAutoLoopState.lastDecision = `error: ${developmentGoalAutoLoopState.lastError}`;
    developmentSchedulerDirty = true;
    throw err;
  } finally {
    const nextDue = db.prepare(`
      SELECT id, next_heartbeat_at
      FROM development_goals
      WHERE auto_run_enabled = 1
        AND status IN ('active', 'running')
        AND COALESCE(next_heartbeat_at, '') != ''
      ORDER BY next_heartbeat_at ASC
      LIMIT 1
    `).get() as { id?: string; next_heartbeat_at?: string } | undefined;
    developmentGoalAutoLoopState.nextDueGoalId = String(nextDue?.id || "");
    developmentGoalAutoLoopState.nextDueAt = String(nextDue?.next_heartbeat_at || "");
    developmentGoalAutoLoopState.lastFinishedAt = nowIso();
    developmentGoalAutoLoopState.running = false;
    developmentGoalAutoLoopRunning = false;
    developmentSchedulerDirty = true;
    // 收尾 + 关键状态变更必须立刻落盘（finally 内同步执行，确保进程被 kill 也能保留）
    persistDevelopmentGoalAutoLoopState({ force: true });
  }
}

function refreshDevelopmentBaselineProgress(projectId: string, baselineId?: string) {
  const row = baselineId ? db.prepare("SELECT * FROM development_baselines WHERE id = ?").get(baselineId) as Record<string, unknown> | undefined : developmentBaselineRow(projectId);
  if (!row) return null;
  const subtasks = developmentSubtasks(projectId, String(row.id));
  const firstUnpassed = subtasks.find((item) => item.status !== "passed");
  const passed = subtasks.filter((item) => item.status === "passed").length;
  const nextStatus = subtasks.length && passed === subtasks.length ? "completed" : String(row.status || "draft");
  db.prepare("UPDATE development_baselines SET status = ?, total_subtasks = ?, passed_subtasks = ?, active_subtask_id = ?, updated_at = ? WHERE id = ?")
    .run(nextStatus, subtasks.length, passed, firstUnpassed?.id || "", nowIso(), String(row.id));
  writeDevelopmentBaselineFile(projectId, String(row.id));
  const projectStatus = subtasks.length && passed === subtasks.length
    ? "ready_for_delivery"
    : subtasks.some((item) => ["blocked", "failed"].includes(item.status))
      ? "blocked"
      : nextStatus === "locked" ? "executing" : "baseline_locked";
  db.prepare("UPDATE projects SET status = ?, progress = ?, updated_at = ? WHERE id = ? AND status != 'archived'")
    .run(projectStatus, subtasks.length ? Math.round((passed / subtasks.length) * 100) : 0, nowIso(), projectId);
  return developmentBaselineBundle(projectId);
}

