function readDevelopmentGateConfig() {
  const fallback = [
    { key: "prd_required", label: "PRD 必须存在", category: "product", required: true, command: "read development_documents.PRD", description: "无 PRD 不进入 build。" },
    { key: "test_evidence_required", label: "测试证据必须存在", category: "engineering", required: true, command: "npm run check && npm run test:prd", description: "无测试证据不进入 release。" },
    { key: "release_approval", label: "正式发布必须审批", category: "release", required: true, command: "approval gate", description: "正式发布必须人工审批。" },
    { key: "no_fake_ok", label: "禁止 fake OK", category: "autonomy", required: true, command: "assert degraded dependencies stay visible", description: "降级依赖必须显式显示。" },
  ];
  try {
    const data = readJsonFileObject(DEVELOPMENT_GATES_CONFIG_PATH);
    const gates = Array.isArray(data.gates) ? data.gates as Array<Record<string, unknown>> : [];
    return gates.length ? gates.map((gate) => ({
      key: String(gate.key || ""),
      label: String(gate.label || gate.key || ""),
      category: String(gate.category || "quality"),
      required: gate.required !== false,
      command: String(gate.command || ""),
      description: String(gate.description || ""),
    })).filter((gate) => gate.key && gate.label) : fallback;
  } catch {
    return fallback;
  }
}

