function createDevelopmentWorkPacket(projectId: string, body: { title?: string; objective?: string; scope?: string; stageKey?: string; ownerAgentId?: string; status?: string; acceptanceCriteria?: string[]; nextAction?: string }) {
  const now = nowIso();
  const title = String(body.title || "新开发包").slice(0, 160);
  const id = `wp-${safeName(title).toLowerCase()}-${randomUUID().slice(0, 8)}`;
  db.prepare(`
    INSERT INTO development_work_packets (id, project_id, title, objective, scope, stage_key, owner_agent_id, status, acceptance_criteria, blockers, next_action, active_task_id, created_at, updated_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `).run(id, projectId, title, String(body.objective || title), String(body.scope || ""), String(body.stageKey || "intake"), cleanAgentId(body.ownerAgentId) || "main", String(body.status || "planned"), JSON.stringify(body.acceptanceCriteria || ["PRD 存在", "计划存在", "测试证据存在"]), "[]", String(body.nextAction || "补齐 PRD/PLAN 并运行 shadow 检查。"), null, now, now);
  developmentEvent({ projectId, eventType: "work_packet_created", actor: "owner", severity: "info", message: `新增开发包：${title}`, payload: { workPacketId: id } });
  audit(db, "development.work_packet.create", "work_packet", id, "normal", { projectId, title });
  return developmentWorkPacketById(id);
}

function updateDevelopmentWorkPacket(packetId: string, body: { title?: string; objective?: string; scope?: string; stageKey?: string; ownerAgentId?: string; status?: string; acceptanceCriteria?: string[]; blockers?: string[]; nextAction?: string; activeTaskId?: string }) {
  const current = db.prepare("SELECT * FROM development_work_packets WHERE id = ?").get(packetId) as Record<string, unknown> | undefined;
  if (!current) return null;
  const now = nowIso();
  const nextActiveTaskId = body.activeTaskId !== undefined ? String(body.activeTaskId || "") : String(current.active_task_id || "");
  db.prepare(`
    UPDATE development_work_packets
    SET title = ?, objective = ?, scope = ?, stage_key = ?, owner_agent_id = ?, status = ?, acceptance_criteria = ?, blockers = ?, next_action = ?, active_task_id = ?, updated_at = ?
    WHERE id = ?
  `).run(
    String(body.title ?? current.title ?? ""),
    String(body.objective ?? current.objective ?? ""),
    String(body.scope ?? current.scope ?? ""),
    String(body.stageKey ?? current.stage_key ?? "intake"),
    cleanAgentId(body.ownerAgentId ?? current.owner_agent_id) || "main",
    String(body.status ?? current.status ?? "planned"),
    JSON.stringify(body.acceptanceCriteria ?? parseJsonArray(current.acceptance_criteria)),
    JSON.stringify(body.blockers ?? parseJsonArray(current.blockers)),
    String(body.nextAction ?? current.next_action ?? ""),
    nextActiveTaskId || null,
    now,
    packetId,
  );
  const updated = developmentWorkPacketById(packetId);
  if (updated) developmentEvent({ projectId: updated.projectId, eventType: "work_packet_updated", actor: "owner", severity: "info", message: `开发包已更新：${updated.title}`, payload: { workPacketId: packetId, status: updated.status } });
  audit(db, "development.work_packet.update", "work_packet", packetId, "normal", body);
  return updated;
}

function developmentToolRegistry(projectId: string) {
  return (db.prepare("SELECT * FROM development_tool_registry WHERE project_id = ? ORDER BY CASE risk_level WHEN 'high' THEN 0 WHEN 'normal' THEN 1 ELSE 2 END, category ASC, tool_key ASC").all(projectId) as Array<Record<string, unknown>>)
    .map((tool) => {
      const view = {
        id: String(tool.id || ""),
        projectId: String(tool.project_id || ""),
        key: String(tool.tool_key || ""),
        label: String(tool.label || ""),
        category: String(tool.category || ""),
        riskLevel: String(tool.risk_level || "low"),
        approvalPolicy: String(tool.approval_policy || "auto_allow"),
        hookPoints: parseJsonArray(tool.hook_points),
        enabled: Boolean(tool.enabled),
        lastStatus: String(tool.last_status || "unknown"),
        lastRunAt: String(tool.last_run_at || ""),
        metadata: safeJsonObject(tool.metadata),
        updatedAt: String(tool.updated_at || ""),
      };
      if (view.key !== "web_search") return view;
      const gate = developmentGates(projectId, "", 40).find((item) => item.key === "no_fake_ok");
      const evidence = `${gate?.status || ""} ${gate?.evidence || ""} ${view.lastStatus}`.toLowerCase();
      if (/invalid|无效|subscription token/i.test(evidence)) {
        return { ...view, lastStatus: "INVALID_RESEARCH_PROVIDER", metadata: { ...view.metadata, effectiveStatusReason: gate?.evidence || "search credential invalid" } };
      }
      if (/blocked|未配置|missing|degraded|降级|brave/i.test(evidence) && !/validated|web_search_validated/i.test(evidence)) {
        return { ...view, lastStatus: "DEGRADED_RESEARCH_PROVIDER", metadata: { ...view.metadata, effectiveStatusReason: gate?.evidence || "search provider degraded" } };
      }
      return view;
    });
}

