function writeDevelopmentContextManifest(projectId: string, runId = "", workPacketId = "", trigger = "manual") {
  const manifest = buildDevelopmentContextManifest(projectId, runId, workPacketId, trigger);
  const id = `ctx-${projectId}-${Date.now()}-${randomUUID().slice(0, 8)}`;
  db.prepare("INSERT INTO development_context_manifests (id, project_id, run_id, work_packet_id, status, summary, manifest_json, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)")
    .run(id, projectId, runId || null, workPacketId || null, manifest.status, manifest.summary, JSON.stringify(manifest), nowIso());
  const manifestDir = path.join(WORKSPACE_DIR, "memory", "reports", "development_context_manifests");
  fs.mkdirSync(manifestDir, { recursive: true });
  const manifestPath = path.join(manifestDir, `${safeName(id)}.json`);
  fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 2));
  upsertDevelopmentDocument(projectId, { key: "context", label: "上下文", title: path.basename(manifestPath), kind: "document", path: manifestPath, url: "", summary: "Development Core v2 每次运行前编译的项目上下文、工具状态、门控和阻塞。", sortOrder: 95 });
  db.prepare("INSERT INTO development_artifacts (id, project_id, run_id, task_id, artifact_type, title, path, url, status, evidence_level, metadata, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
    .run(`artifact-${id}`, projectId, runId || null, null, "context_manifest", "Context Manifest", manifestPath, "", "available", "source", JSON.stringify({ workPacketId, trigger }), nowIso());
  return { id, path: manifestPath, manifest };
}

function buildDevelopmentContextManifest(projectId: string, runId = "", workPacketId = "", trigger = "manual") {
  const project = db.prepare("SELECT p.*, dp.objective dev_objective, dp.repo_path, dp.task_dir, dp.preview_url, dp.default_model_id, dp.default_agent_policy FROM projects p JOIN development_project_profiles dp ON dp.project_id = p.id WHERE p.id = ?").get(projectId) as Record<string, unknown> | undefined;
  const workPacket = workPacketId ? developmentWorkPacketById(workPacketId) : developmentActiveWorkPacket(projectId);
  const activeGoal = developmentActiveGoal(projectId);
  const documents = developmentDocuments(projectId);
  const tasks = developmentTasks(projectId, 30);
  const gates = developmentGates(projectId, "", 40);
  const tools = developmentToolRegistry(projectId);
  const blockers = [
    ...(workPacket?.blockers || []),
    ...gates.filter((gate) => ["BLOCKED", "FAIL", "ERROR", "WARN"].includes(gate.status)).map((gate) => `${gate.label}: ${gate.evidence || gate.status}`),
    ...tools.filter((tool) => /degraded|blocked|error/i.test(tool.lastStatus)).map((tool) => `${tool.label}: ${tool.lastStatus}`),
  ];
  const docRefs = documents.map((doc) => ({ key: doc.key, title: doc.title, status: doc.status, path: doc.path, url: doc.url }));
  return {
    schemaVersion: "development-context-manifest/v2",
    generatedAt: nowIso(),
    trigger,
    status: blockers.length ? "DEGRADED" : "OK",
    summary: blockers.length ? `${blockers.length} 个阻塞或降级项，禁止 fake OK。` : "上下文可用，等待质量门验证。",
    project: project ? {
      id: projectId,
      name: String(project.name || ""),
      status: String(project.status || ""),
      objective: String(project.dev_objective || project.objective || ""),
      repoPath: String(project.repo_path || ""),
      taskDir: String(project.task_dir || ""),
      previewUrl: String(project.preview_url || ""),
      modelId: String(project.default_model_id || "minimax-m3"),
      agentPolicy: String(project.default_agent_policy || "auto"),
    } : { id: projectId },
    run: { id: runId, mode: runId ? "active" : "seed" },
    activeGoal,
    workPacket,
    documents: docRefs,
    tasks: tasks.map((task) => ({ id: task.id, title: task.title, status: task.status, agentId: task.agentId, priority: task.priority })),
    gates,
    tools,
    blockers,
    humanBoundaries: ["gateway_restart", "external_notification", "production_release", "delete_protected_docs", "paid_resource"],
  };
}

function developmentLatestContextManifest(projectId: string) {
  const row = db.prepare("SELECT * FROM development_context_manifests WHERE project_id = ? ORDER BY created_at DESC LIMIT 1").get(projectId) as Record<string, unknown> | undefined;
  if (!row) return null;
  return {
    id: String(row.id || ""),
    projectId: String(row.project_id || ""),
    runId: String(row.run_id || ""),
    workPacketId: String(row.work_packet_id || ""),
    status: String(row.status || ""),
    summary: String(row.summary || ""),
    manifest: safeJsonObject(row.manifest_json),
    createdAt: String(row.created_at || ""),
  };
}

function sanitizeDevelopmentTimelineMessage(input: unknown, maxLength = 460) {
  let text = String(input || "");
  text = text
    .replace(/<think>[\s\S]*?<\/think>/gi, "代理思考已收敛为可见执行记录。")
    .replace(/<\/?(final|answer|analysis|commentary)>/gi, "")
    .replace(/\bOpenClaw\s+(main|boss|worker)\s+代理反馈：\s*/gi, "")
    .replace(/\bOpenClaw\s+(main|boss|worker)\s+代理最终回写：\s*/gi, "")
    .replace(/\s+/g, " ")
    .trim();
  if (!text) return "事件已记录。";
  if (text.length <= maxLength) return text;
  return `${text.slice(0, maxLength - 1).trim()}…`;
}

function developmentGateView(gate: Record<string, unknown>) {
  const key = String(gate.gate_key || "");
  let evidence = String(gate.evidence || "");
  if (evidence === "[object Object]") evidence = "结构化测试证据已记录，打开测试报告或 artifact 查看详情。";
  let status = String(gate.status || "");
  let severity = String(gate.severity || "");
  if (key === "no_fake_ok" && status.toUpperCase() === "PASS" && /degraded|降级|未配置|invalid|无效|Brave/i.test(evidence)) {
    status = "WARN";
    severity = severity || "warn";
  }
  return {
    id: String(gate.id || ""),
    runId: String(gate.run_id || ""),
    key,
    label: String(gate.label || ""),
    status,
    severity,
    evidence,
    required: Boolean(gate.required),
    updatedAt: String(gate.updated_at || ""),
  };
}

function developmentGateRank(gate: { status?: string; severity?: string; updatedAt?: string }) {
  const status = String(gate.status || "").toUpperCase();
  const severity = String(gate.severity || "").toLowerCase();
  if (["BLOCKED", "FAIL", "ERROR"].includes(status) || severity === "high") return 0;
  if (["WARN", "PENDING"].includes(status) || severity === "warn") return 1;
  if (["PASS", "OK", "VALIDATED"].includes(status)) return 3;
  return 2;
}

function developmentLatestReviews(projectId: string, limit = 20) {
  const latest = new Map<string, ReturnType<typeof developmentReviewRecords>[number]>();
  for (const review of developmentReviewRecords(projectId, "", Math.max(limit * 3, limit))) {
    if (!latest.has(review.reviewerKey)) latest.set(review.reviewerKey, review);
  }
  return Array.from(latest.values()).slice(0, limit);
}

function developmentCapabilityTone(status: string) {
  const value = status.toUpperCase();
  if (["OK", "PASS", "VALIDATED", "AVAILABLE"].includes(value)) return "ok";
  if (["BLOCKED", "ERROR", "FAIL", "INVALID"].includes(value) || value.includes("INVALID")) return "error";
  return "warn";
}

function developmentCapabilityHealth(projectId: string, input: { gates?: ReturnType<typeof developmentGates>; latestRun?: ReturnType<typeof developmentLatestRun> } = {}) {
  const project = db.prepare(`
    SELECT p.id, p.name, p.status, p.updated_at, dp.repo_path, dp.task_dir, dp.preview_url
    FROM projects p
    JOIN development_project_profiles dp ON dp.project_id = p.id
    WHERE p.id = ?
  `).get(projectId) as Record<string, unknown> | undefined;
  const gates = input.gates || developmentGates(projectId, "", 80);
  const latestRun = input.latestRun || developmentLatestRun(projectId);
  const events = db.prepare("SELECT COUNT(*) count FROM development_run_events WHERE project_id = ?").get(projectId) as { count?: number } | undefined;
  const pendingApproval = db.prepare("SELECT COUNT(*) count FROM approvals WHERE status IN ('pending','requested') AND details LIKE ?").get(`%"projectId":"${projectId}"%`) as { count?: number } | undefined;
  const reviews = developmentLatestReviews(projectId, 12);
  const noFakeOk = gates.find((gate) => gate.key === "no_fake_ok");
  const noFakeText = `${noFakeOk?.status || ""} ${noFakeOk?.evidence || ""}`.toLowerCase();
  const searchStatus = /invalid|无效|subscription token/.test(noFakeText)
    ? "BLOCKED"
    : /blocked|未配置|missing/.test(noFakeText)
      ? "BLOCKED"
      : /degraded|降级|warn/.test(noFakeText)
        ? "DEGRADED"
        : /validated|web_search_validated|pass|ok/.test(noFakeText)
          ? "OK"
          : "PENDING";
  const blockerGates = gates.filter((gate) => ["BLOCKED", "FAIL", "ERROR"].includes(String(gate.status).toUpperCase()));
  const warnGates = gates.filter((gate) => ["WARN", "PENDING"].includes(String(gate.status).toUpperCase()));
  const weakReviews = reviews.filter((review) => ["WARN", "FAIL", "BLOCKED", "ERROR"].includes(String(review.status).toUpperCase()) || review.score < 85);
  const repoPath = String(project?.repo_path || "");
  const taskDir = String(project?.task_dir || "");
  const repoOk = !repoPath || fs.existsSync(repoPath);
  const taskDirOk = !taskDir || fs.existsSync(taskDir);
  const runStatus = String(latestRun?.status || "");
  const runHealth = /gateway_unavailable|blocked|error|failed/i.test(runStatus)
    ? "BLOCKED"
    : /running|dispatched/i.test(runStatus)
      ? "RUNNING"
      : latestRun ? "OK" : "PENDING";
  const items = [
    {
      key: "research_provider",
      label: "Research Provider",
      status: searchStatus,
      summary: searchStatus === "OK"
        ? "搜索能力通过真实验证，可作为调研证据。"
        : searchStatus === "DEGRADED"
          ? "搜索能力处于降级状态，必须明示 fallback 证据。"
          : searchStatus === "BLOCKED"
            ? "搜索配置或凭据未通过，禁止假完成。"
            : "等待搜索能力验证。",
      evidence: noFakeOk?.evidence || "no_fake_ok gate pending",
      updatedAt: noFakeOk?.updatedAt || "",
    },
    {
      key: "release_approval",
      label: "Release Approval",
      status: Number(pendingApproval?.count || 0) > 0 ? "BLOCKED" : "OK",
      summary: Number(pendingApproval?.count || 0) > 0 ? `${pendingApproval?.count} 个发布/高风险审批待处理。` : "暂无待处理发布审批。",
      evidence: "approvals table",
      updatedAt: nowIso(),
    },
    {
      key: "quality_gates",
      label: "Quality Gates",
      status: blockerGates.length ? "BLOCKED" : warnGates.length || weakReviews.length ? "WARN" : "OK",
      summary: blockerGates.length
        ? `${blockerGates.length} 个阻塞门控。`
        : warnGates.length || weakReviews.length
          ? `${warnGates.length + weakReviews.length} 个警告/低分项。`
          : "质量门当前无阻塞。",
      evidence: [...blockerGates, ...warnGates].slice(0, 3).map((gate) => `${gate.label}:${gate.status}`).join("; ") || "latest gates",
      updatedAt: gates[0]?.updatedAt || "",
    },
    {
      key: "workspace",
      label: "Project Workspace",
      status: repoOk && taskDirOk ? "OK" : "BLOCKED",
      summary: repoOk && taskDirOk ? "项目仓库和任务目录可读。" : "项目工作区路径不可读，需要修复路径或权限。",
      evidence: [repoPath || "repo optional", taskDir || "taskDir optional"].join(" | "),
      updatedAt: String(project?.updated_at || ""),
    },
    {
      key: "event_stream",
      label: "Event Stream",
      status: Number(events?.count || 0) > 0 ? "OK" : "WARN",
      summary: Number(events?.count || 0) > 0 ? `${events?.count} 条开发事件可追溯。` : "还没有真实开发事件。",
      evidence: "development_run_events",
      updatedAt: "",
    },
    {
      key: "agent_runtime",
      label: "Agent Runtime",
      status: runHealth,
      summary: latestRun ? `最近运行：${runStatus || "unknown"} · ${latestRun.activeAgentId || "main"}` : "尚未触发开发运行。",
      evidence: latestRun?.summary ? sanitizeDevelopmentTimelineMessage(latestRun.summary, 900) : "development_runs",
      updatedAt: latestRun?.completedAt || latestRun?.startedAt || "",
    },
  ];
  return items.map((item) => ({ ...item, tone: developmentCapabilityTone(item.status) }));
}

function syncWorkPacketAfterRun(packetId: string, status: string, delivery: Record<string, unknown>) {
  if (!packetId) return;
  const blockers = Array.isArray(delivery.blockers) ? (delivery.blockers as Array<Record<string, unknown>>).map((blocker) => String(blocker.message || blocker.id || "存在阻塞。")) : [];
  const normalized = status.toLowerCase().includes("error") ? "blocked" : status.toLowerCase().includes("degraded") ? "degraded" : blockers.length ? "blocked" : "completed";
  updateDevelopmentWorkPacket(packetId, {
    status: normalized,
    blockers,
    nextAction: blockers.length ? blockers[0] : normalized === "completed" ? "进入 review/release gate 前确认测试证据。" : "继续补齐开发证据。",
  });
}

function developmentTasks(projectId: string, limit = 40) {
  return (db.prepare("SELECT * FROM tasks WHERE project_id = ? ORDER BY CASE status WHEN 'blocked' THEN 0 WHEN 'running' THEN 1 WHEN 'planned' THEN 2 WHEN 'awaiting_confirmation' THEN 3 WHEN 'completed' THEN 8 ELSE 4 END, updated_at DESC LIMIT ?").all(projectId, limit) as Array<Record<string, unknown>>)
    .map((task) => ({
      id: String(task.id || ""),
      title: String(task.title || ""),
      description: String(task.description || ""),
      agentId: String(task.agent_id || ""),
      status: String(task.status || ""),
      priority: String(task.priority || "P2"),
      updatedAt: String(task.updated_at || ""),
      tags: parseJsonArray(task.tags),
    }));
}

function developmentEvents(projectId: string, limit = 80) {
  const rows = db.prepare("SELECT * FROM development_run_events WHERE project_id = ? ORDER BY created_at DESC LIMIT ?").all(projectId, Math.max(limit * 3, limit)) as Array<Record<string, unknown>>;
  const seen = new Set<string>();
  const events = [];
  for (const event of rows) {
    const message = sanitizeDevelopmentTimelineMessage(event.message);
    const key = [
      String(event.subtask_id || ""),
      String(event.event_type || ""),
      String(event.actor || ""),
      message.slice(0, 220),
    ].join("|");
    if (seen.has(key)) continue;
    seen.add(key);
    const payload = safeJsonObject(event.payload);
    if (typeof payload.gatewayText === "string") payload.gatewayText = sanitizeDevelopmentTimelineMessage(payload.gatewayText, 900);
    if (typeof payload.finalText === "string") payload.finalText = sanitizeDevelopmentTimelineMessage(payload.finalText, 900);
    events.push({
      id: String(event.id || ""),
      runId: String(event.run_id || ""),
      taskId: String(event.task_id || ""),
      subtaskId: String(event.subtask_id || ""),
      type: String(event.event_type || ""),
      actor: String(event.actor || ""),
      severity: String(event.severity || "info"),
      message,
      payload,
      createdAt: String(event.created_at || ""),
    });
    if (events.length >= limit) break;
  }
  return events;
}

function developmentEventStats(projectId: string) {
  const rows = db.prepare(`
    SELECT event_type AS type,
      COUNT(*) AS count,
      COALESCE(SUM(LENGTH(message)), 0) AS chars,
      COALESCE(SUM(CASE WHEN event_type IN ('goal_heartbeat', 'goal_auto_tick', 'goal_auto_enabled', 'goal_auto_disabled', 'goal_auto_skipped', 'goal_updated', 'goal_created', 'goal_continuation_contract', 'goal_runway_refreshed') THEN 1 ELSE 0 END), 0) AS noiseCount,
      COALESCE(SUM(CASE WHEN event_type IN ('goal_heartbeat', 'goal_auto_tick', 'goal_auto_enabled', 'goal_auto_disabled', 'goal_updated', 'goal_created', 'goal_continuation_contract', 'goal_runway_refreshed') THEN COALESCE(LENGTH(message), 0) ELSE 0 END), 0) AS noiseChars
    FROM development_run_events
    WHERE project_id = ?
    GROUP BY event_type
  `).all(projectId) as Array<Record<string, unknown>>;
  const byType: Record<string, number> = {};
  let totalCount = 0;
  let totalMessageChars = 0;
  let productiveCount = 0;
  let productiveMessageChars = 0;
  let noiseCount = 0;
  let noiseMessageChars = 0;
  for (const row of rows) {
    const type = String(row.type || "unknown");
    const count = Number(row.count || 0);
    const chars = Number(row.chars || 0);
    const noiseRows = Number(row.noiseCount || 0);
    const noiseChars = Number(row.noiseChars || 0);
    totalCount += Number.isFinite(count) ? count : 0;
    totalMessageChars += Number.isFinite(chars) ? chars : 0;
    byType[type] = count;
    const eventTypeIsNoise = DEVELOPMENT_STAT_NOISE_EVENTS.has(type);
    if (eventTypeIsNoise) {
      noiseCount += Number.isFinite(noiseRows) ? noiseRows : 0;
      noiseMessageChars += Number.isFinite(noiseChars) ? noiseChars : 0;
    } else {
      productiveCount += Number.isFinite(count) ? count : 0;
      productiveMessageChars += Number.isFinite(chars) ? chars : 0;
    }
  }
  const artifactCount = db.prepare("SELECT COUNT(*) AS count FROM development_artifacts WHERE project_id = ?").get(projectId) as { count?: number } | undefined;
  const latest = db.prepare(`
    SELECT id, created_at, message, event_type
    FROM development_run_events
    WHERE project_id = ?
    ORDER BY created_at DESC
    LIMIT 1
  `).get(projectId) as { id?: string; created_at?: string; message?: string; event_type?: string } | undefined;
  const runCount = db.prepare("SELECT COUNT(*) AS count FROM development_runs WHERE project_id = ?").get(projectId) as { count?: number } | undefined;
  return {
    totalCount,
    totalMessageChars,
    productiveMessageChars: productiveMessageChars,
    productiveEventCount: productiveCount,
    noiseMessageChars,
    noiseEventCount: noiseCount,
    artifactCount: Number(artifactCount?.count || 0),
    byType,
    latestEventId: String(latest?.id || ""),
    latestEventType: String(latest?.event_type || ""),
    latestEventMessage: latest?.message ? sanitizeDevelopmentTimelineMessage(latest.message).slice(0, 260) : "",
    latestCreatedAt: String(latest?.created_at || ""),
    runCount: Number(runCount?.count || 0),
  };
}

function reconcileDevelopmentAgentSessionRuns(projectId: string) {
  const nowMs = Date.now();
  const staleCutoffMs = nowMs - 30 * 60 * 1000;
  const parseMs = (value: string, fallback: number) => {
    const parsed = Date.parse(value);
    return Number.isFinite(parsed) ? parsed : fallback;
  };
  const runs = db.prepare(`
    SELECT *
    FROM development_runs
    WHERE project_id = ?
      AND mode = 'subtask'
      AND status IN ('running', 'dispatched')
    ORDER BY started_at DESC
    LIMIT 20
  `).all(projectId) as Array<Record<string, unknown>>;
  for (const run of runs) {
    const runId = String(run.id || "");
    if (!runId) continue;
    const startedAt = String(run.started_at || run.created_at || "");
    const startedMs = parseMs(startedAt, nowMs);
    const agentId = String(run.active_agent_id || "main");
    const toolEvent = db.prepare(`
      SELECT *
      FROM development_run_events
      WHERE project_id = ? AND run_id = ? AND event_type = 'tool_call'
      ORDER BY created_at DESC
      LIMIT 1
    `).get(projectId, runId) as Record<string, unknown> | undefined;
    const subtaskId = String(toolEvent?.subtask_id || "");
    const subtask = subtaskId ? developmentSubtaskById(subtaskId) : null;
    if (subtask && toolEvent) {
      const payload = safeJsonObject(toolEvent.payload);
      const sessionKey = String(payload.sessionKey || `agent:${agentId}:workbench:development:${projectId}:${subtaskId}`);
      const finalText = recoverGatewayFinalFromSession(agentId, sessionKey, Math.max(0, startedMs - 1000)).trim();
      if (finalText) {
        const finishedAt = nowIso();
        const durationMs = Math.max(0, Date.parse(finishedAt) - startedMs);
        const autoAcceptedDegradedSearch = isWebSearchDegradedAcceptance(subtask, finalText);
        const blocked = !autoAcceptedDegradedSearch && /status\s*:\s*blocked|status:\s*BLOCKED|BLOCKED|阻塞|无法访问|Path escapes sandbox|sandbox|cannot access|No such file|failed|error/i.test(finalText);
        const blockers = autoAcceptedDegradedSearch ? [] : blocked ? [inferDevelopmentSessionBlocker(finalText, subtask)].filter(Boolean) as string[] : [];
        const subtaskStatus = autoAcceptedDegradedSearch ? "passed" : blocked ? "blocked" : "needs_review";
        const runStatus = blocked ? "blocked" : "completed";
        const summary = `OpenClaw ${agentId} 代理最终回写：${finalText.replace(/\s+/g, " ").slice(0, 900)}`;
        db.prepare("UPDATE development_runs SET status = ?, completed_at = ?, duration_ms = ?, summary = ? WHERE id = ?")
          .run(runStatus, finishedAt, durationMs, summary, runId);
        db.prepare("UPDATE development_subtasks SET status = ?, blockers = ?, completed_at = CASE WHEN ? = 'passed' THEN ? ELSE completed_at END, updated_at = ? WHERE id = ?")
          .run(subtaskStatus, JSON.stringify(blockers), subtaskStatus, finishedAt, finishedAt, subtaskId);
        developmentEvent({
          projectId,
          runId,
          subtaskId,
          eventType: blocked ? "blocker" : "review",
          actor: agentId,
          severity: blocked ? "warn" : "info",
          message: summary,
          payload: { source: "agent_session_reconcile", sessionKey, finalText: finalText.slice(0, 2500), blockers, autoAcceptedDegradedSearch },
        });
        writeDevelopmentSubtaskResultFromSession(subtask, subtaskStatus, finalText, blockers, agentId);
 if (autoAcceptedDegradedSearch) {
 const acceptanceId = `accept-${subtaskId}-${Date.now()}`;
 db.prepare("INSERT INTO development_subtask_acceptance (id, subtask_id, project_id, run_id, status, reviewer, score, summary, evidence, blockers, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
 .run(acceptanceId, subtaskId, projectId, runId, "passed", "top_ai_pm",95, "降级搜索方案验收通过：保留 DEGRADED 明示和 no_fake_ok gate，允许基线推进。", finalText.slice(0,4000), "[]", finishedAt);
 developmentEvent({
 projectId,
 runId,
 subtaskId,
 eventType: "subtask_acceptance",
 actor: "top_ai_pm",
 severity: "info",
 message: `子任务验收通过：${subtask.title}`,
 payload: { acceptanceId, score:95, status: "passed", blockers: [] },
 });
 audit(db, "development.subtask.acceptance", "development_subtask", subtaskId, "normal", { projectId, status: "passed", score:95, autoAcceptedDegradedSearch: true, source: "agent_session_reconcile" });
 }
 // P0 (goal-progression):代理 session 回写完成后立即扫描 evidence_dir / artifacts_dir。
 try {
 reconcileDevelopmentSubtaskEvidence(subtaskId, { forceReindex: false });
 } catch (err) {
 app.log.warn({ err, subtaskId }, "reconcileDevelopmentAgentSessionRuns: reconcileDevelopmentSubtaskEvidence failed");
 }
 audit(db, "development.subtask.session_reconcile", "development_run", runId, blocked ? "high" : "normal", { projectId, subtaskId, agentId, status: subtaskStatus });
 refreshDevelopmentBaselineProgress(projectId, subtask.baselineId);
 continue;
      }
    }
    const latestEvent = db.prepare(`
      SELECT created_at
      FROM development_run_events
      WHERE project_id = ? AND run_id = ?
      ORDER BY created_at DESC
      LIMIT 1
    `).get(projectId, runId) as { created_at?: string } | undefined;
    const latestMs = parseMs(String(latestEvent?.created_at || startedAt), startedMs);
    if (latestMs > staleCutoffMs) continue;

    const originalStatus = String(run.status || "running");
    const summary = `OpenClaw ${agentId} 代理运行超过 30 分钟无新事件，已转为待接管状态；原状态为 ${originalStatus}，等待真实回写或人工处理。`;
    db.prepare("UPDATE development_runs SET status = ?, duration_ms = ?, summary = ? WHERE id = ?")
      .run("error", Math.max(0, nowMs - startedMs), summary, runId);
    const existing = db.prepare(`
      SELECT id
      FROM development_run_events
      WHERE project_id = ?
        AND run_id = ?
        AND event_type = 'blocker'
        AND message = ?
      LIMIT 1
    `).get(projectId, runId, summary);
    if (!existing) {
      developmentEvent({
        projectId,
        runId,
        eventType: "blocker",
        actor: agentId,
        severity: "warn",
        message: summary,
        payload: {
          source: "development_agent_session_reconcile",
          staleSeconds: Math.max(0, Math.floor((nowMs - latestMs) / 1000)),
        },
      });
    }
  }
}

function developmentArtifacts(projectId: string, runId = "", limit = 80) {
  const rows = runId
    ? db.prepare("SELECT * FROM development_artifacts WHERE project_id = ? AND run_id = ? ORDER BY created_at DESC LIMIT ?").all(projectId, runId, limit)
    : db.prepare("SELECT * FROM development_artifacts WHERE project_id = ? ORDER BY created_at DESC LIMIT ?").all(projectId, limit);
  return (rows as Array<Record<string, unknown>>).map((artifact) => ({
    id: String(artifact.id || ""),
    runId: String(artifact.run_id || ""),
    taskId: String(artifact.task_id || ""),
    type: String(artifact.artifact_type || ""),
    title: String(artifact.title || ""),
    path: String(artifact.path || ""),
    url: String(artifact.url || ""),
    status: String(artifact.status || ""),
    evidenceLevel: String(artifact.evidence_level || ""),
    metadata: safeJsonObject(artifact.metadata),
    createdAt: String(artifact.created_at || ""),
  }));
}

function developmentArtifactById(artifactId: string) {
  const row = db.prepare("SELECT * FROM development_artifacts WHERE id = ?").get(artifactId) as Record<string, unknown> | undefined;
  if (!row) return null;
  const view = {
    id: String(row.id || ""),
    projectId: String(row.project_id || ""),
    runId: String(row.run_id || ""),
    taskId: String(row.task_id || ""),
    type: String(row.artifact_type || ""),
    title: String(row.title || ""),
    path: String(row.path || ""),
    url: String(row.url || ""),
    status: String(row.status || ""),
    evidenceLevel: String(row.evidence_level || ""),
    metadata: safeJsonObject(row.metadata),
    createdAt: String(row.created_at || ""),
  };
  const resolved = resolveDevelopmentArtifactPath(view.path);
  if (!resolved) {
    return {
      ...view,
      sourceStatus: view.path ? "blocked" : "metadata",
      ext: view.path ? path.extname(view.path).toLowerCase() : ".json",
      content: JSON.stringify(view.metadata, null, 2),
      rawUrl: "",
    };
  }
  const ext = path.extname(resolved).toLowerCase();
  const image = [".png", ".jpg", ".jpeg", ".webp"].includes(ext);
  const stat = fs.statSync(resolved);
  return {
    ...view,
    path: resolved,
    name: path.basename(resolved),
    ext,
    size: stat.size,
    mtime: stat.mtime.toISOString(),
    sourceStatus: "available",
    content: image ? "" : readTextFile(resolved, 240_000),
    rawUrl: `/api/development/artifacts/${encodeURIComponent(view.id)}/raw`,
  };
}

function developmentGates(projectId: string, runId = "", limit = 80) {
  const rows = runId
    ? db.prepare("SELECT * FROM development_gates WHERE project_id = ? AND run_id = ? ORDER BY updated_at DESC LIMIT ?").all(projectId, runId, limit)
    : db.prepare("SELECT * FROM development_gates WHERE project_id = ? ORDER BY updated_at DESC LIMIT ?").all(projectId, Math.max(limit * 3, limit));
  const views = (rows as Array<Record<string, unknown>>).map(developmentGateView);
  if (runId) return views;
  const latestByKey = new Map<string, typeof views[number]>();
  for (const gate of views) {
    if (!latestByKey.has(gate.key)) latestByKey.set(gate.key, gate);
  }
  return Array.from(latestByKey.values())
    .sort((a, b) => {
      const rankDelta = developmentGateRank(a) - developmentGateRank(b);
      if (rankDelta !== 0) return rankDelta;
      return Date.parse(b.updatedAt || "") - Date.parse(a.updatedAt || "");
    })
    .slice(0, limit);
}

function developmentLatestRun(projectId: string) {
  const run = db.prepare("SELECT * FROM development_runs WHERE project_id = ? ORDER BY started_at DESC LIMIT 1").get(projectId) as Record<string, unknown> | undefined;
  return run ? developmentRunView(run) : null;
}

function developmentRunView(run: Record<string, unknown>) {
  return {
    id: String(run.id || ""),
    projectId: String(run.project_id || ""),
    mode: String(run.mode || ""),
    triggerType: String(run.trigger_type || ""),
    status: String(run.status || ""),
    activeAgentId: String(run.active_agent_id || ""),
    startedAt: String(run.started_at || ""),
    completedAt: String(run.completed_at || ""),
    durationMs: Number(run.duration_ms || 0),
    summary: String(run.summary || ""),
    deliveryReportPath: String(run.delivery_report_path || ""),
    createdAt: String(run.created_at || ""),
  };
}

function developmentEvent(input: { projectId: string; runId?: string; taskId?: string | null; subtaskId?: string | null; eventType: string; actor: string; severity: string; message: string; payload?: unknown }) {
  const eventType = DEVELOPMENT_STANDARD_EVENT_TYPES.has(input.eventType) ? input.eventType : "message";
  let runId = input.runId || null;
  let taskId = input.taskId || null;
  let payload = input.payload || {};
  try {
    const projectExists = db.prepare("SELECT 1 FROM projects WHERE id = ? LIMIT 1").get(input.projectId);
    if (!projectExists) {
      app.log.warn({ projectId: input.projectId, runId, taskId, subtaskId: input.subtaskId || null, eventType }, "skip development event because project no longer exists");
      return;
    }
    if (runId && !db.prepare("SELECT 1 FROM development_runs WHERE id = ? LIMIT 1").get(runId)) {
      payload = appendDevelopmentEventDroppedRef(payload, "runId", runId);
      runId = null;
    }
    if (taskId && !db.prepare("SELECT 1 FROM tasks WHERE id = ? LIMIT 1").get(taskId)) {
      payload = appendDevelopmentEventDroppedRef(payload, "taskId", taskId);
      taskId = null;
    }
    db.prepare("INSERT INTO development_run_events (id, run_id, project_id, task_id, subtask_id, event_type, actor, severity, message, artifact_id, payload, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
      .run(randomUUID(), runId, input.projectId, taskId, input.subtaskId || null, eventType, input.actor, input.severity, input.message, null, JSON.stringify(payload), nowIso());
  } catch (err) {
    app.log.warn({ err, projectId: input.projectId, runId, taskId, subtaskId: input.subtaskId || null, eventType }, "failed to record development event");
  }
}

function appendDevelopmentEventDroppedRef(payload: unknown, key: "runId" | "taskId", value: string) {
  if (payload && typeof payload === "object" && !Array.isArray(payload)) {
    const row = payload as Record<string, unknown>;
    const existing = row.droppedEventRef && typeof row.droppedEventRef === "object" && !Array.isArray(row.droppedEventRef)
      ? row.droppedEventRef as Record<string, unknown>
      : {};
    return { ...row, droppedEventRef: { ...existing, [key]: value } };
  }
  return { value: payload, droppedEventRef: { [key]: value } };
}

function stageSummary(stageKey: string, status: string) {
  const action = status === "done" ? "已完成" : status === "running" ? "进行中" : status === "blocked" ? "等待门控解除" : "待接入";
  const label = DEVELOPMENT_STAGES.find(([key]) => key === stageKey)?.[1] || stageKey;
  return `${label}${action}`;
}

function buildWorkbenchAttention(input: { items: WorkbenchTaskItem[]; approvals: Array<Record<string, unknown>>; system: any; events: WorkbenchEventRow[] }) {
  const rows: Array<{ id: string; severity: string; title: string; summary: string; agentId?: string; workItemId?: string; actionLabel?: string; createdAt?: string }> = [];
  for (const item of input.items) {
    if (["failed", "blocked", "gateway_unavailable"].includes(item.status)) {
      rows.push({
        id: `blocked:${item.id}`,
        severity: "critical",
        title: item.status === "gateway_unavailable" ? "Gateway 暂不可用" : "工作项阻塞",
        summary: `${item.agentId} · ${item.title} · ${item.nextStep || item.currentSummary || "需要处理"}`,
        agentId: item.agentId,
        workItemId: item.id,
        actionLabel: "查看并恢复",
        createdAt: item.lastActivityAt,
      });
    } else if (["awaiting_confirmation", "pending_approval"].includes(item.status)) {
      rows.push({
        id: `approval:${item.id}`,
        severity: "warn",
        title: "等待确认",
        summary: `${item.agentId} · ${item.title}`,
        agentId: item.agentId,
        workItemId: item.id,
        actionLabel: "确认 PLAN",
        createdAt: item.lastActivityAt,
      });
    } else if (item.isLive) {
      rows.push({
        id: `live:${item.id}`,
        severity: "info",
        title: "代理正在工作",
        summary: `${item.agentId} · ${item.progressLabel || item.status} · ${item.currentSummary || item.title}`,
        agentId: item.agentId,
        workItemId: item.id,
        actionLabel: "查看进度",
        createdAt: item.lastActivityAt,
      });
    } else if (isActiveWorkbenchStatusServer(item.status) && Number(item.staleSeconds || 0) > 900) {
      rows.push({
        id: `stale:${item.id}`,
        severity: "warn",
        title: "执行可能停滞",
        summary: `${item.agentId} · ${item.title} · 已 ${Math.floor(Number(item.staleSeconds || 0) / 60)} 分钟无更新`,
        agentId: item.agentId,
        workItemId: item.id,
        actionLabel: "诊断",
        createdAt: item.lastActivityAt,
      });
    }
  }
  for (const approval of input.approvals.filter((row) => row.status === "pending").slice(0, 8)) {
    rows.push({
      id: `approval-row:${approval.id}`,
      severity: "warn",
      title: "审批待处理",
      summary: `${approval.action || "action"} · ${approval.task_id || "未绑定任务"}`,
      workItemId: approval.task_id ? workbenchItemIdForDbTask(String(approval.task_id)) || undefined : undefined,
      actionLabel: "处理审批",
      createdAt: String(approval.requested_at || ""),
    });
  }
  for (const check of input.system.checks || []) {
    if (!["warn", "error", "unknown"].includes(String(check.status))) continue;
    rows.push({
      id: `check:${check.category}:${check.name}`,
      severity: check.status === "error" ? "critical" : "warn",
      title: String(check.name || "系统告警"),
      summary: String(check.summary || check.category || ""),
      actionLabel: "查看系统",
      createdAt: input.system.generatedAt,
    });
  }
  return rows
    .sort((a, b) => attentionRank(b.severity) - attentionRank(a.severity) || Date.parse(b.createdAt || "") - Date.parse(a.createdAt || ""))
    .slice(0, 12);
}

function attentionRank(severity: string) {
  if (severity === "critical") return 3;
  if (severity === "warn") return 2;
  return 1;
}

function buildWorkbenchInbox() {
  const inbox = filterSyntheticRows(db.prepare("SELECT * FROM inbox_items ORDER BY updated_at DESC LIMIT 40").all() as Array<Record<string, unknown>>);
  const notifications = filterSyntheticRows(db.prepare("SELECT * FROM notifications ORDER BY created_at DESC LIMIT 40").all() as Array<Record<string, unknown>>);
  return {
    unread: inbox.filter((row) => row.status === "unread").length + notifications.filter((row) => row.status === "unread").length,
    items: inbox.slice(0, 12),
    notifications: notifications.slice(0, 12),
  };
}

function buildLowRiskAutonomyResult(action: string, item: WorkbenchTaskItem | null, message: string) {
  const subject = item?.title || item?.id || "当前工作台";
  const evidence = buildAutonomyActionEvidence(item);
  if (action === "recover_prompt") {
    const prompt = [
      "请恢复并继续这个 OpenClaw Workbench 工作项。",
      "要求：先确认真实状态，不要把 Gateway 超时、SSE 断开或陈旧事件误判为完成。",
      `工作项：${item?.id || "-"}`,
      `代理：${item?.agentId || "-"}`,
      `状态：${item?.status || "-"}${item?.phase ? ` / ${item.phase}` : ""}`,
      `任务目录：${item?.taskPath || "-"}`,
      `PLAN：${item?.planPath || "-"}`,
      `RESULT：${item?.resultPath || "-"}`,
      `最近摘要：${item?.currentSummary || item?.description || "-"}`,
      `下一步：${item?.nextStep || "先恢复自动化链路，再继续任务"}`,
      `用户补充：${message || "-"}`,
    ].join("\n");
    return {
      message: `已生成 ${subject} 的恢复提示词`,
      prompt,
      playbook: {
        title: "恢复提示词已生成",
        riskLevel: "low",
        targetSurface: "系统运维 / Gateway 恢复",
        primaryAction: "打开系统设置",
        steps: [
          "核对 Gateway、SSE、模型和任务目录是否仍可访问。",
          "把恢复提示词交给开发台或系统运维入口，带上 PLAN/RESULT 和最近事件。",
          "恢复后回到 Mission Console，验证日志、产出物和最后活动时间是否继续更新。",
        ],
        evidence,
        prompt,
      },
    };
  }
  if (action === "diagnose") {
    const diagnosis = item ? `${item.agentId} 当前处于 ${item.status}/${item.phase}，下一步：${item.nextStep || "继续观察"}` : "未选择工作项，已刷新工作台状态。";
    return {
      message: `已完成 ${subject} 的低风险状态诊断`,
      diagnosis,
      playbook: {
        title: "低风险诊断已完成",
        riskLevel: "low",
        targetSurface: "日志与系统设置",
        primaryAction: item && autonomyItemNeedsRecovery(item) ? "打开系统设置" : "查看日志",
        steps: [
          "确认当前状态是运行、待审批、需恢复还是陈旧等待。",
          "检查最近事件、任务目录、PLAN/RESULT 和可预览产物是否匹配。",
          item && autonomyItemNeedsRecovery(item) ? "优先处理 Gateway/配置恢复，再继续任务。" : "如果日志持续更新，继续观察；若停滞超过 15 分钟，生成恢复提示。",
        ],
        evidence,
      },
    };
  }
  if (action === "summarize") {
    const summary = item ? `${item.title}：${item.currentSummary || item.description || "暂无摘要"}。进度 ${item.progressPercent || 0}%，${item.nextStep || ""}` : "暂无选中工作项。";
    return {
      message: `已生成 ${subject} 的状态摘要`,
      summary,
      playbook: {
        title: "状态摘要已生成",
        riskLevel: "low",
        targetSurface: "Mission Console",
        primaryAction: "查看任务",
        steps: [
          "阅读摘要确认当前任务目标和进度。",
          "打开产出物或预览核验证据。",
          "根据状态继续观察、引导、暂停或恢复。",
        ],
        evidence,
      },
    };
  }
  return {
    message: `已记录低风险自治动作：${action}`,
    note: message || "动作仅写入审计和工作台事件，不产生外部影响。",
  };
}

function buildAutonomyActionEvidence(item: WorkbenchTaskItem | null) {
  if (!item) return ["未选择工作项：仅记录工作台级低风险动作"];
  return [
    `工作项：${item.id}`,
    `代理：${item.agentId}`,
    `状态：${item.status}${item.phase ? ` / ${item.phase}` : ""}`,
    item.taskPath ? `任务目录：${item.taskPath}` : "",
    item.planPath ? `PLAN：${item.planPath}` : "",
    item.resultPath ? `RESULT：${item.resultPath}` : "",
    item.lastActivityAt ? `最后活动：${item.lastActivityAt}` : "",
  ].filter(Boolean);
}

function autonomyItemNeedsRecovery(item: WorkbenchTaskItem | null) {
  if (!item) return false;
  return /gateway_unavailable|blocked|failed|stale|recover|error|timeout|不可用|阻塞|失败|恢复|超时/i.test([
    item.status,
    item.phase,
    item.nextStep,
    item.currentSummary,
    item.lastEvent?.message,
  ].filter(Boolean).join(" "));
}

const AGENT_WORKBENCH_PROFILES: Record<string, { name: string; role: string; subtitle: string; capabilities: string[]; skillHighlights: string[] }> = {
  main: {
    name: "OpenClaw Main",
    role: "系统管理员",
    subtitle: "系统运维、安全审计、任务调度和最终验收",
    capabilities: ["系统运维", "安全审计", "任务调度", "最终验收", "Codex 调用"],
    skillHighlights: ["coding-agent", "task-dispatcher", "knowledge-archiver", "vector-memory"],
  },
  boss: {
    name: "AOG Boss",
    role: "战略决策者",
    subtitle: "战略规划、项目拆解、价值审计和投资人沟通",
    capabilities: ["战略规划", "项目拆解", "价值审计", "决策建议"],
    skillHighlights: ["task-dispatcher", "project-management-expert", "liangzhi-reflection", "ima-skill"],
  },
  worker: {
    name: "AOG Worker",
    role: "执行代理 / 系统运维 Owner",
    subtitle: "任务执行闭环、主动运维、被动接单、知识治理和低风险恢复",
    capabilities: ["执行闭环", "系统运维", "主动巡检", "低风险恢复", "知识治理"],
    skillHighlights: ["task-executor", "openclaw-system-ops", "nas-knowledge", "ima-skill", "knowledge-archiver"],
  },
};

function buildAgentWorkbenchAgents(input: {
  items: WorkbenchTaskItem[];
  summary: Awaited<ReturnType<typeof gatewaySummary>>;
  dbTasks: Array<Record<string, unknown>>;
  skills: Array<Record<string, unknown>>;
  tools: Array<Record<string, unknown>>;
  gatewayCron: Array<Record<string, unknown>>;
  localCron: Array<Record<string, unknown>>;
}) {
  const runtimeCards = agentRuntimeCards(input.summary, input.dbTasks);
  const taskAgents = buildWorkbenchTaskAgents(input.items);
  return ["main", "boss", "worker"].map((agentId) => {
    const profile = AGENT_WORKBENCH_PROFILES[agentId];
    const taskAgent = taskAgents.find((row) => row.id === agentId) || {};
    const runtime = (runtimeCards.find((row: Record<string, unknown>) => String(row.id) === agentId) || {}) as Record<string, unknown>;
    const ownItems = input.items.filter((item) => item.agentId === agentId);
    const current = (taskAgent as { currentWork?: WorkbenchTaskItem }).currentWork || ownItems[0] || null;
    const cronCount = input.gatewayCron.filter((row) => cronBelongsToAgent(row, agentId)).length + input.localCron.filter((row) => cronBelongsToAgent(row, agentId)).length;
    const unreadInbox = db.prepare("SELECT COUNT(*) count FROM inbox_items WHERE agent_id = ? AND status = 'unread'").get(agentId) as { count?: number } | undefined;
    return {
      ...runtime,
      ...taskAgent,
      id: agentId,
      name: profile.name,
      role: profile.role,
      subtitle: profile.subtitle,
      capabilities: profile.capabilities,
      skillHighlights: profile.skillHighlights,
      configuredSkills: input.skills
        .filter((skill) => profile.skillHighlights.some((name) => String(skill.name || skill.id || "").toLowerCase().includes(name.toLowerCase())))
        .slice(0, 8),
      skillCount: input.skills.length,
      toolCount: input.tools.length,
      cronCount,
      unreadInbox: Number(unreadInbox?.count || 0),
      configFiles: agentConfigFiles(agentId).map((file) => ({ key: file.key, exists: file.exists, path: file.path })),
      currentWork: current,
      currentTask: current,
      visualStatus: agentVisualStatus(String((taskAgent as { liveStatus?: string }).liveStatus || runtime.status || "idle")),
      gateway: input.summary.health?.status || runtime.gateway || "unknown",
    };
  });
}

function cronBelongsToAgent(row: Record<string, unknown>, agentId: string) {
  const owner = String(row.owner || row.agentId || row.agent_id || "").toLowerCase();
  return !owner || owner === agentId.toLowerCase();
}

function buildAgentWorkbenchChecks(
  summary: Awaited<ReturnType<typeof gatewaySummary>>,
  sources: ReturnType<typeof sourceStatus>,
  items: WorkbenchTaskItem[],
  approvals: Array<Record<string, unknown>>,
) {
  const checks: Array<{ category: string; name: string; status: string; summary: string }> = [];
  checks.push({
    category: "gateway",
    name: "OpenClaw Gateway",
    status: summary.health?.ok ? "ok" : "warn",
    summary: summary.health?.status || "unknown",
  });
  for (const [name, value] of Object.entries(sources)) {
    checks.push({
      category: "source",
      name,
      status: (value as { status?: string }).status === "connected" ? "ok" : "warn",
      summary: (value as { status?: string }).status || "unknown",
    });
  }
  const blocked = items.filter((item) => ["failed", "blocked", "gateway_unavailable"].includes(item.status)).length;
  if (blocked) checks.push({ category: "tasks", name: "阻塞工作项", status: "warn", summary: `${blocked} 个工作项需要处理` });
  const pending = approvals.filter((approval) => approval.status === "pending").length;
  if (pending) checks.push({ category: "approvals", name: "待审批", status: "warn", summary: `${pending} 项待审批` });
  return checks;
}

function agentVisualStatus(value: string) {
  const normalized = value.toLowerCase();
  if (["working", "busy", "running"].includes(normalized)) return "working";
  if (["waiting", "pending_approval", "awaiting_confirmation", "paused"].includes(normalized)) return "waiting";
  if (["stale", "error", "failed", "offline", "gateway_unavailable"].includes(normalized)) return "stale";
  return "idle";
}

function buildWorkbenchTaskAgents(items: WorkbenchTaskItem[]) {
  return ["main", "boss", "worker"].map((agentId) => {
    const own = items.filter((item) => item.agentId === agentId);
    const active = own.filter((item) => isActiveWorkbenchStatusServer(item.status));
    const executing = active.filter((item) => item.isLive || isExecutingWorkbenchItem(item));
    const waiting = active.filter((item) => isWaitingWorkbenchItem(item));
    const blocked = active.filter((item) => ["gateway_unavailable", "blocked", "failed"].includes(item.status));
    const current = executing[0] || waiting[0] || blocked[0] || own[0] || null;
    const liveStatus = !current
      ? "idle"
      : current.isLive
        ? "working"
        : blocked.length
          ? "stale"
          : waiting.length
            ? "waiting"
            : active.length
              ? "stale"
              : "idle";
    return {
      id: agentId,
      status: active.length ? "busy" : own.length ? "recent" : "idle",
      liveStatus,
      activeCount: active.length,
      recentCount: own.length,
      currentWork: current,
      currentTask: current,
      progressPercent: current?.progressPercent || 0,
      lastEventAt: current?.lastEvent?.createdAt || current?.lastActivityAt || "",
      lastActivityAt: current?.lastActivityAt || "",
    };
  });
}

function buildAgentWorkbenchWorkflows(items: WorkbenchTaskItem[]): AgentWorkbenchWorkflow[] {
  const byId = new Map(items.map((item) => [item.id, item]));
  const byDbTaskId = new Map(items.filter((item) => item.dbTaskId).map((item) => [String(item.dbTaskId), item]));
  const groups = new Map<string, Set<string>>();
  const addToGroup = (key: string, itemId?: string) => {
    if (!key || !itemId || !byId.has(itemId)) return;
    if (!groups.has(key)) groups.set(key, new Set());
    groups.get(key)?.add(itemId);
  };

  for (const item of items) {
    if (item.sessionKey) addToGroup(`session:${item.sessionKey}`, item.id);
    if (item.taskId) addToGroup(`task:${item.taskId}`, item.id);
    if (item.taskPath) addToGroup(`path:${safeRealpath(item.taskPath) || item.taskPath}`, item.id);
  }

  const dependencies = filterSyntheticRows(db.prepare("SELECT * FROM task_dependencies").all() as Array<Record<string, unknown>>);
  for (const dep of dependencies) {
    const from = byDbTaskId.get(String(dep.depends_on_task_id || ""));
    const to = byDbTaskId.get(String(dep.task_id || ""));
    if (from && to) {
      addToGroup(`dependency:${from.id}:${to.id}`, from.id);
      addToGroup(`dependency:${from.id}:${to.id}`, to.id);
    }
  }

  const uniqueGroups = new Map<string, WorkbenchTaskItem[]>();
  for (const ids of groups.values()) {
    const rows = [...ids].map((id) => byId.get(id)).filter(Boolean) as WorkbenchTaskItem[];
    const agentIds = new Set(rows.map((row) => row.agentId));
    if (rows.length < 2 && agentIds.size < 2) continue;
    const key = rows.map((row) => row.id).sort().join("|");
    if (!uniqueGroups.has(key)) uniqueGroups.set(key, rows);
  }

  return [...uniqueGroups.values()]
    .map((rows, index) => buildAgentWorkbenchWorkflow(rows, dependencies, index))
    .sort((a, b) => Date.parse(b.lastActivityAt || "") - Date.parse(a.lastActivityAt || ""))
    .slice(0, 8);
}

function buildAgentWorkbenchWorkflow(rows: WorkbenchTaskItem[], dependencies: Array<Record<string, unknown>>, index: number): AgentWorkbenchWorkflow {
  const agentOrder = new Map([["main", 0], ["boss", 1], ["worker", 2]]);
  const sorted = [...rows].sort((a, b) => {
    const agentRank = (agentOrder.get(a.agentId) ?? 9) - (agentOrder.get(b.agentId) ?? 9);
    return agentRank || Date.parse(a.lastActivityAt || "") - Date.parse(b.lastActivityAt || "");
  });
  const nodes = sorted.map((item) => ({
    id: `node:${item.id}`,
    agentId: item.agentId,
    itemId: item.id,
    label: item.title || item.taskId || item.id,
    status: item.status,
    progressPercent: Number(item.progressPercent || 0),
  }));
  const nodeByDbTaskId = new Map(sorted.filter((item) => item.dbTaskId).map((item) => [String(item.dbTaskId), `node:${item.id}`]));
  const dependencyEdges = dependencies.flatMap((dep) => {
    const from = nodeByDbTaskId.get(String(dep.depends_on_task_id || ""));
    const to = nodeByDbTaskId.get(String(dep.task_id || ""));
    return from && to ? [{ from, to, label: "依赖", active: isActiveWorkflowNode(nodes.find((node) => node.id === to)?.status || "") }] : [];
  });
  const sequentialEdges = nodes.slice(1).map((node, nodeIndex) => ({
    from: nodes[nodeIndex].id,
    to: node.id,
    label: workflowEdgeLabel(nodes[nodeIndex].agentId, node.agentId),
    active: isActiveWorkflowNode(node.status),
  }));
  const edges = dependencyEdges.length ? dependencyEdges : sequentialEdges;
  const lastActivityAt = sorted.map((item) => item.lastActivityAt).sort((a, b) => Date.parse(b || "") - Date.parse(a || ""))[0] || nowIso();
  const blocked = sorted.some((item) => ["failed", "blocked", "gateway_unavailable"].includes(item.status));
  const active = sorted.some((item) => isActiveWorkbenchStatusServer(item.status));
  const completed = sorted.every((item) => ["completed", "completed_partial"].includes(item.status));
  const current = sorted.find((item) => isActiveWorkbenchStatusServer(item.status)) || sorted[0];
  return {
    id: `workflow:${index}:${sorted.map((item) => item.id).join(":")}`,
    title: workflowTitle(sorted),
    status: blocked ? "blocked" : completed ? "completed" : active ? "working" : "recent",
    progressPercent: Math.round(sorted.reduce((sum, item) => sum + Number(item.progressPercent || 0), 0) / Math.max(1, sorted.length)),
    agentIds: Array.from(new Set(sorted.map((item) => item.agentId))),
    nodes,
    edges,
    lastActivityAt,
    currentNodeId: current ? `node:${current.id}` : undefined,
  };
}

function workflowTitle(rows: WorkbenchTaskItem[]) {
  const taskId = rows.find((item) => item.taskId)?.taskId;
  const firstTitle = rows.find((item) => item.title)?.title;
  const agents = Array.from(new Set(rows.map((item) => item.agentId))).join(" + ");
  return `${firstTitle || taskId || "多代理工作流"} · ${agents}`;
}

function workflowEdgeLabel(fromAgent: string, toAgent: string) {
  if (fromAgent === "main" && toAgent === "boss") return "拆解";
  if (fromAgent === "boss" && toAgent === "worker") return "派发";
  if (fromAgent === "worker" && toAgent === "main") return "回传";
  if (fromAgent === toAgent) return "续作";
  return "协作";
}

function isActiveWorkflowNode(status: string) {
  return isActiveWorkbenchStatusServer(status) && !["awaiting_confirmation", "pending_approval"].includes(status);
}

function workbenchTaskStats(items: WorkbenchTaskItem[], approvals: Array<Record<string, unknown>>) {
  const today = new Date().toISOString().slice(0, 10);
  return {
    today: items.filter((item) => item.lastActivityAt.startsWith(today)).length,
    active: items.filter((item) => isActiveWorkbenchStatusServer(item.status)).length,
    approvals: approvals.filter((approval) => approval.status === "pending").length + items.filter((item) => item.status === "awaiting_confirmation").length,
    blocked: items.filter((item) => ["failed", "blocked", "gateway_unavailable"].includes(item.status)).length,
    completed: items.filter((item) => ["completed", "completed_partial"].includes(item.status)).length,
  };
}

function workbenchTaskTimeline(item: WorkbenchTaskItem) {
  return dedupeTimeline([
    ...workbenchEventsForItem(item.id, 40).map((event) => ({
      type: event.eventType,
      actor: event.agentId || event.sourceType,
      message: event.message,
      createdAt: event.createdAt,
    })),
    ...fileTaskTimeline(item.planPath || "", item.resultPath || ""),
    ...item.timelinePreview,
  ]);
}

async function dispatchWorkbenchTask(id: string, taskMeta: Required<TaskExecutorMeta>, agentId: string, sessionKey: string, title: string, description: string, priority: string, risk: string) {
  try {
    taskEvent(id, "dispatching", "system", `正在发送给 ${agentId}，任务已在工作台可见`, { sessionKey, taskPath: taskMeta.taskPath });
    const result = await gatewayCall<{ runId?: string }>("agent", {
      agentId,
      sessionKey,
      message: buildTaskPageDispatchPrompt(taskMeta, agentId, title, description, priority, risk),
      idempotencyKey: id,
    });
    db.prepare("UPDATE tasks SET status = ?, run_id = ?, started_at = COALESCE(started_at, ?), updated_at = ? WHERE id = ?")
      .run(result.ok ? "running" : "gateway_unavailable", result.ok ? result.data?.runId || nowIso() : null, nowIso(), nowIso(), id);
    taskEvent(id, result.ok ? "dispatched" : "gateway_unavailable", "system", result.ok ? "Task sent to OpenClaw Gateway" : "Gateway unavailable during dispatch", result);
    if (!result.ok) notify("warn", "Gateway unavailable", `任务 ${title} 未能发送到代理`, "tasks");
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    db.prepare("UPDATE tasks SET status = ?, updated_at = ? WHERE id = ?").run("gateway_unavailable", nowIso(), id);
    taskEvent(id, "gateway_unavailable", "system", `Gateway dispatch failed: ${message}`, { error: message });
    notify("warn", "Gateway unavailable", `任务 ${title} 未能发送到代理：${message}`, "tasks");
  }
}

function buildTaskPageDispatchPrompt(task: Required<TaskExecutorMeta>, agentId: string, title: string, description: string, priority: string, risk: string) {
  return [
    "请使用 task-executor skill 处理这个 Workbench 任务。",
    "Workbench 已经创建任务目录，禁止创建第二个 TASK 目录。",
    `任务目录：${task.taskPath}`,
    `计划文件：${task.planPath}`,
    `结果文件：${task.resultPath}`,
    `执行代理：${agentId}`,
    `优先级：${priority}`,
    `风险等级：${risk}`,
    "",
    "流程要求：",
    "1. 先判断是否需要向用户提问；如信息足够，写入唯一 PLAN.md。",
    "2. 写入 PLAN.md 后立即执行 ls -la 自检，并等待用户确认，禁止直接执行高风险或未确认任务。",
    "3. 用户确认执行后，再完成任务并写入 RESULT.md。",
    "",
    "任务标题：",
    title,
    "",
    "任务描述：",
    description || title,
  ].join("\n");
}

function workbenchTaskKey(agentId: string, taskId: string) {
  return `task:${agentId}:${taskId}`;
}

function taskArtifacts(planPath: string, resultPath: string) {
  const taskPath = planPath ? path.dirname(planPath) : resultPath ? path.dirname(resultPath) : "";
  return dedupeArtifacts([
    planPath ? { label: "PLAN.md", path: planPath, type: "plan", exists: fs.existsSync(planPath) } : null,
    resultPath ? { label: "RESULT.md", path: resultPath, type: "result", exists: fs.existsSync(resultPath) } : null,
    ...taskDirectoryArtifacts(taskPath, planPath, resultPath),
  ].filter(Boolean) as WorkbenchTaskItem["artifacts"]);
}

function taskDirectoryArtifacts(taskPath: string, planPath = "", resultPath = "") {
  if (!taskPath || !fs.existsSync(taskPath)) return [] as WorkbenchTaskItem["artifacts"];
  const protectedPaths = new Set([planPath, resultPath].filter(Boolean).map((file) => path.resolve(file)));
  const artifactDirs = ["", "artifacts", "evidence", "outputs", "output", "reviews"];
  const rows: WorkbenchTaskItem["artifacts"] = [];
  const supported = /\.(md|markdown|html?|txt|json|log|csv|png|jpe?g|webp|pdf|docx?|xlsx?|pptx?|tsx?|jsx?|mjs|cjs|css)$/i;
  for (const relativeDir of artifactDirs) {
    const dir = relativeDir ? path.join(taskPath, relativeDir) : taskPath;
    if (!fs.existsSync(dir)) continue;
    try {
      for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
        if (!entry.isFile() || entry.name.startsWith(".")) continue;
        const full = path.join(dir, entry.name);
        if (protectedPaths.has(path.resolve(full)) || !supported.test(entry.name)) continue;
        rows.push({
          label: relativeDir ? `${relativeDir}/${entry.name}` : entry.name,
          path: full,
          type: taskArtifactType(entry.name),
          exists: true,
        });
      }
    } catch {
      // Artifact discovery is best-effort and must not break the workbench.
    }
    if (rows.length >= 32) break;
  }
  return rows.slice(0, 32);
}

function taskArtifactType(name: string) {
  const ext = path.extname(name).toLowerCase();
  if (ext === ".md" || ext === ".markdown") return "markdown";
  if (ext === ".html" || ext === ".htm") return "html";
  if ([".png", ".jpg", ".jpeg", ".webp"].includes(ext)) return "image";
  if ([".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs", ".css", ".json"].includes(ext)) return "code";
  if ([".doc", ".docx", ".xls", ".xlsx", ".ppt", ".pptx", ".pdf"].includes(ext)) return "document";
  return "file";
}

function aggregateWorkbenchArtifacts(items: WorkbenchTaskItem[]) {
  const rows = items.flatMap((item) => (item.artifacts || []).map((artifact) => ({
    ...artifact,
    workItemId: item.id,
    agentId: item.agentId,
    taskTitle: item.title,
    updatedAt: item.lastActivityAt,
  })));
  const seen = new Set<string>();
  return rows.filter((row) => {
    const key = `${row.path}:${row.workItemId}`;
    if (!row.path || seen.has(key)) return false;
    seen.add(key);
    return true;
  }).slice(0, 160);
}

function dedupeArtifacts(rows: WorkbenchTaskItem["artifacts"]) {
  const seen = new Set<string>();
  return rows.filter((row) => {
    const key = `${row.label}:${row.path}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function dedupeTimeline(rows: WorkbenchTaskItem["timelinePreview"]) {
  const seen = new Set<string>();
  return rows.filter((row) => {
    const key = `${row.type}:${row.actor}:${row.message}:${row.createdAt || ""}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return Boolean(row.message);
  });
}

function newestStat(files: string[]) {
  return files
    .filter((file) => file && fs.existsSync(file))
    .map((file) => fs.statSync(file))
    .sort((a, b) => b.mtimeMs - a.mtimeMs)[0];
}

function inferFileTaskStatus(planExists: boolean, resultExists: boolean, resultContent: string) {
  if (resultExists) {
    const partial = /暂缓|部分|未处理|未完成|⚠|⏭/i.test(resultContent);
    return { status: partial ? "completed_partial" : "completed", phase: partial ? "completed_partial" : "completed" };
  }
  if (planExists) return { status: "awaiting_confirmation", phase: "planned" };
  return { status: "created", phase: "created" };
}

function extractTaskTitle(content: string, fallback: string) {
  const goal = sectionFirstLine(content, /##\s*任务目标\s*\n([\s\S]*?)(?:\n##|\n#|$)/i);
  if (goal) return goal;
  const heading = String(content || "").split(/\r?\n/).map((line) => line.match(/^#\s+(.+)$/)?.[1]?.trim()).find((line) => line && !/^(任务计划|任务结果)$/i.test(line));
  return stripMarkdownLine(heading || fallback).slice(0, 120);
}

function extractTaskDescription(content: string) {
  return sectionFirstLine(content, /##\s*(?:执行记录|预期结果|最终结果|任务目标)\s*\n([\s\S]*?)(?:\n##|\n#|$)/i) || "";
}

function sectionFirstLine(content: string, pattern: RegExp) {
  const section = String(content || "").match(pattern)?.[1] || "";
  const line = section.split(/\r?\n/).map(stripMarkdownLine).find(Boolean) || "";
  return line.slice(0, 180);
}

function stripMarkdownLine(line: string | undefined) {
  return String(line || "")
    .replace(/^[-*+]\s+/, "")
    .replace(/^#+\s+/, "")
    .replace(/\*\*/g, "")
    .replace(/`/g, "")
    .trim();
}

function priorityFromContent(content: string) {
  return String(content || "").match(/\bP[0-3]\b/i)?.[0]?.toUpperCase() || "";
}

function riskFromContent(content: string) {
  if (/高风险|high/i.test(content)) return "high";
  if (/中风险|medium/i.test(content)) return "medium";
  return "";
}

function fileTaskTimeline(planPath: string, resultPath: string) {
  return [
    planPath && fs.existsSync(planPath) ? {
      type: "plan",
      actor: "task-executor",
      message: "PLAN.md 已生成",
      createdAt: new Date(fs.statSync(planPath).mtimeMs).toISOString(),
    } : null,
    resultPath && fs.existsSync(resultPath) ? {
      type: "result",
      actor: "task-executor",
      message: "RESULT.md 已生成",
      createdAt: new Date(fs.statSync(resultPath).mtimeMs).toISOString(),
    } : null,
  ].filter(Boolean) as WorkbenchTaskItem["timelinePreview"];
}

function gatewaySessionIndex(agentId: string) {
  const safeAgent = agentId.replace(/[^a-zA-Z0-9_-]/g, "");
  const indexPath = path.join(os.homedir(), ".openclaw", "agents", safeAgent, "sessions", "sessions.json");
  if (!fs.existsSync(indexPath)) return [] as Array<{ sessionKey: string; sessionId: string; mtimeMs: number }>;
  try {
    const index = JSON.parse(fs.readFileSync(indexPath, "utf8")) as Record<string, { sessionId?: string }>;
    return Object.entries(index).map(([sessionKey, value]) => {
      const sessionId = String(value?.sessionId || "");
      const file = path.join(os.homedir(), ".openclaw", "agents", safeAgent, "sessions", `${sessionId}.jsonl`);
      return { sessionKey, sessionId, mtimeMs: fs.existsSync(file) ? fs.statSync(file).mtimeMs : 0 };
    }).filter((row) => row.sessionId).sort((a, b) => b.mtimeMs - a.mtimeMs);
  } catch {
    return [];
  }
}

function readGatewaySessionInfo(agentId: string, sessionId: string, mtimeMs: number) {
  const safeAgent = agentId.replace(/[^a-zA-Z0-9_-]/g, "");
  const sessionPath = path.join(os.homedir(), ".openclaw", "agents", safeAgent, "sessions", `${sessionId}.jsonl`);
  const timeline: WorkbenchTaskItem["timelinePreview"] = [];
  let lastUser = "";
  let lastAssistant = "";
  let phase = "recent";
  let status = Date.now() - mtimeMs < 10 * 60_000 ? "running" : "recent";
  if (!fs.existsSync(sessionPath)) return { title: "", description: "", status, phase, timeline };
  try {
    const lines = fs.readFileSync(sessionPath, "utf8").split(/\r?\n/).filter(Boolean).slice(-80);
    for (const line of lines) {
      const row = JSON.parse(line) as { type?: string; timestamp?: string; message?: { role?: string; stopReason?: string; content?: unknown[] } };
      if (row.type !== "message") continue;
      const role = row.message?.role || "";
      const parts = row.message?.content || [];
      const text = extractGatewayText({ content: parts }).replace(/\s+/g, " ").trim();
      if (role === "user" && text) {
        lastUser = text;
        timeline.push({ type: "user", actor: "user", message: text.slice(0, 220), createdAt: row.timestamp });
      }
      if (role === "assistant") {
        const hasTool = parts.some((part) => String((part as Record<string, unknown>).type || "") === "toolCall");
        const thinking = parts.map((part) => firstTextValue(part as Record<string, unknown>, ["thinking", "reasoning", "thought", "thoughts"])).find(Boolean) || "";
        if (thinking) {
          phase = "thinking";
          timeline.push({ type: "thinking", actor: agentId, message: thinking.slice(0, 220), createdAt: row.timestamp });
        }
        if (hasTool) {
          phase = "tool";
          timeline.push({ type: "tool", actor: agentId, message: "调用工具处理中", createdAt: row.timestamp });
        }
        if (text) {
          lastAssistant = text;
          timeline.push({ type: "assistant", actor: agentId, message: text.slice(0, 220), createdAt: row.timestamp });
        }
        if (row.message?.stopReason === "stop") {
          status = "completed";
          phase = "completed";
        }
      }
      if (role === "toolResult") {
        phase = "tool";
        timeline.push({ type: "tool_result", actor: "tool", message: (text || "工具返回").slice(0, 220), createdAt: row.timestamp });
      }
    }
  } catch {
    return { title: "", description: "", status, phase, timeline };
  }
  return {
    title: lastUser.slice(0, 120),
    description: lastAssistant.slice(0, 240),
    status,
    phase,
    timeline: timeline.slice(-8).reverse(),
  };
}

function gatewaySessionTitle(sessionKey: string) {
  if (sessionKey.includes(":cron:")) return `定时任务 ${sessionKey.split(":cron:")[1] || ""}`.trim();
  if (sessionKey.includes(":workbench:")) return `Workbench 会话 ${sessionKey.split(":workbench:")[1] || ""}`.trim();
  return sessionKey || "Gateway 会话";
}

function taskDag(tasks: unknown[], dependencies: unknown[]) {
  const rows = tasks as Array<Record<string, unknown>>;
  const deps = dependencies as Array<Record<string, unknown>>;
  return {
    nodes: rows.map((task) => ({
      id: String(task.id),
      label: task.title,
      status: task.status,
      agentId: task.agent_id,
      priority: task.priority,
      parentTaskId: task.parent_task_id,
    })),
    edges: deps.map((dep) => ({ from: String(dep.depends_on_task_id), to: String(dep.task_id), label: "depends" })),
  };
}

function parseGlobalSearch(raw: string) {
  const tokens = raw.trim().split(/\s+/).filter(Boolean);
  const requested = new Set<KnowledgeSource>();
  const queryParts = [];
  for (const token of tokens) {
    const lowered = token.toLowerCase();
    if (lowered === "@all") {
      for (const src of ALL_KNOWLEDGE_SOURCES) requested.add(src);
    } else if (lowered === "@njx" || lowered === "@njx-knowledge") {
      requested.add("njx-knowledge");
    } else if (lowered === "@memory" || lowered === "@wiki" || lowered === "@nas" || lowered === "@ima") {
      requested.add(lowered.slice(1) as KnowledgeSource);
    } else {
      queryParts.push(token);
    }
  }
  return { query: queryParts.join(" "), sources: requested.size ? [...requested] : [...DEFAULT_KNOWLEDGE_SOURCES] };
}

function buildOverviewAlerts(input: {
  gateway: Awaited<ReturnType<typeof gatewaySummary>>;
  sources: ReturnType<typeof sourceStatus>;
  tasks: Array<Record<string, unknown>>;
  approvals: Array<Record<string, unknown>>;
  cron: Array<Record<string, unknown>>;
  notifications: Array<Record<string, unknown>>;
  knowledge: Record<string, unknown>;
  costResource: Record<string, unknown>;
}) {
  const alerts: Array<Record<string, unknown>> = [];
  const gatewayHealth = input.gateway.health as { ok?: boolean; status?: string; error?: string };
  if (!gatewayHealth.ok) alerts.push({ id: "gateway", severity: "critical", title: "Gateway 断开", body: gatewayHealth.error || gatewayHealth.status || "OpenClaw Gateway unavailable", targetPage: "system" });
  for (const [source, value] of Object.entries(input.sources)) {
    const status = (value as { status?: string }).status || "unknown";
    if (status !== "connected") alerts.push({ id: `source-${source}`, severity: source === "memory" ? "critical" : "warn", title: `${source.toUpperCase()} 不可用`, body: `状态：${status}`, targetPage: source === "memory" ? "system" : "knowledge" });
  }
  const failedCron = input.cron.filter((row) => ["failed", "error"].includes(String(row.status)));
  if (failedCron.length) alerts.push({ id: "cron", severity: "warn", title: "Cron 重复或失败", body: `${failedCron.length} 个定时任务异常`, targetPage: "agent" });
  const stuckTasks = input.tasks.filter((task) => ["failed", "blocked", "gateway_unavailable"].includes(String(task.status)));
  if (stuckTasks.length) alerts.push({ id: "tasks-stuck", severity: "critical", title: "代理任务卡住", body: `${stuckTasks.length} 个任务失败或阻塞`, targetPage: "tasks" });
  const highRiskApprovals = input.approvals.filter((approval) => approval.status === "pending" && String(approval.details || "").toLowerCase().includes("high"));
  const pendingApprovals = input.approvals.filter((approval) => approval.status === "pending");
  if (highRiskApprovals.length || pendingApprovals.length) alerts.push({ id: "approvals", severity: highRiskApprovals.length ? "critical" : "warn", title: "有待审批操作", body: `${pendingApprovals.length} 项待审批，其中高风险 ${highRiskApprovals.length} 项`, targetPage: "tasks" });
  const knowledgeAlerts = input.notifications.filter((item) => ["error", "warn"].includes(String(item.level)) && String(item.source || "").includes("knowledge"));
  if (knowledgeAlerts.length) alerts.push({ id: "knowledge-sync", severity: "warn", title: "知识库同步失败", body: `${knowledgeAlerts.length} 条知识库告警`, targetPage: "knowledge" });
  const token = (input.costResource.token || {}) as { risk?: string; note?: string };
  if (token.risk && ["warn", "critical"].includes(token.risk)) alerts.push({ id: "token", severity: "warn", title: "Token/额度风险", body: token.note || "Token usage monitor not configured", targetPage: "system" });
  const severityRank: Record<string, number> = { critical: 0, warn: 1, info: 2 };
  return alerts.sort((a, b) => (severityRank[String(a.severity)] ?? 9) - (severityRank[String(b.severity)] ?? 9)).slice(0, 12);
}

function countBy(rows: Array<Record<string, unknown>>, key: string) {
  return rows.reduce<Record<string, number>>((acc, row) => {
    const value = String(row[key] || "unknown");
    acc[value] = (acc[value] || 0) + 1;
    return acc;
  }, {});
}

function isOpenStatus(value: unknown) {
  return !["completed", "done", "cancelled", "archived"].includes(String(value || "").toLowerCase());
}

