function parseDateKey(value: unknown) {
  if (typeof value !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
  const [year, month, day] = value.split("-").map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  if (date.getUTCFullYear() !== year || date.getUTCMonth() !== month - 1 || date.getUTCDate() !== day) return null;
  return date;
}

function defaultReportSources() {
  return ["todos", "events", "plan_items", "notes"];
}

function ensureDefaultReportSchedules() {
  const now = nowIso();
  const defaults: Array<[string, string]> = [["daily", "18:00"], ["weekly", "18:10"], ["monthly", "18:20"], ["yearly", "18:30"]];
  const insert = db.prepare("INSERT OR IGNORE INTO report_schedules (report_type, enabled, time_of_day, template_id, sources, last_generated_key, last_run_at, status, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)");
  for (const [type, time] of defaults) insert.run(type, type === "daily" ? 1 : 0, time, null, JSON.stringify(defaultReportSources()), null, null, "idle", now, now);
}

function dispatchDueReportSchedules(force = false) {
  if (reportScheduleDispatching && !force) return { generated: [], skipped: ["already_running"] };
  reportScheduleDispatching = true;
  const generated: unknown[] = [];
  const skipped: string[] = [];
  try {
    ensureDefaultReportSchedules();
    const now = new Date();
    const today = formatLocalDateInZone(now);
    const rows = db.prepare("SELECT * FROM report_schedules WHERE enabled = 1 ORDER BY report_type").all() as Array<Record<string, unknown>>;
    for (const row of rows) {
      const type = String(row.report_type || "daily");
      const key = reportScheduleKey(type, today);
      const due = force || String(row.time_of_day || "18:00") <= now.toTimeString().slice(0, 5);
      if (!due) {
        skipped.push(`${type}:not_due`);
        continue;
      }
      if (!force && row.last_generated_key === key) {
        skipped.push(`${type}:already_generated`);
        continue;
      }
      const range = reportRangeForType(type, today);
      const report = generateReport(db, {
        reportType: type,
        rangeStart: range.start,
        rangeEnd: range.end,
        templateId: String(row.template_id || "") || undefined,
        sources: parseJsonArray(row.sources).length ? parseJsonArray(row.sources) : defaultReportSources(),
        notes: "OpenClaw Workbench 定时生成。",
        replaceExisting: true,
      });
      db.prepare("UPDATE report_schedules SET last_generated_key = ?, last_run_at = ?, status = ?, updated_at = ? WHERE report_type = ?")
        .run(key, nowIso(), "generated", nowIso(), type);
      generated.push(report);
    }
  } finally {
    reportScheduleDispatching = false;
  }
  return { generated, skipped };
}

function reportScheduleKey(type: string, dateKey: string) {
  if (type === "weekly") return `${dateKey.slice(0, 4)}-W${weekNumber(localDateFromKey(dateKey))}`;
  if (type === "monthly") return dateKey.slice(0, 7);
  if (type === "yearly") return dateKey.slice(0, 4);
  return dateKey;
}

function reportRangeForType(type: string, dateKey: string) {
  const date = localDateFromKey(dateKey);
  if (type === "weekly") {
    const day = date.getDay() || 7;
    const start = new Date(date);
    start.setDate(date.getDate() - day + 1);
    const end = new Date(start);
    end.setDate(start.getDate() + 6);
    return { start: formatLocalDateInZone(start), end: formatLocalDateInZone(end) };
  }
  if (type === "monthly") {
    const start = new Date(date.getFullYear(), date.getMonth(), 1);
    const end = new Date(date.getFullYear(), date.getMonth() + 1, 0);
    return { start: formatLocalDateInZone(start), end: formatLocalDateInZone(end) };
  }
  if (type === "yearly") return { start: `${date.getFullYear()}-01-01`, end: `${date.getFullYear()}-12-31` };
  return { start: dateKey, end: dateKey };
}

function localDateFromKey(dateKey: string) {
  const [year, month, day] = dateKey.split("-").map(Number);
  return new Date(year, month - 1, day);
}

function formatLocalDateInZone(date: Date) {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, "0");
  const d = String(date.getDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

function weekNumber(date: Date) {
  const target = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
  const day = target.getUTCDay() || 7;
  target.setUTCDate(target.getUTCDate() + 4 - day);
  const yearStart = new Date(Date.UTC(target.getUTCFullYear(), 0, 1));
  return String(Math.ceil((((target.getTime() - yearStart.getTime()) / MS_PER_DAY) + 1) / 7)).padStart(2, "0");
}

function dateKeyFromUtc(date: Date) {
  return date.toISOString().slice(0, 10);
}

function addUtcDays(date: Date, days: number) {
  const next = new Date(date.getTime());
  next.setUTCDate(next.getUTCDate() + days);
  return next;
}

function daysBetweenInclusive(start: Date, end: Date) {
  return Math.round((end.getTime() - start.getTime()) / MS_PER_DAY) + 1;
}

async function chinaCalendarRange(startKey: string, endKey: string) {
  const start = parseDateKey(startKey);
  const end = parseDateKey(endKey);
  if (!start || !end) return [];
  const cache = readChinaHolidayCache();
  const years = new Set<number>();
  for (let current = start; current.getTime() <= end.getTime(); current = addUtcDays(current, 1)) years.add(current.getUTCFullYear());
  for (const year of years) {
    if (!cache.years[String(year)]) {
      cache.years[String(year)] = await buildChinaCalendarYear(year);
      cache.updatedAt = nowIso();
    }
  }
  writeChinaHolidayCache(cache);
  const out: ChinaCalendarDay[] = [];
  for (let current = start; current.getTime() <= end.getTime(); current = addUtcDays(current, 1)) {
    const key = dateKeyFromUtc(current);
    const row = cache.years[String(current.getUTCFullYear())]?.[key] || fallbackChinaCalendarDay(key);
    out.push(row.source === "cache" ? row : { ...row, source: row.source });
  }
  return out;
}

function readChinaHolidayCache(): ChinaHolidayCache {
  try {
    if (!fs.existsSync(CHINA_HOLIDAY_CACHE)) return { version: 1, updatedAt: nowIso(), years: {} };
    const parsed = JSON.parse(fs.readFileSync(CHINA_HOLIDAY_CACHE, "utf8")) as ChinaHolidayCache;
    return { version: 1, updatedAt: parsed.updatedAt || nowIso(), years: parsed.years || {} };
  } catch {
    return { version: 1, updatedAt: nowIso(), years: {} };
  }
}

function writeChinaHolidayCache(cache: ChinaHolidayCache) {
  try {
    fs.mkdirSync(path.dirname(CHINA_HOLIDAY_CACHE), { recursive: true });
    fs.writeFileSync(CHINA_HOLIDAY_CACHE, JSON.stringify(cache, null, 2), "utf8");
  } catch {
    // Calendar rendering must not depend on cache write permissions.
  }
}

async function buildChinaCalendarYear(year: number) {
  const rows = fallbackChinaCalendarYear(year);
  for (const [date, name] of Object.entries(CHINA_HOLIDAY_SEEDS[year]?.holidays || {})) rows[date] = chinaCalendarDay(date, name, "holiday", "builtin");
  for (const [date, name] of Object.entries(CHINA_HOLIDAY_SEEDS[year]?.makeups || {})) rows[date] = chinaCalendarDay(date, name, "makeup", "builtin");
  const remote = await fetchChinaHolidayYear(year);
  for (const [date, row] of Object.entries(remote)) rows[date] = row;
  return rows;
}

function fallbackChinaCalendarYear(year: number) {
  const rows: Record<string, ChinaCalendarDay> = {};
  for (let current = new Date(Date.UTC(year, 0, 1)); current.getUTCFullYear() === year; current = addUtcDays(current, 1)) {
    const key = dateKeyFromUtc(current);
    rows[key] = fallbackChinaCalendarDay(key);
  }
  return rows;
}

function fallbackChinaCalendarDay(date: string): ChinaCalendarDay {
  const parsed = parseDateKey(date);
  const day = parsed?.getUTCDay() ?? 1;
  const weekend = day === 0 || day === 6;
  return chinaCalendarDay(date, weekend ? "周末" : "", weekend ? "weekend" : "workday", "fallback");
}

async function fetchChinaHolidayYear(year: number) {
  const rows: Record<string, ChinaCalendarDay> = {};
  try {
    const res = await fetch(`https://timor.tech/api/holiday/year/${year}`, { signal: AbortSignal.timeout(4500) });
    if (!res.ok) return rows;
    const data = await res.json() as { code?: number; holiday?: Record<string, { date?: string; holiday?: boolean; name?: string }> };
    if (data.code !== 0 || !data.holiday) return rows;
    for (const [monthDay, item] of Object.entries(data.holiday)) {
      const date = normalizeHolidayDate(year, item.date || monthDay);
      if (!date) continue;
      const type = item.holiday === false ? "makeup" : "holiday";
      rows[date] = chinaCalendarDay(date, item.name || (type === "holiday" ? "节假日" : "调休补班"), type, "timor");
    }
  } catch {
    return rows;
  }
  return rows;
}

function normalizeHolidayDate(year: number, value: string) {
  const date = /^\d{4}-\d{2}-\d{2}$/.test(value) ? value : `${year}-${value}`;
  return parseDateKey(date) ? date : "";
}

function chinaCalendarDay(date: string, name: string, type: ChinaCalendarDay["type"], source: ChinaCalendarDay["source"]): ChinaCalendarDay {
  const isMakeupWorkday = type === "makeup";
  const isHoliday = type === "holiday";
  return {
    date,
    name,
    type,
    isWorkday: type === "workday" || isMakeupWorkday,
    isHoliday,
    isMakeupWorkday,
    source,
  };
}

function startsWithDate(value: unknown, dateKey: string) {
  return typeof value === "string" && value.startsWith(dateKey);
}

function localDateKey() {
  const date = new Date();
  const offset = date.getTimezoneOffset() * 60_000;
  return new Date(date.getTime() - offset).toISOString().slice(0, 10);
}

function ensureDefaultModelConfigs() {
  const defaults = [
    {
      id: "minimax-m3",
      label: "MiniMax M3",
      provider: "minimax",
      model: "MiniMax-M3",
      contextWindow: 1_000_000,
      status: "active",
      metadata: { role: "default", plan: "MiniMax Token Plan", recommendedFor: ["main", "boss", "worker"] },
    },
    {
      id: "minimax-m27-legacy",
      label: "MiniMax M2.7 legacy",
      provider: "minimax",
      model: "MiniMax-M2.7",
      contextWindow: 200_000,
      status: "archived",
      metadata: { role: "fallback", plan: "MiniMax Token Plan", recommendedFor: ["manual-rollback", "legacy-sessions"] },
    },
    {
      id: "minimax-m25-fallback",
      label: "MiniMax M2.5 fallback",
      provider: "minimax",
      model: "MiniMax-M2.5",
      contextWindow: 0,
      status: "archived",
      metadata: { role: "fallback", plan: "MiniMax Token Plan", recommendedFor: ["batch", "low-risk"] },
    },
  ];
  const now = nowIso();
  db.prepare("UPDATE model_configs SET status = 'archived', is_default = 0, updated_at = ? WHERE id = 'deepseek-r1-14b-local' AND status = 'active'").run(now);
  for (const item of defaults) {
    db.prepare("INSERT OR IGNORE INTO model_configs (id, label, provider, model, context_window, status, metadata, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)")
      .run(item.id, item.label, item.provider, item.model, item.contextWindow, item.status, JSON.stringify(item.metadata), now, now);
  }
  db.prepare("UPDATE model_configs SET label = 'MiniMax M3', provider = 'minimax', model = 'MiniMax-M3', context_window = 1000000, status = 'active', is_default = 1, updated_at = ? WHERE id = 'minimax-m3'").run(now);
  db.prepare("UPDATE model_configs SET status = 'archived', is_default = 0, updated_at = ? WHERE id IN ('minimax-m27', 'minimax-m27-legacy', 'minimax-m25-fallback')").run(now);
  const activeDefault = db.prepare("SELECT id FROM model_configs WHERE status = 'active' AND is_default = 1 LIMIT 1").get() as { id: string } | undefined;
  if (!activeDefault) db.prepare("UPDATE model_configs SET is_default = 1, updated_at = ? WHERE id = 'minimax-m3' AND status = 'active'").run(now);
}

function defaultApiKeyRef(provider: string, model: string) {
  const providerPart = safeName(provider || "provider").replace(/-/g, "_").toUpperCase();
  const modelPart = safeName(model || "model").replace(/-/g, "_").toUpperCase();
  return `${providerPart}_${modelPart}_API_KEY`.slice(0, 120);
}

function sanitizeModelConfig(row: unknown) {
  const record = { ...(row as Record<string, unknown>) };
  let metadata: Record<string, unknown> = {};
  try {
    metadata = typeof record.metadata === "string" ? JSON.parse(record.metadata) : (record.metadata as Record<string, unknown>) || {};
  } catch {
    metadata = {};
  }
  delete metadata.apiKey;
  delete metadata.secret;
  delete metadata.token;
  delete metadata.credentials;
  record.metadata = metadata;
  record.api_key_configured = Boolean(record.api_key_configured);
  record.is_default = Boolean(record.is_default);
  return record;
}

function buildKnowledgeGraph(query: { entryId?: string; path?: string }) {
  const selectedPath = String(query.path || "");
  const selectedEntry = query.entryId
    ? db.prepare("SELECT * FROM knowledge_entries WHERE id = ?").get(query.entryId) as { id: string; title: string; source?: string; source_path?: string; content_path?: string } | undefined
    : selectedPath
      ? db.prepare("SELECT * FROM knowledge_entries WHERE source_path = ? OR content_path = ? LIMIT 1").get(selectedPath, selectedPath) as { id: string; title: string; source?: string; source_path?: string; content_path?: string } | undefined
      : undefined;
  const selectedWikiPage = selectedPath
    ? db.prepare("SELECT * FROM knowledge_wiki_pages WHERE path = ? LIMIT 1").get(selectedPath) as { id: string; page_type: string; title: string; path: string; review_status: string; confidence: number; source_paths: string; updated_at: string } | undefined
    : undefined;
  const currentId = selectedEntry ? `entry:${selectedEntry.id}` : selectedPath || "knowledge-root";
  const currentLabel = selectedEntry?.title || selectedWikiPage?.title || path.basename(selectedPath || "Knowledge");
  const nodes = new Map<string, Record<string, unknown>>();
  const edges = new Map<string, Record<string, unknown>>();
  const maxNodes = 650;

  function addNode(node: Record<string, unknown>) {
    const id = String(node.id || "");
    // iter-10: 加 "leaf" 进 priorityNode，让 leaf 即使 nodes.size >= maxNodes 也能注入（侧滑预览 iter-12 关键）
    const priorityNode = ["task", "report", "project", "agent", "wiki", "leaf"].includes(String(node.type || "")) || ["task", "report", "project", "agent", "wiki", "leaf"].includes(String(node.source || ""));
    if (!id || (nodes.size >= maxNodes && !nodes.has(id) && !priorityNode)) return;
    const existing = nodes.get(id);
    if (existing) {
      nodes.set(id, { ...existing, ...node, type: node.type === "current" ? "current" : existing.type });
      return;
    }
    nodes.set(id, node);
  }
  function addEdge(source: string, target: string, label: string) {
    if (!source || !target || source === target) return;
    const id = `${source}->${target}:${label}`;
    if (!edges.has(id)) edges.set(id, { id, source, target, label });
  }

  addNode({ id: currentId, label: currentLabel, type: "current", source: selectedWikiPage ? "wiki" : selectedEntry?.source || "workspace", path: selectedPath || selectedEntry?.content_path || selectedEntry?.source_path || "" });
  const tree = knowledgeTree() as Record<string, { status?: string; items?: Array<Record<string, unknown>> }>;
  for (const [source, group] of Object.entries(tree)) {
    const sourceId = `source:${source}`;
    addNode({ id: sourceId, label: source, type: "source", source });
    if (selectedPath) addEdge(currentId, sourceId, "source");
    for (const item of (group.items || []).slice(0, 80)) {
      collectTreeGraphNode(item, source, sourceId, 0, selectedPath, addNode, addEdge);
      if (nodes.size >= maxNodes) break;
    }
  }

  addNode({ id: "source:wiki", label: "wiki", type: "source", source: "wiki" });
  if (selectedWikiPage) addEdge(currentId, "source:wiki", "source");
  const wikiPages = db.prepare(`
    SELECT id, page_type, title, path, review_status, confidence, source_paths, updated_at
    FROM knowledge_wiki_pages
    ORDER BY updated_at DESC
    LIMIT 120
  `).all() as Array<{ id: string; page_type: string; title: string; path: string; review_status: string; confidence: number; source_paths: string; updated_at: string }>;
  for (const page of wikiPages) {
    const pageId = page.path || `wiki:${page.id}`;
    const isCurrent = selectedPath && page.path === selectedPath;
    addNode({
      id: pageId,
      label: page.title,
      type: isCurrent ? "current" : "wiki",
      source: "wiki",
      path: page.path,
      updatedAt: page.updated_at,
      tags: [page.page_type, page.review_status, `confidence:${Number(page.confidence || 0).toFixed(2)}`].filter(Boolean),
    });
    addEdge("source:wiki", pageId, "wiki-page");
    const sourcePaths = parseJsonArray(page.source_paths).map(String).filter(Boolean).slice(0, 10);
    for (const sourcePath of sourcePaths) {
      const inferred = inferGraphNode(path.basename(sourcePath), sourcePath);
      addNode({
        id: sourcePath,
        label: path.basename(sourcePath),
        type: selectedPath === sourcePath ? "current" : inferred.type,
        source: "memory",
        path: sourcePath,
        tags: inferred.tags,
      });
      addEdge(pageId, sourcePath, "source-evidence");
      if (selectedPath && selectedPath === sourcePath) addEdge(currentId, pageId, "compiled-to");
    }
    if (selectedPath && sourcePaths.includes(selectedPath)) addEdge(currentId, pageId, "compiled-to");
  }

  const recent = db.prepare("SELECT id, title, source, source_path, content_path FROM knowledge_entries ORDER BY updated_at DESC LIMIT 60").all() as Array<{ id: string; title: string; source: string; source_path?: string; content_path?: string }>;
  for (const entry of recent) {
    const id = `entry:${entry.id}`;
    const entryPath = entry.content_path || entry.source_path || "";
    const inferred = inferGraphNode(entry.title, entryPath);
    addNode({ id, label: entry.title, type: id === currentId ? "current" : inferred.type, source: entry.source || "memory", path: entryPath, updatedAt: nowIso(), tags: inferred.tags });
    addEdge(`source:${entry.source || "memory"}`, id, "entry");
    if (selectedPath && entryPath && path.dirname(entryPath) === path.dirname(selectedPath)) addEdge(currentId, id, "same-folder");
    for (const tag of inferred.tags) {
      const tagId = `tag:${tag}`;
      addNode({ id: tagId, label: tag, type: "tag", source: "tag" });
      addEdge(tagId, id, tag === "moc" ? "moc" : "tag");
    }
  }

  const agents = ["main", "boss", "worker"];
  addNode({ id: "source:agents", label: "agents", type: "source", source: "agent" });
  for (const agent of agents) {
    addNode({ id: `agent:${agent}`, label: agent, type: "agent", source: "agent" });
    addEdge("source:agents", `agent:${agent}`, "agent");
  }
  addNode({ id: "source:tasks", label: "tasks", type: "source", source: "task" });
  const tasks = db.prepare("SELECT id, title, agent_id, status, priority, project_id, created_at, updated_at FROM tasks ORDER BY updated_at DESC LIMIT 80").all() as Array<{ id: string; title: string; agent_id: string; status: string; priority?: string; project_id?: string; created_at: string; updated_at: string }>;
  for (const task of tasks) {
    const id = `task:${task.id}`;
    addNode({ id, label: task.title, type: "task", source: "task", path: task.id, updatedAt: task.updated_at, tags: [task.status, task.priority || "P2"].filter(Boolean) });
    addEdge("source:tasks", id, "task");
    addEdge(`agent:${task.agent_id || "worker"}`, id, "owns");
    if (task.project_id) addEdge(`project:${task.project_id}`, id, "project-task");
  }
  addNode({ id: "source:reports", label: "reports", type: "source", source: "report" });
  const reports = db.prepare("SELECT id, title, report_type, status, created_at, updated_at, project_id FROM reports ORDER BY updated_at DESC LIMIT 80").all() as Array<{ id: string; title: string; report_type: string; status: string; created_at: string; updated_at: string; project_id?: string }>;
  for (const report of reports) {
    const id = `report:${report.id}`;
    addNode({ id, label: report.title, type: "report", source: "report", path: report.id, updatedAt: report.updated_at, tags: [report.report_type, report.status].filter(Boolean) });
    addEdge("source:reports", id, "report");
    if (report.project_id) addEdge(`project:${report.project_id}`, id, "project-output");
  }
  addNode({ id: "source:projects", label: "projects", type: "source", source: "project" });
  const projects = db.prepare("SELECT id, name, status, updated_at FROM projects ORDER BY updated_at DESC LIMIT 60").all() as Array<{ id: string; name: string; status: string; updated_at: string }>;
  for (const project of projects) {
    const id = `project:${project.id}`;
    addNode({ id, label: project.name, type: "project", source: "project", path: project.id, updatedAt: project.updated_at, tags: [project.status].filter(Boolean) });
    addEdge("source:projects", id, "project");
  }

  const rootId = selectedEntry?.id;
  if (rootId) {
    const links = db.prepare("SELECT * FROM knowledge_links WHERE source_entry_id = ? AND status != 'archived' LIMIT 60").all(rootId) as Array<{ target: string; relation: string }>;
    for (const link of links) {
      const id = `link:${safeName(link.target)}`;
      addNode({ id, label: link.target, type: "linked", source: "link" });
      addEdge(currentId, id, link.relation || "link");
    }
  }

  const duplicateBuckets = new Map<string, string[]>();
  for (const node of nodes.values()) {
    const label = String(node.label || "").toLowerCase().replace(/\.(md|pdf|docx?|pptx?|xlsx?|txt|csv)$/i, "").trim();
    const type = String(node.type || "");
    if (!label || !["file", "document", "entry", "moc", "media"].includes(type)) continue;
    duplicateBuckets.set(label, [...(duplicateBuckets.get(label) || []), String(node.id)]);
  }
  for (const ids of duplicateBuckets.values()) {
    if (ids.length > 1) {
      for (let i = 1; i < Math.min(ids.length, 4); i += 1) addEdge(ids[0], ids[i], "duplicate");
    }
  }

  // iter-10: 注入预计算的 leaf 节点（iter-9 错放成 return 后的 IIFE 永不执行，改为模块加载时预扫，调用前可用）
  for (const leaf of LEAF_ENTRIES) {
    const leafId = `leaf:${leaf.rel}`;
    addNode({
      id: leafId,
      label: leaf.name,
      type: "leaf",
      source: "memory",
      path: leaf.rel,
      category: leaf.category,
    });
    const parentSource = `source:${leaf.category || "memory"}`;
    if (nodes.has(parentSource)) addEdge(parentSource, leafId, "contains");
  }

  return { nodes: [...nodes.values()], edges: [...edges.values()] };
}

function buildKnowledgeAtlasSnapshot() {
  const tree = knowledgeTree() as Record<string, { status?: string; root?: string; reason?: string; items?: Array<Record<string, unknown>> }>;
  const graph = buildKnowledgeGraph({});
  const wikiPages = (db.prepare(`
    SELECT id, page_type, title, path, review_status, confidence, source_count, source_paths, summary, updated_at
    FROM knowledge_wiki_pages
    ORDER BY updated_at DESC
    LIMIT 200
  `).all() as Array<Record<string, unknown>>).filter((row) => !isAtlasNoiseRecord(row));
  const wikiSources = (db.prepare(`
    SELECT source_path, source_type, wiki_page_id, status, last_compiled_at, metadata
    FROM knowledge_wiki_sources
    ORDER BY last_compiled_at DESC
    LIMIT 260
  `).all() as Array<Record<string, unknown>>).filter((row) => !isAtlasNoiseRecord(row) && !isAtlasNoisePath(String(row.source_path || "")));
  const wikiSourceByPath = new Map(wikiSources.map((row) => [String(row.source_path || ""), row]));
  const wikiPageById = new Map(wikiPages.map((row) => [String(row.id || ""), row]));
  const sourceRows = new Map<string, Record<string, unknown>>();
  const fileRows = db.prepare(`
    SELECT id, source, title, path, file_type, status, created_at, mtime
    FROM knowledge_file_index
    ORDER BY COALESCE(mtime, created_at) DESC
    LIMIT 220
  `).all() as Array<Record<string, unknown>>;
  for (const row of fileRows) {
    const sourcePath = String(row.path || "");
    if (isAtlasNoiseRecord(row) || isAtlasNoisePath(sourcePath)) continue;
    if (!sourcePath || sourcePath.includes("/memory/knowledge/wiki/")) continue;
    sourceRows.set(sourcePath, buildAtlasSourceState(row, "file", wikiSourceByPath, wikiPageById));
  }
  const entryRows = db.prepare(`
    SELECT id, title, source, source_path, content_path, tags, status, updated_at, created_at, metadata
    FROM knowledge_entries
    ORDER BY updated_at DESC
    LIMIT 160
  `).all() as Array<Record<string, unknown>>;
  for (const row of entryRows) {
    const entryPath = String(row.content_path || row.source_path || "");
    if (isAtlasNoiseRecord(row) || isAtlasNoisePath(entryPath)) continue;
    if (!entryPath || sourceRows.has(entryPath)) continue;
    sourceRows.set(entryPath, buildAtlasSourceState({ ...row, path: entryPath, file_type: "note" }, "note", wikiSourceByPath, wikiPageById));
  }
  const outputRows = db.prepare(`
    SELECT id, title, source_path, output_type, status, output_path, updated_at, created_at
    FROM knowledge_output_jobs
    WHERE output_path IS NOT NULL AND output_path != ''
    ORDER BY updated_at DESC
    LIMIT 80
  `).all() as Array<Record<string, unknown>>;
  for (const row of outputRows) {
    const outputPath = String(row.output_path || "");
    if (isAtlasNoiseRecord(row) || isAtlasNoisePath(outputPath)) continue;
    if (!outputPath || sourceRows.has(outputPath)) continue;
    sourceRows.set(outputPath, buildAtlasSourceState({ ...row, path: outputPath, source: "studio", file_type: row.output_type || "output" }, "generated_output", wikiSourceByPath, wikiPageById));
  }
  const reportRows = db.prepare(`
    SELECT id, title, report_type, status, updated_at, created_at, markdown_path, html_path
    FROM reports
    ORDER BY updated_at DESC
    LIMIT 60
  `).all() as Array<Record<string, unknown>>;
  for (const row of reportRows) {
    const reportPath = String(row.html_path || row.markdown_path || "");
    if (isAtlasNoiseRecord(row) || isAtlasNoisePath(reportPath)) continue;
    if (!reportPath || sourceRows.has(reportPath)) continue;
    sourceRows.set(reportPath, buildAtlasSourceState({ ...row, path: reportPath, source: "reports", file_type: row.report_type || "report" }, "generated_report", wikiSourceByPath, wikiPageById));
  }
  addAtlasTreeSourceRows(sourceRows, tree.nas?.items || [], "nas", wikiSourceByPath, wikiPageById, 140);
  addAtlasTreeSourceRows(sourceRows, tree.ima?.items || [], "ima", wikiSourceByPath, wikiPageById, 70);

  const sourceStates = [...sourceRows.values()]
    .sort((a, b) => String(b.updatedAt || "").localeCompare(String(a.updatedAt || "")))
    .slice(0, 260);
  const categories = buildAtlasCategories(sourceStates, wikiPages);
  const noteCategories = buildAtlasNoteCategories(sourceStates);
  const atlasSummary = buildAtlasSummary(sourceStates, categories, wikiPages, tree);
  const sourceEvidence = buildAtlasSourceEvidence(wikiPages, sourceRows, sourceStates, categories);
  const recentRuns = db.prepare("SELECT * FROM knowledge_wiki_runs ORDER BY started_at DESC LIMIT 8").all();
  const wikiStatus = buildKnowledgeWikiStatusSnapshot(db);
  const atlasGraph = buildAtlasGraph(graph, sourceStates, wikiPages, categories, sourceEvidence);
  return {
    ok: true,
    updatedAt: nowIso(),
    sources: Object.fromEntries(Object.entries(tree).map(([key, value]) => [key, { status: value.status || "unknown", root: value.root || "", reason: value.reason || "" }])),
    sourceStates,
    categories,
    noteCategories,
    atlasSummary,
    sourceEvidence,
    graph: atlasGraph,
    focusItems: buildAtlasFocusItems(categories, sourceEvidence, sourceStates, wikiPages, atlasGraph),
    wikiRuns: recentRuns,
    wikiStatus,
    coverageByCategory: wikiStatus.coverageByCategory,
    live: knowledgeLiveSnapshot(),
  };
}

function buildMobileKnowledgeAtlasSnapshot() {
  const vault = mobileVaultInfo();
  const sourceRows = new Map<string, Record<string, unknown>>();
  const pushSource = (row: Record<string, unknown>, fallbackSource: string, fallbackType: string) => {
    const sourcePath = mobileText(row.path || row.source_path || row.content_path || row.output_path || row.markdown_path || row.html_path || "", 260);
    const title = mobileText(row.title || row.name || (sourcePath ? path.basename(sourcePath) : "知识来源"), 120);
    const id = mobileText(row.id || sourcePath || title, 140);
    const dedupeKey = sourcePath || id || title;
    if (!dedupeKey || sourceRows.has(dedupeKey) || isAtlasNoiseRecord({ ...row, path: sourcePath, title })) return;
    sourceRows.set(dedupeKey, {
      id,
      title,
      path: sourcePath,
      source: mobileText(row.source || fallbackSource, 64),
      type: mobileText(row.sourceType || row.file_type || row.output_type || row.report_type || row.kind || fallbackType, 64),
      status: mobileText(row.status || row.review_status || "indexed", 48),
      updatedAt: mobileText(row.updated_at || row.updatedAt || row.mtime || row.created_at || "", 48),
      summary: mobileText(row.summary || row.description || row.reason || "", 180),
    });
  };
  for (const name of vault.preferredEntries || []) {
    const kind = kbClassify(path.join(vault.root || vault.vaultRoot || "", name), name);
    pushSource({
      id: `vault:${name}`,
      title: name,
      path: `/${name}`,
      source: "nas",
      kind: kind === "other" ? "directory" : kind,
      status: "ready",
      summary: name.includes("knowledge_graph") || name.includes("知识")
        ? "南极熊知识图谱/知识库入口"
        : "南极熊高频知识入口",
    }, "nas", "vault_entry");
  }
  const safeAll = (sql: string) => {
    try {
      return db.prepare(sql).all() as Array<Record<string, unknown>>;
    } catch (err) {
      app.log.warn({ err }, "mobile atlas lightweight query failed");
      return [];
    }
  };
  for (const row of safeAll(`
    SELECT id, source, title, path, file_type, status, created_at, mtime
    FROM knowledge_file_index
    ORDER BY COALESCE(mtime, created_at) DESC
    LIMIT 50
  `)) pushSource(row, "file_index", "file");
  for (const row of safeAll(`
    SELECT id, title, source, source_path, content_path, tags, status, updated_at, created_at
    FROM knowledge_entries
    ORDER BY updated_at DESC
    LIMIT 50
  `)) pushSource(row, "knowledge_entry", "note");
  for (const row of safeAll(`
    SELECT id, page_type, title, path, review_status, summary, updated_at
    FROM knowledge_wiki_pages
    ORDER BY updated_at DESC
    LIMIT 40
  `)) pushSource({ ...row, source: "wiki", file_type: row.page_type || "wiki" }, "wiki", "wiki_page");
  for (const row of safeAll(`
    SELECT id, title, report_type, status, updated_at, created_at, markdown_path, html_path
    FROM reports
    ORDER BY updated_at DESC
    LIMIT 30
  `)) pushSource({ ...row, source: "reports" }, "reports", "report");
  const sourceStates = [...sourceRows.values()].slice(0, 80);
  type MobileAtlasCategoryRow = {
    id: string;
    title: string;
    status: string;
    sourceCount: number;
    wikiCount: number;
    summary: string;
  };
  const categoryRows = new Map<string, MobileAtlasCategoryRow>();
  for (const source of sourceStates) {
    const id = mobileText(source.source || "knowledge", 64) || "knowledge";
    const prev = categoryRows.get(id) || {
      id,
      title: id === "nas" ? "南极熊" : id,
      status: "ready",
      sourceCount: 0,
      wikiCount: 0,
      summary: "",
    };
    prev.sourceCount = Number(prev.sourceCount || 0) + 1;
    if (String(source.type || "").includes("wiki")) prev.wikiCount = Number(prev.wikiCount || 0) + 1;
    categoryRows.set(id, prev);
  }
  const categories = [...categoryRows.values()].slice(0, 18).map((row) => ({
    ...row,
    summary: row.id === "nas"
      ? "南极熊 NAS 高频入口、知识图谱和长期知识库"
      : `${row.title || row.id} 最近知识来源`,
  }));
  const graphNodes: Array<Record<string, unknown>> = [
    { id: "source:nas", label: "南极熊", type: "source", source: "nas" },
    { id: "source:recent", label: "最近知识", type: "source", source: "db" },
  ];
  const graphEdges: Array<Record<string, unknown>> = [];
  for (const category of categories) {
    const categoryId = `category:${category.id}`;
    graphNodes.push({ id: categoryId, label: category.title || category.id, type: "category", source: category.id });
    graphEdges.push({ id: `edge:recent:${category.id}`, from: "source:recent", to: categoryId, relation: "contains" });
  }
  for (const source of sourceStates.slice(0, 48)) {
    const nodeId = `source:${mobileText(source.id || source.path || source.title, 96)}`;
    const categoryId = `category:${mobileText(source.source || "knowledge", 64) || "knowledge"}`;
    graphNodes.push({ id: nodeId, label: source.title || "知识来源", type: source.type || "source", source: source.source || "" });
    graphEdges.push({ id: `edge:${categoryId}:${nodeId}`, from: categoryId, to: nodeId, relation: "contains" });
  }
  const connectedSources = [
    vault.status === "connected" ? "nas" : "",
    "local-db",
  ].filter(Boolean);
  return {
    ok: true,
    updatedAt: nowIso(),
    sources: {
      nas: { status: vault.status || (vault.vaultAvailable ? "connected" : "unavailable"), root: vault.root || vault.vaultRoot, reason: vault.reason || vault.vaultFallbackReason || "" },
      local: { status: "connected", root: "workbench-db", reason: "" },
    },
    sourceStates,
    categories: categories.slice(0, 18).map((row) => mobileAtlasCategory(row)),
    noteCategories: categories.filter((row) => String(row.id || "").includes("note") || String(row.id || "").includes("entry")).slice(0, 18).map((row) => mobileAtlasCategory(row)),
    atlasSummary: {
      sourceCount: sourceStates.length,
      categoryCount: categories.length,
      graphNodeCount: graphNodes.length,
      graphEdgeCount: graphEdges.length,
      connectedSources,
      reviewCount: sourceStates.filter((row) => String(row.status || "").includes("review")).length,
      summary: "手机端使用轻量知识地图，优先展示南极熊入口、最近知识来源和可点击分类，避免全量 NAS 扫描卡住移动端。",
    },
    focusItems: sourceStates.slice(0, 12).map((row) => ({
      id: row.id,
      title: row.title,
      status: row.status,
      source: row.source,
      path: row.path,
    })),
    graph: {
      nodes: graphNodes.slice(0, 80).map((row) => ({
        id: mobileText(row.id || row.key || row.label || "", 120),
        label: mobileText(row.label || row.title || row.name || "节点", 80),
        type: mobileText(row.type || row.kind || "node", 48),
        source: mobileText(row.source || row.category || "", 48),
      })),
      edges: graphEdges.slice(0, 120).map((row) => ({
        id: row.id ? mobileText(row.id, 120) : undefined,
        from: mobileText(row.from || row.source || row.sourceId || row.source_entry_id || "", 120),
        to: mobileText(row.to || row.target || row.targetId || row.target_entry_id || "", 120),
        relation: mobileText(row.relation || row.label || row.type || "link", 64),
      })),
    },
    wikiStatus: { status: "mobile_lightweight", sourceCount: sourceStates.length },
    live: { status: "ready", mode: "mobile_lightweight" },
  };
}

function mobileAtlasCategory(row: Record<string, unknown>) {
  return {
    id: mobileText(row.id || row.key || row.title || row.label || "", 80),
    title: mobileText(row.title || row.label || row.name || row.id || "分类", 80),
    status: mobileText(row.status || row.stage || "", 48),
    sourceCount: Number(row.sourceCount || row.sources || row.count || 0),
    wikiCount: Number(row.wikiCount || row.pages || row.pageCount || 0),
    summary: mobileText(row.summary || row.description || row.verdict || "", 160),
  };
}

function buildAtlasSummary(
  sourceStates: Array<Record<string, unknown>>,
  categories: Array<Record<string, unknown>>,
  wikiPages: Array<Record<string, unknown>>,
  tree: Record<string, { status?: string; root?: string; reason?: string; items?: Array<Record<string, unknown>> }>,
) {
  const categoryMap = new Map(categories.map((row) => [String(row.id || ""), row]));
  const countFor = (id: string, field: string) => Number(categoryMap.get(id)?.[field] || 0);
  const connectedSources = Object.entries(tree)
    .filter(([, value]) => value.status === "connected")
    .map(([key]) => key);
  const reviewCount = wikiPages.filter((page) => String(page.review_status || "") === "needs_review").length
    + sourceStates.filter((source) => String(source.status || "") === "needs_review").length;
  const unsupportedCount = sourceStates.filter((source) => String(source.status || "") === "unsupported").length;
  const sourceCount = sourceStates.length;
  const wikiCount = wikiPages.length;
  const nasSourceCount = countFor("nas", "sourceCount");
  const openclawWikiCount = countFor("openclaw", "wikiCount");
  const aviationSignal = countFor("aviation", "sourceCount") + countFor("aviation", "wikiCount");
  return {
    title: "全库知识 Atlas",
    updatedAt: nowIso(),
    verdict: "当前知识库应以 Master MOC 为主入口，把 OpenClaw 本地记忆、南极熊 NAS、IMA 日程笔记、Studio 输出和系统报告编译成可追溯的分类 Wiki；文件树保留为来源证据层，而不是首页主体。",
    coreJudgements: [
      openclawWikiCount > 0
        ? `OpenClaw / AI 系统已有 ${openclawWikiCount} 个 Wiki 页面，是平台建设、三代理和 Gateway 可靠性的主脉络。`
        : "OpenClaw / AI 系统是平台建设主脉络，需要优先把三代理、Gateway、Knowledge 和 Workbench 编译成 Wiki。",
      nasSourceCount > 0
        ? `南极熊 NAS 已纳入 ${nasSourceCount} 个来源，应该按人生规划、学海无涯、知行合一、我的笔记和 09_Wiki 展开。`
        : "南极熊 NAS 是长期知识主仓；若页面未展示 NAS 分类，应先检查挂载与索引同步状态。",
      aviationSignal > 0
        ? "航空运行与航材知识已经形成 AOG、可靠性、安全会、RFID、供应链等业务图谱，应优先保障来源证据可展开。"
        : "航空运行与航材知识需要从会议、案例和供应链记录中提炼为主题、决策、行动项和证据链。",
    ],
    nextActions: [
      "先从 Master MOC 进入分类 Wiki，再展开主题与来源证据。",
      "新增笔记、导入文件、NAS 增量和自动报告统一进入 detected 到 embedded 状态机。",
      "Gateway 不可用时只显示待编译或失败可重试，不伪装为已嵌入。",
    ],
    risks: [
      reviewCount ? `${reviewCount} 个 Wiki/来源需要人工审核或冲突处理。` : "当前待审压力较低，但仍需保留来源依据。",
      unsupportedCount ? `${unsupportedCount} 个媒体或 Office 类来源只记录 manifest，待 OCR/转写/抽取。` : "当前抽取类型以文本为主。",
    ],
    sourceCounts: {
      indexed: sourceCount,
      wikiPages: wikiCount,
      connectedSources,
      reviewCount,
      unsupportedCount,
    },
  };
}

function isAtlasNoisePath(sourcePath: string) {
  const value = sourcePath.toLowerCase();
  if (!value) return false;
  return [
    "wb_e2e_",
    "prd11_test_",
    "model-html-smoke",
    "/tests/fixtures/",
    "/fixtures/knowledge_preview/",
    "/archive/.trash/",
  ].some((pattern) => value.includes(pattern));
}

function isAtlasNoiseRecord(row: Record<string, unknown>) {
  const text = [
    row.id,
    row.title,
    row.path,
    row.source_path,
    row.content_path,
    row.output_path,
    row.markdown_path,
    row.html_path,
    row.summary,
    row.metadata,
  ].map((value) => typeof value === "string" ? value : "").join(" ");
  return isAtlasNoisePath(text);
}

function buildAtlasEvidenceSource(
  sourcePath: string,
  sourceRows: Map<string, Record<string, unknown>>,
  fallbackSource?: Record<string, unknown>,
) {
  const source = sourceRows.get(sourcePath) || fallbackSource || {};
  const sourceType = String(source.sourceType || atlasSourceTypeForPath(sourcePath, source));
  const status = String(source.status || "indexed");
  const supported = atlasSourceSupportsWiki(sourcePath, sourceType);
  return {
    id: String(source.id || sourcePath),
    path: sourcePath,
    title: String(source.title || path.basename(sourcePath || "来源")),
    sourceType,
    sourceTypeLabel: String(source.sourceTypeLabel || atlasSourceTypeLabel(sourceType)),
    status,
    statusLabel: String(source.statusLabel || atlasStatusLabel(status, supported)),
    stage: String(source.stage || atlasStageForStatus(status, supported)),
    category: String(source.category || atlasCategoryForSource(sourcePath)),
    noteCategory: String(source.noteCategory || atlasNoteCategoryForSource(sourcePath)),
    updatedAt: String(source.updatedAt || ""),
    wikiPagePath: String(source.wikiPagePath || ""),
    wikiPageTitle: String(source.wikiPageTitle || ""),
  };
}

function buildAtlasWikiPageReference(page: Record<string, unknown>) {
  const pagePath = String(page.path || "");
  const reviewStatus = String(page.review_status || "indexed");
  return {
    id: String(page.id || pagePath),
    path: pagePath,
    title: String(page.title || path.basename(pagePath || "Wiki 页面")),
    sourceType: "wiki_page",
    sourceTypeLabel: "Wiki 页面",
    status: reviewStatus,
    statusLabel: reviewStatus === "needs_review" ? "待审" : "已编译",
    stage: "embedded",
    category: atlasCategoryForSource(`${page.title || ""} ${page.summary || ""} ${pagePath}`),
    noteCategory: String(page.page_type || "Wiki"),
    updatedAt: String(page.updated_at || ""),
    wikiPagePath: pagePath,
    wikiPageTitle: String(page.title || ""),
  };
}

function buildAtlasSourceEvidence(
  wikiPages: Array<Record<string, unknown>>,
  sourceRows: Map<string, Record<string, unknown>>,
  sourceStates: Array<Record<string, unknown>>,
  categories: Array<Record<string, unknown>>,
) {
  const rows: Array<Record<string, unknown>> = [];
  const used = new Set<string>();
  const statesByCategory = new Map<string, Array<Record<string, unknown>>>();
  for (const source of sourceStates) {
    const category = String(source.category || "general");
    statesByCategory.set(category, [...(statesByCategory.get(category) || []), source]);
  }

  for (const page of wikiPages.slice(0, 40)) {
    const pagePath = String(page.path || "");
    const category = atlasCategoryForSource(`${page.title || ""} ${page.summary || ""} ${pagePath}`);
    const explicitPaths = parseJsonArray(page.source_paths).filter(Boolean);
    const fallbackPaths = (statesByCategory.get(category) || [])
      .filter((source) => String(source.path || "") && String(source.path || "") !== pagePath)
      .slice(0, 4)
      .map((source) => String(source.path));
    const sourcePaths = (explicitPaths.length ? explicitPaths : fallbackPaths).slice(0, 6);
    const key = pagePath || String(page.id || "");
    if (!key || used.has(key)) continue;
    used.add(key);
    rows.push({
      id: page.id || key,
      title: page.title || path.basename(pagePath || key),
      path: pagePath,
      kind: "wiki",
      category,
      pageType: page.page_type,
      reviewStatus: page.review_status,
      summary: page.summary || `该 Wiki 页面归入「${atlasCategoryLabel(category)}」，可从这里展开来源证据和反向链接。`,
      sources: sourcePaths.map((sourcePath) => buildAtlasEvidenceSource(sourcePath, sourceRows, sourceRows.get(sourcePath))),
    });
  }

  for (const category of categories.slice(0, 10)) {
    if (rows.length >= 24) break;
    const categoryId = String(category.id || "general");
    const categorySources = (statesByCategory.get(categoryId) || []).slice(0, 6);
    const key = `category:${categoryId}`;
    if (used.has(key) || categorySources.length === 0) continue;
    used.add(key);
    rows.push({
      id: key,
      title: `${category.title || atlasCategoryLabel(categoryId)} 来源证据`,
      path: String(categorySources[0]?.wikiPagePath || categorySources[0]?.path || ""),
      kind: "category",
      category: categoryId,
      pageType: "source_cluster",
      reviewStatus: Number(category.needsReviewCount || 0) > 0 ? "needs_review" : "indexed",
      summary: `该分类聚合 ${category.sourceCount || categorySources.length} 个来源、${category.wikiCount || 0} 个 Wiki 页面，用于从分类 Wiki 反查来源。`,
      sources: categorySources.map((source) => buildAtlasEvidenceSource(String(source.path || ""), sourceRows, source)),
    });
  }

  for (const source of sourceStates.slice(0, 20)) {
    if (rows.length >= 28) break;
    const sourcePath = String(source.path || "");
    if (!sourcePath || used.has(sourcePath)) continue;
    used.add(sourcePath);
    rows.push({
      id: `source:${sourcePath}`,
      title: source.title || path.basename(sourcePath),
      path: sourcePath,
      kind: "source",
      category: source.category || atlasCategoryForSource(sourcePath),
      pageType: source.sourceType || "source",
      reviewStatus: source.status || "indexed",
      summary: `${source.sourceTypeLabel || atlasSourceTypeLabel(String(source.sourceType || ""))} · ${source.statusLabel || atlasStatusLabel(String(source.status || "indexed"), true)}`,
      sources: [buildAtlasEvidenceSource(sourcePath, sourceRows, source)],
    });
  }

  return rows.slice(0, 28);
}

function atlasTopicLabelsForCategory(category: string) {
  const topics: Record<string, string[]> = {
    openclaw: ["三代理架构", "Gateway 可靠性", "Knowledge Atlas", "任务执行闭环"],
    nas: ["人生规划", "学海无涯", "我的笔记", "NAS Wiki"],
    ima: ["IMA 同步", "云端笔记", "日程资料"],
    assistant: ["日程笔记", "组织运行", "日报周报"],
    aviation: ["AOG 保障", "可靠性会议", "航材供应链", "RFID 项目"],
    ai_product: ["AI 产品品味", "RAG 与知识治理", "Agent 工作流"],
    learning: ["MBA/MEM", "系统思考", "读书共创", "课程框架"],
    life: ["人生规划", "自我修炼", "反思资产"],
    projects: ["业务系统", "项目交付", "决策证据"],
    reports: ["日报", "周报", "自动报告"],
    media: ["原始资料", "可读预览", "抽取候选"],
    governance: ["MOC", "来源证据", "冲突待审"],
    general: ["通用知识", "待分类来源"],
  };
  return topics[category] || topics.general;
}

function buildAtlasFocusItems(
  categories: Array<Record<string, unknown>>,
  sourceEvidence: Array<Record<string, unknown>>,
  sourceStates: Array<Record<string, unknown>>,
  wikiPages: Array<Record<string, unknown>>,
  atlasGraph: { nodes: Array<Record<string, unknown>>; edges: Array<Record<string, unknown>> },
) {
  const items = new Map<string, Record<string, unknown>>();
  const statesByCategory = new Map<string, Array<Record<string, unknown>>>();
  const wikiPagesByCategory = new Map<string, Array<Record<string, unknown>>>();
  for (const source of sourceStates) {
    const category = String(source.category || "general");
    statesByCategory.set(category, [...(statesByCategory.get(category) || []), source]);
  }
  for (const page of wikiPages) {
    const category = atlasCategoryForSource(`${page.title || ""} ${page.summary || ""} ${page.path || ""}`);
    wikiPagesByCategory.set(category, [...(wikiPagesByCategory.get(category) || []), page]);
  }
  const add = (item: Record<string, unknown>) => {
    const id = String(item.id || "");
    if (!id || items.has(id)) return;
    items.set(id, item);
  };
  const relatedFor = (id: string, limit = 8) => atlasGraph.edges
    .filter((edge) => String(edge.source) === id || String(edge.target) === id)
    .slice(0, limit)
    .map((edge) => {
      const neighborId = String(edge.source) === id ? String(edge.target) : String(edge.source);
      const node = atlasGraph.nodes.find((candidate) => String(candidate.id) === neighborId) || {};
      return {
        id: neighborId,
        label: node.label || neighborId,
        type: node.type || "node",
        path: node.path || "",
        relation: edge.label || "",
      };
    });

  for (const category of categories) {
    const id = `category:${category.id}`;
    const categorySourceSamples = [
      ...(statesByCategory.get(String(category.id || "")) || []).slice(0, 4).map((source) => buildAtlasEvidenceSource(String(source.path || ""), new Map(), source)),
      ...(wikiPagesByCategory.get(String(category.id || "")) || []).slice(0, 4).map(buildAtlasWikiPageReference),
    ].slice(0, 6);
    add({
      id,
      label: category.title || atlasCategoryLabel(String(category.id || "")),
      type: "category",
      category: category.id,
      summary: `该分类包含 ${category.sourceCount || 0} 个来源、${category.wikiCount || 0} 个 Wiki 页面，${category.needsReviewCount || 0} 个待审项。`,
      status: Number(category.needsReviewCount || 0) > 0 ? "needs_review" : "embedded",
      sources: categorySourceSamples,
      related: relatedFor(id),
    });
  }

  for (const row of sourceEvidence) {
    const id = String(row.path || row.id || "");
    add({
      id,
      label: row.title || path.basename(id),
      type: row.kind || row.pageType || "wiki",
      category: row.category || atlasCategoryForSource(`${row.title || ""} ${id}`),
      path: row.path || "",
      summary: row.summary || "可从该节点查看 Wiki 页面和来源证据。",
      status: row.reviewStatus || "indexed",
      sources: row.sources || [],
      related: relatedFor(id),
    });
    for (const source of ((row.sources || []) as Array<Record<string, unknown>>).slice(0, 6)) {
      const sourceId = String(source.path || source.id || "");
      add({
        id: sourceId,
        label: source.title || path.basename(sourceId),
        type: source.sourceType || "source",
        category: source.category || atlasCategoryForSource(sourceId),
        path: source.path || "",
        summary: `${source.sourceTypeLabel || "来源"} · ${source.statusLabel || "已索引"}`,
        status: source.status || "indexed",
        related: relatedFor(sourceId),
      });
    }
  }

  for (const source of sourceStates.slice(0, 60)) {
    const id = String(source.path || source.id || "");
    add({
      id,
      label: source.title || path.basename(id),
      type: source.sourceType || "source",
      category: source.category || atlasCategoryForSource(id),
      path: source.path || "",
      summary: `${source.sourceTypeLabel || "来源"} · ${source.statusLabel || "已索引"}${source.wikiPageTitle ? ` · 已关联 ${source.wikiPageTitle}` : ""}`,
      status: source.status || "indexed",
      related: relatedFor(id),
    });
  }

  for (const page of wikiPages.slice(0, 40)) {
    const id = String(page.path || page.id || "");
    add({
      id,
      label: page.title || path.basename(id),
      type: "wiki",
      category: atlasCategoryForSource(`${page.title || ""} ${page.summary || ""} ${id}`),
      path: page.path || "",
      summary: page.summary || "Wiki 页面已进入 Atlas，可从这里回看来源。",
      status: page.review_status || "indexed",
      related: relatedFor(id),
    });
  }

  for (const node of atlasGraph.nodes) {
    const id = String(node.id || "");
    add({
      id,
      label: node.label || id,
      type: node.type || node.source || "node",
      category: node.category || atlasCategoryForSource(`${node.label || ""} ${node.path || ""} ${id}`),
      path: node.path || "",
      summary: node.summary || `${atlasNodeKindForServer(String(node.type || node.source || "node"))}节点已进入 Atlas，可继续查看上下游关系、来源证据和相关主题。`,
      status: Array.isArray(node.tags) ? (node.tags as unknown[]).map(String).find((tag) => /embedded|needs_review|indexed|unsupported/.test(tag)) || "indexed" : "indexed",
      related: relatedFor(id),
    });
  }

  return [...items.values()].slice(0, 180);
}

function atlasNodeKindForServer(type: string) {
  const labels: Record<string, string> = {
    moc: "整体 MOC",
    category: "分类 Wiki",
    topic: "主题",
    wiki: "Wiki 页面",
    source: "来源文档",
    source_cluster: "来源集合",
    note: "笔记",
    assistant_note: "智能助理笔记",
    nas_file: "NAS 文件",
    ima_sync: "IMA 同步",
    studio_output: "Studio 输出",
    generated_report: "系统报告",
    media_manifest: "媒体 Manifest",
    document_manifest: "文档 Manifest",
    image_manifest: "图片 Manifest",
  };
  return labels[type] || "知识";
}

function addAtlasTreeSourceRows(
  sourceRows: Map<string, Record<string, unknown>>,
  items: Array<Record<string, unknown>>,
  source: "nas" | "ima",
  wikiSourceByPath: Map<string, Record<string, unknown>>,
  wikiPageById: Map<string, Record<string, unknown>>,
  limit: number,
) {
  let added = 0;
  const walk = (rows: Array<Record<string, unknown>>, depth: number) => {
    for (const item of rows) {
      if (added >= limit) return;
      const itemPath = String(item.path || "");
      if (itemPath && !sourceRows.has(itemPath)) {
        const itemType = String(item.type || "file");
        sourceRows.set(itemPath, buildAtlasSourceState({
          id: `tree:${source}:${itemPath}`,
          title: String(item.name || path.basename(itemPath)),
          path: itemPath,
          source,
          file_type: itemType,
          status: "indexed",
          created_at: nowIso(),
          mtime: item.mtime || "",
        }, `${source}_tree`, wikiSourceByPath, wikiPageById));
        added += 1;
      }
      if (depth < 4 && Array.isArray(item.children)) walk(item.children as Array<Record<string, unknown>>, depth + 1);
    }
  };
  walk(items, 0);
}

function buildAtlasSourceState(
  row: Record<string, unknown>,
  originType: string,
  wikiSourceByPath: Map<string, Record<string, unknown>>,
  wikiPageById: Map<string, Record<string, unknown>>,
) {
  const sourcePath = String(row.path || row.content_path || row.source_path || "");
  const wikiSource = wikiSourceByPath.get(sourcePath);
  const wikiPage = wikiSource?.wiki_page_id ? wikiPageById.get(String(wikiSource.wiki_page_id)) : undefined;
  const sourceType = atlasSourceTypeForPath(sourcePath, row, originType);
  const supported = atlasSourceSupportsWiki(sourcePath, sourceType);
  const status = wikiSource?.status === "compiled"
    ? "embedded"
    : wikiSource?.status === "needs_review"
      ? "needs_review"
      : supported
        ? String(row.status || "indexed") === "imported" ? "indexed" : "classified"
        : "unsupported";
  return {
    id: String(row.id || sourcePath),
    title: String(row.title || path.basename(sourcePath || "来源")),
    path: sourcePath,
    source: String(row.source || sourceType),
    originType,
    sourceType,
    sourceTypeLabel: atlasSourceTypeLabel(sourceType),
    category: atlasCategoryForSource(`${row.title || ""} ${sourcePath} ${row.source || ""} ${sourceType}`),
    noteCategory: atlasNoteCategoryForSource(`${row.title || ""} ${sourcePath} ${row.file_type || ""} ${row.report_type || ""} ${row.output_type || ""}`),
    status,
    stage: atlasStageForStatus(status, supported),
    statusLabel: atlasStatusLabel(status, supported),
    updatedAt: String(row.updated_at || row.mtime || row.created_at || wikiSource?.last_compiled_at || nowIso()),
    wikiPageId: wikiPage?.id || wikiSource?.wiki_page_id || "",
    wikiPagePath: wikiPage?.path || "",
    wikiPageTitle: wikiPage?.title || "",
    reason: supported ? "" : "第一版只记录 manifest，待 OCR/抽取/转写。",
  };
}

function atlasSourceTypeForPath(sourcePath: string, row: Record<string, unknown> = {}, originType = "file") {
  const text = `${sourcePath} ${row.source || ""} ${row.file_type || ""} ${originType}`.toLowerCase();
  const ext = path.extname(sourcePath).toLowerCase();
  if (originType === "generated_report" || text.includes("reports")) return "generated_report";
  if (originType === "generated_output" || text.includes("studio")) return "studio_output";
  if (text.includes("calendar/") || text.includes("calendar")) return "assistant_note";
  if (text.includes("/nas") || text.includes("/volumes/南极熊")) return "nas_file";
  if (text.includes("ima://") || text.includes("ima")) return "ima_sync";
  if ([".pdf", ".doc", ".docx", ".ppt", ".pptx", ".xls", ".xlsx"].includes(ext)) return "document_manifest";
  if ([".mp3", ".wav", ".m4a", ".mp4", ".mov"].includes(ext)) return "media_manifest";
  if ([".png", ".jpg", ".jpeg", ".webp", ".gif"].includes(ext)) return "image_manifest";
  if (originType === "note" || text.includes("memory-notes") || text.includes("/notes/")) return "note";
  return "local_file";
}

function atlasSourceSupportsWiki(sourcePath: string, sourceType: string) {
  const ext = path.extname(sourcePath).toLowerCase();
  if (["document_manifest", "media_manifest", "image_manifest"].includes(sourceType)) return false;
  return [".md", ".markdown", ".txt", ".html", ".htm", ".json", ".csv", ".yaml", ".yml"].includes(ext);
}

function atlasSourceTypeLabel(sourceType: string) {
  const labels: Record<string, string> = {
    note: "添加笔记",
    assistant_note: "智能助理笔记",
    local_file: "本地文件",
    nas_file: "NAS 文件",
    ima_sync: "IMA 同步",
    studio_output: "Studio 输出",
    generated_report: "自动报告",
    document_manifest: "文档 Manifest",
    media_manifest: "媒体 Manifest",
    image_manifest: "图片 Manifest",
  };
  return labels[sourceType] || "来源";
}

function atlasStageForStatus(status: string, supported: boolean) {
  if (!supported) return "detected";
  if (status === "embedded") return "embedded";
  if (status === "needs_review") return "needs_review";
  if (status === "failed_retry") return "failed_retry";
  return "wiki_compiling";
}

function atlasStatusLabel(status: string, supported: boolean) {
  if (!supported) return "已索引，待抽取";
  if (status === "embedded") return "已嵌入 Wiki";
  if (status === "needs_review") return "待审";
  if (status === "failed_retry") return "失败可重试";
  return "已索引，待编译";
}

function atlasCategoryForSource(text: string) {
  const normalized = text.replace(/\/Users\/njx\/openclaw_data/gi, "").replace(/\/users\/njx\/openclaw_data/gi, "");
  const value = normalized.toLowerCase();
  if (/openclaw|gateway|workbench|三代理|codex|boss|worker|main代理|knowledge atlas/i.test(normalized)) return "openclaw";
  if (/\/volumes\/南极熊|南极熊|(^|[\/_\-\s])nas([\/_\-\s]|$)|04我的笔记|07知识库/i.test(normalized)) return "nas";
  if (/ima|ima_sync|ima同步/i.test(normalized)) return "ima";
  if (/calendar|日程|智能助理|assistant/i.test(normalized)) return "assistant";
  if (/日报|周报|月报|工作总结|summary|report|generated_report/i.test(normalized)) return "reports";
  if (/aog|航材|航空|可靠性|安委会|rfid|供应链|维修|o项|mel|鸟击|雷雨/i.test(normalized)) return "aviation";
  if (/\.(pdf|docx?|pptx?|xlsx?|png|jpe?g|webp|gif|mp3|wav|m4a|mp4|mov|zip)$/i.test(normalized) || /媒体|原始资料|转写|转换|inbox|office|manifest/i.test(normalized)) return "media";
  if (/ai产品|产品经理|agentic|智能体|rag|llm|模型|prompt|提示词/i.test(normalized)) return "ai_product";
  if (/mba|mem|课程|学习|读书|共读|认知|第五项修炼|u型|培训/i.test(normalized)) return "learning";
  if (/人生|自我|规划|思想汇报|阳明|反思|个人/i.test(normalized)) return "life";
  if (/项目|project|prd|roadmap|交付|opc/i.test(normalized) || value.includes("project")) return "projects";
  return "general";
}

function atlasCategoryLabel(category: string) {
  const labels: Record<string, string> = {
    openclaw: "OpenClaw / AI 系统",
    nas: "NAS 南极熊",
    ima: "IMA 同步",
    assistant: "智能助理",
    aviation: "航空运行",
    ai_product: "AI 产品",
    learning: "学习与课程",
    life: "人生规划",
    reports: "日报周报",
    projects: "项目实践",
    media: "媒体与原始资料",
    governance: "Wiki 治理",
    general: "通用知识",
  };
  return labels[category] || category;
}

function atlasNoteCategoryForSource(text: string) {
  if (/会议|会$|纪要|安委会|可靠性会|生产会/i.test(text)) return "会议纪要";
  if (/日报|daily/i.test(text)) return "日报";
  if (/周报|weekly/i.test(text)) return "周报";
  if (/报告|report/i.test(text)) return "自动报告";
  if (/学习|课程|共读|读书/i.test(text)) return "学习笔记";
  if (/决策|决定|decision/i.test(text)) return "决策记录";
  if (/项目|prd|roadmap|project/i.test(text)) return "项目文档";
  if (/转写|录音|transcript/i.test(text)) return "原始转写";
  return "工作记录";
}

function buildAtlasCategories(sourceStates: Array<Record<string, unknown>>, wikiPages: Array<Record<string, unknown>>) {
  const rows = new Map<string, { id: string; title: string; sourceCount: number; embeddedCount: number; needsReviewCount: number; wikiCount: number; latestAt: string; samples: unknown[] }>();
  const ensure = (id: string) => {
    if (!rows.has(id)) rows.set(id, { id, title: atlasCategoryLabel(id), sourceCount: 0, embeddedCount: 0, needsReviewCount: 0, wikiCount: 0, latestAt: "", samples: [] });
    return rows.get(id)!;
  };
  for (const source of sourceStates) {
    const row = ensure(String(source.category || "general"));
    row.sourceCount += 1;
    if (source.status === "embedded") row.embeddedCount += 1;
    if (source.status === "needs_review") row.needsReviewCount += 1;
    row.latestAt = [row.latestAt, String(source.updatedAt || "")].sort().at(-1) || row.latestAt;
    if (row.samples.length < 3) row.samples.push(source);
  }
  for (const page of wikiPages) {
    const category = atlasCategoryForSource(`${page.title || ""} ${page.summary || ""} ${page.path || ""}`);
    const row = ensure(category);
    row.wikiCount += 1;
    row.latestAt = [row.latestAt, String(page.updated_at || "")].sort().at(-1) || row.latestAt;
  }
  return [...rows.values()].sort((a, b) => (b.embeddedCount + b.wikiCount + b.sourceCount) - (a.embeddedCount + a.wikiCount + a.sourceCount)).slice(0, 12);
}

function buildAtlasNoteCategories(sourceStates: Array<Record<string, unknown>>) {
  const rows = new Map<string, { title: string; count: number; embeddedCount: number; samples: unknown[] }>();
  for (const source of sourceStates) {
    const title = String(source.noteCategory || "工作记录");
    if (!rows.has(title)) rows.set(title, { title, count: 0, embeddedCount: 0, samples: [] });
    const row = rows.get(title)!;
    row.count += 1;
    if (source.status === "embedded") row.embeddedCount += 1;
    if (row.samples.length < 2) row.samples.push(source);
  }
  return [...rows.values()].sort((a, b) => b.count - a.count).slice(0, 10);
}

function buildAtlasGraph(
  graph: { nodes: Record<string, unknown>[]; edges: Record<string, unknown>[] },
  sourceStates: Array<Record<string, unknown>>,
  wikiPages: Array<Record<string, unknown>>,
  categories: Array<Record<string, unknown>>,
  sourceEvidence: Array<Record<string, unknown>>,
) {
  const nodes = new Map<string, Record<string, unknown>>();
  const edges = new Map<string, Record<string, unknown>>();
  const addNode = (node: Record<string, unknown>) => {
    const id = String(node.id || "");
    if (!id || nodes.has(id) || nodes.size >= 90) return;
    nodes.set(id, node);
  };
  const addEdge = (edge: Record<string, unknown>) => {
    const source = String(edge.source || "");
    const target = String(edge.target || "");
    if (!source || !target || !nodes.has(source) || !nodes.has(target) || edges.size >= 150) return;
    const id = String(edge.id || `${source}->${target}:${edge.label || ""}`);
    if (!edges.has(id)) edges.set(id, { ...edge, id });
  };
  addNode({ id: "master:moc", label: "整体知识 Wiki", type: "moc", source: "atlas", summary: "全库入口，连接分类 Wiki、主题、来源和证据。" });
  const categoryIds = new Set([
    ...categories.map((category) => String(category.id || "")).filter(Boolean),
    "openclaw", "nas", "ima", "assistant", "ai_product", "aviation", "learning", "life", "projects", "reports", "media", "governance",
  ]);
  for (const category of categoryIds) {
    addNode({ id: `category:${category}`, label: atlasCategoryLabel(category), type: "category", source: "atlas", category, summary: `分类 Wiki：${atlasCategoryLabel(category)}` });
    addEdge({ source: "master:moc", target: `category:${category}`, label: "contains" });
    for (const topic of atlasTopicLabelsForCategory(category).slice(0, 3)) {
      const topicId = `topic:${category}:${topic}`;
      addNode({ id: topicId, label: topic, type: "topic", source: "atlas", category, summary: `${atlasCategoryLabel(category)} 下的主题脉络。` });
      addEdge({ source: `category:${category}`, target: topicId, label: "contains" });
    }
  }
  for (const page of wikiPages.slice(0, 28)) {
    const category = atlasCategoryForSource(`${page.title || ""} ${page.summary || ""} ${page.path || ""}`);
    const pageId = String(page.path || page.id);
    addNode({ id: pageId, label: page.title, type: "wiki", source: "wiki", category, path: page.path, summary: page.summary, tags: [page.page_type, page.review_status].filter(Boolean) });
    addEdge({ source: `category:${category}`, target: pageId, label: "contains" });
    const topic = atlasTopicLabelsForCategory(category)[0];
    if (topic) addEdge({ source: `topic:${category}:${topic}`, target: pageId, label: "explains" });
    for (const sourcePath of parseJsonArray(page.source_paths).slice(0, 4)) {
      addNode({ id: sourcePath, label: path.basename(sourcePath), type: "source", source: "evidence", category, path: sourcePath });
      addEdge({ source: pageId, target: sourcePath, label: "derived_from" });
    }
  }
  for (const row of sourceEvidence.slice(0, 18)) {
    const rowId = String(row.path || row.id || "");
    const category = String(row.category || atlasCategoryForSource(`${row.title || ""} ${rowId}`));
    if (rowId) {
      addNode({ id: rowId, label: row.title || path.basename(rowId), type: row.kind === "category" ? "source_cluster" : "wiki", source: "evidence", category, path: row.path, summary: row.summary });
      addEdge({ source: `category:${category}`, target: rowId, label: "evidence" });
    }
    for (const source of ((row.sources || []) as Array<Record<string, unknown>>).slice(0, 4)) {
      const sourceId = String(source.path || source.id || "");
      if (!sourceId) continue;
      addNode({ id: sourceId, label: source.title || path.basename(sourceId), type: source.sourceType || "source", source: source.source || "evidence", category: source.category || category, path: source.path, tags: [source.status, source.noteCategory].filter(Boolean) });
      if (rowId) addEdge({ source: rowId, target: sourceId, label: "cites" });
      addEdge({ source: `category:${source.category || category}`, target: sourceId, label: String(source.status || "") === "embedded" ? "embedded" : "indexed" });
    }
  }
  for (const source of sourceStates.slice(0, 34)) {
    const sourceId = String(source.path || source.id);
    addNode({ id: sourceId, label: source.title, type: String(source.sourceType || "source"), source: source.source, path: source.path, tags: [source.status, source.noteCategory].filter(Boolean) });
    addEdge({ source: `category:${source.category || "general"}`, target: sourceId, label: source.status === "embedded" ? "embedded" : "detected" });
    const wikiPagePath = String(source.wikiPagePath || "");
    if (wikiPagePath && nodes.has(wikiPagePath)) addEdge({ source: wikiPagePath, target: sourceId, label: "source-evidence" });
  }
  for (const edge of graph.edges.slice(0, 80)) {
    addEdge(edge);
  }
  return { nodes: [...nodes.values()], edges: [...edges.values()] };
}

function knowledgeLiveSnapshot() {
  const values = [
    db.prepare("SELECT MAX(updated_at) value FROM knowledge_entries").get() as { value?: string } | undefined,
    db.prepare("SELECT MAX(created_at) value FROM knowledge_file_index").get() as { value?: string } | undefined,
    db.prepare("SELECT MAX(updated_at) value FROM knowledge_output_jobs").get() as { value?: string } | undefined,
    db.prepare("SELECT MAX(updated_at) value FROM knowledge_wiki_pages").get() as { value?: string } | undefined,
    db.prepare("SELECT MAX(started_at) value FROM knowledge_wiki_runs").get() as { value?: string } | undefined,
  ].map((row) => row?.value || "").filter(Boolean).sort();
  const counts = {
    entries: Number((db.prepare("SELECT COUNT(*) count FROM knowledge_entries").get() as { count?: number } | undefined)?.count || 0),
    files: Number((db.prepare("SELECT COUNT(*) count FROM knowledge_file_index").get() as { count?: number } | undefined)?.count || 0),
    wikiPages: Number((db.prepare("SELECT COUNT(*) count FROM knowledge_wiki_pages").get() as { count?: number } | undefined)?.count || 0),
  };
  return { version: values.at(-1) || nowIso(), ...counts };
}

function compileKnowledgeSourcesBestEffort(paths: string[]) {
  const sourcePaths = uniqueStrings(paths.map(String).filter((item) => item && atlasSourceSupportsWiki(item, atlasSourceTypeForPath(item))));
  if (!sourcePaths.length) return { ok: true, status: "unsupported_manifest_only", sourcePaths: [] };
  try {
    const result = compileKnowledgeWiki(db, { mode: "selected", sourcePaths });
    return { ok: true, status: result.errorCount ? "completed_with_errors" : "embedded", sourcePaths, generatedCount: result.generatedCount, skippedCount: result.skippedCount, errorCount: result.errorCount };
  } catch (err) {
    return { ok: false, status: "failed_retry", sourcePaths, error: err instanceof Error ? err.message : String(err) };
  }
}

function collectTreeGraphNode(
  item: Record<string, unknown>,
  source: string,
  parentId: string,
  depth: number,
  selectedPath: string,
  addNode: (node: Record<string, unknown>) => void,
  addEdge: (source: string, target: string, label: string) => void,
) {
  const itemPath = String(item.path || "");
  if (!itemPath) return;
  const itemType = String(item.type || "file");
  const id = itemPath;
  const isCurrent = selectedPath && itemPath === selectedPath;
  const inferred = inferGraphNode(String(item.title || path.basename(itemPath)), itemPath);
  addNode({
    id,
    label: String(item.title || path.basename(itemPath)),
    type: isCurrent ? "current" : itemType === "folder" ? "folder" : inferred.type,
    source,
    path: itemPath,
    depth,
    size: Number(item.size || 0),
    tags: inferred.tags,
  });
  addEdge(parentId, id, "contains");
  if (itemType !== "folder") {
    for (const tag of inferred.tags) {
      const tagId = `tag:${tag}`;
      addNode({ id: tagId, label: tag, type: "tag", source: "tag" });
      addEdge(tagId, id, tag === "moc" ? "moc" : "tag");
    }
    if (selectedPath && path.dirname(itemPath) === path.dirname(selectedPath) && itemPath !== selectedPath) addEdge(selectedPath, id, "semantic");
  }
  const children = Array.isArray(item.children) ? item.children as Array<Record<string, unknown>> : [];
  const childLimit = depth <= 1 || selectedPath.startsWith(itemPath) ? 36 : 14;
  for (const child of children.slice(0, childLimit)) collectTreeGraphNode(child, source, id, depth + 1, selectedPath, addNode, addEdge);
}

function inferGraphNode(label: string, filePath: string) {
  const ext = path.extname(filePath).toLowerCase();
  const normalized = `${label} ${filePath}`.toLowerCase();
  const tags = new Set<string>();
  for (const part of filePath.split(/[\\/]/).slice(-5)) {
    const clean = part.replace(/\.(md|pdf|docx?|pptx?|xlsx?|txt|csv|png|jpe?g|webp|gif|mp4|mov|m4a|mp3)$/i, "").trim();
    if (clean && clean.length <= 24 && !["memory", "knowledge", "archive", "notes", "index"].includes(clean.toLowerCase())) tags.add(clean);
  }
  if (normalized.includes("moc") || normalized.includes("/moc/") || normalized.includes("_moc")) tags.add("moc");
  if (normalized.includes("task") || normalized.includes("任务")) tags.add("task");
  if (normalized.includes("report") || normalized.includes("报告")) tags.add("report");
  const mediaExts = new Set([".png", ".jpg", ".jpeg", ".webp", ".gif", ".mp4", ".mov", ".m4a", ".mp3", ".wav"]);
  const type = tags.has("moc") ? "moc" : mediaExts.has(ext) ? "media" : "document";
  return { type, tags: [...tags].slice(0, 8) };
}

async function ensureChatSession(body: { sessionId?: string; message?: string; agentId?: string; knowledgeSources?: string[]; skillIds?: string[]; planEnabled?: boolean; modelId?: string }): Promise<ChatSessionRow> {
  if (body.sessionId) {
    const existing = db.prepare("SELECT * FROM chat_sessions WHERE id = ?").get(body.sessionId) as ChatSessionRow | undefined;
    if (existing) return existing;
  }
  const id = randomUUID();
  db.prepare("INSERT INTO chat_sessions (id, title, agent_id, knowledge_sources, skill_ids, plan_enabled, favorite, created_at, updated_at, model_id) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
    .run(id, autoTitle(body.message || "新对话"), body.agentId || "main", JSON.stringify(body.knowledgeSources || ["all"]), JSON.stringify(body.skillIds || []), body.planEnabled ? 1 : 0, 0, nowIso(), nowIso(), body.modelId || "minimax-m3");
  return db.prepare("SELECT * FROM chat_sessions WHERE id = ?").get(id) as ChatSessionRow;
}

function ensureChatSessionForWrite(input: { sessionId: string; agentId?: string; title?: string; content?: string; modelId?: string }) {
  const existing = db.prepare("SELECT id FROM chat_sessions WHERE id = ?").get(input.sessionId);
  if (existing) return false;
  const now = nowIso();
  db.prepare("INSERT INTO chat_sessions (id, title, agent_id, knowledge_sources, skill_ids, plan_enabled, favorite, created_at, updated_at, model_id) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")
    .run(input.sessionId, input.title || autoTitle(input.content || "恢复的对话"), input.agentId || "main", JSON.stringify(["all"]), JSON.stringify([]), 0, 0, now, now, input.modelId || "minimax-m3");
  audit(db, "chat.session.restore_for_write", "chat_session", input.sessionId, "normal", { reason: "missing_session_before_message_insert" });
  return true;
}

function restoreChatSessionIfMissing(session: ChatSessionRow, content = "") {
  return ensureChatSessionForWrite({
    sessionId: session.id,
    agentId: session.agent_id || "main",
    title: session.title || autoTitle(content || "恢复的对话"),
    content,
    modelId: session.model_id || "minimax-m3",
  });
}

async function dispatchChat(sessionId: string, agentId: string, content: string, sourceMessageId: string, context: ChatGatewayContext & { metadata?: Record<string, unknown> } = {}) {
  const result = await runGatewayChat(sessionId, agentId, content, sourceMessageId, context);
  const assistantId = randomUUID();
  ensureChatSessionForWrite({ sessionId, agentId, content, modelId: context.modelId });
  db.prepare("INSERT INTO chat_messages (id, session_id, role, agent_id, content, message_type, status, metadata, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)")
    .run(assistantId, sessionId, "assistant", agentId, result.response, "text", result.status, JSON.stringify({ gateway: result.gateway, context: result.context, ...(context.metadata || {}) }), nowIso());
  db.prepare("UPDATE chat_sessions SET updated_at = ? WHERE id = ?").run(nowIso(), sessionId);
  return db.prepare("SELECT * FROM chat_messages WHERE id = ?").get(assistantId);
}

type IMessageSendIntent = {
  message: string;
  target: string;
  targetLabel: string;
  source: "explicit" | "configured_default";
};

type IMessageSendActionResult = {
  content: string;
  status: "completed" | "sent_pending" | "gateway_unavailable";
  metadata: Record<string, unknown>;
};

type IWechatSendIntent = {
  message: string;
  recipient: string;
  recipientLabel: string;
  source: "explicit" | "configured_default";
};

type IWechatSendActionResult = {
  content: string;
  status: "sent_pending" | "gateway_unavailable";
  metadata: Record<string, unknown>;
};

function normalizeWechatRecipientName(value: string) {
  return String(value || "")
    .replace(/[\s，。；,;:：.!！？\"'“”‘’「」『』《》【】()（）]+$/g, "")
    .replace(/^[\s，。；,;:：.!！？\"'“”‘’「」『』《》【】()（）]+/g, "")
    .replace(/\s+/g, "")
    .trim();
}

function hasExplicitWechatSendAction(raw: string) {
  const text = String(raw || "");
  if (!/微信|weixin|wechat/i.test(text)) return false;
  return [
    /(?:微信|weixin|wechat)[\s\S]{0,24}(?:发送给|发给|推送给|给\s*[\u4e00-\u9fffA-Za-z0-9_\-·]{2,30}\s*(?:发送|发消息|发一条|推送))/iu,
    /(?:发送给|发给|推送给|给\s*[\u4e00-\u9fffA-Za-z0-9_\-·]{2,30}\s*(?:发送|发消息|发一条|推送))[\s\S]{0,24}(?:微信|weixin|wechat)/iu,
    /(?:微信|weixin|wechat)\s*(?:群|群里|里|中)?\s*(?:发送|发一条|发消息|推送)\s*(?:给)?/iu,
  ].some((pattern) => pattern.test(text));
}

function isWechatDiagnosticOrNarration(raw: string) {
  const text = String(raw || "");
  if (/(?:内容|消息|正文)\s*(?:是|为)?\s*[:：]/.test(text)) return false;
  return /(?:失败|报错|为什么|怎么|如何|检查|配置|没有收到|收不到|是否|能否|原因|排查|修复|不一致|反馈|截图|显示|测试|验证|记录|录入了|说了|回复了|我(?:是|叫)|自我介绍)/.test(text);
}

function extractWechatRecipientCandidates(content: string): string[] {
  const raw = String(content || "").trim();
  const candidates: string[] = [];
  const directPatterns = [
    /(?:微信|weixin|wechat)?\s*(?:发送给|发给|推送给)\s*([\u4e00-\u9fffA-Za-z0-9_\-·]{2,30})/iu,
    /(?:微信|weixin|wechat)?\s*给\s*([\u4e00-\u9fffA-Za-z0-9_\-·]{2,30})\s*(?:发送|发消息|发一条|推送)/iu,
    /^([\u4e00-\u9fffA-Za-z0-9_\-·]{2,30})\s*(?:微信)?\s*(?:发送|发消息|发一条|推送)/iu,
  ];
  for (const pattern of directPatterns) {
    const match = raw.match(pattern)?.[1];
    const normalized = normalizeWechatRecipientName(match || "");
    if (normalized && !/发送|发给|发一条|消息|内容|正文|群里|群|微信|wechat|weixin|给|请|帮我/i.test(normalized)) {
      candidates.push(normalized);
    }
  }
  const explicitTarget = raw.match(/\b(chat_id:\d+|chat_guid:[^\s，。；;:：]+|chat_identifier:[^\s，。；;]+)\b/i)?.[1];
  if (explicitTarget) candidates.push(explicitTarget);
  return [...new Set(candidates.filter(Boolean))];
}

function extractWechatMessageContent(content: string, recipient: string) {
  const raw = String(content || "").trim();
  const escapedRecipient = recipient ? recipient.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") : "";
  const candidatePatterns = [
    /(?:内容|消息|正文)\s*(?:是|为)?\s*[:：]\s*([\s\S]+)$/i,
    /(?:发送给|发给|推送给|给)\s*[^\s，。；:：!！?？,，]{2,30}[\s\S]{0,16}[:：]\s*([\s\S]+)$/i,
    /(?:微信|weixin|wechat)[\s\S]{0,48}[:：]\s*([\s\S]+)$/i,
    escapedRecipient ? new RegExp(`${escapedRecipient}[\\s\\S]{0,16}(?:发送|发消息|发一条|推送)\\s*[:：]?\\s*([\\s\\S]+)$`, "i") : null,
  ];
  for (const pattern of candidatePatterns.filter(Boolean) as RegExp[]) {
    const match = raw.match(pattern)?.[1]?.trim();
    if (match) return stripWrappingQuotes(match.replace(/\s*(?:谢谢|麻烦了)[。.!！]?$/i, "").trim());
  }
  return "";
}

function resolveWechatDefaultMetadata(sourceMessageId: string, intentSource: string) {
  return {
    sourceMessageId,
    intentSource,
    intentSourceVersion: 2,
    awaitingEvidenceHint: "当前仅为外发动作预处理与待核验状态，未拿到目标会话回执。",
    verification: "unverified",
    progressHint: "等待外部会话确认",
  };
}

function normalizeJsonObject(value: unknown): Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value)) return {};
  return value as Record<string, unknown>;
}

function extractIMessageFailureAttempts(errorPayload: unknown): unknown[] {
  const candidate = normalizeJsonObject(errorPayload);
  const attempts = Array.isArray(candidate.attempts) ? candidate.attempts : [];
  return attempts.filter((item) => item !== null && typeof item === "object");
}

function extractIMessageFailureReason(input: unknown): string {
  const candidate = normalizeJsonObject(input);
  const nestedError = normalizeJsonObject(candidate.error);
  if (typeof candidate.reason === "string" && candidate.reason.trim()) return candidate.reason;
  if (typeof nestedError.message === "string" && nestedError.message.trim()) return nestedError.message;
  if (typeof candidate.message === "string" && candidate.message.trim()) return candidate.message;
  if (typeof nestedError.data === "string" && nestedError.data.trim()) return nestedError.data;
  if (typeof nestedError.reason === "string" && nestedError.reason.trim()) return nestedError.reason;
  return "OpenClaw iMessage send did not return a success result.";
}

function detectIMessageSendIntent(content: string): IMessageSendIntent | null {
  const raw = String(content || "").trim();
  if (!raw) return null;
  const mentionsIMessage = /iMessage|imessage|iPhone|iphone|苹果手机|手机/.test(raw);
  const asksToSend = /发送|发给|发一条|发消息|推送/.test(raw);
  if (!mentionsIMessage || !asksToSend) return null;
  if (/失败|报错|修复|为什么|怎么|如何|检查|配置|没有收到|收不到/.test(raw) && !/(内容|消息|正文)\s*(是|为)?\s*[:：]/.test(raw)) {
    return null;
  }

  const explicitTarget = raw.match(/\b(chat_id:\d+|chat_guid:[^\s，。；;]+|chat_identifier:[^\s，。；;]+)\b/i)?.[1];
  const patterns = [
    /(?:内容|消息|正文)\s*(?:是|为)?\s*[:：]\s*([\s\S]+)$/i,
    /(?:发送|发给|发一条|发消息|推送)[^:：]{0,40}[:：]\s*([\s\S]+)$/i,
    /(?:说|告诉我)\s*[:：]\s*([\s\S]+)$/i,
  ];
  let message = "";
  for (const pattern of patterns) {
    const match = raw.match(pattern);
    if (match?.[1]?.trim()) {
      message = match[1].trim();
      break;
    }
  }
  if (!message) return null;
  message = stripWrappingQuotes(message.replace(/\s*(?:谢谢|麻烦了)[。.!！]?$/i, "").trim());
  if (!message || message.length > 4000) return null;
  const target = explicitTarget || resolveDefaultIMessageTarget();
  return {
    message,
    target,
    targetLabel: explicitTarget ? "显式 iMessage 目标" : "默认 iPhone 会话",
    source: explicitTarget ? "explicit" : "configured_default",
  };
}

function detectWechatSendIntent(content: string): IWechatSendIntent | null {
  const raw = String(content || "").trim();
  if (!raw) return null;
  if (!hasExplicitWechatSendAction(raw)) return null;
  if (isWechatDiagnosticOrNarration(raw)) return null;

  const recipientCandidates = extractWechatRecipientCandidates(raw);
  const explicitRecipient = recipientCandidates[0] || "";
  let message = extractWechatMessageContent(raw, explicitRecipient) || "";
  if (!message) return null;
  message = stripWrappingQuotes(message.replace(/\s*(?:谢谢|麻烦了)[。.!！]?$/i, "").trim());
  if (!message || message.length > 4000) return null;

  const recipient = (explicitRecipient || resolveDefaultWechatRecipient()).trim();
  const recipientLabel = explicitRecipient ? `显式收件人：${explicitRecipient}` : "默认收件人";
  if (!recipient) return null;
  return {
    message,
    recipient,
    recipientLabel,
    source: explicitRecipient ? "explicit" : "configured_default",
  };
}

function stripWrappingQuotes(value: string) {
  let text = value.trim();
  for (let i = 0; i < 3; i += 1) {
    const next = text
      .replace(/^["'“”‘’「『《【]+/, "")
      .replace(/["'“”‘’」』》】]+$/, "")
      .trim();
    if (next === text) break;
    text = next;
  }
  return text;
}

function resolveDefaultIMessageTarget() {
  const configured = String(process.env.OPENCLAW_WORKBENCH_IMESSAGE_TARGET || "").trim();
  if (configured) return configured;
  try {
    const parsed = safeJsonObject(fs.readFileSync(OPENCLAW_CRON_JOBS_PATH, "utf8"));
    const jobs = Array.isArray(parsed.jobs) ? parsed.jobs : Array.isArray(parsed) ? parsed : [];
    const candidates = jobs
      .map((job) => safeJsonObject(job))
      .map((job) => safeJsonObject(job.delivery).to)
      .filter((to): to is string => typeof to === "string" && /^chat_id:\d+$/i.test(to.trim()))
      .map((to) => to.trim());
    if (candidates[0]) return candidates[0];
  } catch {
    // Fall back to the existing migrated iPhone chat target.
  }
  return DEFAULT_IMESSAGE_TARGET;
}

function resolveDefaultWechatRecipient() {
  const configured = String(process.env.OPENCLAW_WORKBENCH_WECHAT_RECIPIENT || process.env.OPENCLAW_WECHAT_DEFAULT_RECIPIENT || "").trim();
  if (configured) return configured;
  return "";
}

function imessagePendingContent(intent: IMessageSendIntent) {
  return [
    "# iMessage 发送中",
    "",
    "已识别为明确的 iPhone/iMessage 发送请求，Workbench 将直接调用 OpenClaw iMessage channel，不再交给模型猜测工具能力。",
    "",
    `目标：${intent.targetLabel}`,
    `正文：${intent.message}`,
  ].join("\n");
}

function buildWechatPendingContent(intent: IWechatSendIntent, details: { approvalId?: string; verifiedRecipient?: string; safeBehavior?: string }) {
  const verifiedRecipient = (details.verifiedRecipient || "").trim() || intent.recipientLabel;
  const safeBehavior = (details.safeBehavior || "message_not_sent").replace(/_/g, " ");
  return [
    "# 微信外发待核验",
    "",
    "已识别为明确的微信外发请求，已进入审批流程。",
    "",
    `收件人：${verifiedRecipient || intent.recipientLabel}`,
    `正文：${intent.message}`,
    `状态：待核验（尚未拿到目标会话回执）`,
    details.approvalId ? `待审批单号：${details.approvalId}` : "",
    `安全状态：${safeBehavior}`,
    "",
    "请在“微信外发准备”或“待审批”中确认后发送。",
  ].filter(Boolean).join("\n");
}

function createWechatApproval(recipientName: string, message: string, options?: { sourceMessageId?: string; rawIntent?: string; intentSource?: string; intentSourceVersion?: number }) {
  const prepare = computerUseWechatPrepare(recipientName, message) as Record<string, unknown>;
  if (prepare.ok !== true) {
    return {
      ok: false,
      prepare,
      error: "recipient_verification_failed",
      safeBehavior: (prepare.safeBehavior as string) || "message_not_typed_or_sent",
    } as const;
  }
  const approvalId = randomUUID();
  const details = {
    ...resolveWechatDefaultMetadata(options?.sourceMessageId || "", options?.intentSource || "wechat-send"),
    rawIntent: options?.rawIntent || message,
    source: "computer_use_wechat_prepare",
    recipientName,
    message,
    messageLength: message.length,
    messageHash: String(prepare.messageHash || createHash("sha256").update(message).digest("hex").slice(0, 16)),
    messagePreview: message.slice(0, 80),
    verifiedRecipientTitle: prepare.verifiedRecipientTitle || prepare.currentChatTitle || "",
    selectedScreenshotPath: prepare.selectedScreenshotPath || "",
      safeBehavior: prepare.safeBehavior || "message_not_typed_or_sent",
    execution: "not_sent_prepare_only",
  };
  db.prepare("INSERT INTO approvals (id, task_id, action, status, requested_at, details) VALUES (?, ?, ?, ?, ?, ?)")
    .run(approvalId, null, "wechat_send_message", "pending", nowIso(), JSON.stringify(details));
  audit(db, "computer_use.wechat_prepare", "approval", approvalId, "high", details);
  return { ok: true, prepare, approvalId, details } as const;
}

async function runWechatSendAction(intent: IWechatSendIntent, sourceMessageId: string): Promise<IWechatSendActionResult> {
  const startedAt = Date.now();
  const approval = createWechatApproval(intent.recipient, intent.message, {
    sourceMessageId,
    rawIntent: intent.message,
    intentSource: "send-endpoint",
    intentSourceVersion: 2,
  });
  const baseMetadata = {
    sourceMessageId,
    intentSource: "send-endpoint",
    intentSourceVersion: 2,
    verification: "unverified",
    progressHint: "等待外部会话确认",
    awaitingEvidenceHint: "执行已提交待审批/回执，当前仅保留动作线索。",
  };
  const durationMs = Date.now() - startedAt;
  const metadata = {
    ...baseMetadata,
    openclawAction: "wechat.prepare",
    channel: "wechat",
    recipient: intent.recipient,
    recipientLabel: intent.recipientLabel,
    recipientSource: intent.source,
    durationMs,
    recipientConfidence: intent.source === "explicit" ? "high" : "default",
    approvalId: approval.ok && approval.approvalId ? approval.approvalId : "",
  };
  if (approval.ok && approval.approvalId && approval.prepare) {
    const details = approval.details || {};
    const verifiedRecipient = String(details.verifiedRecipientTitle || intent.recipient).trim();
    return {
      status: "sent_pending",
      metadata: {
        ...metadata,
        safeBehavior: details.safeBehavior || "message_not_sent",
        verifiedRecipient,
        awaitingEvidenceHint: baseMetadata.awaitingEvidenceHint,
        sourceMessageId,
        intentSource: "send-endpoint",
        intentSourceVersion: 2,
        verification: "unverified",
        messageHash: details.messageHash || "",
      },
      content: buildWechatPendingContent(intent, { approvalId: approval.approvalId, verifiedRecipient, safeBehavior: String(details.safeBehavior || "message_not_sent") }),
    };
  }
  const safeBehavior = approval.safeBehavior || "message_not_typed_or_sent";
  const errText = sanitizePublicError(approval.prepare ? String(approval.error || approval.prepare.error || "wechat prepare failed") : "wechat prepare failed");
  return {
    status: "gateway_unavailable",
    metadata: {
      ...metadata,
      error: approval.error || "wechat_prepare_failed",
      verification: "failed",
      sourceMessageId,
      intentSource: "send-endpoint",
      intentSourceVersion: 2,
      safeBehavior,
      failure: errText,
      awaitingEvidenceHint: "未通过收件人校验，无法生成可回填外发待核验记录。",
    },
    content: [
      "# 微信外发未进入审批",
      "",
      "已识别为微信外发请求，但未完成收件人验证。",
      "",
      `收件人：${intent.recipientLabel}`,
      `意图来源：wechat-send-endpoint`,
      `错误：${errText}`,
      "",
      "请在“微信外发准备”先完成收件人校验后再次提交。",
    ].join("\n"),
  };
}

async function runIMessageSendAction(intent: IMessageSendIntent, sourceMessageId: string): Promise<IMessageSendActionResult> {
  const target = String(intent.target || "").trim();
  const explicitMatch = target.match(/^(chat_id|chat_guid|chat_identifier)\s*:\s*(.+)$/i);
  const params: Record<string, unknown> = {
    channel: "imessage",
    accountId: "default",
    message: intent.message,
    idempotencyKey: `${sourceMessageId}:imessage-send`,
  };
  if (explicitMatch) {
    const key = explicitMatch[1].toLowerCase();
    const value = explicitMatch[2].trim();
    if (key === "chat_id" || key === "chat_guid" || key === "chat_identifier") {
      const field = key === "chat_identifier" ? "chatIdentifier" : key;
      params[field] = value;
    } else {
      params.to = target;
    }
  } else {
    params.to = target;
  }
  const startedAt = Date.now();
  const gateway = await gatewayCall<Record<string, unknown>>("send", params, 60_000);
  const durationMs = Date.now() - startedAt;
  const sendResult = gateway.ok ? safeJsonObject(gateway.data) : {};
  const payloadResult = safeJsonObject(sendResult.result);
  const messageId = String(payloadResult.messageId || payloadResult.id || payloadResult.guid || sendResult.messageId || "");
  const timedOut = !gateway.ok && isGatewayFinalTimeout(gateway.error);
  const ok = Boolean(gateway.ok && (messageId || sendResult.channel === "imessage" || payloadResult.ok === true));
  const sendError = gateway.ok ? normalizeJsonObject(sendResult.error || payloadResult.error) : normalizeJsonObject(gateway.error);
  const failureReason = gateway.ok
    ? extractIMessageFailureReason(sendError)
    : sanitizePublicError(gateway.error || "gateway_unavailable");
  const attempts = Array.from(new Set([
    ...extractIMessageFailureAttempts(sendError),
    ...extractIMessageFailureAttempts(sendResult),
    ...extractIMessageFailureAttempts(payloadResult),
  ].map((entry) => JSON.stringify(entry))))
    .map((entry) => {
      try {
        return JSON.parse(entry) as Record<string, unknown>;
      } catch {
        return entry;
      }
    });
  const metadata = {
    openclawAction: "imessage.send",
    channel: "imessage",
    target: intent.target,
    targetLabel: intent.targetLabel,
    targetSource: intent.source,
    durationMs,
    attempts,
    failure: ok ? undefined : {
      reason: failureReason,
      source: gateway.ok ? "wrapper" : "gateway",
    },
    gateway: gateway.ok ? { ok: true, status: gateway.status, data: sendResult } : { ok: false, status: gateway.status, error: gateway.error },
    timedOut,
  };
  if (ok) {
    audit(db, "chat.imessage_send", "channel", "imessage", "normal", { target: intent.target, targetSource: intent.source, messageId: messageId || "ok", durationMs });
    return {
      status: "completed",
      metadata,
      content: [
        "# iMessage 已发送",
        "",
        "已通过 OpenClaw 自己的 iMessage channel 发送到 iPhone。",
        "",
        "- 发送路径：OpenClaw Gateway `send` → `channels.imessage`",
        `- 目标：${intent.targetLabel}`,
        `- 消息 ID：${messageId || "ok"}`,
        "",
        "这次没有使用 Codex 直接 AppleScript 兜底。",
      ].join("\n"),
    };
  }
  const sendErrorMessage = normalizeJsonObject(sendError).message || normalizeJsonObject(sendError).reason;
  const error = sanitizePublicError(gateway.error || String(sendErrorMessage || sendResult.error || "OpenClaw iMessage send did not return a success result."));
  const attemptLines = attempts
    .filter((entry): entry is Record<string, unknown> => Boolean(entry && typeof entry === "object" && !Array.isArray(entry)))
    .map((entry) => {
      const attempt = normalizeJsonObject(entry);
      const attemptNo = String(attempt.attempt || "?");
      const strategy = String(attempt.strategy || "send");
      const key = String(attempt.key || "unknown");
      const retryable = attempt.retryable === true ? "可重试" : "不可重试";
      const detail = String(attempt.error || attempt.reason || "").replace(/\n/g, " ").trim();
      return `  - 第 ${attemptNo} 次 (${strategy})：${key}，${retryable}${detail ? `，原因：${detail}` : ""}`;
    });
  audit(db, "chat.imessage_send_failed", "channel", "imessage", "normal", {
    target: intent.target,
    targetSource: intent.source,
    error,
    reason: failureReason,
    attempts,
    durationMs,
  });
  return {
    status: timedOut ? "sent_pending" : "gateway_unavailable",
    metadata,
    content: [
      timedOut ? "# iMessage 已提交，待核验回执" : "# iMessage 发送失败",
      "",
      "Workbench 已识别为 iPhone/iMessage 发送请求，并已改走 OpenClaw channel send；失败不是“模型没有工具”的回答问题，而是 OpenClaw 发送链路没有返回成功。",
      "",
      "- 发送路径：OpenClaw Gateway `send` → `channels.imessage`",
      `- 目标：${intent.targetLabel}`,
      `- 错误：${error}`,
      `- 失败原因：${failureReason}`,
      ...attemptLines.length ? ["- 发送尝试明细：", ...attemptLines] : ["- 发送尝试明细：无（本次未返回 wrapper attempts）"],
      "",
      timedOut
        ? "当前状态是“已提交/待核验”，请根据目标客户端回执确认。若长时间无回执，可通过 `openclaw-cn gateway call send` 与 `channels.status` 检查发送链路。"
        : "Worker 运维下一步应检查：`openclaw-cn gateway call send`、`channels.status`、iMessage wrapper 和 Messages 权限状态。",
    ].join("\n"),
  };
}

async function runGatewayChat(sessionId: string, agentId: string, content: string, sourceMessageId: string, context: ChatGatewayContext = {}) {
  const prompt = composeAgentPrompt(content, context);
  const dispatchedAt = Date.now();
  const sessionKey = context.sessionKey || `agent:${agentId}:workbench:${sessionId}`;
  const gateway = await gatewayCall("agent", {
    agentId,
    sessionKey,
    message: prompt,
    idempotencyKey: sourceMessageId,
  }, context.timeoutMs || CHAT_GATEWAY_TIMEOUT_MS, { expectFinal: true });
  const gatewayText = gateway.ok ? extractGatewayText(gateway.data) : "";
  const gatewayThinking = gateway.ok ? extractGatewayThinking(gateway.data, agentId, dispatchedAt - 1000) : "";
  const timedOut = !gateway.ok && isGatewayFinalTimeout(gateway.error);
  const response = gateway.ok
    ? appendGatewayThinking(gatewayText || `已发送给 ${agentId}。OpenClaw Gateway 已接收。Run ID: ${(gateway.data as { runId?: string } | undefined)?.runId || "gateway accepted"}`, gatewayThinking)
    : timedOut
      ? backgroundGatewayContent(gateway.error || "")
      : `Gateway 暂不可用，消息已保存在工作台。错误：${gateway.error || "unavailable"}`;
  const safeResponse = normalizeExternalActionClaims(response);
  return {
    gateway,
    context: { ...context, sessionKey, gatewayTimedOut: timedOut },
    response: safeResponse,
    status: gateway.ok && gatewayText ? "completed" : gateway.ok ? "dispatched" : timedOut ? "running" : "gateway_unavailable",
  };
}

function findActiveTaskExecutorMeta(sessionId: string): Required<TaskExecutorMeta> | null {
  const rows = db.prepare("SELECT metadata, status FROM chat_messages WHERE session_id = ? AND role = 'assistant' AND deleted_at IS NULL ORDER BY created_at DESC LIMIT 20").all(sessionId) as Array<{ metadata: string; status: string }>;
  for (const row of rows) {
    const meta = normalizeTaskExecutorMeta(safeJsonObject(row.metadata));
    if (!meta.taskExecutor || !meta.taskPath || !meta.taskId) continue;
    const phase = meta.taskExecutorPhase || "clarifying";
    if (["completed", "blocked"].includes(phase) || ["completed", "deleted", "gateway_unavailable"].includes(row.status)) continue;
    return meta as Required<TaskExecutorMeta>;
  }
  return null;
}

function createTaskExecutorMeta(agentId: string): Required<TaskExecutorMeta> {
  const workspace = taskExecutorWorkspace(agentId);
  const baseDir = workspace === "main"
    ? path.join(WORKSPACE_DIR, "tasks")
    : path.join(WORKSPACE_DIR, `${workspace}_workspace`, "tasks");
  fs.mkdirSync(baseDir, { recursive: true });
  const date = localDateKey().replace(/-/g, "");
  const max = fs.readdirSync(baseDir)
    .map((name) => name.match(new RegExp(`^TASK_${date}_(\\d{3})$`))?.[1])
    .filter(Boolean)
    .map((value) => Number(value))
    .filter((value) => Number.isFinite(value))
    .sort((a, b) => b - a)[0] || 0;
  const taskId = `TASK_${date}_${String(max + 1).padStart(3, "0")}`;
  const taskPath = path.join(baseDir, taskId);
  fs.mkdirSync(taskPath, { recursive: true });
  return {
    taskExecutor: true,
    taskId,
    taskPath,
    planPath: path.join(taskPath, "PLAN.md"),
    resultPath: path.join(taskPath, "RESULT.md"),
    taskExecutorPhase: "clarifying",
    gatewaySessionKey: `agent:${agentId}:workbench:task:${taskId}`,
    workspace,
  };
}

function taskExecutorWorkspace(agentId: string): "main" | "boss" | "worker" {
  if (agentId === "boss") return "boss";
  if (agentId === "worker") return "worker";
  return "main";
}

async function runTaskExecutorPlanStep(
  taskMeta: Required<TaskExecutorMeta>,
  agentId: string,
  userText: string,
  sources: string[],
  skills: string[],
  modelId: string,
  userMessageId: string,
  stepKind: "start" | "continue",
) {
  const dispatchedAt = Date.now();
  const prompt = stepKind === "start"
    ? buildTaskExecutorClarifyingPrompt(taskMeta, agentId, userText, sources, skills, modelId)
    : buildTaskExecutorPlanningPrompt(taskMeta, agentId, userText, sources, skills, modelId);
  const gateway = await gatewayCall("agent", {
    agentId,
    sessionKey: taskMeta.gatewaySessionKey,
    message: prompt,
    idempotencyKey: `${userMessageId}:task-executor:${stepKind}`,
  }, PLAN_GATEWAY_TIMEOUT_MS, { expectFinal: true });
  const gatewayText = gateway.ok ? appendGatewayThinking(extractGatewayText(gateway.data), extractGatewayThinking(gateway.data, agentId, dispatchedAt - 1000)) : "";
  let metadata = reconcileTaskExecutorFiles({ ...taskMeta, taskExecutorPhase: stepKind === "start" ? "planning" : "planning" });
  if (metadata.taskExecutorPhase !== "awaiting_confirmation" && !fs.existsSync(metadata.planPath || "")) {
    metadata = writeFallbackTaskExecutorPlan(
      metadata as Required<TaskExecutorMeta>,
      agentId,
      userText,
      sources,
      skills,
      modelId,
      gateway.ok ? "agent_did_not_write_plan" : sanitizePublicError(gateway.error || "gateway_unavailable"),
      gatewayText,
    );
  }
  if (metadata.taskExecutorPhase === "awaiting_confirmation") {
    return {
      content: taskExecutorPlanReadyContent(metadata as Required<TaskExecutorMeta>),
      status: "awaiting_confirmation",
      metadata,
      gateway,
    };
  }
  const timedOut = !gateway.ok && isGatewayFinalTimeout(gateway.error);
  const content = timedOut
    ? taskExecutorBackgroundContent(metadata as Required<TaskExecutorMeta>, gateway.error || "", stepKind)
    : gateway.ok && gatewayText
      ? gatewayText
      : taskExecutorFallbackQuestions(metadata as Required<TaskExecutorMeta>, userText, gateway.error);
  return {
    content,
    status: timedOut ? "planning" : "clarifying",
    metadata: { ...metadata, taskExecutorPhase: timedOut ? "planning" : "clarifying", gatewayTimedOut: timedOut },
    gateway,
  };
}

function buildTaskExecutorClarifyingPrompt(task: Required<TaskExecutorMeta>, agentId: string, userText: string, sources: string[], skills: string[], modelId: string) {
  return [
    "请使用 task-executor skill 处理这个任务，但现在只进入【计划阶段】。",
    "Workbench 已经创建任务目录，禁止再创建新的 TASK 目录，禁止开始执行任务。",
    `任务目录：${task.taskPath}`,
    `计划文件：${task.planPath}`,
    `结果文件：${task.resultPath}`,
    `执行代理：${agentId}`,
    `知识源：${sources.join(", ") || "all"}`,
    `Skills：${ensureTaskExecutor(skills).join(", ")}`,
    `模型配置：${modelId}`,
    "",
    "如果信息足够，请按 task-executor 固定格式写入 PLAN.md，并立即执行 `ls -la` 自检 PLAN.md 存在；然后只输出计划摘要和 PLAN.md 路径，等待用户确认。",
    "如果信息明显不足，请先提出最多 3 个澄清问题，不要执行任务。",
    "",
    "用户任务：",
    userText,
  ].join("\n");
}

function writeFallbackTaskExecutorPlan(
  meta: Required<TaskExecutorMeta>,
  agentId: string,
  userText: string,
  sources: string[],
  skills: string[],
  modelId: string,
  reason: string,
  gatewayDraft?: string,
): TaskExecutorMeta {
  fs.mkdirSync(meta.taskPath, { recursive: true });
  const safeReason = sanitizePublicError(reason || "agent_did_not_write_plan");
  const plan = [
    `# ${meta.taskId} - Workbench Fallback PLAN`,
    "",
    "## 状态",
    "",
    "此 PLAN.md 由 Workbench 本地兜底生成：OpenClaw 代理未在计划阶段产出可检测的 PLAN.md。该文件用于保证“确认执行”有唯一计划文件可审计，正式执行仍需用户点击确认。",
    "",
    "## 任务目录",
    "",
    `- task_path: ${meta.taskPath}`,
    `- plan_path: ${meta.planPath}`,
    `- result_path: ${meta.resultPath}`,
    `- generated_at: ${nowIso()}`,
    `- fallback_reason: ${safeReason}`,
    "",
    "## 用户原始任务",
    "",
    userText || "(empty)",
    "",
    "## 执行配置",
    "",
    `- agent: ${agentId}`,
    `- model: ${modelId}`,
    `- knowledge_sources: ${sources.join(", ") || "all"}`,
    `- skills: ${ensureTaskExecutor(skills).join(", ")}`,
    "",
    "## 执行计划",
    "",
    "1. 读取用户原始任务和当前对话上下文。",
    "2. 使用已选择知识源补充必要背景，但不得暴露凭据或写入受保护路径。",
    "3. 按 task-executor 流程执行任务；涉及高风险动作时先请求确认。",
    "4. 执行完成后写入 RESULT.md，并在结果中列出改动、测试、风险和回滚方式。",
    "5. 立即自检 RESULT.md 是否存在。",
    "",
    "## 验收标准",
    "",
    "- 用户点击确认执行后，代理按本 PLAN.md 继续执行。",
    "- 执行结果写入 RESULT.md。",
    "- 对话返回 RESULT.md 路径和简要结论。",
    "- 不删除项目文档，不重启 OpenClaw Gateway。",
    "",
    "## 代理草稿或提问记录",
    "",
    gatewayDraft?.trim() ? gatewayDraft.trim().slice(0, 12_000) : "计划阶段没有可用代理草稿。",
    "",
    "## PLAN.md 自检",
    "",
    "Workbench 已写入本文件，并通过文件系统 stat 验证路径存在。服务端不在此处执行 shell 命令。",
  ].join("\n");
  fs.writeFileSync(meta.planPath, plan, "utf8");
  const stat = fs.statSync(meta.planPath);
  return {
    ...meta,
    taskExecutorPhase: "awaiting_confirmation",
    fallbackPlanGenerated: true,
    fallbackPlanSize: stat.size,
  } as TaskExecutorMeta;
}

