function reconcileChatMessages(sessionId: string) {
  if (!sessionId) return;
  const rows = db.prepare("SELECT * FROM chat_messages WHERE session_id = ? AND deleted_at IS NULL ORDER BY created_at ASC").all(sessionId) as Array<{ id: string; agent_id?: string; metadata: string; status: string; content: string; created_at: string }>;
  for (const row of rows) {
    const meta = safeJsonObject(row.metadata);
    const taskMeta = normalizeTaskExecutorMeta(meta);
    if (taskMeta.taskExecutor) {
      const reconciled = reconcileTaskExecutorFiles(taskMeta);
      const nextContent = taskExecutorContentForPhase(reconciled as Required<TaskExecutorMeta>, row.content);
      if (nextContent !== row.content || reconciled.taskExecutorPhase !== taskMeta.taskExecutorPhase) {
        db.prepare("UPDATE chat_messages SET content = ?, status = ?, metadata = ? WHERE id = ?")
          .run(nextContent, taskExecutorStatusForPhase(reconciled.taskExecutorPhase), JSON.stringify({ ...meta, ...reconciled, streaming: false }), row.id);
      }
      continue;
    }
    const context = safeJsonObject(meta.context);
    const gatewayTimedOut = Boolean(meta.gatewayTimedOut || context.gatewayTimedOut);
    const sessionKey = String(context.sessionKey || meta.gatewaySessionKey || "");
    if (gatewayTimedOut && sessionKey && ["running", "streaming"].includes(row.status)) {
      const recovered = recoverGatewayFinalFromSession(row.agent_id || "main", sessionKey, Date.parse(row.created_at || "") - 1000);
      if (recovered) {
        db.prepare("UPDATE chat_messages SET content = ?, status = ?, metadata = ? WHERE id = ?")
          .run(recovered, "completed", JSON.stringify({ ...meta, recoveredFromGatewaySession: true, streaming: false }), row.id);
      }
    }
  }
}

function normalizeTaskExecutorMeta(input: Record<string, unknown>): TaskExecutorMeta {
  const taskPath = typeof input.taskPath === "string" ? input.taskPath : "";
  const taskId = typeof input.taskId === "string" ? input.taskId : (taskPath ? path.basename(taskPath) : "");
  const planPath = typeof input.planPath === "string" ? input.planPath : (taskPath ? path.join(taskPath, "PLAN.md") : "");
  const resultPath = typeof input.resultPath === "string" ? input.resultPath : (taskPath ? path.join(taskPath, "RESULT.md") : "");
  const phase = typeof input.taskExecutorPhase === "string" ? input.taskExecutorPhase as TaskExecutorMeta["taskExecutorPhase"] : undefined;
  const workspace = input.workspace === "boss" || input.workspace === "worker" ? input.workspace : "main";
  return {
    taskExecutor: Boolean(input.taskExecutor || taskPath),
    taskId,
    taskPath,
    planPath,
    resultPath,
    taskExecutorPhase: phase,
    gatewaySessionKey: typeof input.gatewaySessionKey === "string" ? input.gatewaySessionKey : "",
    workspace,
  };
}

function reconcileTaskExecutorFiles(meta: TaskExecutorMeta): TaskExecutorMeta {
  const taskPath = meta.taskPath || "";
  const planPath = meta.planPath || (taskPath ? path.join(taskPath, "PLAN.md") : "");
  const resultPath = meta.resultPath || (taskPath ? path.join(taskPath, "RESULT.md") : "");
  const resultReady = Boolean(resultPath && fs.existsSync(resultPath));
  const planReady = Boolean(planPath && fs.existsSync(planPath));
  const currentPhase = meta.taskExecutorPhase || "clarifying";
  const phase = resultReady ? "completed" : currentPhase === "executing" ? "executing" : planReady ? "awaiting_confirmation" : currentPhase;
  return { ...meta, planPath, resultPath, taskExecutorPhase: phase };
}

function taskExecutorStatusForPhase(phase: TaskExecutorMeta["taskExecutorPhase"]) {
  if (phase === "completed") return "completed";
  if (phase === "awaiting_confirmation") return "awaiting_confirmation";
  if (phase === "executing") return "running";
  if (phase === "planning") return "planning";
  if (phase === "blocked") return "gateway_unavailable";
  return "clarifying";
}

function taskExecutorContentForPhase(meta: Required<TaskExecutorMeta>, fallback: string) {
  if (meta.taskExecutorPhase === "completed" && fs.existsSync(meta.resultPath)) return taskExecutorResultReadyContent(meta);
  if (meta.taskExecutorPhase === "awaiting_confirmation" && fs.existsSync(meta.planPath)) return taskExecutorPlanReadyContent(meta);
  return fallback;
}

function taskExecutorPlanReadyContent(meta: Required<TaskExecutorMeta>) {
  const plan = readTextFile(meta.planPath, 80_000);
  return [
    "# 任务计划",
    "",
    `task-executor 已生成唯一计划文件：[PLAN.md](${meta.planPath})`,
    "",
    `任务目录：${meta.taskPath}`,
    "",
    plan || "PLAN.md 已生成，但当前无法读取内容。",
  ].join("\n");
}

function taskExecutorResultReadyContent(meta: Required<TaskExecutorMeta>) {
  const result = readTextFile(meta.resultPath, 80_000);
  return [
    "# 任务结果",
    "",
    `task-executor 已完成执行，结果文件：[RESULT.md](${meta.resultPath})`,
    "",
    `任务目录：${meta.taskPath}`,
    "",
    result || "RESULT.md 已生成，但当前无法读取内容。",
  ].join("\n");
}

function taskExecutorBackgroundContent(meta: Required<TaskExecutorMeta>, error: string, stepKind: "start" | "continue") {
  return [
    stepKind === "start" ? "# 任务执行器提问中" : "# 任务计划生成中",
    "",
    "OpenClaw agent 已接收任务，仍在后台继续处理。Workbench 不再把 final 等待超时误判为 Gateway 不可用。",
    "",
    `任务目录：${meta.taskPath}`,
    `计划文件：[PLAN.md](${meta.planPath})`,
    "",
    `等待状态：${error}`,
    "",
    "稍后刷新对话后，如果 PLAN.md 已生成，这里会自动切换为“确认执行”。",
  ].join("\n");
}

function taskExecutorFallbackQuestions(meta: Required<TaskExecutorMeta>, userText: string, gatewayError?: string) {
  return [
    "# 任务执行器提问",
    "",
    `任务目录：${meta.taskPath}`,
    gatewayError ? `\n> Gateway 本次未返回可用提问，Workbench 先保留 task-executor 提问阶段。错误：${gatewayError}\n` : "",
    "请补充以下信息后，我再生成唯一的 PLAN.md：",
    "",
    "1. 这项任务的最终目标和边界是什么？哪些内容不在范围内？",
    "2. 期望交付物是什么格式？例如对话答复、文件、配置变更、报告或可执行结果。",
    "3. 验收标准是什么？完成后用哪些条件判断通过或不通过？",
    "4. 是否有风险、权限、时间、预算或外部系统限制？",
    "",
    `当前任务：${userText}`,
  ].join("\n");
}

function taskExecutorStreamingStatusContent(meta: TaskExecutorMeta, agentId: string, elapsedSeconds: number) {
  const lines = [
    "运行状态（非模型思考）：task-executor 正在处理。",
    `代理：${agentId}`,
    `任务目录：${meta.taskPath}`,
    elapsedSeconds > 0 ? `已等待：${elapsedSeconds} 秒` : "已等待：刚开始",
    "不会生成第二份 Workbench 计划；PLAN.md/RESULT.md 是唯一来源。",
  ].join("\n");
  return `# 任务执行器\n\n<thinking>${lines}</thinking>`;
}

function backgroundGatewayContent(error: string) {
  return [
    "代理仍在后台运行。",
    "",
    "Workbench 等待最终输出超时，但 Gateway 连接不一定不可用；消息和 Gateway 会话已保留。",
    "",
    `等待状态：${error || "OpenClaw Gateway CLI timed out while waiting for final agent output."}`,
    "",
    "稍后刷新对话，如后台会话已产出最终回复，Workbench 会自动回填。",
  ].join("\n");
}

function isBackgroundGatewayWaitingContent(content: string, status?: string) {
  const text = String(content || "");
  return status === "running" || status === "sent_pending" || /代理仍在后台运行|已提交|待核验|Workbench 等待最终输出超时|等待状态：OpenClaw Gateway CLI timed out|稍后刷新对话|background_running/.test(text);
}

function normalizeChatMessageForClient(row: Record<string, unknown>) {
  const content = String(row.content || "");
  const status = String(row.status || "");
  if (String(row.role || "") === "assistant" && isBackgroundGatewayWaitingContent(content, status)) {
    const createdAt = String(row.created_at || "");
    const elapsedMs = createdAt ? Date.now() - Date.parse(createdAt) : 0;
    const elapsedMinutes = Number.isFinite(elapsedMs) && elapsedMs > 0 ? Math.max(1, Math.round(elapsedMs / 60000)) : 0;
    if (status === "sent_pending") {
      return {
        ...row,
        status: "sent_pending",
        content: status === "sent_pending" && content.includes("待核验")
          ? content
          : [
            "# iMessage 外发待核验",
            "",
            "已提交外发动作，尚未拿到回执。",
            `- 已等待：约 ${elapsedMinutes} 分钟。`,
            "- 结果会在目标会话核验后回填。",
          ].join("\n"),
      };
    }
    return {
      ...row,
      status: "running",
      content: [
        "background_running",
        "",
        "## 代理后台运行中",
        "",
        "- 会话已保留：消息没有丢失。",
        "- 正在等待：OpenClaw Gateway 最终输出。",
        "- 自动回填：代理完成后会写回当前会话。",
        elapsedMinutes ? `- 已等待：约 ${elapsedMinutes} 分钟。` : "- 已等待：刚开始。",
        elapsedMinutes >= 3 ? "- 等候可信度：中低，建议检查 Gateway/代理日志或稍后刷新。" : "- 等候可信度：中，后台会话仍处于可回填状态。",
      ].join("\n"),
    };
  }
  return row;
}

function normalizeExternalActionClaims(content: string) {
  const text = String(content || "");
  const hasExternalSendClaim = /(微信|企业微信|飞书|短信|邮件|外发)[\s\S]{0,100}(已发送|发送成功|已通过|成功发送|发送给)|已通过微信发送|消息已成功发送|已发送给/.test(text);
  const verified = /sent_verified|发送后证据确认|目标窗口.*匹配|发送后消息气泡|已核验发送结果/.test(text);
  if (!hasExternalSendClaim || verified) return text;
  const downgraded = text
    .replace(/✅\s*\*\*消息已成功发送给([^\n*。！!]*)\*\*[。！!]?/g, "⚠️ 外部消息发送结果未核验。")
    .replace(/✅\s*消息已成功发送给[^\n。！!]*[。！!]?/g, "⚠️ 外部消息发送结果未核验。")
    .replace(/「([^」]+)」已通过微信发送。?/g, "「$1」已输入或尝试发送，发送结果待人工核验。")
    .replace(/消息已发送成功/g, "消息发送结果未核验")
    .replace(/已通过微信发送/g, "已输入或尝试发送，发送结果待人工核验");
  return [
    "⚠️ 外部消息状态：未通过 Workbench 证据核验。",
    "",
    "该回复包含外发成功表述，但没有 `sent_verified` 证据。请以目标客户端实际消息记录为准；若只看到输入框内容，则状态是“已输入/待人工发送”，不是“已发送”。",
    "",
    "---",
    "",
    downgraded,
  ].join("\n");
}

function liveGatewayStreamContent(agentId: string, sessionKey: string, sinceMs: number) {
  const sessionId = gatewaySessionIdForKey(agentId, sessionKey);
  if (!sessionId) return "";
  const safeAgent = agentId.replace(/[^a-zA-Z0-9_-]/g, "");
  if (!safeAgent) return "";
  const sessionPath = path.join(os.homedir(), ".openclaw", "agents", safeAgent, "sessions", `${sessionId}.jsonl`);
  if (!fs.existsSync(sessionPath)) return "";

  const thoughts: string[] = [];
  const processLines: string[] = [];
  const textBlocks: string[] = [];
  try {
    for (const line of fs.readFileSync(sessionPath, "utf8").split(/\r?\n/)) {
      if (!line.trim()) continue;
      const row = JSON.parse(line) as { type?: string; timestamp?: string; message?: { role?: string; content?: unknown[] } };
      if (row.type !== "message") continue;
      if (row.timestamp && Date.parse(row.timestamp) < sinceMs) continue;
      const role = row.message?.role || "";
      const parts = row.message?.content || [];
      if (role === "assistant") {
        for (const part of parts) {
          const item = part as Record<string, unknown>;
          const type = String(item.type || "");
          const thinking = firstTextValue(item, ["thinking", "reasoning", "thought", "thoughts"]);
          if (/^(thinking|reasoning|thoughts?)$/i.test(type) && thinking) thoughts.push(thinking);
          if (type === "text" && typeof item.text === "string" && item.text.trim()) textBlocks.push(item.text.trim());
          if (type === "toolCall") processLines.push(formatToolCallTrace(item));
        }
      }
      if (role === "toolResult") {
        const resultText = formatToolResultTrace(parts);
        if (resultText) processLines.push(resultText);
      }
    }
  } catch {
    return "";
  }

  const trace = [...new Set([...thoughts, ...processLines].map((item) => item.trim()).filter(Boolean))].join("\n\n").trim();
  const answer = [...new Set(textBlocks.map((item) => item.trim()).filter(Boolean))].join("\n\n").trim();
  if (!trace && !answer) return "";
  return [
    trace ? `<thinking>${escapeThinkingContent(trace)}</thinking>` : "",
    answer,
  ].filter(Boolean).join("\n\n").trim();
}

function firstTextValue(record: Record<string, unknown>, keys: string[]) {
  for (const key of keys) {
    const value = record[key];
    if (typeof value === "string" && value.trim()) return value.trim();
  }
  return "";
}

function escapeThinkingContent(value: string) {
  return value.replace(/<\/(think|thinking|reasoning|thoughts?)>/gi, "</ $1>");
}

function formatToolCallTrace(item: Record<string, unknown>) {
  const name = String(item.name || item.toolName || "tool");
  const args = typeof item.arguments === "string" ? item.arguments : item.arguments ? JSON.stringify(item.arguments) : "";
  const preview = args.trim() ? `\n参数：${args.trim().slice(0, 800)}` : "";
  return `调用工具：${name}${preview}`;
}

function formatToolResultTrace(parts: unknown[]) {
  const text = parts.map((part) => extractGatewayText(part)).filter(Boolean).join("\n\n").trim();
  if (!text) return "";
  return `工具返回：${text.slice(0, 1200)}`;
}

function recoverGatewayFinalFromSession(agentId: string, sessionKey: string, sinceMs: number) {
  const sessionId = gatewaySessionIdForKey(agentId, sessionKey);
  if (!sessionId) return "";
  const safeAgent = agentId.replace(/[^a-zA-Z0-9_-]/g, "");
  const sessionPath = path.join(os.homedir(), ".openclaw", "agents", safeAgent, "sessions", `${sessionId}.jsonl`);
  if (!fs.existsSync(sessionPath)) return "";
  let finalText = "";
  try {
    for (const line of fs.readFileSync(sessionPath, "utf8").split(/\r?\n/)) {
      if (!line.trim()) continue;
      const row = JSON.parse(line) as { type?: string; timestamp?: string; message?: { role?: string; stopReason?: string; content?: unknown[] } };
      if (row.type !== "message" || row.message?.role !== "assistant" || row.message.stopReason !== "stop") continue;
      if (row.timestamp && Date.parse(row.timestamp) < sinceMs) continue;
      const text = extractGatewayText({ content: row.message.content || [] });
      if (text) finalText = appendGatewayThinking(text, extractGatewayThinking({ result: { meta: { agentMeta: { sessionId } } } }, agentId, sinceMs));
    }
  } catch {
    return "";
  }
  return finalText;
}

function recoverGatewayFinalFromRecentSessionFiles(agentId: string, sessionKey: string, sinceMs: number) {
  const sourcePrefix = knowledgeNoteSourcePrefixFromSessionKey(sessionKey);
  const purpose = knowledgeNotePurposeFromSessionKey(sessionKey);
  if (!sourcePrefix || !purpose) return "";
  const safeAgent = agentId.replace(/[^a-zA-Z0-9_-]/g, "");
  const sessionDir = path.join(os.homedir(), ".openclaw", "agents", safeAgent, "sessions");
  if (!safeAgent || !fs.existsSync(sessionDir)) return "";
  const minMtimeMs = Math.max(0, sinceMs - 120_000);
  const indexedSessionIds = new Set<string>();
  const indexPath = path.join(sessionDir, "sessions.json");
  try {
    const index = fs.existsSync(indexPath)
      ? JSON.parse(fs.readFileSync(indexPath, "utf8")) as Record<string, { sessionId?: string; updatedAt?: number }>
      : {};
    for (const [candidateKey, entry] of Object.entries(index)) {
      if (!candidateKey.includes(`knowledge-note-${purpose}:${sourcePrefix}`)) continue;
      if (entry?.updatedAt && Number(entry.updatedAt) < minMtimeMs) continue;
      const sessionId = String(entry?.sessionId || "");
      if (/^[a-zA-Z0-9_-]+$/.test(sessionId)) indexedSessionIds.add(sessionId);
    }
  } catch {
    return "";
  }
  if (!indexedSessionIds.size) return "";
  let candidates: Array<{ file: string; mtimeMs: number }> = [];
  try {
    candidates = fs.readdirSync(sessionDir)
      .filter((name) => name.endsWith(".jsonl"))
      .filter((name) => indexedSessionIds.has(path.basename(name, ".jsonl")))
      .map((name) => {
        const file = path.join(sessionDir, name);
        const stat = fs.statSync(file);
        return { file, mtimeMs: stat.mtimeMs };
      })
      .filter((item) => item.mtimeMs >= minMtimeMs)
      .sort((a, b) => b.mtimeMs - a.mtimeMs)
      .slice(0, 30);
  } catch {
    return "";
  }

  let latest: { tsMs: number; text: string } | null = null;
  for (const item of candidates) {
    try {
      const raw = fs.readFileSync(item.file, "utf8");
      if (!raw.includes(sourcePrefix)) continue;
      const sessionId = path.basename(item.file, ".jsonl");
      for (const line of raw.split(/\r?\n/)) {
        if (!line.trim()) continue;
        const row = JSON.parse(line) as { type?: string; timestamp?: string; message?: { role?: string; stopReason?: string; content?: unknown[] } };
        if (row.type !== "message" || row.message?.role !== "assistant" || row.message.stopReason !== "stop") continue;
        const tsMs = row.timestamp ? Date.parse(row.timestamp) : item.mtimeMs;
        if (Number.isFinite(tsMs) && tsMs < sinceMs) continue;
        const text = extractGatewayText({ content: row.message.content || [] }).trim();
        if (!text) continue;
        if (!latest || tsMs > latest.tsMs) {
          latest = {
            tsMs,
            text: appendGatewayThinking(text, extractGatewayThinking({ result: { meta: { agentMeta: { sessionId } } } }, agentId, sinceMs)),
          };
        }
      }
    } catch {
      // Keep recovery best-effort; malformed historical session files should not break the request.
    }
  }
  return latest?.text || "";
}

function knowledgeNoteGatewayResultFromLateHarvest<T = unknown>(harvest: KnowledgeNoteLateSessionHarvest, dispatch?: GatewayResult<T>): GatewayResult<T> {
  return {
    ok: true,
    status: "connected",
    data: {
      final: harvest.text,
      recoveredFromSession: true,
      recoveredFromLateSourceHashHarvest: true,
      recoveredAgentId: harvest.agentId,
      recoveredSessionKey: harvest.sessionKey,
      recoveredSessionId: harvest.sessionId,
      transcriptPath: harvest.transcriptPath,
      dispatch,
    } as T,
  };
}

function recoverKnowledgeNoteGatewayFinalBySourceHash(input: {
  purpose: "markdown" | "html";
  sourceHash: string;
  sinceMs: number;
  preferredAgent?: AgentId;
  requirePromptMarker?: string;
}): KnowledgeNoteLateSessionHarvest | null {
  const sourceHash = String(input.sourceHash || "").trim();
  const sourcePrefix = sourceHash.slice(0, 16);
  if (!/^[a-f0-9]{16,}$/i.test(sourceHash) || !sourcePrefix) return null;
  const minUpdatedAt = Math.max(0, input.sinceMs - 5 * 60_000);
  let latest: KnowledgeNoteLateSessionHarvest | null = null;
  for (const agentId of knowledgeNoteLateHarvestAgents(input.preferredAgent)) {
    const sessionDir = path.join(os.homedir(), ".openclaw", "agents", agentId, "sessions");
    const indexPath = path.join(sessionDir, "sessions.json");
    if (!fs.existsSync(indexPath)) continue;
    let index: Record<string, { sessionId?: string; updatedAt?: number; transcriptPath?: string }> = {};
    try {
      index = JSON.parse(fs.readFileSync(indexPath, "utf8")) as typeof index;
    } catch {
      continue;
    }
    const candidates = Object.entries(index)
      .filter(([sessionKey]) => sessionKey.includes(`knowledge-note-${input.purpose}:${sourcePrefix}`))
      .map(([sessionKey, entry]) => ({ sessionKey, entry, updatedAt: Number(entry?.updatedAt || 0) || 0 }))
      .filter((item) => !item.updatedAt || item.updatedAt >= minUpdatedAt)
      .sort((a, b) => b.updatedAt - a.updatedAt)
      .slice(0, 40);
    for (const candidate of candidates) {
      const sessionId = String(candidate.entry?.sessionId || "");
      if (!/^[a-zA-Z0-9_-]+$/.test(sessionId)) continue;
      const transcriptPath = String(candidate.entry?.transcriptPath || "") || path.join(sessionDir, `${sessionId}.jsonl`);
      const harvested = recoverKnowledgeNoteFinalTextFromTranscript(transcriptPath, sourceHash, input.sinceMs, input.requirePromptMarker);
      if (!harvested) continue;
      if (!latest || harvested.tsMs > latest.tsMs) {
        latest = {
          agentId,
          sessionKey: candidate.sessionKey,
          sessionId,
          transcriptPath,
          tsMs: harvested.tsMs,
          text: harvested.text,
        };
      }
    }
  }
  return latest;
}

function knowledgeNoteLateHarvestAgents(preferredAgent?: AgentId): AgentId[] {
  const agents: AgentId[] = [];
  for (const candidate of [preferredAgent, "worker", "boss", "main"]) {
    const agent = normalizeKnowledgeNoteExecutionAgent(candidate);
    if (agent && !agents.includes(agent)) agents.push(agent);
  }
  return agents;
}

function recoverKnowledgeNoteFinalTextFromTranscript(transcriptPath: string, sourceHash: string, sinceMs: number, requirePromptMarker?: string) {
  if (!transcriptPath || !fs.existsSync(transcriptPath)) return null;
  let raw = "";
  try {
    raw = fs.readFileSync(transcriptPath, "utf8");
  } catch {
    return null;
  }
  if (!raw.includes(sourceHash)) return null;
  let latest: { tsMs: number; text: string; userMessageIndex: number } | null = null;
  let lastUserMessageIndex = -1;
  let lastUserMessageText = "";
  const lines = raw.split(/\r?\n/);
  for (let idx = 0; idx < lines.length; idx += 1) {
    const line = lines[idx];
    if (!line.trim()) continue;
    try {
      const row = JSON.parse(line) as {
        type?: string;
        timestamp?: string;
        message?: { role?: string; stopReason?: string; content?: unknown[] };
      };
      if (row.type !== "message") continue;
      if (row.message?.role === "user") {
        const userText = extractAssistantFinalTextOnly(row.message.content || []);
        if (userText) {
          lastUserMessageIndex = idx;
          lastUserMessageText = userText;
        }
        continue;
      }
      if (row.message?.role !== "assistant" || row.message.stopReason !== "stop") continue;
      const tsMs = row.timestamp ? Date.parse(row.timestamp) : 0;
      if (Number.isFinite(tsMs) && tsMs < sinceMs) continue;
      const text = extractAssistantFinalTextOnly(row.message.content || []);
      if (!text || !text.includes(sourceHash)) continue;
      // Only trust candidates whose most recent user message was generated with the
      // current prompt version. Older prompts left stale transcripts that look identical
      // to the latest output but belong to a generation we explicitly retired.
      if (requirePromptMarker) {
        const userIndexFloor = lastUserMessageIndex >= 0 ? lastUserMessageIndex : -1;
        if (userIndexFloor < 0 || !lastUserMessageText.includes(requirePromptMarker)) {
          // No marker anywhere above this candidate means the user message was generated
          // under a different prompt. Skip the candidate entirely.
          if (!lastUserMessageText.includes(requirePromptMarker)) continue;
        }
      }
      if (!latest || tsMs > latest.tsMs) latest = { tsMs: Number.isFinite(tsMs) ? tsMs : Date.now(), text, userMessageIndex: lastUserMessageIndex };
    } catch {
      // Ignore malformed historical transcript rows.
    }
  }
  return latest;
}

function extractAssistantFinalTextOnly(content: unknown[]) {
  return (Array.isArray(content) ? content : [])
    .map((part) => {
      if (!part || typeof part !== "object") return "";
      const record = part as Record<string, unknown>;
      if (record.type === "text" && typeof record.text === "string") return record.text.trim();
      return "";
    })
    .filter(Boolean)
    .join("\n\n")
    .trim();
}

function knowledgeNoteSourcePrefixFromSessionKey(sessionKey: string) {
  const match = String(sessionKey || "").match(/knowledge-note-(?:markdown|html):([a-f0-9]{16})/i);
  return match?.[1] || "";
}

function knowledgeNotePurposeFromSessionKey(sessionKey: string): "markdown" | "html" | "" {
  const match = String(sessionKey || "").match(/knowledge-note-(markdown|html):[a-f0-9]{16}/i);
  const purpose = String(match?.[1] || "").toLowerCase();
  return purpose === "markdown" || purpose === "html" ? purpose : "";
}

function gatewaySessionIdForKey(agentId: string, sessionKey: string) {
  const safeAgent = agentId.replace(/[^a-zA-Z0-9_-]/g, "");
  if (!safeAgent || !sessionKey) return "";
  const indexPath = path.join(os.homedir(), ".openclaw", "agents", safeAgent, "sessions", "sessions.json");
  if (!fs.existsSync(indexPath)) return "";
  try {
    const index = JSON.parse(fs.readFileSync(indexPath, "utf8")) as Record<string, { sessionId?: string }>;
    return String(index[sessionKey]?.sessionId || "");
  } catch {
    return "";
  }
}

function readTextFile(file: string, limit: number) {
  try {
    return fs.readFileSync(file, "utf8").slice(0, limit);
  } catch {
    return "";
  }
}

function resolveWorkbenchFilePath(input: string) {
  const raw = String(input || "").replace(/^file:\/\//i, "").trim();
  if (!raw || raw.includes("\0")) return "";
  const candidate = path.isAbsolute(raw) ? path.resolve(raw) : path.resolve(WORKSPACE_DIR, raw);
  const allowedRoots = [WORKSPACE_DIR, DATA_DIR, SIDECAR_DIR]
    .map((root) => safeRealpath(root))
    .filter(Boolean);
  const realCandidate = safeRealpath(candidate);
  if (!realCandidate) return "";
  const inAllowedRoot = allowedRoots.some((root) => realCandidate === root || realCandidate.startsWith(`${root}${path.sep}`));
  if (!inAllowedRoot) return "";
  try {
    return fs.statSync(realCandidate).isFile() ? realCandidate : "";
  } catch {
    return "";
  }
}

function safeJsonObject(value: unknown): Record<string, unknown> {
  if (!value) return {};
  if (typeof value === "object" && !Array.isArray(value)) return value as Record<string, unknown>;
  if (typeof value !== "string") return {};
  try {
    const parsed = JSON.parse(value);
    return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed as Record<string, unknown> : {};
  } catch {
    return {};
  }
}

function safeSystemMetric<T>(read: () => T, fallback: T): T {
  try {
    return read();
  } catch {
    return fallback;
  }
}

function readValueMetricConfig() {
  if (!fs.existsSync(VALUE_METRICS_CONFIG_PATH)) return DEFAULT_VALUE_METRICS;
  try {
    const data = JSON.parse(fs.readFileSync(VALUE_METRICS_CONFIG_PATH, "utf8")) as { metrics?: unknown };
    return normalizeValueMetricConfig(data.metrics);
  } catch {
    return DEFAULT_VALUE_METRICS;
  }
}

function normalizeValueMetricConfig(input: unknown): ValueMetricConfig[] {
  const rows = Array.isArray(input) ? input : DEFAULT_VALUE_METRICS;
  const defaultsById = new Map(DEFAULT_VALUE_METRICS.map((metric) => [metric.id, metric]));
  const allowedIds = new Set(DEFAULT_VALUE_METRICS.map((metric) => metric.id));
  const seen = new Set<string>();
  const normalized: ValueMetricConfig[] = [];
  for (const row of rows) {
    if (!row || typeof row !== "object") continue;
    const record = row as Record<string, unknown>;
    const id = String(record.id || "").trim();
    if (!allowedIds.has(id) || seen.has(id)) continue;
    const fallback = defaultsById.get(id)!;
    seen.add(id);
    normalized.push({
      id,
      label: cleanValueMetricLabel(record.label, fallback.label),
      enabled: record.enabled !== false,
      order: clampMetricNumber(record.order, fallback.order, 1, 999),
      unit: cleanValueMetricLabel(record.unit, fallback.unit),
      tone: cleanValueMetricTone(record.tone, fallback.tone),
      source: cleanValueMetricLabel(record.source, fallback.source),
      rateWindowMinutes: clampMetricNumber(record.rateWindowMinutes, fallback.rateWindowMinutes, 5, 1440),
      liveWindowMinutes: clampMetricNumber(record.liveWindowMinutes, fallback.liveWindowMinutes, 1, 60),
    });
  }
  for (const fallback of DEFAULT_VALUE_METRICS) {
    if (!seen.has(fallback.id)) normalized.push(fallback);
  }
  return normalized.sort((a, b) => a.order - b.order);
}

function cleanValueMetricLabel(value: unknown, fallback: string) {
  const text = String(value || "").trim();
  return text ? text.slice(0, 40) : fallback;
}

function cleanValueMetricTone(value: unknown, fallback: string) {
  const text = String(value || "").trim();
  return ["cost", "text", "code", "doc", "task", "time"].includes(text) ? text : fallback;
}

function clampMetricNumber(value: unknown, fallback: number, min: number, max: number) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return fallback;
  return Math.min(max, Math.max(min, Math.round(numeric)));
}

function isGatewayFinalTimeout(error?: string) {
  return /OpenClaw Gateway CLI timed out after \d+ms while waiting for final agent output|gateway timeout after \d+ms|gateway closed \((1012|1000|1006|4000)\)|OpenClaw Gateway CLI.*closed \(1012|1000|1006|4000\)|WebSocket close code 1012/i.test(String(error || ""));
}

async function generatePlanViaAgent(sessionId: string, agentId: string, message: string, sources: string[], skills: string[], modelId: string, idempotencyKey: string) {
  const prompt = [
    "请先作为 OpenClaw 代理生成一个可执行计划，不要开始执行。",
    "计划必须符合 task-executor skill 的 PLAN.md 流程，等待用户确认后再执行。",
    `当前日期时间：${workbenchDateTimeLabel()}（Asia/Shanghai）`,
    `知识源：${sources.join(", ") || "all"}`,
    `Skills：${ensureTaskExecutor(skills).join(", ")}`,
    `模型配置：${modelId}`,
    "",
    "用户任务：",
    message,
    "",
    "输出 Markdown，包含：目标、执行代理、知识源、Skill、步骤、风险。",
  ].join("\n");
  const gateway = await gatewayCall("agent", {
    agentId,
    sessionKey: `agent:${agentId}:workbench:${sessionId}:plan`,
    message: prompt,
    idempotencyKey,
  }, PLAN_GATEWAY_TIMEOUT_MS, { expectFinal: true });
  const content = gateway.ok ? extractGatewayText(gateway.data) : "";
  return { content: normalizePlanMarkdown(content), error: gateway.error, gateway };
}

function workbenchDateTimeLabel() {
  return new Intl.DateTimeFormat("zh-CN", {
    timeZone: "Asia/Shanghai",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  }).format(new Date());
}

function writeSse(raw: { writableEnded?: boolean; write: (chunk: string) => unknown }, event: string, data: unknown) {
  if (raw.writableEnded) return;
  raw.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
}

function streamingStatusContent(agentId: string, planMode: boolean, elapsedSeconds: number) {
  const lines = [
    "运行状态（非模型思考）：已发送给代理，正在等待 Gateway 返回。",
    `代理：${agentId}`,
    elapsedSeconds > 0 ? `已等待：${elapsedSeconds} 秒` : "已等待：刚开始",
    "上游返回后会替换为模型实际答复，并展示可提取到的完整思考过程。",
  ].join("\n");
  return planMode ? `# 执行计划\n\n<thinking>${lines}</thinking>` : `<thinking>${lines}</thinking>`;
}

async function streamFinalContent(assistantId: string, content: string, write: (event: string, data: unknown) => void) {
  const chunks = chunkText(content, 520).slice(0, 240);
  let current = "";
  for (const chunk of chunks) {
    current += chunk;
    db.prepare("UPDATE chat_messages SET content = ?, status = ? WHERE id = ?").run(current, "streaming", assistantId);
    write("delta", { message: db.prepare("SELECT * FROM chat_messages WHERE id = ?").get(assistantId) });
    await sleep(18);
  }
  if (current !== content) {
    db.prepare("UPDATE chat_messages SET content = ?, status = ? WHERE id = ?").run(content, "streaming", assistantId);
    write("delta", { message: db.prepare("SELECT * FROM chat_messages WHERE id = ?").get(assistantId) });
  }
}

function chunkText(value: string, size: number) {
  const text = String(value || "");
  const chunks: string[] = [];
  for (let index = 0; index < text.length; index += size) chunks.push(text.slice(index, index + size));
  return chunks.length ? chunks : [""];
}

function sleep(ms: number, signal?: AbortSignal) {
  return new Promise<void>((resolve, reject) => {
    if (signal?.aborted) {
      reject(new Error("Workbench request aborted while waiting for Gateway."));
      return;
    }
    const timer = setTimeout(resolve, ms);
    signal?.addEventListener("abort", () => {
      clearTimeout(timer);
      reject(new Error("Workbench request aborted while waiting for Gateway."));
    }, { once: true });
  });
}

function composeAgentPrompt(content: string, context: { sources?: string[]; skills?: string[]; mode?: string; modelId?: string }) {
  const sources = context.sources?.length ? context.sources : ["all"];
  const skills = context.skills?.length ? context.skills : [];
  return [
    `Workbench mode: ${context.mode || "chat"}`,
    `Knowledge sources: ${sources.join(", ")}`,
    `Skills: ${skills.join(", ") || "none"}`,
    `Preferred model config: ${context.modelId || "default"}`,
    "",
    "外部动作可信边界：涉及微信、企业微信、飞书、邮件、短信、浏览器提交、外部表单或任何外发动作时，除非工具返回结构化 `sent_verified` 且包含目标窗口/会话匹配与发送后证据，否则不得说“已发送/发送成功”。只能说明“已输入/已尝试/待人工确认/未验证”，并提示用户以目标客户端实际记录为准。",
    "",
    content,
  ].join("\n");
}

function buildPlanCard(message: string, agentId: string, sources: string[], skills: string[], gatewayError?: string) {
  const fallback = gatewayError ? `\n\n## 代理计划生成状态\nGateway 暂不可用或超时，已生成本地兜底计划。错误：${gatewayError}` : "";
  return `# 执行计划\n\n## 目标\n${message}\n\n## 执行代理\n${agentId}\n\n## 知识源\n${sources.join(", ") || "all"}\n\n## Skill\n${skills.join(", ") || "未指定"}\n\n## 步骤\n1. 使用 task-executor skill 创建或更新任务计划。\n2. 检索已选择知识源并整理上下文。\n3. 等待用户点击“确认执行”后再发送给代理执行。\n4. 执行完成后回写 RESULT.md 并在对话中返回结果。\n\n## 风险\n- 涉及外部系统或配置变更时，需要二次确认。\n- Gateway 不可用时只保存消息，不执行。${fallback}`;
}

function normalizePlanCard(content: string | undefined, message: string, agentId: string, sources: string[], skills: string[], gatewayError?: string) {
  const base = buildPlanCard(message, agentId, sources, skills, gatewayError);
  const draft = String(content || "").trim();
  if (!draft) return base;
  if (/task-executor/i.test(draft) && /确认执行|等待用户|PLAN\.md/i.test(draft)) {
    return /^#\s*执行计划/m.test(draft) ? draft : `# 执行计划\n\n${draft}`;
  }
  return `${base}\n\n---\n\n## 代理草稿\n${draft}`;
}

function normalizePlanMarkdown(content: string) {
  if (!content.trim()) return "";
  return content.trim().startsWith("#") ? content.trim() : `# 执行计划\n\n${content.trim()}`;
}

// T6 / Phase 2: njx-knowledge 优先策略 + 全源列表统一在这里维护。
// 任何调用方 (chat / research / searchKnowledge) 都走 normalizeSources,
// 避免出现 "all" 字符串泄漏到下游 (searchKnowledge 收到的必须是 KnowledgeSource[])。
const ALL_KNOWLEDGE_SOURCES: KnowledgeSource[] = ["memory", "wiki", "nas", "ima", "njx-knowledge"];
const DEFAULT_KNOWLEDGE_SOURCES: KnowledgeSource[] = ["njx-knowledge"];

function normalizeSources(values: unknown): KnowledgeSource[] {
  const list = Array.isArray(values) ? values.map(String) : [];
  const allowed = new Set<KnowledgeSource>(ALL_KNOWLEDGE_SOURCES);
  // "all" 是客户端占位,展开为 5 个真实 source;同时过滤掉任何非法值。
  const hasAll = list.includes("all");
  const filtered = list.filter((item): item is KnowledgeSource => allowed.has(item as KnowledgeSource));
  if (hasAll) return [...ALL_KNOWLEDGE_SOURCES];
  const unique = [...new Set(filtered)];
  if (unique.length === 0) return [...DEFAULT_KNOWLEDGE_SOURCES];
  return unique;
}

function normalizeSkillIds(values: unknown) {
  const list = Array.isArray(values) ? values.map(String) : [];
  return [...new Set(list.map((item) => item.trim()).filter(Boolean))];
}

function ensureTaskExecutor(skills: string[]) {
  return skills.includes("task-executor") ? skills : ["task-executor", ...skills];
}

function extractGatewayText(data: unknown): string {
  if (typeof data === "string") return data.trim();
  if (!data || typeof data !== "object") return "";
  if (Array.isArray(data)) return data.map(extractGatewayText).filter(Boolean).join("\n\n").trim();
  const record = data as Record<string, unknown>;
  if (record.type === "thinking" && typeof record.thinking === "string" && record.thinking.trim()) {
    return `<think>${record.thinking.trim()}</think>`;
  }
  if (record.type === "text" && typeof record.text === "string" && record.text.trim()) {
    return record.text.trim();
  }
  for (const key of ["content", "message", "text", "reply", "response", "output", "result"]) {
    const value = record[key];
    if (typeof value === "string" && value.trim()) return value.trim();
  }
  if (Array.isArray(record.content)) {
    const text = record.content.map(extractGatewayText).filter(Boolean).join("\n\n").trim();
    if (text) return text;
  }
  if (Array.isArray(record.payloads)) {
    const text = record.payloads.map(extractGatewayText).filter(Boolean).join("\n\n").trim();
    if (text) return text;
  }
  if (Array.isArray(record.choices)) {
    const text = record.choices.map(extractGatewayText).filter(Boolean).join("\n\n").trim();
    if (text) return text;
  }
  for (const key of ["final", "data", "message", "result", "payload", "response", "output", "assistant", "completion", "lastMessage"]) {
    const nested = record[key];
    const text = extractGatewayText(nested);
    if (text) return text;
  }
  return "";
}

function appendGatewayThinking(content: string, thinking: string) {
  const cleanThinking = thinking.trim();
  if (!cleanThinking || /<(think|thinking|reasoning|thoughts?)>/i.test(content)) return content;
  return `<think>${escapeThinkingContent(cleanThinking)}</think>\n\n${content}`;
}

function extractGatewayThinking(data: unknown, agentId: string, sinceMs: number): string {
  const thoughts: string[] = [];
  const payloadThinking = extractGatewayThinkingFromPayload(data);
  if (payloadThinking) thoughts.push(payloadThinking);
  const sessionId = extractGatewaySessionId(data);
  if (!sessionId || !/^[a-zA-Z0-9_-]+$/.test(sessionId)) return [...new Set(thoughts)].join("\n\n").trim();
  const safeAgent = agentId.replace(/[^a-zA-Z0-9_-]/g, "");
  if (!safeAgent) return [...new Set(thoughts)].join("\n\n").trim();
  const sessionPath = path.join(os.homedir(), ".openclaw", "agents", safeAgent, "sessions", `${sessionId}.jsonl`);
  if (!fs.existsSync(sessionPath)) return [...new Set(thoughts)].join("\n\n").trim();
  try {
    for (const line of fs.readFileSync(sessionPath, "utf8").split(/\r?\n/)) {
      if (!line.trim()) continue;
      const row = JSON.parse(line) as { type?: string; timestamp?: string; message?: { role?: string; content?: unknown[] } };
      if (row.type !== "message") continue;
      if (row.timestamp && Date.parse(row.timestamp) < sinceMs) continue;
      if (row.message?.role === "toolResult") {
        const resultText = formatToolResultTrace(row.message.content || []);
        if (resultText) thoughts.push(resultText);
        continue;
      }
      if (row.message?.role !== "assistant") continue;
      for (const part of row.message.content || []) {
        const item = part as { type?: string; thinking?: string; reasoning?: string; thought?: string; thoughts?: string };
        if (item.type === "thinking" && item.thinking?.trim()) thoughts.push(item.thinking.trim());
        if (item.type === "reasoning" && item.reasoning?.trim()) thoughts.push(item.reasoning.trim());
        if (item.thought?.trim()) thoughts.push(item.thought.trim());
        if (item.thoughts?.trim()) thoughts.push(item.thoughts.trim());
        if (item.type === "toolCall") thoughts.push(formatToolCallTrace(part as Record<string, unknown>));
      }
    }
    return [...new Set(thoughts)].join("\n\n").trim();
  } catch {
    return [...new Set(thoughts)].join("\n\n").trim();
  }
}

function extractGatewayThinkingFromPayload(data: unknown): string {
  if (!data || typeof data !== "object") return "";
  if (Array.isArray(data)) return [...new Set(data.map(extractGatewayThinkingFromPayload).filter(Boolean))].join("\n\n").trim();
  const record = data as Record<string, unknown>;
  const thoughts: string[] = [];
  for (const key of ["thinking", "reasoning", "thought", "thoughts"]) {
    const value = record[key];
    if (typeof value === "string" && value.trim()) thoughts.push(value.trim());
  }
  if (/^(thinking|reasoning|thoughts?)$/i.test(String(record.type || ""))) {
    for (const key of ["text", "content", "message"]) {
      const value = record[key];
      if (typeof value === "string" && value.trim()) thoughts.push(value.trim());
    }
  }
  for (const key of ["content", "payloads", "choices", "final", "data", "result", "payload", "response", "output", "assistant", "completion", "lastMessage"]) {
    const nested = record[key];
    const nestedThinking = extractGatewayThinkingFromPayload(nested);
    if (nestedThinking) thoughts.push(nestedThinking);
  }
  return [...new Set(thoughts)].join("\n\n").trim();
}

function extractGatewaySessionId(data: unknown): string {
  if (!data || typeof data !== "object") return "";
  const record = data as Record<string, unknown>;
  const result = record.result as Record<string, unknown> | undefined;
  const meta = (result?.meta || record.meta) as Record<string, unknown> | undefined;
  const agentMeta = meta?.agentMeta as Record<string, unknown> | undefined;
  return String(agentMeta?.sessionId || record.sessionId || "");
}

function autoTitle(input: string) {
  return (input || "新对话").replace(/\s+/g, " ").slice(0, 36);
}

function sanitizePublicError(input: string) {
  return input
    .replace(/Command failed:\s*openclaw-cn\s+gateway\s+call[\s\S]*/gi, "OpenClaw Gateway RPC failed")
    .replace(/openclaw-cn\s+gateway\s+call\s+[^\n\r]*/gi, "OpenClaw Gateway RPC failed")
    .replace(/--params\s+\{[\s\S]*?\}\s+--timeout/gi, "--params [redacted] --timeout")
    .replace(/token=\S+/gi, "token=[redacted]")
    .slice(0, 800);
}

function parseJsonArray(value: unknown) {
  if (Array.isArray(value)) return value.map(String);
  if (typeof value !== "string") return [];
  try {
    const parsed = JSON.parse(value);
    return Array.isArray(parsed) ? parsed.map(String) : [];
  } catch {
    return [];
  }
}

function defaultReportCron(type: string) {
  if (type === "weekly") return "0 18 * * 5";
  if (type === "monthly") return "0 18 28 * *";
  if (type === "yearly") return "0 18 31 12 *";
  return "0 18 * * *";
}

function escapeInlineHtml(value: string) {
  return escapeHtml(String(value || ""));
}

function escapeHtml(value: string) {
  return value.replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;", "'": "&#039;" })[char] || char);
}

const developmentGoalAutoLoopTimer = setInterval(() => {
  runDevelopmentGoalAutoLoop().catch((err) => app.log.warn({ err }, "development goal auto loop failed"));
}, 60_000);
developmentGoalAutoLoopTimer.unref?.();

const cloudbaseForwarder = new CloudbaseForwarder({
  localUrl: `http://127.0.0.1:${PORT}`,
  log: app.log,
  version: MOBILE_LATEST_APP_VERSION,
});
cloudbaseForwarderSingleton.instance = cloudbaseForwarder;
cloudbaseForwarder.start();
process.on("SIGTERM", () => cloudbaseForwarder.stop());
process.on("SIGINT", () => cloudbaseForwarder.stop());

app.listen({ host: HOST, port: PORT }).catch((err) => {
  app.log.error(err);
  process.exit(1);
});
